INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('651004f3-8106-4555-b75b-ae97202e3a90', '8c406124-9903-47de-a830-bb6cf94fbbfa', '“Hərbi vəzifə və hərbi xidmət haqqında” AR Qanununa əsasən, ümumi təhsil müəssisələrində Gənclərin çağırışaqədərki hazırlığı (GÇH) fənninin başlıca məqsədi nədir?', 'multiple_choice', '["Gənclərə yalnız atəş hazırlığı və fiziki dözümlülük üzrə praktiki vərdişləri tədris etmək", "Gənclərə yalnız Silahlı Qüvvələrin ümumqoşun nizamnamələrinin hüquqi əsaslarını və sıra hərəkətlərini öyrətmək", "Gəncləri müddətli həqiqi hərbi xidmətə çağırışdan azad edən tibbi-sosial əsaslarla tanış etmək", "Gənclərə hərbi xidmətin əsaslarını, ümumqoşun nizamnamələrini, sıra, atəş, topoqrafiya və mülki müdafiə üzrə zəruri ilkin hərbi bacarıqları kompleks şəkildə aşılamaq", "Gənclərə mülki müdafiə xəbərdarlıq siqnallarını və yalnız ilkin tibbi yardım qaydalarını aşılamaq"]'::jsonb, 'Gənclərə hərbi xidmətin əsaslarını, ümumqoşun nizamnamələrini, sıra, atəş, topoqrafiya və mülki müdafiə üzrə zəruri ilkin hərbi bacarıqları kompleks şəkildə aşılamaq', 'Düzgün cavab: D) Gənclərə hərbi xidmətin əsaslarını, ümumqoşun nizamnamələrini, sıra, atəş, topoq', '', 1, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b1ec5cbe-fed5-4b0c-98c2-7cd7f1bdefbf', '651004f3-8106-4555-b75b-ae97202e3a90', 'ka', '„სამხედრო ვალდებულებისა და სამხედრო სამსახურის შესახებ“ აზერბაიჯანის რესპუბლიკის კანონის თანახმად, რა არის ზოგადსაგანმანათლებლო დაწესებულებებში წვევამდელთა სამხედრო მომზადების (წსმ) საგნის მთავარი მიზანი?', '["ახალგაზრდებისთვის სამხედრო სამსახურის სამართლებრივი საფუძვლების, საერთო-საჯარისო წესდებების ნაწილისა და მხოლოდ სამწყობრო მომზადების უნარების სწავლება", "ახალგაზრდებისთვის სამხედრო სამსახურის საფუძვლების, მხოლოდ საცეცხლე და ფიზიკური მომზადების პრაქტიკული უნარების ჩამოყალიბება, წესდებების თეორიულად სწავლება", "ახალგაზრდებისთვის სამხედრო სამსახურის საფუძვლების, საერთო-საჯარისო წესდებების, სამშობლოს დასაცავად აუცილებელი მორალურ-ფსიქოლოგიური და მხოლოდ სამედიცინო მომზადების უნარების ჩამოყალიბება", "ახალგაზრდებისთვის სამხედრო სამსახურის საფუძვლების, საერთო-საჯარისო წესდებების, სამშობლოს დასაცავად აუცილებელი მორალურ-ფსიქოლოგიური, სამწყობრო, საცეცხლე, ტოპოგრაფიული და სამოქალაქო თავდაცვის პირველადი სამხედრო უნარ-ჩვევების კომპლექსურად ჩამოყალიბება", "ახალგაზრდებისთვის სამხედრო სამსახურის საფუძვლების, საერთო-საჯარისო წესდებებისა და სამოქალაქო თავდაცვის მხოლოდ გამაფრთხილებელი სიგნალების სწავლება"]'::jsonb, 'ახალგაზრდებისთვის სამხედრო სამსახურის საფუძვლების, საერთო-საჯარისო წესდებების, სამშობლოს დასაცავად აუცილებელი მორალურ-ფსიქოლოგიური, სამწყობრო, საცეცხლე, ტოპოგრაფიული და სამოქალაქო თავდაცვის პირველადი სამხედრო უნარ-ჩვევების კომპლექსურად ჩამოყალიბება', 'Düzgün cavab: D) ახალგაზრდებისთვის სამხედრო სამსახურის საფუძვლების, საერთო-საჯარისო წესდებების, ს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b2ddf8f9-c92c-495d-8370-fa71f03122ee', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Azərbaycan Respublikası Konstitusiyasının 109-cu maddəsinə əsasən, Silahlı Qüvvələrin Ali Baş Komandanı səlahiyyətini kim icra edir?', 'multiple_choice', '["Azərbaycan Respublikası Silahlı Qüvvələrinin Baş Qərargah rəisi", "Azərbaycan Respublikasının Prezidenti", "Azərbaycan Respublikasının Baş naziri", "Azərbaycan Respublikasının Təhlükəsizlik Şurasının katibi", "Azərbaycan Respublikasının Müdafiə Naziri"]'::jsonb, 'Azərbaycan Respublikasının Prezidenti', 'Düzgün cavab: B) Azərbaycan Respublikasının Prezidenti', '', 2, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('df01193e-1d44-487a-be44-e5c9cb670658', 'b2ddf8f9-c92c-495d-8370-fa71f03122ee', 'ka', 'აზერბაიჯანის რესპუბლიკის კონსტიტუციის 109-ე მუხლის თანახმად, ვინ არის შეიარაღებული ძალების უმაღლესი მთავარსარდალი?', '["აზერბაიჯანის რესპუბლიკის პრეზიდენტი – როგორც თავდაცვის საბჭოს თავმჯდომარე, ომის პერიოდში უმაღლესი მთავარსარდლის უფლებამოსილების დროებით შემსრულებელი პირია", "აზერბაიჯანის რესპუბლიკის პრეზიდენტი – კონსტიტუციის თანახმად, შეიარაღებული ძალების უმაღლესი მთავარსარდალია და პირდაპირ ახორციელებს ამ უფლებამოსილებას", "აზერბაიჯანის რესპუბლიკის ვიცე-პრეზიდენტი – პრეზიდენტის არყოფნის შემთხვევებში კონსტიტუციით უმაღლეს მთავარსარდლად ითვლება", "თავდაცვის მინისტრი – პრეზიდენტის ბრძანებულებით ინიშნება უმაღლეს მთავარსარდლად და მუდმივად ასრულებს ამ მოვალეობას", "გენერალური შტაბის უფროსი – საბრძოლო ოპერაციების დროს ფაქტობრივად ასრულებს უმაღლესი მთავარსარდლის ფუნქციას"]'::jsonb, 'აზერბაიჯანის რესპუბლიკის პრეზიდენტი – კონსტიტუციის თანახმად, შეიარაღებული ძალების უმაღლესი მთავარსარდალია და პირდაპირ ახორციელებს ამ უფლებამოსილებას', 'Düzgün cavab: B) აზერბაიჯანის რესპუბლიკის პრეზიდენტი – კონსტიტუციის თანახმად, შეიარაღებული ძალები', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c3563ca7-96ce-4dc4-a353-365b12aea79f', '8c406124-9903-47de-a830-bb6cf94fbbfa', '“Hərbi vəzifə və hərbi xidmət haqqında” AR Qanununa əsasən, kişi cinsli vətəndaşların ilkin hərbi qeydiyyata alınması hansı yaşda və hansı dövrdə həyata keçirilir?', 'multiple_choice', '["18 yaşı tamam olan ilin oktyabr–dekabr aylarında, çağırış komissiyasının qərarı ilə", "16 yaşı tamam olan ilin sentyabr–noyabr aylarında, GÇH rəhbərinin tərtib etdiyi siyahı üzrə", "17 yaşı tamam olan ilin aprel–iyun aylarında, təhsil aldığı ümumi təhsil müəssisəsində", "15 yaşı tamam olan ilin yanvar–mart aylarında, bələdiyyə orqanlarının təqdimatı ilə", "16 yaşı tamam olan ilin yanvar–mart aylarında, yaşayış yeri üzrə müvafiq icra hakimiyyəti orqanında"]'::jsonb, '16 yaşı tamam olan ilin yanvar–mart aylarında, yaşayış yeri üzrə müvafiq icra hakimiyyəti orqanında', 'Düzgün cavab: E) 16 yaşı tamam olan ilin yanvar–mart aylarında, yaşayış yeri üzrə müvafiq icra ha', '', 3, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7e7ce48f-1e3f-4126-8e6c-15ea3fb9a230', 'c3563ca7-96ce-4dc4-a353-365b12aea79f', 'ka', '„სამხედრო ვალდებულებისა და სამხედრო სამსახურის შესახებ“ კანონის თანახმად, რა ასაკში და რა პერიოდში ხორციელდება მოქალაქეთა პირველადი სამხედრო აღრიცხვა?', '["ყოველწლიურად თებერვალ-აპრილში, 16 წლის ასაკის მამრობითი სქესის მოქალაქეებისა საგანმანათლებლო დაწესებულებაში", "ყოველწლიურად იანვარ-მარტში, 17 წლის ასაკის მამრობითი სქესის მოქალაქეებისა საცხოვრებელი ადგილის მიხედვით", "ყოველწლიურად ოქტომბერ-დეკემბერში, 16 წლის ასაკის მამრობითი სქესის მოქალაქეებისა საცხოვრებელი ადგილის მიხედვით", "ყოველწლიურად იანვარ-მარტში, 15 წლის ასაკის მამრობითი სქესის მოქალაქეებისა საცხოვრებელი ადგილის მიხედვით", "ყოველწლიურად იანვარ-მარტში, 16 წლის ასაკის მამრობითი სქესის მოქალაქეებისა საცხოვრებელი ადგილის მიხედვით შესაბამის აღმასრულებელ ორგანოში"]'::jsonb, 'ყოველწლიურად იანვარ-მარტში, 16 წლის ასაკის მამრობითი სქესის მოქალაქეებისა საცხოვრებელი ადგილის მიხედვით შესაბამის აღმასრულებელ ორგანოში', 'Düzgün cavab: E) ყოველწლიურად იანვარ-მარტში, 16 წლის ასაკის მამრობითი სქესის მოქალაქეებისა საცხოვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e86be3eb-62c5-4a0b-a070-ee461ff0b815', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'GÇH fənn kabinetində tədris-təlim silahlarının və pnevmatik tüfənglərin saxlanması üzrə hansı təhlükəsizlik tələbi məcburidir?', 'multiple_choice', '["Siqnalizasiyalı və yanğından mühafizəli ayrıca otaqda, kilidli və möhürlənmiş xüsusi dəmir şkaflarda (piramidalarda), uçot jurnalı əsasında", "Müəllimlər otağında açarlı asma şkafda, yalnız məktəb növbətçisinin nəzarəti ilə", "Təsərrüfat anbarında taxta yeşiklərin içərisində, təsərrüfat müdirinin cavabdehliyi altında", "GÇH sinif otağında açıq divar stendlərində, şagirdlərin sərbəst baxış keçirə biləcəyi şəraitdə", "Məktəb direktorunun iş otağındakı ümumi dəmir seyfdə, sənədlərlə birlikdə və möhürlənmədən"]'::jsonb, 'Siqnalizasiyalı və yanğından mühafizəli ayrıca otaqda, kilidli və möhürlənmiş xüsusi dəmir şkaflarda (piramidalarda), uçot jurnalı əsasında', 'Düzgün cavab: A) Siqnalizasiyalı və yanğından mühafizəli ayrıca otaqda, kilidli və möhürlənmiş xü', '', 4, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0293180f-4e9f-4c8c-bba3-c8737933191f', 'e86be3eb-62c5-4a0b-a070-ee461ff0b815', 'ka', 'რა სავალდებულო მოთხოვნა არსებობს წსმ-ის სასწავლო კაბინეტში სასწავლო-საწვრთნელი იარაღისა და პნევმატური შაშხანების შენახვისთვის?', '["სპეციალურ ლითონის კარადებში (პირამიდებში), დაკეტილ, დალუქულ, სიგნალიზაციითა და ხანძარსაწინააღმდეგო დაცვით აღჭურვილ ცალკე ოთახში, აღრიცხვის ჟურნალით", "სპეციალურ ხის კარადებში, დაკეტილ, დალუქულ, სიგნალიზაციით აღჭურვილ ცალკე ოთახში, აღრიცხვის ჟურნალის გარეშე", "სპეციალურ ლითონის კარადებში, ღია საკეტით, დალუქვის გარეშე, მხოლოდ ხანძარსაწინააღმდეგო დაცვის მქონე ოთახში, აღრიცხვის ჟურნალით", "სპეციალურ ლითონის სეიფებში, დაკეტილ, დალუქულ, სიგნალიზაციის გარეშე, მასწავლებელთა საერთო ოთახში, აღრიცხვის ჟურნალით", "სპეციალურ ლითონის კარადებში, დაკეტილ, დალუქულ, სიგნალიზაციითა და ხანძარსაწინააღმდეგო დაცვით საკლასო ოთახის შიგნით, ჟურნალის გარეშე"]'::jsonb, 'სპეციალურ ლითონის კარადებში (პირამიდებში), დაკეტილ, დალუქულ, სიგნალიზაციითა და ხანძარსაწინააღმდეგო დაცვით აღჭურვილ ცალკე ოთახში, აღრიცხვის ჟურნალით', 'Düzgün cavab: A) სპეციალურ ლითონის კარადებში (პირამიდებში), დაკეტილ, დალუქულ, სიგნალიზაციითა და ხ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ddedfc47-8d79-4be5-99a4-cc16993a55ca', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Sıra hazırlığı nizamnaməsinə əsasən, “FARAĞAT!” komandası verildikdə hərbi qulluqçu hansı nizamnamə vəziyyətini almalıdır?', 'multiple_choice', '["Dabanlar 10 sm aralı, pəncələr paralel, dizlər sərbəst, əllər arxada birləşmiş, baş dik", "Dabanlar birləşmiş, pəncələr 60 dərəcə bucaq altında açıq, dizlər düz və gərgin, sinə irəli, çiyinlər arxada, baş dik, baxış irəli", "Dabanlar birləşmiş, pəncələr 90 dərəcə açıq, dizlər bükülü, bədən çəkisi sol ayaq üzərində", "Dabanlar və pəncələr bitişik, qollar aşağı sallanmış, baxış komandirin üzünə zillənmiş", "Dabanlar aralı, bədən tam sərbəst buraxılmış, sağ ayaq yarım addım irəli çəkilmiş"]'::jsonb, 'Dabanlar birləşmiş, pəncələr 60 dərəcə bucaq altında açıq, dizlər düz və gərgin, sinə irəli, çiyinlər arxada, baş dik, baxış irəli', 'Düzgün cavab: B) Dabanlar birləşmiş, pəncələr 60 dərəcə bucaq altında açıq, dizlər düz və gərgin,', '', 5, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('759fe1d7-8758-4928-a9de-d3250f052eca', 'ddedfc47-8d79-4be5-99a4-cc16993a55ca', 'ka', 'სამწყობრო მომზადების წესდების თანახმად, რა მდგომარეობა უნდა მიიღოს სამხედრო მოსამსახურემ ბრძანებაზე „სმენა!“ (Смирно!)?', '["ქუსლები შეტყუპებული, ტერფები 45 გრადუსით გაშლილი, მუხლები ოდნავ მოხრილი, სხეული თავისუფალი, მზერა მეთაურზე", "ქუსლები შეტყუპებული, ტერფები 60-70 გრადუსით გაშლილი, მუხლები გამართული და დაჭიმული, მკერდი წინ, მუცელი შეწეული, მხრები უკან, თავი გამართული, მზერა წინ", "ქუსლები შეტყუპებული, ტერფები 90 გრადუსით გაშლილი, მუხლები გამართული, თავი ოდნავ დახრილი, მზერა ქვემოთ", "ქუსლები 10 სმ-ით დაშორებული, ტერფები პარალელური, მუხლები გამართული, ხელები უკან შეერთებული, მზერა წინ", "ქუსლები შეტყუპებული, ტერფები 60-70 გრადუსით გაშლილი, სხეული მოდუნებული, ხელები ჯიბეებში"]'::jsonb, 'ქუსლები შეტყუპებული, ტერფები 60-70 გრადუსით გაშლილი, მუხლები გამართული და დაჭიმული, მკერდი წინ, მუცელი შეწეული, მხრები უკან, თავი გამართული, მზერა წინ', 'Düzgün cavab: B) ქუსლები შეტყუპებული, ტერფები 60-70 გრადუსით გაშლილი, მუხლები გამართული და დაჭიმუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('62b71785-c770-4d9f-ae77-d0a8ce0c6074', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Sıra hazırlığında hərbi qulluqçuların bir-birinin arxasında nizamnamə məsafəsi (distansiya) ilə yerləşdiyi düzülüş necə adlanır?', 'multiple_choice', '["Cərgə (şerenqa)", "Kolonna (qolona)", "Sıra cəbhəsi", "İkitərəfli sıra", "Cinah"]'::jsonb, 'Kolonna (qolona)', 'Düzgün cavab: B) Kolonna (qolona)', '', 6, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('10347b54-be67-4188-9619-d27a4727647a', '62b71785-c770-4d9f-ae77-d0a8ce0c6074', 'ka', 'სამწყობრო მომზადებაში როგორ ეწოდება წყობას, რომელშიც სამხედრო მოსამსახურეები ერთმანეთის ზურგს უკან დგანან?', '["მწკრივი (შერენგა) – გვერდიგვერდ დგომა, ინტერვალი 70-80 სმ", "კოლონა – ერთმანეთის ზურგს უკან, დისტანციით დგომა", "ორმწკრივა კოლონა – ერთმანეთის ზურგს უკან წყვილ-წყვილად დგომა, განსაკუთრებული შემთხვევა", "მწყობრის სიღრმე – მწკრივიდან კოლონაზე გადასვლის შუალედური მანძილი", "ფლანგი – მწყობრის მარჯვენა და მარცხენა დაბოლოება"]'::jsonb, 'კოლონა – ერთმანეთის ზურგს უკან, დისტანციით დგომა', 'Düzgün cavab: B) კოლონა – ერთმანეთის ზურგს უკან, დისტანციით დგომა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('55fcc097-25a9-48ed-bfd1-6d8dd65f229b', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Məktəb həyətində və ya yaxın ərazidə şübhəli əşya və ya partlamamış hərbi sursat aşkar edildikdə düzgün hərəkət alqoritmi hansıdır?', 'multiple_choice', '["Sursatın üzərini qumla örtmək, təhlükəsiz yerə daşımaq və yalnız dərs bitdikdən sonra məlumat vermək", "Ərazini təcrid etmədən şagirdləri həyətdə saxlamaq və yalnız yerli bələdiyyəyə yazılı müraciət etmək", "Sursatın növünü dəqiqləşdirmək üçün şagirdlərlə birlikdə vizual baxış keçirmək və foto çəkmək", "Sursatı yerindən tərpətmədən ətrafında daş hasar çəkmək və dərsləri adi qaydada davam etdirmək", "Sursata qətiyyən toxunmamaq, ərazini təcrid edib insanları uzaqlaşdırmaq, rəhbərliyə, 102, 112 və ANAMA-ya dərhal xəbər vermək"]'::jsonb, 'Sursata qətiyyən toxunmamaq, ərazini təcrid edib insanları uzaqlaşdırmaq, rəhbərliyə, 102, 112 və ANAMA-ya dərhal xəbər vermək', 'Düzgün cavab: E) Sursata qətiyyən toxunmamaq, ərazini təcrid edib insanları uzaqlaşdırmaq, rəhbər', '', 7, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8e81c02f-e728-4118-911e-43b7d52a2ea1', '55fcc097-25a9-48ed-bfd1-6d8dd65f229b', 'ka', 'როგორია უსაფრთხოების ალგორითმი სკოლის ტერიტორიაზე აუფეთქებელი საბრძოლო მასალის აღმოჩენისას?', '["არ შევეხოთ, თუმცა ახლოდან გადავუღოთ ფოტო და გავაგზავნოთ მშობელთა ჯგუფში, შემდეგ შევატყობინოთ ხელმძღვანელობას", "მსუბუქად შევეხოთ გადაადგილების გარეშე, შემოვღობოთ ქვებით და გავაგრძელოთ გაკვეთილი", "დავასხათ წყალი, ფრთხილად გავიტანოთ სკოლის ეზოდან და დავრეკოთ 102-ში", "ტერიტორიის იზოლირების გარეშე პირდაპირ დავრეკოთ საგანგებო სიტუაციების მართვის სამსახურში და მოსწავლეები დავტოვოთ კლასში", "არ შევეხოთ, არ მივუახლოვდეთ, მოვახდინოთ ტერიტორიის იზოლირება, მოსწავლეები განვარიდოთ მინიმუმ 100 მეტრით, შევატყობინოთ ხელმძღვანელობას, 102-ს, 112-სა და განაღმვის სამსახურს (ANAMA)"]'::jsonb, 'არ შევეხოთ, არ მივუახლოვდეთ, მოვახდინოთ ტერიტორიის იზოლირება, მოსწავლეები განვარიდოთ მინიმუმ 100 მეტრით, შევატყობინოთ ხელმძღვანელობას, 102-ს, 112-სა და განაღმვის სამსახურს (ANAMA)', 'Düzgün cavab: E) არ შევეხოთ, არ მივუახლოვდეთ, მოვახდინოთ ტერიტორიის იზოლირება, მოსწავლეები განვარ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6e54307f-5d4d-4f12-8618-7edd72e84fb5', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'AK-74 avtomatının natamam sökülməsi ardıcıllığında birinci icra edilən əməliyyat hansıdır?', 'multiple_choice', '["Qaytarıcı mexanizmin lülə qutusundan çıxarılması", "Təmizləmə çubuğunun (şompulun) çıxarılması", "Qaz borusunun ötürücü lülə ilə birlikdə ayrılması", "Lülə qutusu qapağının ayrılması", "Maqazinin (sandıqcanın) ayrılması və patronun lülədə olub-olmamasının yoxlanması"]'::jsonb, 'Maqazinin (sandıqcanın) ayrılması və patronun lülədə olub-olmamasının yoxlanması', 'Düzgün cavab: E) Maqazinin (sandıqcanın) ayrılması və patronun lülədə olub-olmamasının yoxlanması', '', 8, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('19d4c010-0ee2-4594-b088-f15d8654c73c', '6e54307f-5d4d-4f12-8618-7edd72e84fb5', 'ka', 'ავტომატ AK-74-ის არასრული დაშლისას რომელი ნაწილი გამოიყოფა პირველად?', '["მჭიდი – ლულის კოლოფის ხუფის მოხსნის შემდეგ გამოიყოფა მეორე რიგში", "საწმენდი ღერო (შომპოლი) – ლულის ქვეშიდან ამოღებით გამოიყოფა პირველ რიგში", "დამბრუნებელი მექანიზმი – უსაფრთხოებისთვის პირველად გამოსაღები ზამბარიანი მექანიზმია", "ლულის კოლოფის ხუფი – არასრული დაშლის პირველი მოქმედებაა", "მჭიდი – უსაფრთხოებისთვის იხსნება პირველ რიგში, შემდეგ მოწმდება სავაზნის სისუფთავე (ვაზნის არსებობა ლულაში)"]'::jsonb, 'მჭიდი – უსაფრთხოებისთვის იხსნება პირველ რიგში, შემდეგ მოწმდება სავაზნის სისუფთავე (ვაზნის არსებობა ლულაში)', 'Düzgün cavab: E) მჭიდი – უსაფრთხოებისთვის იხსნება პირველ რიგში, შემდეგ მოწმდება სავაზნის სისუფთავ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8a3e08fd-aaa3-4648-954c-364fbf321dda', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'AK-74 avtomatından atılan 5.45x39 mm patronun gülləsinin lülədən çıxış ilkin sürəti normativ olaraq nə qədərdir?', 'multiple_choice', '["960 m/san", "1050 m/san", "900 m/san", "715 m/san", "820 m/san"]'::jsonb, '900 m/san', 'Düzgün cavab: C) 900 m/san', '', 9, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6c1fda62-caea-49da-a642-7a364e6767a2', '8a3e08fd-aaa3-4648-954c-364fbf321dda', 'ka', 'დაახლოებით რამდენია AK-74 ავტომატიდან ნასროლი 5.45x39 მმ ტყვიის საწყისი სიჩქარე ლულიდან გამოსვლისას?', '["900 მ/წმ", "915 მ/წმ", "900–915 მ/წმ დიაპაზონში", "715 მ/წმ", "735 მ/წმ"]'::jsonb, '900–915 მ/წმ დიაპაზონში', 'Düzgün cavab: C) 900–915 მ/წმ დიაპაზონში', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('22fe757f-db2c-434d-8bb8-e618db9ce467', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Təlim atışları zamanı silahla davranma təhlükəsizlik qaydalarına əsasən hansı hərəkət **QƏTİ QADAĞANDIR**?', 'multiple_choice', '["Atış zamanı fərdi qulaqlıqlardan və qoruyucu eynəklərdən istifadə etmək", "Silahı dolu və ya boş olmasından asılı olmayaraq insanlara, arxaya və hədəfdən kənar istiqamətə tuşlamaq", "Atəş rəhbərinin komandası ilə silahı atəş xəttində doldurmaq", "Atəş başa çatdıqdan sonra silahı qoruyucuya qoyaraq baxış üçün təqdim etmək", "Komanda verildikdən sonra hədəfi dəqiq nişan alaraq tək-tək atəş açmaq"]'::jsonb, 'Silahı dolu və ya boş olmasından asılı olmayaraq insanlara, arxaya və hədəfdən kənar istiqamətə tuşlamaq', 'Düzgün cavab: B) Silahı dolu və ya boş olmasından asılı olmayaraq insanlara, arxaya və hədəfdən k', '', 10, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9e8fffb0-ddd7-4812-b8ed-80ff2fdd09a8', '22fe757f-db2c-434d-8bb8-e618db9ce467', 'ka', 'რა ქმედებაა კატეგორიულად აკრძალული სასწავლო სროლების დროს?', '["იარაღის მიმართვა მხოლოდ სამიზნისკენ, თუმცა საცეცხლე ხაზზე შესვლა ხელმძღვანელის ნებართვის გარეშე", "იარაღის მიმართვა ადამიანებისკენ, გვერდებზე და სამიზნის მიღმა მიუხედავად იმისა, დატენილია თუ არა იგი; საცეცხლე ხაზზე ნებართვის გარეშე გადაადგილება", "იარაღის მიმართვა სამიზნისკენ, თუმცა სროლის შემდეგ იარაღის დადება მაგიდაზე ხელმძღვანელის ბრძანების გარეშე", "ცარიელი იარაღის მიმართვა ადამიანებისკენ პრინციპით – დატენილი იკრძალება, ცარიელი დასაშვებია", "სროლის დროს ყურსასმენების გამოუყენებლობა და ხმამაღალი საუბარი"]'::jsonb, 'იარაღის მიმართვა ადამიანებისკენ, გვერდებზე და სამიზნის მიღმა მიუხედავად იმისა, დატენილია თუ არა იგი; საცეცხლე ხაზზე ნებართვის გარეშე გადაადგილება', 'Düzgün cavab: B) იარაღის მიმართვა ადამიანებისკენ, გვერდებზე და სამიზნის მიღმა მიუხედავად იმისა, დ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0609502b-8454-4790-9d12-beb8e1df4858', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'GP-5 və GP-7 tipli süzücü ümumqoşun əleyhqazlarının əsas mühafizə təyinatı nədir?', 'multiple_choice', '["Tənəffüs orqanlarını, gözləri və üz dərisini zəhərləyici maddələrdən, radioaktiv tozdan və bakterial aerozollardan qorumaq", "Tənəffüs orqanlarını yalnız karbon qazından qorumaq, görmə orqanlarını isə açıq saxlamaq", "Yüksək gərginlikli elektromaqnit sahələrindən qorunmanı təmin etmək", "İnsanı nüvə partlayışının zərbə dalğasından və yüksək hərarətindən qorumaq", "Yalnız sualtı mühitdə oksigenlə tənəffüsü fasiləsiz təmin etmək"]'::jsonb, 'Tənəffüs orqanlarını, gözləri və üz dərisini zəhərləyici maddələrdən, radioaktiv tozdan və bakterial aerozollardan qorumaq', 'Düzgün cavab: A) Tənəffüs orqanlarını, gözləri və üz dərisini zəhərləyici maddələrdən, radioaktiv', '', 11, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6263ca40-0816-4c9e-9191-79cdaa481ec6', '0609502b-8454-4790-9d12-beb8e1df4858', 'ka', 'რა არის GP-5 ან GP-7 ტიპის ფილტრაციული საერთო-საჯარისო აირწინაღის ძირითადი დანიშნულება?', '["სასუნთქი ორგანოების, თვალებისა და სახის კანის დაცვა მომწამვლელი ნივთიერებებისგან, რადიოაქტიური მტვრისა და ბაქტერიული საშუალებებისგან", "სასუნთქი ორგანოების დაცვა მხოლოდ მომწამვლელი ნივთიერებებისა და რადიოაქტიური მტვრისგან, თვალების დაცვის გარეშე", "სასუნთქი ორგანოების დაცვა მხოლოდ ბაქტერიული საშუალებებისა და მხუთავი აირისგან", "სასუნთქი ორგანოების, თვალებისა და სახის კანის დაცვა მხოლოდ რადიოაქტიური მტვრისგან, მომწამვლელი ნივთიერებებისგან დაცვის გარეშე", "სასუნთქი ორგანოების დაცვა მომწამვლელი ნივთიერებებისგან, რადიოაქტიური მტვრისგან, ბაქტერიული საშუალებებისა და დარტყმითი ტალღისგან"]'::jsonb, 'სასუნთქი ორგანოების, თვალებისა და სახის კანის დაცვა მომწამვლელი ნივთიერებებისგან, რადიოაქტიური მტვრისა და ბაქტერიული საშუალებებისგან', 'Düzgün cavab: A) სასუნთქი ორგანოების, თვალებისა და სახის კანის დაცვა მომწამვლელი ნივთიერებებისგან', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('889b3ffd-5599-4643-91ae-c5ea77378331', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Mülki Müdafiə üzrə “Hava həyəcanı!” siqnalı verildikdə ümumi təhsil müəssisəsində görülməli olan ilkin tədbir hansıdır?', 'multiple_choice', '["Yalnız məktəb rəhbərliyi təxliyə olunur, tədris heyəti binanın mühafizəsini təşkil edir", "Şagirdlər sinif otaqlarında saxlanılaraq pəncərə qarşısında müşahidə mövqeyi tuturlar", "Elektrik və qaz açıq saxlanılır, şagirdlər fərdi qaydada evlərinə buraxılır", "Dərslər dərhal dayandırılır, kommunal xətlər (qaz, elektrik, su) kəsilir və şagirdlər mütəşəkkil qaydada sığınacaqlara təxliyə edilir", "Bütün pəncərələr açılır, dərslər davam etdirilir və şagirdlər açıq idman meydançasına çıxarılır"]'::jsonb, 'Dərslər dərhal dayandırılır, kommunal xətlər (qaz, elektrik, su) kəsilir və şagirdlər mütəşəkkil qaydada sığınacaqlara təxliyə edilir', 'Düzgün cavab: D) Dərslər dərhal dayandırılır, kommunal xətlər (qaz, elektrik, su) kəsilir və şagi', '', 12, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('55b65038-2d6d-43e2-bca3-62202a943cc1', '889b3ffd-5599-4643-91ae-c5ea77378331', 'ka', 'რა ზომები უნდა მიიღონ სკოლაში სამოქალაქო თავდაცვის სიგნალზე „საჰაერო განგაში!“?', '["გაკვეთილები გრძელდება, ფანჯრები იღება, მოსწავლეები წვებიან კლასში იატაკზე", "გაკვეთილები წყდება, შუქი ითიშება, მაგრამ გაზი რჩება ღია, მოსწავლეები იკრიბებიან სპორტდარბაზში", "გაკვეთილები წყდება, დოკუმენტები ნადგურდება, მოსწავლეები ინდივიდუალურად იგზავნებიან სახლში", "გაკვეთილები დაუყოვნებლივ წყდება, ითიშება შუქი, გაზი, წყალი, ელექტროენერგია, უზრუნველყოფილია დოკუმენტების დაცვა, მოსწავლეთა ევაკუაცია ხორციელდება თავშესაფარში გეგმის მიხედვით", "გაკვეთილები წყდება, ყველა კომუნიკაცია რჩება ღია, მოსწავლეები გაჰყავთ ღია მოედანზე"]'::jsonb, 'გაკვეთილები დაუყოვნებლივ წყდება, ითიშება შუქი, გაზი, წყალი, ელექტროენერგია, უზრუნველყოფილია დოკუმენტების დაცვა, მოსწავლეთა ევაკუაცია ხორციელდება თავშესაფარში გეგმის მიხედვით', 'Düzgün cavab: D) გაკვეთილები დაუყოვნებლივ წყდება, ითიშება შუქი, გაზი, წყალი, ელექტროენერგია, უზრუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7c0359eb-2fb2-42de-9fdc-05f14041e54c', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Nüvə partlayışının əsas zədələyici amillərinin tam və düzgün sırası hansı bənddə göstərilmişdir?', 'multiple_choice', '["İşıq şüalanması, bioloji infeksiya, nüfuzedici radiasiya və lazer şüası", "Elektromaqnit impulsu, kimyəvi çirklənmə, seysmik dalğa və bakterial yayılma", "Zərbə dalğası, işıq şüalanması, nüfuzedici radiasiya, radioaktiv zəhərlənmə və elektromaqnit impulsu", "Zərbə dalğası, səs dalğası, zəhərli kimyəvi tüstü və yüksək atmosfer təzyiqi", "Zərbə dalğası, radioaktiv zəhərlənmə, istilik konveksiyası və səs rezonansı"]'::jsonb, 'Zərbə dalğası, işıq şüalanması, nüfuzedici radiasiya, radioaktiv zəhərlənmə və elektromaqnit impulsu', 'Düzgün cavab: C) Zərbə dalğası, işıq şüalanması, nüfuzedici radiasiya, radioaktiv zəhərlənmə və e', '', 13, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2d3cdfd8-2ab5-4fac-889f-d831a1a82669', '7c0359eb-2fb2-42de-9fdc-05f14041e54c', 'ka', 'რა არის ბირთვული იარაღის ძირითადი დამაზიანებელი ფაქტორები?', '["დარტყმითი ტალღა, მანათობელი გამოსხივება, გამჭოლი რადიაცია, რადიოაქტიური დაბინძურება", "დარტყმითი ტალღა, მანათობელი გამოსხივება, გამჭოლი რადიაცია, ქიმიური დაბინძურება", "დარტყმითი ტალღა, მანათობელი გამოსხივება, გამჭოლი რადიაცია, რადიოაქტიური დაბინძურება, ელექტრომაგნიტური იმპულსი", "დარტყმითი ტალღა, ბგერითი ტალღა, მანათობელი გამოსხივება, რადიოაქტიური დაბინძურება, ელექტრომაგნიტური იმპულსი", "დარტყმითი ტალღა, მანათობელი გამოსხივება, გამჭოლი რადიაცია, ბიოლოგიური დაბინძურება"]'::jsonb, 'დარტყმითი ტალღა, მანათობელი გამოსხივება, გამჭოლი რადიაცია, რადიოაქტიური დაბინძურება, ელექტრომაგნიტური იმპულსი', 'Düzgün cavab: C) დარტყმითი ტალღა, მანათობელი გამოსხივება, გამჭოლი რადიაცია, რადიოაქტიური დაბინძურ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d65ab045-b7b2-4737-a785-05488219648a', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Ətraf arteriyalarından fontan vuran güclü qanaxma zamanı qankəsici turna (jqut) necə tətbiq olunmalıdır?', 'multiple_choice', '["Yaradan 20 sm aşağıda, dərini zədələyəcək tərzdə sıxaraq və buz qoyulmadan", "Qanayan yaradan aşağı nahiyəyə, damarları tam sıxmadan və 3 saatdan artıq saxlamaqla", "Birbaşa yaranın üzərinə, çılpaq dəriyə toxunaraq və vaxt qeyd edilmədən boş şəkildə", "Qanayan yaradan yuxarıda (ürəyə tərəf), parça və ya geyim üzərindən sıxaraq, altına qoyulma vaxtı yazılmış qeyd bərkitməklə", "Yalnız oynağın tam büküş yerinə, metal məftil vasitəsilə bərk düyünlənməklə"]'::jsonb, 'Qanayan yaradan yuxarıda (ürəyə tərəf), parça və ya geyim üzərindən sıxaraq, altına qoyulma vaxtı yazılmış qeyd bərkitməklə', 'Düzgün cavab: D) Qanayan yaradan yuxarıda (ürəyə tərəf), parça və ya geyim üzərindən sıxaraq, alt', '', 14, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7507f990-5597-4feb-8b16-fc72739386f3', 'd65ab045-b7b2-4737-a785-05488219648a', 'ka', 'როგორ უნდა დაედოს რეზინის ლახტი (ტურნიკეტი) არტერიული სისხლდენის დროს?', '["ჭრილობის ზემოთ, უშუალოდ კანზე, თავისუფლად, დროის მითითების გარეშე", "ჭრილობის ქვემოთ, ტანსაცმელზე, მოჭერით, დროის მითითებით", "უშუალოდ ჭრილობაზე, ტანსაცმელზე, მოჭერით, დროის მითითებით", "ჭრილობის ზემოთ (გულთან ახლოს), ტანსაცმელზე ან ქსოვილზე, მოჭერით, ქვეშ დაკეცილი ქაღალდის დადებით, რომელზეც მითითებულია დრო", "ჭრილობის ზემოთ, ტანსაცმელზე, 2 საათზე მეტხანს დატოვებით, დროის მითითების გარეშე"]'::jsonb, 'ჭრილობის ზემოთ (გულთან ახლოს), ტანსაცმელზე ან ქსოვილზე, მოჭერით, ქვეშ დაკეცილი ქაღალდის დადებით, რომელზეც მითითებულია დრო', 'Düzgün cavab: D) ჭრილობის ზემოთ (გულთან ახლოს), ტანსაცმელზე ან ქსოვილზე, მოჭერით, ქვეშ დაკეცილი ქ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6b9de447-0421-4e10-94c9-335bfc1a7b7d', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Yuxarı ətrafın (qolun) qapalı sümük sınıqları zamanı ilkin tibbi yardımın əsas prinsipi necə icra edilir?', 'multiple_choice', '["Sınıq sümük ucları əllə dartılaraq yerinə salınır və isti kompres qoyulur", "Heç bir şin qoyulmadan qol sərbəst sallanmış vəziyyətdə xəstəxanaya piyada göndərilir", "Şin vasitəsilə sınıq nahiyəsindən yuxarıdakı və aşağıdakı ən azı iki qonşu oynaq (dirsək və çiyin) tam hərəkətsizləşdirilir", "Yalnız sınıq nahiyəsi bərk masaj edilir və oynaqların hərəkəti yoxlanılır", "Yalnız bilək oynağı sarınır, dirsək və çiyin oynaqları sərbəst hərəkətli saxlanılır"]'::jsonb, 'Şin vasitəsilə sınıq nahiyəsindən yuxarıdakı və aşağıdakı ən azı iki qonşu oynaq (dirsək və çiyin) tam hərəkətsizləşdirilir', 'Düzgün cavab: C) Şin vasitəsilə sınıq nahiyəsindən yuxarıdakı və aşağıdakı ən azı iki qonşu oynaq', '', 15, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2ee79d1f-e11d-4d9f-9b51-dd234ad36790', '6b9de447-0421-4e10-94c9-335bfc1a7b7d', 'ka', 'როგორ აღმოუჩენენ პირველად დახმარებას ზედა კიდურის (მკლავის) დახურული მოტეხილობის დროს?', '["არტაშნის დადებით მხოლოდ მოტეხილობის ადგილისა და ერთი მეზობელი სახსრის იმობილიზაცია", "არტაშნის გარეშე მკლავის სხეულზე ელასტიკური ბინტით მიხვევა და სითბოს დადება", "არტაშნის (შინას) დადებით მოტეხილობის ადგილის ზემოთ და ქვემოთ მინიმუმ ორი მეზობელი სახსრის (მხრისა და იდაყვის) უძრაობის უზრუნველყოფა, ცივის დადება", "ძვლის ხელით ჩასწორება და შემდეგ არტაშნის დადება", "არტაშნის დადებით მხოლოდ ქვედა სახსრის იმობილიზაცია"]'::jsonb, 'არტაშნის (შინას) დადებით მოტეხილობის ადგილის ზემოთ და ქვემოთ მინიმუმ ორი მეზობელი სახსრის (მხრისა და იდაყვის) უძრაობის უზრუნველყოფა, ცივის დადება', 'Düzgün cavab: C) არტაშნის (შინას) დადებით მოტეხილობის ადგილის ზემოთ და ქვემოთ მინიმუმ ორი მეზობელ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f096400e-dea5-41d9-a1d7-cb90e6548528', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Termiki yanıq zamanı zədələnmiş dəri səthinə ilkin yardım göstərərkən hansı müdaxilə **QƏTİ QADAĞANDIR**?', 'multiple_choice', '["Zərərçəkənə ağrıkəsici dərman və bol maye vermək", "Yanıq sahəsini 10–15 dəqiqə təmiz soyuq axar su altında saxlamaq", "Ağır yanıq hallarında təcili tibbi yardıma (103) dərhal müraciət etmək", "Yanıq nahiyəsinə quru steril tənzif sarğı qoymaq", "Dəri qovuqlarını deşmək, yaraya yağ, qatıq, diş pastası və ya spirt sürtmək, yapışmış paltarı qoparmaq"]'::jsonb, 'Dəri qovuqlarını deşmək, yaraya yağ, qatıq, diş pastası və ya spirt sürtmək, yapışmış paltarı qoparmaq', 'Düzgün cavab: E) Dəri qovuqlarını deşmək, yaraya yağ, qatıq, diş pastası və ya spirt sürtmək, yap', '', 16, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('eb5a5dcc-8b6f-4608-af26-22bf18a4b8a7', 'f096400e-dea5-41d9-a1d7-cb90e6548528', 'ka', 'რა ჩარევაა აკრძალული თერმული დამწვრობის დროს დაზიანებულ კანის ზედაპირზე?', '["ბუშტუკების გახვრეტა სტერილური ნემსით, შემდეგ ზეთის წასმა", "ჭრილობაზე მშრალი სტერილური საფენის დადება და ცივი წყლით დაბანა – აკრძალულია", "სასწრაფო დახმარების გამოძახება – აკრძალულია", "ცივი წყლის ქვეშ 10 წუთით გაჩერება – აკრძალულია", "ბუშტუკების გახვრეტა, ჭრილობაზე ცხიმის, მაწვნის, კბილის პასტის, სპირტის წასმა, მიმწვარი ტანსაცმლის აგლეჯა"]'::jsonb, 'ბუშტუკების გახვრეტა, ჭრილობაზე ცხიმის, მაწვნის, კბილის პასტის, სპირტის წასმა, მიმწვარი ტანსაცმლის აგლეჯა', 'Düzgün cavab: E) ბუშტუკების გახვრეტა, ჭრილობაზე ცხიმის, მაწვნის, კბილის პასტის, სპირტის წასმა, მი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e8594d91-36b9-421e-a2df-2481c0f43451', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Azərbaycan Respublikasının qanunvericiliyinə əsasən, Azərbaycan Ordusunun tərkibinə daxil olan qoşun növləri hansılardır?', 'multiple_choice', '["Quru Qoşunları, Hərbi Hava Qüvvələri və Hərbi Dəniz Qüvvələri", "Quru Qoşunları, Daxili Qoşunlar və Fövqəladə Hallar Nazirliyinin xilasetmə qüvvələri", "Hərbi Dəniz Qüvvələri, Ədliyyə Mühafizə Alayı və Mülki Müdafiə Qoşunları", "Quru Qoşunları, Polis Alayı və Milli Qvardiya", "Hərbi Hava Qüvvələri, Dövlət Sərhəd Xidməti və Xüsusi Rabitə Qoşunları"]'::jsonb, 'Quru Qoşunları, Hərbi Hava Qüvvələri və Hərbi Dəniz Qüvvələri', 'Düzgün cavab: A) Quru Qoşunları, Hərbi Hava Qüvvələri və Hərbi Dəniz Qüvvələri', '', 17, true, false, true, 1.0, 'exact', true, false, NOW());
