INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6746593c-0054-41a4-b827-669ef82475ef', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Sıra hazırlığı nizamnaməsinə əsasən, hərbi qulluqçuların adi addımla yerişi zamanı addımın normativ tempi və uzunluğu nə qədərdir?', 'multiple_choice', '["Dəqiqədə 110–120 addım, addımın uzunluğu 70–80 sm", "Dəqiqədə 130–140 addım, addımın uzunluğu 85–95 sm", "Dəqiqədə 100–110 addım, addımın uzunluğu 60–70 sm", "Dəqiqədə 90–100 addım, addımın uzunluğu 50–60 sm", "Dəqiqədə 120–130 addım, addımın uzunluğu 90–100 sm"]'::jsonb, 'Dəqiqədə 110–120 addım, addımın uzunluğu 70–80 sm', 'Düzgün cavab: A) Dəqiqədə 110–120 addım, addımın uzunluğu 70–80 sm', '', 20, true, false, true, 1.0, 'exact', true, false, NOW());
