INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9fb16ac2-d1a0-478c-9afe-fa24254a32d7', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Ümumi təhsil müəssisələrinin şagirdləri arasında keçirilən ənənəvi “Şahin” hərbi-idman oyununun əsas məqsədi nədir?', 'multiple_choice', '["Şagirdlərdə fiziki dözümlülük, sıra hazırlığı, hərbi-tətbiqi vərdişlər və vətənpərvərlik tərbiyəsini kompleks inkişaf etdirmək", "Şagirdlərə avtomobil idarəetmə vəsiqəsi qazandırmaq üçün sürücülük təlimi keçmək", "Yalnız şagirdlərin nəzəri riyazi biliklərini və fənn olimpiadalarına hazırlığını yoxlamaq", "Məktəb təsərrüfat inventarlarının illik texniki inventarizasiyasını aparmaq", "Yalnız şagirdlərin peşə məktəblərinə qəbul imtahanlarını təşkil etmək"]'::jsonb, 'Şagirdlərdə fiziki dözümlülük, sıra hazırlığı, hərbi-tətbiqi vərdişlər və vətənpərvərlik tərbiyəsini kompleks inkişaf etdirmək', 'Düzgün cavab: A) Şagirdlərdə fiziki dözümlülük, sıra hazırlığı, hərbi-tətbiqi vərdişlər və vətənp', '', 22, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('08c92d53-e181-433a-8deb-3cb4ab93a593', '9fb16ac2-d1a0-478c-9afe-fa24254a32d7', 'ka', 'რა არის სკოლაში ჩატარებული სამხედრო-სპორტული თამაშის „შავარდენის“ („Şahin“) მთავარი მიზანი?', '["მოსწავლეებში ფიზიკური გამძლეობის, სამწყობრო და დისციპლინური უნარების, პირველადი სამხედრო უნარ-ჩვევების, ტოპოგრაფიისა და პატრიოტული სულისკვეთების ჩამოყალიბება", "მოსწავლეებში მხოლოდ ფიზიკური გამძლეობისა და სპორტული უნარების ჩამოყალიბება", "მოსწავლეებში მხოლოდ სამწყობრო მომზადებისა და დისციპლინის ჩამოყალიბება", "მოსწავლეებში მხოლოდ პატრიოტული სულისკვეთების ჩამოყალიბება, ფიზიკური მომზადების გარეშე", "მოსწავლეებს შორის მხოლოდ ინტელექტუალური შეჯიბრებების ორგანიზება"]'::jsonb, 'მოსწავლეებში ფიზიკური გამძლეობის, სამწყობრო და დისციპლინური უნარების, პირველადი სამხედრო უნარ-ჩვევების, ტოპოგრაფიისა და პატრიოტული სულისკვეთების ჩამოყალიბება', 'Düzgün cavab: A) მოსწავლეებში ფიზიკური გამძლეობის, სამწყობრო და დისციპლინური უნარების, პირველადი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f8e10b8f-e6d2-4796-aeca-9325e4d459ab', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Yetkin şəxslərdə ürək-ağciyər reanimasiyası (ilkin reanimasiya) zamanı döş qəfəsinin sıxılması (kompressiya) ilə süni nəfəsvermə nisbəti necə olmalıdır?', 'multiple_choice', '["15 sıxma : 1 nəfəs (dəqiqədə 60–80 tezliklə, 2–3 sm dərinlikdə)", "20 sıxma : 4 nəfəs (dəqiqədə 80–90 tezliklə, 3–4 sm dərinlikdə)", "50 sıxma : 5 nəfəs (dəqiqədə 140–160 tezliklə, 7–8 sm dərinlikdə)", "10 sıxma : 2 nəfəs (dəqiqədə 50–60 tezliklə, 1–2 sm dərinlikdə)", "30 sıxma : 2 nəfəs (dəqiqədə 100–120 tezliklə, 5–6 sm dərinlikdə)"]'::jsonb, '30 sıxma : 2 nəfəs (dəqiqədə 100–120 tezliklə, 5–6 sm dərinlikdə)', 'Düzgün cavab: E) 30 sıxma : 2 nəfəs (dəqiqədə 100–120 tezliklə, 5–6 sm dərinlikdə)', '', 23, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('17b82f08-e253-4667-88cf-2d2feb3d47ce', 'f8e10b8f-e6d2-4796-aeca-9325e4d459ab', 'ka', 'როგორი უნდა იყოს გულმკერდის კომპრესიისა და ხელოვნური სუნთქვის (ჩაბერვის) თანაფარდობა ზრდასრულებში გულ-ფილტვის რეანიმაციის დროს?', '["30 კომპრესია : 2 ჩაბერვა, წუთში 80-100 კომპრესია, 3-4 სმ სიღრმეზე", "15 კომპრესია : 2 ჩაბერვა, წუთში 100-120 კომპრესია, 5-6 სმ სიღრმეზე", "30 კომპრესია : 1 ჩაბერვა, წუთში 100-120 კომპრესია, 5-6 სმ სიღრმეზე", "30 კომპრესია : 2 ჩაბერვა, წუთში 100-120 კომპრესია, 2-3 სმ სიღრმეზე", "30 კომპრესია : 2 ჩაბერვა, წუთში 100-120 კომპრესია, 5-6 სმ სიღრმეზე"]'::jsonb, '30 კომპრესია : 2 ჩაბერვა, წუთში 100-120 კომპრესია, 5-6 სმ სიღრმეზე', 'Düzgün cavab: E) 30 კომპრესია : 2 ჩაბერვა, წუთში 100-120 კომპრესია, 5-6 სმ სიღრმეზე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c496f2fd-20d9-45ff-8467-5a2cb1f88044', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Fərdi sarğı paketinin (İPP) əsas təyinatı və tərkib üstünlüyü nədən ibarətdir?', 'multiple_choice', '["Sınıq zamanı ətrafı hərəkətsizləşdirmək üçün metal şin konstruksiyası formalaşdırmaq", "Yaralanmalar zamanı steril bint və yastıqcıqlarla yaranı bağlayaraq infeksiyalaşmadan qorumaq və qanaxmanı azaltmaq", "Yalnız kimyəvi zəhərləyici maddələri dəridən neytrallaşdırmaq üçün maye məhlul püskürtmək", "Yalnız dəm qazından zəhərlənmə hallarında tənəffüs yoluna süni oksigen vermək", "Şagirdlərin dərslərdə hərbi forma geyimlərini tikmək və təmir etmək"]'::jsonb, 'Yaralanmalar zamanı steril bint və yastıqcıqlarla yaranı bağlayaraq infeksiyalaşmadan qorumaq və qanaxmanı azaltmaq', 'Düzgün cavab: B) Yaralanmalar zamanı steril bint və yastıqcıqlarla yaranı bağlayaraq infeksiyalaş', '', 24, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f40fa310-e96e-4785-b7db-26373a421dab', 'c496f2fd-20d9-45ff-8467-5a2cb1f88044', 'ka', 'რა არის ინდივიდუალური გადასახვევი პაკეტის (იგპ) ძირითადი დანიშნულება?', '["ჭრილობაზე სტერილური საფენის დადება და ძვლის მოტეხილობების ფიქსაცია", "ჭრილობაზე სტერილური საფენის დადება, სისხლდენის შემცირება და ჭრილობის დაცვა დაბინძურებისგან", "ჭრილობაზე არასტერილური საფენის დადება, სისხლდენის გაძლიერება", "საფენის დადება მხოლოდ დამწვრობებზე", "ჭრილობაზე სტერილური საფენის დადება, მაგრამ სისხლდენის შეუჩერებლად"]'::jsonb, 'ჭრილობაზე სტერილური საფენის დადება, სისხლდენის შემცირება და ჭრილობის დაცვა დაბინძურებისგან', 'Düzgün cavab: B) ჭრილობაზე სტერილური საფენის დადება, სისხლდენის შემცირება და ჭრილობის დაცვა დაბინ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8c01629a-ccc2-4484-88c2-807ff41e18f4', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Ümumi təhsil müəssisəsində GÇH rəhbərinin əsas vəzifə öhdəliklərinə hansı fəaliyyət daxildir?', 'multiple_choice', '["Məktəbin istilik qazanxanasının texniki təmirini və təmizliyini həyata keçirmək", "Yalnız fiziki tərbiyə dərslərini tədris etmək, hərbi-vətənpərvərlik işlərindən azad olmaq", "Tədris silahlarını və sursatları qeydiyyatsız şəkildə şagirdlərin evlərinə paylamaq", "GÇH fənn proqramının tədrisini təşkil etmək, sıra, atəş, MM təlimlərini təhlükəsiz keçmək və fənn kabinetinin pasportlaşdırılmasını təmin etmək", "Məktəbin illik maliyyə smetasını tərtib etmək və müəllimlərin əməkhaqqını hesablamaq"]'::jsonb, 'GÇH fənn proqramının tədrisini təşkil etmək, sıra, atəş, MM təlimlərini təhlükəsiz keçmək və fənn kabinetinin pasportlaşdırılmasını təmin etmək', 'Düzgün cavab: D) GÇH fənn proqramının tədrisini təşkil etmək, sıra, atəş, MM təlimlərini təhlükəs', '', 25, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a111573d-dd77-4cb0-9de8-08562eb4c14a', '8c01629a-ccc2-4484-88c2-807ff41e18f4', 'ka', 'რა არის სკოლაში წსმ-ის ხელმძღვანელის ძირითადი თანამდებობრივი მოვალეობა სასწავლო პროცესში?', '["წსმ-ის საგანში მხოლოდ სამწყობრო და საცეცხლე გაკვეთილების ჩატარება, კაბინეტზე პასუხისმგებლობის არქონა", "წსმ-ის საგნობრივი სასწავლო პროგრამის შესრულება, თუმცა სამოქალაქო თავდაცვის გაკვეთილების საგანგებო სიტუაციების სამინისტროსთვის მინდობა", "წსმ-ის საგნობრივი სასწავლო პროგრამის შესრულება, თუმცა უსაფრთხოების წესების დაუცველად", "წსმ-ის საგნობრივი სასწავლო პროგრამის შესრულება, სამწყობრო, საცეცხლე, ტოპოგრაფიული, საწესდებო და სამოქალაქო თავდაცვის გაკვეთილების უსაფრთხოდ და მეთოდურად ჩატარება, კაბინეტის პასპორტიზაცია", "მხოლოდ სკოლის სამეურნეო სამუშაოების ზედამხედველობა"]'::jsonb, 'წსმ-ის საგნობრივი სასწავლო პროგრამის შესრულება, სამწყობრო, საცეცხლე, ტოპოგრაფიული, საწესდებო და სამოქალაქო თავდაცვის გაკვეთილების უსაფრთხოდ და მეთოდურად ჩატარება, კაბინეტის პასპორტიზაცია', 'Düzgün cavab: D) წსმ-ის საგნობრივი სასწავლო პროგრამის შესრულება, სამწყობრო, საცეცხლე, ტოპოგრაფიულ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9bd14cda-415c-43bd-8bba-20cdd8b94372', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Mülki Müdafiə sistemində dinc və müharibə dövründə əhalinin mühafizəsinin 3 əsas üsulu hansıdır?', 'multiple_choice', '["Şəxsi sığınacaqların inşası, əhalinin silahlandırılması və sərhədlərin bağlanması", "Yalnız fərdi mühafizə vasitələrindən istifadə və rabitə xətlərinin kəsilməsi", "Mühafizə qurğularında (sığınacaqlarda) daldalanma, təhlükəsiz zonalara təxliyə və fərdi mühafizə vasitələrindən istifadə", "Məktəblərin bağlanması, şəhərlərdə komendant saatı və bütün ərzaqların müsadirəsi", "Yalnız əhalinin dağlıq rayonlara köçürülməsi və nəqliyyatın dayandırılması"]'::jsonb, 'Mühafizə qurğularında (sığınacaqlarda) daldalanma, təhlükəsiz zonalara təxliyə və fərdi mühafizə vasitələrindən istifadə', 'Düzgün cavab: C) Mühafizə qurğularında (sığınacaqlarda) daldalanma, təhlükəsiz zonalara təxliyə v', '', 26, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e2152f0a-a345-482d-96f9-7a9bfdfb98bb', '9bd14cda-415c-43bd-8bba-20cdd8b94372', 'ka', 'რა არის მოსახლეობის დაცვის ძირითადი მეთოდები სამოქალაქო თავდაცვის სისტემაში?', '["მხოლოდ თავშესაფრებში შეფარება", "მხოლოდ ევაკუაცია", "თავშესაფრებში შეფარება, ევაკუაცია უსაფრთხო ზონებში, ინდივიდუალური დაცვის საშუალებების გამოყენება", "მხოლოდ ინდივიდუალური დაცვის საშუალებების გამოყენება", "თავშესაფრებში შეფარება და კომენდანტის საათი"]'::jsonb, 'თავშესაფრებში შეფარება, ევაკუაცია უსაფრთხო ზონებში, ინდივიდუალური დაცვის საშუალებების გამოყენება', 'Düzgün cavab: C) თავშესაფრებში შეფარება, ევაკუაცია უსაფრთხო ზონებში, ინდივიდუალური დაცვის საშუალე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('452cc29b-dfd9-43a2-8c99-065e6d0649e0', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Azərbaycan Respublikasının Dövlət Bayrağındakı üç bərabər enli zolağın (mavi, qırmızı, yaşıl) rəmzi mənası hansı bənddə düzgün göstərilmişdir?', 'multiple_choice', '["Mavi – türk mənşəli olmağımızı, qırmızı – müasir cəmiyyət qurmaq və inkişafı, yaşıl – islam sivilizasiyasına mənsubluğu", "Mavi – islam dinini, qırmızı – türk mənşəyini, yaşıl – beynəlxalq əməkdaşlığı", "Mavi – Xəzər dənizini, qırmızı – müstəqilliyi, yaşıl – meşə zolaqlarını və gəncliyi", "Mavi – sülhü və səmanı, qırmızı – qəhrəmanlıq və müharibəni, yaşıl – təbiət və kənd təsərrüfatını", "Mavi – dövlətçilik ənənələrini, qırmızı – iqtisadi qüdrəti, yaşıl – ekoloji təmizliyi"]'::jsonb, 'Mavi – türk mənşəli olmağımızı, qırmızı – müasir cəmiyyət qurmaq və inkişafı, yaşıl – islam sivilizasiyasına mənsubluğu', 'Düzgün cavab: A) Mavi – türk mənşəli olmağımızı, qırmızı – müasir cəmiyyət qurmaq və inkişafı, ya', '', 27, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('741a1ce8-70b3-423b-af1d-32841d14a72d', '452cc29b-dfd9-43a2-8c99-065e6d0649e0', 'ka', '„აზერბაიჯანის რესპუბლიკის სახელმწიფო დროშის შესახებ“ კანონის თანახმად, რას გამოხატავს დროშის სამი ფერი?', '["ლურჯი – თურქულობა, წითელი – თანამედროვეობა/დემოკრატია, მწვანე – ისლამი", "ლურჯი – თურქულობა, წითელი – ისლამი, მწვანე – თანამედროვეობა", "ლურჯი – ისლამი, წითელი – თურქულობა, მწვანე – თანამედროვეობა", "ლურჯი – თურქულობა, წითელი – თანამედროვეობა, მწვანე – ბუნება", "ლურჯი – მშვიდობა, წითელი – დემოკრატია, მწვანე – ისლამი"]'::jsonb, 'ლურჯი – თურქულობა, წითელი – თანამედროვეობა/დემოკრატია, მწვანე – ისლამი', 'Düzgün cavab: A) ლურჯი – თურქულობა, წითელი – თანამედროვეობა/დემოკრატია, მწვანე – ისლამი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c0fb1e1a-9de1-4474-983e-975fd61c9486', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Ümumi təhsil müəssisəsində Mülki Müdafiə rəhbəri və MM qərargah rəisi vəzifələrini ştat üzrə kimlər icra edir?', 'multiple_choice', '["Mülki Müdafiə rəhbəri – məktəb həkimi, MM qərargah rəisi – kitabxana müdiri", "Mülki Müdafiə rəhbəri – təsərrüfat müdiri, MM qərargah rəisi – məktəb direktoru", "Mülki Müdafiə rəhbəri – yerli polis rəisi, MM qərargah rəisi – bədən tərbiyəsi müəllimi", "Mülki Müdafiə rəhbəri – məktəb direktoru, MM qərargah rəisi – GÇH rəhbəri", "Mülki Müdafiə rəhbəri – GÇH rəhbəri, MM qərargah rəisi – məktəb psixoloqu"]'::jsonb, 'Mülki Müdafiə rəhbəri – məktəb direktoru, MM qərargah rəisi – GÇH rəhbəri', 'Düzgün cavab: D) Mülki Müdafiə rəhbəri – məktəb direktoru, MM qərargah rəisi – GÇH rəhbəri', '', 28, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('048f6f22-581a-4abe-8f3c-5465f1907208', 'c0fb1e1a-9de1-4474-983e-975fd61c9486', 'ka', 'ვინ არის სკოლის სამოქალაქო თავდაცვის შტაბის უფროსი და ვინ არის უშუალოდ პასუხისმგებელი საევაკუაციო გეგმის შესრულებაზე?', '["სკოლის დირექტორი – როგორც სამოქალაქო თავდაცვის შტაბის უფროსი, ხოლო წსმ-ის ხელმძღვანელი – მისი მოადგილე", "დირექტორის მოადგილე – როგორც სამოქალაქო თავდაცვის შტაბის უფროსი, ხოლო წსმ-ის ხელმძღვანელი – როგორც წევრი", "სკოლის დირექტორი – სამოქალაქო თავდაცვის ხელმძღვანელი, ხოლო შტაბის უფროსი – საგანგებო სიტუაციების სამინისტროს წარმომადგენელი", "წსმ-ის ხელმძღვანელი – როგორც სკოლის სამოქალაქო თავდაცვის შტაბის უფროსი და მასწავლებელი", "წსმ-ის ხელმძღვანელი – სამოქალაქო თავდაცვის ხელმძღვანელი, ხოლო შტაბის უფროსი – დირექტორის მოადგილე"]'::jsonb, 'წსმ-ის ხელმძღვანელი – როგორც სკოლის სამოქალაქო თავდაცვის შტაბის უფროსი და მასწავლებელი', 'Düzgün cavab: D) წსმ-ის ხელმძღვანელი – როგორც სკოლის სამოქალაქო თავდაცვის შტაბის უფროსი და მასწავ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bd85d768-58d5-45b1-84c2-1b4c12c75855', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'F-1 müdafiə tipli əl qumbarasının partlayışı zamanı qəlpələrin təhlükəli yayılma radiusu normativ olaraq neçə metrdir?', 'multiple_choice', '["1000 metrədək", "25 metrədək", "200 metrədək", "500 metrədək", "50 metrədək"]'::jsonb, '200 metrədək', 'Düzgün cavab: C) 200 metrədək', '', 29, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9a2f861e-acb8-4fd5-9c41-ad41409f7dfe', 'bd85d768-58d5-45b1-84c2-1b4c12c75855', 'ka', 'დაახლოებით რამდენი მეტრია თავდაცვითი ხელყუმბარა F-1-ის ნამსხვრევების გავრცელების საშიში რადიუსი?', '["200 მეტრამდე სასიკვდილო, საშიში 500 მ", "50 მეტრამდე საშიში, სასიკვდილო 25 მ", "200 მეტრამდე საშიში, სასიკვდილო 25-30 მ", "200 მეტრი – მხოლოდ სასიკვდილო რადიუსი", "25 მეტრი – საშიში რადიუსი"]'::jsonb, '200 მეტრამდე საშიში, სასიკვდილო 25-30 მ', 'Düzgün cavab: C) 200 მეტრამდე საშიში, სასიკვდილო 25-30 მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fb2bf6b8-9a4f-409c-9c72-b98c6ec4f9ba', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Məktəbdə GÇH fənn kabinetinin və hərbi-tətbiqi maneələr zolağının pasportlaşdırılmasına və maddi bazasına cavabdehlik kimə həvalə olunur?', 'multiple_choice', '["Uşaq birliyi təşkilatı rəhbərinə", "İnformatika laborantına", "Valideyn-müəllim assosiasiyasının sədrinə", "Məktəb katibə-makinaçısına", "GÇH rəhbərinə"]'::jsonb, 'GÇH rəhbərinə', 'Düzgün cavab: E) GÇH rəhbərinə', '', 30, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('777044c6-382f-4019-84dc-20f9552e2131', 'fb2bf6b8-9a4f-409c-9c72-b98c6ec4f9ba', 'ka', 'ვინ არის პასუხისმგებელი სკოლაში წსმ-ის კაბინეტისა და დაბრკოლებათა ზოლის პასპორტიზაციაზე?', '["სკოლის დირექტორი – უშუალოდ როგორც კაბინეტის გამგე", "სამეურნეო ნაწილის გამგე – როგორც სასწავლო ბაზაზე პასუხისმგებელი", "ფიზიკური აღზრდის მასწავლებელი – როგორც დაბრკოლებათა ზოლზე პასუხისმგებელი", "საგანგებო სიტუაციების სამინისტროს წარმომადგენელი – როგორც პასპორტიზაციაზე პასუხისმგებელი", "წსმ-ის ხელმძღვანელი – როგორც კაბინეტის გამგე და სასწავლო ბაზაზე პასუხისმგებელი პირი"]'::jsonb, 'წსმ-ის ხელმძღვანელი – როგორც კაბინეტის გამგე და სასწავლო ბაზაზე პასუხისმგებელი პირი', 'Düzgün cavab: E) წსმ-ის ხელმძღვანელი – როგორც კაბინეტის გამგე და სასწავლო ბაზაზე პასუხისმგებელი პ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('84c4abbd-4fe1-4f8e-9c42-ca18f09bb83b', '8c406124-9903-47de-a830-bb6cf94fbbfa', '“Təhsil haqqında” AR Qanununa əsasən, aşağıdakılardan hansı təhsilverənlərin hüquqlarına **AİD DEYİLDİR** (vəzifəsidir)?', 'multiple_choice', '["Şərəf və ləyaqətinə hörmətlə yanaşılmasını tələb etmək", "Təhsil proqramlarının (kurikulumların) mənimsənilməsini təmin etmək və keyfiyyətli təhsil vermək", "Təhlükəsiz və normal təhsil-tərbiyə və əmək şəraiti ilə təmin olunmaq", "İxtisasını, elmi dərəcəsini artırmaq və yeni tədris texnologiyalarını sərbəst seçmək", "Təhsil müəssisəsinin idarə olunmasında və Pedaqoji Şurada iştirak etmək"]'::jsonb, 'Təhsil proqramlarının (kurikulumların) mənimsənilməsini təmin etmək və keyfiyyətli təhsil vermək', 'Düzgün cavab: B) Təhsil proqramlarının (kurikulumların) mənimsənilməsini təmin etmək və keyfiyyət', '', 31, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('53799130-1607-4b4a-8284-d144f0539d2b', '84c4abbd-4fe1-4f8e-9c42-ca18f09bb83b', 'ka', '„განათლების შესახებ“ კანონის თანახმად, რომელი არ განეკუთვნება მასწავლებელთა (პედაგოგთა) უფლებებს?', '["საგანმანათლებლო პროგრამების ხარისხიანი ათვისების მოთხოვნა – უფლებაა", "საგანმანათლებლო პროგრამების ათვისების უზრუნველყოფა – ეს არის მასწავლებლის მოვალეობა და არა უფლება", "სასწავლო პროცესის ორგანიზებაში მონაწილეობა – უფლებაა", "პატივისა და ღირსების პატივისცემის მოთხოვნა – უფლებაა", "კვალიფიკაციის ამაღლება – უფლებაა"]'::jsonb, 'საგანმანათლებლო პროგრამების ათვისების უზრუნველყოფა – ეს არის მასწავლებლის მოვალეობა და არა უფლება', 'Düzgün cavab: B) საგანმანათლებლო პროგრამების ათვისების უზრუნველყოფა – ეს არის მასწავლებლის მოვალე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d6538380-15ef-492f-8b7f-aa5bc2952ddf', '8c406124-9903-47de-a830-bb6cf94fbbfa', '“Təhsil haqqında” AR Qanununa əsasən, aşağıdakılardan hansı bilavasitə təhsilalanların hüquqlarına aiddir?', 'multiple_choice', '["Məktəbin Pedaqoji Şurasına sədrlik etmək və rəsmi əmrlər imzalamaq", "Məktəbdə çalışan pedaqoji işçiləri işə qəbul və ya azad etmək", "İnsan ləyaqətini alçaldan hərəkətlərdən müdafiə olunmaq, həyat və sağlamlıq üçün təhlükəsiz təhsil şəraiti ilə təmin olunmaq", "Dövlət təhsil standartlarını və fənn proqramlarını müstəqil dəyişdirmək", "Təhsil müəssisəsinin illik maliyyə hesabatlarını və ştat cədvəlini təsdiq etmək"]'::jsonb, 'İnsan ləyaqətini alçaldan hərəkətlərdən müdafiə olunmaq, həyat və sağlamlıq üçün təhlükəsiz təhsil şəraiti ilə təmin olunmaq', 'Düzgün cavab: C) İnsan ləyaqətini alçaldan hərəkətlərdən müdafiə olunmaq, həyat və sağlamlıq üçün', '', 32, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('576ab072-5d63-4c9a-8148-081aca47b651', 'd6538380-15ef-492f-8b7f-aa5bc2952ddf', 'ka', '„განათლების შესახებ“ კანონის თანახმად, რომელი განეკუთვნება მოსწავლეთა (განათლების მიმღებთა) უფლებებს?', '["სიცოცხლისა და ჯანმრთელობისთვის უსაფრთხო სასწავლო პირობების შექმნა – ეს დაწესებულების მოვალეობაა", "საგანმანათლებლო დაწესებულების ბიუჯეტის დამტკიცება", "სიცოცხლისა და ჯანმრთელობისთვის უსაფრთხო სასწავლო პირობებით უზრუნველყოფა", "პედაგოგიური საბჭოს თავმჯდომარეობა", "საგანმანათლებლო სტანდარტების დამტკიცება"]'::jsonb, 'სიცოცხლისა და ჯანმრთელობისთვის უსაფრთხო სასწავლო პირობებით უზრუნველყოფა', 'Düzgün cavab: C) სიცოცხლისა და ჯანმრთელობისთვის უსაფრთხო სასწავლო პირობებით უზრუნველყოფა', NOW(), NOW());
