INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a7f9dc6e-9e9a-4531-b3db-7895967704fd', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Azərbaycan Respublikası Konstitusiyasının 42-ci maddəsinə əsasən, dövlət hər bir vətəndaş üçün hansı təhsil təminatını verir?', 'multiple_choice', '["Dövlət yalnız ödənişli əsaslarla tam orta təhsil almaq hüququnu təmin edir", "Dövlət yalnız xaricdə təhsil alanların xərclərini qarşılayır", "Dövlət yalnız 21 yaşa qədər şəxslərin peşə təhsilini maliyyələşdirir", "Dövlət pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir", "Dövlət hər bir vətəndaşa imtahansız və pulsuz ali təhsil təminatı verir"]'::jsonb, 'Dövlət pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir', 'Düzgün cavab: D) Dövlət pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir', '', 38, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e8f8c7bf-e536-44b6-80d9-868604004249', 'a7f9dc6e-9e9a-4531-b3db-7895967704fd', 'ka', 'კონსტიტუციის თანახმად, რა დებულებაა განმტკიცებული მოქალაქის განათლების უფლებასთან დაკავშირებით?', '["სახელმწიფო უზრუნველყოფს ფასიანი სავალდებულო საბაზო ზოგადი განათლების უფლებას", "სახელმწიფო უზრუნველყოფს უფასო სავალდებულო სრული ზოგადი საშუალო განათლების უფლებას", "სახელმწიფო უზრუნველყოფს უფასო სავალდებულო დაწყებითი განათლების უფლებას", "სახელმწიფო უზრუნველყოფს უფასო სავალდებულო საბაზო ზოგადი განათლების მიღების უფლებას", "სახელმწიფო უზრუნველყოფს მხოლოდ უმაღლესი განათლების უფლებას"]'::jsonb, 'სახელმწიფო უზრუნველყოფს უფასო სავალდებულო საბაზო ზოგადი განათლების მიღების უფლებას', 'Düzgün cavab: D) სახელმწიფო უზრუნველყოფს უფასო სავალდებულო საბაზო ზოგადი განათლების მიღების უფლებ', NOW(), NOW());
