INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('47efdcd5-e944-4e9e-8285-feda9f65728b', '8c406124-9903-47de-a830-bb6cf94fbbfa', '“Təhsil haqqında” AR Qanununa əsasən, təhsilverənlərin attestasiyasının keçirilməsində əsas məqsəd nədir?', 'multiple_choice', '["Təhsilverənlərin peşəkarlıq səviyyəsinin və peşə yararlılığının tutduğu vəzifəyə uyğunluğunu yoxlamaq", "Məktəbə ayrılan dövlət vəsaitlərinin xərclənməsini audit etmək", "Müəllimləri növbədənkənar hərbi təlimlərə cəlb etmək", "Şagirdlərin dərsə davamiyyət faizini rəsmi qeydə almaq", "Məktəb binasının yanğın təhlükəsizliyi vəziyyətini qiymətləndirmək"]'::jsonb, 'Təhsilverənlərin peşəkarlıq səviyyəsinin və peşə yararlılığının tutduğu vəzifəyə uyğunluğunu yoxlamaq', 'Düzgün cavab: A) Təhsilverənlərin peşəkarlıq səviyyəsinin və peşə yararlılığının tutduğu vəzifəyə', '', 44, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c9c4b81c-47d7-4e17-a62a-a48166f505d9', '47efdcd5-e944-4e9e-8285-feda9f65728b', 'ka', '„განათლების შესახებ“ კანონის თანახმად, რა მიზნით ტარდება ატესტაცია?', '["მოსწავლეთა და პედაგოგთა ცოდნისა და პროფესიონალიზმის დონის სტანდარტებთან შესაბამისობის შესამოწმებლად", "მხოლოდ მოსწავლეთა ცოდნის დონის შესამოწმებლად", "მხოლოდ პედაგოგთა პროფესიონალიზმის დონის შესამოწმებლად", "სკოლის ტექნიკური უსაფრთხოების შესამოწმებლად", "სკოლის ფინანსური მდგომარეობის შესამოწმებლად"]'::jsonb, 'მოსწავლეთა და პედაგოგთა ცოდნისა და პროფესიონალიზმის დონის სტანდარტებთან შესაბამისობის შესამოწმებლად', 'Düzgün cavab: A) მოსწავლეთა და პედაგოგთა ცოდნისა და პროფესიონალიზმის დონის სტანდარტებთან შესაბამი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('171ecaa2-2718-422b-8d70-e0a89d36a0c8', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Pedaqoji işçilər tərəfindən xidməti fəaliyyət zamanı etik davranış qaydalarının pozulması hansı hüquqi məsuliyyət növünə səbəb olur?', 'multiple_choice', '["Mülki-hüquqi müqavilə öhdəliyinə", "Maddi cərimə tətbiq edilən inzibati həbsə", "İntizam məsuliyyətinə", "Heç bir hüquqi məsuliyyət yaratmır", "Birbaşa cinayət məsuliyyətinə"]'::jsonb, 'İntizam məsuliyyətinə', 'Düzgün cavab: C) İntizam məsuliyyətinə', '', 45, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6da893a1-1a97-45f8-b65b-5de235b5bac8', '171ecaa2-2718-422b-8d70-e0a89d36a0c8', 'ka', 'რა პასუხისმგებლობას იწვევს სამსახურებრივი საქმიანობის დროს ეთიკური ქცევის წესების დარღვევა?', '["ადმინისტრაციულ პასუხისმგებლობას – მხოლოდ ჯარიმას", "სისხლისსამართლებრივ პასუხისმგებლობას – პირდაპირ პატიმრობას", "დისციპლინურ პასუხისმგებლობას", "არანაირ პასუხისმგებლობას არ იწვევს", "სამოქალაქო პასუხისმგებლობას"]'::jsonb, 'დისციპლინურ პასუხისმგებლობას', 'Düzgün cavab: C) დისციპლინურ პასუხისმგებლობას', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('09d4e5a0-9e97-4ef1-a372-6bdfe821d4b8', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Kompüter şəbəkələrində Lokal Şəbəkə (LAN) ilə Qlobal Şəbəkə (WAN) arasındakı əsas texnoloji fərq nədən ibarətdir?', 'multiple_choice', '["LAN yalnız internetə çıxış üçün, WAN isə ofisdaxili printer paylaşımı üçündür", "LAN qlobal miqyaslı beynəlxalq şəbəkədir, WAN isə yalnız fərdi kompüter daxili şindir", "LAN şəbəkəsində IP ünvanlardan istifadə olunmur, WAN-da isə mütləqdir", "LAN məhdud coğrafi sahəni (otaq, bina), WAN isə geniş coğrafi əraziləri (şəhər, ölkə, qitə) əhatə edir", "LAN yalnız peyk rabitəsi ilə, WAN isə yalnız optik kabellərlə işləyir"]'::jsonb, 'LAN məhdud coğrafi sahəni (otaq, bina), WAN isə geniş coğrafi əraziləri (şəhər, ölkə, qitə) əhatə edir', 'Düzgün cavab: D) LAN məhdud coğrafi sahəni (otaq, bina), WAN isə geniş coğrafi əraziləri (şəhər,', '', 46, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4b5ac46d-53f6-4587-8d8a-0506b113079f', '09d4e5a0-9e97-4ef1-a372-6bdfe821d4b8', 'ka', 'რა არის ძირითადი ტექნოლოგიური განსხვავება LAN-სა და WAN-ს შორის?', '["LAN მოიცავს ფართო ტერიტორიებს, ხოლო WAN – შეზღუდულ არეალს", "LAN განკუთვნილია მხოლოდ ინტერნეტთან წვდომისთვის, ხოლო WAN – ლოკალური ფაილების გაცვლისთვის", "LAN მოიცავს შეზღუდულ არეალს, ხოლო WAN ერთსა და იმავე შენობას – განსხვავება ოქმშია", "LAN მოიცავს შეზღუდულ გეოგრაფიულ არეალს (შენობა, კამპუსი), ხოლო WAN – ფართო ტერიტორიებს (ქალაქი, ქვეყანა, კონტინენტი)", "LAN მოიცავს ფართო არეალს 10 კმ-ს, ხოლო WAN – 1 კმ-ს"]'::jsonb, 'LAN მოიცავს შეზღუდულ გეოგრაფიულ არეალს (შენობა, კამპუსი), ხოლო WAN – ფართო ტერიტორიებს (ქალაქი, ქვეყანა, კონტინენტი)', 'Düzgün cavab: D) LAN მოიცავს შეზღუდულ გეოგრაფიულ არეალს (შენობა, კამპუსი), ხოლო WAN – ფართო ტერიტ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('150d2acd-95d5-4ce8-a985-3af6c637f9b0', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'İnternetdə istifadəçilərin daxil etdiyi domen adlarını (məsələn, edu.gov.az) kompüterlərin anladığı rəqəmsal IP ünvanlarına çevirən əsas şəbəkə xidməti hansıdır?', 'multiple_choice', '["DNS (Domain Name System)", "HTTP (HyperText Transfer Protocol)", "SMTP (Simple Mail Transfer Protocol)", "DHCP (Dynamic Host Configuration Protocol)", "FTP (File Transfer Protocol)"]'::jsonb, 'DNS (Domain Name System)', 'Düzgün cavab: A) DNS (Domain Name System)', '', 47, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e046f74b-a7a9-4f82-9eed-ea1e1694e4d5', '150d2acd-95d5-4ce8-a985-3af6c637f9b0', 'ka', 'რომელი ძირითადი ქსელური სერვისი გარდაქმნის დომენურ სახელებს IP მისამართებად?', '["DNS – Domain Name System, პორტი 53", "DNS – Domain Name System, პორტი 80", "DHCP – Dynamic Host Configuration, პორტი 53", "DNS – Data Name Service, პორტი 53", "DNS – Domain Network Service, პორტი 443"]'::jsonb, 'DNS – Domain Name System, პორტი 53', 'Düzgün cavab: A) DNS – Domain Name System, პორტი 53', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d7e5dc4e-ec6c-4375-8323-a3328a2ced94', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'İki faktorlu autentifikasiya (2FA) təhlükəsizlik mexanizminin əsas üstünlüyü nədən ibarətdir?', 'multiple_choice', '["Şifrə unudulduqda kompüterin əməliyyat sistemini avtomatik yenidən quraşdırması", "Şifrə daxil edilmədən birbaşa istənilən veb-sayta sərbəst giriş təmin etməsi", "İstifadəçinin əsas şifrəsi ələ keçirilsə belə, ikinci müstəqil təsdiq kodu olmadan hesaba girişi əngəlləməsi", "İnternet şəbəkəsinin sürətini və fayl yükləmə həcmini ikiqat artırması", "Kompüterə antivirus proqramı yazılmasının qarşısını alması"]'::jsonb, 'İstifadəçinin əsas şifrəsi ələ keçirilsə belə, ikinci müstəqil təsdiq kodu olmadan hesaba girişi əngəlləməsi', 'Düzgün cavab: C) İstifadəçinin əsas şifrəsi ələ keçirilsə belə, ikinci müstəqil təsdiq kodu olmad', '', 48, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d251cf18-d043-4318-b3a0-53882a1801ab', 'd7e5dc4e-ec6c-4375-8323-a3328a2ced94', 'ka', 'რა არის ორფაქტორიანი აუთენტიფიკაციის (2FA) მექანიზმის მთავარი უპირატესობა?', '["პაროლის ხელში ჩაგდებისას, წვდომის დაშვება მეორე დადასტურების გარეშეც, თუმცა გაფრთხილებით", "მხოლოდ პაროლის სირთულის გაზრდა", "პაროლის ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების გარეშე", "ინტერნეტის სიჩქარის გაზრდა", "პაროლის ავტომატური შეცვლა"]'::jsonb, 'პაროლის ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების გარეშე', 'Düzgün cavab: C) პაროლის ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3a73a54a-4215-4a50-8c81-ba3255d3a08b', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Kiberdələduzların rəsmi və etibarlı təşkilat adından saxta e-poçt və keçidlər göndərərək istifadəçilərin məxfi məlumatlarını (şifrə, kart məlumatları) ələ keçirməsi hücumu necə adlanır?', 'multiple_choice', '["DDoS hücumu", "Ransomware (Fidyə proqramı)", "Spyware (Casus proqram)", "Trojan (Troyan atı)", "Fişinq (Phishing)"]'::jsonb, 'Fişinq (Phishing)', 'Düzgün cavab: E) Fişinq (Phishing)', '', 49, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('5fdc9f07-865c-43b4-9789-23c7ec8f8b9e', '3a73a54a-4215-4a50-8c81-ba3255d3a08b', 'ka', 'თავდასხმის რომელი სახეობაა, როდესაც თაღლითები სანდო ორგანიზაციის სახელით ყალბ ელფოსტას აგზავნიან მონაცემების მისათვისებლად?', '["Spear Phishing – მხოლოდ DDoS თავდასხმის სახეობა", "ფიშინგი – მხოლოდ ვირუსების გავრცელების მეთოდი", "ვიშინგი (Vishing) – მხოლოდ სატელეფონო შეტევა, ელფოსტა არ ეხება", "ფიშინგი – მხოლოდ სარეკლამო შეტევა", "ფიშინგი (Phishing) – სოციალურ ინჟინერიაზე დაფუძნებული მონაცემთა მოპარვა ყალბი ელფოსტითა და ვებსაიტით"]'::jsonb, 'ფიშინგი (Phishing) – სოციალურ ინჟინერიაზე დაფუძნებული მონაცემთა მოპარვა ყალბი ელფოსტითა და ვებსაიტით', 'Düzgün cavab: E) ფიშინგი (Phishing) – სოციალურ ინჟინერიაზე დაფუძნებული მონაცემთა მოპარვა ყალბი ელ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('dc59f9c3-5e34-4d60-8056-918f20f3bdfd', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'MS Word mətn redaktorunda seçilmiş abzasın sol, sağ kənar boşluqlarını və birinci sətir girintisini vizual tənzimləmək üçün hansı elementdən istifadə edilir?', 'multiple_choice', '["Başlıq sətrindəki pəncərəni bağlama düyməsindən", "Pəncərənin ən aşağısında yerləşən Vəziyyət zolağından (Status Bar)", "Tez Keçid panelindəki Yadda saxla düyməsindən", "Üfüqi xətkeş üzərindəki girinti sürüşdürücülərindən", "Sənədin şaquli fırlatma zolağından (Scroll Bar)"]'::jsonb, 'Üfüqi xətkeş üzərindəki girinti sürüşdürücülərindən', 'Düzgün cavab: D) Üfüqi xətkeş üzərindəki girinti sürüşdürücülərindən', '', 50, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4cf9971f-f342-4e0c-a0c5-36b87d30cda4', 'dc59f9c3-5e34-4d60-8056-918f20f3bdfd', 'ka', 'Word-ში რომელი ელემენტი გამოიყენება აბზაცის შეწევების (indent) ზუსტი ვიზუალური რეგულირებისთვის?', '["ვერტიკალურ სახაზავზე არსებული შეწევის მორბენალები", "ჰორიზონტალური სახაზავი – მხოლოდ First Line-ისთვის", "სტატუსის ზოლი (Status Bar)", "ჰორიზონტალურ სახაზავზე არსებული შეწევის მორბენალები (სლაიდერები) და Paragraph დიალოგური ფანჯარა", "ჰორიზონტალური სახაზავი – მხოლოდ Left indent-ისთვის"]'::jsonb, 'ჰორიზონტალურ სახაზავზე არსებული შეწევის მორბენალები (სლაიდერები) და Paragraph დიალოგური ფანჯარა', 'Düzgün cavab: D) ჰორიზონტალურ სახაზავზე არსებული შეწევის მორბენალები (სლაიდერები) და Paragraph დი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ee419376-c039-4836-bd88-33f1c29bbcaf', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'MS Word-də sənədin digər səhifələrinə toxunmadan yalnız müəyyən səhifələrin istiqamətini (Orientation: Portrait/Landscape) dəyişmək üçün hansı əməliyyat icra olunmalıdır?', 'multiple_choice', '["Həmin səhifələrin əvvəlinə və sonuna Bölmə Kəsilməsi (Section Break – Next Page) əlavə edib istiqaməti dəyişmək", "Sənədi iki ayrı sənədə bölərək ayrı fayllar kimi saxlamaq", "Bütün mətni seçib klaviaturadan Ctrl + Enter düymələrini basmaq", "Sənədə adi Səhifə Kəsilməsi (Page Break) qoyub şriftin ölçüsünü kiçiltmək", "Görünüş rejimini yalnız Qaralama (Draft) formasına keçirmək"]'::jsonb, 'Həmin səhifələrin əvvəlinə və sonuna Bölmə Kəsilməsi (Section Break – Next Page) əlavə edib istiqaməti dəyişmək', 'Düzgün cavab: A) Həmin səhifələrin əvvəlinə və sonuna Bölmə Kəsilməsi (Section Break – Next Page)', '', 51, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('dc0a3572-2dc0-4fc6-93c5-c4c10e02a518', 'ee419376-c039-4836-bd88-33f1c29bbcaf', 'ka', 'Word-ში რა ოპერაცია უნდა შესრულდეს ზოგიერთი გვერდის ვერტიკალურ (წიგნისებურ), ხოლო ზოგიერთის ჰორიზონტალურ (ალბომურ) ორიენტაციაზე დასაყენებლად?', '["დოკუმენტში სექციის გაწყვეტის (Section Break – Next Page) დამატება და ამ სექციის Orientation პარამეტრის შეცვლა", "დოკუმენტში გვერდის გაწყვეტის (Page Break) დამატება და Orientation-ის შეცვლა", "დოკუმენტში სექციის გაწყვეტის დამატება და მთელი დოკუმენტის Orientation-ის შეცვლა", "სექციის გაწყვეტის დამატების გარეშე პირდაპირ Orientation-ის შეცვლა", "დოკუმენტის გაყოფა ორ ცალკე ფაილად"]'::jsonb, 'დოკუმენტში სექციის გაწყვეტის (Section Break – Next Page) დამატება და ამ სექციის Orientation პარამეტრის შეცვლა', 'Düzgün cavab: A) დოკუმენტში სექციის გაწყვეტის (Section Break – Next Page) დამატება და ამ სექციის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f74def1f-872b-4eef-b1bd-f55f311ed82b', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'MS Word-də başlıq üslublarına (Heading styles) əsasən avtomatik yenilənən Mündəricat yerləşdirmək üçün hansı lent tabına müraciət edilir?', 'multiple_choice', '["Layout (Düzən) > Page Setup", "Review (İcmal) > Track Changes", "Insert (Əlavə et) > WordArt", "View (Görünüş) > Zoom", "References (İstinadlar) > Table of Contents"]'::jsonb, 'References (İstinadlar) > Table of Contents', 'Düzgün cavab: E) References (İstinadlar) > Table of Contents', '', 52, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('dedc8f5a-fa27-49bd-968c-2666a5141167', 'f74def1f-872b-4eef-b1bd-f55f311ed82b', 'ka', 'Word-ში სათაურებზე დაყრდნობით ავტომატურად განახლებადი სარჩევის შესაქმნელად რომელ ჩანართს (tab) უნდა მივმართოთ?', '["References > Insert Caption", "Insert > Table of Contents", "References > Bibliography", "Layout > Table of Contents", "References > Table of Contents"]'::jsonb, 'References > Table of Contents', 'Düzgün cavab: E) References > Table of Contents', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ab509f99-af7f-4cd8-ab37-39871f4186bb', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'MS Excel cədvəl redaktorunda düstur daxilində `$C$2` mütləq ünvanı istifadə edildikdə, bu düstur başqa xanalara kopyalanarkən həmin ünvan necə dəyişir?', 'multiple_choice', '["Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır", "Xana daxilindəki düstur avtomatik olaraq #REF! xətasına çevrilir", "Sətir nömrəsi sabit qalır, lakin sütun hərfi sağa doğru sürüşür", "Həm sütun, həm də sətir yeni xanaya uyğun olaraq avtomatik sürüşür", "Sütun sabit qalır, lakin sətir nömrəsi aşağıya doğru sürüşür"]'::jsonb, 'Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', 'Düzgün cavab: A) Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', '', 53, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c3902f53-d3f8-4d56-a473-29cd8f52affc', 'ab509f99-af7f-4cd8-ab37-39871f4186bb', 'ka', 'Excel-ში როგორ იცვლება ფორმულა სხვა უჯრებში კოპირებისას, თუ მასში გამოყენებულია აბსოლუტური მისამართი $C$2?', '["რჩება სრულიად უცვლელი – აბსოლუტური ბმული", "უცვლელი რჩება მხოლოდ სვეტი – შერეული ბმული", "უცვლელი რჩება მხოლოდ სტრიქონი – შერეული ბმული", "ინაცვლებს როგორც სვეტი, ასევე სტრიქონი – ფარდობითი ბმული", "სვეტი ინაცვლებს, სტრიქონი რჩება უცვლელი – როგორც $C2"]'::jsonb, 'რჩება სრულიად უცვლელი – აბსოლუტური ბმული', 'Düzgün cavab: A) რჩება სრულიად უცვლელი – აბსოლუტური ბმული', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('85ac50bf-05f0-4a67-aeca-2648b03cc5a9', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'MS Excel-də `A1:A10` diapazonunda yalnız qiyməti 50-dən böyük olan xanaların sayını hesablamaq üçün hansı funksiya düzgün sintaksislə yazılmışdır?', 'multiple_choice', '["=COUNT(A1:A10; >50)", "=COUNTIF(A1:A10; \">50\")", "=IFCOUNT(A1:A10; \">50\")", "=SUMIF(A1:A10; >50)", "=COUNTIF(A1:A10 = 50)"]'::jsonb, '=COUNTIF(A1:A10; ">50")', 'Düzgün cavab: B) =COUNTIF(A1:A10; ">50")', '', 54, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2f9a3b55-eb4a-432a-ad8f-89b8e4b642c3', '85ac50bf-05f0-4a67-aeca-2648b03cc5a9', 'ka', 'Excel-ში A1:A10 დიაპაზონში მხოლოდ 50-ზე მეტი მნიშვნელობის მქონე უჯრების რაოდენობის დასათვლელად რომელი ფუნქციაა სწორი?', '["=COUNTIF(A1:A10;\"> 50\") – ინტერვალით (space)", "=COUNTIF(A1:A10;\">50\")", "=COUNTIF(A1:A10;50) – ბრჭყალების გარეშე", "=COUNTIFS(A1:A10;\">50\") – ერთი პირობისას", "=COUNT(A1:A10;\">50\")"]'::jsonb, '=COUNTIF(A1:A10;">50")', 'Düzgün cavab: B) =COUNTIF(A1:A10;">50")', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('14b56b92-2e3d-4d72-9759-8772c14c6b0c', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'MS Excel-də B2 xanasındakı əməkhaqqı 800-dən çox olduqda 15%, əks halda 5% mükafat hesablayan məntiqi düstur hansıdır?', 'multiple_choice', '["=IF(B2>800; B2*0.15; 0)", "=IF(B2>800; B2*0.15; B2*0.05)", "=IF(B2>=800; B2*0.15; B2*0.05)", "=IF(B2>800; 15%; 5%)", "=IF(B2<800; B2*0.15; B2*0.05)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: B) =IF(B2>800; B2*0.15; B2*0.05)', '', 55, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('20d815d8-2099-45ff-bdad-b12a9fc28426', '14b56b92-2e3d-4d72-9759-8772c14c6b0c', 'ka', 'Excel-ში რომელი ფორმულა ითვლის 15%-იან პრემიას, როდესაც B2 უჯრაში ხელფასი 800-ზე მეტია?', '["=IF(B2>=800;B2*0.15;B2*0.05) – 800-ის ჩათვლით", "=IF(B2>800;B2*0.15;B2*0.05)", "=IF(B2>800;B2*15%;B2*5%) – პროცენტით იგივეა, მაგრამ 800-ზე მეტის პირობა არასწორია? სინამდვილეში იგივეა, მაგრამ ლოგიკა განსხვავებულია", "=IF(B2>800;B2*0.15;0) – წინააღმდეგ შემთხვევაში 0", "=IF(B2>800;B2*0.15;B2*0.10)"]'::jsonb, '=IF(B2>800;B2*0.15;B2*0.05)', 'Düzgün cavab: B) =IF(B2>800;B2*0.15;B2*0.05)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6f93ca04-7099-4c9d-adf9-7755cde6464d', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'MS Excel-də seçilmiş xanaya yalnız müəyyən diapazonda ədədlərin və ya xüsusi siyahıdakı məlumatların daxil edilməsini təmin edən alət hansıdır?', 'multiple_choice', '["Text to Columns (Mətnin sütunlara bölünməsi)", "Data Validation (Verilənlərin doğrulanması)", "AutoFilter (Avtosüzgəc)", "Remove Duplicates (Təkrarların silinməsi)", "Conditional Formatting (Şərti formatlaşdırma)"]'::jsonb, 'Data Validation (Verilənlərin doğrulanması)', 'Düzgün cavab: B) Data Validation (Verilənlərin doğrulanması)', '', 56, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('aabbcd5d-8cca-4044-8556-130362733105', '6f93ca04-7099-4c9d-adf9-7755cde6464d', 'ka', 'Excel-ში რომელი ინსტრუმენტი იძლევა საშუალებას უჯრაში რიცხვები შევიდეს მხოლოდ განსაზღვრულ დიაპაზონში?', '["Data Validation – მხოლოდ Whole Number კრიტერიუმით", "Data Validation – Whole Number, Decimal, List კრიტერიუმებით", "Conditional Formatting", "Data Validation – მხოლოდ List კრიტერიუმით", "Filter"]'::jsonb, 'Data Validation – Whole Number, Decimal, List კრიტერიუმებით', 'Düzgün cavab: B) Data Validation – Whole Number, Decimal, List კრიტერიუმებით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4dc86657-bced-4edb-8f51-fb405ef9c2a0', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'MS PowerPoint proqramında təqdimatdakı bütün slaydların vahid dizaynını, şrift və loqosunu eyni anda tənzimləmək üçün hansı rejimdən istifadə edilir?', 'multiple_choice', '["Reading View (Oxu rejimi)", "Presenter View (Aparıcı görünüşü)", "Slide Sorter (Slayd çeşidləyicisi)", "Slide Master (Slayd nümunəsi)", "Notes Master (Qeydlər nümunəsi)"]'::jsonb, 'Slide Master (Slayd nümunəsi)', 'Düzgün cavab: D) Slide Master (Slayd nümunəsi)', '', 57, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b2be8eac-7628-47a1-9555-3375fd49141d', '4dc86657-bced-4edb-8f51-fb405ef9c2a0', 'ka', 'PowerPoint-ში რომელი რეჟიმი გამოიყენება ყველა სლაიდის ერთიანი დიზაინის შაბლონის შესაცვლელად?', '["Slide Master – Insert ჩანართში", "Slide Sorter", "Slide Master – Design ჩანართში", "Slide Master – View ჩანართში", "Handout Master"]'::jsonb, 'Slide Master – View ჩანართში', 'Düzgün cavab: D) Slide Master – View ჩანართში', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('455a36fc-38ba-4c35-9341-e266ef6148b5', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'MS PowerPoint proqramında “Transition” (Keçid) ilə “Animation” (Animasiya) arasındakı əsas texnoloji fərq nədir?', 'multiple_choice', '["Transition bir slayddan digərinə keçid effekti, Animation isə slayd daxilindəki obyektlərin hərəkət effektidir", "Transition və Animation tamamilə eyni funksiyadır və heç bir fərqi yoxdur", "Transition yalnız çap rejimində, Animation isə yalnız slayd redaktəsi zamanı işləyir", "Transition slayd daxilindəki mətnlərə, Animation isə yalnız slayddan slayda keçidlərə tətbiq olunur", "Transition yalnız video faylları, Animation isə yalnız səs yazılarını idarə edir"]'::jsonb, 'Transition bir slayddan digərinə keçid effekti, Animation isə slayd daxilindəki obyektlərin hərəkət effektidir', 'Düzgün cavab: A) Transition bir slayddan digərinə keçid effekti, Animation isə slayd daxilindəki', '', 58, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('5f5c3c6d-60c8-464f-b13e-4d204ca58e33', '455a36fc-38ba-4c35-9341-e266ef6148b5', 'ka', 'რა არის ძირითადი განსხვავება PowerPoint-ში ''Transition''-სა და ''Animation''-ს შორის?', '["Transition არის სლაიდიდან სლაიდზე გადასვლის ეფექტი, ხოლო Animation – სლაიდის შიგნით არსებული ობიექტის ანიმაციის ეფექტი", "Transition არის სლაიდის შიგნით არსებული ობიექტის ეფექტი, ხოლო Animation – სლაიდიდან სლაიდზე გადასვლის ეფექტი", "ორივე ერთნაირია – სლაიდიდან სლაიდზე გადასვლის ეფექტი", "ორივე ერთნაირია – ობიექტის მოძრაობის ეფექტი", "Transition არის მხოლოდ ხმოვანი ეფექტი, ხოლო Animation – მხოლოდ ვიზუალური"]'::jsonb, 'Transition არის სლაიდიდან სლაიდზე გადასვლის ეფექტი, ხოლო Animation – სლაიდის შიგნით არსებული ობიექტის ანიმაციის ეფექტი', 'Düzgün cavab: A) Transition არის სლაიდიდან სლაიდზე გადასვლის ეფექტი, ხოლო Animation – სლაიდის შიგ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f1b90ea1-e35b-408c-ab3a-4bcb2cdf80a5', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Bulud saxlama xidmətlərində (məsələn, OneDrive) saxlanılan sənədin əvvəlki tarixdəki redaktə versiyalarına baxmaq və bərpa etmək üçün hansı funksiyadan istifadə olunur?', 'multiple_choice', '["Version History (Versiya tarixçəsi)", "Compatibility Mode (Uyğunluq rejimi)", "Save As (Fərqli saxla)", "Encrypt with Password (Parolla şifrələmə)", "Inspect Document (Sənədi yoxla)"]'::jsonb, 'Version History (Versiya tarixçəsi)', 'Düzgün cavab: A) Version History (Versiya tarixçəsi)', '', 59, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7ead8524-5337-4e90-87c7-b796618ec5cf', 'f1b90ea1-e35b-408c-ab3a-4bcb2cdf80a5', 'ka', 'ღრუბლოვან საცავებში რომელი ფუნქცია გამოიყენება დოკუმენტის წინა ვერსიებზე დასაბრუნებლად?', '["Version History – File > Info > Version History", "Version History – File > Save As", "Version History – Home > History", "Browse Version – File > Open", "Version History – View > History"]'::jsonb, 'Version History – File > Info > Version History', 'Düzgün cavab: A) Version History – File > Info > Version History', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('89224023-6c23-4696-be1e-b338e643ae5d', '8c406124-9903-47de-a830-bb6cf94fbbfa', 'Süni intellekt əsaslı generativ dil modellərində (LLM) “Hallüsinasiya” (Hallucination) termini nəyi ifadə edir?', 'multiple_choice', '["Modelin yalnız proqramlaşdırma kodlarında sintaksis səhvləri etməsini", "Modelin kompüterin aparat hissəsini qızdıraraq sıradan çıxarmasını", "Modelin yalnız orfoqrafik hərf səhvləri buraxmasını", "Modelin real faktlara əsaslanmayan, uydurma məlumatları çox inandırıcı və qətiyyətli tərzdə təqdim etməsini", "Modelin internet bağlantısını zəiflədərək şəbəkəni dondurmasını"]'::jsonb, 'Modelin real faktlara əsaslanmayan, uydurma məlumatları çox inandırıcı və qətiyyətli tərzdə təqdim etməsini', 'Düzgün cavab: D) Modelin real faktlara əsaslanmayan, uydurma məlumatları çox inandırıcı və qətiyy', '', 60, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e8f5a448-ecca-4e36-9b4f-77052a348beb', '89224023-6c23-4696-be1e-b338e643ae5d', 'ka', 'რას გამოხატავს „ჰალუცინაციის“ (Hallucination) რისკი ხელოვნურ ინტელექტზე დაფუძნებულ გენერაციულ მოდელებში?', '["მოდელის მიერ მცდარი ინფორმაციის არადამაჯერებელი ფორმით გენერირებას", "მოდელის მიერ მხოლოდ კოდში შეცდომის დაშვებას", "მოდელის მიერ აპარატურის მწყობრიდან გამოყვანას", "მოდელის მიერ მცდარი, გამოგონილი ან არარსებული ინფორმაციის დამაჯერებელი ფორმით გენერირებას", "მოდელის მიერ ინტერნეტის გაყინვას"]'::jsonb, 'მოდელის მიერ მცდარი, გამოგონილი ან არარსებული ინფორმაციის დამაჯერებელი ფორმით გენერირებას', 'Düzgün cavab: D) მოდელის მიერ მცდარი, გამოგონილი ან არარსებული ინფორმაციის დამაჯერებელი ფორმით გე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a38a13a9-f9b5-4849-989b-bbeb921aa08b', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Ümumi təhsil müəssisəsində İnformatika kabinetinin laborantının əsas vəzifə öhdəliklərinə hansı fəaliyyət daxildir?', 'multiple_choice', '["İnformatika fənni üzrə dövlət təhsil proqramını (kurikulumu) müstəqil hazırlayıb təsdiq etmək", "Kompüter texnikasının, şəbəkə infrastrukturunun və multimedia avadanlıqlarının texniki sazlığını, təhlükəsizliyini və tədrisə hazırlığını təmin etmək, proqram təminatının qurulmasına texniki dəstək vermək", "Məktəbdə təhsil alan şagirdlərin dərsdənkənar tərbiyə işlərinə və sinif rəhbərlərinə ümumi rəhbərlik etmək", "Fənn üzrə summativ qiymətləndirmə materiallarını tərtib edib şagirdlərin rüblük qiymətlərini təsdiqləmək", "Məktəbin illik maliyyə hesabatlarını tərtib etmək və kadr kargüzarlığını aparmaq"]'::jsonb, 'Kompüter texnikasının, şəbəkə infrastrukturunun və multimedia avadanlıqlarının texniki sazlığını, təhlükəsizliyini və tədrisə hazırlığını təmin etmək, proqram təminatının qurulmasına texniki dəstək vermək', 'Düzgün cavab: B) Kompüter texnikasının, şəbəkə infrastrukturunun və multimedia avadanlıqlarının t', '', 1, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('5768c26b-59e9-4817-a064-cee17139aaec', 'a38a13a9-f9b5-4849-989b-bbeb921aa08b', 'ka', 'რა საქმიანობა შედის ზოგადსაგანმანათლებლო დაწესებულებაში ინფორმატიკის კაბინეტის ლაბორანტის ძირითად სამსახურებრივ მოვალეობებში?', '["სკოლის წლიური ფინანსური ანგარიშგებისა და საბუღალტრო აღრიცხვის წარმოება", "კომპიუტერული ტექნიკის, ქსელური ინფრასტრუქტურისა და მულტიმედიური მოწყობილობების ტექნიკური გამართულობის, უსაფრთხოებისა და სასწავლო პროცესისთვის მზადყოფნის უზრუნველყოფა, პროგრამული უზრუნველყოფის ინსტალაციის მხარდაჭერა", "ინფორმატიკის საგნობრივი სასწავლო პროგრამის დამოუკიდებლად შემუშავება და დამტკიცება", "საგნის მიხედვით შემაჯამებელი შეფასების მასალების შედგენა და მოსწავლეთა კვარტალური/სემესტრული ნიშნების დამტკიცება", "სკოლაში მოსწავლეთა კლასგარეშე აღმზრდელობითი საქმიანობის ხელმძღვანელობა"]'::jsonb, 'კომპიუტერული ტექნიკის, ქსელური ინფრასტრუქტურისა და მულტიმედიური მოწყობილობების ტექნიკური გამართულობის, უსაფრთხოებისა და სასწავლო პროცესისთვის მზადყოფნის უზრუნველყოფა, პროგრამული უზრუნველყოფის ინსტალაციის მხარდაჭერა', 'Düzgün cavab: B) კომპიუტერული ტექნიკის, ქსელური ინფრასტრუქტურისა და მულტიმედიური მოწყობილობების ტ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('15a61218-bb5a-4e77-a61b-c9378deff2cf', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Sanitar-gigiyenik normalara (SanPiN) əsasən, məktəb informatika laboratoriyasında havanın optimal temperaturu və nisbi rütubəti hansı hədlərdə tənzimlənməlidir?', 'multiple_choice', '["Temperatur 19–21°C, nisbi rütubət 55–62% hədlərində", "Temperatur 16–18°C, nisbi rütubət 50–55% hədlərində", "Temperatur 24–26°C, nisbi rütubət 30–35% hədlərində", "Temperatur 15–17°C, nisbi rütubət 70–80% hədlərində", "Temperatur 22–25°C, nisbi rütubət 40–45% hədlərində"]'::jsonb, 'Temperatur 19–21°C, nisbi rütubət 55–62% hədlərində', 'Düzgün cavab: A) Temperatur 19–21°C, nisbi rütubət 55–62% hədlərində', '', 2, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8fa52104-2264-44cf-92da-681364e0bfbd', '15a61218-bb5a-4e77-a61b-c9378deff2cf', 'ka', 'სანიტარიულ-ჰიგიენური ნორმების (SanPiN) თანახმად, რა ფარგლებში უნდა რეგულირდებოდეს ჰაერის ოპტიმალური ტემპერატურა და ფარდობითი ტენიანობა სასკოლო ინფორმატიკის ლაბორატორიაში?', '["ტემპერატურა 19–21°C, ფარდობითი ტენიანობა 55–62% ფარგლებში, ჰაერის ნაკადის სიჩქარე 0.1–0.2 მ/წმ", "ტემპერატურა 22–24°C, ტენიანობა 40–45%, ხმაური 50 დბ", "ტემპერატურა 18–20°C, ტენიანობა 60–70%, ბუნებრივი ვენტილაცია", "ტემპერატურა 20–22°C, ტენიანობა 50–55%, კონდიციონერის მუდმივი მუშაობა", "ტემპერატურა 17–19°C, ტენიანობა 45–50%, განათება 200 ლუქსი"]'::jsonb, 'ტემპერატურა 19–21°C, ფარდობითი ტენიანობა 55–62% ფარგლებში, ჰაერის ნაკადის სიჩქარე 0.1–0.2 მ/წმ', 'Düzgün cavab: A) ტემპერატურა 19–21°C, ფარდობითი ტენიანობა 55–62% ფარგლებში, ჰაერის ნაკადის სიჩქარ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b178fd06-3efa-405d-a57d-ceea4cf7f775', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Təhsil müəssisələrində sanitar qaydalara əsasən, I–IV sinif şagirdləri üçün kompüter ekranı qarşısında fasiləsiz işləmə müddəti ən çoxu nə qədər müəyyən edilmişdir?', 'multiple_choice', '["Dərsdə fasiləsiz olaraq ən çoxu 25–30 dəqiqə", "Dərsdə fasiləsiz olaraq ən çoxu 10–15 dəqiqə", "Dərsdə fasiləsiz olaraq ən çoxu 35–40 dəqiqə", "Dərsdə fasiləsiz olaraq ən çoxu 20–25 dəqiqə", "Bütün dərs boyu fasiləsiz olaraq 45 dəqiqə"]'::jsonb, 'Dərsdə fasiləsiz olaraq ən çoxu 10–15 dəqiqə', 'Düzgün cavab: B) Dərsdə fasiləsiz olaraq ən çoxu 10–15 dəqiqə', '', 3, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('42352d93-315d-4606-9bea-41a2750200c1', 'b178fd06-3efa-405d-a57d-ceea4cf7f775', 'ka', 'საგანმანათლებლო დაწესებულებების სანიტარიული წესების თანახმად, მაქსიმუმ რამდენი ხნით არის განსაზღვრული I–IV კლასების მოსწავლეებისთვის კომპიუტერის ეკრანთან უწყვეტი მუშაობის ხანგრძლივობა?', '["ყოველ გაკვეთილზე 25–30 წუთი უწყვეტად, სულ 35 წუთი", "ყოველ გაკვეთილზე უწყვეტად არაუმეტეს 10–15 წუთისა, საერთო ჯამში არაუმეტეს 20-25 წუთისა", "ყოველ გაკვეთილზე 20–25 წუთი უწყვეტად, სულ 30 წუთი", "ყოველ გაკვეთილზე 15–20 წუთი უწყვეტად, სულ 25 წუთი", "ყოველ გაკვეთილზე 5–10 წუთი უწყვეტად, სულ 15 წუთი"]'::jsonb, 'ყოველ გაკვეთილზე უწყვეტად არაუმეტეს 10–15 წუთისა, საერთო ჯამში არაუმეტეს 20-25 წუთისა', 'Düzgün cavab: B) ყოველ გაკვეთილზე უწყვეტად არაუმეტეს 10–15 წუთისა, საერთო ჯამში არაუმეტეს 20-25 წ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ca9b2b80-11c1-4fd0-ac2d-44b6b9553f99', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İnformatika kabinetində şagirdin iş yerinin erqonomik təşkili zamanı monitor ilə gözlər arasındakı optimal məsafə nə qədər olmalıdır?', 'multiple_choice', '["25–35 sm məsafədə (ekran tam göz bərabərində)", "50–70 sm məsafədə (baxış xətti ekranın mərkəzinə və ya bir qədər aşağı yönəlməklə)", "30–40 sm məsafədə (ekran göz səviyyəsindən yuxarıda)", "15–25 sm məsafədə (ekran klaviaturanın üstündə)", "80–100 sm məsafədə (ekran masanın ən kənarında)"]'::jsonb, '50–70 sm məsafədə (baxış xətti ekranın mərkəzinə və ya bir qədər aşağı yönəlməklə)', 'Düzgün cavab: B) 50–70 sm məsafədə (baxış xətti ekranın mərkəzinə və ya bir qədər aşağı yönəlməkl', '', 4, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6e42ab7e-2dba-4961-83de-80ff99c3859e', 'ca9b2b80-11c1-4fd0-ac2d-44b6b9553f99', 'ka', 'ინფორმატიკის კაბინეტში მოსწავლის სამუშაო ადგილის სწორად ორგანიზებისას, როგორი უნდა იყოს მანძილი თვალსა და მონიტორს შორის და განთავსების კუთხე?', '["მანძილი უნდა იყოს 40–50 სმ და მზერა მიმართული ეკრანის ქვედა კიდისკენ", "მანძილი უნდა იყოს 50–70 სმ და მზერის ხაზი მიმართული მონიტორის ცენტრის პერპენდიკულარულად ან ოდნავ ზემოდან ქვემოთ (10-20 გრადუსით)", "მანძილი უნდა იყოს 45–60 სმ და ეკრანი უნდა იყოს ვერტიკალურად 90 გრადუსით", "მანძილი უნდა იყოს 70–90 სმ და მონიტორი ფანჯრის სინათლის პარალელურად უნდა განთავსდეს", "მანძილი უნდა იყოს 60–80 სმ და ეკრანი თვალის დონიდან 30 გრადუსით მაღლა"]'::jsonb, 'მანძილი უნდა იყოს 50–70 სმ და მზერის ხაზი მიმართული მონიტორის ცენტრის პერპენდიკულარულად ან ოდნავ ზემოდან ქვემოთ (10-20 გრადუსით)', 'Düzgün cavab: B) მანძილი უნდა იყოს 50–70 სმ და მზერის ხაზი მიმართული მონიტორის ცენტრის პერპენდიკუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('70822621-46ce-49bf-81d9-cb42d1747bea', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İnformatika dərslərində şagirdlərdə görmə yorğunluğunu və boyun-əzələ gərginliyini aradan qaldırmaq üçün hansı profilaktik tədbir icra olunmalıdır?', 'multiple_choice', '["Hər 5 dəqiqədən bir şagirdlərin oturduğu kompüter masasını dəyişdirmək", "Otağın ümumi işıqlarını tam söndürərək yalnız monitor işığında dərs keçmək", "Monitorun parlaqlığını maksimuma çatdıraraq kontrastı minimuma endirmək", "Dərs zamanı xüsusi göz gimnastikası, boyun və bilək üçün qısa fiziki fasilələr (fizkultdəqiqələr) tətbiq etmək", "Dərs boyu şagirdlərin ekrana baxma bucağını fasiləsiz 90 dərəcədə məcburi saxlamaq"]'::jsonb, 'Dərs zamanı xüsusi göz gimnastikası, boyun və bilək üçün qısa fiziki fasilələr (fizkultdəqiqələr) tətbiq etmək', 'Düzgün cavab: D) Dərs zamanı xüsusi göz gimnastikası, boyun və bilək üçün qısa fiziki fasilələr (', '', 5, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b77db608-64f4-4fc6-bc48-b1c08358bd23', '70822621-46ce-49bf-81d9-cb42d1747bea', 'ka', 'ინფორმატიკის გაკვეთილებზე მოსწავლეებში მხედველობითი გადაღლისა და კისერ-კუნთოვანი დაძაბულობის მოსახსნელად რა პროფილაქტიკური ღონისძიება უნდა გატარდეს?', '["ოთახში განათების სრულად გამორთვა და მხოლოდ მონიტორის შუქზე მუშაობა", "ყოველ 5 წუთში მოსწავლეთა ადგილების გადანაცვლება", "მოსწავლეებისთვის სათვალის ტარების დავალდებულება და ეკრანის ფილტრის მოხსნა", "გაკვეთილის დროს შესვენებებსა და პაუზებში სპეციალური თვალის ვარჯიშების, კისრისა და მაჯის ფიზიკური პაუზების (ფიზკულტპაუზა) ჩატარება", "მონიტორის სიკაშკაშის 100%-მდე გაზრდა და კონტრასტის შემცირება"]'::jsonb, 'გაკვეთილის დროს შესვენებებსა და პაუზებში სპეციალური თვალის ვარჯიშების, კისრისა და მაჯის ფიზიკური პაუზების (ფიზკულტპაუზა) ჩატარება', 'Düzgün cavab: D) გაკვეთილის დროს შესვენებებსა და პაუზებში სპეციალური თვალის ვარჯიშების, კისრისა დ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7aeb1374-9ded-4ddb-b5d0-a1330586e987', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İnformatika kabinetində kompüter avadanlıqlarının elektrik təhlükəsizliyini təmin etmək üçün hansı qoruyucu sistemin mövcudluğu məcburidir?', 'multiple_choice', '["Elektrik xətlərinin açıq taxta kanallarla döşəmə üzərindən çəkilməsi", "Yalnız yüksək tezlikli rezonans gücləndirici filtr sisteminin qurulması", "Bütün kompüterlərin yalnız neytral sıfır xəttinə ardıcıl birləşdirilməsi", "Laboratoriyanın yalnız fərdi generatorla qidalandırılaraq torpaqlanmaması", "Qoruyucu torpaqlama xətti, avtomat qoruyucu açarlar və qoruyucu açma qurğusu (RCD / UZO)"]'::jsonb, 'Qoruyucu torpaqlama xətti, avtomat qoruyucu açarlar və qoruyucu açma qurğusu (RCD / UZO)', 'Düzgün cavab: E) Qoruyucu torpaqlama xətti, avtomat qoruyucu açarlar və qoruyucu açma qurğusu (RC', '', 6, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a7dbe353-160d-40f4-bcb7-8a37d56ffd0e', '7aeb1374-9ded-4ddb-b5d0-a1330586e987', 'ka', 'ინფორმატიკის კაბინეტში კომპიუტერების ელექტროუსაფრთხოების უზრუნველსაყოფად რომელი ძირითადი დამცავი სისტემის არსებობაა სავალდებულო?', '["ყველა კომპიუტერის თანმიმდევრული შეერთება საერთო ნულოვან გამტართან", "ელექტროგაყვანილობის გაყვანა მხოლოდ ხის ტიხრების შიგნით", "მხოლოდ გარე პლასტმასის იზოლაციის მქონე ტრანსფორმატორული სისტემა", "მხოლოდ სარეზერვო აკუმულატორული ბატარეების დამონტაჟება", "სტანდარტების შესაბამისი დამცავი დამიწების კონტური, დამცავი ავტომატური ამომრთველები, დიფერენციალური დაცვის მოწყობილობა (RCD / UZO) და ძაბვის სტაბილიზატორი"]'::jsonb, 'სტანდარტების შესაბამისი დამცავი დამიწების კონტური, დამცავი ავტომატური ამომრთველები, დიფერენციალური დაცვის მოწყობილობა (RCD / UZO) და ძაბვის სტაბილიზატორი', 'Düzgün cavab: E) სტანდარტების შესაბამისი დამცავი დამიწების კონტური, დამცავი ავტომატური ამომრთველე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('25b45e78-0190-40a7-bc9a-260cd0cce4ce', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İnformatika laboratoriyasında elektrik naqillərinin və şəbəkə kabellərinin istismarı zamanı hansı hal təhlükəsizlik qaydalarının pozulması sayılır?', 'multiple_choice', '["Elektrik xətlərinin yanmayan xüsusi kabel-kanallarla (plintus) divar boyu çəkilməsi", "Şagirdlərin hərəkət etdiyi keçid zonasında naqillərin döşəmə üzərində açıq, qorunmayan və sərbəst atılması", "Şəbəkə kommutatorunun ventilyasiyalı xüsusi telekommunikasiya şkafına yerləşdirilməsi", "Mərkəzi elektrik lövhəsində saz avtomat açarların quraşdırılması", "Hər işçi masa üçün standartlara uyğun torpaqlanmış rozetkaların quraşdırılması"]'::jsonb, 'Şagirdlərin hərəkət etdiyi keçid zonasında naqillərin döşəmə üzərində açıq, qorunmayan və sərbəst atılması', 'Düzgün cavab: B) Şagirdlərin hərəkət etdiyi keçid zonasında naqillərin döşəmə üzərində açıq, qoru', '', 7, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e5f3da52-ef5b-4d2d-ab58-c6ebf80f5742', '25b45e78-0190-40a7-bc9a-260cd0cce4ce', 'ka', 'ინფორმატიკის ლაბორატორიაში ელექტრო და ქსელური კაბელების გაყვანისას რომელი შემთხვევა ითვლება უსაფრთხოების წესების დარღვევად?', '["ელექტროფარში ავტომატური დამცველების გამართულ მდგომარეობაში შენარჩუნება", "მოსწავლეთა გადაადგილების გასასვლელ ზონებში, იატაკზე სადენების ღიად, დაუცველად, თავისუფლად და არეულად დაყრა", "თითოეული მაგიდისთვის დამიწებული როზეტების დამონტაჟება", "კაბელების გაყვანა კედლის გასწვრივ დახურული, ცეცხლგამძლე საკაბელო არხებით (კაბელ-არხებით)", "ქსელური კომუტატორის განთავსება სპეციალურ დახურულ მეტალის კარადაში"]'::jsonb, 'მოსწავლეთა გადაადგილების გასასვლელ ზონებში, იატაკზე სადენების ღიად, დაუცველად, თავისუფლად და არეულად დაყრა', 'Düzgün cavab: B) მოსწავლეთა გადაადგილების გასასვლელ ზონებში, იატაკზე სადენების ღიად, დაუცველად, თ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f8b32043-961a-4101-b0bf-cfb7a2fc2c43', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Elektrik gərginliyi altında olan kompüter avadanlığında yanğın baş verdikdə hansı söndürmə vasitəsindən istifadə **QƏTİ QADAĞANDIR**?', 'multiple_choice', '["Quru kvars qumundan və ya yanmayan asbest örtükdən istifadə etmək", "Gərginliyi ümumi açarla kəsdikdən sonra yanğın təhlükəsizlik qaydalarına uyğun müdaxilə etmək", "Gərginlik kəsilmədən su və ya kimyəvi köpüklü odsöndürən vasitələrdən istifadə etmək", "Quru toz tərkibli (OP) odsöndürücü balonlardan istifadə etmək", "Karbon qazlı (CO2) odsöndürücü balonlardan istifadə etmək"]'::jsonb, 'Gərginlik kəsilmədən su və ya kimyəvi köpüklü odsöndürən vasitələrdən istifadə etmək', 'Düzgün cavab: C) Gərginlik kəsilmədən su və ya kimyəvi köpüklü odsöndürən vasitələrdən istifadə e', '', 8, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('da6d0282-571f-4879-898f-2fe3c5197794', 'f8b32043-961a-4101-b0bf-cfb7a2fc2c43', 'ka', 'ელექტრული ძაბვის ქვეშ მყოფ კომპიუტერულ მოწყობილობაზე ხანძრის გაჩენისას, რომელი ხანძარსაწინააღმდეგო საშუალების გამოყენებაა კატეგორიულად აკრძალული?', '["მშრალი კვარცის ქვიშისა და ხანძარსაწინააღმდეგო ტილოს გამოყენება", "მშრალი ფხვნილოვანი ტიპის (OP) ცეცხლმაქრების გამოყენება", "წყლის ან ქიმიური ქაფის, წყალზე დაფუძნებული ცეცხლმაქრი საშუალებების გამოყენება ელექტროქსელიდან გათიშვის გარეშე", "ნახშირორჟანგოვანი ტიპის (OU / CO2) ცეცხლმაქრების გამოყენება", "ცეცხლგამძლე აზბესტის ან ქეჩის გადასაფარებლების გამოყენება"]'::jsonb, 'წყლის ან ქიმიური ქაფის, წყალზე დაფუძნებული ცეცხლმაქრი საშუალებების გამოყენება ელექტროქსელიდან გათიშვის გარეშე', 'Düzgün cavab: C) წყლის ან ქიმიური ქაფის, წყალზე დაფუძნებული ცეცხლმაქრი საშუალებების გამოყენება ელ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bcc7c1ea-2481-4310-8543-99f45489814b', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İnformatika kabinetində insanı elektrik cərəyanı vurduqda görülməli olan ilk təxirəsalınmaz tədbir nədir?', 'multiple_choice', '["Kompüteri yenidən işə salaraq gərginlik sıçrayışını yoxlamaq", "Zərərçəkənə dərhal soyuq su içirtmək və ayağa qaldırmaq", "Çılpaq əllə zərərçəkənin qolundan tutub onu kənara dartmaq", "Zərərçəkənin ətraflarını bərk masaj edərək hərəkət etdirmək", "Ümumi açarı söndürərək cərəyanı dərhal kəsmək və ya quru dielektrik əşya ilə zərərçəkəni naqildən ayırmaq"]'::jsonb, 'Ümumi açarı söndürərək cərəyanı dərhal kəsmək və ya quru dielektrik əşya ilə zərərçəkəni naqildən ayırmaq', 'Düzgün cavab: E) Ümumi açarı söndürərək cərəyanı dərhal kəsmək və ya quru dielektrik əşya ilə zər', '', 9, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d1320445-64e4-4e83-a49d-1785f7023031', 'bcc7c1ea-2481-4310-8543-99f45489814b', 'ka', 'ინფორმატიკის კაბინეტში ადამიანის ელექტროდენით დაზიანებისას (დენის დარტყმისას) რა არის პირველი გადაუდებელი ღონისძიება?', '["დაზარალებულისთვის ხელში ჩავლება და მისი დაუყოვნებლივ განზე გამოქაჩვა", "დაზარალებულისთვის დაუყოვნებლივ ხელოვნური სუნთქვის ჩატარება და ბევრი სითხის დალევინება", "დაზარალებულის კიდურებზე სასწრაფო დამწოლი ნახვევის დადება", "იმ კომპიუტერის ხელახლა ჩართვა, რომელზეც შემთხვევა მოხდა, და ძაბვის გაზომვა", "დენის გათიშვა საერთო ავტომატური ამომრთველის გამორთვით ან კონტაქტის გაწყვეტა მშრალი დიელექტრიკული (ხის, რეზინის) საგნით, შემდეგ კი პირველადი დახმარების აღმოჩენა"]'::jsonb, 'დენის გათიშვა საერთო ავტომატური ამომრთველის გამორთვით ან კონტაქტის გაწყვეტა მშრალი დიელექტრიკული (ხის, რეზინის) საგნით, შემდეგ კი პირველადი დახმარების აღმოჩენა', 'Düzgün cavab: E) დენის გათიშვა საერთო ავტომატური ამომრთველის გამორთვით ან კონტაქტის გაწყვეტა მშრა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6982d61b-2c53-4be1-887d-8d42c1d121f0', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Şagirdlərin İnformatika kabinetində texniki təhlükəsizlik qaydaları ilə tanış edilməsi hansı rəsmi sənədlə qeydiyyata alınır?', 'multiple_choice', '["Məktəbin kadrlar şöbəsinin əmək kitabçalarında", "Məktəb kitabxanasının dərslik inventarlaşdırma kitabında", "Məktəbin illik təsərrüfat xərcləri aktında", "İnformatika kabinetinin Təhlükəsizlik Texnikası üzrə Təlimatlandırma Jurnalında (şagirdlərin imzası ilə)", "Fənn müəlliminin fərdi gündəlik dərs planlaşdırma qeydlərində"]'::jsonb, 'İnformatika kabinetinin Təhlükəsizlik Texnikası üzrə Təlimatlandırma Jurnalında (şagirdlərin imzası ilə)', 'Düzgün cavab: D) İnformatika kabinetinin Təhlükəsizlik Texnikası üzrə Təlimatlandırma Jurnalında', '', 10, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0d008a2f-bdf5-49bd-8694-478a8af91091', '6982d61b-2c53-4be1-887d-8d42c1d121f0', 'ka', 'ინფორმატიკის კაბინეტში მოსწავლეთა ტექნიკური უსაფრთხოების წესების გაცნობა რომელი ოფიციალური დოკუმენტით ფორმდება?', '["საგნის მასწავლებლის გაკვეთილის ინდივიდუალური დაგეგმვის რვეულში", "წლიური სამეურნეო ხარჯების აქტში", "სასკოლო ბიბლიოთეკის საინვენტარო რეესტრში", "ინფორმატიკის კაბინეტის უსაფრთხოების ტექნიკის ინსტრუქტაჟის ჟურნალში, მოსწავლეთა ხელმოწერით", "მოსწავლეთა შეფასებისა და დასწრების ჟურნალში"]'::jsonb, 'ინფორმატიკის კაბინეტის უსაფრთხოების ტექნიკის ინსტრუქტაჟის ჟურნალში, მოსწავლეთა ხელმოწერით', 'Düzgün cavab: D) ინფორმატიკის კაბინეტის უსაფრთხოების ტექნიკის ინსტრუქტაჟის ჟურნალში, მოსწავლეთა ხ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5cec33a9-e76d-4b41-bf5d-bdb896c4a438', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Kompüterin ana platasında yerləşən, bütün hesab-məntiq və idarəetmə əməliyyatlarını icra edən əsas mikrosxem necə adlanır?', 'multiple_choice', '["Audio kontroller mikrosxemi", "Şimal körpüsü çipseti (Northbridge)", "Mərkəzi Prosessor (CPU)", "Baza daxiletmə-xaricetmə mikrosxemi (BIOS)", "Şəbəkə kontrolleri (NIC)"]'::jsonb, 'Mərkəzi Prosessor (CPU)', 'Düzgün cavab: C) Mərkəzi Prosessor (CPU)', '', 11, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('12598817-0e19-4df4-9eb4-427cb925ed1a', '5cec33a9-e76d-4b41-bf5d-bdb896c4a438', 'ka', 'რა ეწოდება დედაპლატაზე განთავსებულ ძირითად მიკროსქემას, რომელიც ასრულებს ყველა მათემატიკურ და ლოგიკურ ოპერაციას?', '["ჩრდილოეთ ხიდის ჩიპსეტი (Northbridge)", "ოპერატიული მეხსიერების კონტროლერი (RAM Controller)", "ცენტრალური პროცესორი (CPU - Central Processing Unit)", "შეტანა-გამოტანის საბაზისო სისტემის მიკროსქემა (BIOS)", "გრაფიკული პროცესორი (GPU) - ვიდეობარათის ბირთვი"]'::jsonb, 'ცენტრალური პროცესორი (CPU - Central Processing Unit)', 'Düzgün cavab: C) ცენტრალური პროცესორი (CPU - Central Processing Unit)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7c3c15b7-7d99-4429-9abe-27c6ad8ec087', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Əməliyyat sisteminin və cari icra olunan proqramların məlumatlarının emal zamanı saxlandığı enerji-asılı müvəqqəti yaddaş hansıdır?', 'multiple_choice', '["Operativ Yaddaş Qurğusu (RAM)", "Daimi Yaddaş Qurğusu (ROM)", "Xarici sərt maqnit diski (External HDD)", "Fləş kart yaddaşı (USB Flash Drive)", "Optik disk qurğusu (DVD-RW)"]'::jsonb, 'Operativ Yaddaş Qurğusu (RAM)', 'Düzgün cavab: A) Operativ Yaddaş Qurğusu (RAM)', '', 12, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f4cc5f61-e3fa-4e3b-85b1-1ad346a32a70', '7c3c15b7-7d99-4429-9abe-27c6ad8ec087', 'ka', 'რომელია ენერგოდამოკიდებული მეხსიერება, სადაც ოპერაციული სისტემისა და მიმდინარე მომუშავე პროგრამების მონაცემები დამუშავების დროს დროებით ინახება?', '["ოპერატიული მეხსიერების მოწყობილობა (RAM - Random Access Memory)", "ქეშ-მეხსიერება (Cache L1/L2/L3) - პროცესორის შიგნით", "ვიდეო მეხსიერება (VRAM) - გრაფიკული ბარათის მეხსიერება", "მუდმივი მეხსიერების მოწყობილობა (ROM) - BIOS-ის მეხსიერება", "მყარი დისკის ბუფერული მეხსიერება"]'::jsonb, 'ოპერატიული მეხსიერების მოწყობილობა (RAM - Random Access Memory)', 'Düzgün cavab: A) ოპერატიული მეხსიერების მოწყობილობა (RAM - Random Access Memory)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('dc4054ab-6247-44c9-b82a-999a096b73d8', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Məlumatların saxlanmasında bərkcisimli SSD disklərinin ənənəvi maqnit HDD disklərindən əsas texnoloji üstünlüyü nədən ibarətdir?', 'multiple_choice', '["Məlumatların yalnız analoq maqnit lentləri üzərində kodlaşdırılması", "İşləmək üçün elektrik enerjisinə heç bir ehtiyac duymaması", "NAND fləş mikrosxemləri əsasında işləyərək daha yüksək oxuma/yazma sürəti, səssiz iş prinsipi və zərbəyə dözümlülük təmin etməsi", "Yalnız internet bağlantısı aktiv olduqda məlumatları yaddaşda saxlaması", "İçərisində fırlanan maqnit disklərin və mexaniki başlıqların daha sürətlə hərəkət etməsi"]'::jsonb, 'NAND fləş mikrosxemləri əsasında işləyərək daha yüksək oxuma/yazma sürəti, səssiz iş prinsipi və zərbəyə dözümlülük təmin etməsi', 'Düzgün cavab: C) NAND fləş mikrosxemləri əsasında işləyərək daha yüksək oxuma/yazma sürəti, səssi', '', 13, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f0412778-530a-4e78-ad49-b6b55f2a1865', 'dc4054ab-6247-44c9-b82a-999a096b73d8', 'ka', 'მონაცემთა შენახვაში რა არის SSD დისკების ძირითადი ტექნოლოგიური განსხვავება და უპირატესობა HDD დისკებთან შედარებით?', '["SSD დისკები მუშაობს ელექტროენერგიის მოხმარების გარეშე", "SSD დისკები განკუთვნილია მხოლოდ აუდიო-ვიდეო არქივისთვის", "SSD დისკები მუშაობს NAND ფლეშ-მეხსიერების საფუძველზე, რაც უზრუნველყოფს ჩაწერის/წაკითხვის უფრო მაღალ სიჩქარეს, უხმაურო მუშაობასა და დარტყმისადმი გამძლეობას", "SSD დისკები ინახავს მონაცემებს მხოლოდ მაშინ, როცა ინტერნეტი აქტიურია", "SSD დისკებში მონაცემები იწერება მაგნიტურ დისკებზე მექანიკური თავაკებით"]'::jsonb, 'SSD დისკები მუშაობს NAND ფლეშ-მეხსიერების საფუძველზე, რაც უზრუნველყოფს ჩაწერის/წაკითხვის უფრო მაღალ სიჩქარეს, უხმაურო მუშაობასა და დარტყმისადმი გამძლეობას', 'Düzgün cavab: C) SSD დისკები მუშაობს NAND ფლეშ-მეხსიერების საფუძველზე, რაც უზრუნველყოფს ჩაწერის/წ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('00bc0379-de64-4b7c-b4ec-d7910d0ec3a8', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Elektrik şəbəkəsində qəfil gərginlik kəsilməsi və ya sıçrayışları zamanı kompüterlərin müvəqqəti avtonom qidalanmasını təmin edən qurğu hansıdır?', 'multiple_choice', '["Fasiləsiz Qida Mənbəyi (UPS / İBP)", "Gərginlik dəyişdirici transformator bloku", "Soyuducu kuler radiator sistemi", "Yüksək tezlikli şəbəkə filtri (Surge protector)", "Dizel yanacaqlı avtomat generator stansiyası"]'::jsonb, 'Fasiləsiz Qida Mənbəyi (UPS / İBP)', 'Düzgün cavab: A) Fasiləsiz Qida Mənbəyi (UPS / İBP)', '', 14, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1a974aea-4e44-4d47-9503-7a2d4828752e', '00bc0379-de64-4b7c-b4ec-d7910d0ec3a8', 'ka', 'რომელი მოწყობილობა უზრუნველყოფს კომპიუტერების დროებით ავტონომიურ კვებას ელექტროქსელში ძაბვის მოულოდნელი რყევებისა და გათიშვის დროს?', '["უწყვეტი კვების წყარო (UPS / უპს - Uninterruptible Power Supply)", "ტრანსფორმატორის ბლოკი - ცვლის ძაბვას", "გენერატორი - იძლევა ხანგრძლივ ენერგიას", "ძაბვის სტაბილიზატორი (AVR) - მხოლოდ არეგულირებს ძაბვას", "ქსელური ფილტრი (Surge Protector) - მხოლოდ იცავს"]'::jsonb, 'უწყვეტი კვების წყარო (UPS / უპს - Uninterruptible Power Supply)', 'Düzgün cavab: A) უწყვეტი კვების წყარო (UPS / უპს - Uninterruptible Power Supply)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('df2c3d6a-4c3f-41fc-b5ad-cc57fbe4627d', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Prosessorun kristalı ilə soyuducu radiator arasındakı mikroskopik hava boşluqlarını dolduraraq effektiv istilikötürməni təmin edən maddə hansıdır?', 'multiple_choice', '["Qrafit əsaslı bərkidici lak", "Spirtli təmizləyici həlledici məhlul", "Silikon dielektrik sürtkü yağı", "Epoksid qatranı yapışqanı", "Termointerfeys pastası (Termopasta)"]'::jsonb, 'Termointerfeys pastası (Termopasta)', 'Düzgün cavab: E) Termointerfeys pastası (Termopasta)', '', 15, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('719fa505-13cf-4acd-859a-c4ce1a1b0292', 'df2c3d6a-4c3f-41fc-b5ad-cc57fbe4627d', 'ka', 'რა სპეციალური ნივთიერება გამოიყენება პროცესორის კრისტალსა და გამაგრილებელ რადიატორს შორის ჰაერის სიცარიელის აღმოსაფხვრელად და სითბოს უკეთ გადასაცემად?', '["სილიკონის დიელექტრიკული ზეთი - იზოლაციისთვის", "ეპოქსიდური ფისი - რადიატორის დასაწებებლად", "გრაფიტის შემცველი წებო - დასამაგრებლად", "თხევადი ლითონის სარჩილავი - მხოლოდ ექსტრემალური გაგრილებისთვის", "თერმოინტერფეისის პასტა (თერმოპასტა / Thermal Paste / MX-4)"]'::jsonb, 'თერმოინტერფეისის პასტა (თერმოპასტა / Thermal Paste / MX-4)', 'Düzgün cavab: E) თერმოინტერფეისის პასტა (თერმოპასტა / Thermal Paste / MX-4)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('af2712fb-81c4-4b43-8fcf-dbf87a8dad7c', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Kompüter işə salınarkən POST (Power-On Self-Test) mərhələsində ana platadan 1 uzun və 2 qısa səs siqnalının verilməsi hansı aparat nasazlığını göstərir?', 'multiple_choice', '["Monitorun enerji düyməsinin söndürüldüyünü", "Klaviaturanın USB portuna qoşulmadığını", "Sərt diskin (HDD/SSD) kabelinin qopduğunu", "Videokartın (qrafik adapterin) nasazlığını və ya yuvaya düzgün oturmadığını", "Mərkəzi prosessorun kulerinin həddindən artıq sürətlə fırlandığını"]'::jsonb, 'Videokartın (qrafik adapterin) nasazlığını və ya yuvaya düzgün oturmadığını', 'Düzgün cavab: D) Videokartın (qrafik adapterin) nasazlığını və ya yuvaya düzgün oturmadığını', '', 16, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c12690fa-11ce-48ea-8435-8ebcfc034d06', 'af2712fb-81c4-4b43-8fcf-dbf87a8dad7c', 'ka', 'კომპიუტერის ჩართვისას POST ეტაპზე 1 გრძელი და 2 მოკლე სიგნალის (ბიპის) გაჟღერება ყველაზე ხშირად რომელ შეცდომაზე მიუთითებს?', '["მყარი დისკი (HDD/SSD) არ არის მიერთებული", "ოპერატიული მეხსიერების (RAM) გაუმართაობაზე ან კონტაქტის პრობლემაზე", "კლავიატურა არ არის შეერთებული ან გაჭედილია", "ვიდეობარათის (გრაფიკული ადაპტერის) გაუმართაობაზე, სლოტში არასწორ ჩაჯდომაზე ან დამატებითი კვების კაბელის შეუერთებლობაზე", "ოპერაციული სისტემის ჩამტვირთავი ფაილების დაზიანებაზე"]'::jsonb, 'ვიდეობარათის (გრაფიკული ადაპტერის) გაუმართაობაზე, სლოტში არასწორ ჩაჯდომაზე ან დამატებითი კვების კაბელის შეუერთებლობაზე', 'Düzgün cavab: D) ვიდეობარათის (გრაფიკული ადაპტერის) გაუმართაობაზე, სლოტში არასწორ ჩაჯდომაზე ან და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8ef14776-f60b-4966-b771-aab8e47b5152', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Monitoru, televizoru və ya proyektoru kompüterə həm yüksək keyfiyyətli rəqəmsal video, həm də çoxkanallı audio siqnal ötürməklə qoşan interfeys hansıdır?', 'multiple_choice', '["VGA (D-Sub) interfeysi", "RJ-45 şəbəkə konnektoru", "PS/2 interfeysi", "DVI-D interfeysi", "HDMI və ya DisplayPort interfeysi"]'::jsonb, 'HDMI və ya DisplayPort interfeysi', 'Düzgün cavab: E) HDMI və ya DisplayPort interfeysi', '', 17, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0efe2fed-633a-4e76-9e50-4181b83a36a9', '8ef14776-f60b-4966-b771-aab8e47b5152', 'ka', 'რომელი ინტერფეისი აერთებს მონიტორს ან პროექტორს კომპიუტერთან როგორც ციფრული ვიდეო, ისე მრავალარხიანი აუდიო სიგნალების გადაცემით?', '["VGA (D-Sub) - გადასცემს მხოლოდ ანალოგურ ვიდეოს", "RJ-45 - გადასცემს მხოლოდ ქსელურ სიგნალს", "USB 2.0 - გადასცემს მხოლოდ მონაცემებს", "DVI-D - გადასცემს მხოლოდ ციფრულ ვიდეოს", "HDMI (High-Definition Multimedia Interface) ან DisplayPort ინტერფეისი"]'::jsonb, 'HDMI (High-Definition Multimedia Interface) ან DisplayPort ინტერფეისი', 'Düzgün cavab: E) HDMI (High-Definition Multimedia Interface) ან DisplayPort ინტერფეისი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9a27a61e-4627-4c84-911b-f558f8dd2f8b', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Sistem blokunun daxili komponentlərini toz və çirklənmədən təmizləyərkən laborant hansı ən təhlükəsiz vasitədən istifadə etməlidir?', 'multiple_choice', '["Yüksək hərarətli sənaye lehim feni", "Spirtli nəm əsgi və yuyucu toz məhlulu", "Metal simli kobud fırça və zımpara kağızı", "Məişət tozsoranının maye sorma rejimi", "Sıxılmış quru hava balonu, pnevmatik üfürücü və antistatik fırça"]'::jsonb, 'Sıxılmış quru hava balonu, pnevmatik üfürücü və antistatik fırça', 'Düzgün cavab: E) Sıxılmış quru hava balonu, pnevmatik üfürücü və antistatik fırça', '', 18, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b5ad1b89-79ad-4029-a1ab-3f6aaed8cd0c', '9a27a61e-4627-4c84-911b-f558f8dd2f8b', 'ka', 'სისტემური ბლოკის შიდა კომპონენტების მტვრისა და დაბინძურებისგან გაწმენდისას რომელი ყველაზე უსაფრთხო საშუალება უნდა გამოიყენოს ლაბორანტმა?', '["ლითონის წვერიანი ჯაგრისი და ზუმფარის ქაღალდი", "საყოფაცხოვრებო მტვერსასრუტი სველი შეწოვის ფუნქციით", "სპირტში დასველებული ნაჭერი და სარეცხი საშუალება", "ცხელი ჰაერის სამრეწველო ფენი მაქსიმალურ რეჟიმზე", "შეკუმშული მშრალი ჰაერის ბალონი, სპეციალური პნევმატური შემბერი, ანტისტატიკური ჯაგრისი და ESD ანტისტატიკური სამაჯური"]'::jsonb, 'შეკუმშული მშრალი ჰაერის ბალონი, სპეციალური პნევმატური შემბერი, ანტისტატიკური ჯაგრისი და ESD ანტისტატიკური სამაჯური', 'Düzgün cavab: E) შეკუმშული მშრალი ჰაერის ბალონი, სპეციალური პნევმატური შემბერი, ანტისტატიკური ჯაგ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('709681eb-889b-4a0a-9b5d-50bf60a18a57', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Kompüterə yeni əməliyyat sistemi quraşdırılarkən ilkin yükləmə qurğusunun (Boot Device / Priority) təyin edilməsi hansı menyudan tənzimlənir?', 'multiple_choice', '["Aygıtlar Yöneticisinin drayver yeniləmə pəncərəsindən", "BIOS / UEFI menyusundan", "Windows Bələdçisinin görünüş panelindən", "Windows Qovluq Parametrlərindən (Folder Options)", "Tapşırıqlar Menecerinin Performans bölməsindən"]'::jsonb, 'BIOS / UEFI menyusundan', 'Düzgün cavab: B) BIOS / UEFI menyusundan', '', 19, true, false, true, 1.0, 'exact', true, false, NOW());
