INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4cb05b38-baa7-44a6-9cb5-75c25d6895c4', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Əməliyyat sisteminin kompüterin aparat qurğuları (videokart, printer, şəbəkə kartı) ilə qarşılıqlı əlaqəsini təmin edən xüsusi proqram təminatı necə adlanır?', 'multiple_choice', '["Antivirus utiliti", "Drayver (Device Driver)", "Translyator proqramı", "Arxivator proqramı", "Multimedia pleyeri"]'::jsonb, 'Drayver (Device Driver)', 'Düzgün cavab: B) Drayver (Device Driver)', '', 20, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1ab84046-37d6-408d-a2b5-0ea60188e359', '4cb05b38-baa7-44a6-9cb5-75c25d6895c4', 'ka', 'რა ეწოდება სისტემურ პროგრამულ უზრუნველყოფას, რომელიც უზრუნველყოფს ოპერაციული სისტემის კავშირს აპარატურულ მოწყობილობებთან?', '["Firmware - აპარატურის მუდმივი ჩაშენებული პროგრამა", "დრაივერი (Device Driver) - მოწყობილობის მწარმოებლის მიერ მოწოდებული პროგრამული უზრუნველყოფა", "Middleware - შუალედური დონის პროგრამა", "უტილიტა - მომსახურე პროგრამები", "კოდეკების პაკეტი - მულტიმედიისთვის"]'::jsonb, 'დრაივერი (Device Driver) - მოწყობილობის მწარმოებლის მიერ მოწოდებული პროგრამული უზრუნველყოფა', 'Düzgün cavab: B) დრაივერი (Device Driver) - მოწყობილობის მწარმოებლის მიერ მოწოდებული პროგრამული უ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fe281bc6-2cb6-4b24-9933-2fbad3476a40', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Laboratoriyadakı eyni parametrlərə malik çoxsaylı kompüterlərə əməliyyat sistemini və proqram paketlərini ən sürətli şəkildə quraşdırmaq üçün hansı metod tətbiq olunur?', 'multiple_choice', '["İlkin sazlanmış etalon sistemin obrazını (Disk Image / Klonlama) yaradaraq şəbəkə və ya USB vasitəsilə digər kompüterlərə köçürmək", "Bütün kompüterlərin sərt disklərini hər dərsdən əvvəl bir-biri ilə fiziki dəyişmək", "Hər bir kompüterə əməliyyat sistemini və proqramları diskdən növbə ilə əl ilə sıfırdan yazmaq", "Kompüterləri format edərək heç bir proqram təminatı yazmadan tədrisə buraxmaq", "Proqramları mətn redaktorunda skript kimi açıb hər kompüterdə əllə yığmaq"]'::jsonb, 'İlkin sazlanmış etalon sistemin obrazını (Disk Image / Klonlama) yaradaraq şəbəkə və ya USB vasitəsilə digər kompüterlərə köçürmək', 'Düzgün cavab: A) İlkin sazlanmış etalon sistemin obrazını (Disk Image / Klonlama) yaradaraq şəbək', '', 21, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('69c6102b-d4fe-406a-885c-2c175f430a85', 'fe281bc6-2cb6-4b24-9933-2fbad3476a40', 'ka', 'რა არის ყველაზე ოპტიმალური მეთოდი ლაბორატორიაში იდენტური კონფიგურაციის კომპიუტერებზე ოპერაციული სისტემის სწრაფად დასაყენებლად?', '["წინასწარ გამართული ეტალონური სისტემის ასლის/იმიჯის (Disk Image / კლონირება - Acronis, Clonezilla) შექმნა და PXE-ით ან USB-ით სხვა კომპიუტერებზე გადატანა", "პროგრამების ხელით შეყვანა ტექსტურ რედაქტორში სკრიპტის სახით", "ყველა კომპიუტერის დაფორმატება და პროგრამების გარეშე დატოვება", "თითოეულ კომპიუტერზე პროგრამების დისკიდან ცალ-ცალკე ინსტალაცია", "მყარი დისკების ფიზიკური შეცვლა"]'::jsonb, 'წინასწარ გამართული ეტალონური სისტემის ასლის/იმიჯის (Disk Image / კლონირება - Acronis, Clonezilla) შექმნა და PXE-ით ან USB-ით სხვა კომპიუტერებზე გადატანა', 'Düzgün cavab: A) წინასწარ გამართული ეტალონური სისტემის ასლის/იმიჯის (Disk Image / კლონირება - Acr', NOW(), NOW());
