INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('daacfca0-ed3d-4094-9614-60f35acef901', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Windows əməliyyat sistemində cavab verməyən (donmuş) tətbiqi və ya prosesi məcburi dayandırmaq üçün hansı sistem alətindən istifadə edilir?', 'multiple_choice', '["System Restore (Sistemi bərpa aləti)", "Disk Cleanup (Diskin təmizlənməsi utiliti)", "Task Manager (Tapşırıqlar Meneceri) və ya Taskkill əmri", "Disk Defragmenter (Diskin optimallaşdırılması)", "Windows Memory Diagnostic (Yaddaş diaqnostikası)"]'::jsonb, 'Task Manager (Tapşırıqlar Meneceri) və ya Taskkill əmri', 'Düzgün cavab: C) Task Manager (Tapşırıqlar Meneceri) və ya Taskkill əmri', '', 23, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b824d3e5-91a0-41d8-834c-0a8a49cbb919', 'daacfca0-ed3d-4094-9614-60f35acef901', 'ka', 'Windows-ში გაჭედილი (პასუხგაუცემელი) პროგრამული პროცესის იძულებით შესაჩერებლად რომელი ხელსაწყო გამოიყენება?', '["Windows Memory Diagnostic - მეხსიერების დიაგნოსტიკა", "Control Panel - საკონტროლო პანელი", "Task Manager (დავალებათა მენეჯერი - Ctrl+Shift+Esc) ან Taskkill ბრძანება", "Disk Defragmenter - დისკის ოპტიმიზაცია", "System Restore - სისტემის აღდგენის ხელსაწყო"]'::jsonb, 'Task Manager (დავალებათა მენეჯერი - Ctrl+Shift+Esc) ან Taskkill ბრძანება', 'Düzgün cavab: C) Task Manager (დავალებათა მენეჯერი - Ctrl+Shift+Esc) ან Taskkill ბრძანება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('eb3a4287-6a52-48da-822a-b4b40bbe51f2', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İnformatika kabinetində kompüterləri lokal şəbəkəyə simli qoşmaq üçün istifadə olunan kabel növü və konnektor hansıdır?', 'multiple_choice', '["Standart USB kabeli və Type-A konnektoru", "Telefon kabeli və RJ-11 konnektoru", "UTP bükülü cütlük kabeli və RJ-45 konnektoru", "VGA analoq kabeli və D-Sub konnektoru", "Koaksial kabel və BNC konnektoru"]'::jsonb, 'UTP bükülü cütlük kabeli və RJ-45 konnektoru', 'Düzgün cavab: C) UTP bükülü cütlük kabeli və RJ-45 konnektoru', '', 24, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7d0348ea-afe2-4982-951e-5381397017ad', 'eb3a4287-6a52-48da-822a-b4b40bbe51f2', 'ka', 'ინფორმატიკის კაბინეტში კომპიუტერების ლოკალურ ქსელში ჩასართავად რომელი ტიპის კაბელი და კონექტორი გამოიყენება?', '["USB კაბელი და Type-A კონექტორი", "კოაქსიალური კაბელი და BNC კონექტორი", "UTP (გრეხილი წყვილი - Unshielded Twisted Pair) Cat5e/Cat6 კაბელი და RJ-45 კონექტორი", "სატელეფონო კაბელი და RJ-11 კონექტორი", "ოპტიკურ-ბოჭკოვანი კაბელი და SC/LC კონექტორი"]'::jsonb, 'UTP (გრეხილი წყვილი - Unshielded Twisted Pair) Cat5e/Cat6 კაბელი და RJ-45 კონექტორი', 'Düzgün cavab: C) UTP (გრეხილი წყვილი - Unshielded Twisted Pair) Cat5e/Cat6 კაბელი და RJ-45 კონექტ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ec994207-ad03-479b-b51e-8f3fe49ba98a', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Lokal şəbəkəyə qoşulan işçi kompüterlərə dinamik IP ünvanları avtomatik paylayan şəbəkə protokolu hansıdır?', 'multiple_choice', '["DHCP (Dynamic Host Configuration Protocol)", "ARP (Address Resolution Protocol)", "DNS (Domain Name System)", "FTP (File Transfer Protocol)", "HTTP (HyperText Transfer Protocol)"]'::jsonb, 'DHCP (Dynamic Host Configuration Protocol)', 'Düzgün cavab: A) DHCP (Dynamic Host Configuration Protocol)', '', 25, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('01314ac8-e211-444f-9c18-060330120782', 'ec994207-ad03-479b-b51e-8f3fe49ba98a', 'ka', 'რომელი ქსელური ოქმი ახორციელებს ლოკალურ ქსელში ჩართულ სამუშაო სადგურებზე დინამიკური IP მისამართების ავტომატურ განაწილებას?', '["DHCP (Dynamic Host Configuration Protocol) - ჰოსტის დინამიკური კონფიგურაციის ოქმი", "DNS - დომენური სახელების სისტემა", "HTTP - ჰიპერტექსტის გადაცემის ოქმი", "ARP - მისამართის გარკვევის ოქმი", "FTP - ფაილების გადაცემის ოქმი"]'::jsonb, 'DHCP (Dynamic Host Configuration Protocol) - ჰოსტის დინამიკური კონფიგურაციის ოქმი', 'Düzgün cavab: A) DHCP (Dynamic Host Configuration Protocol) - ჰოსტის დინამიკური კონფიგურაციის ოქმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a51ac484-b3b1-4c05-b7ba-8eeb63b347f1', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Məktəb kompüterlərində şagirdlərin zərərli, yaşa uyğun olmayan və qeyri-pedaqoji veb-saytlara daxil olmasının qarşısını almaq üçün hansı sistem tətbiq olunur?', 'multiple_choice', '["Diskin defraqmentasiya proqramları və ekran qoruyucuları", "Veb-məzmun filtri (Content Filtering) və Təhlükəsizlik Divarı (Firewall)", "Ekran klaviaturası və mətn şrift generatorları", "Arxivator proqramları və qrafik drayver paketləri", "Sürətli fayl yükləmə menecerləri və multimedia pleyerləri"]'::jsonb, 'Veb-məzmun filtri (Content Filtering) və Təhlükəsizlik Divarı (Firewall)', 'Düzgün cavab: B) Veb-məzmun filtri (Content Filtering) və Təhlükəsizlik Divarı (Firewall)', '', 26, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cac6c28d-8cd4-4f3a-a5d2-5a912e641c18', 'a51ac484-b3b1-4c05-b7ba-8eeb63b347f1', 'ka', 'სასკოლო კომპიუტერებზე მოსწავლეების მიერ მავნე და არასასწავლო საიტებზე შესვლის თავიდან ასაცილებლად რომელი პროგრამული უზრუნველყოფა გამოიყენება?', '["დისკის დეფრაგმენტაციის უტილიტები და ეკრანმზოგი აპლიკაციები", "ვებ-შინაარსის ფილტრი (Content Filtering / URL Filtering) და ქსელური ეკრანი / ფაიერვოლი (Firewall / Next-Gen Firewall)", "ფაილების სწრაფი ჩამოტვირთვის მენეჯერები და ქეშის გამწმენდი გაფართოებები", "ფაილების საარქივო პროგრამები და მულტიმედიური კოდეკების პაკეტები", "ვირტუალური კლავიატურა და ტექსტის მთარგმნელი ლექსიკონები"]'::jsonb, 'ვებ-შინაარსის ფილტრი (Content Filtering / URL Filtering) და ქსელური ეკრანი / ფაიერვოლი (Firewall / Next-Gen Firewall)', 'Düzgün cavab: B) ვებ-შინაარსის ფილტრი (Content Filtering / URL Filtering) და ქსელური ეკრანი / ფაი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b7a6bdbd-6dbb-480b-905c-9454fc77ba14', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Xarici USB fləş-daşıyıcılardan laboratoriya kompüterlərinə zərərverici virusların yoluxmasının qarşısını almaq üçün ən effektiv profilaktik tədbir hansıdır?', 'multiple_choice', '["Kompüterə qoşulan fləş-kartdakı bütün şəxsi faylları xəbərdarlıq etmədən silmək", "Kompüterləri yalnız internet bağlantısı kəsilmiş rejimdə saxlamaq", "Kompüterin bütün USB portlarını fiziki olaraq sındırıb yararsız hala salmaq", "Hər dərsin sonunda kompüterin əməliyyat sistemini yenidən format etmək", "Mərkəzləşdirilmiş antivirus sistemini aktiv saxlamaq, xarici daşıyıcıların avtomatik işə düşməsini (autorun) deaktiv etmək və qoşulan yaddaşı skan etmək"]'::jsonb, 'Mərkəzləşdirilmiş antivirus sistemini aktiv saxlamaq, xarici daşıyıcıların avtomatik işə düşməsini (autorun) deaktiv etmək və qoşulan yaddaşı skan etmək', 'Düzgün cavab: E) Mərkəzləşdirilmiş antivirus sistemini aktiv saxlamaq, xarici daşıyıcıların avtom', '', 27, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('02b322ba-cef7-4a16-acab-1e39852dcae9', 'b7a6bdbd-6dbb-480b-905c-9454fc77ba14', 'ka', 'მოსწავლეების მიერ მოტანილი გარე USB ფლეშ-ბარათებიდან ლაბორატორიის კომპიუტერებზე მავნე პროგრამების გავრცელების თავიდან ასაცილებლად რა ზომა უნდა მიიღოს ლაბორანტმა?', '["ყველა USB პორტის დედაპლატიდან ფიზიკურად მოჭრა და გამოთიშვა", "ფლეშ-ბარათზე არსებული ყველა ფაილის დაუყოვნებლივ წაშლა შეერთებისთანავე", "კომპიუტერების ექსპლუატაცია მხოლოდ უსაფრთხო რეჟიმში (Safe Mode)", "ოპერაციული სისტემის ხელახალი დაფორმატება ყოველი გაკვეთილის შემდეგ", "ცენტრალიზებული ანტივირუსული (Endpoint Protection) სისტემის აქტიურ მდგომარეობაში შენარჩუნება, autorun-ის გამორთვა და მიერთებული მატარებლების ავტომატური სკანირება"]'::jsonb, 'ცენტრალიზებული ანტივირუსული (Endpoint Protection) სისტემის აქტიურ მდგომარეობაში შენარჩუნება, autorun-ის გამორთვა და მიერთებული მატარებლების ავტომატური სკანირება', 'Düzgün cavab: E) ცენტრალიზებული ანტივირუსული (Endpoint Protection) სისტემის აქტიურ მდგომარეობაში', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fc5df15d-88ac-4cab-a993-6b1807137519', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İnteraktiv elektron lövhədə elektron qələmin (stilusun) toxunduğu nöqtə ilə ekrandakı kursorun tam üst-üstə düşməsini təmin edən sazlama prosesi necə adlanır?', 'multiple_choice', '["Sinxronizasiya", "Formatlaşdırma", "Defragmentasiya", "Virtualizasiya", "Kalibrasiya (Calibration)"]'::jsonb, 'Kalibrasiya (Calibration)', 'Düzgün cavab: E) Kalibrasiya (Calibration)', '', 28, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('63be3c04-7603-4f68-b98c-931bed64f5f1', 'fc5df15d-88ac-4cab-a993-6b1807137519', 'ka', 'რა ეწოდება რეგულირების პროცესს, რომლის დროსაც ინტერაქტიულ ელექტრონულ დაფაზე სტილუსის შეხების ადგილი კურსორის კოორდინატებს ზუსტად ემთხვევა?', '["სინქრონიზაციის პროცესი - მოწყობილობათა შეთანხმება", "ლინეარიზაციის პროცესი - ხაზოვნების რეგულირება", "ვალიდაციის პროცესი - დადასტურება", "ორიენტაციის პროცესი - ეკრანის მობრუნება", "კალიბრაციის (Calibration) პროცესი - 4, 9 ან 16 წერტილის მიხედვით"]'::jsonb, 'კალიბრაციის (Calibration) პროცესი - 4, 9 ან 16 წერტილის მიხედვით', 'Düzgün cavab: E) კალიბრაციის (Calibration) პროცესი - 4, 9 ან 16 წერტილის მიხედვით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a45a983d-d6c6-4625-8b10-d18406647b09', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Multimedia proyektorunun daxili lampasının həddindən artıq qızaraq partlamaması və sıradan çıxmaması üçün düzgün söndürülmə qaydası necədir?', 'multiple_choice', '["Proyektorun hava ventilyasiya dəliklərini sıx parça ilə bağlamaq", "İdarəetmə pultu və ya Power düyməsi ilə söndürüb, daxili soyuducu pər (ventilyator) lampanı tam soyutduqdan sonra elektrik şəbəkəsindən ayırmaq", "Cihazı heç vaxt söndürməyərək aylarla fasiləsiz işlək saxlamaq", "Proyektor işlək vəziyyətdə olarkən elektrik kabelini dərhal divar rozetkasından dartıb çıxarmaq", "İsti linzanı dərhal nəm soyuq dəsmalla bükərək soyumağa qoymaq"]'::jsonb, 'İdarəetmə pultu və ya Power düyməsi ilə söndürüb, daxili soyuducu pər (ventilyator) lampanı tam soyutduqdan sonra elektrik şəbəkəsindən ayırmaq', 'Düzgün cavab: B) İdarəetmə pultu və ya Power düyməsi ilə söndürüb, daxili soyuducu pər (ventilyat', '', 29, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3e01932b-881e-4c12-8063-ea4986c409c8', 'a45a983d-d6c6-4625-8b10-d18406647b09', 'ka', 'მულტიმედიური პროექტორის ნათურის გადახურებისა და მწყობრიდან გამოსვლის თავიდან ასაცილებლად როგორია მისი გამორთვის სწორი წესი?', '["სავენტილაციო ღიობების ნაჭრით დაფარვა და გასაგრილებლად დატოვება", "გამორთვა პულტით ან კორპუსზე არსებული Power ღილაკით და ქსელიდან გათიშვა მხოლოდ მას შემდეგ, რაც შიდა ქულერი ნათურას გააგრილებს (ვენტილატორის გაჩერების შემდეგ)", "მუშაობის პროცესში კვების კაბელის როზეტიდან დაუყოვნებლივ გამოძრობა", "გახურებული ლინზის ამოღება და ცივ წყალში ჩადება", "პროექტორის 24 საათის განმავლობაში მუდმივად ჩართულ მდგომარეობაში დატოვება"]'::jsonb, 'გამორთვა პულტით ან კორპუსზე არსებული Power ღილაკით და ქსელიდან გათიშვა მხოლოდ მას შემდეგ, რაც შიდა ქულერი ნათურას გააგრილებს (ვენტილატორის გაჩერების შემდეგ)', 'Düzgün cavab: B) გამორთვა პულტით ან კორპუსზე არსებული Power ღილაკით და ქსელიდან გათიშვა მხოლოდ მა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b7399901-9d43-4843-b2ea-28d4be8730ea', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İnformatika kabinetində kompüterlərin, şəbəkə qurğularının və lisenziyalı proqram təminatının rəsmi uçotu hansı sənəddə qeyd olunur?', 'multiple_choice', '["Məktəb təsərrüfat anbarının silinmiş mallar siyahısında", "Məktəb kitabxanasının ümumi bədii kitab fondu reyestrində", "Şagirdlərin dərsdənkənar dərnək fəaliyyəti qeydiyyat kitabında", "İnformatika kabinetinin Pasportu və Avadanlıqların Texniki Uçot Jurnalında", "Məktəb yeməkxanasının gündəlik ərzaq qəbulu qaiməsində"]'::jsonb, 'İnformatika kabinetinin Pasportu və Avadanlıqların Texniki Uçot Jurnalında', 'Düzgün cavab: D) İnformatika kabinetinin Pasportu və Avadanlıqların Texniki Uçot Jurnalında', '', 30, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7e7a90d2-d2c8-4274-b602-3ad524801790', 'b7399901-9d43-4843-b2ea-28d4be8730ea', 'ka', 'რომელ დოკუმენტში აისახება ინფორმატიკის კაბინეტში კომპიუტერების, ინტერაქტიული მოწყობილობებისა და ლიცენზირებული პროგრამული უზრუნველყოფის აღრიცხვა?', '["სასკოლო ბიბლიოთეკის სახელმძღვანელოების საერთო ფონდის რეესტრში", "კლასგარეშე წრეობრივი მუშაობის ჟურნალში", "პედაგოგიური საბჭოს გადაწყვეტილებათა წიგნში", "ინფორმატიკის კაბინეტის პასპორტში, მოწყობილობების ტექნიკური აღრიცხვის ჟურნალსა და საინვენტარო წიგნში", "მოსწავლეთა დამამთავრებელი მოწმობების (ატესტატების) გაცემის რეგისტრაციაში"]'::jsonb, 'ინფორმატიკის კაბინეტის პასპორტში, მოწყობილობების ტექნიკური აღრიცხვის ჟურნალსა და საინვენტარო წიგნში', 'Düzgün cavab: D) ინფორმატიკის კაბინეტის პასპორტში, მოწყობილობების ტექნიკური აღრიცხვის ჟურნალსა და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('59011193-ea03-4b5a-92be-c16303234d19', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Azərbaycan Respublikası Konstitusiyasının 42-ci maddəsinə əsasən, vətəndaşların təhsil hüququ ilə bağlı hansı norma təsbit edilmişdir?', 'multiple_choice', '["Dövlət hər bir vətəndaş üçün imtahansız pulsuz ali təhsil təminatı verir", "Dövlət təhsil hüququnu yalnız 16 yaşadək olan şəxslərə şamil edir", "Dövlət yalnız ibtidai təhsil pilləsini məcburi hesab edir", "Dövlət yalnız ödənişli əsaslarla tam orta təhsil almaq hüququnu təmin edir", "Dövlət pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir"]'::jsonb, 'Dövlət pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir', 'Düzgün cavab: E) Dövlət pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir', '', 31, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a23bf8c9-820e-4b6e-b514-fca9e4048839', '59011193-ea03-4b5a-92be-c16303234d19', 'ka', 'კონსტიტუციის 42-ე მუხლის თანახმად, განათლების უფლების გარანტიასთან დაკავშირებით რომელი დებულებაა განმტკიცებული?', '["სახელმწიფო უზრუნველყოფს უფასო განათლებას უმაღლესი განათლების ყველა საფეხურზე", "სახელმწიფო სავალდებულოდ მიიჩნევს მხოლოდ დაწყებით განათლებას", "სახელმწიფო განათლების უფლებას ავრცელებს მხოლოდ 18 წლამდე ასაკის მოქალაქეებზე", "სახელმწიფო უფასო განათლებას უზრუნველყოფს მხოლოდ სახელმწიფო სკოლებში", "სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო ზოგად საშუალო განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და განათლების სისტემაზე სახელმწიფო კონტროლს"]'::jsonb, 'სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო ზოგად საშუალო განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და განათლების სისტემაზე სახელმწიფო კონტროლს', 'Düzgün cavab: E) სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო ზოგად საშუა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('623eaa05-6cbd-4107-ba62-db6a3f31478d', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Azərbaycan Respublikası Konstitusiyasının 25-ci maddəsinə əsasən, bərabərlik hüququnun əsas məzmunu hansı bənddə düzgün əks olunmuşdur?', 'multiple_choice', '["Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən və sosial mənşəyindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir", "Dövlət yalnız pensiya yaşına çatmış şəxslərin bərabərliyinə təminat verir", "Bərabərlik prinsipi yalnız məhkəmə çəkişməsi zamanı tətbiq olunur", "Bərabərlik hüququ yalnız dövlət qulluqçuları arasında hüquqi qüvvəyə malikdir", "Dövlət bərabərlik təminatını yalnız paytaxt ərazisində yaşayan vətəndaşlara şamil edir"]'::jsonb, 'Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən və sosial mənşəyindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir', 'Düzgün cavab: A) Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən və sosial', '', 32, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6d354102-425c-404e-b49b-b8d17fa57cb1', '623eaa05-6cbd-4107-ba62-db6a3f31478d', 'ka', 'კონსტიტუციის 25-ე მუხლის მიხედვით, რომელია სწორი ნორმა, რომელიც თანასწორობის უფლების არსს ასახავს?', '["სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესის, მრწამსის, სოციალური წარმოშობის მიუხედავად", "თანასწორობა გამოიყენება მხოლოდ საჯარო მოხელეებს შორის", "სახელმწიფო უზრუნველყოფს მხოლოდ აზერბაიჯანის მოქალაქეთა თანასწორობას", "თანასწორობის უფლება გამოიყენება მხოლოდ სასამართლო პროცესში", "სახელმწიფო თანასწორობას უზრუნველყოფს მხოლოდ შრომით ურთიერთობებში"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესის, მრწამსის, სოციალური წარმოშობის მიუხედავად', 'Düzgün cavab: A) სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას რასის,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('36920407-06b0-4df6-83e8-3c3b13406636', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Azərbaycan Respublikası Konstitusiyasının 32-ci maddəsinə əsasən, şəxsi toxunulmazlıq hüququ ilə bağlı hansı norma müəyyən edilmişdir?', 'multiple_choice', '["Öz razılığı olmadan kimsənin şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına yol verilmir", "Şəxsi toxunulmazlıq hüququ yalnız dövlət sirri daşıyan vəzifəli şəxslərə aiddir", "Şəxsi məlumatlar istənilən şəxs tərəfindən icazəsiz toplana və yayıla bilər", "Şəxsi məlumatların toxunulmazlığı yalnız kommersiya müəssisələrində qorunur", "Vətəndaşın şəxsi yazışmaları heç bir məhkəmə qərarı olmadan ictimaiyyətə açıqlana bilər"]'::jsonb, 'Öz razılığı olmadan kimsənin şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına yol verilmir', 'Düzgün cavab: A) Öz razılığı olmadan kimsənin şəxsi həyatı haqqında məlumatların toplanılmasına,', '', 33, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('31302970-b491-4075-bacd-9035ce944292', '36920407-06b0-4df6-83e8-3c3b13406636', 'ka', 'კონსტიტუციის 32-ე მუხლის თანახმად, რა წესია დადგენილი პირადი ხელშეუხებლობის უფლებასთან დაკავშირებით?', '["მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა, გამოყენება და გავრცელება დაუშვებელია, გარდა კანონით დადგენილი შემთხვევებისა", "პერსონალური ინფორმაციის შეგროვება შესაძლებელია სასამართლოს გადაწყვეტილების გარეშეც", "პირადი ცხოვრების შესახებ ინფორმაციის გავრცელება შესაძლებელია მხოლოდ ზეპირი თანხმობით", "პერსონალური მონაცემების შეგროვება თავისუფლად რეგულირდება შინაგანაწესით", "პირადი ხელშეუხებლობა ვრცელდება მხოლოდ სახელმწიფო საიდუმლოების მატარებელ პირებზე"]'::jsonb, 'მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა, გამოყენება და გავრცელება დაუშვებელია, გარდა კანონით დადგენილი შემთხვევებისა', 'Düzgün cavab: A) მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7aeb3e53-eb26-4ae3-aac3-bd556b4231a6', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', '“Təhsil haqqında” AR Qanununa əsasən, dövlət təhsil siyasətinin əsas prinsiplərindən olan “humanistlik” nəyi ifadə edir?', 'multiple_choice', '["Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquq və azadlıqlarının prioritet elan olunmasını", "Təhsil standartlarının müasir beynəlxalq təcrübələrdən təcrid edilməsini", "Yalnız humanitar elmlərin tədris olunaraq dəqiq elmlərin tədrisdən çıxarılmasını", "Təhsil müəssisələrində vahid məcburi ideologiyanın formalaşdırılmasını", "Şəxsiyyətin fərdi maraqlarının sıxışdırılaraq yalnız kollektivin tələblərinin təmin olunmasını"]'::jsonb, 'Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquq və azadlıqlarının prioritet elan olunmasını', 'Düzgün cavab: A) Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquq və aza', '', 34, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c0668909-b365-41fe-bbbe-b8b0b70aa85f', '7aeb3e53-eb26-4ae3-aac3-bd556b4231a6', 'ka', '„განათლების შესახებ“ კანონის მე-3 მუხლის თანახმად, რას გამოხატავს პრინციპი „ჰუმანურობა“?', '["ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას", "საგანმანათლებლო დაწესებულებების დაფინანსებას მხოლოდ სახელმწიფოს მიერ", "კონკურენტული გარემოს გაუქმებას", "მოსწავლეთა მომზადებას მხოლოდ შრომის ბაზრის მოთხოვნების შესაბამისად", "განათლების დაფუძნებას მხოლოდ ეროვნულ ღირებულებებზე"]'::jsonb, 'ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას', 'Düzgün cavab: A) ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('340e7200-22da-4433-9f84-298104e05f0c', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', '“Təhsil haqqında” AR Qanununun 12-ci maddəsinə əsasən, Azərbaycan Respublikasında təsbit edilmiş rəsmi təhsil formaları hansılardır?', 'multiple_choice', '["Dövlət, bələdiyyə və özəl təhsil", "İbtidai, orta və magistratura təhsili", "Formal, qeyri-formal və informal təhsil", "Əyani, qiyabi və distant təhsil", "Məktəbəqədər, ümumi və ali təhsil"]'::jsonb, 'Formal, qeyri-formal və informal təhsil', 'Düzgün cavab: C) Formal, qeyri-formal və informal təhsil', '', 35, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b9a1d7f5-169c-46cf-8975-cdaebe039c5e', '340e7200-22da-4433-9f84-298104e05f0c', 'ka', '„განათლების შესახებ“ კანონის მე-12 მუხლის თანახმად, რომელია განსაზღვრული განათლების ფორმები?', '["სკოლამდელი, ზოგადი და პროფესიული განათლება", "სახელმწიფო, კერძო და მუნიციპალური განათლება", "ფორმალური, არაფორმალური და ინფორმალური განათლება", "დაწყებითი, საშუალო და უმაღლესი განათლება", "დასწრებული, დაუსწრებელი და დისტანციური განათლება"]'::jsonb, 'ფორმალური, არაფორმალური და ინფორმალური განათლება', 'Düzgün cavab: C) ფორმალური, არაფორმალური და ინფორმალური განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('391a2226-b174-46f6-a59d-6fe625aa4d1f', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Müxtəlif səbəblərdən ümumi təhsildən kənarda qalmış şəxslərə təhsil almaq və ya təhsilin hər hansı səviyyəsini vaxtından əvvəl bitirmək hüququ verən təhsilalma forması hansıdır?', 'multiple_choice', '["Evdə təhsilalma forması", "Sərbəst (eksternat) təhsilalma forması", "Stasionar təhsilalma forması", "İnklüziv təhsilalma forması", "Qrup təhsili forması"]'::jsonb, 'Sərbəst (eksternat) təhsilalma forması', 'Düzgün cavab: B) Sərbəst (eksternat) təhsilalma forması', '', 36, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f5836fa6-a52f-4056-8bb9-df5940e62bf6', '391a2226-b174-46f6-a59d-6fe625aa4d1f', 'ka', 'განათლების მიღების რომელი ფორმა აძლევს განათლების მიღების უფლებას პირებს, რომლებიც სხვადასხვა მიზეზით განათლების მიღმა დარჩნენ?', '["შინ სწავლების ფორმა", "ექსტერნატის (თავისუფალი) განათლების ფორმა", "ინკლუზიური განათლების ფორმა", "დისტანციური განათლების ფორმა", "ინდივიდუალური სწავლების ფორმა"]'::jsonb, 'ექსტერნატის (თავისუფალი) განათლების ფორმა', 'Düzgün cavab: B) ექსტერნატის (თავისუფალი) განათლების ფორმა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ad33cbe9-32a9-45da-b52f-065cb350f65f', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', '“Təhsil haqqında” AR Qanununa əsasən, aşağıdakılardan hansı bilavasitə təhsilverənlərin vəzifələrinə aiddir?', 'multiple_choice', '["Məktəb binasının əsaslı təmir planını hazırlayıb podratçı təşkilat seçmək", "Məktəbin illik büdcəsini təsdiq etmək və xərclərə müstəqil sərəncam vermək", "İxtisasını artırmaq, müasir interaktiv təlim metodlarını və İKT nailiyyətlərini tədrisdə tətbiq etmək", "Təhsilalanların valideynlərindən məktəb fondu üçün maddi vəsait tələb etmək", "Dövlət təhsil proqramlarını öz şəxsi mülahizəsinə uyğun ixtisar etmək"]'::jsonb, 'İxtisasını artırmaq, müasir interaktiv təlim metodlarını və İKT nailiyyətlərini tədrisdə tətbiq etmək', 'Düzgün cavab: C) İxtisasını artırmaq, müasir interaktiv təlim metodlarını və İKT nailiyyətlərini', '', 37, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1894e1d8-bffb-4c77-8327-9fc5c602839e', 'ad33cbe9-32a9-45da-b52f-065cb350f65f', 'ka', '„განათლების შესახებ“ კანონის 32-ე მუხლის თანახმად, რომელი დებულება განეკუთვნება პედაგოგთა/საგანმანათლებლო საქმიანობის განმახორციელებელთა მოვალეობებს?', '["საგაკვეთილო ცხრილის დამოუკიდებლად შედგენა", "დასწრებაზე კონტროლის შეწყვეტა", "კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, თანამედროვე სწავლების მეთოდებისა და ისტ-ის დაუფლება და სასწავლო პროცესში გამოყენება", "საგანმანათლებლო პროგრამების თვითნებურად შეცვლა", "მშობლებისგან დამატებითი საფასურის მოთხოვნა"]'::jsonb, 'კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, თანამედროვე სწავლების მეთოდებისა და ისტ-ის დაუფლება და სასწავლო პროცესში გამოყენება', 'Düzgün cavab: C) კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, თანამედროვე სწავლების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b45f3df9-d745-49a1-9076-8f0b92944440', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', '“Ümumi təhsil haqqında” AR Qanununa əsasən, ümumi təhsil pilləsinin səviyyələri ardıcıllıqla hansı bənddə düzgün göstərilmişdir?', 'multiple_choice', '["İbtidai təhsil (I–V siniflər), orta təhsil (VI–IX siniflər) və peşə təhsili", "İbtidai təhsil (I–III siniflər), natamam orta (IV–VIII siniflər) və tam orta (IX–XI siniflər)", "Körpələr evi, məktəbəqədər hazırlıq və əsas ümumi təhsil", "Məktəbəqədər təhsil (0–6 yaş) və yalnız ümumi baza təhsili (I–IX siniflər)", "Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV siniflər), ümumi orta təhsil (V–IX siniflər) və tam orta təhsil (X–XI siniflər)"]'::jsonb, 'Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV siniflər), ümumi orta təhsil (V–IX siniflər) və tam orta təhsil (X–XI siniflər)', 'Düzgün cavab: E) Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV siniflər), ümumi orta təhsil (V–', '', 38, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ed21e90d-46b1-401b-80ff-e07cb6ba4ffd', 'b45f3df9-d745-49a1-9076-8f0b92944440', 'ka', '„ზოგადი განათლების შესახებ“ კანონის თანახმად, რომელია ზოგადი განათლების საფეხურები?', '["დაწყებითი (I–III), საშუალო (IV–IX) და უფროსი (X–XII)", "მოსამზადებელი (0), დაწყებითი (I–IV) და საშუალო (V–XI)", "სკოლამდელი (I–IV), საშუალო (V–X) და სრული (XI–XII)", "დაწყებითი (I–V), ზოგადი (VI–IX) და პროფესიული (X–XI)", "სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული ზოგადი საშუალო განათლება (X–XI)"]'::jsonb, 'სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული ზოგადი საშუალო განათლება (X–XI)', 'Düzgün cavab: E) სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b85ccbd4-9c80-4ac2-9c06-7981e10ca872', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', '“Ümumi təhsil haqqında” AR Qanununa əsasən, aşağıdakılardan hansı təhsilalanların hüquqlarına **AİD DEYİLDİR**?', 'multiple_choice', '["İnsan ləyaqətini alçaldan, fiziki və psixi zorakılıq hərəkətlərindən müdafiə olunmaq", "Dövlət təhsil müəssisələrində dərsliklərlə pulsuz təmin olunmaq", "Məktəbin kitabxana və informasiya resurslarından pulsuz istifadə etmək", "Həyat və sağlamlıq üçün təhlükəsiz təhsil şəraiti ilə təmin olunmaq", "Məktəbin daxili nizam-intizam qaydalarını müstəqil şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq"]'::jsonb, 'Məktəbin daxili nizam-intizam qaydalarını müstəqil şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq', 'Düzgün cavab: E) Məktəbin daxili nizam-intizam qaydalarını müstəqil şəkildə dəyişdirmək və pedaqo', '', 39, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('49776a38-f57e-4187-b38c-c143f8c5ce64', 'b85ccbd4-9c80-4ac2-9c06-7981e10ca872', 'ka', '„ზოგადი განათლების შესახებ“ კანონის 21-ე მუხლის თანახმად, რომელი დებულება არ განეკუთვნება მოსწავლეთა უფლებებს?', '["სახელმწიფო სკოლებში სახელმძღვანელოებით უფასო უზრუნველყოფა", "უსაფრთხო და ჯანსაღი საგანმანათლებლო გარემოთი უზრუნველყოფა", "ბიბლიოთეკითა და ლაბორატორიით უფასოდ სარგებლობა", "ღირსების შემლახველი მოპყრობისგან დაცვა", "დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიური პერსონალის საქმიანობის შეჩერება"]'::jsonb, 'დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიური პერსონალის საქმიანობის შეჩერება', 'Düzgün cavab: E) დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიური პერსონალის საქმიანო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b8cc6924-49bc-46fe-9ab7-179aaae76aa9', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Ümumi təhsil müəssisəsinin Nümunəvi Nizamnaməsinə əsasən, məktəbin gündəlik fəaliyyətinə cari rəhbərliyi kim həyata keçirir?', 'multiple_choice', '["Valideyn-Müəllim Assosiasiyasının sədri", "Yerli bələdiyyə orqanının təyin etdiyi inzibati nümayəndə", "Pedaqoji Şuranın ən yaşlı müəllim üzvü", "Məktəbin Həmkarlar İttifaqı Komitəsinin rəhbəri", "Müvafiq icra hakimiyyəti orqanı tərəfindən vəzifəyə təyin olunan məktəb direktoru"]'::jsonb, 'Müvafiq icra hakimiyyəti orqanı tərəfindən vəzifəyə təyin olunan məktəb direktoru', 'Düzgün cavab: E) Müvafiq icra hakimiyyəti orqanı tərəfindən vəzifəyə təyin olunan məktəb direktor', '', 40, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ab06c03b-0a68-431f-bc7b-e972c5a69d08', 'b8cc6924-49bc-46fe-9ab7-179aaae76aa9', 'ka', 'სამოდელო წესდების (დებულების) თანახმად, ვინ ახორციელებს სკოლის საქმიანობის მიმდინარე ხელმძღვანელობას?', '["მშობელთა და მასწავლებელთა ასოციაციის თავმჯდომარე", "მუნიციპალიტეტის თავმჯდომარის მიერ დანიშნული წარმომადგენელი", "პროფკავშირის კომიტეტის ხელმძღვანელი", "პედაგოგიური საბჭოს მიერ არჩეული თავმჯდომარე", "შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული ან სამუშაოზე მიღებული დირექტორი"]'::jsonb, 'შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული ან სამუშაოზე მიღებული დირექტორი', 'Düzgün cavab: E) შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული ან სა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('464816dd-032e-4b0e-b288-f3f9549b2386', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Ümumi təhsil müəssisəsinin Pedaqoji Şurasında qərarların qəbul edilməsi və səlahiyyətlilik qaydası necə tənzimlənir?', 'multiple_choice', '["İclasda üzvlərin sayından asılı olmayaraq qərarlar yalnız məktəb psixoloqunun razılığı ilə təsdiqlənir", "Yalnız məktəb direktoru və fənn metodiki birləşmə rəhbərləri iştirak etdikdə qərar qəbul olunur", "Qərarlar gizli səsvermə ilə qəbul edilərək yerli icra hakimiyyəti tərəfindən təsdiqlənir", "Pedaqoji Şura üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilir", "Pedaqoji Şurada bütün qərarlar istisnasız olaraq yalnız 100% yekdilliklə qəbul edilməlidir"]'::jsonb, 'Pedaqoji Şura üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilir', 'Düzgün cavab: D) Pedaqoji Şura üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir', '', 41, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('380e31e9-76ba-4dc6-b951-c8760fe6c555', '464816dd-032e-4b0e-b288-f3f9549b2386', 'ka', 'პედაგოგიური საბჭოს შესახებ დებულების თანახმად, როგორია გადაწყვეტილების მიღების წესი?', '["მონაწილეობენ მხოლოდ საგნობრივი კათედრების ხელმძღვანელები", "უფლებამოსილია, თუ ესწრება წევრთა ნახევარზე მეტი; გადაწყვეტილებები მიიღება ერთხმად", "უნდა ესწრებოდეს ყველა წევრი, გადაწყვეტილებები მიიღება ხმების 2/3-ით", "სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით", "სხდომა ტარდება ღია კენჭისყრით, გადაწყვეტილებებს აფორმებს მდივანი"]'::jsonb, 'სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით', 'Düzgün cavab: D) სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f753d2e2-9bab-42a3-85fa-59767c332c3a', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'AR Əmək Məcəlləsinə əsasən, işçilər üçün həftəlik normal iş vaxtı və I, II dərəcə əlilliyi olan şəxslər üçün qısaldılmış iş vaxtı ən çoxu neçə saatdır?', 'multiple_choice', '["Həftəlik normal iş vaxtı 48 saat, əlilliyi olan şəxslər üçün 40 saat", "Həftəlik normal iş vaxtı 36 saat, əlilliyi olan şəxslər üçün 24 saat", "Həftəlik normal iş vaxtı 40 saat, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saat", "Həftəlik normal iş vaxtı 42 saat, əlilliyi olan şəxslər üçün 35 saat", "Həftəlik normal iş vaxtı 45 saat, əlilliyi olan şəxslər üçün 30 saat"]'::jsonb, 'Həftəlik normal iş vaxtı 40 saat, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saat', 'Düzgün cavab: C) Həftəlik normal iş vaxtı 40 saat, I və II dərəcə əlilliyi olan şəxslər üçün isə', '', 42, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6df29fc3-a5ac-4c27-a357-448d07829031', 'f753d2e2-9bab-42a3-85fa-59767c332c3a', 'ka', 'შრომის კოდექსის 89-ე და 91-ე მუხლების თანახმად, როგორია სამუშაო დროის ნორმალური და შემოკლებული ხანგრძლივობა?', '["ნორმალური სამუშაო დრო 40 საათია, 16 წლამდე ასაკის მუშაკებისთვის - 24 საათი", "ნორმალური სამუშაო დრო 36 საათია, მძიმე სფეროში მომუშავეთათვის - 30 საათი", "ყოველკვირეული ნორმალური სამუშაო დრო არ უნდა აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის - კვირაში 36 საათს", "ნორმალური სამუშაო დრო 45 საათია, პედაგოგიური მუშაკებისთვის - 30 საათი", "ნორმალური სამუშაო დრო 48 საათია, მოზარდებისთვის - 40 საათი"]'::jsonb, 'ყოველკვირეული ნორმალური სამუშაო დრო არ უნდა აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის - კვირაში 36 საათს', 'Düzgün cavab: C) ყოველკვირეული ნორმალური სამუშაო დრო არ უნდა აღემატებოდეს 40 საათს, ხოლო I და II', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b79ed44a-e1f2-438c-b0ea-d81108bb20a7', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'AR Əmək Məcəlləsinin 186-cı maddəsinə əsasən, əmək intizamını pozan işçiyə işəgötürən tərəfindən verilə bilən intizam tənbehlərinin tam siyahısı hansıdır?', 'multiple_choice', '["Xəbərdarlıq, töhmət və işçinin əməkhaqqından tutulmaqla məktəb fonduna köçürülən cərimə", "İnzibati həbs, ictimai işlərə cəlb etmə və əmək kitabçasının ləğv edilməsi", "Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə əmək müqaviləsinin ləğvi", "Şifahi danlaq, aylıq əməkhaqqının 50% tutulması və 1 il müddətinə vəzifə dərəcəsinin aşağı salınması", "Yazılı xəbərdarlıq, ictimai qınaq və işçinin attestasiyadan kənarlaşdırılması"]'::jsonb, 'Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə əmək müqaviləsinin ləğvi', 'Düzgün cavab: C) Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutu', '', 43, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('04fcc6a2-dae7-4f36-9d7a-8c8ebf27ce50', 'b79ed44a-e1f2-438c-b0ea-d81108bb20a7', 'ka', 'შრომის კოდექსის 186-ე მუხლის თანახმად, რომელია დისციპლინური სახდელების სრული ჩამონათვალი?', '["საყვედური, ხელფასის 50%-ის დაკავება და თანამდებობის დაქვეითება", "ადმინისტრაციული ჯარიმა, საზოგადოებრივი შრომა და ხელშეკრულების შეწყვეტა", "საყვედური, სასტიკი საყვედური ბოლო გაფრთხილებით, ყოველთვიური ხელფასის არაუმეტეს 1/4-ის ოდენობით ჯარიმა (თუ გათვალისწინებულია კოლექტიური ხელშეკრულებით) და შრომითი ხელშეკრულების შეწყვეტა შრომის კოდექსის 70-ე მუხლით", "გაფრთხილება, საყვედური, თანამდებობიდან გათავისუფლება და ჯარიმა", "ზეპირი საყვედური, წერილობითი საყვედური, მკაცრი საყვედური და სამსახურიდან დათხოვნა"]'::jsonb, 'საყვედური, სასტიკი საყვედური ბოლო გაფრთხილებით, ყოველთვიური ხელფასის არაუმეტეს 1/4-ის ოდენობით ჯარიმა (თუ გათვალისწინებულია კოლექტიური ხელშეკრულებით) და შრომითი ხელშეკრულების შეწყვეტა შრომის კოდექსის 70-ე მუხლით', 'Düzgün cavab: C) საყვედური, სასტიკი საყვედური ბოლო გაფრთხილებით, ყოველთვიური ხელფასის არაუმეტეს 1', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('124df964-fcd3-4b5e-8ef2-0257472402fb', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'AR Əmək Məcəlləsinin 187 və 188-ci maddələrinə əsasən, intizam tənbehinin tətbiqi və qüvvədə olma müddəti qaydası necədir?', 'multiple_choice', '["İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz", "Yalnız şifahi izahat alınır və tənbeh verildiyi gündən 2 il müddətində qüvvədə saxlanılır", "İşçidən heç bir izahat tələb edilmədən tənbeh verilir və 1 il müddətində qüvvədə qalır", "İntizam tənbehi məhkəmə qərarı ilə verilir və 3 il müddətində qüvvədə qalır", "İntizam tənbehi verildikdən sonra 1 ay ərzində yeni tənbeh tətbiq edilməzsə avtomatik qüvvədən düşür"]'::jsonb, 'İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz', 'Düzgün cavab: A) İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbe', '', 44, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('dfb595a4-b244-4192-854e-25d79b20d149', '124df964-fcd3-4b5e-8ef2-0257472402fb', 'ka', 'შრომის კოდექსის 187-ე მუხლის თანახმად, როგორია დისციპლინური სახდელის დადების წესი?', '["დისციპლინური სახდელის დადებამდე მუშაკს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია დადების დღიდან 1 წლის განმავლობაში", "ახსნა-განმარტება სავალდებულოა, სახდელი მოქმედებს 3 თვის განმავლობაში", "ახსნა-განმარტება არ მოითხოვება, სახდელი სასამართლოს გადაწყვეტილებით ძალაში რჩება 3 წელი", "ახსნა-განმარტება მიიღება მხოლოდ ზეპირად და სახდელი მოქმედებს 6 თვე", "სახდელი შეიძლება დაიდოს ახსნა-განმარტების მოთხოვნის გარეშე და ძალაში რჩება 2 წელი"]'::jsonb, 'დისციპლინური სახდელის დადებამდე მუშაკს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია დადების დღიდან 1 წლის განმავლობაში', 'Düzgün cavab: A) დისციპლინური სახდელის დადებამდე მუშაკს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტებ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('56f4d88d-fe17-42ad-9c1a-350825a6965c', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'AR Əmək Məcəlləsinə əsasən, işçi öz təşəbbüsü ilə əmək müqaviləsini ləğv etmək istədikdə işəgötürəni nə qədər müddət əvvəl yazılı ərizə ilə xəbərdar etməlidir?', 'multiple_choice', '["10 iş günü əvvəl", "3 iş günü əvvəl", "2 həftə əvvəl", "1 təqvim ayı əvvəl", "2 təqvim ayı əvvəl"]'::jsonb, '1 təqvim ayı əvvəl', 'Düzgün cavab: D) 1 təqvim ayı əvvəl', '', 45, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a47537a7-4320-4b23-8e49-37eb78cc7b6a', '56f4d88d-fe17-42ad-9c1a-350825a6965c', 'ka', 'შრომის კოდექსის 69-ე და 172-ე მუხლების თანახმად, როგორია მუშაკის საკუთარი ინიციატივით შრომითი ხელშეკრულების შეწყვეტის წესი?', '["მუშაკი განცხადებას წარადგენს 15 დღით ადრე", "მუშაკი აფრთხილებს 3 სამუშაო დღით ადრე", "მუშაკი ზეპირად აფრთხილებს 2 კვირით ადრე", "მუშაკმა წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი 1 კალენდარული თვით ადრე; საბოლოო ანგარიშსწორება ხდება არაუგვიანეს ბოლო სამუშაო დღისა", "მუშაკს შეუძლია სამსახურიდან გაფრთხილების გარეშე წასვლა"]'::jsonb, 'მუშაკმა წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი 1 კალენდარული თვით ადრე; საბოლოო ანგარიშსწორება ხდება არაუგვიანეს ბოლო სამუშაო დღისა', 'Düzgün cavab: D) მუშაკმა წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი 1 კალენდარული თვით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a5602402-3748-4f0d-bb71-c8c287248653', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Kompüter şəbəkələrində Lokal Şəbəkə (LAN) ilə Qlobal Şəbəkə (WAN) arasındakı əsas texnoloji fərq nədən ibarətdir?', 'multiple_choice', '["LAN yalnız peyk rabitəsi ilə, WAN isə yalnız telefon kabelləri ilə əlaqə yaradır", "LAN şəbəkəsində heç vaxt IP ünvanlaşdırmadan istifadə olunmur", "LAN-da informasiya ötürmə sürəti qlobal WAN şəbəkəsindən həmişə qat-qat aşağı olur", "LAN məhdud bir coğrafi ərazini (otaq, bina, kampus), WAN isə geniş coğrafi əraziləri (şəhərlər, ölkələr, qitələr) əhatə edir", "LAN yalnız internetə çıxış üçün, WAN isə ofisdaxili printerlərin paylaşımı üçündür"]'::jsonb, 'LAN məhdud bir coğrafi ərazini (otaq, bina, kampus), WAN isə geniş coğrafi əraziləri (şəhərlər, ölkələr, qitələr) əhatə edir', 'Düzgün cavab: D) LAN məhdud bir coğrafi ərazini (otaq, bina, kampus), WAN isə geniş coğrafi ərazi', '', 46, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e5a1f7ae-fc1d-4054-ac40-0682605954f8', 'a5602402-3748-4f0d-bb71-c8c287248653', 'ka', 'რა არის ძირითადი განსხვავება LAN და WAN ქსელებს შორის?', '["LAN განკუთვნილია ინტერნეტთან წვდომისთვის, ხოლო WAN ლოკალური რესურსების გაზიარებისთვის", "LAN-ში სიჩქარე დაბალია, WAN-ში სიჩქარე მაღალია", "LAN განკუთვნილია სახელმწიფო უწყებებისთვის, ხოლო WAN ინდივიდუალური მომხმარებლებისთვის", "LAN აერთიანებს კომპიუტერებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა), ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს", "LAN იქმნება მხოლოდ სადენიანი, WAN კი მხოლოდ უსადენო ტექნოლოგიით"]'::jsonb, 'LAN აერთიანებს კომპიუტერებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა), ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს', 'Düzgün cavab: D) LAN აერთიანებს კომპიუტერებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა),', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('70c7aa4c-e7e1-4fb1-98fb-9e9181103fdf', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İnternet şəbəkəsində istifadəçilərin daxil etdiyi domen adlarını rəqəmsal IP ünvanlarına çevirən əsas iyerarxik şəbəkə xidməti hansıdır?', 'multiple_choice', '["NAT (Network Address Translation)", "DHCP (Dynamic Host Configuration Protocol)", "DNS (Domain Name System)", "FTP (File Transfer Protocol)", "ARP (Address Resolution Protocol)"]'::jsonb, 'DNS (Domain Name System)', 'Düzgün cavab: C) DNS (Domain Name System)', '', 47, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f176746e-77f8-438b-9091-2701d9256502', '70c7aa4c-e7e1-4fb1-98fb-9e9181103fdf', 'ka', 'რომელია ძირითადი ქსელური სერვისი, რომელიც დომენურ სახელებს IP მისამართებად გარდაქმნის?', '["DHCP - დინამიკური IP განაწილების სისტემა", "NAT - მისამართების გარდაქმნის სისტემა", "DNS (Domain Name System) - განაწილებული იერარქიული დომენური სახელების სისტემა", "ARP - MAC მისამართის განსაზღვრის სისტემა", "Proxy Service - შუალედური ქეშირების სისტემა"]'::jsonb, 'DNS (Domain Name System) - განაწილებული იერარქიული დომენური სახელების სისტემა', 'Düzgün cavab: C) DNS (Domain Name System) - განაწილებული იერარქიული დომენური სახელების სისტემა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('080c73bc-5a42-4677-afc1-7b98269535d4', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'İki faktorlu autentifikasiya (2FA) təhlükəsizlik mexanizminin əsas üstünlüyü nədən ibarətdir?', 'multiple_choice', '["Kompüterdəki mətn fayllarını avtomatik şifrələyərək diskdə yerə qənaət etməsi", "İnternet bağlantısının sürətini və fayl endirmə həcmini ikiqat artırması", "İstifadəçinin bütün parollarını yadda saxlayaraq klaviaturadan şifrə yığımını ləğv etməsi", "Kompüterin əməliyyat sisteminin internetdən asılı olmadan avtomatik yenilənməsi", "Əsas istifadəçi şifrəsi ələ keçirilsə belə, ikinci müstəqil təsdiqləmə (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləməsi"]'::jsonb, 'Əsas istifadəçi şifrəsi ələ keçirilsə belə, ikinci müstəqil təsdiqləmə (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləməsi', 'Düzgün cavab: E) Əsas istifadəçi şifrəsi ələ keçirilsə belə, ikinci müstəqil təsdiqləmə (SMS kod,', '', 48, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('44a72d2f-6502-4e18-813d-ee33ca5ce943', '080c73bc-5a42-4677-afc1-7b98269535d4', 'ka', 'რა არის ორფაქტორიანი ავთენტიფიკაციის (2FA) მექანიზმის ძირითადი უპირატესობა?', '["ერთდროულად რამდენიმე მოწყობილობიდან შესვლის შეზღუდვა", "ფაილების ავტომატური დაარქივება მეხსიერების ეკონომიის მიზნით", "ინტერნეტის სიჩქარის გაზრდა და შიფრაციის დაჩქარება", "ოპერაციული სისტემის განახლებების ავტომატური ინსტალაცია", "პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების გარეშე (SMS კოდი, TOTP, ავთენტიფიკატორის აპლიკაცია ან FIDO2 გასაღები)"]'::jsonb, 'პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების გარეშე (SMS კოდი, TOTP, ავთენტიფიკატორის აპლიკაცია ან FIDO2 გასაღები)', 'Düzgün cavab: E) პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d47deca2-4b6a-48c9-9584-40c20b56a69f', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Kiberfırıldaqçıların etibarlı təşkilat və ya xidmət adından saxta e-poçt və saxta veb-keçidlər göndərərək istifadəçilərin məxfi məlumatlarını ələ keçirməsi hansı kiberhücum növüdür?', 'multiple_choice', '["Spyware (Casus proqram təminatı)", "Fişinq (Phishing)", "Brute Force (Kütləvi şifrə seçimi)", "DDoS hücumu", "Ransomware (Fidyə proqramı)"]'::jsonb, 'Fişinq (Phishing)', 'Düzgün cavab: B) Fişinq (Phishing)', '', 49, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('613ec51f-fb3f-4b01-baef-0479bdabd31b', 'd47deca2-4b6a-48c9-9584-40c20b56a69f', 'ka', 'ყალბი ელექტრონული წერილების (e-mail) გაგზავნით მონაცემთა მითვისება კიბერშეტევის რომელ სახეობას განეკუთვნება?', '["სპუფინგი (Spoofing) - IP ან MAC მისამართის გაყალბება", "ფიშინგი (Phishing) - სოციალური ინჟინერიის საფუძველზე ყალბი ელფოსტისა და ვებსაიტის მეშვეობით საიდენტიფიკაციო მონაცემების მოპარვა", "სნიფინგი (Sniffing) - ქსელური ტრაფიკის ფარული მოსმენა", "ბრუტ-ფორსი (Brute Force) - პაროლის მასიური შერჩევით გამოცნობა", "გამომძალველი პროგრამა (Ransomware) - ფაილების დაშიფვრა და გამოსასყიდის მოთხოვნა"]'::jsonb, 'ფიშინგი (Phishing) - სოციალური ინჟინერიის საფუძველზე ყალბი ელფოსტისა და ვებსაიტის მეშვეობით საიდენტიფიკაციო მონაცემების მოპარვა', 'Düzgün cavab: B) ფიშინგი (Phishing) - სოციალური ინჟინერიის საფუძველზე ყალბი ელფოსტისა და ვებსაიტი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('235d8886-1d3e-45bf-b1e5-292ffc83f781', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'MS Word mətn redaktorunda abzasın sol, sağ kənar boşluqlarını və birinci sətir girintisini vizual olaraq dəqiq tənzimləmək üçün hansı elementdən istifadə edilir?', 'multiple_choice', '["Tez Müraciət Panelindəki Çap düyməsindən", "Sənədin şaquli fırlatma zolağından (Scroll Bar)", "Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücülərindən", "Pəncərənin ən aşağısındakı Vəziyyət zolağından (Status Bar)", "Sənədin miqyasını dəyişən Zoom sürüşdürücüsündən"]'::jsonb, 'Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücülərindən', 'Düzgün cavab: C) Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücülərindən', '', 50, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e6e005ec-0c8d-419e-874e-b0f7be55ec3f', '235d8886-1d3e-45bf-b1e5-292ffc83f781', 'ka', 'Word-ში აბზაცის შეწევის (ინდენტაციის) ზუსტად დასარეგულირებლად ინტერფეისის რომელი ელემენტი გამოიყენება?', '["სწრაფი წვდომის პანელი და ლენტისებრი ინტერფეისი", "მდგომარეობის ზოლი (Status Bar) და მასშტაბის სლაიდერი", "ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული შეწევის მარკერები (სლაიდერები) და Paragraph დიალოგური ფანჯარა", "ვერტიკალური სახაზავი და გვერდის კიდეების ველები", "ნავიგაციის პანელი და ძებნის ველი"]'::jsonb, 'ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული შეწევის მარკერები (სლაიდერები) და Paragraph დიალოგური ფანჯარა', 'Düzgün cavab: C) ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული შეწევის მარკერები (სლაიდერები', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4573a62a-eafb-4bfd-9f63-06314881bab2', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'MS Word-də digər səhifələrə toxunmadan yalnız müəyyən səhifələrin oriyentasiyasını (məsələn, Albom / Landscape) dəyişmək üçün hansı əməliyyat icra olunmalıdır?', 'multiple_choice', '["Müvafiq səhifənin əvvəlinə və sonuna Bölmə Kəsilməsi (Section Break – Next Page) əlavə edib həmin bölmənin oriyentasiyasını dəyişmək", "Sənədi iki ayrı Word sənədinə bölərək ayrı-ayrı çap etmək", "Sənədin yalnız görünüş rejimini Veb-sənəd (Web Layout) formasına keçirmək", "Mətn qutusu əlavə edərək bütün səhifəni 90 dərəcə fırlatmaq", "Bütün sənəd üçün Page Break əlavə edib şriftin ölçüsünü kiçiltmək"]'::jsonb, 'Müvafiq səhifənin əvvəlinə və sonuna Bölmə Kəsilməsi (Section Break – Next Page) əlavə edib həmin bölmənin oriyentasiyasını dəyişmək', 'Düzgün cavab: A) Müvafiq səhifənin əvvəlinə və sonuna Bölmə Kəsilməsi (Section Break – Next Page)', '', 51, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7f25d9c9-13f2-40fa-aec7-268081105295', '4573a62a-eafb-4bfd-9f63-06314881bab2', 'ka', 'Word-ში ზოგიერთი გვერდის ვერტიკალურ (წიგნისებრ), ხოლო ზოგიერთის ჰორიზონტალურ (ალბომურ) ორიენტაციაში დასაფორმატებლად რა ოპერაცია უნდა შესრულდეს?', '["დოკუმენტში უნდა დაემატოს სექციის წყვეტა (Section Break - Next Page) და ამ სექციისთვის შეიცვალოს პარამეტრი Layout > Orientation", "დოკუმენტი ორ ცალკე ფაილად უნდა გაიყოს და თითოეულის ორიენტაცია ცალ-ცალკე განისაზღვროს", "გვერდის კიდეების ველების შეცვლით უნდა შეიქმნას ჰორიზონტალური ეფექტი", "თითოეული გვერდისთვის ცალკე უნდა დაემატოს Page Break და შეიცვალოს ორიენტაცია", "ტექსტური ველების (Text Box) გამოყენებით უნდა შემოტრიალდეს გვერდი"]'::jsonb, 'დოკუმენტში უნდა დაემატოს სექციის წყვეტა (Section Break - Next Page) და ამ სექციისთვის შეიცვალოს პარამეტრი Layout > Orientation', 'Düzgün cavab: A) დოკუმენტში უნდა დაემატოს სექციის წყვეტა (Section Break - Next Page) და ამ სექციი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fe86a2d7-cc54-48c2-b7de-21440dc772d7', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'MS Word-də sənəd başlıqlarına əsasən avtomatik yenilənən Mündəricat yerləşdirmək üçün hansı lent tabına müraciət edilir?', 'multiple_choice', '["Insert (Əlavə et) > Shapes", "View (Görünüş) > Split", "Layout (Düzən) > Page Setup", "References (İstinadlar) > Table of Contents", "Review (İcmal) > Word Count"]'::jsonb, 'References (İstinadlar) > Table of Contents', 'Düzgün cavab: D) References (İstinadlar) > Table of Contents', '', 52, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('339cc3d9-0491-4d38-b7f3-6074383b185e', 'fe86a2d7-cc54-48c2-b7de-21440dc772d7', 'ka', 'Word-ში სათაურებზე დაფუძნებული ავტომატურად განახლებადი სარჩევის (Mündəricat) შესაქმნელად რომელ ჩანართს (ტაბს) უნდა მივმართოთ?', '["Layout > Table of Contents", "Review > Table of Contents", "View > Navigation Pane", "References (ბმულები/სქოლიოები) ჩანართი > Table of Contents ჯგუფი", "Insert > Table of Contents"]'::jsonb, 'References (ბმულები/სქოლიოები) ჩანართი > Table of Contents ჯგუფი', 'Düzgün cavab: D) References (ბმულები/სქოლიოები) ჩანართი > Table of Contents ჯგუფი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c514d2fd-3057-4545-b4c1-ee6a426ba88c', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'MS Excel-də `$C$2` mütləq ünvanı olan düstur başqa xanalara kopyalandıqda həmin xana ünvanı necə dəyişir?', 'multiple_choice', '["Sətir nömrəsi sabit qalır, lakin sütun hərfi sağa doğru sürüşür", "Həm sütun, həm də sətir yeni xanaya uyğun olaraq nisbi sürüşür", "Sütun sabit qalır, lakin sətir nömrəsi aşağıya doğru sürüşür", "Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır", "Xana daxilindəki düstur avtomatik olaraq #REF! xətasına çevrilir"]'::jsonb, 'Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', 'Düzgün cavab: D) Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', '', 53, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('01fee25b-7df7-4e98-91f6-d7da3942740c', 'c514d2fd-3057-4545-b4c1-ee6a426ba88c', 'ka', 'Excel-ში ფორმულა, რომელიც შეიცავს აბსოლუტურ მისამართს $C$2, როგორ შეიცვლება სხვა უჯრებში კოპირებისას?', '["ფორმულა დააბრუნებს შეცდომას #REF!", "მხოლოდ სვეტი დარჩება უცვლელი, სტრიქონი შეიცვლება", "ავტომატურად გადაადგილდება როგორც სვეტი, ისე სტრიქონი", "რადგან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი დარჩება (აბსოლუტური მიმართვა)", "მხოლოდ სტრიქონი დარჩება უცვლელი, სვეტი შეიცვლება"]'::jsonb, 'რადგან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი დარჩება (აბსოლუტური მიმართვა)', 'Düzgün cavab: D) რადგან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('41681040-da63-4dfe-9ee5-635051a57248', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'MS Excel-də `A1:A10` diapazonunda yalnız qiyməti 50-dən böyük olan xanaların sayını hesablamaq üçün hansı funksiya düzgün yazılmışdır?', 'multiple_choice', '["=SUMIF(A1:A10; >50)", "=COUNT(A1:A10; >50)", "=COUNTIF(A1:A10 = 50)", "=COUNTIF(A1:A10; \">50\")", "=IFCOUNT(A1:A10; \">50\")"]'::jsonb, '=COUNTIF(A1:A10; ">50")', 'Düzgün cavab: D) =COUNTIF(A1:A10; ">50")', '', 54, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a8732b7a-adda-4e26-b160-ebf5f197e42f', '41681040-da63-4dfe-9ee5-635051a57248', 'ka', 'Excel-ში A1:A10 დიაპაზონში მხოლოდ 50-ზე მეტი მნიშვნელობის მქონე უჯრების რაოდენობის დასათვლელად რომელი ფუნქციაა სწორი?', '["=COUNTIF(A1:A10;>50)", "=IF(A1:A10>50;COUNT(A1:A10))", "=SUMIF(A1:A10;\">50\")", "=COUNTIF(A1:A10;\">50\")", "=COUNTIFS(A1:A10;\">50\")"]'::jsonb, '=COUNTIF(A1:A10;">50")', 'Düzgün cavab: D) =COUNTIF(A1:A10;">50")', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b5b67494-6388-4fb2-affd-38e29b858108', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'MS Excel-də B2 xanasındakı əməkhaqqı 800-dən çox olduqda 15%, əks halda 5% mükafat hesablayan məntiqi düstur hansıdır?', 'multiple_choice', '["=IF(B2>800; B2*0.15; 0)", "=IF(B2>800; 15%; 5%)", "=IF(B2>800; B2*0.15; B2*0.05)", "=IF(B2>=800; B2*0.15; B2*0.05)", "=IF(B2<800; B2*0.15; B2*0.05)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: C) =IF(B2>800; B2*0.15; B2*0.05)', '', 55, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('fc0d503a-c0a6-43a1-aa6c-56e790f022cc', 'b5b67494-6388-4fb2-affd-38e29b858108', 'ka', 'Excel-ში რომელია ფორმულა, რომელიც გამოითვლის 15%-იან პრემიას, როდესაც B2 უჯრაში ხელფასი 800-ზე მეტია (ხოლო წინააღმდეგ შემთხვევაში 5%-ს)?', '["=IF(B2>=800; B2*0.15; B2*0.05)", "=SWITCH(B2>800; TRUE; B2*0.15; FALSE; B2*0.05)", "=IF(B2>800; B2*0.15; B2*0.05)", "=IFS(B2>800; B2*0.15; TRUE; B2*0.05)", "=IF(B2>800; B2*15%; B2*5%)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: C) =IF(B2>800; B2*0.15; B2*0.05)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8dfcb539-831f-4ad5-8b18-85e153a9251f', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'MS Excel-də seçilmiş xanaya yalnız müəyyən diapazonda ədədlərin və ya xüsusi siyahıdakı qiymətlərin daxil edilməsinə icazə verən alət hansıdır?', 'multiple_choice', '["Data Validation (Verilənlərin doğrulanması)", "Conditional Formatting (Şərti formatlaşdırma)", "Text to Columns (Mətnin sütunlara bölünməsi)", "AutoFilter (Avtosüzgəc)", "Remove Duplicates (Təkrarların silinməsi)"]'::jsonb, 'Data Validation (Verilənlərin doğrulanması)', 'Düzgün cavab: A) Data Validation (Verilənlərin doğrulanması)', '', 56, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f6519dad-847f-41d6-b437-617f637aaee8', '8dfcb539-831f-4ad5-8b18-85e153a9251f', 'ka', 'Excel-ში რომელი ხელსაწყო იძლევა უჯრაში მხოლოდ გარკვეულ დიაპაზონში რიცხვების შეყვანის დაშვების შესაძლებლობას?', '["Data Validation (მონაცემთა ვალიდაცია / შემოწმება) - Data ჩანართში Whole Number, List, Date კრიტერიუმებით", "Conditional Formatting - პირობითი ფორმატირება", "Group - დაჯგუფებით დაცვა", "Data Consolidation - მონაცემთა კონსოლიდაცია", "Filter - გაფილტვრით დაშვება"]'::jsonb, 'Data Validation (მონაცემთა ვალიდაცია / შემოწმება) - Data ჩანართში Whole Number, List, Date კრიტერიუმებით', 'Düzgün cavab: A) Data Validation (მონაცემთა ვალიდაცია / შემოწმება) - Data ჩანართში Whole Number,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ebb0e6a9-67de-4a18-85c1-9378cc8c184a', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'MS PowerPoint proqramında təqdimatdakı bütün slaydların vahid dizaynını, şrift və loqosunu eyni anda tənzimləmək üçün hansı rejimdən istifadə olunur?', 'multiple_choice', '["Reading View (Oxu rejimi)", "Slide Master (Slayd nümunəsi)", "Presenter View (Aparıcı görünüşü)", "Notes Master (Qeydlər nümunəsi)", "Slide Sorter (Slayd çeşidləyicisi)"]'::jsonb, 'Slide Master (Slayd nümunəsi)', 'Düzgün cavab: B) Slide Master (Slayd nümunəsi)', '', 57, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d3810965-c403-45c0-a32f-d3d48b2e66e5', 'ebb0e6a9-67de-4a18-85c1-9378cc8c184a', 'ka', 'PowerPoint-ში ყველა სლაიდის ერთიანი დიზაინის შაბლონის შესაცვლელად რომელი რეჟიმი გამოიყენება?', '["Notes Master - შენიშვნების ოსტატის რეჟიმი", "Slide Master (სლაიდების ოსტატი) - View ჩანართის Master Views ჯგუფი", "Outline View - სტრუქტურის რეჟიმი", "Slide Sorter - სლაიდების დამხარისხებელი", "Reading View - კითხვის რეჟიმი"]'::jsonb, 'Slide Master (სლაიდების ოსტატი) - View ჩანართის Master Views ჯგუფი', 'Düzgün cavab: B) Slide Master (სლაიდების ოსტატი) - View ჩანართის Master Views ჯგუფი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ac742360-515a-47ae-93d6-3ec924241811', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'MS PowerPoint proqramında “Transition” (Keçid) ilə “Animation” (Animasiya) arasındakı əsas fərq nədir?', 'multiple_choice', '["Transition yalnız video faylları, Animation isə yalnız səs fayllarını idarə edir", "Transition və Animation tamamilə eyni funksiyadır və heç bir fərqi yoxdur", "Transition slayd daxilindəki mətnlərə, Animation isə yalnız slayddan slayda keçidlərə tətbiq olunur", "Transition bir slayddan digər slayda keçid effektidir, Animation isə slayd daxilindəki obyektlərin hərəkət effektidir", "Transition yalnız çap rejimində, Animation isə yalnız slayd nümayişi zamanı işləyir"]'::jsonb, 'Transition bir slayddan digər slayda keçid effektidir, Animation isə slayd daxilindəki obyektlərin hərəkət effektidir', 'Düzgün cavab: D) Transition bir slayddan digər slayda keçid effektidir, Animation isə slayd daxil', '', 58, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e519cc77-4349-4a2f-9de0-45f131314fdb', 'ac742360-515a-47ae-93d6-3ec924241811', 'ka', 'PowerPoint-ში რა არის ძირითადი განსხვავება ''Transition''-სა (გადასვლა) და ''Animation''-ს (ანიმაცია) შორის?', '["Transition ირთვება ავტომატურად, Animation კი ხელით", "Transition არის ხმოვანი ეფექტი, Animation კი ვიზუალური ეფექტი", "ორივე ერთი და იგივე ფუნქციაა, მხოლოდ სახელებია განსხვავებული", "Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორე სლაიდზე გადასვლისას, ხოლო Animation არის სლაიდის შიგნით არსებული კონკრეტული ობიექტების მოძრაობის ეფექტი", "Transition გამოიყენება ობიექტებისთვის, Animation კი სლაიდებისთვის"]'::jsonb, 'Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორე სლაიდზე გადასვლისას, ხოლო Animation არის სლაიდის შიგნით არსებული კონკრეტული ობიექტების მოძრაობის ეფექტი', 'Düzgün cavab: D) Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორე სლაიდზე გადასვლისას, ხოლო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d3aa9b25-522a-44fc-96e0-6b7fe2bb36d6', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Bulud saxlama xidmətlərində (məsələn, OneDrive) saxlanılan sənədin əvvəlki tarixdəki redaktə versiyalarına baxmaq və bərpa etmək üçün hansı funksiyadan istifadə olunur?', 'multiple_choice', '["Inspect Document (Sənədi yoxla)", "Compatibility Mode (Uyğunluq rejimi)", "Save As (Fərqli saxla)", "Version History (Versiya tarixçəsi)", "Encrypt with Password (Parolla şifrələmə)"]'::jsonb, 'Version History (Versiya tarixçəsi)', 'Düzgün cavab: D) Version History (Versiya tarixçəsi)', '', 59, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9c470633-6c8d-4184-83a5-d5808239d254', 'd3aa9b25-522a-44fc-96e0-6b7fe2bb36d6', 'ka', 'ღრუბლოვან საცავებში წინა ცვლილებებზე დასაბრუნებლად რომელი ფუნქცია გამოიყენება?', '["Sync History - სინქრონიზაციის ისტორია", "Backup and Restore - სარეზერვო ასლის შექმნისა და აღდგენის ხელსაწყო", "File Recovery - ფაილის აღდგენის ხელსაწყო", "Version History (ვერსიების ისტორია) - File > Info > Version History ან OneDrive/SharePoint-ის ისტორია", "Activity Log - აქტივობის ჟურნალი"]'::jsonb, 'Version History (ვერსიების ისტორია) - File > Info > Version History ან OneDrive/SharePoint-ის ისტორია', 'Düzgün cavab: D) Version History (ვერსიების ისტორია) - File > Info > Version History ან OneDrive/', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('446a4521-72ed-45e5-a19d-224554b4d4ab', 'ecdb8cc1-7b6a-4bb0-83ba-ca7c2f44da9b', 'Süni intellekt əsaslı generativ dil modellərində (LLM) “Hallüsinasiya” (Hallucination) riski nəyi ifadə edir?', 'multiple_choice', '["Modelin real faktlara əsaslanmayan, uydurma məlumatları çox inandırıcı və qətiyyətli tərzdə təqdim etməsini", "Modelin yalnız orfoqrafik hərf səhvləri buraxmasını", "Modelin kompüterin prosessorunu qızdıraraq texniki avadanlığı sıradan çıxarmasını", "Modelin yalnız proqramlaşdırma dillərində sintaksis xətaları etməsini", "Modelin internet bağlantısını zəiflədərək lokal şəbəkəni dondurmasını"]'::jsonb, 'Modelin real faktlara əsaslanmayan, uydurma məlumatları çox inandırıcı və qətiyyətli tərzdə təqdim etməsini', 'Düzgün cavab: A) Modelin real faktlara əsaslanmayan, uydurma məlumatları çox inandırıcı və qətiyy', '', 60, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6c5b487f-92e6-4e8c-8955-38df0298871e', '446a4521-72ed-45e5-a19d-224554b4d4ab', 'ka', 'ხელოვნურ ინტელექტში რას გამოხატავს „ჰალუცინაციის“ (Hallucination) რისკი?', '["მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ციტატების ან წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით", "მოდელის მიერ კომპიუტერის რესურსების ზედმეტად გადატვირთვას", "მოდელის მიერ მომხმარებლის მოთხოვნის გაუგებრობის გამო შემთხვევითი პასუხის გაცემას", "მოდელის მიერ პასუხის გაცემაზე უარის თქმასა და შეცდომის დაბრუნებას", "მოდელის მიერ მხოლოდ ინგლისურ ენაზე პასუხის გაცემას და სხვა ენების მხარდაჭერის არარსებობას"]'::jsonb, 'მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ციტატების ან წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით', 'Düzgün cavab: A) მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ციტატების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('baaae6e4-5b23-469e-8d46-c96d6bb4d70e', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Ümumi təhsil müəssisəsində kargüzarlığın və sənəd dövriyyəsinin təşkilində katibə-makinaçının əsas vəzifə funksiyası hansıdır?', 'multiple_choice', '["Məktəbin maliyyə-təsərrüfat fəaliyyətini idarə etmək, büdcə smetasını tərtib etmək və tender sənədlərini hazırlamaq", "Müəssisəyə daxil olan və çıxan sənədlərin qeydiyyatını aparmaq, rəsmi yazışmaları tərtib etmək, icra nəzarətini təşkil etmək və cari arxivi formalaşdırmaq", "Tədris planlarının və summativ qiymətləndirmə cədvəllərinin metodiki ekspertizasını aparmaq və pedaqoji şuraya təqdim etmək", "Məktəbin təhlükəsizlik sistemlərinin və istilik-kommunikasiya avadanlığının texniki sazlığına nəzarət etmək", "Şagirdlərin dərs davamiyyətini və fənn üzrə nailiyyətlərini elektron sistemdə izləmək və valideynlərə hesabat vermək"]'::jsonb, 'Müəssisəyə daxil olan və çıxan sənədlərin qeydiyyatını aparmaq, rəsmi yazışmaları tərtib etmək, icra nəzarətini təşkil etmək və cari arxivi formalaşdırmaq', 'Düzgün cavab: B) Müəssisəyə daxil olan və çıxan sənədlərin qeydiyyatını aparmaq, rəsmi yazışmalar', '', 1, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8ff2ba2e-d816-4460-bc77-c55c86756aa9', 'baaae6e4-5b23-469e-8d46-c96d6bb4d70e', 'ka', 'რა არის მდივან-მემანქანის ძირითადი ფუნქცია ზოგადსაგანმანათლებლო დაწესებულებაში საქმისწარმოებისა და დოკუმენტბრუნვის ორგანიზებაში?', '["მოსწავლეთა გაკვეთილებზე დასწრებისა და საგნობრივი მიღწევების მონიტორინგი ელექტრონულ სისტემაში და მშობლებისთვის ანგარიშის წარდგენა", "დაწესებულებაში შემოსული და გასული დოკუმენტების რეგისტრაცია, ოფიციალური მიმოწერის შედგენა, შესრულების კონტროლის ორგანიზება და მიმდინარე არქივის ფორმირება", "სკოლის საფინანსო-სამეურნეო საქმიანობის მართვა, საბიუჯეტო ხარჯთაღრიცხვის შედგენა და სატენდერო დოკუმენტაციის მომზადება", "სკოლის უსაფრთხოების სისტემებისა და გათბობა-კომუნიკაციის მოწყობილობების ტექნიკური გამართულობის კონტროლი", "სასწავლო გეგმებისა და შემაჯამებელი შეფასების ცხრილების მეთოდიკური ექსპერტიზის ჩატარება და პედაგოგიური საბჭოსთვის წარდგენა"]'::jsonb, 'დაწესებულებაში შემოსული და გასული დოკუმენტების რეგისტრაცია, ოფიციალური მიმოწერის შედგენა, შესრულების კონტროლის ორგანიზება და მიმდინარე არქივის ფორმირება', 'Düzgün cavab: B) დაწესებულებაში შემოსული და გასული დოკუმენტების რეგისტრაცია, ოფიციალური მიმოწერის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('232e97d7-2b96-4f8d-9410-46224852ea25', '1940e17b-2e5d-4863-83aa-0206aad16aa3', '“Ümumi təhsil müəssisəsinə aid tədris-pedaqoji sənədlərin aparılması və saxlanılması haqqında Təlimat”a əsasən, məktəbə daxil olan bütün rəsmi məktub və sənədlər hansı uçot sənədində qeydə alınır?', 'multiple_choice', '["Tədris-pedaqoji sənədlərin Təftiş Reyestrində", "Daxil olan sənədlərin qeydiyyatı jurnalında (elektron və ya kağız formada)", "Məktəb Şurasının Qərarlarının Protokol Dəftərində", "Gələn qonaqların və valideyn müraciətlərinin qeydiyyat kitabında", "Ümumi təhsil müəssisəsinin Daxili Nəzarət Jurnalında"]'::jsonb, 'Daxil olan sənədlərin qeydiyyatı jurnalında (elektron və ya kağız formada)', 'Düzgün cavab: B) Daxil olan sənədlərin qeydiyyatı jurnalında (elektron və ya kağız formada)', '', 2, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1261c83f-e36d-462e-ac0a-16e1fa569b06', '232e97d7-2b96-4f8d-9410-46224852ea25', 'ka', '„ზოგადსაგანმანათლებლო დაწესებულების სასწავლო-პედაგოგიური დოკუმენტების წარმოებისა და შენახვის შესახებ ინსტრუქციის“ თანახმად, რომელ სააღრიცხვო დოკუმენტში რეგისტრირდება სკოლაში შემოსული ყველა ოფიციალური წერილი და დოკუმენტი?', '["ზოგადსაგანმანათლებლო დაწესებულების შიდა კონტროლის ჟურნალში", "შემოსული დოკუმენტების სარეგისტრაციო ჟურნალში (ელექტრონული ან ქაღალდის ფორმით)", "მოსულ სტუმართა და მშობელთა მომართვების სარეგისტრაციო წიგნში", "სასწავლო-პედაგოგიური დოკუმენტების ინსპექტირების რეესტრში", "სასკოლო საბჭოს გადაწყვეტილებათა ოქმების რვეულში"]'::jsonb, 'შემოსული დოკუმენტების სარეგისტრაციო ჟურნალში (ელექტრონული ან ქაღალდის ფორმით)', 'Düzgün cavab: B) შემოსული დოკუმენტების სარეგისტრაციო ჟურნალში (ელექტრონული ან ქაღალდის ფორმით)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ef596068-d3c3-45d9-9780-cffa0ed66ce3', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Təhsil müəssisəsindən digər təşkilat və qurumlara göndərilən (çıxan) rəsmi sənədlərin qeydiyyat indeksi və nömrəsi necə müəyyən edilir?', 'multiple_choice', '["Göndərilmə üsulu və təcili icra qrifinə uyğun şərti kodlaşdırma ilə", "Sənədin hazırlandığı kompüterin IP ünvanı və elektron imza kodu ilə", "Çıxan sənədlərin qeydiyyatı jurnalındakı sıra nömrəsi, işin nomenklatura indeksi və tarix əsasında", "Təhsil Nazirliyinin vahid elektron reyestr nömrəsi və sənədin həcmi ilə", "Sənədi imzalayan direktorun şəxsi kadr nömrəsi və göndərilən qurumun VÖEN-i ilə"]'::jsonb, 'Çıxan sənədlərin qeydiyyatı jurnalındakı sıra nömrəsi, işin nomenklatura indeksi və tarix əsasında', 'Düzgün cavab: C) Çıxan sənədlərin qeydiyyatı jurnalındakı sıra nömrəsi, işin nomenklatura indeksi', '', 3, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('021fd8d4-b109-4a9a-8ede-b311096699c6', 'ef596068-d3c3-45d9-9780-cffa0ed66ce3', 'ka', 'როგორ განისაზღვრება საგანმანათლებლო დაწესებულებიდან სხვა ორგანიზაციებსა და უწყებებში გასაგზავნი (გასული) ოფიციალური დოკუმენტების სარეგისტრაციო ინდექსი და ნომერი?', '["გაგზავნის ხერხისა და სასწრაფო შესრულების გრიფის შესაბამისი პირობითი კოდირებით", "განათლების სამინისტროს ერთიანი ელექტრონული რეესტრის ნომრითა და დოკუმენტის მოცულობით", "გასული დოკუმენტების სარეგისტრაციო ჟურნალში რიგითი ნომრის, საქმეთა ნომენკლატურის ინდექსისა და თარიღის საფუძველზე", "დოკუმენტის ხელმომწერი დირექტორის პირადი საკადრო ნომრითა და ადრესატი უწყების საიდენტიფიკაციო კოდით", "იმ კომპიუტერის IP მისამართით, რომელზეც დოკუმენტი მომზადდა, და ელექტრონული ხელმოწერის კოდით"]'::jsonb, 'გასული დოკუმენტების სარეგისტრაციო ჟურნალში რიგითი ნომრის, საქმეთა ნომენკლატურის ინდექსისა და თარიღის საფუძველზე', 'Düzgün cavab: C) გასული დოკუმენტების სარეგისტრაციო ჟურნალში რიგითი ნომრის, საქმეთა ნომენკლატურის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8ca4d7a3-1fb3-403f-b2b6-79c2bef6c1f1', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Ümumi təhsil müəssisəsində direktor tərəfindən imzalanan daxili inzibati əmrlər əsasən hansı iki əsas kateqoriyaya bölünür?', 'multiple_choice', '["Daimi əmrlər və Müvəqqəti sərəncamlar", "Pedaqoji heyət üzrə əmrlər və Texniki heyət üzrə əmrlər", "Əsas fəaliyyət (ümumi tədris-təşkilati) üzrə əmrlər və Şəxsi heyət (kadr) üzrə əmrlər", "Tədris-tərbiyə əmrləri və Maliyyə-təsərrüfat əmrləri", "Ümumi orta təhsil üzrə əmrlər və Tam orta təhsil üzrə əmrlər"]'::jsonb, 'Əsas fəaliyyət (ümumi tədris-təşkilati) üzrə əmrlər və Şəxsi heyət (kadr) üzrə əmrlər', 'Düzgün cavab: C) Əsas fəaliyyət (ümumi tədris-təşkilati) üzrə əmrlər və Şəxsi heyət (kadr) üzrə ə', '', 4, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3614b728-0561-4d80-8801-b550e550a99b', '8ca4d7a3-1fb3-403f-b2b6-79c2bef6c1f1', 'ka', 'ზოგადსაგანმანათლებლო დაწესებულებაში დირექტორის მიერ გამოცემული შიდა ადმინისტრაციული ბრძანებები ძირითადად რომელ ორ ძირითად კატეგორიად იყოფა?', '["პედაგოგიური პერსონალის ბრძანებები და ტექნიკური პერსონალის ბრძანებები", "მუდმივი ბრძანებები და დროებითი განკარგულებები", "ძირითადი საქმიანობის (ზოგადი სასწავლო-ორგანიზაციული) ბრძანებები და პირადი შემადგენლობის (საკადრო) ბრძანებები", "სასწავლო-აღმზრდელობითი ბრძანებები და საფინანსო-სამეურნეო ბრძანებები", "საბაზო ზოგადი განათლების ბრძანებები და სრული ზოგადი განათლების ბრძანებები"]'::jsonb, 'ძირითადი საქმიანობის (ზოგადი სასწავლო-ორგანიზაციული) ბრძანებები და პირადი შემადგენლობის (საკადრო) ბრძანებები', 'Düzgün cavab: C) ძირითადი საქმიანობის (ზოგადი სასწავლო-ორგანიზაციული) ბრძანებები და პირადი შემადგ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f7dd78f1-2e75-4702-a656-05ad50f60372', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Məktəbə birinci sinfə və ya digər siniflərə qəbul olunan hər bir şagird haqqında ilkin məlumatlar hansı əsas dövlət uçot kitabına daxil edilir?', 'multiple_choice', '["Sinif Jurnalının Titul Vərəqinə", "Məktəbə Qəbul Əmrlərinin Reyestr Kitabına", "Şagirdlərin Şəxsi İşlərinin Qeydiyyat Jurnalına", "Təhsilalanların Fərdi İnkişaf Kartotekasına", "Şagirdlərin Əlifba kitabına (Əlifba uçot kitabı / elektron əlifba)"]'::jsonb, 'Şagirdlərin Əlifba kitabına (Əlifba uçot kitabı / elektron əlifba)', 'Düzgün cavab: E) Şagirdlərin Əlifba kitabına (Əlifba uçot kitabı / elektron əlifba)', '', 5, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ff1b6e12-75ad-406e-ac05-ff4f68c1fed1', 'f7dd78f1-2e75-4702-a656-05ad50f60372', 'ka', 'რომელ ძირითად სახელმწიფო სააღრიცხვო წიგნში შედის პირველადი მონაცემები სკოლაში პირველ ან სხვა კლასებში მიღებული თითოეული მოსწავლის შესახებ?', '["მოსწავლეთა ინდივიდუალური განვითარების ბარათებში", "სკოლაში მიღების ბრძანებათა რეესტრის წიგნში", "საკლასო ჟურნალის თავფურცელზე", "მოსწავლეთა პირადი საქმეების სარეგისტრაციო ჟურნალში", "მოსწავლეთა ანბანურ წიგნში (ანბანური აღრიცხვის წიგნი / ელექტრონული ანბანი)"]'::jsonb, 'მოსწავლეთა ანბანურ წიგნში (ანბანური აღრიცხვის წიგნი / ელექტრონული ანბანი)', 'Düzgün cavab: E) მოსწავლეთა ანბანურ წიგნში (ანბანური აღრიცხვის წიგნი / ელექტრონული ანბანი)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b0bf465f-18cf-4488-83b5-2a35c1b6efd7', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Ümumi təhsil müəssisəsində təhsilalanın Şəxsi işi (şagird qovluğu) hansı müddətdə məktəbdə mühafizə olunur?', 'multiple_choice', '["Yalnız ibtidai təhsil səviyyəsi başa çatanadək saxlanılır, sonra arxivə verilir", "Hər tədris ilinin sonunda bağlanılır və növbəti il üçün yeni qovluq açılır", "Şagird məktəbə qəbul olunduqda açılır və məktəbi bitirənədək, başqa məktəbə köçənədək və ya xaric olunanadək saxlanılır", "Şagirdin valideyninin ərizəsinə əsasən istənilən vaxt məhv edilir", "Ümumi orta təhsil başa çatdıqdan sonra 5 il müddətində saxlanılır"]'::jsonb, 'Şagird məktəbə qəbul olunduqda açılır və məktəbi bitirənədək, başqa məktəbə köçənədək və ya xaric olunanadək saxlanılır', 'Düzgün cavab: C) Şagird məktəbə qəbul olunduqda açılır və məktəbi bitirənədək, başqa məktəbə köçə', '', 6, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b7bb9f69-e002-428a-bfd9-39a477a38500', 'b0bf465f-18cf-4488-83b5-2a35c1b6efd7', 'ka', 'რა ვადით ინახება სკოლაში მოსწავლის პირადი საქმე ზოგადსაგანმანათლებლო დაწესებულებაში?', '["საბაზო განათლების დასრულების შემდეგ 5 წლის განმავლობაში", "მოსწავლის მშობლის განცხადების საფუძველზე ნებისმიერ დროს ნადგურდება", "იხსნება მოსწავლის სკოლაში მიღებისას და ინახება სკოლის დამთავრებამდე, სხვა სკოლაში გადასვლამდე ან გარიცხვამდე", "ინახება მხოლოდ დაწყებითი განათლების საფეხურის დასრულებამდე, შემდეგ ბარდება არქივს", "იხურება ყოველი სასწავლო წლის ბოლოს და მომდევნო წლისთვის იხსნება ახალი საქაღალდე"]'::jsonb, 'იხსნება მოსწავლის სკოლაში მიღებისას და ინახება სკოლის დამთავრებამდე, სხვა სკოლაში გადასვლამდე ან გარიცხვამდე', 'Düzgün cavab: C) იხსნება მოსწავლის სკოლაში მიღებისას და ინახება სკოლის დამთავრებამდე, სხვა სკოლაშ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2ceb7aed-c74b-4166-8831-4a0b6f17f777', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Şagird digər ümumi təhsil müəssisəsinə yerdəyişmə etdikdə onun şəxsi işinin verilməsi hansı hüquqi əsasla həyata keçirilir?', 'multiple_choice', '["Sinif rəhbərinin yazılı təqdimatı və Pedaqoji Şuranın razılığı əsasında", "Rayon təhsil sektorunun şifahi tapşırığı və elektron sistemdə qeydiyyat əsasında", "Məktəb psixoloqunun rəyi və şagirdin ərizəsi əsasında", "Yeni təhsil müəssisəsindən verilmiş rəsmi arayış (qəbul haqqında təsdiq bildirişi) və direktorun müvafiq əmri əsasında, valideyn ərizəsi ilə", "Valideynin şifahi müraciəti və köhnə məktəbin möhürü ilə təsdiq edilərək"]'::jsonb, 'Yeni təhsil müəssisəsindən verilmiş rəsmi arayış (qəbul haqqında təsdiq bildirişi) və direktorun müvafiq əmri əsasında, valideyn ərizəsi ilə', 'Düzgün cavab: D) Yeni təhsil müəssisəsindən verilmiş rəsmi arayış (qəbul haqqında təsdiq bildiriş', '', 7, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e842989e-3bba-4708-a35e-82357b39b47b', '2ceb7aed-c74b-4166-8831-4a0b6f17f777', 'ka', 'რა სამართლებრივი საფუძვლით გაიცემა მოსწავლის პირადი საქმე სხვა ზოგადსაგანმანათლებლო დაწესებულებაში გადასვლისას (მობილობისას)?', '["სკოლის ფსიქოლოგის დასკვნისა და მოსწავლის განცხადების საფუძველზე", "რაიონული საგანმანათლებლო რესურსცენტრის ზეპირი დავალებისა და ელექტრონულ სისტემაში რეგისტრაციის საფუძველზე", "მშობლის ზეპირი მიმართვისა და ძველი სკოლის ბეჭდით დამოწმების საფუძველზე", "ახალი საგანმანათლებლო დაწესებულების ოფიციალური ცნობის (მიღების დამადასტურებელი შეტყობინების), დირექტორის შესაბამისი ბრძანებისა და მშობლის განცხადების საფუძველზე", "დამრიგებლის წერილობითი წარდგინებისა და პედაგოგიური საბჭოს თანხმობის საფუძველზე"]'::jsonb, 'ახალი საგანმანათლებლო დაწესებულების ოფიციალური ცნობის (მიღების დამადასტურებელი შეტყობინების), დირექტორის შესაბამისი ბრძანებისა და მშობლის განცხადების საფუძველზე', 'Düzgün cavab: D) ახალი საგანმანათლებლო დაწესებულების ოფიციალური ცნობის (მიღების დამადასტურებელი შ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c8b292e8-94b4-4a22-b4bc-d8fac0b48c45', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Dövlət idarəçiliyində və kargüzarlıqda sənədin ''Rekviziti'' anlayışı nəyi ifadə edir?', 'multiple_choice', '["Sənədin tərcümə olunduğu dillərin siyahısını və tərcüməçinin adını", "Sənədin elektron variantının fayl ölçüsünü və formatını bildirən texniki göstəriciləri", "Sənədin hüquqi qüvvəyə malik olması üçün onda əks olunan məcburi rəsmi elementləri (təşkilatın adı, tarix, nömrə, başlıq, mətn, imza, möhür və s.)", "Sənədin göndərildiyi ünvanın poçt indeksi və çatdırılma marşrutu barədə məlumatları", "Sənədin arxivdə saxlanma müddətini və məxfilik dərəcəsini göstərən şərti nişanları"]'::jsonb, 'Sənədin hüquqi qüvvəyə malik olması üçün onda əks olunan məcburi rəsmi elementləri (təşkilatın adı, tarix, nömrə, başlıq, mətn, imza, möhür və s.)', 'Düzgün cavab: C) Sənədin hüquqi qüvvəyə malik olması üçün onda əks olunan məcburi rəsmi elementlə', '', 8, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4e828415-b7c7-46e0-8854-f89ca32945f8', 'c8b292e8-94b4-4a22-b4bc-d8fac0b48c45', 'ka', 'რას გამოხატავს დოკუმენტის „რეკვიზიტის“ ცნება სახელმწიფო მმართველობასა და საქმისწარმოებაში?', '["ტექნიკურ მაჩვენებლებს, რომლებიც მიუთითებს დოკუმენტის ელექტრონული ვერსიის ფაილის ზომასა და ფორმატზე", "იმ ენების ჩამონათვალსა და მთარგმნელის სახელს, რომლებზეც დოკუმენტი ითარგმნა", "სავალდებულო ოფიციალურ ელემენტებს (ორგანიზაციის დასახელება, თარიღი, ნომერი, სათაური, ტექსტი, ხელმოწერა, ბეჭედი და ა.შ.), რომლებიც ასახულია დოკუმენტში მისი იურიდიული ძალის უზრუნველსაყოფად", "პირობით ნიშნებს, რომლებიც მიუთითებს დოკუმენტის არქივში შენახვის ვადასა და საიდუმლოების გრიფზე", "მონაცემებს საფოსტო ინდექსისა და მიტანის მარშრუტის შესახებ იმ მისამართზე, სადაც დოკუმენტი გაიგზავნა"]'::jsonb, 'სავალდებულო ოფიციალურ ელემენტებს (ორგანიზაციის დასახელება, თარიღი, ნომერი, სათაური, ტექსტი, ხელმოწერა, ბეჭედი და ა.შ.), რომლებიც ასახულია დოკუმენტში მისი იურიდიული ძალის უზრუნველსაყოფად', 'Düzgün cavab: C) სავალდებულო ოფიციალურ ელემენტებს (ორგანიზაციის დასახელება, თარიღი, ნომერი, სათაუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1e44f024-ed00-4dbf-b8b1-b2f041fb56c7', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Sənədin rəsmi təsdiqi üçün onun üzərinə vurulan dairəvi gerbli möhür hansı qaydada yerləşdirilməlidir?', 'multiple_choice', '["Yalnız əlavələrin (qoşmaların) hər bir səhifəsinin aşağı küncünə", "Vəzifəli şəxsin imzasının və adının üzərini tam örtmədən, imzanın müəyyən hissəsini və vəzifə adını əhatə edəcək şəkildə, aydın oxunacaq formada", "Sənədin mətn hissəsinin ortasına, əsas məlumatı örtəcək şəkildə", "Sənədin yuxarı sağ küncündə, təsdiq qrifinin birbaşa üzərinə", "Sənədin arxa səhifəsinə, qeydiyyat ştampının üzərinə"]'::jsonb, 'Vəzifəli şəxsin imzasının və adının üzərini tam örtmədən, imzanın müəyyən hissəsini və vəzifə adını əhatə edəcək şəkildə, aydın oxunacaq formada', 'Düzgün cavab: B) Vəzifəli şəxsin imzasının və adının üzərini tam örtmədən, imzanın müəyyən hissəs', '', 9, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3bb78486-22e4-4e6b-9708-19fab17637b3', '1e44f024-ed00-4dbf-b8b1-b2f041fb56c7', 'ka', 'რა წესით უნდა დაისვას დოკუმენტის ოფიციალური დამოწმებისთვის მრგვალი გერბიანი ბეჭედი?', '["დოკუმენტის ტექსტური ნაწილის შუაში, ძირითადი ინფორმაციის დაფარვით", "თანამდებობის პირის ხელმოწერისა და სახელის სრულად დაუფარავად, ისე, რომ მოიცავდეს ხელმოწერის გარკვეულ ნაწილსა და თანამდებობის დასახელებას, მკაფიოდ წაკითხვადი ფორმით", "დოკუმენტის უკანა გვერდზე, სარეგისტრაციო შტამპის ზემოდან", "დოკუმენტის ზედა მარჯვენა კუთხეში, უშუალოდ დამტკიცების გრიფზე", "მხოლოდ დანართების თითოეული გვერდის ქვედა კუთხეში"]'::jsonb, 'თანამდებობის პირის ხელმოწერისა და სახელის სრულად დაუფარავად, ისე, რომ მოიცავდეს ხელმოწერის გარკვეულ ნაწილსა და თანამდებობის დასახელებას, მკაფიოდ წაკითხვადი ფორმით', 'Düzgün cavab: B) თანამდებობის პირის ხელმოწერისა და სახელის სრულად დაუფარავად, ისე, რომ მოიცავდეს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9a064c9c-8158-4391-abc6-85f73207a6bc', '1940e17b-2e5d-4863-83aa-0206aad16aa3', '“Vətəndaşların müraciətləri haqqında” AR Qanununa əsasən, məktəbə daxil olmuş vətəndaş müraciətlərinə hansı müddətdə baxılmalıdır?', 'multiple_choice', '["Müraciətin həcmindən asılı olaraq 20 təqvim günü, kollektiv müraciətlərə 45 təqvim günü ərzində", "Bütün kateqoriyalardan olan müraciətlərə 7 iş günü ərzində, təxirəsalınmaz hallarda 3 iş günü ərzində", "Vətəndaşın statusundan asılı olaraq 10-20 iş günü ərzində, valideyn müraciətlərinə 5 iş günü ərzində", "Təhsil müəssisəsi rəhbərinin təyin etdiyi vətəndaş qəbulu gününə qədər", "Əlavə öyrənilmə və yoxlama tələb olunmadıqda 15 iş günü, əlavə araşdırma tələb olunduqda isə 30 iş günü ərzində"]'::jsonb, 'Əlavə öyrənilmə və yoxlama tələb olunmadıqda 15 iş günü, əlavə araşdırma tələb olunduqda isə 30 iş günü ərzində', 'Düzgün cavab: E) Əlavə öyrənilmə və yoxlama tələb olunmadıqda 15 iş günü, əlavə araşdırma tələb o', '', 10, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('88c0671f-faed-4098-84cf-94902b02de80', '9a064c9c-8158-4391-abc6-85f73207a6bc', 'ka', 'კანონის „მოქალაქეთა მომართვების შესახებ“ თანახმად, რა ვადაში უნდა განიხილოს სკოლაში შემოსული მოქალაქეთა მომართვები?', '["მომართვის მოცულობის მიხედვით 20 კალენდარულ დღეში, კოლექტიური მომართვები 45 კალენდარულ დღეში", "ყველა კატეგორიის მომართვა 7 სამუშაო დღეში, გადაუდებელ შემთხვევებში 3 სამუშაო დღეში", "მოქალაქის სტატუსის მიხედვით 10-20 სამუშაო დღეში, მშობელთა მომართვები 5 სამუშაო დღეში", "საგანმანათლებლო დაწესებულების ხელმძღვანელის მიერ დანიშნულ მოქალაქეთა მიღების დღემდე", "თუ დამატებითი შესწავლა და შემოწმება არ მოითხოვება – 15 სამუშაო დღეში, ხოლო დამატებითი მოკვლევის საჭიროებისას – 30 სამუშაო დღეში, ვადის გაგრძელების შესახებ შეტყობინებით"]'::jsonb, 'თუ დამატებითი შესწავლა და შემოწმება არ მოითხოვება – 15 სამუშაო დღეში, ხოლო დამატებითი მოკვლევის საჭიროებისას – 30 სამუშაო დღეში, ვადის გაგრძელების შესახებ შეტყობინებით', 'Düzgün cavab: E) თუ დამატებითი შესწავლა და შემოწმება არ მოითხოვება – 15 სამუშაო დღეში, ხოლო დამატ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bc9808fe-43b6-4da0-b281-93b2ad25f7d2', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Təhsil müəssisəsində Kargüzarlıq Nomenklaturasının əsas təyinatı nədir?', 'multiple_choice', '["Təhsilalanların davamiyyət və qiymət göstəricilərinin vahid elektron bazası", "Müəssisədə yaranan bütün sənəd qovluqlarının (işlərin) saxlanma müddətləri göstərilməklə tərtib edilmiş sistemləşdirilmiş başlıqlar siyahısı", "Təsərrüfat mallarının və avadanlıqların inventar nömrələrinin qeydiyyat kitabı", "Pedaqoji kollektivin dərs yükünün və fənlər üzrə bölgüsünün təsdiq edilmiş siyahısı", "Müəssisənin illik maliyyə xərcləri smetasının və satınalmalarının planlaşdırılması cədvəli"]'::jsonb, 'Müəssisədə yaranan bütün sənəd qovluqlarının (işlərin) saxlanma müddətləri göstərilməklə tərtib edilmiş sistemləşdirilmiş başlıqlar siyahısı', 'Düzgün cavab: B) Müəssisədə yaranan bütün sənəd qovluqlarının (işlərin) saxlanma müddətləri göstə', '', 11, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('31a371c6-17be-489d-b21a-ecb8c1062edf', 'bc9808fe-43b6-4da0-b281-93b2ad25f7d2', 'ka', 'რა არის საქმეთა ნომენკლატურის ძირითადი დანიშნულება საგანმანათლებლო დაწესებულებაში?', '["პედაგოგიური კოლექტივის საათობრივი დატვირთვისა და საგნების მიხედვით განაწილების დამტკიცებული სია", "დაწესებულებაში შექმნილი ყველა საქმის (საქაღალდის) სისტემატიზებული სათაურების ნუსხა მათი შენახვის ვადების მითითებით", "სამეურნეო საქონლისა და აღჭურვილობის საინვენტარო ნომრების სარეგისტრაციო წიგნი", "დაწესებულების წლიური ფინანსური ხარჯთაღრიცხვისა და შესყიდვების დაგეგმვის ცხრილი", "მოსწავლეთა დასწრებისა და შეფასების მაჩვენებლების ერთიანი ელექტრონული ბაზა"]'::jsonb, 'დაწესებულებაში შექმნილი ყველა საქმის (საქაღალდის) სისტემატიზებული სათაურების ნუსხა მათი შენახვის ვადების მითითებით', 'Düzgün cavab: B) დაწესებულებაში შექმნილი ყველა საქმის (საქაღალდის) სისტემატიზებული სათაურების ნუს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5a713294-f3f1-4024-86ef-cc73123879c3', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Ümumi təhsil müəssisəsində Şəxsi heyət (kadr) üzrə əmrlər və işçilərin şəxsi vərəqələri arxivdə neçə il saxlanmalıdır?', 'multiple_choice', '["25 il müddətində", "50 il müddətində", "10 il müddətində", "75 il müddətində (uzunmüddətli saxlanma kateqoriyası)", "5 il müddətində"]'::jsonb, '75 il müddətində (uzunmüddətli saxlanma kateqoriyası)', 'Düzgün cavab: D) 75 il müddətində (uzunmüddətli saxlanma kateqoriyası)', '', 12, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('db29a17f-2d2a-4cdf-bdaf-f50fb2f0ca07', '5a713294-f3f1-4024-86ef-cc73123879c3', 'ka', 'რამდენი წელი უნდა ინახებოდეს არქივში პირადი შემადგენლობის (საკადრო) ბრძანებები და თანამშრომელთა პირადი ბარათები ზოგადსაგანმანათლებლო დაწესებულებაში?', '["10 წლის განმავლობაში, შემდეგ განადგურების აქტით", "25 წლის განმავლობაში, შემდეგ საექსპერტო კომისიის გადაწყვეტილებით", "5 წლის განმავლობაში, საგანმანათლებლო დაწესებულების ლიკვიდაციამდე", "75 წლის განმავლობაში (ხანგრძლივი შენახვის კატეგორია)", "50 წლის განმავლობაში, სახელმწიფო არქივში ჩაბარებამდე"]'::jsonb, '75 წლის განმავლობაში (ხანგრძლივი შენახვის კატეგორია)', 'Düzgün cavab: D) 75 წლის განმავლობაში (ხანგრძლივი შენახვის კატეგორია)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ced99ecd-aa1c-4076-a737-a5cb06608e06', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Məktəbi bitirən məzunlara dövlət nümunəli təhsil sənədlərinin (attestatların) verilməsi hansı rəsmi sənəddə qeydə alınır?', 'multiple_choice', '["Məzunların fərdi nailiyyətlərinin yekun protokolunda", "Məktəbin illik hesabat statistikasında", "Sinif jurnallarının buraxılış vərəqlərində", "Pedaqoji Şuranın buraxılış qərarlarının qeydiyyat dəftərində", "Attestatların (şəhadətnamələrin) verilməsi və uçotu kitabında (ciddi hesabat sənədi)"]'::jsonb, 'Attestatların (şəhadətnamələrin) verilməsi və uçotu kitabında (ciddi hesabat sənədi)', 'Düzgün cavab: E) Attestatların (şəhadətnamələrin) verilməsi və uçotu kitabında (ciddi hesabat sən', '', 13, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ac7dacff-552d-4cad-9b5f-4f41d0caa9ff', 'ced99ecd-aa1c-4076-a737-a5cb06608e06', 'ka', 'რომელ ოფიციალურ დოკუმენტში რეგისტრირდება სკოლის კურსდამთავრებულთათვის სახელმწიფო ნიმუშის განათლების დამადასტურებელი დოკუმენტების (ატესტატების) გაცემა?', '["სკოლის წლიურ სტატისტიკურ ანგარიშში", "კურსდამთავრებულთა ინდივიდუალური მიღწევების შემაჯამებელ ოქმში", "საკლასო ჟურნალების გამოსაშვებ ფურცლებში", "პედაგოგიური საბჭოს გამოსაშვებ გადაწყვეტილებათა სარეგისტრაციო რვეულში", "ატესტატების (მოწმობების) გაცემისა და აღრიცხვის წიგნში (მკაცრი აღრიცხვის სპეციალური დოკუმენტი)"]'::jsonb, 'ატესტატების (მოწმობების) გაცემისა და აღრიცხვის წიგნში (მკაცრი აღრიცხვის სპეციალური დოკუმენტი)', 'Düzgün cavab: E) ატესტატების (მოწმობების) გაცემისა და აღრიცხვის წიგნში (მკაცრი აღრიცხვის სპეციალუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('74273f58-bda5-4faa-8c85-f4c1b80a1507', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Rəsmi tədris-pedaqoji və kargüzarlıq sənədlərində düzəlişlərin edilməsi qaydası ilə bağlı hansı hüquqi norma doğrudur?', 'multiple_choice', '["Ciddi hesabat və rəsmi sənədlərdə silinməyə, korrektorla örtülməyə yol verilmir; zəruri düzəliş səhv sözün üstündən bir xətt çəkilərək düzgünü yazılmaqla, müvafiq vəzifəli şəxsin imzası və möhürü ilə təsdiqlənir", "Səhv qeydin üzəri qalın xətlə qaralanaraq heç bir əlavə qeyd olmadan saxlanılır", "Səhv məlumat olan vərəq sənəddən çıxarılır və nömrələnmədən yeni vərəqlə əvəz olunur", "İstənilən düzəliş katibənin fərdi qeydi ilə sənədin kənarında sərbəst aparıla bilər", "Səhv yazılmış sözün üzərindən xətt çəkilib yanına düzgün variant yazılır, lakin imza və möhür tələb olunmur"]'::jsonb, 'Ciddi hesabat və rəsmi sənədlərdə silinməyə, korrektorla örtülməyə yol verilmir; zəruri düzəliş səhv sözün üstündən bir xətt çəkilərək düzgünü yazılmaqla, müvafiq vəzifəli şəxsin imzası və möhürü ilə təsdiqlənir', 'Düzgün cavab: A) Ciddi hesabat və rəsmi sənədlərdə silinməyə, korrektorla örtülməyə yol verilmir;', '', 14, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6d6e2b33-9dfa-4d8b-bd27-7efb49e9ef0a', '74273f58-bda5-4faa-8c85-f4c1b80a1507', 'ka', 'რომელი მოსაზრებაა სწორი ოფიციალურ სასწავლო-პედაგოგიურ და საქმისწარმოების დოკუმენტებში შესწორებების შეტანის წესთან დაკავშირებით?', '["მკაცრი აღრიცხვისა და ოფიციალურ დოკუმენტებში დაუშვებელია წაშლა, კორექტორით გადაფარვა და უკანონო გადახაზვა; აუცილებელი შესწორება კეთდება დადგენილი წესით გადახაზვითა და დამოწმებით", "შეცდომის შემცველი ფურცელი ამოიღება დოკუმენტიდან და დაუნომრავად იცვლება ახალი ფურცლით", "შეცდომით დაწერილ სიტყვას გადაესმება ერთი ხაზი და გვერდით იწერება სწორი ვარიანტი, თუმცა ხელმოწერა და ბეჭედი არ მოითხოვება", "შეცდომით გაკეთებული ჩანაწერი იმალება სქელი ხაზით ყოველგვარი დამატებითი მინაწერის გარეშე", "ნებისმიერი შესწორება თავისუფლად შეიძლება განხორციელდეს მდივნის ინდივიდუალური მინაწერით დოკუმენტის კიდეზე"]'::jsonb, 'მკაცრი აღრიცხვისა და ოფიციალურ დოკუმენტებში დაუშვებელია წაშლა, კორექტორით გადაფარვა და უკანონო გადახაზვა; აუცილებელი შესწორება კეთდება დადგენილი წესით გადახაზვითა და დამოწმებით', 'Düzgün cavab: A) მკაცრი აღრიცხვისა და ოფიციალურ დოკუმენტებში დაუშვებელია წაშლა, კორექტორით გადაფა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f40ffee0-062f-4bf7-bf4f-c362ef158c3c', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Ümumi təhsil müəssisəsində Pedaqoji Şuranın iclas protokollarının rəsmiləşdirilməsi üzrə hansı tələb məcburidir?', 'multiple_choice', '["Protokol dəftərində yalnız qərarlar qeyd edilir, müzakirələr əks olunmur", "Protokollar yalnız elektron poçtda saxlanmalı, kağız nüsxə çıxarılmamalıdır", "Hər tədris ilinin sonunda köhnə dəftər məhv edilərək yenisi tərtib olunur", "Protokol dəftərinin səhifələri nömrələnməli, qaytanlanmalı, məktəb rəhbərinin imzası və möhürü ilə təsdiqlənməli və ardıcıl aparılmalıdır", "Protokollar ayrı-ayrı vərəqlərdə çap olunaraq plastik qovluqda saxlanılmalıdır"]'::jsonb, 'Protokol dəftərinin səhifələri nömrələnməli, qaytanlanmalı, məktəb rəhbərinin imzası və möhürü ilə təsdiqlənməli və ardıcıl aparılmalıdır', 'Düzgün cavab: D) Protokol dəftərinin səhifələri nömrələnməli, qaytanlanmalı, məktəb rəhbərinin im', '', 15, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a5fe594b-218a-4fee-8fda-ae8bd64cc6f7', 'f40ffee0-062f-4bf7-bf4f-c362ef158c3c', 'ka', 'რომელი მოთხოვნაა სავალდებულო ზოგადსაგანმანათლებლო დაწესებულებაში პედაგოგიური საბჭოს სხდომის ოქმების გაფორმებისას?', '["ყოველ სასწავლო წლის ბოლოს ძველი რვეული ნადგურდება და დგება ახალი", "ოქმები უნდა დაიბეჭდოს ცალკე ფურცლებზე და შეინახოს პლასტიკურ საქაღალდეში", "ოქმები უნდა შეინახოს მხოლოდ ელექტრონულ ფოსტაში და არ უნდა გაკეთდეს ქაღალდის ასლი", "ოქმების წიგნის გვერდები უნდა იყოს დანომრილი, ზონარგაყრილი, დამოწმებული სკოლის ხელმძღვანელის ხელმოწერითა და ბეჭდით და იწარმოებოდეს თანმიმდევრულად", "ოქმების წიგნში აღინიშნება მხოლოდ გადაწყვეტილებები, მსჯელობა არ აისახება"]'::jsonb, 'ოქმების წიგნის გვერდები უნდა იყოს დანომრილი, ზონარგაყრილი, დამოწმებული სკოლის ხელმძღვანელის ხელმოწერითა და ბეჭდით და იწარმოებოდეს თანმიმდევრულად', 'Düzgün cavab: D) ოქმების წიგნის გვერდები უნდა იყოს დანომრილი, ზონარგაყრილი, დამოწმებული სკოლის ხე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8a17593a-cb82-4bb3-ab92-7a53e25f4452', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Məktəbdə kargüzarlıq zamanı “Fərdi məlumatların qorunması haqqında” AR Qanununa əsasən katibə hansı hərəkətə **YOL VERMƏMƏLİDİR**?', 'multiple_choice', '["Şagirdlərin və ya işçilərin şəxsiyyət vəsiqəsi məlumatlarını, yaşayış ünvanlarını və sağlamlıq məlumatlarını kənar şəxslərə təqdim etmək və açıq paylaşmaq", "Daxil olan vətəndaş ərizələrini qeydiyyat jurnalında xronoloji ardıcıllıqla qeydə almaq", "Fərdi məlumatları xidməti kadr qovluqlarında və kilidli seyfdə mühafizə etmək", "Elektron bazada fərdi istifadəçi adı və şifrə ilə sənəd dövriyyəsini icra etmək", "Rəhbərliyin rəsmi tapşırığı ilə dövlət orqanlarına qanuni arayışları hazırlamaq"]'::jsonb, 'Şagirdlərin və ya işçilərin şəxsiyyət vəsiqəsi məlumatlarını, yaşayış ünvanlarını və sağlamlıq məlumatlarını kənar şəxslərə təqdim etmək və açıq paylaşmaq', 'Düzgün cavab: A) Şagirdlərin və ya işçilərin şəxsiyyət vəsiqəsi məlumatlarını, yaşayış ünvanların', '', 16, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3d698ee4-ec18-465b-b2b1-80e7b45b0fa8', '8a17593a-cb82-4bb3-ab92-7a53e25f4452', 'ka', 'სკოლაში საქმისწარმოებისას კანონის „პერსონალურ მონაცემთა დაცვის შესახებ“ თანახმად, რა ქმედება არ უნდა დაუშვას მდივანმა?', '["მოსწავლეთა ან თანამშრომელთა პირადობის მოწმობის მონაცემების, საცხოვრებელი მისამართებისა და ჯანმრთელობის შესახებ ინფორმაციის გარეშე პირებისთვის გადაცემა, საჯაროდ გაზიარება", "პერსონალური მონაცემების შენახვა სამსახურებრივ საკადრო საქაღალდეებსა და ჩაკეტილ სეიფში", "ხელმძღვანელობის ოფიციალური დავალებით სახელმწიფო ორგანოებისთვის კანონიერი ცნობების მომზადება", "ელექტრონულ ბაზაში ინდივიდუალური მომხმარებლის სახელითა და პაროლით დოკუმენტბრუნვის განხორციელება", "შემოსული მოქალაქეთა განცხადებების ქრონოლოგიური რეგისტრაცია სარეგისტრაციო ჟურნალში"]'::jsonb, 'მოსწავლეთა ან თანამშრომელთა პირადობის მოწმობის მონაცემების, საცხოვრებელი მისამართებისა და ჯანმრთელობის შესახებ ინფორმაციის გარეშე პირებისთვის გადაცემა, საჯაროდ გაზიარება', 'Düzgün cavab: A) მოსწავლეთა ან თანამშრომელთა პირადობის მოწმობის მონაცემების, საცხოვრებელი მისამარ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('496541da-96ae-4f6b-8357-2217f8c5722b', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Rəsmi sənədin surətinin əslinə tam uyğun olduğunu hüquqi cəhətdən təsdiqləyən qeyd hansı formada yazılmalıdır?', 'multiple_choice', '["“Təsdiq olunur” qrifı və Pedaqoji Şura katibinin imzası", "“Surətdir” qeydi və icraçının tabel nömrəsi", "“Yoxlanıldı” sözü, icraçının adı və e-poçt ünvanı", "“Əsli ilə düzdür” və ya “Düzdür” sözləri, vəzifə adı, şəxsi imza, ad-soyad, tarix və təşkilat möhürü", "“Məlumat üçün qəbul edildi” sözləri və sinif rəhbərinin imzası"]'::jsonb, '“Əsli ilə düzdür” və ya “Düzdür” sözləri, vəzifə adı, şəxsi imza, ad-soyad, tarix və təşkilat möhürü', 'Düzgün cavab: D) “Əsli ilə düzdür” və ya “Düzdür” sözləri, vəzifə adı, şəxsi imza, ad-soyad, tari', '', 17, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1dc9f221-0f46-42e7-9003-819567a62826', '496541da-96ae-4f6b-8357-2217f8c5722b', 'ka', 'რა ფორმით უნდა გაკეთდეს წარწერა, რომელიც ადასტურებს დოკუმენტის ასლის სრულ შესაბამისობას დედანთან?', '["სიტყვები „მიღებულია ცნობად“ და დამრიგებლის ხელმოწერა", "დამტკიცების გრიფი „მტკიცდება“ და პედაგოგიური საბჭოს მდივნის ხელმოწერა", "სიტყვა „შემოწმებულია“, შემსრულებლის სახელი და ელფოსტის მისამართი", "სიტყვები „დედანი სწორია“ ან „სწორია“, თანამდებობა, პირადი ხელმოწერა, სახელი და გვარი, თარიღი და ბეჭედი (საჭიროების შემთხვევაში)", "მინაწერი „ასლია“ და შემსრულებლის ტაბელის ნომერი"]'::jsonb, 'სიტყვები „დედანი სწორია“ ან „სწორია“, თანამდებობა, პირადი ხელმოწერა, სახელი და გვარი, თარიღი და ბეჭედი (საჭიროების შემთხვევაში)', 'Düzgün cavab: D) სიტყვები „დედანი სწორია“ ან „სწორია“, თანამდებობა, პირადი ხელმოწერა, სახელი და გ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('258905d5-fbed-421b-b82a-cd275fb129e4', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Elektron sənəd dövriyyəsi sistemində rəsmi sənədlərin hüquqi qüvvəsini təmin edən elektron imza vasitəsi hansıdır?', 'multiple_choice', '["Gücləndirilmiş elektron imza (ASAN İmza, SİMA İmza və ya Elektron İmza sertifikatı)", "Sənədin altında icraçının klaviaturada yazılmış adı və soyadı", "Sənədin skan edilmiş PDF surətinin sistemə yüklənməsi", "Sənədin tərtib olunduğu kompüterin statik IP ünvanı", "İstifadəçinin e-poçtuna göndərilən birdəfəlik SMS OTP kodu"]'::jsonb, 'Gücləndirilmiş elektron imza (ASAN İmza, SİMA İmza və ya Elektron İmza sertifikatı)', 'Düzgün cavab: A) Gücləndirilmiş elektron imza (ASAN İmza, SİMA İmza və ya Elektron İmza sertifika', '', 18, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b1e3fe92-065f-4e71-b11a-80ebf079505a', '258905d5-fbed-421b-b82a-cd275fb129e4', 'ka', 'დოკუმენტბრუნვის ელექტრონულ სისტემაში რომელი ელექტრონული ხელმოწერის საშუალება უზრუნველყოფს ოფიციალური დოკუმენტების იურიდიულ ძალას?', '["კვალიფიციური / გაძლიერებული ელექტრონული ხელმოწერა (ASAN İmza, SİMA İmza ან ელექტრონული ხელმოწერის სერტიფიკატი - E-GOV)", "მომხმარებლის ელფოსტაზე გაგზავნილი ერთჯერადი OTP კოდი", "დოკუმენტის სკანირებული ასლის სისტემაში ატვირთვა", "დოკუმენტის PDF ფორმატში გადაყვანა და ელექტრონულ საქაღალდეში დაარქივება", "იმ კომპიუტერის სტატიკური IP მისამართი, რომელზეც შედგენილია დოკუმენტი"]'::jsonb, 'კვალიფიციური / გაძლიერებული ელექტრონული ხელმოწერა (ASAN İmza, SİMA İmza ან ელექტრონული ხელმოწერის სერტიფიკატი - E-GOV)', 'Düzgün cavab: A) კვალიფიციური / გაძლიერებული ელექტრონული ხელმოწერა (ASAN İmza, SİMA İmza ან ელექტ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c4c3b378-8f4f-4cae-b8db-d6462399d847', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Məktəbə yeni qəbul olunan işçinin əmək müqaviləsi və işə qəbul əmri əsasında tərtib olunan əsas kadr uçot sənədi hansıdır?', 'multiple_choice', '["Pedaqoji kollektivin illik ixtisasartırma qeydiyyat vərəqəsi", "Həmkarlar İttifaqı Komitəsinin fərdi üzvlük kartı", "İşçinin Şəxsi işi və T-2 formalı şəxsi vərəqəsi (şəxsi kartı)", "Müəssisənin illik əməkhaqqı ödəniş və mükafatlandırma cədvəli", "Təhsilalanların illik fənn nailiyyətləri cədvəli"]'::jsonb, 'İşçinin Şəxsi işi və T-2 formalı şəxsi vərəqəsi (şəxsi kartı)', 'Düzgün cavab: C) İşçinin Şəxsi işi və T-2 formalı şəxsi vərəqəsi (şəxsi kartı)', '', 19, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('884f0d4b-a36b-4c01-a36a-dfc3f277f132', 'c4c3b378-8f4f-4cae-b8db-d6462399d847', 'ka', 'რომელია ძირითადი საკადრო სააღრიცხვო დოკუმენტი, რომელიც დგება სკოლაში ახლად მიღებული თანამშრომლის შრომითი ხელშეკრულებისა და სამუშაოზე მიღების ბრძანების საფუძველზე?', '["მოსწავლეთა წლიური საგნობრივი მიღწევების ცხრილი", "დაწესებულების წლიური ხელფასის გადახდისა და პრემიირების უწყისი", "თანამშრომლის პირადი საქმე და T-2 ფორმის პირადი ბარათი (სააღრიცხვო ბარათი)", "პროფკავშირის კომიტეტის ინდივიდუალური საწევრო ბარათი", "პედაგოგიური კოლექტივის კვალიფიკაციის ამაღლების წლიური სააღრიცხვო ფურცელი"]'::jsonb, 'თანამშრომლის პირადი საქმე და T-2 ფორმის პირადი ბარათი (სააღრიცხვო ბარათი)', 'Düzgün cavab: C) თანამშრომლის პირადი საქმე და T-2 ფორმის პირადი ბარათი (სააღრიცხვო ბარათი)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('734c831d-c91d-41a2-adbc-38369a51f19d', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Sənədlərin arxivləşdirilməsi zamanı işlərin formalaşdırılması qaydasına hansı tələb **AİD DEYİLDİR** (qadağandır)?', 'multiple_choice', '["Sənədlərin oxunmasını çətinləşdirəcək şəkildə üzərinə düzəliş boyası (korrektor) çəkilməsi, silinməsi və ya qaralanması", "Qovluğun daxilindəki vərəqlərin sağ yuxarı küncdən ardıcıl nömrələnməsi", "Qovluğun üz qabığında müəssisə adı, indeks və saxlanma müddətinin göstərilməsi", "Qovluqdakı sənədlərin xronoloji ardıcıllıqla sistemləşdirilməsi", "Qovluğun sonunda təsdiqedici vərəqin (içlik siyahısı) tərtib olunması"]'::jsonb, 'Sənədlərin oxunmasını çətinləşdirəcək şəkildə üzərinə düzəliş boyası (korrektor) çəkilməsi, silinməsi və ya qaralanması', 'Düzgün cavab: A) Sənədlərin oxunmasını çətinləşdirəcək şəkildə üzərinə düzəliş boyası (korrektor)', '', 20, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('55d6e479-29fe-4ee7-ae54-773bfb4ec25d', '734c831d-c91d-41a2-adbc-38369a51f19d', 'ka', 'დოკუმენტების დაარქივებისას საქმეთა ფორმირების წესს რომელი მოთხოვნა არ მიეკუთვნება?', '["დოკუმენტებზე კორექტორის გადასმა, წაშლა ან გადაშავება ისე, რომ გართულდეს მათი წაკითხვა", "საქაღალდის ბოლოს სადამოწმებო ფურცლის (შიდა აღწერის) შედგენა", "საქაღალდის ყდაზე დაწესებულების სახელწოდების, ინდექსისა და შენახვის ვადის მითითება", "საქაღალდეში არსებული ფურცლების დანომრვა ზედა მარჯვენა კუთხეში", "საქაღალდეში დოკუმენტების სისტემატიზაცია ქრონოლოგიური თანმიმდევრობით"]'::jsonb, 'დოკუმენტებზე კორექტორის გადასმა, წაშლა ან გადაშავება ისე, რომ გართულდეს მათი წაკითხვა', 'Düzgün cavab: A) დოკუმენტებზე კორექტორის გადასმა, წაშლა ან გადაშავება ისე, რომ გართულდეს მათი წაკ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b48731e3-edf1-482e-8caf-26f4054af662', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Xidməti ezamiyyətə göndərilən məktəb əməkdaşının ezamiyyə vəsiqəsində hansı məlumatların əks olunması məcburidir?', 'multiple_choice', '["İşçinin ailə tərkibi və əvvəlki iş yerləri üzrə ümumi əmək stajı", "İşçinin ali təhsil diplomunun nömrəsi və elmi ixtisas dərəcəsi", "Ezam olunduğu təşkilat və yer, məqsəd, müddət, gəlmə və getmə tarixləri üzrə qeydlər, vəzifəli şəxsin imzası və təşkilat möhürləri", "İşçinin fərdi bank rekvizitləri və son attestasiya balları", "Müəssisənin illik təsərrüfat büdcəsi və qeydiyyat kodu"]'::jsonb, 'Ezam olunduğu təşkilat və yer, məqsəd, müddət, gəlmə və getmə tarixləri üzrə qeydlər, vəzifəli şəxsin imzası və təşkilat möhürləri', 'Düzgün cavab: C) Ezam olunduğu təşkilat və yer, məqsəd, müddət, gəlmə və getmə tarixləri üzrə qey', '', 21, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a48310de-66d4-4d46-9a80-92d1d863b3ba', 'b48731e3-edf1-482e-8caf-26f4054af662', 'ka', 'რა ინფორმაციის ასახვაა სავალდებულო სამსახურებრივ მივლინებაში გაგზავნილი სკოლის თანამშრომლის სამივლინებო მოწმობაში?', '["თანამშრომლის დიპლომის ნომერი და საკვალიფიკაციო კატეგორია", "დაწესებულების წლიური სამეურნეო ბიუჯეტი და სარეგისტრაციო კოდი", "მივლინების ადგილი, მიზანი, ვადა, ჩასვლისა და გამგზავრების თარიღების აღნიშვნები, ხელმოწერა და ორგანიზაციის ბეჭდები", "თანამშრომლის ოჯახური შემადგენლობა და საერთო სტაჟი წინა სამუშაო ადგილების მიხედვით", "თანამშრომლის პირადი საბანკო რეკვიზიტები და ბოლო ატესტაციის ქულები"]'::jsonb, 'მივლინების ადგილი, მიზანი, ვადა, ჩასვლისა და გამგზავრების თარიღების აღნიშვნები, ხელმოწერა და ორგანიზაციის ბეჭდები', 'Düzgün cavab: C) მივლინების ადგილი, მიზანი, ვადა, ჩასვლისა და გამგზავრების თარიღების აღნიშვნები,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e86cf940-a68f-47a8-9169-64220537461a', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Təhsil müəssisəsinin blankında hazırlanan rəsmi məktubun sol aşağı küncündə icraçı haqqında hansı məlumat göstərilməlidir?', 'multiple_choice', '["İcraçının fərdi elektron imza şifrəsi və kompüter nömrəsi", "İcraçının ali təhsil aldığı müəssisənin adı və məzuniyyət ili", "İcraçının şəxsi FİN kodu və yaşayış yeri üzrə qeydiyyat ünvanı", "İcraçının ümumi əmək stajı və ictimai vəzifələri", "İcraçının soyadı, adı, atasının adı (inisial) və xidməti telefon nömrəsi, zərurət olduqda e-poçt ünvanı"]'::jsonb, 'İcraçının soyadı, adı, atasının adı (inisial) və xidməti telefon nömrəsi, zərurət olduqda e-poçt ünvanı', 'Düzgün cavab: E) İcraçının soyadı, adı, atasının adı (inisial) və xidməti telefon nömrəsi, zərurə', '', 22, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('61f7f1af-92b0-4031-a4e6-451eadbda3e0', 'e86cf940-a68f-47a8-9169-64220537461a', 'ka', 'საგანმანათლებლო დაწესებულების ბლანკზე მომზადებული ოფიციალური წერილის ქვედა მარცხენა კუთხეში შემსრულებლის შესახებ რა მონაცემები უნდა მიეთითოს?', '["შემსრულებლის პირადი ნომერი და საცხოვრებელი მისამართი", "იმ უმაღლესი სასწავლებლის დასახელება, რომელიც შემსრულებელმა დაამთავრა, და დამთავრების წელი", "შემსრულებლის პირადი ელფოსტის პაროლი და კომპიუტერის ნომერი", "შემსრულებლის შრომითი სტაჟი და საზოგადოებრივი მოვალეობები", "შემსრულებლის გვარი, სახელი, მამის სახელი (ინიციალები) და სამსახურებრივი ტელეფონის ნომერი, საჭიროების შემთხვევაში ელფოსტა"]'::jsonb, 'შემსრულებლის გვარი, სახელი, მამის სახელი (ინიციალები) და სამსახურებრივი ტელეფონის ნომერი, საჭიროების შემთხვევაში ელფოსტა', 'Düzgün cavab: E) შემსრულებლის გვარი, სახელი, მამის სახელი (ინიციალები) და სამსახურებრივი ტელეფონი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('91ebf9e8-ed8f-4ad7-938e-64518a027ca0', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Məktəb dəftərxanasında ofis texnikası ilə işləyərkən texniki təhlükəsizlik qaydalarına hansı hərəkət **AİD DEYİLDİR** (qadağandır)?', 'multiple_choice', '["Kartricləri dəyişərkən daxili qızdırıcı (fuser) hissələrə ehtiyatla yanaşmaq", "Nasaz və izolyasiyası zədələnmiş elektrik naqillərindən istifadə etməmək", "Printerdə kağız ilişdikdə onu metal kəsici alətlərlə, kobud güc tətbiq edərək dartıb çıxarmaq", "İş günü bitdikdə cihazları elektrik şəbəkəsindən ayırmaq", "Cihazların üzərinə maye və kənar cisimlərin düşməsinin qarşısını almaq"]'::jsonb, 'Printerdə kağız ilişdikdə onu metal kəsici alətlərlə, kobud güc tətbiq edərək dartıb çıxarmaq', 'Düzgün cavab: C) Printerdə kağız ilişdikdə onu metal kəsici alətlərlə, kobud güc tətbiq edərək da', '', 23, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7d5c6ff6-6d26-4395-ae7b-213833af7c57', '91ebf9e8-ed8f-4ad7-938e-64518a027ca0', 'ka', 'სკოლის კანცელარიაში საოფისე ტექნიკასთან მუშაობისას ტექნიკური უსაფრთხოების წესებს რომელი არ მიეკუთვნება?', '["გაუმართავი და დაზიანებული იზოლაციის მქონე სადენების გამოყენებისგან თავის შეკავება", "კარტრიჯების შეცვლისას შიდა გამახურებელ (ფუზერის) ნაწილებთან სიფრთხილის გამოჩენა", "პრინტერში ქაღალდის გაჭედვისას მისი ლითონის მჭრელი ხელსაწყოებით, ძალის გამოყენებით გამოღება და ბეჭდვის დაუყოვნებლივ გაგრძელება", "სამუშაო დღის დასრულებისას მოწყობილობების ელექტროქსელიდან გამორთვა, მოლოდინის რეჟიმში არდატოვება", "მოწყობილობებზე სითხისა და უცხო სხეულების მოხვედრის თავიდან აცილება"]'::jsonb, 'პრინტერში ქაღალდის გაჭედვისას მისი ლითონის მჭრელი ხელსაწყოებით, ძალის გამოყენებით გამოღება და ბეჭდვის დაუყოვნებლივ გაგრძელება', 'Düzgün cavab: C) პრინტერში ქაღალდის გაჭედვისას მისი ლითონის მჭრელი ხელსაწყოებით, ძალის გამოყენები', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('21e4fcc9-0ff4-4ef9-9c9b-5f4bd1e6260c', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Ümumi təhsil müəssisəsində direktorun əmrlərinin nömrələnməsi hər təqvim ilində hansı qaydada aparılır?', 'multiple_choice', '["Əmrlərin məzmununa baxılmadan hər ay üçün sərbəst intervallar təyin edilir", "Əsas və kadr əmrləri üçün vahid qarışıq nömrələnmə aparılır", "Əvvəlki ilin son nömrəsindən fasiləsiz davam etdirilir", "Hər yeni təqvim ilinin 1 yanvar tarixindən 1 nömrəsindən başlayaraq xronoloji ardıcıllıqla, əsas və kadr əmrləri ayrı-ayrılıqda aparılır", "Hər tədris rübünün əvvəlində nömrələnmə yenidən 1-dən başlayır"]'::jsonb, 'Hər yeni təqvim ilinin 1 yanvar tarixindən 1 nömrəsindən başlayaraq xronoloji ardıcıllıqla, əsas və kadr əmrləri ayrı-ayrılıqda aparılır', 'Düzgün cavab: D) Hər yeni təqvim ilinin 1 yanvar tarixindən 1 nömrəsindən başlayaraq xronoloji ar', '', 24, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e264e704-deef-4469-9eb8-769e2c8b1420', '21e4fcc9-0ff4-4ef9-9c9b-5f4bd1e6260c', 'ka', 'რა წესით წარმოებს დირექტორის ბრძანებების ნუმერაცია ყოველ კალენდარულ წელს ზოგადსაგანმანათლებლო დაწესებულებაში?', '["ძირითადი და საკადრო ბრძანებებისთვის წარმოებს ერთიანი შერეული ნუმერაცია", "ბრძანებების შინაარსის გაუთვალისწინებლად ყოველი თვისთვის დგინდება თავისუფალი ინტერვალები", "უწყვეტად გრძელდება წინა წლის ბოლო ნომრიდან", "ყოველი ახალი კალენდარული წლის 1 იანვრიდან იწყება 1 ნომრიდან ქრონოლოგიური თანმიმდევრობით, ძირითადი და საკადრო ბრძანებებისთვის ცალ-ცალკე", "ყოველი სასწავლო მეოთხედის დასაწყისში ნუმერაცია ხელახლა იწყება 1-დან"]'::jsonb, 'ყოველი ახალი კალენდარული წლის 1 იანვრიდან იწყება 1 ნომრიდან ქრონოლოგიური თანმიმდევრობით, ძირითადი და საკადრო ბრძანებებისთვის ცალ-ცალკე', 'Düzgün cavab: D) ყოველი ახალი კალენდარული წლის 1 იანვრიდან იწყება 1 ნომრიდან ქრონოლოგიური თანმიმდ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('40fee2f6-d643-4076-9769-fa406c129e6e', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'İşə qəbul, başqa işə keçirilmə və ya intizam tənbehi əmrləri ilə işçi hansı müddətdə tanış edilməlidir?', 'multiple_choice', '["Yalnız işçinin növbəti məzuniyyət dövrü başa çatdıqdan sonra", "İllik statistik kadr hesabatı tərtib edildiyi zaman", "Əmr verildiyi gündən dərhal və ya ən geci 3 iş günü müddətində, imza etdirilməklə (imzalamadıqda akt tərtib edilərək)", "Növbəti əməkhaqqı ödənişi həyata keçirilənədək şifahi məlumat verməklə", "Əmrin imzalandığı ayın son iş günündə bildiriş göndərməklə"]'::jsonb, 'Əmr verildiyi gündən dərhal və ya ən geci 3 iş günü müddətində, imza etdirilməklə (imzalamadıqda akt tərtib edilərək)', 'Düzgün cavab: C) Əmr verildiyi gündən dərhal və ya ən geci 3 iş günü müddətində, imza etdirilməkl', '', 25, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0111397a-007d-4ae5-ba4f-89be19d36bd9', '40fee2f6-d643-4076-9769-fa406c129e6e', 'ka', 'რა ვადაში უნდა გაეცნოს თანამშრომელი სამუშაოზე მიღების, სხვა სამუშაოზე გადაყვანის ან დისციპლინური სახდელის დაკისრების ბრძანებებს?', '["ბრძანების ხელმოწერის თვის ბოლო სამუშაო დღეს შეტყობინების გაგზავნით", "წლიური სტატისტიკური საკადრო ანგარიშის შედგენის დროს", "ბრძანების გამოცემის დღიდან დაუყოვნებლივ ან არაუგვიანეს 3 სამუშაო დღის ვადაში ხელმოწერით, ხოლო თანამშრომლის უარის შემთხვევაში აქტის შედგენით", "შემდეგი ხელფასის გადახდამდე ზეპირი ინფორმაციის მიწოდებით", "მხოლოდ თანამშრომლის მორიგი შვებულების პერიოდის დასრულების შემდეგ"]'::jsonb, 'ბრძანების გამოცემის დღიდან დაუყოვნებლივ ან არაუგვიანეს 3 სამუშაო დღის ვადაში ხელმოწერით, ხოლო თანამშრომლის უარის შემთხვევაში აქტის შედგენით', 'Düzgün cavab: C) ბრძანების გამოცემის დღიდან დაუყოვნებლივ ან არაუგვიანეს 3 სამუშაო დღის ვადაში ხელ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('79a14cdf-9f3d-4ca2-84ab-218eeceb8e79', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Məktəbdə çalışan heyətin əmək kitabçalarının və kadr sənədlərinin uçotu və saxlanmasına kim cavabdehdir?', 'multiple_choice', '["Valideyn-Müəllim Assosiasiyasının idarə heyəti", "Direktorun əmri ilə kadr və kargüzarlıq işi həvalə olunmuş məsul şəxs (katibə-makinaçı / kadrlar üzrə məsul)", "Metodbirləşmə rəhbərləri və fənn komissiyaları", "Həmkarlar İttifaqı Komitəsinin seçkili sədri", "Təsərrüfat işləri üzrə direktor müavini"]'::jsonb, 'Direktorun əmri ilə kadr və kargüzarlıq işi həvalə olunmuş məsul şəxs (katibə-makinaçı / kadrlar üzrə məsul)', 'Düzgün cavab: B) Direktorun əmri ilə kadr və kargüzarlıq işi həvalə olunmuş məsul şəxs (katibə-ma', '', 26, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6685332e-3d5d-4387-8bd8-c525971b41cd', '79a14cdf-9f3d-4ca2-84ab-218eeceb8e79', 'ka', 'ვინ არის პასუხისმგებელი სკოლაში მომუშავე პერსონალის შრომის წიგნაკების აღრიცხვასა და შენახვაზე?', '["მშობელთა და მასწავლებელთა ასოციაციის გამგეობა", "დირექტორის ბრძანებით საკადრო და საქმისწარმოების სამუშაოზე პასუხისმგებელი პირი (მდივან-მემანქანე / კადრების სპეციალისტი)", "პროფკავშირის კომიტეტის არჩეული თავმჯდომარე", "დირექტორის მოადგილე სამეურნეო დარგში", "საგნობრივი კათედრების ხელმძღვანელები და საგნობრივი კომისიები"]'::jsonb, 'დირექტორის ბრძანებით საკადრო და საქმისწარმოების სამუშაოზე პასუხისმგებელი პირი (მდივან-მემანქანე / კადრების სპეციალისტი)', 'Düzgün cavab: B) დირექტორის ბრძანებით საკადრო და საქმისწარმოების სამუშაოზე პასუხისმგებელი პირი (მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d339ff1c-603b-4c34-a49b-3f76e4a0216c', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Katibə-makinaçının iş yerində erqonomik və sanitar-gigiyenik normalara əsasən hansı tələb doğrudur?', 'multiple_choice', '["Otağın təbii havalandırılması məhdudlaşdırılmalı və pəncərələr daimi bağlı qalmalıdır", "İş masası və stul tənzimlənməli, monitor göz səviyyəsindən bir qədər aşağıda və 50–70 sm məsafədə, işıq sol tərəfdən düşməlidir", "Monitor birbaşa pəncərə qarşısında, günəş işığının ekrana əks olunduğu istiqamətdə yerləşdirilməlidir", "Klaviatura diz səviyyəsindən xeyli aşağıda, ayaqların üzərində saxlanılmalıdır", "Süni işıqlandırma yalnız arxa tərəfdən monitorun səthinə yönəldilməlidir"]'::jsonb, 'İş masası və stul tənzimlənməli, monitor göz səviyyəsindən bir qədər aşağıda və 50–70 sm məsafədə, işıq sol tərəfdən düşməlidir', 'Düzgün cavab: B) İş masası və stul tənzimlənməli, monitor göz səviyyəsindən bir qədər aşağıda və', '', 27, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('14af96c0-8afd-4a42-bb0e-e6919b07909f', 'd339ff1c-603b-4c34-a49b-3f76e4a0216c', 'ka', 'ერგონომიკული და სანიტარიულ-ჰიგიენური ნორმების თანახმად, რომელი მოთხოვნაა სწორი მდივან-მემანქანის სამუშაო ადგილისთვის?', '["ხელოვნური განათება მხოლოდ უკანა მხრიდან უნდა იყოს მიმართული მონიტორის ზედაპირზე", "სამუშაო მაგიდა და სკამი უნდა იყოს რეგულირებადი, მონიტორი თვალის დონეზე ოდნავ დაბლა და 50–70 სმ მანძილზე, სინათლე კი მარცხენა მხრიდან უნდა ეცემოდეს", "მონიტორი უნდა განთავსდეს უშუალოდ ფანჯრის წინ, ისე, რომ მზის სინათლე ეკრანზე აირეკლებოდეს", "ოთახის ბუნებრივი ვენტილაცია უნდა შეიზღუდოს და ფანჯრები მუდმივად დახურული უნდა იყოს", "კლავიატურა უნდა განთავსდეს მუხლის დონეზე ბევრად დაბლა, ფეხებზე"]'::jsonb, 'სამუშაო მაგიდა და სკამი უნდა იყოს რეგულირებადი, მონიტორი თვალის დონეზე ოდნავ დაბლა და 50–70 სმ მანძილზე, სინათლე კი მარცხენა მხრიდან უნდა ეცემოდეს', 'Düzgün cavab: B) სამუშაო მაგიდა და სკამი უნდა იყოს რეგულირებადი, მონიტორი თვალის დონეზე ოდნავ დაბ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('28e48a6a-2be5-4ff6-a1e6-efd3f1ab7c11', '1940e17b-2e5d-4863-83aa-0206aad16aa3', '“Azərbaycan Respublikasında dövlət dili haqqında” AR Qanununa əsasən, məktəbdə rəsmi kargüzarlıq hansı dildə aparılmalıdır?', 'multiple_choice', '["Məktəbdə tədris olunan xarici dil fənlərinin dilində", "Müəssisə rəhbərliyinin qərarı ilə seçilən istənilən əcnəbi dildə", "İkidilli paralel tərcümə və qarışıq blanklar əsasında", "Regionun yerli dialekt və şivələrində", "Azərbaycan Respublikasının dövlət dilində (Azərbaycan dilində)"]'::jsonb, 'Azərbaycan Respublikasının dövlət dilində (Azərbaycan dilində)', 'Düzgün cavab: E) Azərbaycan Respublikasının dövlət dilində (Azərbaycan dilində)', '', 28, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cce31139-879e-4ae7-beb1-0c33af562ece', '28e48a6a-2be5-4ff6-a1e6-efd3f1ab7c11', 'ka', 'კანონის „აზერბაიჯანის რესპუბლიკაში სახელმწიფო ენის შესახებ“ თანახმად, რომელ ენაზე უნდა იწარმოებოდეს ოფიციალური საქმისწარმოება სკოლაში?', '["ორენოვანი პარალელური თარგმანითა და შერეული ბლანკების საფუძველზე", "რეგიონის ადგილობრივ დიალექტებსა და კილოებზე, მოსახლეობისთვის გასაგები ფორმით", "დაწესებულების ხელმძღვანელობის გადაწყვეტილებით არჩეულ ნებისმიერ უცხო ენაზე", "სკოლაში სწავლებული უცხო ენების საგნების ენაზე", "აზერბაიჯანის რესპუბლიკის სახელმწიფო ენაზე (აზერბაიჯანულ ენაზე), აუცილებლობის შემთხვევაში დამატებითი თარგმანით"]'::jsonb, 'აზერბაიჯანის რესპუბლიკის სახელმწიფო ენაზე (აზერბაიჯანულ ენაზე), აუცილებლობის შემთხვევაში დამატებითი თარგმანით', 'Düzgün cavab: E) აზერბაიჯანის რესპუბლიკის სახელმწიფო ენაზე (აზერბაიჯანულ ენაზე), აუცილებლობის შემ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('099619af-9922-4c77-83d0-15525b192e36', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Təhsil müəssisəsi tərəfindən şagirdə verilən rəsmi təhsil arayışında hansı məlumatın olması məcburidir?', 'multiple_choice', '["Arayışın verilmə tarixi, çıxan qeydiyyat nömrəsi, şagirdin soyadı, adı, oxuduğu sinif, təqdim ediləcəyi yer, direktorun imzası və gerbli möhür", "Məktəb binasının inventar nömrəsi və təhsil sektorunun ünvanı", "Şagirdin oxuduğu sinif otağının sahəsi və məktəbin tutumu", "Şagirdin ailə üzvlərinin iş yerləri və aylıq gəlir göstəriciləri", "Şagirdin dərnəklərdəki fəallığı və tədbirlərdə iştirak dərəcəsi"]'::jsonb, 'Arayışın verilmə tarixi, çıxan qeydiyyat nömrəsi, şagirdin soyadı, adı, oxuduğu sinif, təqdim ediləcəyi yer, direktorun imzası və gerbli möhür', 'Düzgün cavab: A) Arayışın verilmə tarixi, çıxan qeydiyyat nömrəsi, şagirdin soyadı, adı, oxuduğu', '', 29, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a3773be6-7a67-4c1d-9897-e4e23ac3b64b', '099619af-9922-4c77-83d0-15525b192e36', 'ka', 'რა ინფორმაციის არსებობაა სავალდებულო საგანმანათლებლო დაწესებულების მიერ მოსწავლეზე გაცემულ ოფიციალურ სასკოლო ცნობაში?', '["ცნობის თარიღი, სარეგისტრაციო ნომერი, მოსწავლის სახელი და გვარი, კლასი რომელშიც სწავლობს, წარდგენის ადგილი, დირექტორის ხელმოწერა და გერბიანი ბეჭედი", "მოსწავლის აქტიურობა წრეებში და ღონისძიებებში მონაწილეობის ხარისხი", "მოსწავლის ოჯახის წევრთა სამუშაო ადგილები და ყოველთვიური შემოსავლის მაჩვენებლები", "სკოლის შენობის საინვენტარო ნომერი და საგანმანათლებლო სექტორის მისამართი", "იმ საკლასო ოთახის ფართობი, სადაც მოსწავლე სწავლობს, და სკოლის ტევადობა"]'::jsonb, 'ცნობის თარიღი, სარეგისტრაციო ნომერი, მოსწავლის სახელი და გვარი, კლასი რომელშიც სწავლობს, წარდგენის ადგილი, დირექტორის ხელმოწერა და გერბიანი ბეჭედი', 'Düzgün cavab: A) ცნობის თარიღი, სარეგისტრაციო ნომერი, მოსწავლის სახელი და გვარი, კლასი რომელშიც ს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fe396be1-2f7e-47f5-ba03-14d02147f40a', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Məktəb dəftərxanasında və arxiv otağında yanğın təhlükəsizliyi qaydalarına əsasən hansı hərəkət **QƏTİ QADAĞANDIR**?', 'multiple_choice', '["Kağız sənəd qovluqlarını və arxiv qutularını açıq elektrik qızdırıcılarının və elektrik lövhələrinin bilavasitə yaxınlığında qalaqlamaq", "Elektrik açarlarını və rozetkaları saz vəziyyətdə saxlamaq", "İş otağından çıxarkən elektrik cihazlarını şəbəkədən tam ayırmaq", "İlkin yanğınsöndürmə vasitələrinin (odsöndürənlərin) sazlığını mütəmadi yoxlamaq", "Təxliyə çıxışlarını və dəhlizləri sərbəst və maneəsiz saxlamaq"]'::jsonb, 'Kağız sənəd qovluqlarını və arxiv qutularını açıq elektrik qızdırıcılarının və elektrik lövhələrinin bilavasitə yaxınlığında qalaqlamaq', 'Düzgün cavab: A) Kağız sənəd qovluqlarını və arxiv qutularını açıq elektrik qızdırıcılarının və e', '', 30, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('133d642f-e651-43d7-90ba-d3bbfc597ccc', 'fe396be1-2f7e-47f5-ba03-14d02147f40a', 'ka', 'სახანძრო უსაფრთხოების წესების თანახმად, რა ქმედებაა აკრძალული სკოლის კანცელარიასა და საარქივო ოთახში?', '["დოკუმენტების ქაღალდის საქაღალდეებისა და საარქივო ყუთების შენახვა ღია ელექტროგამათბობლებთან, ღუმელებთან და ელექტროფარებთან უშუალო სიახლოვეს", "საევაკუაციო გასასვლელებისა და დერეფნების თავისუფალ და დაუბრკოლებელ მდგომარეობაში შენარჩუნება", "ხანძარსაწინააღმდეგო პირველადი საშუალებების გამოყენების წესების გაცნობა", "ელექტროჩამრთველებისა და როზეტების გამართულ მდგომარეობაში შენარჩუნება", "სამუშაო ოთახიდან გასვლისას ელექტრომოწყობილობების ქსელიდან სრულად გამორთვა"]'::jsonb, 'დოკუმენტების ქაღალდის საქაღალდეებისა და საარქივო ყუთების შენახვა ღია ელექტროგამათბობლებთან, ღუმელებთან და ელექტროფარებთან უშუალო სიახლოვეს', 'Düzgün cavab: A) დოკუმენტების ქაღალდის საქაღალდეებისა და საარქივო ყუთების შენახვა ღია ელექტროგამა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6cf3023b-1ef5-467c-ac3c-eb706ebdd19a', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Azərbaycan Respublikası Konstitusiyasının 42-ci maddəsinə əsasən, təhsil hüququnun təminatı ilə bağlı hansı müddəa təsbit edilmişdir?', 'multiple_choice', '["Dövlət yalnız dövlət məktəblərində təhsili pulsuz edir, özəl məktəblərdə təhsil ödənişlidir", "Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququna, istedadlı şəxslərin təhsilini davam etdirməsinə və təhsil sisteminə dövlət nəzarətinə təminat verir", "Dövlət təhsil hüququnu yalnız 18 yaşadək vətəndaşlara şamil edir", "Dövlət ali təhsilin bütün pillələrində pulsuz təhsilə təminat verir", "Dövlət yalnız ibtidai təhsili icbari hesab edir"]'::jsonb, 'Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququna, istedadlı şəxslərin təhsilini davam etdirməsinə və təhsil sisteminə dövlət nəzarətinə təminat verir', 'Düzgün cavab: B) Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququna, isteda', '', 31, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a4b8f897-ec2e-4872-96f7-eb98989addfe', '6cf3023b-1ef5-467c-ac3c-eb706ebdd19a', 'ka', 'აზერბაიჯანის რესპუბლიკის კონსტიტუციის 42-ე მუხლის თანახმად, რა დებულებაა განმტკიცებული განათლების უფლების გარანტიასთან დაკავშირებით?', '["სახელმწიფო სავალდებულოდ მიიჩნევს მხოლოდ დაწყებით განათლებას", "სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო საბაზო ზოგად განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და განათლების სისტემაზე სახელმწიფო კონტროლის გარანტიას", "სახელმწიფო განათლებას უფასოს ხდის მხოლოდ სახელმწიფო სკოლებში, კერძო სკოლებში სწავლა ფასიანია", "სახელმწიფო უზრუნველყოფს უფასო განათლების გარანტიას უმაღლესი განათლების ყველა საფეხურზე", "სახელმწიფო განათლების უფლებას მხოლოდ 18 წლამდე ასაკის მოქალაქეებზე ავრცელებს"]'::jsonb, 'სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო საბაზო ზოგად განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და განათლების სისტემაზე სახელმწიფო კონტროლის გარანტიას', 'Düzgün cavab: B) სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო საბაზო ზოგა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8487c110-c764-4d71-a610-aeb5485ca666', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Azərbaycan Respublikası Konstitusiyasının 25-ci maddəsinə görə, bərabərlik hüququnun məzmununu əks etdirən düzgün hüquqi norma hansıdır?', 'multiple_choice', '["Dövlət yalnız Azərbaycan vətəndaşlarının hüquq bərabərliyinə təminat verir", "Bərabərlik hüququ yalnız dövlət qulluqçuları arasında tətbiq edilir", "Dövlət bərabərliyi yalnız əmək münasibətlərində təmin edir", "Bərabərlik hüququ yalnız məhkəmə prosesində tətbiq olunur", "Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, əqidəsindən və sosial mənşəyindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir"]'::jsonb, 'Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, əqidəsindən və sosial mənşəyindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir', 'Düzgün cavab: E) Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, əqidəsin', '', 32, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6600541f-6065-4dae-8d41-551f3ce8c9b0', '8487c110-c764-4d71-a610-aeb5485ca666', 'ka', 'აზერბაიჯანის რესპუბლიკის კონსტიტუციის 25-ე მუხლის მიხედვით, რომელია სწორი სამართლებრივი ნორმა, რომელიც ასახავს თანასწორობის უფლების შინაარსს?', '["სახელმწიფო უზრუნველყოფს უფლებრივ თანასწორობას მხოლოდ აზერბაიჯანის მოქალაქეებისთვის", "თანასწორობის უფლება გამოიყენება მხოლოდ საჯარო მოხელეებს შორის", "თანასწორობის უფლება გამოიყენება მხოლოდ სასამართლო პროცესში", "სახელმწიფო თანასწორობას უზრუნველყოფს მხოლოდ შრომით ურთიერთობებში", "სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას, განურჩევლად რასისა, ეთნიკური კუთვნილებისა, რელიგიისა, ენისა, სქესისა, მრწამსისა, სოციალური წარმოშობისა"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას, განურჩევლად რასისა, ეთნიკური კუთვნილებისა, რელიგიისა, ენისა, სქესისა, მრწამსისა, სოციალური წარმოშობისა', 'Düzgün cavab: E) სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას, განურჩ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('874aa76b-cb2d-4225-b951-1bf7228cfae9', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Azərbaycan Respublikası Konstitusiyasının 32-ci maddəsinə əsasən, şəxsi toxunulmazlıq hüququ ilə bağlı hansı qayda müəyyən olunmuşdur?', 'multiple_choice', '["Şəxsi həyat haqqında məlumatların yayılması yalnız şifahi razılıqla mümkündür", "Öz razılığı olmadan kimsənin şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir", "Şəxsi toxunulmazlıq hüququ yalnız dövlət sirri daşıyan şəxslərə şamil edilir", "Şəxsi məlumatlar yalnız məhkəmə qərarı olmadan da toplanıla bilər", "Fərdi məlumatların toplanması daxili nizamnamə ilə sərbəst tənzimlənir"]'::jsonb, 'Öz razılığı olmadan kimsənin şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir', 'Düzgün cavab: B) Öz razılığı olmadan kimsənin şəxsi həyatı haqqında məlumatların toplanılmasına,', '', 33, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0668e19e-9f3e-47f5-a716-824bf58206d9', '874aa76b-cb2d-4225-b951-1bf7228cfae9', 'ka', 'აზერბაიჯანის რესპუბლიკის კონსტიტუციის 32-ე მუხლის თანახმად, რა წესია დადგენილი პირადი ხელშეუხებლობის უფლებასთან დაკავშირებით?', '["პირადი ცხოვრების შესახებ ინფორმაციის გავრცელება შესაძლებელია მხოლოდ ზეპირი თანხმობით", "მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა, გამოყენება და გავრცელება დაუშვებელია, გარდა კანონით დადგენილი შემთხვევებისა", "პირადი ხელშეუხებლობის უფლება ვრცელდება მხოლოდ იმ პირებზე, რომლებიც ფლობენ სახელმწიფო საიდუმლოებას", "პირადი მონაცემების შეგროვება შესაძლებელია სასამართლოს გადაწყვეტილების გარეშეც", "პერსონალური მონაცემების შეგროვება თავისუფლად რეგულირდება შიდა განაწესით"]'::jsonb, 'მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა, გამოყენება და გავრცელება დაუშვებელია, გარდა კანონით დადგენილი შემთხვევებისა', 'Düzgün cavab: B) მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f987ab66-92c2-4e2e-a48b-58f963760c12', '1940e17b-2e5d-4863-83aa-0206aad16aa3', '“Təhsil haqqında” AR Qanununun 3-cü maddəsinə əsasən, təhsil sahəsində dövlət siyasətinin əsas prinsiplərindən olan ''Humanistlik'' nəyi ifadə edir?', 'multiple_choice', '["Təhsilin yalnız milli dəyərlərə əsaslanmasını", "Təhsildə rəqabət mühitinin aradan qaldırılmasını", "Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını", "Təhsilalanların yalnız əmək bazarının tələblərinə uyğun hazırlanmasını", "Təhsil müəssisələrinin yalnız dövlət tərəfindən maliyyələşdirilməsini"]'::jsonb, 'Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını', 'Düzgün cavab: C) Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və', '', 34, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('795aff29-e9d6-43f0-bba4-67f1a3a86992', 'f987ab66-92c2-4e2e-a48b-58f963760c12', 'ka', 'კანონის „განათლების შესახებ“ მე-3 მუხლის თანახმად, რას გამოხატავს „ჰუმანიზმი“, რომელიც განათლების სფეროში სახელმწიფო პოლიტიკის ერთ-ერთი ძირითადი პრინციპია?', '["საგანმანათლებლო დაწესებულებების დაფინანსებას მხოლოდ სახელმწიფოს მიერ", "განათლების დაფუძნებას მხოლოდ ეროვნულ ფასეულობებზე", "ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას", "განათლებაში კონკურენტული გარემოს აღმოფხვრას", "მოსწავლეთა მომზადებას მხოლოდ შრომის ბაზრის მოთხოვნების შესაბამისად"]'::jsonb, 'ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას', 'Düzgün cavab: C) ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('afda19b1-6396-410e-b70b-5f610ea84416', '1940e17b-2e5d-4863-83aa-0206aad16aa3', '“Təhsil haqqında” AR Qanununun 12-ci maddəsinə əsasən, Azərbaycan Respublikasında təsbit edilmiş təhsil formaları hansılardır?', 'multiple_choice', '["Məktəbəqədər, ümumi və peşə təhsili", "Əyani, qiyabi və distant təhsil", "Formal, qeyri-formal və informal təhsil", "Dövlət, özəl və bələdiyyə təhsili", "İbtidai, orta və ali təhsil"]'::jsonb, 'Formal, qeyri-formal və informal təhsil', 'Düzgün cavab: C) Formal, qeyri-formal və informal təhsil', '', 35, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('add5a5d2-5a96-4b3b-af7b-cf8342d1a919', 'afda19b1-6396-410e-b70b-5f610ea84416', 'ka', 'კანონის „განათლების შესახებ“ მე-12 მუხლის თანახმად, რომელია აზერბაიჯანის რესპუბლიკაში განმტკიცებული განათლების ფორმები?', '["დღის (დასწრებული), დაუსწრებელი და დისტანციური განათლება", "სახელმწიფო, კერძო და მუნიციპალური განათლება", "ფორმალური, არაფორმალური და ინფორმალური განათლება", "სკოლამდელი, ზოგადი და პროფესიული განათლება", "დაწყებითი, საშუალო და უმაღლესი განათლება"]'::jsonb, 'ფორმალური, არაფორმალური და ინფორმალური განათლება', 'Düzgün cavab: C) ფორმალური, არაფორმალური და ინფორმალური განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d38efbb5-6916-4320-b976-d3ed0c2f1f4d', '1940e17b-2e5d-4863-83aa-0206aad16aa3', '“Təhsil haqqında” AR Qanununa əsasən, müxtəlif səbəblərdən ümumi təhsildən kənarda qalmış şəxslərə təhsil almaq hüququ verən forma hansıdır?', 'multiple_choice', '["Evdə təhsilalma forması", "Distant təhsilalma forması", "İnklüziv təhsilalma forması", "Fərdi təhsilalma forması", "Sərbəst (eksternat) təhsilalma forması"]'::jsonb, 'Sərbəst (eksternat) təhsilalma forması', 'Düzgün cavab: E) Sərbəst (eksternat) təhsilalma forması', '', 36, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b6664d07-e7df-4989-8f3e-00fcf58795fb', 'd38efbb5-6916-4320-b976-d3ed0c2f1f4d', 'ka', 'კანონის „განათლების შესახებ“ თანახმად, განათლების მიღების რომელი ფორმა აძლევს განათლების მიღების უფლებას იმ პირებს, რომლებიც სხვადასხვა მიზეზით დარჩნენ ზოგადი განათლების მიღმა?', '["ინდივიდუალური სწავლების ფორმა", "ინკლუზიური სწავლების ფორმა", "დისტანციური სწავლების ფორმა", "შინა სწავლების ფორმა", "ექსტერნატის (თავისუფალი) სწავლების ფორმა"]'::jsonb, 'ექსტერნატის (თავისუფალი) სწავლების ფორმა', 'Düzgün cavab: E) ექსტერნატის (თავისუფალი) სწავლების ფორმა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('19133c02-c31d-4073-962b-7357917827f1', '1940e17b-2e5d-4863-83aa-0206aad16aa3', '“Təhsil haqqında” AR Qanununun 32-ci maddəsinə əsasən, təhsilverənlərin vəzifələrinə aid olan müddəa hansıdır?', 'multiple_choice', '["Valideynlərdən əlavə təhsil haqqı tələb etmək", "Dərs cədvəlini müstəqil tərtib etmək", "Təhsil proqramlarını sərbəst dəyişdirmək və dərslikləri seçmək", "İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını və İKT-ni mənimsəyərək tədris prosesində tətbiq etmək", "Şagirdlərin davamiyyətinə nəzarəti dayandırmaq"]'::jsonb, 'İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını və İKT-ni mənimsəyərək tədris prosesində tətbiq etmək', 'Düzgün cavab: D) İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını və', '', 37, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f2baba5e-5477-4b7b-8125-99ddec04a0eb', '19133c02-c31d-4073-962b-7357917827f1', 'ka', 'კანონის „განათლების შესახებ“ 32-ე მუხლის თანახმად, რომელი დებულება მიეკუთვნება პედაგოგთა (მასწავლებელთა) მოვალეობებს?', '["მშობლებისგან დამატებითი სწავლის საფასურის მოთხოვნა", "გაკვეთილების ცხრილის დამოუკიდებლად შედგენა", "მოსწავლეთა დასწრებაზე კონტროლის შეწყვეტა", "კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, სწავლების თანამედროვე მეთოდებისა და ისტ-ის დაუფლება და სასწავლო პროცესში გამოყენება", "საგანმანათლებლო პროგრამების თვითნებურად შეცვლა და სახელმძღვანელოების შერჩევა"]'::jsonb, 'კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, სწავლების თანამედროვე მეთოდებისა და ისტ-ის დაუფლება და სასწავლო პროცესში გამოყენება', 'Düzgün cavab: D) კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, სწავლების თანამედროვე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ef055c13-a419-40af-8666-440589e92e1b', '1940e17b-2e5d-4863-83aa-0206aad16aa3', '“Ümumi təhsil haqqında” AR Qanununa əsasən, ümumi təhsil pilləsinin səviyyələri üzrə bölgüsü hansı variantda tam göstərilmişdir?', 'multiple_choice', '["İbtidai (I–V), ümumi (VI–IX) və peşə (X–XI)", "Hazırlıq (0), ibtidai (I–IV) və orta (V–XI)", "Məktəbəqədər (I–IV), orta (V–X) və tam (XI–XII)", "Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV siniflər), ümumi orta təhsil (V–IX siniflər) və tam orta təhsil (X–XI siniflər)", "İbtidai (I–III), orta (IV–IX) və böyük (X–XII)"]'::jsonb, 'Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV siniflər), ümumi orta təhsil (V–IX siniflər) və tam orta təhsil (X–XI siniflər)', 'Düzgün cavab: D) Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV siniflər), ümumi orta təhsil (V–', '', 38, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('28868277-797d-43f4-9035-3ccef4574bae', 'ef055c13-a419-40af-8666-440589e92e1b', 'ka', 'კანონის „ზოგადი განათლების შესახებ“ თანახმად, რომელ ვარიანტშია სრულად ნაჩვენები ზოგადი განათლების საფეხურები?', '["დაწყებითი (I–V), საბაზო (VI–IX) და პროფესიული (X–XI)", "სკოლამდელი (I–IV), საშუალო (V–X) და სრული (XI–XII)", "მოსამზადებელი (0), დაწყებითი (I–IV) და საშუალო (V–XI)", "სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული ზოგადი განათლება (X–XI)", "დაწყებითი (I–III), საშუალო (IV–IX) და უფროსი (X–XII)"]'::jsonb, 'სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული ზოგადი განათლება (X–XI)', 'Düzgün cavab: D) სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('00d23867-b1c4-4586-9607-43c3c5966a55', '1940e17b-2e5d-4863-83aa-0206aad16aa3', '“Ümumi təhsil haqqında” AR Qanununun 21-ci maddəsinə əsasən, aşağıdakılardan hansı təhsilalanların hüquqlarına **AİD DEYİLDİR**?', 'multiple_choice', '["Təhlükəsiz və sağlam təhsil şəraiti ilə təmin olunmaq", "Ləyaqətini alçaldan rəftardan müdafiə olunmaq", "Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq", "Kitabxana və laboratoriyadan pulsuz istifadə etmək", "Dövlət məktəblərində dərsliklərlə pulsuz təmin olunmaq"]'::jsonb, 'Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq', 'Düzgün cavab: C) Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoj', '', 39, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8f66893b-348b-41b2-bff9-7a35345fc478', '00d23867-b1c4-4586-9607-43c3c5966a55', 'ka', 'კანონის „ზოგადი განათლების შესახებ“ 21-ე მუხლის თანახმად, რომელი დებულება არ მიეკუთვნება მოსწავლეთა უფლებებს?', '["ბიბლიოთეკითა და ლაბორატორიით უფასო სარგებლობა", "უსაფრთხო და ჯანსაღი სასწავლო გარემოთი უზრუნველყოფა", "დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება", "სახელმწიფო სკოლებში სახელმძღვანელოებით უფასო უზრუნველყოფა", "ღირსების შემლახავი მოპყრობისგან დაცვა"]'::jsonb, 'დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება', 'Düzgün cavab: C) დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6d660756-4f23-44c8-888e-23aaf6704df3', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Dövlət və bələdiyyə ümumi təhsil müəssisələrinin Nümunəvi Nizamnaməsinə əsasən, məktəbin fəaliyyətinə cari rəhbərliyi kim həyata keçirir?', 'multiple_choice', '["Valideyn-Müəllim Assosiasiyasının sədri", "Bələdiyyə sədri tərəfindən təyin olunan nümayəndə", "Pedaqoji Şura tərəfindən seçilən sədr", "Müvafiq icra hakimiyyəti orqanı tərəfindən vəzifəyə təyin olunan məktəb direktoru", "Həmkarlar İttifaqı Komitəsinin rəhbəri"]'::jsonb, 'Müvafiq icra hakimiyyəti orqanı tərəfindən vəzifəyə təyin olunan məktəb direktoru', 'Düzgün cavab: D) Müvafiq icra hakimiyyəti orqanı tərəfindən vəzifəyə təyin olunan məktəb direktor', '', 40, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0e02e863-bdad-406a-a75b-ac364500cb6f', '6d660756-4f23-44c8-888e-23aaf6704df3', 'ka', 'სახელმწიფო და მუნიციპალური ზოგადსაგანმანათლებლო დაწესებულებების ტიპური წესდების თანახმად, ვინ ახორციელებს სკოლის საქმიანობის მიმდინარე ხელმძღვანელობას?', '["პედაგოგიური საბჭოს მიერ არჩეული თავმჯდომარე", "მშობელთა და მასწავლებელთა ასოციაციის თავმჯდომარე", "პროფკავშირის კომიტეტის ხელმძღვანელი", "შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს (განათლების მართვის ორგანოს) მიერ თანამდებობაზე დანიშნული დირექტორი", "მუნიციპალიტეტის თავმჯდომარის მიერ დანიშნული წარმომადგენელი"]'::jsonb, 'შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს (განათლების მართვის ორგანოს) მიერ თანამდებობაზე დანიშნული დირექტორი', 'Düzgün cavab: D) შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს (განათლების მართვის ორგანოს) მიერ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('787a5ad9-f1f4-4ba5-b4c7-d14f648e3d6e', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Ümumi təhsil müəssisələrində Pedaqoji Şura haqqında Əsasnaməyə əsasən, qərarların qəbul edilməsi qaydası necədir?', 'multiple_choice', '["İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilir", "Bütün üzvlər iştirak etməlidir, qərarlar 2/3 səs çoxluğu ilə qəbul edilir", "Yalnız fənn birləşmə rəhbərləri iştirak edir, qərarlar direktor tərəfindən təsdiqlənmir", "Üzvlərin yarısından çoxu iştirak etdikdə səlahiyyətlidir, qərarlar yekdilliklə qəbul edilir", "İclas açıq səsvermə ilə keçirilir, qərarlar katib tərəfindən rəsmiləşdirilir"]'::jsonb, 'İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilir', 'Düzgün cavab: A) İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qəra', '', 41, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1bebc784-a9fa-4409-86bc-cda400afc28c', '787a5ad9-f1f4-4ba5-b4c7-d14f648e3d6e', 'ka', 'ზოგადსაგანმანათლებლო დაწესებულებებში პედაგოგიური საბჭოს შესახებ დებულების თანახმად, როგორია გადაწყვეტილებების მიღების წესი?', '["სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით", "მონაწილეობენ მხოლოდ საგნობრივი გაერთიანებების ხელმძღვანელები, გადაწყვეტილებებს დირექტორი არ ამტკიცებს", "უფლებამოსილია, თუ ესწრება წევრთა ნახევარზე მეტი, გადაწყვეტილებები მიიღება ერთხმად", "სხდომა ტარდება ღია კენჭისყრით, გადაწყვეტილებებს აფორმებს მდივანი", "უნდა ესწრებოდეს ყველა წევრი, გადაწყვეტილებები მიიღება ხმების 2/3-ის უმრავლესობით"]'::jsonb, 'სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით', 'Düzgün cavab: A) სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e6f680cd-b219-4417-96c3-95b183e3135c', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'AR Əmək Məcəlləsinin 89 və 91-ci maddələrinə əsasən, iş vaxtının normal və qısaldılmış müddəti ilə bağlı düzgün norma hansıdır?', 'multiple_choice', '["Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz", "Normal iş vaxtı 40 saat, 16 yaşadək işçilər üçün 24 saatdır", "Normal iş vaxtı 36 saat, ağır sahədə çalışanlar üçün 30 saatdır", "Normal iş vaxtı 45 saat, pedaqoji işçilər üçün 30 saatdır", "Normal iş vaxtı 48 saat, yeniyetmələr üçün 40 saatdır"]'::jsonb, 'Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz', 'Düzgün cavab: A) Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün i', '', 42, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('363c0957-9a8d-4f4e-bc35-55dbe8419835', 'e6f680cd-b219-4417-96c3-95b183e3135c', 'ka', 'შრომის კოდექსის 89-ე და 91-ე მუხლების თანახმად, რომელია სწორი ნორმა სამუშაო დროის ნორმალურ და შემოკლებულ ხანგრძლივობასთან დაკავშირებით?', '["კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის – კვირაში 36 საათს", "ნორმალური სამუშაო დრო არის 40 საათი, 16 წლამდე ასაკის თანამშრომლებისთვის – 24 საათი", "ნორმალური სამუშაო დრო არის 45 საათი, პედაგოგიური მუშაკებისთვის – 30 საათი", "ნორმალური სამუშაო დრო არის 48 საათი, მოზარდებისთვის – 40 საათი", "ნორმალური სამუშაო დრო არის 36 საათი, მძიმე სფეროში მომუშავეთათვის – 30 საათი"]'::jsonb, 'კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის – კვირაში 36 საათს', 'Düzgün cavab: A) კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4a857cb3-0ee5-4b86-80e3-dfc13c0aad56', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'AR Əmək Məcəlləsinin 186-cı maddəsinə əsasən, əmək intizamını pozan işçiyə tətbiq edilə bilən intizam tənbehləri hansılardır?', 'multiple_choice', '["Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə əmək müqaviləsinin ləğvi", "İnzibati cərimə, ictimai işlər və müqaviləyə xitam", "Töhmət, maaşın 50% tutulması və vəzifənin aşağı salınması", "Xəbərdarlıq, töhmət, vəzifədən azad etmə və cərimə", "Şifahi töhmət, yazılı töhmət, şiddətli töhmət və işdən çıxarma"]'::jsonb, 'Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə əmək müqaviləsinin ləğvi', 'Düzgün cavab: A) Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutu', '', 43, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9d5b3c25-c9fe-4ced-aabb-64b2753982ac', '4a857cb3-0ee5-4b86-80e3-dfc13c0aad56', 'ka', 'შრომის კოდექსის 186-ე მუხლის თანახმად, რომელი დისციპლინური სახდელები შეიძლება დაეკისროს თანამშრომელს, რომელიც არღვევს შრომისა და საშემსრულებლო დისციპლინას?', '["საყვედური, მკაცრი საყვედური ბოლო გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალისწინებულ შემთხვევაში ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა და შრომის კოდექსის 70-ე მუხლით ხელშეკრულების შეწყვეტა", "ადმინისტრაციული ჯარიმა, საზოგადოებრივი სამუშაო და ხელშეკრულების შეწყვეტა", "ზეპირი საყვედური, წერილობითი საყვედური, მკაცრი საყვედური და სამსახურიდან დათხოვნა", "გაფრთხილება, საყვედური, თანამდებობიდან გათავისუფლება და ჯარიმა", "საყვედური, ხელფასის 50%-ის დაკავება და თანამდებობის დაქვეითება"]'::jsonb, 'საყვედური, მკაცრი საყვედური ბოლო გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალისწინებულ შემთხვევაში ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა და შრომის კოდექსის 70-ე მუხლით ხელშეკრულების შეწყვეტა', 'Düzgün cavab: A) საყვედური, მკაცრი საყვედური ბოლო გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0c8e8242-dc49-41be-8044-4ded5f3efac4', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'AR Əmək Məcəlləsinin 187 və 188-ci maddələrinə əsasən, intizam tənbehinin tətbiqi və qüvvədə olma müddəti hansı qaydada tənzimlənir?', 'multiple_choice', '["İzahat yalnız şifahi alınır və tənbeh 3 ay qüvvədə olur", "İntizam tənbehi verildikdə işçinin razılığı tələb olunur və 1 təqvim ili qüvvədə qalır", "İzahat tələb edilmədən tənbeh verilə bilər və verildiyi gündən 1 il qüvvədə qalır", "İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz", "İzahat mütləqdir, tənbeh məhkəmə qərarı ilə 2 il qüvvədə saxlanılır"]'::jsonb, 'İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz', 'Düzgün cavab: D) İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbe', '', 44, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e6a2db63-9ab4-45f7-ad06-ef308af366c0', '0c8e8242-dc49-41be-8044-4ded5f3efac4', 'ka', 'შრომის კოდექსის 187-ე მუხლის თანახმად, რა მოთხოვნაა დადგენილი დისციპლინური სახდელის დაკისრებისა და მისი მოქმედების ვადასთან დაკავშირებით?', '["სახდელი შეიძლება დაეკისროს ახსნა-განმარტების მოთხოვნის გარეშე და ძალაში რჩება 2 წელი", "ახსნა-განმარტება მიიღება მხოლოდ ზეპირად და სახდელი მოქმედებს 6 თვე", "ახსნა-განმარტება სავალდებულოა, სახდელი მოქმედებს 3 თვე და ავტომატურად იშლება", "დისციპლინური სახდელის დაკისრებამდე თანამშრომლისგან მოთხოვნილი უნდა იქნეს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია დაკისრების დღიდან 1 წლის განმავლობაში", "ახსნა-განმარტება არ მოითხოვება, სახდელი სასამართლოს გადაწყვეტილებით ძალაში რჩება 3 წელი"]'::jsonb, 'დისციპლინური სახდელის დაკისრებამდე თანამშრომლისგან მოთხოვნილი უნდა იქნეს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია დაკისრების დღიდან 1 წლის განმავლობაში', 'Düzgün cavab: D) დისციპლინური სახდელის დაკისრებამდე თანამშრომლისგან მოთხოვნილი უნდა იქნეს წერილობ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3112938c-f806-418d-aaa4-923ae17e54dc', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'AR Əmək Məcəlləsinin 69 və 172-ci maddələrinə əsasən, işçinin öz təşəbbüsü ilə əmək müqaviləsinə xitam verilməsi qaydası necədir?', 'multiple_choice', '["İşçi 3 iş günü əvvəl xəbərdarlıq edir, haqq-hesab 1 ay ərzində ödənilir", "İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab müqaviləyə xitam verildiyi sonuncu iş günündən gec olmayaraq tam ödənilir", "İşçi xəbərdarlıq etmədən çıxa bilər, haqq-hesab 10 gün ərzində ödənilir", "İşçi 15 gün əvvəl ərizə verir, haqq-hesab növbəti ayın 15-də ödənilir", "İşçi 2 həftə əvvəl şifahi xəbərdarlıq edir, haqq-hesab 7 gün ərzində ödənilir"]'::jsonb, 'İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab müqaviləyə xitam verildiyi sonuncu iş günündən gec olmayaraq tam ödənilir', 'Düzgün cavab: B) İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haq', '', 45, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7fd6fb0f-60ed-4307-9509-6e8f22570165', '3112938c-f806-418d-aaa4-923ae17e54dc', 'ka', 'შრომის კოდექსის 69-ე და 172-ე მუხლების თანახმად, როგორია დასაქმებულის საკუთარი ინიციატივით შრომითი ხელშეკრულების შეწყვეტის წესი?', '["დასაქმებული განცხადებას წარადგენს 15 დღით ადრე, ანგარიშსწორება ხდება მომდევნო თვის 15 რიცხვში", "დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი; საბოლოო ანგარიშსწორება სრულად უნდა განხორციელდეს ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღეს არაუგვიანეს", "დასაქმებულს შეუძლია წავიდეს გაფრთხილების გარეშე, ანგარიშსწორება ხდება 10 დღის ვადაში", "დასაქმებული აფრთხილებს 3 სამუშაო დღით ადრე, ანგარიშსწორება ხდება 1 თვის ვადაში", "დასაქმებული 2 კვირით ადრე ზეპირად აფრთხილებს, ანგარიშსწორება ხდება 7 დღის განმავლობაში"]'::jsonb, 'დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი; საბოლოო ანგარიშსწორება სრულად უნდა განხორციელდეს ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღეს არაუგვიანეს', 'Düzgün cavab: B) დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1f814a38-1f00-4019-abad-65e3a786957f', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Kompüter şəbəkələrinin əhatə dairəsinə görə LAN və WAN şəbəkələrinin əsas fərqi nədir?', 'multiple_choice', '["LAN dövlət qurumları üçün, WAN fərdi istifadəçilər üçündür", "LAN-da sürət aşağı, WAN-da sürət yüksək olur", "LAN internetə çıxış üçün, WAN lokal resurs paylaşımı üçündür", "LAN yalnız simli, WAN yalnız simsiz texnologiya ilə qurulur", "LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri birləşdirir, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir"]'::jsonb, 'LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri birləşdirir, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir', 'Düzgün cavab: E) LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri bi', '', 46, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6fd7ec17-084b-4cbf-b34b-42c78cd1404d', '1f814a38-1f00-4019-abad-65e3a786957f', 'ka', 'რა არის ძირითადი განსხვავება LAN და WAN ქსელებს შორის კომპიუტერული ქსელების მოქმედების არეალის მიხედვით?', '["LAN სახელმწიფო უწყებებისთვისაა, WAN – ინდივიდუალური მომხმარებლებისთვის", "LAN იქმნება მხოლოდ სადენიანი, WAN კი მხოლოდ უსადენო ტექნოლოგიით", "LAN-ში სიჩქარე დაბალია, WAN-ში – მაღალი", "LAN ინტერნეტში გასასვლელადაა, WAN – ლოკალური რესურსების გაზიარებისთვის", "LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა, კამპუსი) განთავსებულ კომპიუტერებს, ხოლო WAN არის განაწილებული გლობალური ქსელი, რომელიც აკავშირებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს"]'::jsonb, 'LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა, კამპუსი) განთავსებულ კომპიუტერებს, ხოლო WAN არის განაწილებული გლობალური ქსელი, რომელიც აკავშირებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს', 'Düzgün cavab: E) LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა, კამპუსი) განთა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('41235944-5e90-44a9-82c3-f6892ad66c22', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'İnternet şəbəkəsində domen adlarını IP ünvanlarına çevirən əsas şəbəkə xidməti hansıdır?', 'multiple_choice', '["Proxy Service (Vekil xidməti)", "NAT (Network Address Translation)", "DHCP (Dynamic Host Configuration Protocol)", "ARP (Address Resolution Protocol)", "DNS (Domain Name System)"]'::jsonb, 'DNS (Domain Name System)', 'Düzgün cavab: E) DNS (Domain Name System)', '', 47, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9bd32518-dff3-41d0-b1a5-db0a24e78a03', '41235944-5e90-44a9-82c3-f6892ad66c22', 'ka', 'რომელია ძირითადი ქსელური სერვისი, რომელიც ინტერნეტში დომენურ სახელებს IP მისამართებად გარდაქმნის?', '["NAT – მისამართების გარდაქმნის სისტემა", "DHCP – დინამიკური IP განაწილების სისტემა", "ARP – MAC მისამართის განსაზღვრის სისტემა", "Proxy Service – შუალედური ქეშირების სისტემა", "DNS (Domain Name System) – დომენური სახელების განაწილებული იერარქიული სისტემა"]'::jsonb, 'DNS (Domain Name System) – დომენური სახელების განაწილებული იერარქიული სისტემა', 'Düzgün cavab: E) DNS (Domain Name System) – დომენური სახელების განაწილებული იერარქიული სისტემა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b42e753e-4297-453d-af58-a11fa02c2425', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'İnformasiya təhlükəsizliyində ''İki faktorlu autentifikasiya'' (2FA) mexanizminin əsas üstünlüyü nədir?', 'multiple_choice', '["Eyni anda bir neçə cihazdan daxil olmanı məhdudlaşdırması", "Faylları avtomatik arxivləşdirərək yaddaşa qənaət etməsi", "Əməliyyat sisteminin yeniləmələrini avtomatik quraşdırması", "Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləməsi", "İnternet sürətini artıraraq şifrələmə prosesini sürətləndirməsi"]'::jsonb, 'Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləməsi', 'Düzgün cavab: D) Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifi', '', 48, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('77e0b6ed-54e2-47c1-8558-6f289e2b1316', 'b42e753e-4297-453d-af58-a11fa02c2425', 'ka', 'რა არის „ორფაქტორიანი აუთენტიფიკაციის“ (2FA) მექანიზმის მთავარი უპირატესობა ინფორმაციულ უსაფრთხოებაში?', '["ერთდროულად რამდენიმე მოწყობილობიდან შესვლის შეზღუდვა", "ოპერაციული სისტემის განახლებების ავტომატური ინსტალაცია", "ფაილების ავტომატური დაარქივება მეხსიერების დაზოგვის მიზნით", "პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების გარეშე (SMS კოდი, TOTP, აუთენტიფიკატორის აპლიკაცია ან FIDO2 გასაღები)", "ინტერნეტის სიჩქარის გაზრდა დაშიფვრის პროცესის დაჩქარებით"]'::jsonb, 'პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების გარეშე (SMS კოდი, TOTP, აუთენტიფიკატორის აპლიკაცია ან FIDO2 გასაღები)', 'Düzgün cavab: D) პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('cc88b866-6a66-46cc-8ff0-95da6da56cbf', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Fırıldaqçıların etibarlı təşkilat adından saxta e-poçt və keçidlər göndərərək məlumatları mənimsəməsi hansı kiberhücum növüdür?', 'multiple_choice', '["Spoofing (Ünvan saxtalaşdırması)", "Fişinq (Phishing)", "Sniffing (Trafik dinlənilməsi)", "Ransomware (Fidyə proqramı)", "Brute Force (Şifrə seçimi)"]'::jsonb, 'Fişinq (Phishing)', 'Düzgün cavab: B) Fişinq (Phishing)', '', 49, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d00c428f-8a7d-4ee4-830d-3fd1726cf040', 'cc88b866-6a66-46cc-8ff0-95da6da56cbf', 'ka', 'კიბერშეტევის რომელ სახეს მიეკუთვნება თაღლითების მიერ სანდო ორგანიზაციის სახელით ყალბი ელფოსტის გაგზავნა მონაცემების მითვისების მიზნით?', '["Brute Force – პაროლის შერჩევა მასობრივი ცდების გზით", "ფიშინგი (Phishing) – საიდენტიფიკაციო მონაცემების მოპარვა სოციალური ინჟინერიის საფუძველზე, ყალბი ელფოსტისა და ვებსაიტის მეშვეობით", "Ransomware – ფაილების დაშიფვრა გამოსასყიდის მოთხოვნით", "Spoofing – IP ან MAC მისამართის გაყალბება", "Sniffing – ქსელური ტრაფიკის ფარული მოსმენა"]'::jsonb, 'ფიშინგი (Phishing) – საიდენტიფიკაციო მონაცემების მოპარვა სოციალური ინჟინერიის საფუძველზე, ყალბი ელფოსტისა და ვებსაიტის მეშვეობით', 'Düzgün cavab: B) ფიშინგი (Phishing) – საიდენტიფიკაციო მონაცემების მოპარვა სოციალური ინჟინერიის სა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4e08ff79-9947-43d5-a470-71e0847cd027', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Microsoft Word proqramında abzasın girintilərini dəqiq tənzimləmək üçün hansı interfeys elementindən istifadə olunur?', 'multiple_choice', '["Sürətli müraciət paneli və lent interfeysi", "Naviqasiya paneli və axtarış qutusu", "Vəziyyət zolağı və miqyas sürüşdürücüsü", "Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi", "Şaquli xətkeş və səhifə kənar boşluqları"]'::jsonb, 'Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi', 'Düzgün cavab: D) Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph', '', 50, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('5609125a-95e0-417c-a336-0f135a1adfc5', '4e08ff79-9947-43d5-a470-71e0847cd027', 'ka', 'ინტერფეისის რომელი ელემენტი გამოიყენება Microsoft Word-ში აბზაცის შეწევების (ინდენტაციის) ზუსტად დასარეგულირებლად?', '["სწრაფი წვდომის პანელი და ლენტის ინტერფეისი", "სტატუსის ზოლი და მასშტაბის სლაიდერი", "ვერტიკალური სახაზავი და გვერდის მინდვრები", "ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული შეწევის სლაიდერები და დიალოგური ფანჯარა Paragraph", "ნავიგაციის პანელი და ძიების ველი"]'::jsonb, 'ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული შეწევის სლაიდერები და დიალოგური ფანჯარა Paragraph', 'Düzgün cavab: D) ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული შეწევის სლაიდერები და დიალოგუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('77f644c3-e1b3-46b9-8b39-3440115cad52', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Microsoft Word sənədində bəzi səhifələri şaquli, bəzi səhifələri üfüqi oriyentasiyada formatlamaq üçün hansı əməliyyat icra olunmalıdır?', 'multiple_choice', '["Hər səhifə üçün ayrıca Page Break əlavə edilib oriyentasiya dəyişdirilməlidir", "Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir", "Mətn qutuları istifadə edilərək səhifə fırladılmalıdır", "Sənəd iki ayrı fayla bölünüb hər birinin oriyentasiyası ayrı təyin edilməlidir", "Səhifə kənar boşluqları dəyişdirilərək üfüqi effekt yaradılmalıdır"]'::jsonb, 'Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir', 'Düzgün cavab: B) Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin O', '', 51, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f5744a88-968f-4379-93f5-b83fd8e70763', '77f644c3-e1b3-46b9-8b39-3440115cad52', 'ka', 'Microsoft Word-ის დოკუმენტში ზოგიერთი გვერდის ვერტიკალურ (წიგნისებურ), ხოლო ზოგიერთის ჰორიზონტალურ (ალბომურ) ორიენტაციაში დასაფორმატებლად რომელი ოპერაცია უნდა შესრულდეს?', '["დოკუმენტი უნდა გაიყოს ორ ცალკე ფაილად და თითოეულის ორიენტაცია ცალ-ცალკე განისაზღვროს", "დოკუმენტს უნდა დაემატოს სექციის გაწყვეტა (Section Break - Next Page) და ამ სექციისთვის შეიცვალოს პარამეტრი Layout > Orientation", "თითოეული გვერდისთვის ცალკე უნდა დაემატოს Page Break და შეიცვალოს ორიენტაცია", "ტექსტური ველების (Text Box) გამოყენებით გვერდი უნდა შემოტრიალდეს", "გვერდის მინდვრების შეცვლით უნდა შეიქმნას ჰორიზონტალური ეფექტი"]'::jsonb, 'დოკუმენტს უნდა დაემატოს სექციის გაწყვეტა (Section Break - Next Page) და ამ სექციისთვის შეიცვალოს პარამეტრი Layout > Orientation', 'Düzgün cavab: B) დოკუმენტს უნდა დაემატოს სექციის გაწყვეტა (Section Break - Next Page) და ამ სექცი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fe40e52a-0138-4ad3-a9de-214e65b1647c', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Microsoft Word proqramında başlıqlara əsasən avtomatik yenilənən Mündəricat yaratmaq üçün hansı taba müraciət edilir?', 'multiple_choice', '["View > Navigation Pane", "Layout > Table of Contents", "Insert > Table of Contents", "Review > Table of Contents", "References (İstinadlar) tabı > Table of Contents"]'::jsonb, 'References (İstinadlar) tabı > Table of Contents', 'Düzgün cavab: E) References (İstinadlar) tabı > Table of Contents', '', 52, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7f7bd3bc-0509-45c0-9a26-e2fc67cb6c14', 'fe40e52a-0138-4ad3-a9de-214e65b1647c', 'ka', 'სათაურების მიხედვით ავტომატურად განახლებადი სარჩევის შესაქმნელად Microsoft Word-ში რომელ ჩანართს (Tab) უნდა მივმართოთ?', '["View > Navigation Pane", "Insert > Table of Contents", "Layout > Table of Contents", "Review > Table of Contents", "References ჩანართი > Table of Contents ჯგუფი"]'::jsonb, 'References ჩანართი > Table of Contents ჯგუფი', 'Düzgün cavab: E) References ჩანართი > Table of Contents ჯგუფი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ef69f8e8-1ac8-478c-b31e-07437635d318', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Microsoft Excel cədvəlində `$C$2` mütləq xana ünvanı olan düstur başqa xanalara kopyalandıqda necə dəyişir?', 'multiple_choice', '["Düstur xəta verir və #REF! qaytarır", "Yalnız sütun sabit qalır, sətir dəyişir", "Yalnız sətir sabit qalır, sütun dəyişir", "Həm sütun, həm sətir avtomatik sürüşür", "Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır"]'::jsonb, 'Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', 'Düzgün cavab: E) Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', '', 53, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cccd67a6-0987-4090-b863-0aaf3daf5400', 'ef69f8e8-1ac8-478c-b31e-07437635d318', 'ka', 'როგორ იცვლება Microsoft Excel-ის ცხრილში ფორმულა სხვა უჯრებში კოპირებისას, თუ მასში გამოყენებულია აბსოლუტური მისამართი $C$2?', '["მხოლოდ სვეტი რჩება უცვლელი, სტრიქონი კი იცვლება", "მხოლოდ სტრიქონი რჩება უცვლელი, სვეტი კი იცვლება", "ავტომატურად ინაცვლებს როგორც სვეტი, ისე სტრიქონი", "ფორმულა იძლევა შეცდომას და აბრუნებს #REF!-ს", "რადგან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური ბმული)"]'::jsonb, 'რადგან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური ბმული)', 'Düzgün cavab: E) რადგან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f566ee82-995c-4e30-aded-848b03fdbf1b', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Microsoft Excel proqramında `A1:A10` diapazonunda yalnız qiyməti 50-dən böyük olan xanaların sayını hesablamaq üçün hansı funksiya düzgündür?', 'multiple_choice', '["=COUNTIF(A1:A10; \">50\")", "=IF(A1:A10>50; COUNT(A1:A10))", "=COUNTIFS(A1:A10; \">50\")", "=SUMIF(A1:A10; \">50\")", "=COUNTIF(A1:A10; >50)"]'::jsonb, '=COUNTIF(A1:A10; ">50")', 'Düzgün cavab: A) =COUNTIF(A1:A10; ">50")', '', 54, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('5a8d916a-aaa7-4d44-83b5-3f345879c02b', 'f566ee82-995c-4e30-aded-848b03fdbf1b', 'ka', 'Microsoft Excel-ში რომელი ფუნქციაა სწორი A1:A10 დიაპაზონში მხოლოდ იმ უჯრების რაოდენობის დასათვლელად, რომელთა მნიშვნელობა 50-ზე მეტია?', '["=COUNTIF(A1:A10;\">50\")", "=SUMIF(A1:A10;\">50\") - პირობითი ჯამი", "=IF(A1:A10>50;COUNT(A1:A10)) - მასივის ფორმულა", "=COUNTIFS(A1:A10;\">50\") - რთული პირობითი რაოდენობა", "=COUNTIF(A1:A10;>50) - ჩანაწერი ბრჭყალების გარეშე"]'::jsonb, '=COUNTIF(A1:A10;">50")', 'Düzgün cavab: A) =COUNTIF(A1:A10;">50")', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0b4a4506-39b9-416e-b9c6-1d53629b81bb', '1940e17b-2e5d-4863-83aa-0206aad16aa3', 'Microsoft Excel-də B2 xanasındakı əməkhaqqı 800-dən çox olduqda 15% mükafat, əks halda 5% hesablayan düstur hansıdır?', 'multiple_choice', '["=IF(B2>=800; B2*0.15; B2*0.05)", "=IF(B2>800; B2*0.15; B2*0.05)", "=IF(B2>800; B2*15%; B2*5%)", "=IFS(B2>800; B2*0.15; TRUE; B2*0.05)", "=SWITCH(B2>800; TRUE; B2*0.15; FALSE; B2*0.05)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: B) =IF(B2>800; B2*0.15; B2*0.05)', '', 55, true, false, true, 1.0, 'exact', true, false, NOW());
