INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7f3d08d0-bce9-4a0b-bd28-2c04005d1ca7', '67cfa91f-5aea-475e-9c53-9ed8aab4a4fd', 'ka', 'რას გამოხატავს „ჰალუცინაციის“ რისკი ხელოვნურ ინტელექტზე დაფუძნებულ გენერაციულ მოდელებში?', '["მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ბმულების ან წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით", "მოდელის მიერ მომხმარებლის მოთხოვნის გაუგებრობის გამო შემთხვევითი პასუხის გაცემას", "მოდელის მიერ კომპიუტერის რესურსების გადაჭარბებულად გადატვირთვას", "მოდელის მიერ პასუხის მხოლოდ ინგლისურ ენაზე გაცემას და სხვა ენების მხარდაუჭერლობას", "მოდელის მიერ პასუხის გაცემაზე უარის თქმას და შეცდომის დაბრუნებას"]'::jsonb, 'მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ბმულების ან წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით', 'Düzgün cavab: A) მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ბმულების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0286bc86-5266-4e6b-a297-b8a38f5fbd7b', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', '“Kitabxana işi haqqında” AR Qanununa əsasən, kitabxana fondunun hüquqi tərifi hansı bənddə düzgün verilmişdir?', 'multiple_choice', '["İstifadəçilərin tələbatını ödəmək üçün toplanan, saxlanan, sistemləşdirilən və mühafizə olunan bütün növ sənədlərin nizamlanmış, qeydiyyata alınmış məcmusu", "Kitabxananın oxu zalında daimi qorunan və abunəçilərə verilməyən nadir əlyazmalar fondu", "Yalnız ümumi təhsil müəssisələrində tədris olunan fənn dərslikləri və metodik vəsaitlərin toplusu", "Kitabxananın cari ildə dövlət büdcəsi hesabına abunə olduğu dövri mətbuat orqanlarının illik arxivi", "Yalnız dövlət hakimiyyəti orqanlarının qəbul etdiyi normativ hüquqi aktlar və məcəllələr toplusu"]'::jsonb, 'İstifadəçilərin tələbatını ödəmək üçün toplanan, saxlanan, sistemləşdirilən və mühafizə olunan bütün növ sənədlərin nizamlanmış, qeydiyyata alınmış məcmusu', 'Düzgün cavab: A) İstifadəçilərin tələbatını ödəmək üçün toplanan, saxlanan, sistemləşdirilən və m', '', 1, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1fbf5628-7f87-46a9-ad05-05bc4ddf93b8', '0286bc86-5266-4e6b-a297-b8a38f5fbd7b', 'ka', 'კანონის „საბიბლიოთეკო საქმის შესახებ“ თანახმად, რა არის საბიბლიოთეკო ფონდის სამართლებრივი დეფინიცია?', '["ყველა სახის დოკუმენტის მოწესრიგებული, აღრიცხული ერთობლიობა, რომელიც შეგროვებული, შენახული, სისტემატიზებული და დაცულია მომხმარებელთა მოთხოვნილებების დასაკმაყოფილებლად", "პერიოდული გამოცემების წლიური არქივი, რომელზეც ბიბლიოთეკა მიმდინარე წელს სახელმწიფო ბიუჯეტის ხარჯზეა გამოწერილი", "მხოლოდ სახელმწიფო ხელისუფლების ორგანოების მიერ მიღებული ნორმატიულ-სამართლებრივი აქტები და კოდექსები", "სამკითხველო დარბაზში მუდმივად დაცული იშვიათ ხელნაწერთა კრებული, რომელიც აბონენტებზე არ გაიცემა", "მხოლოდ ზოგადსაგანმანათლებლო დაწესებულებებში სასწავლო საგნობრივი სახელმძღვანელოებისა და მეთოდიკური სახელმძღვანელოების კრებული"]'::jsonb, 'ყველა სახის დოკუმენტის მოწესრიგებული, აღრიცხული ერთობლიობა, რომელიც შეგროვებული, შენახული, სისტემატიზებული და დაცულია მომხმარებელთა მოთხოვნილებების დასაკმაყოფილებლად', 'Düzgün cavab: A) ყველა სახის დოკუმენტის მოწესრიგებული, აღრიცხული ერთობლიობა, რომელიც შეგროვებული,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('60f400f0-46d6-488a-b445-7f97860bdd0e', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', '“Kitabxana işi haqqında” AR Qanununa əsasən, kitabxana istifadəçilərinin əsas hüquqlarına aid olan müddəa hansıdır?', 'multiple_choice', '["Kitabxananın daxili nizamnaməsini və struktur bölmələrinin fəaliyyətini müstəqil dəyişdirmək", "Fonda daxil olan nadir nəşrləri kommersiya məqsədilə şəxsi mülkiyyətinə keçirmək", "Kitabxana fondundan sənədləri müvəqqəti istifadə üçün almaq, kataloq və kartotekalardan, informasiya və məsləhət xidmətindən sərbəst yararlanmaq", "Kitabxana fonduna daxil olan ədəbiyyatın qiymətləndirilməsini və silinməsini təkbaşına icra etmək", "Ştat cədvəlinin müəyyən edilməsində və kadrların təyin olunmasında birbaşa iştirak etmək"]'::jsonb, 'Kitabxana fondundan sənədləri müvəqqəti istifadə üçün almaq, kataloq və kartotekalardan, informasiya və məsləhət xidmətindən sərbəst yararlanmaq', 'Düzgün cavab: C) Kitabxana fondundan sənədləri müvəqqəti istifadə üçün almaq, kataloq və kartotek', '', 2, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('276f082c-040d-4231-b8b6-d22f1f43c6bd', '60f400f0-46d6-488a-b445-7f97860bdd0e', 'ka', 'კანონის „საბიბლიოთეკო საქმის შესახებ“ მე-15 მუხლის თანახმად, რომელი დებულება განეკუთვნება ბიბლიოთეკის მომხმარებელთა ძირითად უფლებებს?', '["ბიბლიოთეკის შინაგანაწესისა და სტრუქტურული ქვედანაყოფების საქმიანობის დამოუკიდებლად შეცვლა", "საშტატო განრიგის განსაზღვრასა და კადრების დანიშვნაში უშუალო მონაწილეობის მიღება", "საბიბლიოთეკო ფონდიდან დოკუმენტების დროებით სარგებლობაში მიღება, კატალოგებითა და კარტოთეკებით, საინფორმაციო და საკონსულტაციო მომსახურებით თავისუფლად სარგებლობა", "ფონდში არსებული იშვიათი გამოცემის კომერციული მიზნით პირად საკუთრებაში გადაცემა", "საბიბლიოთეკო ფონდში შემოსული ლიტერატურის შეფასებისა და ჩამოწერის ერთპიროვნულად განხორციელება"]'::jsonb, 'საბიბლიოთეკო ფონდიდან დოკუმენტების დროებით სარგებლობაში მიღება, კატალოგებითა და კარტოთეკებით, საინფორმაციო და საკონსულტაციო მომსახურებით თავისუფლად სარგებლობა', 'Düzgün cavab: C) საბიბლიოთეკო ფონდიდან დოკუმენტების დროებით სარგებლობაში მიღება, კატალოგებითა და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fbadc7ca-a1ef-4d59-97ae-fcb4827aedde', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Ümumi təhsil müəssisəsinin kitabxanasının Nümunəvi Əsasnaməsinə əsasən, məktəb kitabxanasının başlıca funksiyası nədir?', 'multiple_choice', '["Təhsilalanları və pedaqoji kollektivi tədris prosesini təmin edən dərslik, bədii, elmi, metodik ədəbiyyatla təchiz etmək və mütaliə mədəniyyətini formalaşdırmaq", "Fənn olimpiadalarının test suallarını hazırlamaq və attestasiya nəticələrini təsdiqləmək", "Məktəb binasının təmir işlərinə və kommunal istilik sistemlərinə texniki rəhbərlik etmək", "Məktəbin bütün kadr kargüzarlığını və əmək müqavilələrinin elektron qeydiyyatını idarə etmək", "Şagirdlərin dərsdənkənar kommersiya yönümlü fəaliyyətlərini və ödənişli kurslarını təşkil etmək"]'::jsonb, 'Təhsilalanları və pedaqoji kollektivi tədris prosesini təmin edən dərslik, bədii, elmi, metodik ədəbiyyatla təchiz etmək və mütaliə mədəniyyətini formalaşdırmaq', 'Düzgün cavab: A) Təhsilalanları və pedaqoji kollektivi tədris prosesini təmin edən dərslik, bədii', '', 3, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('47131472-8493-4c9a-af40-fb19fde58628', 'fbadc7ca-a1ef-4d59-97ae-fcb4827aedde', 'ka', 'ზოგადსაგანმანათლებლო დაწესებულების ბიბლიოთეკის ტიპური დებულების თანახმად, რა არის სასკოლო ბიბლიოთეკის მთავარი ფუნქცია?', '["შემსწავლელთა და პედაგოგიური კოლექტივის სრული და დროული უზრუნველყოფა სახელმძღვანელოებით, მხატვრული, სამეცნიერო, მეთოდიკური და პერიოდული ლიტერატურით სასწავლო პროცესის, სწავლა-აღზრდისა და თვითგანათლების მხარდასაჭერად და კითხვის კულტურის ჩამოყალიბება", "მოსწავლეთა კლასგარეშე კომერციული მიმართულების საქმიანობებისა და ფასიანი კურსების ორგანიზება", "სასკოლო ოლიმპიადების სატესტო დავალებების მომზადება და ატესტაციის შედეგების დამტკიცება", "სასკოლო შენობის მატერიალურ-ტექნიკური სარემონტო სამუშაოებისა და საქვაბის კომუნალური სისტემების მართვა", "სკოლის მთელი საკადრო საქმისწარმოებისა და შრომითი ხელშეკრულებების ელექტრონული რეგისტრაციის მართვა"]'::jsonb, 'შემსწავლელთა და პედაგოგიური კოლექტივის სრული და დროული უზრუნველყოფა სახელმძღვანელოებით, მხატვრული, სამეცნიერო, მეთოდიკური და პერიოდული ლიტერატურით სასწავლო პროცესის, სწავლა-აღზრდისა და თვითგანათლების მხარდასაჭერად და კითხვის კულტურის ჩამოყალიბება', 'Düzgün cavab: A) შემსწავლელთა და პედაგოგიური კოლექტივის სრული და დროული უზრუნველყოფა სახელმძღვანე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d5557d78-f6e9-4ebd-9708-eb19b71ef097', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Məktəb kitabxanasında fonda daxil olan hər bir kitab nüsxəsinin fərdi (hissəvi) uçotu hansı əsas dövlət sənədində aparılır?', 'multiple_choice', '["Oxucu formulyarının fərdi qeydiyyat kartoçkasında", "Şagirdlərin dərsdənkənar fərdi mütaliə gündəliyində", "Dövri mətbuatın illik abunə və qeydiyyat vərəqəsində", "Kitabxana xidmətinin illik maliyyə smeta cədvəlində", "Kitabxana fondunun İnventar Kitabında (İnventar reyestrində)"]'::jsonb, 'Kitabxana fondunun İnventar Kitabında (İnventar reyestrində)', 'Düzgün cavab: E) Kitabxana fondunun İnventar Kitabında (İnventar reyestrində)', '', 4, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f1a7fb47-9d9f-4f3c-a59c-19f2c7287223', 'd5557d78-f6e9-4ebd-9708-eb19b71ef097', 'ka', 'სასკოლო ბიბლიოთეკაში რომელ ძირითად სახელმწიფო სააღრიცხვო დოკუმენტში წარმოებს ფონდში შემოსული თითოეული წიგნის ინდივიდუალური (ცალობითი) აღრიცხვა?', '["საბიბლიოთეკო მომსახურების წლიური საფინანსო ხარჯთაღრიცხვის ცხრილში", "პერიოდული გამოცემების წლიური რეგისტრაციისა და გამოწერის ფურცელში", "მოსწავლეთა კლასგარეშე ინდივიდუალური კითხვის დღიურში", "მკითხველის ფორმულარის ინდივიდუალური რეგისტრაციის ბარათში", "საბიბლიოთეკო ფონდის ინვენტარულ წიგნში (ინვენტარის რეესტრში) - თითოეული ეგზემპლარისთვის ცალკე ინვენტარული ნომრით"]'::jsonb, 'საბიბლიოთეკო ფონდის ინვენტარულ წიგნში (ინვენტარის რეესტრში) - თითოეული ეგზემპლარისთვის ცალკე ინვენტარული ნომრით', 'Düzgün cavab: E) საბიბლიოთეკო ფონდის ინვენტარულ წიგნში (ინვენტარის რეესტრში) - თითოეული ეგზემპლარ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('42feb969-01e9-41f5-b395-17f5d1fd26c7', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Müasir məktəb kitabxanalarında fondun elektron uçotu, axtarışı və elektron kataloqun formalaşdırılması üçün istifadə olunan sistem necə adlanır?', 'multiple_choice', '["Lokal şəbəkə fayl mübadiləsi serveri (FTP)", "Avtomatlaşdırılmış Kitabxana-İnformasiya Sistemi (AKİS / ALİS)", "Əməliyyat sisteminin fayl arxivləşdirmə utiliti (WinRAR)", "Mühasibat uçotunun 1C elektron əməliyyat proqramı", "Qrafik dizayn və təsvir emalı proqram paketi (Photoshop)"]'::jsonb, 'Avtomatlaşdırılmış Kitabxana-İnformasiya Sistemi (AKİS / ALİS)', 'Düzgün cavab: B) Avtomatlaşdırılmış Kitabxana-İnformasiya Sistemi (AKİS / ALİS)', '', 5, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3de44377-d627-4289-9aad-e08ced44cfc9', '42feb969-01e9-41f5-b395-17f5d1fd26c7', 'ka', 'თანამედროვე სასკოლო ბიბლიოთეკებში რა ეწოდება პროგრამულ კომპლექსს, რომელიც გამოიყენება ფონდის ელექტრონული აღრიცხვისა და კატალოგის ფორმირებისთვის?', '["ოპერაციული სისტემის ფაილების საარქივო უტილიტა (WinRAR)", "ავტომატიზებული საბიბლიოთეკო-საინფორმაციო სისტემა (AKİS / ALİS / Koha / IRBIS ტიპის ელექტრონული საბიბლიოთეკო პროგრამა)", "გრაფიკული რედაქტორი და ანიმაციური პროგრამების პაკეტი (Photoshop, Corel)", "ელექტრონული ფოსტის სერვერი და სპამის ფილტრაციის პროგრამა", "ბუღალტერიის 1C ელექტრონული ოპერაციული სისტემა"]'::jsonb, 'ავტომატიზებული საბიბლიოთეკო-საინფორმაციო სისტემა (AKİS / ALİS / Koha / IRBIS ტიპის ელექტრონული საბიბლიოთეკო პროგრამა)', 'Düzgün cavab: B) ავტომატიზებული საბიბლიოთეკო-საინფორმაციო სისტემა (AKİS / ALİS / Koha / IRBIS ტიპ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9c6c1321-9387-49cf-a3c0-d071dac10b4c', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana fonduna qəbul edilən hər bir nüsxəyə verilən və fonddan silinənədək dəyişməz qalan fərdi uçot kodu necə adlanır?', 'multiple_choice', '["Nəşriyyat barkodu (ISBN)", "Qeydiyyat seriyası", "İnventar nömrəsi", "Təsnifat indeksi", "Müəllif nişanı"]'::jsonb, 'İnventar nömrəsi', 'Düzgün cavab: C) İnventar nömrəsi', '', 6, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('65a6a10d-e60f-4379-995b-ec0d48458437', '9c6c1321-9387-49cf-a3c0-d071dac10b4c', 'ka', 'რა ეწოდება ინდივიდუალურ კოდს, რომელიც ენიჭება საბიბლიოთეკო ფონდში მიღებულ თითოეულ ეგზემპლარს და უცვლელი რჩება ფონდიდან ამორიცხვამდე?', '["საავტორო ნიშანი - ხავკინას ცხრილის მიხედვით ასო-ციფრული კომბინაცია", "სარეგისტრაციო სერია - ჯამური აღრიცხვის წიგნში რიგითი ნომერი", "ინვენტარული ნომერი - ფონდში მიღებული თითოეული ეგზემპლარის ინდივიდუალური, უნიკალური სააღრიცხვო ნომერი", "საგამომცემლო შტრიხკოდი - ISBN ან საერთაშორისო შტრიხკოდი", "კლასიფიკაციის ინდექსი - უთკ (UDC) ან საბიბლიოთეკო-ბიბლიოგრაფიული კლასიფიკაციის მიხედვით მეცნიერების დარგობრივი კოდი"]'::jsonb, 'ინვენტარული ნომერი - ფონდში მიღებული თითოეული ეგზემპლარის ინდივიდუალური, უნიკალური სააღრიცხვო ნომერი', 'Düzgün cavab: C) ინვენტარული ნომერი - ფონდში მიღებული თითოეული ეგზემპლარის ინდივიდუალური, უნიკალუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('58a47af7-b2d4-475d-8ee9-11c8cae7cae1', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxanaya yeni daxil olmuş ədəbiyyat partiyasının işlənməsi prosesində hansı mərhələ fərdi inventar uçotundan **ƏVVƏL** icra olunmalıdır?', 'multiple_choice', '["Kitabın dərhal oxu zalının açıq rəflərinə yerləşdirilməsi", "Kitabların ilkin yoxlanılması, ştamplanması və Cəmi (ümumi) uçot kitabında (K-1) qeydə alınması", "Kitabların cildlərinin bərkidilməsi və laminasiya edilməsi", "Kitabın oxucunun fərdi formulyarına daxil edilərək verilməsi", "Kitabın fonddan silinməsi üzrə rəsmi aktın tərtibi"]'::jsonb, 'Kitabların ilkin yoxlanılması, ştamplanması və Cəmi (ümumi) uçot kitabında (K-1) qeydə alınması', 'Düzgün cavab: B) Kitabların ilkin yoxlanılması, ştamplanması və Cəmi (ümumi) uçot kitabında (K-1)', '', 7, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('47e0e616-8f47-4839-866f-dac624da7bde', '58a47af7-b2d4-475d-8ee9-11c8cae7cae1', 'ka', 'ბიბლიოთეკაში ახლად შემოსული ლიტერატურის პარტიის დამუშავების პროცესში რომელი ეტაპი უნდა შესრულდეს ინდივიდუალურ აღრიცხვამდე?', '["წიგნის ყდის გამაგრება და ლამინირება", "წიგნების დაშტამპვა (დაბეჭდვა), ჯამური (საერთო) აღრიცხვის წიგნში რეგისტრაცია და პირველადი შემოწმება", "წიგნის ფონდიდან ჩამოწერის ოფიციალური აქტის შედგენა და დამტკიცება", "წიგნის მკითხველის ინდივიდუალურ ფორმულარში შეტანა", "წიგნის დაუყოვნებლივ სამკითხველო დარბაზში განთავსება და მკითხველზე გაცემა"]'::jsonb, 'წიგნების დაშტამპვა (დაბეჭდვა), ჯამური (საერთო) აღრიცხვის წიგნში რეგისტრაცია და პირველადი შემოწმება', 'Düzgün cavab: B) წიგნების დაშტამპვა (დაბეჭდვა), ჯამური (საერთო) აღრიცხვის წიგნში რეგისტრაცია და პ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b08b277b-10d4-4074-a035-fe08089628fe', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Universal Onluq Təsnifat (UOK) və ya Kitabxana-Biblioqrafiya Təsnifatı (KBT) sistemlərində ədəbiyyat hansı prinsipə əsasən qruplaşdırılır?', 'multiple_choice', '["Kitabın fiziki ölçülərinə və səhifələrinin ümumi sayına görə", "Elm sahələrinə, bilik sahələrinə və məzmunun mövzu istiqamətinə görə", "Kitabın poliqrafik tərtibatına və nəşr ilinin ardıcıllığına görə", "Nəşriyyatın yerləşdiyi inzibati və coğrafi əraziyə görə", "Müəllifin vətəndaşlığına, elmi dərəcəsinə və yaşına görə"]'::jsonb, 'Elm sahələrinə, bilik sahələrinə və məzmunun mövzu istiqamətinə görə', 'Düzgün cavab: B) Elm sahələrinə, bilik sahələrinə və məzmunun mövzu istiqamətinə görə', '', 8, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2036137b-28e4-4a12-9221-f0f8e176262b', 'b08b277b-10d4-4074-a035-fe08089628fe', 'ka', 'უნივერსალური ათწილადი კლასიფიკაციისა (უთკ / UDC) ან საბიბლიოთეკო-ბიბლიოგრაფიული კლასიფიკაციის სისტემებში რა პრინციპით ჯგუფდება ლიტერატურა?', '["გამომცემლობის ადმინისტრაციული და გეოგრაფიული მდებარეობის მიხედვით", "მეცნიერების დარგების, ცოდნის სფეროებისა და შინაარსის თემატური მიმართულების, იერარქიული სტრუქტურის მიხედვით", "წიგნის ყდის პოლიგრაფიული გაფორმებისა და გამოცემის წლის მიხედვით", "წიგნის ფიზიკური ზომებისა და გვერდების საერთო რაოდენობის მიხედვით", "ავტორის მოქალაქეობის, სამეცნიერო ხარისხისა და ასაკის მიხედვით"]'::jsonb, 'მეცნიერების დარგების, ცოდნის სფეროებისა და შინაარსის თემატური მიმართულების, იერარქიული სტრუქტურის მიხედვით', 'Düzgün cavab: B) მეცნიერების დარგების, ცოდნის სფეროებისა და შინაარსის თემატური მიმართულების, იერა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bf5b3d96-058c-4717-a6cc-7770402c8f67', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxanaçılıq praktikasında Xavkina cədvəli (Müəllif cədvəli) hansı məqsədlə tətbiq olunur?', 'multiple_choice', '["Müəllifin soyadının və ya kitabın sərlövhəsinin ilk hərflərinə əsasən müəllif nişanını müəyyən etmək və rəfdə əlifba düzülüşünü təmin etmək üçün", "Kitabxananın illik oxucu kontingentini yaş qrupları üzrə qeydə almaq üçün", "Kitabın nəşr olunduğu tirajın ümumi həcmini dəqiqləşdirmək üçün", "Kitabın pərakəndə satış bazarındakı qiymətini hesablamaq üçün", "Oxucuların fərdi mütaliə sürətini və dərketmə dərəcəsini qiymətləndirmək üçün"]'::jsonb, 'Müəllifin soyadının və ya kitabın sərlövhəsinin ilk hərflərinə əsasən müəllif nişanını müəyyən etmək və rəfdə əlifba düzülüşünü təmin etmək üçün', 'Düzgün cavab: A) Müəllifin soyadının və ya kitabın sərlövhəsinin ilk hərflərinə əsasən müəllif ni', '', 9, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('414b1b6c-03cb-4950-a842-003aceaaf604', 'bf5b3d96-058c-4717-a6cc-7770402c8f67', 'ka', 'საბიბლიოთეკო პრაქტიკაში რა მიზნით გამოიყენება ხავკინას ცხრილი (საავტორო ცხრილი)?', '["ავტორის გვარის ან წიგნის სათაურის პირველი ასოების მიხედვით საავტორო ნიშნის (ასო + ციფრი) განსასაზღვრად და თაროზე ანბანური განლაგების უზრუნველსაყოფად", "ბიბლიოთეკის მკითხველთა წლიური კონტინგენტის კატეგორიების მიხედვით დასაჯგუფებლად", "წიგნის გამოცემის ტირაჟის საერთო მოცულობის დასაზუსტებლად", "სავაჭრო ქსელებში წიგნის საცალო გასაყიდი ფასის გამოსათვლელად", "მკითხველთა ინდივიდუალური კითხვის სიჩქარისა და ინტელექტის დონის შესამოწმებლად"]'::jsonb, 'ავტორის გვარის ან წიგნის სათაურის პირველი ასოების მიხედვით საავტორო ნიშნის (ასო + ციფრი) განსასაზღვრად და თაროზე ანბანური განლაგების უზრუნველსაყოფად', 'Düzgün cavab: A) ავტორის გვარის ან წიგნის სათაურის პირველი ასოების მიხედვით საავტორო ნიშნის (ასო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f590c982-0101-4649-a180-686198d53e4c', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Əlifba kataloqunda biblioqrafik kartoçkalar hansı ardıcıllıqla sistemləşdirilir?', 'multiple_choice', '["Elm sahələrinin iyerarxik təsnifat dərəcəsinə və indeksinə görə", "Müəlliflərin soyadlarının və ya kollektiv müəllifliyi olmayan kitabların sərlövhələrinin ciddi əlifba sırası ilə", "Kitabların kitabxanaya daxilolma tarixlərinin xronoloji ardıcıllığı ilə", "Kitabların inventar nömrələrinin artma ardıcıllığı ilə", "Kitabların çap olunduğu nəşriyyatların adlarına görə"]'::jsonb, 'Müəlliflərin soyadlarının və ya kollektiv müəllifliyi olmayan kitabların sərlövhələrinin ciddi əlifba sırası ilə', 'Düzgün cavab: B) Müəlliflərin soyadlarının və ya kollektiv müəllifliyi olmayan kitabların sərlövh', '', 10, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8e209a0b-e8a2-46b6-bcee-d079b8d2ae6c', 'f590c982-0101-4649-a180-686198d53e4c', 'ka', 'ანბანურ კატალოგში რა თანმიმდევრობით სისტემატიზდება ბიბლიოგრაფიული ბარათები?', '["წიგნების ინვენტარული ნომრების ზრდადობის თანმიმდევრობით", "ავტორების გვარების ან უავტორო წიგნების სათაურების მკაცრი ანბანური რიგით, ასო-ასო", "იმ გამომცემლობების სახელწოდებათა ანბანური რიგით, სადაც წიგნები დაიბეჭდა", "მეცნიერების დარგების იერარქიული კლასიფიკაციის ხარისხისა და ინდექსის მიხედვით", "წიგნების შემოსვლის თარიღების ქრონოლოგიური თანმიმდევრობით"]'::jsonb, 'ავტორების გვარების ან უავტორო წიგნების სათაურების მკაცრი ანბანური რიგით, ასო-ასო', 'Düzgün cavab: B) ავტორების გვარების ან უავტორო წიგნების სათაურების მკაცრი ანბანური რიგით, ასო-ასო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b0bd745e-c94f-4479-8990-2162e2ecf3d5', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Sistemli kataloqun oxucular və kitabxanaçı üçün ən mühüm biblioqrafik təyinatı nədir?', 'multiple_choice', '["Fondun məzmununu elm sahələri üzrə iyerarxik əks etdirərək müəyyən mövzuya aid bütün ədəbiyyatı bir yerdə tapmağa imkan yaratmaq", "Oxucuların fonda vurduğu ziyanın məbləğini hesablamaq və rəsmiləşdirmək", "Yalnız müəllifin soyadına əsasən əlifba sırası ilə axtarışı təmin etmək", "Yalnız cari təqvim ilində çap olunmuş qəzet və jurnalları qeydiyyata almaq", "Kitabxana əməkdaşlarının aylıq iş vaxtının uçotunu aparmaq"]'::jsonb, 'Fondun məzmununu elm sahələri üzrə iyerarxik əks etdirərək müəyyən mövzuya aid bütün ədəbiyyatı bir yerdə tapmağa imkan yaratmaq', 'Düzgün cavab: A) Fondun məzmununu elm sahələri üzrə iyerarxik əks etdirərək müəyyən mövzuya aid b', '', 11, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3055a30b-3062-4bd8-9a29-e027f4b90e99', 'b0bd745e-c94f-4479-8990-2162e2ecf3d5', 'ka', 'რა არის სისტემური კატალოგის უმნიშვნელოვანესი ბიბლიოგრაფიული ფუნქცია მკითხველისა და ბიბლიოთეკარისთვის?', '["ფონდის შინაარსის, მეცნიერების ყველა დარგის უთკ-ის მიხედვით იერარქიული ასახვა, რაც შესაძლებელს ხდის კონკრეტულ თემასა და სამეცნიერო დარგთან დაკავშირებული მთელი ლიტერატურის ერთად მოძიებას", "ბიბლიოთეკის თანამშრომელთა ყოველთვიური სამუშაო დროის აღრიცხვა", "მკითხველთა მიერ ფონდისთვის მიყენებული ზიანის ოდენობის დათვლა და გაფორმება", "ინდივიდუალური წიგნის მოძიება მხოლოდ ავტორის გვარის მიხედვით", "მხოლოდ მიმდინარე წელს გამოცემული პერიოდული გაზეთებისა და ჟურნალების რეგისტრაცია"]'::jsonb, 'ფონდის შინაარსის, მეცნიერების ყველა დარგის უთკ-ის მიხედვით იერარქიული ასახვა, რაც შესაძლებელს ხდის კონკრეტულ თემასა და სამეცნიერო დარგთან დაკავშირებული მთელი ლიტერატურის ერთად მოძიებას', 'Düzgün cavab: A) ფონდის შინაარსის, მეცნიერების ყველა დარგის უთკ-ის მიხედვით იერარქიული ასახვა, რა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f0bc3163-e6d7-4a55-baec-89960d7a26ae', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Ümumi təhsil müəssisəsində dövlət tərəfindən təmin edilən dərsliklərin idarə olunmasında kitabxanaçının əsas vəzifəsi hansıdır?', 'multiple_choice', '["Çatışmayan fənn dərsliklərinin əvəzinə başqa fənn kitablarını məcburi vermək", "Dərslikləri yalnız əlaçı şagirdlərə paylayıb digərlərinə satın almağı tapşırmaq", "Dərsliklərin mətnindəki elmi səhvləri müstəqil redaktə edərək təkrar nəşr etmək", "Dərslik fondunu qəbul etmək, uçotunu aparmaq, tədris ili əvvəlində paylama aktı ilə paylamaq və tədris ili sonunda geri təhvil almaq", "Dərsliklərlə təminatı yalnız buraxılış sinifləri arasında məhdudlaşdırmaq"]'::jsonb, 'Dərslik fondunu qəbul etmək, uçotunu aparmaq, tədris ili əvvəlində paylama aktı ilə paylamaq və tədris ili sonunda geri təhvil almaq', 'Düzgün cavab: D) Dərslik fondunu qəbul etmək, uçotunu aparmaq, tədris ili əvvəlində paylama aktı', '', 12, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('303c538c-9c45-419b-aa21-6b25937b6478', 'f0bc3163-e6d7-4a55-baec-89960d7a26ae', 'ka', 'ზოგადსაგანმანათლებლო სკოლაში სახელმწიფოს მიერ გამოყოფილი უფასო სახელმძღვანელოების განაწილებისა და შეგროვების პროცესში რა ევალება ბიბლიოთეკარს?', '["სახელმძღვანელოების მხოლოდ აქტიურ მოსწავლეებზე განაწილება და სხვებისთვის შეძენის დავალება", "ნაკლული სახელმძღვანელოების ნაცვლად სხვა საგნობრივი წიგნების სავალდებულო წესით მიწოდება", "სახელმძღვანელოების ტექსტში არსებული საგნობრივი შეცდომების დამოუკიდებლად რედაქტირება და გამომცემლობაში გაგზავნა", "სახელმძღვანელოების ფონდის მიღება, ჯამურ და ინვენტარულ აღრიცხვაში გატარება, კლასების მიხედვით განაწილება, სასწავლო წლის დასაწყისში განაწილების აქტით გაცემა და წლის ბოლოს უკან ჩაბარება-შემოწმება", "სახელმძღვანელოებით უზრუნველყოფის მხოლოდ გამოსაშვები კლასებით შემოფარგვლა"]'::jsonb, 'სახელმძღვანელოების ფონდის მიღება, ჯამურ და ინვენტარულ აღრიცხვაში გატარება, კლასების მიხედვით განაწილება, სასწავლო წლის დასაწყისში განაწილების აქტით გაცემა და წლის ბოლოს უკან ჩაბარება-შემოწმება', 'Düzgün cavab: D) სახელმძღვანელოების ფონდის მიღება, ჯამურ და ინვენტარულ აღრიცხვაში გატარება, კლასე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b6c7e839-1f25-4ecf-8221-ac356716ea9f', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Məktəb kitabxanasında fiziki tamlığını itirmiş, cırılmış və ya məzmunca köhnəlmiş ədəbiyyatın fonddan silinməsi necə rəsmiləşdirilir?', 'multiple_choice', '["Kitabların inventar nömrəsinin üstündən xətt çəkilərək akt tərtib edilmədən atılması ilə", "Yalnız valideyn komitəsinin ümumi yığıncağının tövsiyə qərarı ilə", "Yaradılmış rəsmi komissiyanın baxışı əsasında tərtib və təsdiq olunan Silinmə Aktı ilə (inventar kitabında qeyd aparılmaqla)", "Yalnız kitabxanaçının fərdi qeydləri və şəxsi təşəbbüsü ilə", "Məktəbin təsərrüfat müdirinin verdiyi fərdi şifahi göstəriş əsasında"]'::jsonb, 'Yaradılmış rəsmi komissiyanın baxışı əsasında tərtib və təsdiq olunan Silinmə Aktı ilə (inventar kitabında qeyd aparılmaqla)', 'Düzgün cavab: C) Yaradılmış rəsmi komissiyanın baxışı əsasında tərtib və təsdiq olunan Silinmə Ak', '', 13, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ab805342-2728-453e-80ca-dbf6c959370a', 'b6c7e839-1f25-4ecf-8221-ac356716ea9f', 'ka', 'სასკოლო ბიბლიოთეკაში როგორ ფორმდება ფიზიკური მთლიანობადაკარგული, დაზიანებული ან შინაარსობრივად მოძველებული ლიტერატურის ფონდიდან ჩამოწერა?', '["სკოლის სამეურნეო ნაწილის გამგის ინდივიდუალური დავალების საფუძველზე", "წიგნების პირდაპირ ინვენტარული წიგნიდან გადახაზვით და აქტის შედგენის გარეშე გადაყრით", "სკოლის ხელმძღვანელობის მიერ შექმნილი კომისიის (ბიბლიოთეკარი, მოადგილე, მასწავლებელი) მიერ შედგენილი, ფონდის შემოწმების საფუძველზე დამტკიცებული ოფიციალური ჩამოწერის აქტით, ინვენტარულ წიგნში შესაბამისი აღნიშვნის გაკეთებით", "მხოლოდ მშობელთა კომიტეტის საერთო კრების სარეკომენდაციო გადაწყვეტილებით", "მხოლოდ ბიბლიოთეკარის პირადი ზეპირი შეხედულებითა და ყოველდღიური ჩანაწერებით"]'::jsonb, 'სკოლის ხელმძღვანელობის მიერ შექმნილი კომისიის (ბიბლიოთეკარი, მოადგილე, მასწავლებელი) მიერ შედგენილი, ფონდის შემოწმების საფუძველზე დამტკიცებული ოფიციალური ჩამოწერის აქტით, ინვენტარულ წიგნში შესაბამისი აღნიშვნის გაკეთებით', 'Düzgün cavab: C) სკოლის ხელმძღვანელობის მიერ შექმნილი კომისიის (ბიბლიოთეკარი, მოადგილე, მასწავლებ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0df754f4-3447-48bd-adfb-311f42c032dd', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Oxucu formulyarının (abunə kartının) kitabxana xidmətində əsas təyinatı nədir?', 'multiple_choice', '["Oxucuya verilmiş və geri alınmış nəşrlərin adlarını, inventar nömrələrini, tarixləri və oxucu imzasını əks etdirən fərdi uçot sənədi kimi", "Kitabxana binasının texniki vəziyyətini və yanğın parametrini qeyd etmək", "Müəssisənin illik təsərrüfat mallarının mədaxilini qeydə almaq", "Məktəbin Pedaqoji Şurasının qərarlarını protokollaşdırmaq və arxivləşdirmək", "Fənn müəllimlərinin həftəlik dərs cədvəlini və dərs yükünü əks etdirmək"]'::jsonb, 'Oxucuya verilmiş və geri alınmış nəşrlərin adlarını, inventar nömrələrini, tarixləri və oxucu imzasını əks etdirən fərdi uçot sənədi kimi', 'Düzgün cavab: A) Oxucuya verilmiş və geri alınmış nəşrlərin adlarını, inventar nömrələrini, tarix', '', 14, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b38fe643-b23d-4bd8-8f32-219982c50adb', '0df754f4-3447-48bd-adfb-311f42c032dd', 'ka', 'რა არის მკითხველის ფორმულარის (სააბონემენტო ბარათის) ძირითადი დანიშნულება საბიბლიოთეკო საქმისწარმოებაში?', '["ინდივიდუალური სააღრიცხვო დოკუმენტი, რომელშიც ფიქსირდება მკითხველზე გაცემული და მისგან დაბრუნებული გამოცემების სათაურები, ინვენტარული ნომრები, გაცემისა და დაბრუნების თარიღები და მკითხველის ხელმოწერა", "დაწესებულების წლიური სამეურნეო საქონლის შემოსავლის აღრიცხვა", "საგნის მასწავლებლების ყოველკვირეული საგაკვეთილო ცხრილისა და პედაგოგიური დატვირთვის ასახვა", "საბიბლიოთეკო შენობის ტექნიკური მდგომარეობისა და სახანძრო პარამეტრების აღნიშვნა", "სკოლის პედაგოგიური საბჭოს გადაწყვეტილებების ოქმებში ასახვა და დაარქივება"]'::jsonb, 'ინდივიდუალური სააღრიცხვო დოკუმენტი, რომელშიც ფიქსირდება მკითხველზე გაცემული და მისგან დაბრუნებული გამოცემების სათაურები, ინვენტარული ნომრები, გაცემისა და დაბრუნების თარიღები და მკითხველის ხელმოწერა', 'Düzgün cavab: A) ინდივიდუალური სააღრიცხვო დოკუმენტი, რომელშიც ფიქსირდება მკითხველზე გაცემული და მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b69f82e5-9828-4d21-831d-3065dae40c1e', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana fondunun dövri inventarizasiyasının (yoxlanılmasının) başlıca məqsədi nədir?', 'multiple_choice', '["Fonddakı faktiki nüsxələrin sayını uçot sənədləri (inventar və cəmi uçot kitabları) ilə tutuşdurub çatışmazlıq və itkiləri aşkar etmək", "Mövcud kataloq kartoçkalarını məhv edərək sistemi yenidən tərtib etmək", "Kitabların rəflərdəki rəng və cild uyğunluğunun vizual tərtibatını təmin etmək", "Oxu zalında kitabların qeydiyyatsız aparılmasına icazə vermək", "Yalnız yeni daxil olmuş dərsliklərin qiymət dərəcələrini artırmaq"]'::jsonb, 'Fonddakı faktiki nüsxələrin sayını uçot sənədləri (inventar və cəmi uçot kitabları) ilə tutuşdurub çatışmazlıq və itkiləri aşkar etmək', 'Düzgün cavab: A) Fonddakı faktiki nüsxələrin sayını uçot sənədləri (inventar və cəmi uçot kitabla', '', 15, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('fa4dc029-e3b3-4415-81ef-43715f8c64d2', 'b69f82e5-9828-4d21-831d-3065dae40c1e', 'ka', 'რა არის მთავარი მიზანი საბიბლიოთეკო ფონდის პერიოდული ინვენტარიზაციის ჩატარებისას?', '["ფონდში არსებული ფაქტობრივი ეგზემპლარების რაოდენობისა და განლაგების შედარება სააღრიცხვო დოკუმენტებთან (ინვენტარული წიგნები, ჯამური აღრიცხვის წიგნი), დანაკლისის, ზედმეტობისა და დანაკარგების გამოვლენა", "არსებული სააღრიცხვო ბარათების განადგურება და სისტემის ხელახლა შედგენა", "სამკითხველო დარბაზიდან წიგნების გატანის ნებართვის გაცემა რეგისტრაციის გარეშე", "მხოლოდ ახლად შემოსული სახელმძღვანელოების საფასურის გაზრდა", "თაროებზე წიგნების ფერისა და ყდის შესაბამისობის ვიზუალური გაფორმების უზრუნველყოფა"]'::jsonb, 'ფონდში არსებული ფაქტობრივი ეგზემპლარების რაოდენობისა და განლაგების შედარება სააღრიცხვო დოკუმენტებთან (ინვენტარული წიგნები, ჯამური აღრიცხვის წიგნი), დანაკლისის, ზედმეტობისა და დანაკარგების გამოვლენა', 'Düzgün cavab: A) ფონდში არსებული ფაქტობრივი ეგზემპლარების რაოდენობისა და განლაგების შედარება სააღ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b9a94afe-69ad-4a0f-99e2-6da225a56b25', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Məktəb kitabxanaçısının şagirdlərlə keçirdiyi “Kitabxana-biblioqrafiya dərsləri”nin başlıca tərbiyəvi məqsədi nədir?', 'multiple_choice', '["Şagirdlərdə mütaliə mədəniyyətini, ensiklopediya, lüğət, kataloq və biblioqrafik məlumat bazalarından müstəqil istifadə vərdişlərini aşılamaq", "Şagirdlərin intizam tənbehlərini və ailə vəziyyətlərini kollektiv müzakirə etmək", "Şagirdləri kitabxana otağının təmir-tikinti işlərinə cəlb etmək", "İmtahan test suallarının doğru cavablarını şagirdlərə əvvəlcədən bildirmək", "Fənn müəllimlərinin dərs yükünü azaltmaq üçün əvəzedici fənn dərsləri tədris etmək"]'::jsonb, 'Şagirdlərdə mütaliə mədəniyyətini, ensiklopediya, lüğət, kataloq və biblioqrafik məlumat bazalarından müstəqil istifadə vərdişlərini aşılamaq', 'Düzgün cavab: A) Şagirdlərdə mütaliə mədəniyyətini, ensiklopediya, lüğət, kataloq və biblioqrafik', '', 16, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cc7fa65a-eb32-4a26-98a4-6e96bb47d673', 'b9a94afe-69ad-4a0f-99e2-6da225a56b25', 'ka', 'რა არის სასკოლო ბიბლიოთეკარის მიერ მოსწავლეებთან ჩატარებული „საბიბლიოთეკო-ბიბლიოგრაფიული გაკვეთილების“ მთავარი სააღმზრდელო მიზანი?', '["მოსწავლეებში კითხვის კულტურის, წიგნით, ლექსიკონებით, ენციკლოპედიებით, ელექტრონული კატალოგებითა და ბიბლიოგრაფიული დამხმარე საშუალებებით დამოუკიდებლად და კულტურულად სარგებლობის უნარ-ჩვევების გამომუშავება", "საგნის მასწავლებელთა დატვირთვის შესამცირებლად შემცვლელი გაკვეთილების ჩატარება", "საგამოცდო კითხვების სწორი პასუხების მოსწავლეებისთვის წინასწარ შეტყობინება", "მოსწავლეთა დისციპლინური სახდელებისა და ოჯახური მდგომარეობის კოლექტიური განხილვა", "მოსწავლეთა ჩართვა ბიბლიოთეკის სარემონტო-სამშენებლო სამუშაოებში"]'::jsonb, 'მოსწავლეებში კითხვის კულტურის, წიგნით, ლექსიკონებით, ენციკლოპედიებით, ელექტრონული კატალოგებითა და ბიბლიოგრაფიული დამხმარე საშუალებებით დამოუკიდებლად და კულტურულად სარგებლობის უნარ-ჩვევების გამომუშავება', 'Düzgün cavab: A) მოსწავლეებში კითხვის კულტურის, წიგნით, ლექსიკონებით, ენციკლოპედიებით, ელექტრონულ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c6610ae2-27c6-4b53-891f-efcf38f7c7f2', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana fondunda olan nadir, dəyərli və tək nüsxəli ensiklopedik nəşrlərdən istifadə qaydası necədir?', 'multiple_choice', '["Şagirdlərə və müəllimlərə heç bir halda nümayiş etdirilmir və seyfdə gizlədilir", "Yalnız məktəb təsərrüfat müdirinin şifahi icazəsi ilə evə verilir", "Oxuculara evdə mütaliə etmək üçün 30 təqvim günü müddətinə verilir", "Yalnız oxu zalında kitabxanaçının nəzarəti altında istifadəyə verilir və evə aparılmasına icazə verilmir", "Oxucunun fərdi xahişi ilə qeydiyyatsız daimi istifadəyə hədiyyə edilir"]'::jsonb, 'Yalnız oxu zalında kitabxanaçının nəzarəti altında istifadəyə verilir və evə aparılmasına icazə verilmir', 'Düzgün cavab: D) Yalnız oxu zalında kitabxanaçının nəzarəti altında istifadəyə verilir və evə apa', '', 17, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ca02d5b0-cecd-4718-8d40-8359fb88b565', 'c6610ae2-27c6-4b53-891f-efcf38f7c7f2', 'ka', 'როგორია საბიბლიოთეკო ფონდში არსებული იშვიათი, ღირებული და ერთადერთ ეგზემპლარად არსებული ენციკლოპედიური და ლექსიკონური გამოცემებით სარგებლობის წესი?', '["მკითხველის პირადი თხოვნით დოკუმენტის გარეშე საჩუქრდება მუდმივ სარგებლობაში", "მკითხველებს სახლში წასაკითხად ეძლევათ 30 კალენდარული დღის ვადით", "მოსწავლეებსა და მასწავლებლებს არავითარ შემთხვევაში არ ეჩვენებათ და ინახება დახურულ სეიფში", "გაიცემა მხოლოდ ბიბლიოთეკის სამკითხველო დარბაზში, ბიბლიოთეკარის მეთვალყურეობით გამოსაყენებლად; სახლში წაღება და სრული კოპირება დაუშვებელია (დაცულია)", "სახლში გაიცემა 1 თვით მხოლოდ სკოლის სამეურნეო ნაწილის გამგის წერილობითი ნებართვით"]'::jsonb, 'გაიცემა მხოლოდ ბიბლიოთეკის სამკითხველო დარბაზში, ბიბლიოთეკარის მეთვალყურეობით გამოსაყენებლად; სახლში წაღება და სრული კოპირება დაუშვებელია (დაცულია)', 'Düzgün cavab: D) გაიცემა მხოლოდ ბიბლიოთეკის სამკითხველო დარბაზში, ბიბლიოთეკარის მეთვალყურეობით გა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e7e892bb-e55d-48fb-8c00-4fd05941d272', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana fondunun fiziki mühafizəsi məqsədilə təşkil edilən “Sanitar günü” zamanı hansı əsas tədbirlər icra olunur?', 'multiple_choice', '["Köhnə kitabların rəsmi akt olmadan tullantı kimi atılması", "Yalnız kitabxana işçilərinin fərdi tibbi müayinədən keçməsi", "Fondun və rəflərin tozdan təmizlənməsi, rütubət-havalandırma rejiminə nəzarət, gigiyenik tədbirlər və zədələnmiş kitabların təmiri", "Pedaqoji kollektiv üçün qapalı inzibati iclas keçirilməsi", "Kitabxananın qapıları bağlanaraq işçilərin iş saatlarının qısaldılması"]'::jsonb, 'Fondun və rəflərin tozdan təmizlənməsi, rütubət-havalandırma rejiminə nəzarət, gigiyenik tədbirlər və zədələnmiş kitabların təmiri', 'Düzgün cavab: C) Fondun və rəflərin tozdan təmizlənməsi, rütubət-havalandırma rejiminə nəzarət, g', '', 18, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('07007a7b-3c09-487c-8490-f3b35f518d63', 'e7e892bb-e55d-48fb-8c00-4fd05941d272', 'ka', 'საბიბლიოთეკო ფონდის დაცვის მიზნით ორგანიზებული „სანიტარიული დღის“ განმავლობაში რა ღონისძიებები ხორციელდება?', '["პედაგოგიური კოლექტივისთვის ტარდება დახურული ადმინისტრაციული კრება", "ბიბლიოთეკის კარები იკეტება და თანამშრომლებს სამუშაო საათები უმოკლდებათ", "ფონდისა და თაროების მტვრისგან გაწმენდა, წიგნების ჰიგიენური მოწესრიგება, ტენიანობისა და ვენტილაციის რეჟიმის კონტროლი, პროფილაქტიკური დეზინფექცია, დაზიანებული წიგნების შეკეთება", "მხოლოდ საბიბლიოთეკო პერსონალის ინდივიდუალური სამედიცინო შემოწმების უზრუნველყოფა", "მხოლოდ ახალი სახელმძღვანელოების ფასიანი გაყიდვა და ბაზრობის მოწყობა"]'::jsonb, 'ფონდისა და თაროების მტვრისგან გაწმენდა, წიგნების ჰიგიენური მოწესრიგება, ტენიანობისა და ვენტილაციის რეჟიმის კონტროლი, პროფილაქტიკური დეზინფექცია, დაზიანებული წიგნების შეკეთება', 'Düzgün cavab: C) ფონდისა და თაროების მტვრისგან გაწმენდა, წიგნების ჰიგიენური მოწესრიგება, ტენიანობ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0b23bb8e-a87b-41bc-aa98-bcc6ed856ed3', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana fondunun uzunmüddətli qorunması üçün otaqda tələb olunan standart temperatur və nisbi rütubət norması hansıdır?', 'multiple_choice', '["Temperatur 5–10°C, nisbi rütubət 80–90%", "Temperatur 30–35°C, nisbi rütubət 70–80%", "Temperatur 0–5°C, nisbi rütubət 10–20%", "Temperatur 28–32°C, nisbi rütubət 20–30%", "Temperatur 16–20°C (optimal 18±2°C), nisbi rütubət 50–60% (optimal 55±5%)"]'::jsonb, 'Temperatur 16–20°C (optimal 18±2°C), nisbi rütubət 50–60% (optimal 55±5%)', 'Düzgün cavab: E) Temperatur 16–20°C (optimal 18±2°C), nisbi rütubət 50–60% (optimal 55±5%)', '', 19, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e44575ac-7153-4166-97f2-cff2b6391738', '0b23bb8e-a87b-41bc-aa98-bcc6ed856ed3', 'ka', 'საბიბლიოთეკო ფონდის ხანგრძლივი შენახვისთვის რა წარმოადგენს ოთახში ჰაერის ტემპერატურისა და ფარდობითი ტენიანობის სტანდარტულ ნორმას?', '["ტემპერატურა 0–5°C, ფარდობითი ტენიანობა 10–20% - სამაცივრო რეჟიმი", "ტემპერატურა 30–35°C, ფარდობითი ტენიანობა 70–80% - ტროპიკული რეჟიმი", "ტემპერატურა 5–10°C, ფარდობითი ტენიანობა 80–90% - ნესტიანი არქივი", "ტემპერატურა 28–32°C, ფარდობითი ტენიანობა 20–30% - მშრალი სიცხე", "ტემპერატურა 16–20°C (ოპტიმალური 18±2°C), ფარდობითი ტენიანობა 50–60% (ოპტიმალური 55±5%), ჰაერის ცირკულაციით"]'::jsonb, 'ტემპერატურა 16–20°C (ოპტიმალური 18±2°C), ფარდობითი ტენიანობა 50–60% (ოპტიმალური 55±5%), ჰაერის ცირკულაციით', 'Düzgün cavab: E) ტემპერატურა 16–20°C (ოპტიმალური 18±2°C), ფარდობითი ტენიანობა 50–60% (ოპტიმალური', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f82eb3a0-1cee-4f5e-8188-1415d8c66be3', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana fondunun mühafizəsi zamanı kitabların birbaşa günəş şüalarından qorunmasının başlıca elmi səbəbi nədir?', 'multiple_choice', '["Kitabxana otağının daimi tam qaranlıq rejimdə qalmasını təmin etmək üçün", "Günəş şüaları kağız liflərini qurudaraq kövrəkləşdirir, saraldır, mətni və rəngləri soldurur, cildin dağılmasına səbəb olur", "Kitab rəflərinin metal konstruksiyalarının paslanmasını ləngitmək üçün", "Kitabların poliqrafik cildinin parlaqlığını süni şəkildə artırmaq üçün", "Kitab vərəqlərinin çəkisinin təbii buxarlanma ilə azalmasının qarşısını almaq üçün"]'::jsonb, 'Günəş şüaları kağız liflərini qurudaraq kövrəkləşdirir, saraldır, mətni və rəngləri soldurur, cildin dağılmasına səbəb olur', 'Düzgün cavab: B) Günəş şüaları kağız liflərini qurudaraq kövrəkləşdirir, saraldır, mətni və rəngl', '', 20, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b90d7b25-964b-475d-93b0-dd3235153a01', 'f82eb3a0-1cee-4f5e-8188-1415d8c66be3', 'ka', 'საბიბლიოთეკო ფონდის ფიზიკური დაცვისას რა არის წიგნების მზის პირდაპირი სხივებისგან დაცვის მთავარი სამეცნიერო მიზეზი?', '["წიგნის ფურცლების წონის ბუნებრივი აორთქლებით შემცირების თავიდან ასაცილებლად", "მზის პირდაპირი სხივები აშრობს და მყიფეს ხდის ქაღალდის ბოჭკოებს, იწვევს მის გაყვითლებას, ტექსტისა და საღებავების გახუნებას, ყდისა და წებოს დაშლას", "წიგნის თაროების ლითონისა და ხის კონსტრუქციების კოროზიის თავიდან ასაცილებლად", "ბიბლიოთეკის ოთახში მუდმივი სიბნელის რეჟიმის უზრუნველსაყოფად", "წიგნების პოლიგრაფიული ყდის სიპრიალის ხელოვნურად გასაზრდელად"]'::jsonb, 'მზის პირდაპირი სხივები აშრობს და მყიფეს ხდის ქაღალდის ბოჭკოებს, იწვევს მის გაყვითლებას, ტექსტისა და საღებავების გახუნებას, ყდისა და წებოს დაშლას', 'Düzgün cavab: B) მზის პირდაპირი სხივები აშრობს და მყიფეს ხდის ქაღალდის ბოჭკოებს, იწვევს მის გაყვი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b9f8cf89-d129-4ea4-9c3c-4123f294a96a', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Oxucu tərəfindən itirilmiş və ya yararsız hala salınmış kitabxana kitabının əvəzlənməsi qaydası necə tənzimlənir?', 'multiple_choice', '["İtirilmiş kitabın əvəzinə mütləq dəftərxana kağızı və ya qələm təhvil verilməlidir", "Oxucuya töhmət verilir və kitabxana xidmətləri bütün məktəb üzrə dayandırılır", "Oxucu dərhal məktəbdən xaric edilərək barəsində cərimə protokolu yazılır", "Oxucu itirilmiş kitabın eynisini və ya kitabxana tərəfindən məzmun və dəyərcə bərabərdəyərli hesab edilən digər zəruri nəşri (aktla) təqdim etməlidir", "Oxucu heç bir məsuliyyət daşımır və kitab akt tərtib edilmədən dərhal silinir"]'::jsonb, 'Oxucu itirilmiş kitabın eynisini və ya kitabxana tərəfindən məzmun və dəyərcə bərabərdəyərli hesab edilən digər zəruri nəşri (aktla) təqdim etməlidir', 'Düzgün cavab: D) Oxucu itirilmiş kitabın eynisini və ya kitabxana tərəfindən məzmun və dəyərcə bə', '', 21, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('657b1cb9-799f-4e00-ac70-091fb5e86fe5', 'b9f8cf89-d129-4ea4-9c3c-4123f294a96a', 'ka', 'როგორ რეგულირდება მკითხველის მიერ დაკარგული ან სრულად დაზიანებული საბიბლიოთეკო წიგნის ჩანაცვლების წესი?', '["დაკარგული წიგნის სანაცვლოდ აუცილებლად უნდა ჩაბარდეს საკანცელარიო ქაღალდი ან კალმები", "მკითხველი არ ატარებს მატერიალურ პასუხისმგებლობას და წიგნი ჩამოიწერება აქტის შედგენის გარეშე", "მკითხველი დაუყოვნებლივ ირიცხება სკოლიდან და მის წინააღმდეგ დგება ოქმი", "მკითხველმა უნდა წარმოადგინოს დაკარგული წიგნის იდენტური ან ბიბლიოთეკის მიერ შინაარსითა და ღირებულებით თანაბარფასოვნად მიჩნეული, ფონდისთვის საჭირო სხვა გამოცემა (აქტით)", "მკითხველს ეძლევა დისციპლინური საყვედური და ბიბლიოთეკა წყვეტს მუშაობას"]'::jsonb, 'მკითხველმა უნდა წარმოადგინოს დაკარგული წიგნის იდენტური ან ბიბლიოთეკის მიერ შინაარსითა და ღირებულებით თანაბარფასოვნად მიჩნეული, ფონდისთვის საჭირო სხვა გამოცემა (აქტით)', 'Düzgün cavab: D) მკითხველმა უნდა წარმოადგინოს დაკარგული წიგნის იდენტური ან ბიბლიოთეკის მიერ შინაა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('72a32b07-fa20-4ab0-acbd-60aeb637b5ce', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', '“Kitabxana işi haqqında” AR Qanununa əsasən, “Milli mətbuat nüsxəsi” (məcburi nüsxə) anlayışı nəyi ifadə edir?', 'multiple_choice', '["Kitabxanaçının şəxsi istifadəsi üçün nəşriyyat tərəfindən ayrılan pulsuz nüsxələri", "Yalnız xarici ölkələrdə çap olunan Azərbaycan dilli dərslikləri", "Ölkə ərazisində dərc olunan bütün növ çap məhsullarından qanunla müəyyən edilmiş sayda depozitar kitabxanalara göndərilən pulsuz nüsxələri", "Qüsurlu çap olunmuş və satış şəbəkələrinə buraxılmayan qəzet və jurnal nüsxələrini", "Yalnız ümumtəhsil məktəbliləri üçün pulsuz paylanan dəftərxana ləvazimatlarını"]'::jsonb, 'Ölkə ərazisində dərc olunan bütün növ çap məhsullarından qanunla müəyyən edilmiş sayda depozitar kitabxanalara göndərilən pulsuz nüsxələri', 'Düzgün cavab: C) Ölkə ərazisində dərc olunan bütün növ çap məhsullarından qanunla müəyyən edilmiş', '', 22, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9815080a-255a-40bc-b6bb-5d6bc5ababab', '72a32b07-fa20-4ab0-acbd-60aeb637b5ce', 'ka', 'კანონის „საბიბლიოთეკო საქმის შესახებ“ მე-16 მუხლის თანახმად, რას გამოხატავს ცნება „ეროვნული ბეჭდური ეგზემპლარი“ (სავალდებულო ეგზემპლარი)?', '["ბიბლიოთეკარის პირადი სარგებლობისთვის გამომცემლობის მიერ გამოყოფილ უფასო ეგზემპლარებს", "მხოლოდ უცხო ქვეყნებში გამოცემულ სახელმძღვანელოებს", "ქვეყნის ტერიტორიაზე გამოცემული ყველა სახის ბეჭდური პროდუქციიდან (წიგნი, გაზეთი, ჟურნალი) კანონით დადგენილი ოდენობითა და ვადებში დეპოზიტარულ ბიბლიოთეკებში გაგზავნილ სავალდებულო უფასო ეგზემპლარებს", "დეფექტურად დაბეჭდილ და სავაჭრო ქსელში გაუსვლელ გაზეთებისა და ჟურნალების ეგზემპლარებს", "მხოლოდ ზოგადსაგანმანათლებლო სკოლის მოსწავლეებისთვის უფასოდ დასარიგებელ სასწავლო ნივთებს"]'::jsonb, 'ქვეყნის ტერიტორიაზე გამოცემული ყველა სახის ბეჭდური პროდუქციიდან (წიგნი, გაზეთი, ჟურნალი) კანონით დადგენილი ოდენობითა და ვადებში დეპოზიტარულ ბიბლიოთეკებში გაგზავნილ სავალდებულო უფასო ეგზემპლარებს', 'Düzgün cavab: C) ქვეყნის ტერიტორიაზე გამოცემული ყველა სახის ბეჭდური პროდუქციიდან (წიგნი, გაზეთი,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fc44fb9d-8a0b-4602-be3c-321e63547de4', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana fondunun komplektləşdirilməsi mənbələrinə hansı qanunsuz variant **AİD DEYİLDİR**?', 'multiple_choice', '["Kitabxanalararası abunə və rəsmi kitab mübadiləsi sistemləri", "Qanuni kitab ticarəti şəbəkələrindən və nəşriyyatlardan satınalmalar", "Dövlət orqanları tərəfindən mərkəzləşdirilmiş təminat və satınalmalar", "Müəlliflər və ya təşkilatlar tərəfindən fonda rəsmi hədiyyə edilən nəşrlər", "Mənşəyi məlum olmayan, sənədsiz və qanunsuz yollarla əldə edilmiş, möhürsüz və uçotsuz nəşrlər"]'::jsonb, 'Mənşəyi məlum olmayan, sənədsiz və qanunsuz yollarla əldə edilmiş, möhürsüz və uçotsuz nəşrlər', 'Düzgün cavab: E) Mənşəyi məlum olmayan, sənədsiz və qanunsuz yollarla əldə edilmiş, möhürsüz və u', '', 23, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a8a0806e-79f9-488e-bb8a-981b21ceb2d1', 'fc44fb9d-8a0b-4602-be3c-321e63547de4', 'ka', 'რომელი უკანონო ვარიანტი არ განეკუთვნება საბიბლიოთეკო ფონდის დაკომპლექტების კანონიერ წყაროებს?', '["ბიბლიოთეკათშორისი აბონემენტი და წიგნის საერთაშორისო გაცვლის სისტემები (MBA)", "სახელმწიფო ორგანოების მიერ ცენტრალიზებული მომარაგება და შესყიდვები", "ავტორების ან საზოგადოებრივი ორგანიზაციების მიერ ფონდისთვის ნაჩუქარი გამოცემები (შეწირულობა)", "კანონიერი წიგნით ვაჭრობის ქსელებიდან და გამომცემლობებიდან ოფიციალური შესყიდვები", "უცნობი წარმოშობის, უსაბუთო, უკანონო გზით (მოპარული, მეკობრული) მოპოვებული, უბეჭდო და აღურიცხავი გამოცემები"]'::jsonb, 'უცნობი წარმოშობის, უსაბუთო, უკანონო გზით (მოპარული, მეკობრული) მოპოვებული, უბეჭდო და აღურიცხავი გამოცემები', 'Düzgün cavab: E) უცნობი წარმოშობის, უსაბუთო, უკანონო გზით (მოპარული, მეკობრული) მოპოვებული, უბეჭდ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f8dad551-6c00-42fb-bb8f-47c5e21d26f0', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana işçisinin peşə etikası qaydalarına əsasən hansı davranış kobud pozuntu sayılır?', 'multiple_choice', '["Öz peşəkar bilik və biblioqrafik səriştəsini mütəmadi artırmaq", "Fondun mühafizəsi üçün vaxtında zəruri təhlükəsizlik tədbirləri görmək", "Bütün oxuculara nəzakətli, obyektiv və qərəzsiz xidmət göstərmək", "Oxucunun fərdi məlumatlarının və mütaliə maraqlarının məxfiliyini qorumaq", "Oxucular arasında sosial mənşəyinə, cinsinə, dilinə görə ayrı-seçkiliyə yol vermək və fərdi məlumatlarını yaymaq"]'::jsonb, 'Oxucular arasında sosial mənşəyinə, cinsinə, dilinə görə ayrı-seçkiliyə yol vermək və fərdi məlumatlarını yaymaq', 'Düzgün cavab: E) Oxucular arasında sosial mənşəyinə, cinsinə, dilinə görə ayrı-seçkiliyə yol verm', '', 24, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('db081598-a6b3-4292-8170-604e97d4a6e1', 'f8dad551-6c00-42fb-bb8f-47c5e21d26f0', 'ka', 'საბიბლიოთეკო თანამშრომლის პროფესიული ეთიკის წესების თანახმად, რომელი ქცევა ითვლება უხეშ დარღვევად?', '["ყველა მკითხველისთვის თავაზიანი, ობიექტური და მიუკერძოებელი მომსახურების გაწევა", "საკუთარი პროფესიული ცოდნისა და ბიბლიოგრაფიული კომპეტენციის მუდმივი ამაღლება", "მკითხველის პერსონალური მონაცემებისა და კითხვის ინტერესების კონფიდენციალურობის დაცვა", "ფონდის შენარჩუნებისთვის უსაფრთხოების ზომების დროულად მიღება", "მკითხველთა შორის სოციალური წარმოშობის, სქესის, ენის, რელიგიის, პოლიტიკური შეხედულებების მიხედვით დისკრიმინაციის დაშვება, პერსონალური მონაცემების გავრცელება და ტენდენციური მომსახურება"]'::jsonb, 'მკითხველთა შორის სოციალური წარმოშობის, სქესის, ენის, რელიგიის, პოლიტიკური შეხედულებების მიხედვით დისკრიმინაციის დაშვება, პერსონალური მონაცემების გავრცელება და ტენდენციური მომსახურება', 'Düzgün cavab: E) მკითხველთა შორის სოციალური წარმოშობის, სქესის, ენის, რელიგიის, პოლიტიკური შეხედუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('192f4805-001c-4a4b-ab59-1392fdca147f', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana otağında yanğın təhlükəsizliyinin təmin olunması üzrə hansı fikir **YANLIŞDIR**?', 'multiple_choice', '["Yanğın xəbərdaredici siqnalizasiya sisteminin işləkliyi mütəmadi yoxlanılmalıdır", "Elektrik naqilləri saz saxlanmalı, qeyri-standart qızdırıcılardan istifadə edilməməlidir", "Otaqda təxliyə planı görünən və işıqlı yerdən asılmalıdır", "Kitabxananın ehtiyat çıxış yollarını və qapılarını kitab bağlamaları və arxiv qutuları ilə bağlamaq", "Kitabxana ilkin yanğınsöndürmə vasitələri (odsöndürənlər) ilə təmin olunmalıdır"]'::jsonb, 'Kitabxananın ehtiyat çıxış yollarını və qapılarını kitab bağlamaları və arxiv qutuları ilə bağlamaq', 'Düzgün cavab: D) Kitabxananın ehtiyat çıxış yollarını və qapılarını kitab bağlamaları və arxiv qu', '', 25, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c8f9952f-6c1e-46d3-9cb6-1d8da67228b5', '192f4805-001c-4a4b-ab59-1392fdca147f', 'ka', 'საბიბლიოთეკო ოთახში სახანძრო უსაფრთხოების უზრუნველყოფის კუთხით რომელი მოთხოვნაა მცდარი?', '["ხანძარსაწინააღმდეგო სიგნალიზაციის სისტემის გამართულობა რეგულარულად უნდა შემოწმდეს", "ოთახში საევაკუაციო გეგმა თვალსაჩინო და განათებულ ადგილზე უნდა იყოს გამოკრული", "ელექტროგაყვანილობა უნდა იყოს გამართული, არასტანდარტული გამათბობლების გამოყენება დაუშვებელია", "ბიბლიოთეკის სათადარიგო გასასვლელი გზები და კარები ჩახერგილი უნდა იყოს წიგნების შეკვრებით, ზედმეტი ავეჯითა და საარქივო ყუთებით", "ბიბლიოთეკა უზრუნველყოფილი უნდა იყოს პირველადი ხანძარსაწინააღმდეგო საშუალებებით (ცეცხლსაქრობებით)"]'::jsonb, 'ბიბლიოთეკის სათადარიგო გასასვლელი გზები და კარები ჩახერგილი უნდა იყოს წიგნების შეკვრებით, ზედმეტი ავეჯითა და საარქივო ყუთებით', 'Düzgün cavab: D) ბიბლიოთეკის სათადარიგო გასასვლელი გზები და კარები ჩახერგილი უნდა იყოს წიგნების შ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8d250747-e141-4313-bac6-d306d1b28d17', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana fondunun bioloji zərərvericilərdən (həşərat, kif göbələyi) mühafizəsi üçün hansı tədbir ən vacibdir?', 'multiple_choice', '["Kitabları birbaşa nəmişlik olan döşəmə üzərinə yığaraq saxlamaq", "Otaqda havanın nisbi rütubətini süni şəkildə 90%-ə qədər artırmaq", "Kitabların arasına kimyəvi nəmləndirici mayelər püskürtmək", "Müntəzəm ventilyasiya, optimal temperatur-rütubət rejiminin qorunması, rəflərin tozsuzlaşdırılması və profilaktik dezinfeksiya", "Otağın qapı və pəncərələrini havalandırmadan aylarla qapalı saxlamaq"]'::jsonb, 'Müntəzəm ventilyasiya, optimal temperatur-rütubət rejiminin qorunması, rəflərin tozsuzlaşdırılması və profilaktik dezinfeksiya', 'Düzgün cavab: D) Müntəzəm ventilyasiya, optimal temperatur-rütubət rejiminin qorunması, rəflərin', '', 26, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bde3fd93-6afd-481e-9023-a7a541d8b9cf', '8d250747-e141-4313-bac6-d306d1b28d17', 'ka', 'საბიბლიოთეკო ფონდის ბიოლოგიური მავნებლებისგან დასაცავად რომელი ღონისძიებაა აუცილებელი?', '["წიგნების პირდაპირ ნესტიან იატაკზე დაწყობა და შენახვა", "ოთახში ჰაერის ფარდობითი ტენიანობის ხელოვნურად გაზრდა 90%-მდე", "წიგნებს შორის ქიმიური დამატენიანებელი ხსნარების შესხურება", "ოთახის რეგულარული ვენტილაცია, ოპტიმალური ტემპერატურულ-ტენიანობითი რეჟიმის დაცვა, თაროების მტვრისგან გაწმენდა და საჭიროების შემთხვევაში პროფილაქტიკური დეზინფექციისა და დეზინსექციის ჩატარება", "ოთახის კარებისა და ფანჯრების განიავების გარეშე მუდმივად დაკეტილ მდგომარეობაში შენარჩუნება"]'::jsonb, 'ოთახის რეგულარული ვენტილაცია, ოპტიმალური ტემპერატურულ-ტენიანობითი რეჟიმის დაცვა, თაროების მტვრისგან გაწმენდა და საჭიროების შემთხვევაში პროფილაქტიკური დეზინფექციისა და დეზინსექციის ჩატარება', 'Düzgün cavab: D) ოთახის რეგულარული ვენტილაცია, ოპტიმალური ტემპერატურულ-ტენიანობითი რეჟიმის დაცვა,', NOW(), NOW());
