INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('241c24cf-6947-494d-8a5d-71757c9fb903', '24581e3c-9bea-4211-b460-21b1ac900202', 'ka', 'სასკოლო ბიბლიოთეკის ფონდის სტრუქტურაში რომელი გამოცემები შედის „პერიოდული გამოცემების ფონდში“?', '["გარკვეული პერიოდულობით, რეგულარულად გამომავალი გაზეთები, ჟურნალები, ბიულეტენები, კრებულები და გაგრძელებადი გამოცემები", "მრავალტომიანი ენციკლოპედიური ლექსიკონები და გეოგრაფიული რუკების კრებული", "საგნობრივი სახელმძღვანელოები და სასწავლო-მეთოდიკური სახელმძღვანელოები მასწავლებლებისთვის", "მოსწავლეთა გამოსაშვები გამოცდის თხზულებების კრებული", "მასწავლებელთა ინდივიდუალური წლიური კალენდარული გეგმები და საგნობრივი ჟურნალები"]'::jsonb, 'გარკვეული პერიოდულობით, რეგულარულად გამომავალი გაზეთები, ჟურნალები, ბიულეტენები, კრებულები და გაგრძელებადი გამოცემები', 'Düzgün cavab: A) გარკვეული პერიოდულობით, რეგულარულად გამომავალი გაზეთები, ჟურნალები, ბიულეტენები,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4ce467b6-280c-4a53-909d-60076e7a9dc1', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana kataloq kartoçkasının sol yuxarı küncündə qeyd olunan “Yerləşmə şifri” nəyi ifadə edir?', 'multiple_choice', '["Kitabxana əməkdaşının fərdi kadr identifikasiya nömrəsini", "Kitabın ticarət şəbəkəsindəki ilkin pərakəndə satış qiymətini", "Təhsil müəssisəsinin dövlət statistik reyestr kodunu", "Təsnifat indeksindən və müəllif nişanından ibarət olub, kitabın fonddakı, rəfdəki dəqiq yerini göstərən şərti işarəni", "Kitabın indiyədək neçə oxucu tərəfindən oxunduğunu göstərən sayğacı"]'::jsonb, 'Təsnifat indeksindən və müəllif nişanından ibarət olub, kitabın fonddakı, rəfdəki dəqiq yerini göstərən şərti işarəni', 'Düzgün cavab: D) Təsnifat indeksindən və müəllif nişanından ibarət olub, kitabın fonddakı, rəfdək', '', 28, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e6608817-e49b-4cfa-b0ef-5a246ba60655', '4ce467b6-280c-4a53-909d-60076e7a9dc1', 'ka', 'საბიბლიოთეკო სააღრიცხვო ბარათის ზედა მარცხენა კუთხეში მითითებული „განთავსების შიფრი“ (Call number) რას აღნიშნავს?', '["ბიბლიოთეკის თანამშრომლის საკადრო საიდენტიფიკაციო ნომერს", "სავაჭრო ქსელში წიგნის პირვანდელ საცალო ფასს", "მრიცხველს, რომელიც აჩვენებს, თუ რამდენმა მკითხველმა წაიკითხა წიგნი აქამდე", "პირობით ალფაციფრულ აღნიშვნას, რომელიც შედგება წიგნის კლასიფიკაციის ინდექსისა (უთკ/BBK) და საავტორო ნიშნისგან (ხავკინა) და უთითებს მის ზუსტ ადგილს ფონდში, თაროზე", "საგანმანათლებლო დაწესებულების სახელმწიფო სტატისტიკურ სარეგისტრაციო კოდს"]'::jsonb, 'პირობით ალფაციფრულ აღნიშვნას, რომელიც შედგება წიგნის კლასიფიკაციის ინდექსისა (უთკ/BBK) და საავტორო ნიშნისგან (ხავკინა) და უთითებს მის ზუსტ ადგილს ფონდში, თაროზე', 'Düzgün cavab: D) პირობით ალფაციფრულ აღნიშვნას, რომელიც შედგება წიგნის კლასიფიკაციის ინდექსისა (უთ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('da9b881b-ecda-4750-8baf-dec75e8049d3', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Kitabxana fondunun illik fəaliyyəti barədə Pedaqoji Şuraya təqdim edilən rəsmi hesabatda hansı əsas göstərici əks olunmalıdır?', 'multiple_choice', '["Məktəbin kommunal elektrik və su sayğaclarının aylıq göstəriciləri", "Pedaqoji heyətin fərdi dərs cədvəli və fənn kurikulumları", "Fondun ümumi həcmi, daxilolmalar və silinmələr, dərsliklə təminat faizi, oxucu sayı, kitab verilişi və mütaliə tədbirləri göstəriciləri", "Sinif otaqlarındakı parta və yazı lövhələrinin ümumi sayı", "Yalnız kitabxanaçının işə gəlmə və getmə saatları cədvəli"]'::jsonb, 'Fondun ümumi həcmi, daxilolmalar və silinmələr, dərsliklə təminat faizi, oxucu sayı, kitab verilişi və mütaliə tədbirləri göstəriciləri', 'Düzgün cavab: C) Fondun ümumi həcmi, daxilolmalar və silinmələr, dərsliklə təminat faizi, oxucu s', '', 29, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d47c0864-eab5-4b9f-affa-778185dea21e', 'da9b881b-ecda-4750-8baf-dec75e8049d3', 'ka', 'საბიბლიოთეკო ფონდის წლიური საქმიანობის შესახებ პედაგოგიური საბჭოსთვის წარდგენილ ოფიციალურ ანგარიშში რომელი მაჩვენებელი უნდა აისახოს?', '["საკლასო ოთახებში მერხებისა და სასკოლო დაფების საერთო რაოდენობა", "მხოლოდ ბიბლიოთეკარის სამსახურში გამოცხადებისა და წასვლის საათების ცხრილი", "ფონდის საერთო მოცულობა, წლის განმავლობაში შემოსულობები და ჩამოწერები, სახელმძღვანელოებით უზრუნველყოფის პროცენტი, მკითხველთა რაოდენობა, წიგნების გაცემა, მიმართვიანობის დინამიკა და ღონისძიებების სტატისტიკურ-ანალიტიკური მაჩვენებლები", "პედაგოგიური პერსონალის ინდივიდუალური საგაკვეთილო ცხრილი და საგნობრივი კურიკულუმები", "მხოლოდ სკოლის კომუნალური ელექტროენერგიისა და წყლის მრიცხველების ყოველთვიური მაჩვენებლები"]'::jsonb, 'ფონდის საერთო მოცულობა, წლის განმავლობაში შემოსულობები და ჩამოწერები, სახელმძღვანელოებით უზრუნველყოფის პროცენტი, მკითხველთა რაოდენობა, წიგნების გაცემა, მიმართვიანობის დინამიკა და ღონისძიებების სტატისტიკურ-ანალიტიკური მაჩვენებლები', 'Düzgün cavab: C) ფონდის საერთო მოცულობა, წლის განმავლობაში შემოსულობები და ჩამოწერები, სახელმძღვა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e854a8f1-bd77-4d39-828a-caff093e026f', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Təhsil müəssisəsinin kitabxanasında ilk tibbi yardım qutusunun saxlanması hansı zərurətdən irəli gəlir?', 'multiple_choice', '["Kitabxana fondunun dərslik və bədii ədəbiyyat üzrə illik qeydiyyatını aparmaq üçün", "Oxucuların mütaliə zamanı görmə qabiliyyətini yoxlayan optik cihazların saxlanması üçün", "Əməyin mühafizəsi qaydalarına əsasən qəfil xəsarət, kəsik, yıxılma və ya qəza zamanı ilkin tibbi yardımın təxirəsalınmaz göstərilməsi üçün", "Kitabxana oxu zalında şagirdlərə profilaktik tibbi peyvəndlərin vurulmasını təşkil etmək üçün", "Təhsilalanların fənlər üzrə summativ qiymətləndirmə protokollarını mühafizə etmək üçün"]'::jsonb, 'Əməyin mühafizəsi qaydalarına əsasən qəfil xəsarət, kəsik, yıxılma və ya qəza zamanı ilkin tibbi yardımın təxirəsalınmaz göstərilməsi üçün', 'Düzgün cavab: C) Əməyin mühafizəsi qaydalarına əsasən qəfil xəsarət, kəsik, yıxılma və ya qəza za', '', 30, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('db2ffe15-ee3b-4681-8663-983b81b7b130', 'e854a8f1-bd77-4d39-828a-caff093e026f', 'ka', 'საგანმანათლებლო დაწესებულების ბიბლიოთეკაში პირველადი სამედიცინო დახმარების აფთიაქის ქონა რა აუცილებლობიდან გამომდინარეობს?', '["სახელმძღვანელოებისა და მხატვრული ლიტერატურის მიხედვით საბიბლიოთეკო ფონდის წლიური აღრიცხვის საწარმოებლად", "სამკითხველო დარბაზში მოსწავლეთა პროფილაქტიკური სამედიცინო აცრების ორგანიზებისთვის", "შრომის დაცვისა და უსაფრთხოების ტექნიკის წესების შესაბამისად, უეცარი ტრავმის, ჭრილობის, დაცემის ან უბედური შემთხვევის დროს პირველადი სამედიცინო დახმარების აღმოსაჩენად და სანიტარიულ-ჰიგიენური უსაფრთხოებისთვის", "მოსწავლეთა საგნობრივი შემაჯამებელი შეფასების ოქმების შესანახად", "ოპტიკური ხელსაწყოების შესანახად, რომლებიც კითხვისას მკითხველთა მხედველობას ამოწმებს"]'::jsonb, 'შრომის დაცვისა და უსაფრთხოების ტექნიკის წესების შესაბამისად, უეცარი ტრავმის, ჭრილობის, დაცემის ან უბედური შემთხვევის დროს პირველადი სამედიცინო დახმარების აღმოსაჩენად და სანიტარიულ-ჰიგიენური უსაფრთხოებისთვის', 'Düzgün cavab: C) შრომის დაცვისა და უსაფრთხოების ტექნიკის წესების შესაბამისად, უეცარი ტრავმის, ჭრი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b46f941f-1327-4464-8fa3-5078fcd40f20', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Azərbaycan Respublikası Konstitusiyasının 42-ci maddəsinə əsasən, təhsil hüququnun təminatı ilə bağlı hansı müddəa təsbit edilmişdir?', 'multiple_choice', '["Dövlət yalnız dövlət məktəblərində təhsili pulsuz edir", "Dövlət təhsil hüququnu yalnız 18 yaşadək vətəndaşlara şamil edir", "Dövlət yalnız ibtidai təhsili icbari hesab edir", "Dövlət ali təhsilin bütün pillələrində pulsuz təhsilə təminat verir", "Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququna, istedadlı şəxslərin təhsilini davam etdirməsinə və təhsil sisteminə dövlət nəzarətinə təminat verir"]'::jsonb, 'Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququna, istedadlı şəxslərin təhsilini davam etdirməsinə və təhsil sisteminə dövlət nəzarətinə təminat verir', 'Düzgün cavab: E) Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququna, isteda', '', 31, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4b066680-61ef-4539-aa6e-1663859b11ac', 'b46f941f-1327-4464-8fa3-5078fcd40f20', 'ka', 'კონსტიტუციის 42-ე მუხლის თანახმად, რომელი დებულებაა განმტკიცებული განათლების უფლების უზრუნველყოფასთან დაკავშირებით?', '["სახელმწიფო განათლების უფლებას მხოლოდ 18 წლამდე ასაკის მოქალაქეებზე ავრცელებს", "სახელმწიფო განათლებას უფასოს ხდის მხოლოდ სახელმწიფო სკოლებში", "სახელმწიფო უზრუნველყოფს უფასო განათლებას უმაღლესი განათლების ყველა საფეხურზე", "სახელმწიფო სავალდებულოდ მიიჩნევს მხოლოდ დაწყებით განათლებას", "სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას მიიღოს უფასო სავალდებულო ზოგადი საშუალო განათლება, ნიჭიერი პირების მიერ განათლების გაგრძელებას და სახელმწიფო კონტროლს განათლების სისტემაზე"]'::jsonb, 'სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას მიიღოს უფასო სავალდებულო ზოგადი საშუალო განათლება, ნიჭიერი პირების მიერ განათლების გაგრძელებას და სახელმწიფო კონტროლს განათლების სისტემაზე', 'Düzgün cavab: E) სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას მიიღოს უფასო სავალდებულო ზოგა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b7510c4c-9da6-4b77-a295-f922e8e09977', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Azərbaycan Respublikası Konstitusiyasının 25-ci maddəsinə görə, bərabərlik hüququnun məzmununu əks etdirən düzgün hüquqi norma hansıdır?', 'multiple_choice', '["Dövlət yalnız Azərbaycan vətəndaşlarının bərabərliyinə təminat verir", "Bərabərlik hüququ yalnız məhkəmə prosesində tətbiq olunur", "Dövlət bərabərliyi yalnız əmək münasibətlərində təmin edir", "Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, əqidəsindən, sosial mənşəyindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir", "Bərabərlik yalnız dövlət qulluqçuları arasında tətbiq edilir"]'::jsonb, 'Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, əqidəsindən, sosial mənşəyindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir', 'Düzgün cavab: D) Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, əqidəsin', '', 32, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d5188881-d41b-4e74-b423-bd1e51964f8c', 'b7510c4c-9da6-4b77-a295-f922e8e09977', 'ka', 'კონსტიტუციის 25-ე მუხლის თანახმად, რომელია თანასწორობის უფლების შინაარსის ამსახველი სწორი ნორმა?', '["თანასწორობის უფლება გამოიყენება მხოლოდ სასამართლო პროცესში", "სახელმწიფო უზრუნველყოფს მხოლოდ აზერბაიჯანის მოქალაქეთა თანასწორობას", "თანასწორობა გამოიყენება მხოლოდ საჯარო მოხელეებს შორის", "სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესის, მრწამსის, სოციალური წარმოშობის მიუხედავად", "სახელმწიფო თანასწორობას უზრუნველყოფს მხოლოდ შრომით ურთიერთობებში"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესის, მრწამსის, სოციალური წარმოშობის მიუხედავად', 'Düzgün cavab: D) სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b043881d-81b8-4d17-a17b-e04b88d0bfac', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Azərbaycan Respublikası Konstitusiyasının 32-ci maddəsinə əsasən, şəxsi toxunulmazlıq hüququ ilə bağlı hansı qayda müəyyən olunmuşdur?', 'multiple_choice', '["Şəxsi məlumatlar məhkəmə qərarı olmadan da toplanıla bilər", "Fərdi məlumatların toplanması daxili nizamnamə ilə sərbəst tənzimlənir", "Şəxsi həyat haqqında məlumatların yayılması yalnız şifahi razılıqla mümkündür", "Şəxsi toxunulmazlıq yalnız dövlət sirri daşıyan şəxslərə şamil edilir", "Öz razılığı olmadan kimsənin şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir"]'::jsonb, 'Öz razılığı olmadan kimsənin şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir', 'Düzgün cavab: E) Öz razılığı olmadan kimsənin şəxsi həyatı haqqında məlumatların toplanılmasına,', '', 33, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bc979e98-709e-40f5-be3f-1f0cfe98dec2', 'b043881d-81b8-4d17-a17b-e04b88d0bfac', 'ka', 'კონსტიტუციის 32-ე მუხლის თანახმად, რა წესია დადგენილი პირადი ხელშეუხებლობის უფლებასთან დაკავშირებით?', '["პირადი ცხოვრების შესახებ ინფორმაციის გავრცელება შესაძლებელია მხოლოდ ზეპირი თანხმობით", "პირადი ხელშეუხებლობა ვრცელდება მხოლოდ იმ პირებზე, რომლებიც ფლობენ სახელმწიფო საიდუმლოებას", "პერსონალური ინფორმაციის შეგროვება შესაძლებელია სასამართლოს გადაწყვეტილების გარეშეც", "პერსონალური მონაცემების შეგროვება თავისუფლად რეგულირდება შინაგანაწესით", "მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა, გამოყენება და გავრცელება დაუშვებელია, გარდა კანონით დადგენილი შემთხვევებისა"]'::jsonb, 'მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა, გამოყენება და გავრცელება დაუშვებელია, გარდა კანონით დადგენილი შემთხვევებისა', 'Düzgün cavab: E) მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9baa230d-f807-4bde-b57d-84ec24d7c83e', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', '“Təhsil haqqında” AR Qanununun 3-cü maddəsinə əsasən, təhsil sahəsində dövlət siyasətinin əsas prinsiplərindən olan ''Humanistlik'' nəyi ifadə edir?', 'multiple_choice', '["Təhsil müəssisələrinin yalnız dövlət tərəfindən maliyyələşdirilməsini", "Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını", "Təhsildə rəqabət mühitinin aradan qaldırılmasını", "Təhsilin yalnız milli dəyərlərə əsaslanmasını", "Təhsilalanların yalnız əmək bazarına uyğun hazırlanmasını"]'::jsonb, 'Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını', 'Düzgün cavab: B) Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və', '', 34, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('219d380d-000e-43c1-bc6b-093ea4640b63', '9baa230d-f807-4bde-b57d-84ec24d7c83e', 'ka', 'კანონის „განათლების შესახებ“ მე-3 მუხლის თანახმად, რას გამოხატავს „ჰუმანურობის“ პრინციპი?', '["განათლების დაფუძნებას მხოლოდ ეროვნულ ფასეულობებზე", "ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას", "კონკურენტული გარემოს აღმოფხვრას", "საგანმანათლებლო დაწესებულებების დაფინანსებას მხოლოდ სახელმწიფოს მიერ", "შემსწავლელთა მომზადებას მხოლოდ შრომის ბაზრის მოთხოვნების შესაბამისად"]'::jsonb, 'ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას', 'Düzgün cavab: B) ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b507248f-a0d5-47e7-8ccb-4c1a5f1e0ea7', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', '“Təhsil haqqında” AR Qanununun 12-ci maddəsinə əsasən, Azərbaycan Respublikasında təsbit edilmiş təhsil formaları hansılardır?', 'multiple_choice', '["İbtidai, orta və ali təhsil", "Əyani, qiyabi və distant təhsil", "Formal, qeyri-formal və informal təhsil", "Dövlət, özəl və bələdiyyə təhsili", "Məktəbəqədər, ümumi və peşə təhsili"]'::jsonb, 'Formal, qeyri-formal və informal təhsil', 'Düzgün cavab: C) Formal, qeyri-formal və informal təhsil', '', 35, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('239ab82e-d0cc-4193-bc52-1bfd76d8b493', 'b507248f-a0d5-47e7-8ccb-4c1a5f1e0ea7', 'ka', 'კანონის „განათლების შესახებ“ მე-12 მუხლის თანახმად, რომელია განათლების მიღების დადგენილი ფორმები?', '["სახელმწიფო, კერძო და მუნიციპალური განათლება", "დაწყებითი, საშუალო და უმაღლესი განათლება", "ფორმალური, არაფორმალური და ინფორმალური განათლება", "დასწრებული, დაუსწრებელი და დისტანციური განათლება", "სკოლამდელი, ზოგადი და პროფესიული განათლება"]'::jsonb, 'ფორმალური, არაფორმალური და ინფორმალური განათლება', 'Düzgün cavab: C) ფორმალური, არაფორმალური და ინფორმალური განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b76d8c05-f79c-43ad-8f9b-9f48b87a1fed', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Müxtəlif səbəblərdən ümumi təhsildən kənarda qalmış şəxslərə təhsil almaq hüququ verən təhsilalma forması hansıdır?', 'multiple_choice', '["Fərdi təhsilalma forması", "İnklüziv təhsilalma forması", "Evdə təhsilalma forması", "Sərbəst (eksternat) təhsilalma forması", "Distant təhsilalma forması"]'::jsonb, 'Sərbəst (eksternat) təhsilalma forması', 'Düzgün cavab: D) Sərbəst (eksternat) təhsilalma forması', '', 36, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cb8ec769-f6fb-461b-bc5a-af1362fdb040', 'b76d8c05-f79c-43ad-8f9b-9f48b87a1fed', 'ka', 'განათლების მიღების რომელი ფორმა აძლევს განათლების მიღების უფლებას იმ პირებს, რომლებიც სხვადასხვა მიზეზით დარჩნენ განათლების მიღმა?', '["დისტანციური განათლების ფორმა", "ინკლუზიური განათლების ფორმა", "შინ სწავლების ფორმა", "ექსტერნატის (თავისუფალი) განათლების ფორმა", "ინდივიდუალური განათლების ფორმა"]'::jsonb, 'ექსტერნატის (თავისუფალი) განათლების ფორმა', 'Düzgün cavab: D) ექსტერნატის (თავისუფალი) განათლების ფორმა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9a3fbcb1-be28-49b7-88ea-124a6952caed', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', '“Təhsil haqqında” AR Qanununun 32-ci maddəsinə əsasən, təhsilverənlərin vəzifələrinə aid olan müddəa hansıdır?', 'multiple_choice', '["İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını və İKT-ni mənimsəyərək tədris prosesində tətbiq etmək", "Təhsil proqramlarını sərbəst dəyişdirmək", "Şagirdlərin davamiyyətinə nəzarəti dayandırmaq", "Valideynlərdən əlavə haqq tələb etmək", "Dərs cədvəlini müstəqil tərtib etmək"]'::jsonb, 'İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını və İKT-ni mənimsəyərək tədris prosesində tətbiq etmək', 'Düzgün cavab: A) İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını və', '', 37, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('09c8a522-cb80-4f95-be3e-e8657e96a1f8', '9a3fbcb1-be28-49b7-88ea-124a6952caed', 'ka', 'კანონის „განათლების შესახებ“ 32-ე მუხლის თანახმად, რომელი დებულება განეკუთვნება პედაგოგთა (მასწავლებელთა) მოვალეობებს?', '["კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, თანამედროვე სწავლების მეთოდებისა და ისტ-ის ათვისება და გამოყენება სასწავლო პროცესში", "საგაკვეთილო ცხრილის დამოუკიდებლად შედგენა", "დასწრების კონტროლის შეწყვეტა", "საგანმანათლებლო პროგრამების თვითნებურად შეცვლა", "მშობლებისგან დამატებითი საფასურის მოთხოვნა"]'::jsonb, 'კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, თანამედროვე სწავლების მეთოდებისა და ისტ-ის ათვისება და გამოყენება სასწავლო პროცესში', 'Düzgün cavab: A) კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, თანამედროვე სწავლების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5392fc5d-24a3-4a02-bd1b-e743d37a9411', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', '“Ümumi təhsil haqqında” AR Qanununa əsasən, ümumi təhsil pilləsinin səviyyələri hansı variantda tam göstərilmişdir?', 'multiple_choice', '["Məktəbəqədər (I–IV), orta (V–X) və tam (XI–XII)", "İbtidai (I–V), ümumi (VI–IX) və peşə (X–XI)", "Hazırlıq (0), ibtidai (I–IV) və orta (V–XI)", "İbtidai (I–III), orta (IV–IX) və böyük (X–XII)", "Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)"]'::jsonb, 'Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)', 'Düzgün cavab: E) Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və ta', '', 38, true, false, true, 1.0, 'exact', true, false, NOW());
