INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b615f1f2-4c7b-44f0-abd6-90042e15a6b1', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', '“Ümumi təhsil haqqında” AR Qanununun 21-ci maddəsinə əsasən, aşağıdakılardan hansı təhsilalanların hüquqlarına **AİD DEYİLDİR**?', 'multiple_choice', '["Təhlükəsiz və sağlam təhsil şəraiti ilə təmin olunmaq", "Kitabxana və laboratoriyadan pulsuz istifadə etmək", "Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq", "Dövlət məktəblərində dərsliklərlə pulsuz təmin olunmaq", "Ləyaqətini alçaldan rəftardan müdafiə olunmaq"]'::jsonb, 'Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq', 'Düzgün cavab: C) Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoj', '', 39, true, false, true, 1.0, 'exact', true, false, NOW());
