INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d79510c1-34fd-4c13-b2b6-a91666d2be67', '9f820336-825e-4e77-a493-af91d9f8d47f', 'ka', 'ტიპური დებულების თანახმად, ვინ ახორციელებს სკოლის საქმიანობის მიმდინარე ხელმძღვანელობას?', '["პროფკავშირული კომიტეტის ხელმძღვანელი", "მუნიციპალიტეტის თავმჯდომარის მიერ დანიშნული წარმომადგენელი", "მშობელთა და მასწავლებელთა ასოციაციის თავმჯდომარე", "პედაგოგიური საბჭოს მიერ არჩეული თავმჯდომარე", "შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექტორი"]'::jsonb, 'შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექტორი', 'Düzgün cavab: E) შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e6605003-2e24-46ba-a072-59e68c947cd1', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Pedaqoji Şura haqqında Əsasnaməyə əsasən, qərarların qəbul edilməsi qaydası necədir?', 'multiple_choice', '["İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilərək direktorun əmri ilə rəsmiləşdirilir", "Bütün üzvlər iştirak etməlidir, qərarlar 2/3 səs çoxluğu ilə qəbul edilir", "İclas açıq səsvermə ilə keçirilir, qərarlar katib tərəfindən rəsmiləşdirilir", "Yalnız fənn birləşmə rəhbərləri iştirak edir", "Üzvlərin yarısından çoxu iştirak etdikdə səlahiyyətlidir, qərarlar yekdilliklə qəbul edilir"]'::jsonb, 'İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilərək direktorun əmri ilə rəsmiləşdirilir', 'Düzgün cavab: A) İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qəra', '', 41, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3d5b3f47-6c19-4c65-a519-91a882221688', 'e6605003-2e24-46ba-a072-59e68c947cd1', 'ka', 'პედაგოგიური საბჭოს შესახებ დებულების თანახმად, როგორია გადაწყვეტილების მიღების წესი?', '["სხდომა უფლებამოსილია წევრთა არანაკლებ ორი მესამედის მონაწილეობისას და გადაწყვეტილებები მიიღება ხმების უბრალო უმრავლესობით, რაც ფორმდება დირექტორის ბრძანებით", "უნდა მონაწილეობდეს ყველა წევრი, გადაწყვეტილებები მიიღება ხმების 2/3-ით", "მონაწილეობენ მხოლოდ საგნობრივი კათედრების ხელმძღვანელები", "უფლებამოსილია წევრთა ნახევარზე მეტის მონაწილეობისას, გადაწყვეტილებები მიიღება ერთხმად", "სხდომა ტარდება ღია კენჭისყრით, გადაწყვეტილებებს აფორმებს მდივანი"]'::jsonb, 'სხდომა უფლებამოსილია წევრთა არანაკლებ ორი მესამედის მონაწილეობისას და გადაწყვეტილებები მიიღება ხმების უბრალო უმრავლესობით, რაც ფორმდება დირექტორის ბრძანებით', 'Düzgün cavab: A) სხდომა უფლებამოსილია წევრთა არანაკლებ ორი მესამედის მონაწილეობისას და გადაწყვეტი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('00298562-e3af-4cc3-89da-509b97249aba', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'AR Əmək Məcəlləsinin 89 və 91-ci maddələrinə əsasən, iş vaxtının normal və qısaldılmış müddəti necə tənzimlənir?', 'multiple_choice', '["Normal iş vaxtı 40 saat, 16 yaşadək işçilər üçün 24 saatdır", "Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz", "Normal iş vaxtı 48 saat, yeniyetmələr üçün 40 saatdır", "Normal iş vaxtı 36 saat, ağır sahədə çalışanlar üçün 30 saatdır", "Normal iş vaxtı 45 saat, pedaqoji işçilər üçün 30 saatdır"]'::jsonb, 'Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz', 'Düzgün cavab: B) Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün i', '', 42, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9268a652-c93a-4be8-a82a-5cdb71c70316', '00298562-e3af-4cc3-89da-509b97249aba', 'ka', 'შრომის კოდექსის 89-ე და 91-ე მუხლების თანახმად, როგორია სამუშაო დროის ნორმალური და შემოკლებული ხანგრძლივობა?', '["ნორმალური სამუშაო დრო 36 საათია, მძიმე პირობებში მომუშავეთათვის - 30 საათი", "ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირთათვის - კვირაში 36 საათს", "ნორმალური სამუშაო დრო 48 საათია, მოზარდებისთვის - 40 საათი", "ნორმალური სამუშაო დრო 40 საათია, 16 წლამდე ასაკის მუშაკებისთვის - 24 საათი", "ნორმალური სამუშაო დრო 45 საათია, პედაგოგიური მუშაკებისთვის - 30 საათი"]'::jsonb, 'ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირთათვის - კვირაში 36 საათს', 'Düzgün cavab: B) ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9873f705-56c1-4fff-a834-01377a364380', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'AR Əmək Məcəlləsinin 186-cı maddəsinə əsasən, intizam tənbehlərinin tam və qanuni siyahısı hansıdır?', 'multiple_choice', '["Şifahi töhmət, yazılı töhmət, şiddətli töhmət və işdən çıxarma", "Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi", "Töhmət, maaşın 50% tutulması və vəzifənin aşağı salınması", "İnzibati cərimə, ictimai işlər və müqaviləyə xitam", "Xəbərdarlıq, töhmət, vəzifədən azad etmə və cərimə"]'::jsonb, 'Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi', 'Düzgün cavab: B) Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutu', '', 43, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('fa092b9a-9f1c-47db-8839-bff128f4a602', '9873f705-56c1-4fff-a834-01377a364380', 'ka', 'შრომის კოდექსის 186-ე მუხლის თანახმად, რომელია დისციპლინური სახდელების სრული ჩამონათვალი?', '["საყვედური, ხელფასის 50%-ის დაკავება და თანამდებობრივი დაქვეითება", "საყვედური, სასტიკი საყვედური უკანასკნელი გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალისწინებულ შემთხვევაში ყოველთვიური ხელფასის არაუმეტეს 1/4-ის ოდენობით ჯარიმა და შრომითი ხელშეკრულების შეწყვეტა შრომის კოდექსის 70-ე მუხლით", "ზეპირი საყვედური, წერილობითი საყვედური, სასტიკი საყვედური და სამსახურიდან გათავისუფლება", "გაფრთხილება, საყვედური, თანამდებობიდან გათავისუფლება და ჯარიმა", "ადმინისტრაციული ჯარიმა, საზოგადოებრივი შრომა და ხელშეკრულების შეწყვეტა"]'::jsonb, 'საყვედური, სასტიკი საყვედური უკანასკნელი გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალისწინებულ შემთხვევაში ყოველთვიური ხელფასის არაუმეტეს 1/4-ის ოდენობით ჯარიმა და შრომითი ხელშეკრულების შეწყვეტა შრომის კოდექსის 70-ე მუხლით', 'Düzgün cavab: B) საყვედური, სასტიკი საყვედური უკანასკნელი გაფრთხილებით, კოლექტიური ხელშეკრულებით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('eefe10f8-c913-4fa9-b1a2-28a1e90f1256', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'AR Əmək Məcəlləsinin 187 və 188-ci maddələrinə əsasən, intizam tənbehinin tətbiqi və qüvvədə olma müddəti qaydası necədir?', 'multiple_choice', '["İzahat tələb olunmur, tənbeh məhkəmə qərarı ilə 3 il qüvvədə qalır", "İntizam tənbehi verildikdə işçidən izahat alınır və tənbeh verildiyi gündən 1 il qüvvədə qalır", "İzahat tələb edilmədən tənbeh verilə bilər və 2 il qüvvədə qalır", "İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz", "İzahat mütləqdir, tənbeh yalnız 1 ay qüvvədə olur"]'::jsonb, 'İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz', 'Düzgün cavab: D) İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbe', '', 44, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f23ec1ad-9970-422f-8371-9f9b4d6913a5', 'eefe10f8-c913-4fa9-b1a2-28a1e90f1256', 'ka', 'შრომის კოდექსის 187-ე მუხლის თანახმად, როგორია დისციპლინური სახდელის დადების წესი?', '["ახსნა-განმარტება არ მოითხოვება, სახდელი ძალაში რჩება სასამართლოს გადაწყვეტილებით 3 წლის განმავლობაში", "სახდელი შეიძლება დაედოს ახსნა-განმარტების მოთხოვნის გარეშე და ძალაში რჩება 2 წელი", "ახსნა-განმარტება სავალდებულოა, სახდელი ძალაშია 3 თვე", "დისციპლინური სახდელის დადებამდე მუშაკს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია დადების დღიდან 1 წლის განმავლობაში", "ახსნა-განმარტება მიიღება მხოლოდ ზეპირად და სახდელი ძალაშია 6 თვე"]'::jsonb, 'დისციპლინური სახდელის დადებამდე მუშაკს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია დადების დღიდან 1 წლის განმავლობაში', 'Düzgün cavab: D) დისციპლინური სახდელის დადებამდე მუშაკს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტებ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('db830f68-da72-49cb-abb3-cea1ba30ec37', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'AR Əmək Məcəlləsinin 69 və 172-ci maddələrinə əsasən, işçinin öz təşəbbüsü ilə əmək müqaviləsinə xitam verilməsi qaydası necədir?', 'multiple_choice', '["İşçi 3 iş günü əvvəl xəbərdarlıq edir", "İşçi 15 gün əvvəl ərizə verir", "İşçi xəbərdarlıq etmədən çıxa bilər", "İşçi 2 həftə əvvəl şifahi xəbərdarlıq edir", "İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab sonuncu iş günündən gec olmayaraq tam ödənilir"]'::jsonb, 'İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab sonuncu iş günündən gec olmayaraq tam ödənilir', 'Düzgün cavab: E) İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haq', '', 45, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6a74950c-9ed0-44bf-9757-7fac4e41142b', 'db830f68-da72-49cb-abb3-cea1ba30ec37', 'ka', 'შრომის კოდექსის 69-ე და 172-ე მუხლების თანახმად, როგორია მუშაკის საკუთარი ინიციატივით შრომითი ხელშეკრულების შეწყვეტის წესი?', '["მუშაკი განცხადებას წარადგენს 15 დღით ადრე", "მუშაკი ზეპირად აფრთხილებს 2 კვირით ადრე", "მუშაკი აფრთხილებს 3 სამუშაო დღით ადრე", "მუშაკს შეუძლია წავიდეს გაფრთხილების გარეშე", "მუშაკმა დამსაქმებელი წერილობითი განცხადებით უნდა გააფრთხილოს 1 კალენდარული თვით ადრე; საბოლოო ანგარიშსწორება სრულად ხდება არაუგვიანეს ბოლო სამუშაო დღისა"]'::jsonb, 'მუშაკმა დამსაქმებელი წერილობითი განცხადებით უნდა გააფრთხილოს 1 კალენდარული თვით ადრე; საბოლოო ანგარიშსწორება სრულად ხდება არაუგვიანეს ბოლო სამუშაო დღისა', 'Düzgün cavab: E) მუშაკმა დამსაქმებელი წერილობითი განცხადებით უნდა გააფრთხილოს 1 კალენდარული თვით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4d2be801-d87c-4a5e-83f7-7aa6f8c87e4d', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'LAN və WAN şəbəkələrinin əsas fərqi nədən ibarətdir?', 'multiple_choice', '["LAN-da sürət aşağı, WAN-da sürət yüksək olur", "LAN yalnız simli, WAN yalnız simsiz texnologiya ilə qurulur", "LAN dövlət qurumları üçün, WAN fərdi istifadəçilər üçündür", "LAN internetə çıxış üçün, WAN lokal resurs paylaşımı üçündür", "LAN məhdud coğrafi ərazidə (otaq, bina, məktəb) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir"]'::jsonb, 'LAN məhdud coğrafi ərazidə (otaq, bina, məktəb) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir', 'Düzgün cavab: E) LAN məhdud coğrafi ərazidə (otaq, bina, məktəb) yerləşən kompüterləri, WAN isə b', '', 46, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f94a3f6b-7539-4cfe-a31d-5293622b7a45', '4d2be801-d87c-4a5e-83f7-7aa6f8c87e4d', 'ka', 'რა არის მთავარი განსხვავება LAN და WAN ქსელებს შორის?', '["LAN-ში სიჩქარე დაბალია, WAN-ში სიჩქარე მაღალია", "LAN ინტერნეტთან წვდომისთვისაა, WAN ლოკალური რესურსების გასაზიარებლად", "LAN სახელმწიფო სტრუქტურებისთვისაა, WAN ინდივიდუალური მომხმარებლებისთვის", "LAN იქმნება მხოლოდ სადენიანი, ხოლო WAN მხოლოდ უსადენო ტექნოლოგიით", "LAN არის შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებული კომპიუტერების ქსელი, ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს"]'::jsonb, 'LAN არის შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებული კომპიუტერების ქსელი, ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს', 'Düzgün cavab: E) LAN არის შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებული კომპიუტ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('52f3e245-c8f3-492e-bb6f-e5e94512f384', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'İnternetdə domen adlarını kompüterlərin anladığı rəqəmsal IP ünvanlarına çevirən əsas şəbəkə xidməti hansıdır?', 'multiple_choice', '["ARP (Address Resolution Protocol)", "Proxy Service (Vekil xidməti)", "NAT (Network Address Translation)", "DNS (Domain Name System)", "DHCP (Dynamic Host Configuration Protocol)"]'::jsonb, 'DNS (Domain Name System)', 'Düzgün cavab: D) DNS (Domain Name System)', '', 47, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3e763ae9-3307-48b8-a168-045a1a580fe0', '52f3e245-c8f3-492e-bb6f-e5e94512f384', 'ka', 'რომელია ძირითადი ქსელური სერვისი, რომელიც დომენურ სახელებს IP მისამართებად გარდაქმნის?', '["NAT - მისამართების გარდაქმნის სისტემა", "DHCP - დინამიკური IP განაწილების სისტემა", "Proxy Service - შუალედური ქეშირების სისტემა", "DNS (Domain Name System) - დომენური სახელების განაწილებული იერარქიული სისტემა", "ARP - MAC მისამართის განსაზღვრის სისტემა"]'::jsonb, 'DNS (Domain Name System) - დომენური სახელების განაწილებული იერარქიული სისტემა', 'Düzgün cavab: D) DNS (Domain Name System) - დომენური სახელების განაწილებული იერარქიული სისტემა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c4effce7-ad28-49a2-b473-0ae0327f8bcb', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'İki faktorlu autentifikasiya (2FA) mexanizminin əsas üstünlüyü nədir?', 'multiple_choice', '["Əməliyyat sisteminin yeniləmələrini avtomatik quraşdırması", "Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləməsi", "Faylları avtomatik arxivləşdirərək yaddaşa qənaət etməsi", "İnternet sürətini artıraraq şifrələməni sürətləndirməsi", "Eyni anda bir neçə cihazdan daxil olmanı məhdudlaşdırması"]'::jsonb, 'Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləməsi', 'Düzgün cavab: B) Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifi', '', 48, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0d810afd-ca34-40c7-ab3a-48c37a1f1c02', 'c4effce7-ad28-49a2-b473-0ae0327f8bcb', 'ka', 'რა არის ორფაქტორიანი ავთენტიფიკაციის (2FA) მექანიზმის მთავარი უპირატესობა?', '["ოპერაციული სისტემის განახლებების ავტომატური ინსტალაცია", "პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების (SMS კოდი, TOTP, ავთენტიფიკატორის აპლიკაცია ან FIDO2 გასაღები) გარეშე", "ერთდროულად რამდენიმე მოწყობილობიდან შესვლის შეზღუდვა", "ფაილების ავტომატური დაარქივება მეხსიერების დაზოგვის მიზნით", "ინტერნეტის სიჩქარის გაზრდა და შიფრაციის დაჩქარება"]'::jsonb, 'პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების (SMS კოდი, TOTP, ავთენტიფიკატორის აპლიკაცია ან FIDO2 გასაღები) გარეშე', 'Düzgün cavab: B) პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('12cccf78-109c-4580-a102-b961846ea181', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Saxta e-poçt və keçidlər göndərərək istifadəçilərin məxfi məlumatlarını mənimsəmə hansı kiberhücum növüdür?', 'multiple_choice', '["Brute Force (Kütləvi şifrə seçimi)", "Fişinq (Phishing)", "Ransomware (Fidyə proqramı)", "Spoofing (Ünvan saxtalaşdırması)", "Sniffing (Şəbəkə dinlənilməsi)"]'::jsonb, 'Fişinq (Phishing)', 'Düzgün cavab: B) Fişinq (Phishing)', '', 49, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3deab41a-39e8-44fe-93be-99958e1441d0', '12cccf78-109c-4580-a102-b961846ea181', 'ka', 'ყალბი ელექტრონული წერილის გაგზავნით მონაცემების მითვისება კიბერშეტევის რომელ სახეობას განეკუთვნება?', '["სნიფინგი (Sniffing) - ქსელური ტრაფიკის ფარული მოსმენა", "ფიშინგი (Phishing) - სოციალური ინჟინერიის საფუძველზე ყალბი ელფოსტისა და ვებსაიტის მეშვეობით საიდენტიფიკაციო მონაცემების მოპარვა", "Brute Force - პაროლის შერჩევა მასიური ცდების გზით", "გამომძალველი პროგრამა (Ransomware) - ფაილების დაშიფვრა გამოსასყიდის მოთხოვნით", "სპუფინგი (Spoofing) - IP ან MAC მისამართის გაყალბება"]'::jsonb, 'ფიშინგი (Phishing) - სოციალური ინჟინერიის საფუძველზე ყალბი ელფოსტისა და ვებსაიტის მეშვეობით საიდენტიფიკაციო მონაცემების მოპარვა', 'Düzgün cavab: B) ფიშინგი (Phishing) - სოციალური ინჟინერიის საფუძველზე ყალბი ელფოსტისა და ვებსაიტი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('65687d39-b1aa-46e6-bc7d-089eabb2bbd9', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Word-da abzasın girintilərini dəqiq tənzimləmək üçün hansı elementdən istifadə olunur?', 'multiple_choice', '["Vəziyyət zolağı və miqyas sürüşdürücüsü", "Şaquli xətkeş və səhifə kənar boşluqları", "Naviqasiya paneli və axtarış qutusu", "Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi", "Sürətli müraciət paneli və lent interfeysi"]'::jsonb, 'Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi', 'Düzgün cavab: D) Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph', '', 50, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9b97fa90-55c7-406d-8118-f376a4bc49c7', '65687d39-b1aa-46e6-bc7d-089eabb2bbd9', 'ka', 'Word-ში რომელი ელემენტი გამოიყენება აბზაცის შეწევის (ინდენტაციის) ზუსტად დასარეგულირებლად?', '["ნავიგაციის პანელი და ძიების ველი", "სტატუსის ზოლი და მასშტაბირების სლაიდერი", "ვერტიკალური სახაზავი და გვერდის მინდვრები", "ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული შეწევის მარკერები და Paragraph დიალოგური ფანჯარა", "სწრაფი წვდომის პანელი და ლენტის ინტერფეისი"]'::jsonb, 'ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული შეწევის მარკერები და Paragraph დიალოგური ფანჯარა', 'Düzgün cavab: D) ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული შეწევის მარკერები და Paragrap', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ad131a76-e670-4a24-905c-4ee890cf6c32', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Word-da sənədin bəzi səhifələrini şaquli, bəzi səhifələrini üfüqi oriyentasiyada formatlamaq üçün hansı əməliyyat icra olunmalıdır?', 'multiple_choice', '["Mətn qutuları istifadə edilərək səhifə fırladılmalıdır", "Sənəd iki ayrı fayla bölünüb hər birinin oriyentasiyası ayrı təyin edilməlidir", "Səhifə kənar boşluqları dəyişdirilərək üfüqi effekt yaradılmalıdır", "Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir", "Hər səhifə üçün ayrıca Page Break əlavə edilib oriyentasiya dəyişdirilməlidir"]'::jsonb, 'Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir', 'Düzgün cavab: D) Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin O', '', 51, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3fe885ff-9f63-4ff6-b454-72c34e0188bf', 'ad131a76-e670-4a24-905c-4ee890cf6c32', 'ka', 'Word-ში ზოგიერთი გვერდის ვერტიკალურ (წიგნისებრ) და ზოგიერთი გვერდის ჰორიზონტალურ (ალბომურ) ორიენტაციაში დასაფორმატებლად რომელი მოქმედება უნდა შესრულდეს?', '["დოკუმენტი ორ ცალკე ფაილად უნდა გაიყოს და თითოეულს ცალკე განესაზღვროს ორიენტაცია", "თითოეული გვერდისთვის ცალკე უნდა ჩაისვას Page Break და შეიცვალოს ორიენტაცია", "გვერდის მინდვრების შეცვლით უნდა შეიქმნას ჰორიზონტალური ეფექტი", "დოკუმენტში უნდა ჩაისვას სექციის გაწყვეტა (Section Break - Next Page) და შეიცვალოს ამ სექციის Layout > Orientation პარამეტრი", "ტექსტური ველების (Text Box) გამოყენებით უნდა შემოტრიალდეს გვერდი"]'::jsonb, 'დოკუმენტში უნდა ჩაისვას სექციის გაწყვეტა (Section Break - Next Page) და შეიცვალოს ამ სექციის Layout > Orientation პარამეტრი', 'Düzgün cavab: D) დოკუმენტში უნდა ჩაისვას სექციის გაწყვეტა (Section Break - Next Page) და შეიცვალო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2b5b4992-29c1-4309-831d-6dea07aa7a28', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Word-da başlıqlara əsasən avtomatik yenilənən Mündəricat yaratmaq üçün hansı taba müraciət edilir?', 'multiple_choice', '["Layout > Table of Contents", "Review > Table of Contents", "Insert > Table of Contents", "View > Navigation Pane", "References (İstinadlar) tabı > Table of Contents"]'::jsonb, 'References (İstinadlar) tabı > Table of Contents', 'Düzgün cavab: E) References (İstinadlar) tabı > Table of Contents', '', 52, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6ec45b52-da1c-4982-98dd-b0b8919399c1', '2b5b4992-29c1-4309-831d-6dea07aa7a28', 'ka', 'Word-ში სათაურების საფუძველზე ავტომატურად განახლებადი სარჩევის შესაქმნელად რომელ ჩანართს უნდა მივმართოთ?', '["Review > Table of Contents", "View > Navigation Pane", "Insert > Table of Contents", "Layout > Table of Contents", "ჩანართი References > ჯგუფი Table of Contents"]'::jsonb, 'ჩანართი References > ჯგუფი Table of Contents', 'Düzgün cavab: E) ჩანართი References > ჯგუფი Table of Contents', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5b65cb5f-f445-4042-b303-7851edc3ba60', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Excel-də `$C$2` mütləq xana ünvanı olan düstur başqa xanalara kopyalandıqda necə dəyişir?', 'multiple_choice', '["Yalnız sətir sabit qalır, sütun dəyişir", "Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır", "Düstur xəta verir və #REF! qaytarır", "Həm sütun, həm sətir avtomatik sürüşür", "Yalnız sütun sabit qalır, sətir dəyişir"]'::jsonb, 'Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', 'Düzgün cavab: B) Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', '', 53, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('eb505c1d-9166-47fa-9804-45e2e703343c', '5b65cb5f-f445-4042-b303-7851edc3ba60', 'ka', 'Excel-ში როგორ იცვლება უჯრედის აბსოლუტური მისამართის შემცველი ფორმულა $C$2 სხვა უჯრედებში კოპირებისას?', '["ავტომატურად ინაცვლებს როგორც სვეტი, ასევე სტრიქონი", "რადგან დოლარის ნიშანი ($) ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკკოპირდეს ფორმულა, უჯრედის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური ბმული)", "ფორმულა იძლევა შეცდომას და აბრუნებს #REF!-ს", "მხოლოდ სტრიქონი რჩება უცვლელი, სვეტი იცვლება", "მხოლოდ სვეტი რჩება უცვლელი, სტრიქონი იცვლება"]'::jsonb, 'რადგან დოლარის ნიშანი ($) ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკკოპირდეს ფორმულა, უჯრედის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური ბმული)', 'Düzgün cavab: B) რადგან დოლარის ნიშანი ($) ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკკოპირდეს ფორ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7077a286-deb9-44d8-b368-76941e2e9a0e', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Excel-də `A1:A10` diapazonunda yalnız qiyməti 50-dən böyük olan xanaların sayını hesablamaq üçün hansı funksiya düzgündür?', 'multiple_choice', '["=COUNTIF(A1:A10; \">50\")", "=COUNTIFS(A1:A10; \">50\")", "=SUMIF(A1:A10; \">50\")", "=IF(A1:A10>50; COUNT(A1:A10))", "=COUNTIF(A1:A10; >50)"]'::jsonb, '=COUNTIF(A1:A10; ">50")', 'Düzgün cavab: A) =COUNTIF(A1:A10; ">50")', '', 54, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('dcae1730-c369-452a-b170-6ef1481944bb', '7077a286-deb9-44d8-b368-76941e2e9a0e', 'ka', 'Excel-ში A1:A10 დიაპაზონში მხოლოდ 50-ზე მეტი მნიშვნელობის მქონე უჯრედების რაოდენობის დასათვლელად რომელი ფუნქციაა სწორი?', '["=COUNTIF(A1:A10;\">50\")", "=COUNTIFS(A1:A10;\">50\")", "=SUMIF(A1:A10;\">50\")", "=IF(A1:A10>50;COUNT(A1:A10))", "=COUNTIF(A1:A10;>50)"]'::jsonb, '=COUNTIF(A1:A10;">50")', 'Düzgün cavab: A) =COUNTIF(A1:A10;">50")', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d7168f56-7c33-4d3a-b0d5-c813e4578d9d', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Excel-də B2 xanasındakı əməkhaqqı 800-dən çox olduqda 15% mükafat, əks halda 5% hesablayan düstur hansıdır?', 'multiple_choice', '["=IF(B2>800; B2*15%; B2*5%)", "=IF(B2>=800; B2*0.15; B2*0.05)", "=IF(B2>800; B2*0.15; B2*0.05)", "=SWITCH(B2>800; TRUE; B2*0.15; FALSE; B2*0.05)", "=IFS(B2>800; B2*0.15; TRUE; B2*0.05)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: C) =IF(B2>800; B2*0.15; B2*0.05)', '', 55, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c0269ddb-5d6b-4fc0-a555-6ef4f9fb0bdd', 'd7168f56-7c33-4d3a-b0d5-c813e4578d9d', 'ka', 'Excel-ში რომელი ფორმულა ითვლის 15%-იან პრემიას, თუ B2 უჯრედში არსებული ხელფასი 800-ზე მეტია, ხოლო წინააღმდეგ შემთხვევაში 5%-ს?', '["=IFS(B2>800; B2*0.15; TRUE; B2*0.05)", "=SWITCH(B2>800; TRUE; B2*0.15; FALSE; B2*0.05)", "=IF(B2>800; B2*0.15; B2*0.05)", "=IF(B2>800; B2*15%; B2*5%)", "=IF(B2>=800; B2*0.15; B2*0.05)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: C) =IF(B2>800; B2*0.15; B2*0.05)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('140e6fd3-9ad4-4103-9a28-9643663c799b', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Excel-də xanaya yalnız müəyyən diapazonda ədədlərin daxil edilməsinə icazə verən alət hansıdır?', 'multiple_choice', '["Data Consolidation (Verilənlərin birləşdirilməsi)", "Conditional Formatting (Şərti formatlaşdırma)", "Filter (Süzgəc)", "Group (Qruplaşdırma)", "Data Validation (Verilənlərin doğrulanması)"]'::jsonb, 'Data Validation (Verilənlərin doğrulanması)', 'Düzgün cavab: E) Data Validation (Verilənlərin doğrulanması)', '', 56, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('04a68a91-5f23-4931-9abe-76b1d314ae0b', '140e6fd3-9ad4-4103-9a28-9643663c799b', 'ka', 'Excel-ში რომელი ინსტრუმენტი იძლევა უჯრედში მხოლოდ გარკვეულ დიაპაზონში რიცხვების შეყვანის დაშვების საშუალებას?', '["პირობითი ფორმატირება (Conditional Formatting)", "მონაცემთა კონსოლიდაცია (Data Consolidation)", "გაფილტვრა (Filter)", "დაჯგუფება (Group)", "მონაცემთა ვალიდაცია (Data Validation) - ჩანართ Data-ში Whole Number, List, Date კრიტერიუმებით"]'::jsonb, 'მონაცემთა ვალიდაცია (Data Validation) - ჩანართ Data-ში Whole Number, List, Date კრიტერიუმებით', 'Düzgün cavab: E) მონაცემთა ვალიდაცია (Data Validation) - ჩანართ Data-ში Whole Number, List, Date', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1c0ba762-7c3a-4a65-86eb-25b186732290', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'PowerPoint-da bütün slaydların vahid dizayn şablonunu dəyişmək üçün hansı rejimdən istifadə olunur?', 'multiple_choice', '["Slide Sorter (Slayd çeşidləyicisi)", "Outline View (Struktur rejimi)", "Slide Master (Slayd nümunəsi)", "Reading View (Oxu rejimi)", "Notes Master (Qeydlər nümunəsi)"]'::jsonb, 'Slide Master (Slayd nümunəsi)', 'Düzgün cavab: C) Slide Master (Slayd nümunəsi)', '', 57, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('51184ec9-2b3e-451e-bffd-947551deb24e', '1c0ba762-7c3a-4a65-86eb-25b186732290', 'ka', 'PowerPoint-ში ყველა სლაიდის ერთიანი დიზაინის შაბლონის შესაცვლელად რომელი რეჟიმი გამოიყენება?', '["Notes Master - შენიშვნების ოსტატის რეჟიმი", "Reading View - კითხვის რეჟიმი", "Slide Master (სლაიდების ნიმუში / ოსტატი) - View ჩანართში ჯგუფი Master Views", "Slide Sorter - სლაიდების დახარისხების რეჟიმი", "Outline View - სტრუქტურის რეჟიმი"]'::jsonb, 'Slide Master (სლაიდების ნიმუში / ოსტატი) - View ჩანართში ჯგუფი Master Views', 'Düzgün cavab: C) Slide Master (სლაიდების ნიმუში / ოსტატი) - View ჩანართში ჯგუფი Master Views', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bf4c7115-247b-45f3-9203-529ffa3a1759', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'PowerPoint-də “Transition” ilə “Animation” arasındakı əsas fərq nədir?', 'multiple_choice', '["Transition obyektlərə, Animation slaydlara tətbiq olunur", "Hər ikisi eyni funksiyadır, sadəcə adları fərqlidir", "Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin hərəkət effektidir", "Transition avtomatik, Animation əl ilə işə düşür", "Transition səs effekti, Animation vizual effektdir"]'::jsonb, 'Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin hərəkət effektidir', 'Düzgün cavab: C) Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation i', '', 58, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0a1ff47b-af6e-43ef-a7c5-9d0326be9432', 'bf4c7115-247b-45f3-9203-529ffa3a1759', 'ka', 'PowerPoint-ში რა არის მთავარი განსხვავება „Transition“-სა და „Animation“-ს შორის?', '["ორივე ერთი და იგივე ფუნქციაა, მხოლოდ სახელწოდებებია განსხვავებული", "Transition ავტომატურია, Animation კი ხელით ირთვება", "Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animation არის კონკრეტული ობიექტების მოძრაობის ეფექტი სლაიდის შიგნით", "Transition ხმოვანი ეფექტია, Animation კი ვიზუალური", "Transition გამოიყენება ობიექტებზე, Animation კი სლაიდებზე"]'::jsonb, 'Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animation არის კონკრეტული ობიექტების მოძრაობის ეფექტი სლაიდის შიგნით', 'Düzgün cavab: C) Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animat', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e302cd1e-c3fb-4825-a9c4-d5e85e01904c', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Bulud saxlama xidmətlərində sənəd üzərində işləyərkən əvvəlki dəyişikliklərə qayıtmaq üçün hansı funksiyadan istifadə olunur?', 'multiple_choice', '["Activity Log (Fəaliyyət jurnalı)", "Version History (Versiya tarixçəsi)", "File Recovery (Fayl bərpası)", "Sync History (Sinxronizasiya tarixçəsi)", "Backup and Restore (Ehtiyat nüsxə)"]'::jsonb, 'Version History (Versiya tarixçəsi)', 'Düzgün cavab: B) Version History (Versiya tarixçəsi)', '', 59, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3d3a8609-bbb7-498a-b37c-a69a3caaa823', 'e302cd1e-c3fb-4825-a9c4-d5e85e01904c', 'ka', 'ღრუბლოვან საცავებში წინა ცვლილებებზე დასაბრუნებლად რომელი ფუნქცია გამოიყენება?', '["Activity Log - აქტივობის ჟურნალი", "Version History (ვერსიების ისტორია) - File > Info > Version History ან ისტორია OneDrive/SharePoint-ში", "File Recovery - ფაილის აღდგენის ინსტრუმენტი", "Sync History - სინქრონიზაციის ისტორია", "Backup and Restore - სარეზერვო ასლის შექმნისა და აღდგენის ინსტრუმენტი"]'::jsonb, 'Version History (ვერსიების ისტორია) - File > Info > Version History ან ისტორია OneDrive/SharePoint-ში', 'Düzgün cavab: B) Version History (ვერსიების ისტორია) - File > Info > Version History ან ისტორია O', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('daac3074-ff26-484f-81c3-87729c2ef673', '65d87ab5-7551-4ad4-b0be-07ea9060ee9d', 'Süni intellekt əsaslı generativ modellərdə ''Hallüsinasiya'' riski nəyi ifadə edir?', 'multiple_choice', '["Modelin real faktlara əsaslanmayan, uydurma məlumatları çox inandırıcı və qətiyyətli tərzdə təqdim etməsini", "Modelin istifadəçi sorğusunu başa düşmədən təsadüfi cavab verməsini", "Modelin kompüterin resurslarını həddindən artıq yükləməsini", "Modelin cavab verməkdən imtina etməsini və xəta qaytarmasını", "Modelin yalnız ingilis dilində cavab verib digər dilləri dəstəkləməməsini"]'::jsonb, 'Modelin real faktlara əsaslanmayan, uydurma məlumatları çox inandırıcı və qətiyyətli tərzdə təqdim etməsini', 'Düzgün cavab: A) Modelin real faktlara əsaslanmayan, uydurma məlumatları çox inandırıcı və qətiyy', '', 60, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cd63f561-9cb3-4db6-9d23-34bb48d975cc', 'daac3074-ff26-484f-81c3-87729c2ef673', 'ka', 'ხელოვნურ ინტელექტში რას გამოხატავს „ჰალუცინაციის“ რისკი?', '["მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ციტატებისა თუ წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით", "მოდელის მიერ პასუხის გაცემაზე უარის თქმასა და შეცდომის დაბრუნებას", "მოდელის მიერ კომპიუტერის რესურსების გადაჭარბებულ დატვირთვას", "მოდელის მიერ პასუხის მხოლოდ ინგლისურ ენაზე გაცემას და სხვა ენების მხარდაჭერის არქონას", "მოდელის მიერ მომხმარებლის მოთხოვნის გაუგებრობის გამო შემთხვევითი პასუხის გაცემას"]'::jsonb, 'მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ციტატებისა თუ წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით', 'Düzgün cavab: A) მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ციტატების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bb58a827-47d0-4b45-9ae0-55139786a8bf', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Məktəb təbiət fənləri (kimya, fizika, biologiya) laboratoriyasında laborantın əsas vəzifə funksiyası hansıdır?', 'multiple_choice', '["Tədris proqramına uyğun olaraq şagirdlərin laboratoriya dəftərlərini yoxlamaq, təcrübə nəticələrini qiymətləndirmək və elektron jurnalda qeydiyyat aparmaq", "Fənn müəllimləri ilə birlikdə illik iş planının icrasını əlaqələndirmək, laboratoriya avadanlığının uçot jurnalını aparmaq və təhlükəsizlik təlimatlarının yerinə yetirilməsinə nəzarət etmək", "Məktəbin təsərrüfat işlərinə rəhbərlik etmək, inventarların satın alınması üçün sifarişlər hazırlamaq və anbar qalığının aylıq hesabatını təqdim etmək", "Dərs cədvəlinə uyğun laboratoriya və təcrübə məşğələlərinin cihaz, qab və reaktivlərini hazırlamaq, texniki sazlığı təmin etmək və müəllimə texniki dəstək göstərmək", "Laboratoriya avadanlıqlarının kalibrlənməsi üçün xarici servislə yazışmaları aparmaq və müəllimlərin dərs bölgüsünü təşkil etmək"]'::jsonb, 'Dərs cədvəlinə uyğun laboratoriya və təcrübə məşğələlərinin cihaz, qab və reaktivlərini hazırlamaq, texniki sazlığı təmin etmək və müəllimə texniki dəstək göstərmək', 'Düzgün cavab: D) Dərs cədvəlinə uyğun laboratoriya və təcrübə məşğələlərinin cihaz, qab və reakti', '', 1, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e7236e39-2675-4187-936f-85fae58c5dbe', 'bb58a827-47d0-4b45-9ae0-55139786a8bf', 'ka', 'რა არის სასკოლო საბუნებისმეტყველო მეცნიერებათა (ქიმია, ფიზიკა, ბიოლოგია) ლაბორატორიაში ლაბორანტის ძირითადი ფუნქციური მოვალეობა?', '["სკოლის სამეურნეო საქმიანობის ხელმძღვანელობა, ინვენტარის შესყიდვის შეკვეთების მომზადება და სასაწყობო ნაშთის ყოველთვიური ანგარიშის წარდგენა", "ლაბორატორიული აღჭურვილობის დაკალიბრების მიზნით გარე მომსახურების სამსახურთან მიმოწერის წარმოება და მასწავლებელთა საგაკვეთილო საათების განაწილების ორგანიზება", "საგნის მასწავლებლებთან ერთად წლიური სამუშაო გეგმის შესრულების კოორდინირება, ლაბორატორიული აღჭურვილობის აღრიცხვის ჟურნალის წარმოება და უსაფრთხოების ინსტრუქციების შესრულებაზე კონტროლი", "ცხრილის შესაბამისად ლაბორატორიული და პრაქტიკული მეცადინეობებისთვის ხელსაწყოების, ჭურჭლისა და რეაქტივების მომზადება, მათი ტექნიკური გამართულობის უზრუნველყოფა და მასწავლებლისთვის ტექნიკური მხარდაჭერის გაწევა", "სასწავლო პროგრამის შესაბამისად მოსწავლეთა ლაბორატორიული რვეულების შემოწმება, ექსპერიმენტის შედეგების შეფასება და ელექტრონულ ჟურნალში აღრიცხვა"]'::jsonb, 'ცხრილის შესაბამისად ლაბორატორიული და პრაქტიკული მეცადინეობებისთვის ხელსაწყოების, ჭურჭლისა და რეაქტივების მომზადება, მათი ტექნიკური გამართულობის უზრუნველყოფა და მასწავლებლისთვის ტექნიკური მხარდაჭერის გაწევა', 'Düzgün cavab: D) ცხრილის შესაბამისად ლაბორატორიული და პრაქტიკული მეცადინეობებისთვის ხელსაწყოების,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('df662c18-4c13-4b85-89aa-ed3a0f69de3d', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Kimya laboratoriyasında qatı sulfat turşusunu (H₂SO₄) su ilə durulaşdırarkən hansı əsas təhlükəsizlik qaydasına riayət olunmalıdır?', 'multiple_choice', '["Hər iki mayeni bərabər həcmdə ölçüb eyni anda soyuq suya davamlı qarışdırmaqla əlavə etmək və termometr ilə nəzarət etmək", "Qatı turşunu əvvəlcə 50% nisbətində durulaşdırıb, sonra qalan suyu birbaşa əlavə edərək eksotermik reaksiyanı sürətləndirmək", "Qatı turşunu nazik şırnaqla, şüşə çubuqla daimi qarışdırmaqla, soyudaraq tədricən suyun üzərinə əlavə etmək", "Suyu nazik şırnaqla turşunun üzərinə əlavə edərkən qarışığı su hamamında 60°C-yə qədər qızdırmaq", "Turşu və suyu çini qabda qarışdırıb, qarışdırma zamanı qoruyucu əlcək və eynəkdən istifadə edərək çalxalamaq"]'::jsonb, 'Qatı turşunu nazik şırnaqla, şüşə çubuqla daimi qarışdırmaqla, soyudaraq tədricən suyun üzərinə əlavə etmək', 'Düzgün cavab: C) Qatı turşunu nazik şırnaqla, şüşə çubuqla daimi qarışdırmaqla, soyudaraq tədricə', '', 2, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f64e0221-c0bf-458f-8777-44a5d3c6264b', 'df662c18-4c13-4b85-89aa-ed3a0f69de3d', 'ka', 'ქიმიის ლაბორატორიაში კონცენტრირებული გოგირდმჟავას (H₂SO₄) წყლით გაზავებისას უსაფრთხოების რომელი ძირითადი წესი უნდა იყოს დაცული?', '["ორივე სითხის თანაბარი მოცულობით გაზომვა და ერთდროულად შერევა უწყვეტი მორევითა და თერმომეტრით კონტროლით", "მჟავასა და წყლის ფაიფურის ჭურჭელში შერევა დამცავი ხელთათმანებისა და სათვალის გამოყენებით ჭურჭლის შენჯღრევით", "კონცენტრირებული მჟავას წვრილი ნაკადით, მინის წკირით უწყვეტი მორევის პირობებში და გაციებით, თანდათანობით წყალზე დამატება", "კონცენტრირებული მჟავას ჯერ 50%-იანი თანაფარდობით გაზავება და შემდეგ დარჩენილი წყლის პირდაპირ დამატება ეგზოთერმული რეაქციის დასაჩქარებლად", "წყლის წვრილი ნაკადით მჟავაზე დამატება ნარევის წყლის აბაზანაში 60°C-მდე გაცხელებით"]'::jsonb, 'კონცენტრირებული მჟავას წვრილი ნაკადით, მინის წკირით უწყვეტი მორევის პირობებში და გაციებით, თანდათანობით წყალზე დამატება', 'Düzgün cavab: C) კონცენტრირებული მჟავას წვრილი ნაკადით, მინის წკირით უწყვეტი მორევის პირობებში და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('736375c3-4476-467c-9d22-cf9d5b2cddd1', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada dərinin qatı turşu ilə yanması (kimyəvi yanıq) zamanı göstərilməli olan düzgün ilkin yardım hansıdır?', 'multiple_choice', '["Dərini dərhal quru tamponla silib, 3%-li hidrogen peroksid və sonra borat turşusu ilə yuyub sarğı etmək", "Dərini 10–15 dəqiqə bol axar su ilə yumaq, sonra 2%-li natrium-hidrokarbonat məhlulu ilə tampon etmək və steril sarğı qoymaq", "Dərini bol su ilə yuyub, 10%-li ammonyak məhlulu ilə tampon edib, sonra pambıq-tənzif kompresi qoymaq", "Zədələnmiş nahiyəni 5 dəqiqə axar su ilə yuyub, sonra 5%-li sirkə turşusu məhlulu ilə neytrallaşdırıb yağlı məlhəm çəkmək", "Yanmış sahəni 20 dəqiqə soyuq su ilə yuyub, sonra 2%-li kalium-permanqanat məhlulu ilə dezinfeksiya edib açıq saxlamaq"]'::jsonb, 'Dərini 10–15 dəqiqə bol axar su ilə yumaq, sonra 2%-li natrium-hidrokarbonat məhlulu ilə tampon etmək və steril sarğı qoymaq', 'Düzgün cavab: B) Dərini 10–15 dəqiqə bol axar su ilə yumaq, sonra 2%-li natrium-hidrokarbonat məh', '', 3, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('03b598aa-f7c8-4441-840f-3cf0d6ae65c9', '736375c3-4476-467c-9d22-cf9d5b2cddd1', 'ka', 'ლაბორატორიაში კონცენტრირებული მჟავით კანის დამწვრობის (ქიმიური დამწვრობის) დროს როგორია სწორი პირველადი დახმარება?', '["დამწვარი ადგილის 20 წუთის განმავლობაში ცივი წყლით დაბანა, შემდეგ კალიუმის პერმანგანატის 2%-იანი ხსნარით დეზინფექცია და ღიად დატოვება", "კანის 10–15 წუთის განმავლობაში გამდინარე წყლის უხვი ჭავლით ჩამორეცხვა, შემდეგ ნატრიუმის ჰიდროკარბონატის (სოდის) 2%-იანი ხსნარით დამუშავება და სტერილური ნახვევის დადება", "დაზიანებული უბნის 5 წუთის განმავლობაში გამდინარე წყლით დაბანა, შემდეგ ძმარმჟავას 5%-იანი ხსნარით განეიტრალება და ცხიმოვანი მალამოს წასმა", "კანის უხვი წყლით დაბანა, ამიაკის 10%-იანი ხსნარით დამუშავება და შემდეგ ბამბა-დოლბანდის კომპრესის დადება", "კანის დაუყოვნებლივ გამშრალება მშრალი ტამპონით, წყალბადის ზეჟანგის 3%-იანი ხსნარითა და შემდეგ ბორის მჟავით ჩამორეცხვა და შეხვევა"]'::jsonb, 'კანის 10–15 წუთის განმავლობაში გამდინარე წყლის უხვი ჭავლით ჩამორეცხვა, შემდეგ ნატრიუმის ჰიდროკარბონატის (სოდის) 2%-იანი ხსნარით დამუშავება და სტერილური ნახვევის დადება', 'Düzgün cavab: B) კანის 10–15 წუთის განმავლობაში გამდინარე წყლის უხვი ჭავლით ჩამორეცხვა, შემდეგ ნა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e71a902e-e560-41ea-b21c-a669da1880c9', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada təcrübə zamanı kəskin iyli zəhərli qazların tənəffüs yollarına getməsi nəticəsində zəhərlənmə baş verdikdə ilk növbədə hansı təxirəsalınmaz tədbir görülməlidir?', 'multiple_choice', '["Zərərçəkənə kəskin qoxulu efir iylətmək və qapalı otaqda süni tənəffüs vermək", "Zərərçəkəni laboratoriyadan çıxarmadan yerində uzatmaq, sinəsinə soyuq kompres qoymaq və 10%-li qlükoza məhlulu vermək", "Zərərçəkənin üzünü bol su ilə yuyub, antihistamin preparat verərək köməkçi otaqda dincəlməyə qoymaq", "Zərərçəkənə dərhal aktivləşdirilmiş kömür tozu içirtmək və pəncərəni yarımçıq açaraq təcrübəyə davam etmək", "Zərərçəkəni dərhal təmiz havaya çıxarmaq, yaxasını açıb rahat nəfəs almasını təmin etmək, sakit vəziyyətdə uzatmaq və dərhal tibbi yardım çağırmaq"]'::jsonb, 'Zərərçəkəni dərhal təmiz havaya çıxarmaq, yaxasını açıb rahat nəfəs almasını təmin etmək, sakit vəziyyətdə uzatmaq və dərhal tibbi yardım çağırmaq', 'Düzgün cavab: E) Zərərçəkəni dərhal təmiz havaya çıxarmaq, yaxasını açıb rahat nəfəs almasını təm', '', 4, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b358acf2-4549-4f1c-9438-f8d107d4c3e9', 'e71a902e-e560-41ea-b21c-a669da1880c9', 'ka', 'ლაბორატორიაში ექსპერიმენტის დროს სასუნთქ გზებში მძაფრსუნიანი ტოქსიკური აირების მოხვედრით გამოწვეული მოწამვლისას, რა გადაუდებელი ღონისძიება უნდა გატარდეს პირველ რიგში?', '["დაზარალებულისთვის სახის უხვი წყლით დაბანა, ანტიჰისტამინური პრეპარატის მიცემა და დამხმარე ოთახში დასასვენებლად დატოვება", "დაზარალებულის ლაბორატორიიდან გაუყვანებლად ადგილზე დაწვენა, მკერდზე ცივი კომპრესის დადება და გლუკოზის 10%-იანი ხსნარის მიცემა", "დაზარალებულისთვის დაუყოვნებლივ ნიშადურის სპირტის ორთქლის შესუნთქება, შემდეგ ცხელი ჩაის მიცემა და 30 წუთის განმავლობაში მეთვალყურეობის ქვეშ დატოვება", "დაზარალებულის გამწოვი კარადის წინ დასმა, სახეზე სოდის 2%-იანი ხსნარით დასველებული დოლბანდის აფარება და ფანჯრების დახურვა", "დაზარალებულის დაუყოვნებლივ გაყვანა სუფთა ჰაერზე, ტანსაცმლის საყელოს შეხსნა თავისუფალი სუნთქვის უზრუნველსაყოფად, საჭიროების შემთხვევაში ჟანგბადის მიწოდება და სასწრაფო სამედიცინო დახმარების გამოძახება"]'::jsonb, 'დაზარალებულის დაუყოვნებლივ გაყვანა სუფთა ჰაერზე, ტანსაცმლის საყელოს შეხსნა თავისუფალი სუნთქვის უზრუნველსაყოფად, საჭიროების შემთხვევაში ჟანგბადის მიწოდება და სასწრაფო სამედიცინო დახმარების გამოძახება', 'Düzgün cavab: E) დაზარალებულის დაუყოვნებლივ გაყვანა სუფთა ჰაერზე, ტანსაცმლის საყელოს შეხსნა თავის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('adf1162f-2bff-4b89-921a-b84650c81026', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Kimya laboratoriyasında zəhərli, kəskin iyli və ya boğucu qazların ayrılması ilə müşayiət olunan reaksiyalar harada aparılmalıdır?', 'multiple_choice', '["Köməkçi hazırlıq otağında, qapısı bağlı vəziyyətdə və fərdi əleyhqaz maskası taxılaraq", "Xüsusi ayrılmış nümayiş otağında, ümumi havalandırma 50% rejimində işləyərkən", "Laboratoriyanın mərkəzi masasında, əlavə portativ ventilyator quraşdırılaraq və pəncərələr açıq saxlanılmaqla", "Ventilyasiya sistemi tam işlək vəziyyətdə olan xüsusi sorucu şkafın daxilində, qoruyucu şüşə endirilmiş vəziyyətdə", "Müəllim masasında, şagirdlərdən 1 metr məsafədə və nümayiş üçün şəffaf qoruyucu ekran arxasında"]'::jsonb, 'Ventilyasiya sistemi tam işlək vəziyyətdə olan xüsusi sorucu şkafın daxilində, qoruyucu şüşə endirilmiş vəziyyətdə', 'Düzgün cavab: D) Ventilyasiya sistemi tam işlək vəziyyətdə olan xüsusi sorucu şkafın daxilində, q', '', 5, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d6c563a3-fa1c-4325-b287-4cf4a4ea3e30', 'adf1162f-2bff-4b89-921a-b84650c81026', 'ka', 'სად უნდა ჩატარდეს ლაბორატორიაში ქიმიური რეაქციები, რომლებსაც თან ახლავს ტოქსიკური, მძაფრსუნიანი და აქროლადი აირების გამოყოფა?', '["სპეციალურად გამოყოფილ სადემონსტრაციო ოთახში, საერთო ვენტილაციის 50%-იან რეჟიმში მუშაობისას", "მასწავლებლის მაგიდაზე, მოსწავლეებისგან 1 მეტრის დაშორებით და სადემონსტრაციო გამჭვირვალე დამცავი ეკრანის მიღმა", "ლაბორატორიის ცენტრალურ მაგიდაზე, დამატებითი პორტატიული ვენტილატორის დამონტაჟებითა და ღია ფანჯრების პირობებში", "სპეციალურ გამწოვ კარადაში, სრულად გამართული სავენტილაციო სისტემითა და დაწეული დამცავი მინით", "დამხმარე მოსამზადებელ ოთახში, დახურული კარითა და ინდივიდუალური აირწინაღის გამოყენებით"]'::jsonb, 'სპეციალურ გამწოვ კარადაში, სრულად გამართული სავენტილაციო სისტემითა და დაწეული დამცავი მინით', 'Düzgün cavab: D) სპეციალურ გამწოვ კარადაში, სრულად გამართული სავენტილაციო სისტემითა და დაწეული და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d56d68c0-426b-4a6f-9f35-5acd96b2b0b7', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Məktəb laboratoriyasında tezalışan mayelərin (TAM — spirt, aseton, efir, benzin) saxlanması və istifadəsi üzrə hansı qayda **YANLIŞDIR?**', 'multiple_choice', '["TAM ilə işləyərkən rezin əlcəkdən istifadə məcburi deyil, yalnız eynək kifayətdir", "Tezalışan mayelər birbaşa yanan açıq alovun və ya qızdırıcı elektrik cihazlarının yanında saxlanıla bilər", "TAM olan şüşə qabların metal rəfdə birbaşa günəş işığı altında saxlanması, əgər qapaqları hermetikdirsə", "TAM qalıqları az miqdarda olduqda (100 ml-dən az) laboratoriya çanağına su ilə durulaşdırılaraq axıdılması", "Tezalışan mayelər laboratoriyada açıq şəkildə 5 litrdən artıq saxlanıla bilər, əgər otaq 2 saatdan bir havalandırılırsa"]'::jsonb, 'Tezalışan mayelər birbaşa yanan açıq alovun və ya qızdırıcı elektrik cihazlarının yanında saxlanıla bilər', 'Düzgün cavab: B) Tezalışan mayelər birbaşa yanan açıq alovun və ya qızdırıcı elektrik cihazlarını', '', 6, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('287e6756-b0d5-4d4a-9586-5fe955b23f7d', 'd56d68c0-426b-4a6f-9f35-5acd96b2b0b7', 'ka', 'რომელი წესია მცდარი სასკოლო ლაბორატორიაში ადვილად აალებადი სითხეების (სპირტი, აცეტონი, ეთერი, ბენზინი) შენახვისა და გამოყენების შესახებ?', '["ადვილად აალებად სითხეებთან მუშაობისას რეზინის ხელთათმანების გამოყენება სავალდებულო არ არის, საკმარისია მხოლოდ სათვალე", "ადვილად აალებადი სითხეები შეიძლება ინახებოდეს უშუალოდ ღია ცეცხლთან ან გამათბობელ ელექტრომოწყობილობებთან ახლოს", "ადვილად აალებადი სითხეები ლაბორატორიაში ღია სახით შეიძლება ინახებოდეს 5 ლიტრზე მეტი ოდენობით, თუ ოთახი 2 საათში ერთხელ ნიავდება", "ადვილად აალებადი სითხეების ნარჩენების მცირე ოდენობით (100 მლ-ზე ნაკლები) ლაბორატორიის ნიჟარაში წყლით გაზავებით ჩაღვრა", "ადვილად აალებადი სითხეებიანი მინის ჭურჭლის ლითონის თაროზე პირდაპირი მზის სხივების ქვეშ შენახვა, თუკი მათი თავსახურები ჰერმეტულია"]'::jsonb, 'ადვილად აალებადი სითხეები შეიძლება ინახებოდეს უშუალოდ ღია ცეცხლთან ან გამათბობელ ელექტრომოწყობილობებთან ახლოს', 'Düzgün cavab: B) ადვილად აალებადი სითხეები შეიძლება ინახებოდეს უშუალოდ ღია ცეცხლთან ან გამათბობელ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('03589231-c520-426d-a26f-97cf7f8b3a57', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada kimyəvi maddələrin saxlandığı qabların üzərində hansı məlumatların olması məcburidir?', 'multiple_choice', '["Maddənin dəqiq adı, kimyəvi formulu, qatılığı, istehsal/tarix, təhlükə sinfi və müvafiq GHS xəbərdarlıq nişanı", "Maddənin laboratoriyaya daxil olma tarixi, son istifadə tarixi və tədarükçü şirkətin loqotipi", "Maddənin CAS nömrəsi, miqdarı, alınma mənbəyi və məktəbin inventar nömrəsi", "Maddənin istifadə təyinatı, sinfi, qrup nömrəsi və müəllimin fənn kodu", "Maddənin beynəlxalq ticarət adı, istehsalçı ölkə, saxlanma temperaturu və laboratoriya rəhbərinin imzası"]'::jsonb, 'Maddənin dəqiq adı, kimyəvi formulu, qatılığı, istehsal/tarix, təhlükə sinfi və müvafiq GHS xəbərdarlıq nişanı', 'Düzgün cavab: A) Maddənin dəqiq adı, kimyəvi formulu, qatılığı, istehsal/tarix, təhlükə sinfi və', '', 7, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('07e0c7fb-1208-4726-b683-5e19f1d68321', '03589231-c520-426d-a26f-97cf7f8b3a57', 'ka', 'რა ინფორმაციის არსებობაა სავალდებულო ჭურჭელზე, რომელშიც ლაბორატორიაში ქიმიური ნივთიერებები ინახება?', '["ნივთიერების ზუსტი სახელწოდება, ქიმიური ფორმულა, კონცენტრაცია, დამზადების თარიღი, საფრთხის კლასი და შესაბამისი GHS გამაფრთხილებელი ნიშანი", "ნივთიერების CAS ნომერი, რაოდენობა, მიღების წყარო და სკოლის საინვენტარო ნომერი", "ნივთიერების ლაბორატორიაში მიღების თარიღი, ვარგისიანობის ვადა და მომწოდებელი კომპანიის ლოგოტიპი", "ნივთიერების საერთაშორისო სავაჭრო სახელწოდება, მწარმოებელი ქვეყანა, შენახვის ტემპერატურა და ლაბორატორიის ხელმძღვანელის ხელმოწერა", "ნივთიერების გამოყენების დანიშნულება, კლასი, ჯგუფის ნომერი და მასწავლებლის საგნის კოდი"]'::jsonb, 'ნივთიერების ზუსტი სახელწოდება, ქიმიური ფორმულა, კონცენტრაცია, დამზადების თარიღი, საფრთხის კლასი და შესაბამისი GHS გამაფრთხილებელი ნიშანი', 'Düzgün cavab: A) ნივთიერების ზუსტი სახელწოდება, ქიმიური ფორმულა, კონცენტრაცია, დამზადების თარიღი,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f7678792-89d3-49c8-81cc-441b1ff8c803', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Kimya laboratoriyasında mayelərin dəqiq həcmini ölçmək və titrləmə proseslərini aparmaq üçün hansı şüşə qablardan istifadə olunur?', 'multiple_choice', '["Bünzen kolbası, defleqmator və soyuducu", "Ölçü silindri, kimyəvi stəkan və yastıdibli kolba", "Bürət, pipet (Mor və ya avtomatik) və dəqiq ölçülü ölçü kolbaları", "Menzurka, sınaq şüşəsi və kristallizator", "Qıf, damcıladıcı və saat şüşəsi"]'::jsonb, 'Bürət, pipet (Mor və ya avtomatik) və dəqiq ölçülü ölçü kolbaları', 'Düzgün cavab: C) Bürət, pipet (Mor və ya avtomatik) və dəqiq ölçülü ölçü kolbaları', '', 8, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f0790d28-20dd-47ee-89de-e2dc56edfa49', 'f7678792-89d3-49c8-81cc-441b1ff8c803', 'ka', 'რომელი მინის ჭურჭელი გამოიყენება ქიმიის ლაბორატორიაში სითხეების ზუსტი მოცულობის გასაზომად და ტიტრაციის პროცესის ჩასატარებლად?', '["ძაბრი, საწვეთური და საათის მინა", "საზომი ცილინდრი, ქიმიური ჭიქა და ბრტყელძირა კოლბა", "ბიურეტი, პიპეტი (მორის ან ავტომატური) და ზუსტი მოცულობის საზომი კოლბები", "მენზურა, სინჯარა და კრისტალიზატორი", "ბუნზენის კოლბა, დეფლეგმატორი და მაცივარი"]'::jsonb, 'ბიურეტი, პიპეტი (მორის ან ავტომატური) და ზუსტი მოცულობის საზომი კოლბები', 'Düzgün cavab: C) ბიურეტი, პიპეტი (მორის ან ავტომატური) და ზუსტი მოცულობის საზომი კოლბები', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9627f23d-27c1-4117-95a9-b87ea5f6eba7', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Bərk kimyəvi maddələrin xırdalanması, üyüdülməsi və toz halına salınması üçün hansı laboratoriya avadanlığından istifadə edilir?', 'multiple_choice', '["Çini buxarlandırma kasası və şpatel", "Çini havan və havan dəstəsi (dəstək)", "Elektrikli qarışdırıcı və maqnit qarışdırıcı", "Məsaməli çini süzgəc və Bünzen kolbası", "Metal maşa və laboratoriya kəlbətini"]'::jsonb, 'Çini havan və havan dəstəsi (dəstək)', 'Düzgün cavab: B) Çini havan və havan dəstəsi (dəstək)', '', 9, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2a9fa2c2-7d6a-4705-95c7-24fae3650232', '9627f23d-27c1-4117-95a9-b87ea5f6eba7', 'ka', 'რომელი ლაბორატორიული ინვენტარი გამოიყენება მყარი ქიმიური ნივთიერებების დასაქუცმაცებლად, დასაფქვავად და ფხვნილისებრ მდგომარეობამდე მისაყვანად?', '["ფოროვანი ფაიფურის ფილტრი და ბუნზენის კოლბა", "ფაიფურის როდინი და როდინდამყოლი (ფილთაქვა)", "ლითონის მაშა და ლაბორატორიული მარწუხი", "ელექტრონული და მაგნიტური შემრევი", "ფაიფურის ასაორთქლებელი ჯამი და შპატელი"]'::jsonb, 'ფაიფურის როდინი და როდინდამყოლი (ფილთაქვა)', 'Düzgün cavab: B) ფაიფურის როდინი და როდინდამყოლი (ფილთაქვა)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3b6c76ae-d729-41fd-9a81-ed908ee1a440', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada qızdırma prosesi zamanı içərisində maye olan sınaq şüşəsini alovda tutarkən onun açıq ağzı hansı tərəfə yönəldilməlidir?', 'multiple_choice', '["Masa üzərindəki keramik plitə istiqamətinə, 45 dərəcə bucaq altında", "Sorucu şkafın daxili divarına doğru, şüşə bir qədər maili tutulmaqla", "Təcrübə aparanın və ya digər insanların olmadığı boş və təhlükəsiz tərəfə, divara doğru", "Ştativin metal dayağına doğru, sıçrama zamanı metal səthə dəyməsi üçün", "Pəncərə şüşəsinə doğru, ventilyasiya axınına perpendikulyar istiqamətdə"]'::jsonb, 'Təcrübə aparanın və ya digər insanların olmadığı boş və təhlükəsiz tərəfə, divara doğru', 'Düzgün cavab: C) Təcrübə aparanın və ya digər insanların olmadığı boş və təhlükəsiz tərəfə, divar', '', 10, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4c4d697f-d9d9-4be5-ab66-eca62c26230c', '3b6c76ae-d729-41fd-9a81-ed908ee1a440', 'ka', 'ლაბორატორიაში გაცხელების პროცესში სითხიანი სინჯარის ცეცხლზე დაჭერისას, საით უნდა იყოს მიმართული მისი ღია პირი?', '["შტატივის ლითონის სადგამისკენ, რათა შხეფები ლითონის ზედაპირს მოხვდეს", "მაგიდაზე არსებული კერამიკული ფილის მიმართულებით, 45 გრადუსიანი კუთხით", "ცარიელი და უსაფრთხო მიმართულებით, კედლისკენ, სადაც არ იმყოფება ექსპერიმენტის ჩამტარებელი ან სხვა ადამიანი", "გამწოვი კარადის შიდა კედლისკენ, სინჯარის ოდნავ დახრილად დაჭერით", "ფანჯრის მინისკენ, სავენტილაციო ნაკადის პერპენდიკულარული მიმართულებით"]'::jsonb, 'ცარიელი და უსაფრთხო მიმართულებით, კედლისკენ, სადაც არ იმყოფება ექსპერიმენტის ჩამტარებელი ან სხვა ადამიანი', 'Düzgün cavab: C) ცარიელი და უსაფრთხო მიმართულებით, კედლისკენ, სადაც არ იმყოფება ექსპერიმენტის ჩამ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('522030d8-58d4-49c5-8ded-cc203be9922d', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada civəli termometr sındıqda və ətrafa civə dağıldıqda görülməli olan təxirəsalınmaz zərərsizləşdirmə prosesi necə adlanır və necə icra olunur?', 'multiple_choice', '["Dezinfeksiya — civənin kalsium-xlorid ilə örtülməsi və qapalı qabda saxlanması", "Demerkurizasiya — civə qalıqlarının mexaniki toplanması, xırdalanmış kükürd tozu və ya KMnO₄ məhlulu ilə zərərsizləşdirilməsi və otağın havalandırılması", "Deaktivasiya — civənin su ilə yuyulub kanalizasiyaya axıdılması və otağın xlorlu su ilə silinməsi", "Dekontaminasiya — civə damcılarının tozsoranla toplanması və spirtlə silinməsi", "Dezinseksiya — civənin üzərinə sirkə turşusu tökülərək buxarlandırılması və pəncərələrin bağlanması"]'::jsonb, 'Demerkurizasiya — civə qalıqlarının mexaniki toplanması, xırdalanmış kükürd tozu və ya KMnO₄ məhlulu ilə zərərsizləşdirilməsi və otağın havalandırılması', 'Düzgün cavab: B) Demerkurizasiya — civə qalıqlarının mexaniki toplanması, xırdalanmış kükürd tozu', '', 11, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bcb480d8-4d6b-4104-9fd2-eafd79ffc57c', '522030d8-58d4-49c5-8ded-cc203be9922d', 'ka', 'რა ეწოდება და როგორ სრულდება გადაუდებელი გაუვნებელყოფის პროცესი, როდესაც ლაბორატორიაში ვერცხლისწყლიანი თერმომეტრი ტყდება და გარშემო ვერცხლისწყალი იღვრება?', '["დეაქტივაცია — ვერცხლისწყლის წყლით ჩარეცხვა კანალიზაციაში და ოთახის ქლორიანი წყლით მოწმენდა", "დემერკურიზაცია — ვერცხლისწყლის ნარჩენების მექანიკური შეგროვება, დაფხვნილი გოგირდის ფხვნილით ან KMnO4-ის ხსნარით გაუვნებელყოფა და ოთახის განიავება", "დეკონტამინაცია — ვერცხლისწყლის წვეთების მტვერსასრუტით შეგროვება და სპირტით გაწმენდა", "დეზინსექცია — ვერცხლისწყალზე ძმარმჟავას დასხმა აორთქლების მიზნით და ფანჯრების დახურვა", "დეზინფექცია — ვერცხლისწყლის დაფარვა კალციუმის ქლორიდით და ჰერმეტულ ჭურჭელში შენახვა"]'::jsonb, 'დემერკურიზაცია — ვერცხლისწყლის ნარჩენების მექანიკური შეგროვება, დაფხვნილი გოგირდის ფხვნილით ან KMnO4-ის ხსნარით გაუვნებელყოფა და ოთახის განიავება', 'Düzgün cavab: B) დემერკურიზაცია — ვერცხლისწყლის ნარჩენების მექანიკური შეგროვება, დაფხვნილი გოგირდ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1a48b8ca-8e03-43ba-8dc2-e47c0d8b50d0', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Biologiya laboratoriyasında müvəqqəti və daimi mikropreparatların hazırlanması üçün istifadə edilən alt və üst şüşələr necə adlanır?', 'multiple_choice', '["Daşıyıcı şüşə və qoruyucu şüşə", "Altlıq şüşəsi və mikrometr şüşəsi", "Substrat şüşəsi və preparat şüşəsi", "Baza şüşəsi və lamel şüşəsi", "Əşya şüşəsi (alt, qalın) və örtük şüşəsi (üst, nazik, 0.17 mm)"]'::jsonb, 'Əşya şüşəsi (alt, qalın) və örtük şüşəsi (üst, nazik, 0.17 mm)', 'Düzgün cavab: E) Əşya şüşəsi (alt, qalın) və örtük şüşəsi (üst, nazik, 0.17 mm)', '', 12, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('dbaa5856-3f3c-48f5-8336-ff9052bf91f1', '1a48b8ca-8e03-43ba-8dc2-e47c0d8b50d0', 'ka', 'რა ეწოდება ქვედა და ზედა მინებს, რომლებიც ბიოლოგიის ლაბორატორიაში დროებითი და მუდმივი მიკროპრეპარატების მოსამზადებლად გამოიყენება?', '["საბაზისო მინა და ლამელის მინა", "სადგამი მინა და მიკრომეტრული მინა", "მატარებელი მინა და დამცავი მინა", "სუბსტრატის მინა და პრეპარატის მინა", "საგნობრივი მინა (ქვედა, სქელი) და საფარი მინა (ზედა, თხელი, 0.17 მმ)"]'::jsonb, 'საგნობრივი მინა (ქვედა, სქელი) და საფარი მინა (ზედა, თხელი, 0.17 მმ)', 'Düzgün cavab: E) საგნობრივი მინა (ქვედა, სქელი) და საფარი მინა (ზედა, თხელი, 0.17 მმ)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('345e3ed8-e14f-49fb-b940-af46f3baa693', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Fizika laboratoriyasında elektrik dövrəsini yığarkən dövrəyə cərəyan mənbəyindən gərginlik nə vaxt verilməlidir?', 'multiple_choice', '["Ampermetr qoşulduqdan sonra, voltmetr qoşulmamışdan əvvəl", "Şagirdlər yerlərini tutduqdan sonra, müəllim izahat verərkən", "Dövrənin əsas elementləri birləşdirildikdən sonra, reostat yoxlanılmadan əvvəl", "Naqillər masaya düzüldükdən dərhal sonra, açar qapalı vəziyyətdə olmaqla", "Yalnız dövrə tam yığıldıqdan və müəllim və ya laborant sxemin düzgünlüyünü, açarın açıq olmasını yoxladıqdan sonra"]'::jsonb, 'Yalnız dövrə tam yığıldıqdan və müəllim və ya laborant sxemin düzgünlüyünü, açarın açıq olmasını yoxladıqdan sonra', 'Düzgün cavab: E) Yalnız dövrə tam yığıldıqdan və müəllim və ya laborant sxemin düzgünlüyünü, açar', '', 13, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8e4f39cf-957a-41d1-b928-ff0194939578', '345e3ed8-e14f-49fb-b940-af46f3baa693', 'ka', 'ფიზიკის ლაბორატორიაში ელექტრული წრედის აწყობისას როდის უნდა მიეწოდოს წრედს ძაბვა დენის წყაროდან?', '["წრედის ძირითადი ელემენტების შეერთების შემდეგ, რეოსტატის შემოწმებამდე", "ამპერმეტრის ჩართვის შემდეგ, ვოლტმეტრის ჩართვამდე", "მას შემდეგ, რაც მოსწავლეები ადგილებს დაიკავებენ, მასწავლებლის მიერ ახსნის პროცესში", "გამტარების მაგიდაზე დალაგებისთანავე, ჩამრთველის ჩაკეტილ მდგომარეობაში ყოფნისას", "მხოლოდ მას შემდეგ, რაც წრედი სრულად აეწყობა და მასწავლებელი ან ლაბორანტი შეამოწმებს სქემის სისწორესა და ჩამრთველის ღია (გამორთულ) მდგომარეობას"]'::jsonb, 'მხოლოდ მას შემდეგ, რაც წრედი სრულად აეწყობა და მასწავლებელი ან ლაბორანტი შეამოწმებს სქემის სისწორესა და ჩამრთველის ღია (გამორთულ) მდგომარეობას', 'Düzgün cavab: E) მხოლოდ მას შემდეგ, რაც წრედი სრულად აეწყობა და მასწავლებელი ან ლაბორანტი შეამოწმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2ce8686f-c6ab-4b40-9d56-7204ba5386a6', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Elektrik dövrəsində cərəyan şiddətini və gərginliyi ölçən cihazlar hansılardır və dövrəyə necə qoşulurlar?', 'multiple_choice', '["Ampermetr və Voltmetr hər ikisi ardıcıl qoşulur, reostatdan əvvəl", "Ampermetr paralel, Voltmetr ardıcıl qoşulur, hər ikisi mənbəyə birbaşa", "Hər iki cihaz induktiv qoşulur, maqnit sahəsi ilə əlaqələndirilərək", "Ampermetr dövrəyə ardıcıl, Voltmetr isə ölçülən hissəyə paralel qoşulur, qütblərə diqqət edilərək", "Ampermetr mənbəyə paralel, Voltmetr dövrəyə ardıcıl qoşulur"]'::jsonb, 'Ampermetr dövrəyə ardıcıl, Voltmetr isə ölçülən hissəyə paralel qoşulur, qütblərə diqqət edilərək', 'Düzgün cavab: D) Ampermetr dövrəyə ardıcıl, Voltmetr isə ölçülən hissəyə paralel qoşulur, qütblər', '', 14, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4b51d6d4-9c50-4810-953d-9c363668c6c0', '2ce8686f-c6ab-4b40-9d56-7204ba5386a6', 'ka', 'რომელი ხელსაწყოებით იზომება დენის ძალა და ძაბვა ელექტრულ წრედში და როგორ ირთვება ისინი წრედში?', '["ამპერმეტრი ირთვება პარალელურად, ვოლტმეტრი — მიმდევრობით, ორივე პირდაპირ წყაროსთან", "ორივე ხელსაწყო ირთვება ინდუქციურად, მაგნიტურ ველთან დაკავშირებით", "ამპერმეტრი ირთვება წყაროს პარალელურად, ვოლტმეტრი — წრედში მიმდევრობით", "ამპერმეტრი წრედში ირთვება მიმდევრობით, ხოლო ვოლტმეტრი გასაზომ უბანზე პარალელურად, პოლარობის დაცვით", "ამპერმეტრი და ვოლტმეტრი ორივე ირთვება მიმდევრობით, რეოსტატამდე"]'::jsonb, 'ამპერმეტრი წრედში ირთვება მიმდევრობით, ხოლო ვოლტმეტრი გასაზომ უბანზე პარალელურად, პოლარობის დაცვით', 'Düzgün cavab: D) ამპერმეტრი წრედში ირთვება მიმდევრობით, ხოლო ვოლტმეტრი გასაზომ უბანზე პარალელურად', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0c63d266-be6e-4679-9047-19321c5d06f3', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada aktiv qələvi metalların (məsələn, Natrium və ya Kalium) saxlanma qaydası necədir?', 'multiple_choice', '["Quru qum içərisində, taxta qutuda, sərin yerdə", "Vakuum altında, metal konteynerdə, azot atmosferində", "Quru kerosin, mineral yağ və ya parafin təbəqəsi altında kip bağlı qalındivarlı şüşə qabda, oksidləşdiricilərdən uzaqda", "Etil spirti və qliserin qarışığında, soyuducuda 4°C-də", "Distillə edilmiş su altında, hava keçirməyən plastik qabda"]'::jsonb, 'Quru kerosin, mineral yağ və ya parafin təbəqəsi altında kip bağlı qalındivarlı şüşə qabda, oksidləşdiricilərdən uzaqda', 'Düzgün cavab: C) Quru kerosin, mineral yağ və ya parafin təbəqəsi altında kip bağlı qalındivarlı', '', 15, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b21c6580-9cbc-43a4-8f2e-7c1a1750cf79', '0c63d266-be6e-4679-9047-19321c5d06f3', 'ka', 'როგორია ლაბორატორიაში აქტიური ტუტე ლითონების (მაგალითად, ნატრიუმის ან კალიუმის) შენახვის წესი?', '["ეთილის სპირტისა და გლიცერინის ნარევში, მაცივარში 4°C ტემპერატურაზე", "გამოხდილი წყლის ქვეშ, ჰაერგაუმტარ პლასტმასის ჭურჭელში", "მშრალი ნავთის (კეროსინის), მინერალური ზეთის ან პარაფინის ფენის ქვეშ, მჭიდროდ დახურულ სქელკედლიან მინის ჭურჭელში, მჟანგავებისგან მოშორებით", "მშრალ ქვიშაში, ხის ყუთში, გრილ ადგილას", "ვაკუუმის ქვეშ, ლითონის კონტეინერში, აზოტის ატმოსფეროში"]'::jsonb, 'მშრალი ნავთის (კეროსინის), მინერალური ზეთის ან პარაფინის ფენის ქვეშ, მჭიდროდ დახურულ სქელკედლიან მინის ჭურჭელში, მჟანგავებისგან მოშორებით', 'Düzgün cavab: C) მშრალი ნავთის (კეროსინის), მინერალური ზეთის ან პარაფინის ფენის ქვეშ, მჭიდროდ დახ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('41d7eb3b-5049-4db6-a7f6-ee7db6b2951a', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada reaktivlərin dadına baxmaq və ya qoxusunu yoxlamaqla bağlı təhlükəsizlik qaydası nəyi tələb edir?', 'multiple_choice', '["Qoxunu təyin etmək üçün qabın ağzı 5 sm məsafədən dərindən nəfəs alınır", "Bütün reaktivlərin qoxusu pambıq üzərində yoxlanılır, dadına baxılmır", "Yalnız kristal duzların dadına baxmaq olar, mayelərin qoxusu birbaşa iylənir", "Zəif turşuların dadına baxmaq olar, əgər laboratoriya rəhbəri icazə verirsə", "Reaktivlərin dadına baxmaq qadağandır; qoxunu hiss etmək üçün qabdan çıxan havanı əllə yüngülcə buruna tərəf yellətmək lazımdır"]'::jsonb, 'Reaktivlərin dadına baxmaq qadağandır; qoxunu hiss etmək üçün qabdan çıxan havanı əllə yüngülcə buruna tərəf yellətmək lazımdır', 'Düzgün cavab: E) Reaktivlərin dadına baxmaq qadağandır; qoxunu hiss etmək üçün qabdan çıxan havan', '', 16, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b2f56116-233e-49f9-964c-9e00916a32ca', '41d7eb3b-5049-4db6-a7f6-ee7db6b2951a', 'ka', 'რას მოითხოვს უსაფრთხოების წესი ლაბორატორიაში რეაქტივების გასინჯვასთან ან მათი სუნის შემოწმებასთან დაკავშირებით?', '["სუსტი მჟავების გასინჯვა ნებადართულია, თუ ამის ნებართვას ლაბორატორიის ხელმძღვანელი გასცემს", "სუნის დასადგენად ჭურჭლის პირიდან 5 სმ-ის მანძილზე კეთდება ღრმა ჩასუნთქვა", "ყველა რეაქტივის სუნი მოწმდება ბამბაზე, მათი გასინჯვა კი აკრძალულია", "მხოლოდ კრისტალური მარილების გასინჯვაა ნებადართულია, სითხეების სუნი კი პირდაპირ შეიგრძნობა", "რეაქტივების გასინჯვა კატეგორიულად აკრძალულია; სუნის შესაგრძნობად ჭურჭლიდან გამომავალი ჰაერი ხელით მსუბუქად უნდა მიიმართოს ცხვირისკენ"]'::jsonb, 'რეაქტივების გასინჯვა კატეგორიულად აკრძალულია; სუნის შესაგრძნობად ჭურჭლიდან გამომავალი ჰაერი ხელით მსუბუქად უნდა მიიმართოს ცხვირისკენ', 'Düzgün cavab: E) რეაქტივების გასინჯვა კატეგორიულად აკრძალულია; სუნის შესაგრძნობად ჭურჭლიდან გამომ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('efeb39ed-dba7-4943-bc6f-543540768f4d', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada gərginlik altında olan elektrik cihazlarının və naqillərin alışması zamanı yanğını hansı vasitə ilə söndürmək **QƏTİ QADAĞANDIR?**', 'multiple_choice', '["Su və ya köpüklü odsöndürən vasitələrlə, elektrik şəbəkəsi ayrılmadan", "Tozlu odsöndürənlə və yanğın örtüyü ilə", "Quru qumla və ya karbon qazlı odsöndürənlə, şəbəkə ayrılmadan", "Qum və torpaq qarışığı ilə söndürməklə", "Karbon qazlı balonla və şəbəkəni ayırmaqla"]'::jsonb, 'Su və ya köpüklü odsöndürən vasitələrlə, elektrik şəbəkəsi ayrılmadan', 'Düzgün cavab: A) Su və ya köpüklü odsöndürən vasitələrlə, elektrik şəbəkəsi ayrılmadan', '', 17, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('141faffc-a9ca-49b9-a027-97599f2450ee', 'efeb39ed-dba7-4943-bc6f-543540768f4d', 'ka', 'ლაბორატორიაში ძაბვის ქვეშ მყოფი ელექტრომოწყობილობებისა და სადენების აალებისას რომელი საშუალებით ხანძრის ჩაქრობაა კატეგორიულად აკრძალული?', '["წყლით ან ქაფის ცეცხლსაქრობი საშუალებებით, ელექტროქსელიდან გათიშვის გარეშე", "ქვიშისა და მიწის ნარევით ჩაქრობა", "ნახშირორჟანგის ცეცხლსაქრობით ქსელიდან გამორთვის შემდეგ", "ფხვნილოვანი ცეცხლსაქრობითა და ცეცხლგამძლე გადასაფარებლით", "მშრალი ქვიშით ან ნახშირორჟანგის ცეცხლსაქრობით, ქსელიდან გათიშვის გარეშე"]'::jsonb, 'წყლით ან ქაფის ცეცხლსაქრობი საშუალებებით, ელექტროქსელიდან გათიშვის გარეშე', 'Düzgün cavab: A) წყლით ან ქაფის ცეცხლსაქრობი საშუალებებით, ელექტროქსელიდან გათიშვის გარეშე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a113092a-2d6a-43f5-939e-3be1499ee015', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Təcrübə zamanı laboratoriya qablarında çat, yarıq və ya qırıq aşkar edildikdə hansı addım atılmalıdır?', 'multiple_choice', '["Çat yerini xüsusi silikonla bərpa edib yenidən rəfə qoymaq", "Çatlamış qabları 50°C-dən aşağı temperaturlarda soyuq təcrübələrdə istifadə etmək", "Çat və qırıq olan qabları dərhal istifadədən çıxarmaq, qeydiyyata almaq və təhlükəsiz şəkildə utilizasiya etmək", "Qırıq qabları köməkçi otaqda saxlayıb nümayiş vasitəsi kimi istifadə etmək", "Çatlı qabları yuyub qurudaraq yenidən kalibrləmək"]'::jsonb, 'Çat və qırıq olan qabları dərhal istifadədən çıxarmaq, qeydiyyata almaq və təhlükəsiz şəkildə utilizasiya etmək', 'Düzgün cavab: C) Çat və qırıq olan qabları dərhal istifadədən çıxarmaq, qeydiyyata almaq və təhlü', '', 18, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cb5fd6d9-234a-4e03-9627-f0364f1fac50', 'a113092a-2d6a-43f5-939e-3be1499ee015', 'ka', 'რა ნაბიჯი უნდა გადაიდგას, თუ ექსპერიმენტის დროს ლაბორატორიულ ჭურჭელზე აღმოჩნდება ბზარი, ნაბზარი ან ნატეხი?', '["დაბზარული ჭურჭლის გამოყენება 50°C-ზე დაბალ ტემპერატურაზე ცივ ექსპერიმენტებში", "გატეხილი ჭურჭლის დამხმარე ოთახში შენახვა და სადემონსტრაციო საშუალებად გამოყენება", "დაბზარული და დაზიანებული ჭურჭლის დაუყოვნებლივ ამოღება ხმარებიდან, აღრიცხვა და უსაფრთხო უტილიზაცია", "დაბზარული ჭურჭლის გარეცხვა, გაშრობა და ხელახალი დაკალიბრება", "ბზარის ადგილის სპეციალური სილიკონით აღდგენა და თაროზე დაბრუნება"]'::jsonb, 'დაბზარული და დაზიანებული ჭურჭლის დაუყოვნებლივ ამოღება ხმარებიდან, აღრიცხვა და უსაფრთხო უტილიზაცია', 'Düzgün cavab: C) დაბზარული და დაზიანებული ჭურჭლის დაუყოვნებლივ ამოღება ხმარებიდან, აღრიცხვა და უს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d9e2df35-442e-44ae-9fe3-daca7517201f', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriya işləri bitdikdən sonra istifadə olunmuş kimyəvi qabların yuyulması, zərərsizləşdirilməsi və qurudulmasına birbaşa kim cavabdehdir?', 'multiple_choice', '["Növbətçi şagirdlər və fənn müəllimi birlikdə, növbəli şəkildə", "Məktəbin təsərrüfat müdiri və laborant birlikdə", "Laboratoriya müdiri və texniki işçi, qrafikə əsasən", "Təhlükəsizlik və sanitariya qaydalarına uyğun olaraq fənn laboratoriyasının laborantı, müəllimin nəzarəti altında", "Xadimə heyəti, xüsusi təlimat əsasında"]'::jsonb, 'Təhlükəsizlik və sanitariya qaydalarına uyğun olaraq fənn laboratoriyasının laborantı, müəllimin nəzarəti altında', 'Düzgün cavab: D) Təhlükəsizlik və sanitariya qaydalarına uyğun olaraq fənn laboratoriyasının labo', '', 19, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f5a2b4a7-837b-4b35-af16-7757d9663b4f', 'd9e2df35-442e-44ae-9fe3-daca7517201f', 'ka', 'ლაბორატორიული სამუშაოების დასრულების შემდეგ ვინ არის უშუალოდ პასუხისმგებელი გამოყენებული ქიმიური ჭურჭლის გარეცხვაზე, გაუვნებელყოფასა და გაშრობაზე?', '["მორიგე მოსწავლეები და საგნის მასწავლებელი ერთად, მორიგეობის მიხედვით", "ლაბორატორიის გამგე და ტექნიკური მუშაკი, გრაფიკის შესაბამისად", "ტექნიკური პერსონალი (დამლაგებლები), სპეციალური ინსტრუქციის საფუძველზე", "უსაფრთხოებისა და სანიტარიული წესების შესაბამისად, საგნობრივი ლაბორატორიის ლაბორანტი, მასწავლებლის კონტროლით", "სკოლის სამეურნეო ნაწილის გამგე და ლაბორანტი ერთად"]'::jsonb, 'უსაფრთხოებისა და სანიტარიული წესების შესაბამისად, საგნობრივი ლაბორატორიის ლაბორანტი, მასწავლებლის კონტროლით', 'Düzgün cavab: D) უსაფრთხოებისა და სანიტარიული წესების შესაბამისად, საგნობრივი ლაბორატორიის ლაბორა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ee208dd9-ce46-4928-a901-32e4167582fe', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada istifadə olunan spirt lampasının (spirtovka) təhlükəsiz söndürülməsi qaydası necədir?', 'multiple_choice', '["Xüsusi qapağını (kolpaçok) alovun üzərinə qoyaraq havanın (oksigenin) daxil olmasını kəsməklə, üfürmədən", "Qapağı yarım açıq qoyaraq alovun öz-özünə sönməsini gözləməklə", "Fitili pinsetlə içəri çəkərək spirtdə söndürməklə", "Alovun üzərinə metal lövhə qoyub sonra su tökməklə", "Fitili yan tərəfə əyərək alovu azaltmaqla və sonra üfürməklə"]'::jsonb, 'Xüsusi qapağını (kolpaçok) alovun üzərinə qoyaraq havanın (oksigenin) daxil olmasını kəsməklə, üfürmədən', 'Düzgün cavab: A) Xüsusi qapağını (kolpaçok) alovun üzərinə qoyaraq havanın (oksigenin) daxil olma', '', 20, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f5a0098c-842d-4cc7-a314-ec7c65edc0f4', 'ee208dd9-ce46-4928-a901-32e4167582fe', 'ka', 'როგორია ლაბორატორიაში გამოყენებული სპირტქურის (სპირტოვკის) უსაფრთხოდ ჩაქრობის წესი?', '["სპეციალური თავსახურის (ჩამხშობის) ალზე დაფარებით ჰაერის (ჟანგბადის) მიწოდების შეწყვეტის გზით, ჩაბერვის გარეშე", "ალზე ლითონის ფირფიტის დაფარებით და შემდეგ წყლის დასხმით", "თავსახურის ნახევრად დაფარებით და ალის თავისთავად ჩაქრობის დალოდებით", "პატრუქის გვერდზე გადახრით ალის შემცირებით და შემდეგ ჩაბერვით", "პატრუქის პინცეტით შიგნით ჩაწევით და სპირტში ჩაქრობით"]'::jsonb, 'სპეციალური თავსახურის (ჩამხშობის) ალზე დაფარებით ჰაერის (ჟანგბადის) მიწოდების შეწყვეტის გზით, ჩაბერვის გარეშე', 'Düzgün cavab: A) სპეციალური თავსახურის (ჩამხშობის) ალზე დაფარებით ჰაერის (ჟანგბადის) მიწოდების შე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bac869ba-dbd9-48fd-a19b-690e30627572', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Kimyəvi reaktivlərin, cihazların və laboratoriya avadanlıqlarının məktəb laboratoriyasında uçotu hansı rəsmi sənəddə aparılır?', 'multiple_choice', '["Laboratoriya Təhlükəsizlik Aktında və Təlimat Jurnalında", "Kimyəvi Maddələrin Xəzinə Kitabında və sifariş blankında", "Laboratoriya avadanlıqlarının və reaktivlərinin Uçot və Qeydiyyat Jurnalında, inventar nömrəsi ilə", "Maddi dəyərlilərin Qeydiyyat Kitabında və anbar qəbzində", "Tədris Avadanlıqlarının Pasportunda və illik hesabatda"]'::jsonb, 'Laboratoriya avadanlıqlarının və reaktivlərinin Uçot və Qeydiyyat Jurnalında, inventar nömrəsi ilə', 'Düzgün cavab: C) Laboratoriya avadanlıqlarının və reaktivlərinin Uçot və Qeydiyyat Jurnalında, in', '', 21, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a5d08cdd-c59d-4a43-8140-888944e605ff', 'bac869ba-dbd9-48fd-a19b-690e30627572', 'ka', 'რომელ ოფიციალურ დოკუმენტში წარმოებს ქიმიური რეაქტივების, ხელსაწყოებისა და ლაბორატორიული აღჭურვილობის აღრიცხვა სასკოლო ლაბორატორიაში?', '["მატერიალურ ფასეულობათა სარეგისტრაციო წიგნსა და სასაწყობო ქვითარში", "ქიმიურ ნივთიერებათა საგანძურის წიგნსა და შეკვეთის ბლანკში", "ლაბორატორიული აღჭურვილობისა და რეაქტივების აღრიცხვისა და რეგისტრაციის ჟურნალში, საინვენტარო ნომრით", "სასწავლო აღჭურვილობის პასპორტსა და წლიურ ანგარიშში", "ლაბორატორიის უსაფრთხოების აქტსა და ინსტრუქტაჟის ჟურნალში"]'::jsonb, 'ლაბორატორიული აღჭურვილობისა და რეაქტივების აღრიცხვისა და რეგისტრაციის ჟურნალში, საინვენტარო ნომრით', 'Düzgün cavab: C) ლაბორატორიული აღჭურვილობისა და რეაქტივების აღრიცხვისა და რეგისტრაციის ჟურნალში,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d6ae61c8-828a-4507-b0e8-86b5e1b103c4', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Şagirdin əli laboratoriya şüşəsi qırıntısı ilə kəsildikdə və qanaxma yarandıqda ilkin yardım necə göstərilməlidir?', 'multiple_choice', '["Yaranı dərhal bol su ilə yuyub hidrogen peroksid töküb açıq saxlamaq", "Yaraya soda tozu səpib pambıqla sıxmaq və 10 dəqiqə qaldırılmış vəziyyətdə tutmaq", "Əli spirtlə silib yapışqan lentlə bağlamaq və soyuq kompres qoymaq", "Kəsik yerini yodla tam doldurub sıxıcı sarğı ilə bağlamaq və dərsə davam etmək", "Şüşə qırıntılarını ehtiyatla kənarlaşdırmaq, yaranın ətrafını antiseptiklə silib steril sarğı qoymaq və tibb məntəqəsinə müraciət etmək"]'::jsonb, 'Şüşə qırıntılarını ehtiyatla kənarlaşdırmaq, yaranın ətrafını antiseptiklə silib steril sarğı qoymaq və tibb məntəqəsinə müraciət etmək', 'Düzgün cavab: E) Şüşə qırıntılarını ehtiyatla kənarlaşdırmaq, yaranın ətrafını antiseptiklə silib', '', 22, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c8d06bb4-7795-4726-87b3-e1f752ff08f8', 'd6ae61c8-828a-4507-b0e8-86b5e1b103c4', 'ka', 'როგორ უნდა აღმოეჩინოს პირველადი დახმარება მოსწავლეს, თუ მან ხელი ლაბორატორიული მინის ნამსხვრევით გაიჭრა და განვითარდა სისხლდენა?', '["ჭრილობის იოდით სრულად დამუშავება, დამწოლი ნახვევის დადება და გაკვეთილის გაგრძელება", "ჭრილობაზე სოდის ფხვნილის მოყრა, ბამბით დაწოლა და ხელის 10 წუთით აწეულ მდგომარეობაში გაჩერება", "ჭრილობის დაუყოვნებლივ უხვი წყლით დაბანა, წყალბადის ზეჟანგის დასხმა და ღიად დატოვება", "ხელის სპირტით გაწმენდა, წებოვანი ლენტით დაფიქსირება და ცივი კომპრესის დადება", "მინის ნამსხვრევების ფრთხილად მოცილება, ჭრილობის ირგვლივ კანის ანტისეპტიკით დამუშავება, სტერილური ნახვევის დადება და სამედიცინო პუნქტისთვის მიმართვა"]'::jsonb, 'მინის ნამსხვრევების ფრთხილად მოცილება, ჭრილობის ირგვლივ კანის ანტისეპტიკით დამუშავება, სტერილური ნახვევის დადება და სამედიცინო პუნქტისთვის მიმართვა', 'Düzgün cavab: E) მინის ნამსხვრევების ფრთხილად მოცილება, ჭრილობის ირგვლივ კანის ანტისეპტიკით დამუშ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('39660d94-f421-4935-904d-c4632dabd3e1', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada maddələri çəkmək üçün istifadə olunan analitik və texniki tərəzilərin istismar qaydalarına hansı **AİD DEYİLDİR?**', 'multiple_choice', '["Qaynar, nəm və ya aqressiv buxarlanan qabların dərhal tərəzi gözünə qoyulub çəkilməsi", "Tərəzini nivelirlə horizontal vəziyyətə gətirmək", "Tərəzinin şüşə qapağını bağlı saxlayaraq çəkmə aparmaq", "Çəki daşlarını pinsetlə götürmək və tarazlaşdırmaq", "Kimyəvi maddəni birbaşa gözə deyil, saat şüşəsində çəkmək"]'::jsonb, 'Qaynar, nəm və ya aqressiv buxarlanan qabların dərhal tərəzi gözünə qoyulub çəkilməsi', 'Düzgün cavab: A) Qaynar, nəm və ya aqressiv buxarlanan qabların dərhal tərəzi gözünə qoyulub çəki', '', 23, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('842fe708-34ad-4b6a-862e-1d344bd99877', '39660d94-f421-4935-904d-c4632dabd3e1', 'ka', 'ჩამოთვლილთაგან რომელი არ მიეკუთვნება ლაბორატორიაში ნივთიერებათა ასაწონად გამოყენებული ანალიზური და ტექნიკური სასწორების ექსპლუატაციის წესებს?', '["ცხელი, ნესტიანი ან აგრესიულად აორთქლებადი ჭურჭლის დაუყოვნებლივ სასწორის თეფშზე დადება და აწონვა", "ქიმიური ნივთიერების აწონვა საათის მინაზე და არა უშუალოდ სასწორის თეფშზე", "საწონების პინცეტით აღება და გაწონასწორება", "აწონვის ჩატარება სასწორის მინის დამცავი კარადის დახურულ მდგომარეობაში", "სასწორის თარაზოს (ნიველირის) საშუალებით ჰორიზონტალურ მდგომარეობაში მოყვანა"]'::jsonb, 'ცხელი, ნესტიანი ან აგრესიულად აორთქლებადი ჭურჭლის დაუყოვნებლივ სასწორის თეფშზე დადება და აწონვა', 'Düzgün cavab: A) ცხელი, ნესტიანი ან აგრესიულად აორთქლებადი ჭურჭლის დაუყოვნებლივ სასწორის თეფშზე დ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3221eb1c-486a-4c1d-a693-54be0efbe7d7', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriya otağında və sorucu şkafda havalandırma sisteminin işlək vəziyyətdə olması nə vaxt və necə yoxlanılmalıdır?', 'multiple_choice', '["İldə iki dəfə, sanitar qovşaq yoxlanışı ilə paralel", "Hər rübün sonunda, direktorun iştirakı ilə komissiya tərəfindən", "Yalnız qoxu hiss edildikdə və ya şagird şikayət etdikdə", "Ayda bir dəfə, yalnız texniki baxış zamanı, vizual olaraq", "Hər tədris ilinin əvvəlində və hər laboratoriya təcrübəsinə başlamazdan əvvəl müntəzəm qaydada, kağız zolaq və ya anemometrlə"]'::jsonb, 'Hər tədris ilinin əvvəlində və hər laboratoriya təcrübəsinə başlamazdan əvvəl müntəzəm qaydada, kağız zolaq və ya anemometrlə', 'Düzgün cavab: E) Hər tədris ilinin əvvəlində və hər laboratoriya təcrübəsinə başlamazdan əvvəl mü', '', 24, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8740bb22-360a-4d04-93a8-4a989b5094d6', '3221eb1c-486a-4c1d-a693-54be0efbe7d7', 'ka', 'როდის და როგორ უნდა შემოწმდეს ლაბორატორიულ ოთახსა და გამწოვ კარადაში სავენტილაციო სისტემის გამართულობა?', '["მხოლოდ სუნის შეგრძნებისას ან მოსწავლის საჩივრის შემთხვევაში", "წელიწადში ორჯერ, სანიტარიული კვანძის შემოწმების პარალელურად", "ყოველი კვარტალის ბოლოს, კომისიის მიერ დირექტორის მონაწილეობით", "თვეში ერთხელ, მხოლოდ ტექნიკური დათვალიერებისას, ვიზუალურად", "ყოველ სასწავლო წლის დასაწყისში და ყოველი ლაბორატორიული ექსპერიმენტის დაწყებამდე რეგულარულად, ქაღალდის ზოლით ან ანემომეტრით"]'::jsonb, 'ყოველ სასწავლო წლის დასაწყისში და ყოველი ლაბორატორიული ექსპერიმენტის დაწყებამდე რეგულარულად, ქაღალდის ზოლით ან ანემომეტრით', 'Düzgün cavab: E) ყოველ სასწავლო წლის დასაწყისში და ყოველი ლაბორატორიული ექსპერიმენტის დაწყებამდე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('62af4f40-f372-4149-8ca1-377cc5ea51fd', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada kimyəvi turşu və ya qələvi məhlulu gözə sıçradıqda dərhal hansı təxirəsalınmaz tədbir görülməlidir?', 'multiple_choice', '["Gözə 2%-li soda məhlulu damcıladıb sonra quru tamponla silmək", "Gözü dərhal 10–15 dəqiqə bol axar su ilə, göz qapaqları açıq vəziyyətdə yumaq və təcili tibbi yardıma müraciət etmək", "Gözü bağlı saxlayıb 5 dəqiqə sonra borat turşusu ilə yumaq", "Gözə antiseptik məlhəm çəkib sarğı qoymaq və 1 saat gözləmək", "Gözü spirtli məhlulla silib pambıqla örtmək"]'::jsonb, 'Gözü dərhal 10–15 dəqiqə bol axar su ilə, göz qapaqları açıq vəziyyətdə yumaq və təcili tibbi yardıma müraciət etmək', 'Düzgün cavab: B) Gözü dərhal 10–15 dəqiqə bol axar su ilə, göz qapaqları açıq vəziyyətdə yumaq və', '', 25, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6aad48bc-4f1a-4eeb-b29f-8cf796730d0f', '62af4f40-f372-4149-8ca1-377cc5ea51fd', 'ka', 'რა გადაუდებელი ზომები უნდა იქნეს მიღებული დაუყოვნებლივ, როდესაც ლაბორატორიაში თვალში ქიმიური მჟავას ან ტუტის ხსნარი შეესხმება?', '["თვალის დახუჭულ მდგომარეობაში გაჩერება და 5 წუთის შემდეგ ბორის მჟავით დაბანა", "თვალის დაუყოვნებლივ ჩამორეცხვა 10–15 წუთის განმავლობაში გამდინარე წყლის უხვი ჭავლით, ქუთუთოების ღია მდგომარეობაში, და სასწრაფო სამედიცინო დახმარების გამოძახება", "თვალში სოდის 2%-იანი ხსნარის ჩაწვეთება და შემდეგ მშრალი ტამპონით გამშრალება", "თვალის სპირტიანი ხსნარით გაწმენდა და ბამბით დაფარვა", "თვალზე ანტისეპტიკური მალამოს წასმა, ნახვევის დადება და 1 საათის განმავლობაში დალოდება"]'::jsonb, 'თვალის დაუყოვნებლივ ჩამორეცხვა 10–15 წუთის განმავლობაში გამდინარე წყლის უხვი ჭავლით, ქუთუთოების ღია მდგომარეობაში, და სასწრაფო სამედიცინო დახმარების გამოძახება', 'Düzgün cavab: B) თვალის დაუყოვნებლივ ჩამორეცხვა 10–15 წუთის განმავლობაში გამდინარე წყლის უხვი ჭავ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('16587859-dff9-47e8-8e66-5ebac7c23b56', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Biologiya laboratoriyasında mikroskopla iş zamanı obyektiv və okulyar linzalarının cızılmaması və təmiz saxlanması üçün nədən istifadə edilməlidir?', 'multiple_choice', '["Nəm salfet və ammonyak məhlulundan", "Xüsusi yumşaq optik salfetdən, mikrofiber və ya təmiz flanel parçadan, ksilol olmadan", "Qələvi məhlulu ilə isladılmış tənzifdən", "Quru pambıq və etil spirtindən, dairəvi hərəkətlərlə", "Sərt kağız dəsmal və aseton qarışığından"]'::jsonb, 'Xüsusi yumşaq optik salfetdən, mikrofiber və ya təmiz flanel parçadan, ksilol olmadan', 'Düzgün cavab: B) Xüsusi yumşaq optik salfetdən, mikrofiber və ya təmiz flanel parçadan, ksilol ol', '', 26, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cd3e8c26-9b85-4018-aa6f-1c1957868adc', '16587859-dff9-47e8-8e66-5ebac7c23b56', 'ka', 'რა უნდა იქნეს გამოყენებული ბიოლოგიის ლაბორატორიაში მიკროსკოპთან მუშაობისას ობიექტივისა და ოკულარის ლინზების დაკაწვრის თავიდან ასაცილებლად და მათი სისუფთავის შესანარჩუნებლად?', '["ტუტის ხსნარით დასველებული დოლბანდი", "სპეციალური რბილი ოპტიკური ხელსახოცი, მიკროფიბრა ან სუფთა ფლანელის ქსოვილი, ქსილოლის გარეშე", "სველი ხელსახოცი და ამიაკის ხსნარი", "მშრალი ბამბა და ეთილის სპირტი, წრიული მოძრაობებით", "უხეში ქაღალდის პირსახოცი და აცეტონის ნარევი"]'::jsonb, 'სპეციალური რბილი ოპტიკური ხელსახოცი, მიკროფიბრა ან სუფთა ფლანელის ქსოვილი, ქსილოლის გარეშე', 'Düzgün cavab: B) სპეციალური რბილი ოპტიკური ხელსახოცი, მიკროფიბრა ან სუფთა ფლანელის ქსოვილი, ქსილო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('58d45978-202e-453f-b02c-4b65d899cd67', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriya tullantılarının (işlənmiş turşu, qələvi və ağır metal duzları məhlullarının) utilizasiyası necə aparılmalıdır?', 'multiple_choice', '["Qatılaşdırılaraq buxarlandırılıb bərk tullantı kimi atılaraq", "Plastik qablarda toplanıb məişət tullantısı ilə qarışdırılaraq", "Torpağa basdırılaraq və ya yandırılaraq", "Əvvəlcə xüsusi qablarda neytrallaşdırılaraq, durulaşdırılaraq laboratoriya utilizasiya təlimatına və ekoloji normaya uyğun kənarlaşdırılmaqla", "Az miqdarda olduqda kanalizasiyaya bol su ilə axıdılaraq"]'::jsonb, 'Əvvəlcə xüsusi qablarda neytrallaşdırılaraq, durulaşdırılaraq laboratoriya utilizasiya təlimatına və ekoloji normaya uyğun kənarlaşdırılmaqla', 'Düzgün cavab: D) Əvvəlcə xüsusi qablarda neytrallaşdırılaraq, durulaşdırılaraq laboratoriya utili', '', 27, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ae204222-0667-41a3-9bb8-c11ef869dc24', '58d45978-202e-453f-b02c-4b65d899cd67', 'ka', 'როგორ უნდა განხორციელდეს ლაბორატორიული ნარჩენების (გამოყენებული მჟავების, ტუტეებისა და მძიმე ლითონების მარილების ხსნარების) უტილიზაცია?', '["მიწაში ჩაფლვით ან დაწვით", "კონცენტრირებით, აორთქლებით და მყარ ნარჩენად გადაყრით", "მცირე რაოდენობის შემთხვევაში კანალიზაციაში უხვი წყლით ჩარეცხვით", "ჯერ სპეციალურ ჭურჭელში განეიტრალებით, გაზავებით და ლაბორატორიული უტილიზაციის ინსტრუქციისა და ეკოლოგიური ნორმების შესაბამისად გატანით", "პლასტმასის ჭურჭელში შეგროვებით და საყოფაცხოვრებო ნარჩენებთან შერევით"]'::jsonb, 'ჯერ სპეციალურ ჭურჭელში განეიტრალებით, გაზავებით და ლაბორატორიული უტილიზაციის ინსტრუქციისა და ეკოლოგიური ნორმების შესაბამისად გატანით', 'Düzgün cavab: D) ჯერ სპეციალურ ჭურჭელში განეიტრალებით, გაზავებით და ლაბორატორიული უტილიზაციის ინს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('367b5818-7995-4ab9-b85e-2d73998af8df', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Məktəb kimya-biologiya laboratoriyasında laborant və müəllimin istifadə etməli olduğu fərdi mühafizə vasitələri (FMV) hansılardır?', 'multiple_choice', '["Pambıq xalat, qoruyucu eynək, rezin və ya nitril əlcəklər, qoruyucu önlük və qapalı ayaqqabı", "Xüsusi kimyəvi kostyum, əleyhqaz və çəkmələr", "Tibbi xalat, cərrahi maska və birdəfəlik əlcək", "Yanğına davamlı kombinezon, dəbilqə və eynək", "Polimer önlük, üz sipəri, lateks əlcək və respirator"]'::jsonb, 'Pambıq xalat, qoruyucu eynək, rezin və ya nitril əlcəklər, qoruyucu önlük və qapalı ayaqqabı', 'Düzgün cavab: A) Pambıq xalat, qoruyucu eynək, rezin və ya nitril əlcəklər, qoruyucu önlük və qap', '', 28, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e1bf904b-06a9-4a5b-a5b7-e99438938695', '367b5818-7995-4ab9-b85e-2d73998af8df', 'ka', 'ინდივიდუალური დაცვის რომელი საშუალებები (იდს) უნდა გამოიყენონ ლაბორანტმა და მასწავლებელმა სასკოლო ქიმია-ბიოლოგიის ლაბორატორიაში?', '["ბამბის ხალათი, დამცავი სათვალე, რეზინის ან ნიტრილის ხელთათმანები, დამცავი წინსაფარი და დახურული ფეხსაცმელი", "სამედიცინო ხალათი, ქირურგიული ნიღაბი და ერთჯერადი ხელთათმანი", "ცეცხლგამძლე კომბინეზონი, ჩაფხუტი და სათვალე", "სპეციალური ქიმიური კოსტიუმი, აირწინაღი და ჩექმები", "პოლიმერული წინსაფარი, სახის ფარი, ლატექსის ხელთათმანი და რესპირატორი"]'::jsonb, 'ბამბის ხალათი, დამცავი სათვალე, რეზინის ან ნიტრილის ხელთათმანები, დამცავი წინსაფარი და დახურული ფეხსაცმელი', 'Düzgün cavab: A) ბამბის ხალათი, დამცავი სათვალე, რეზინის ან ნიტრილის ხელთათმანები, დამცავი წინსაფ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d51b4b19-51a4-4123-85d6-c4899788cb83', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Laboratoriyada qaz kranları və qaz xətlərindən istifadə zamanı kəskin qaz qoxusu hiss edildikdə ilk növbədə nə edilməlidir?', 'multiple_choice', '["Elektrik açarlarını yandırıb-söndürməmək, açıq alovdan istifadə etməmək, qaz kranını bağlamaq, pəncərələri açıb otağı havalandırmaq", "Elektrik cihazlarını söndürüb qapını bağlayaraq otağı tərk etmək", "Qaz kranını açıq saxlayıb sızmanın mənbəyini kibritlə yoxlamaq", "Qaz xəttinin üzərinə yaş parça örtüb dərhal direktoru çağırmaq", "Bütün pəncərələri bağlayıb qazın yayılmasının qarşısını almaq"]'::jsonb, 'Elektrik açarlarını yandırıb-söndürməmək, açıq alovdan istifadə etməmək, qaz kranını bağlamaq, pəncərələri açıb otağı havalandırmaq', 'Düzgün cavab: A) Elektrik açarlarını yandırıb-söndürməmək, açıq alovdan istifadə etməmək, qaz kra', '', 29, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4b3fe61f-ef75-4746-9bba-a3505e1f63d8', 'd51b4b19-51a4-4123-85d6-c4899788cb83', 'ka', 'რა უნდა გაკეთდეს პირველ რიგში, თუ ლაბორატორიაში გაზის ონკანებისა და გაზგაყვანილობის გამოყენებისას იგრძნობა გაზის მძაფრი სუნი?', '["არ ჩაირთოს და არ გამოირთოს ელექტროჩამრთველები, არ იქნეს გამოყენებული ღია ცეცხლი, გადაიკეტოს გაზის ონკანი, გაიღოს ფანჯრები და განიავდეს ოთახი", "გაზის ონკანის ღიად დატოვება და გაჟონვის წყაროს ასანთით შემოწმება", "გაზის მილზე სველი ნაჭრის დაფარება და დაუყოვნებლივ დირექტორის გამოძახება", "ელექტრომოწყობილობების გამორთვა, კარის დაკეტვა და ოთახის დატოვება", "ყველა ფანჯრის დახურვა გაზის გავრცელების თავიდან ასაცილებლად"]'::jsonb, 'არ ჩაირთოს და არ გამოირთოს ელექტროჩამრთველები, არ იქნეს გამოყენებული ღია ცეცხლი, გადაიკეტოს გაზის ონკანი, გაიღოს ფანჯრები და განიავდეს ოთახი', 'Düzgün cavab: A) არ ჩაირთოს და არ გამოირთოს ელექტროჩამრთველები, არ იქნეს გამოყენებული ღია ცეცხლი,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a352ad23-ec46-425c-b5d9-d220c8252f71', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Məktəb laboratoriyasında müasir rəqəmsal laboratoriya avadanlıqları və sensorların işə hazırlanması zamanı laborantın vəzifəsi nədir?', 'multiple_choice', '["Sensorları birbaşa 220V şəbəkəyə qoşub işləkliyini yoxlamaq", "Proqram təminatını silib yenidən quraşdırmaq və sınaq etməmək", "Bütün sensorları distillə edilmiş suda saxlayaraq kalibrləmək", "Sensorların sazlığını yoxlamaq, interfeys blokunu kompyuterə qoşub proqramı və kalibrləməni sınaqdan keçirmək", "Cihazların batareyalarını çıxarıb yalnız naqillə işlətmək"]'::jsonb, 'Sensorların sazlığını yoxlamaq, interfeys blokunu kompyuterə qoşub proqramı və kalibrləməni sınaqdan keçirmək', 'Düzgün cavab: D) Sensorların sazlığını yoxlamaq, interfeys blokunu kompyuterə qoşub proqramı və k', '', 30, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8359252b-436f-4821-a9df-bf6ef2f16851', 'a352ad23-ec46-425c-b5d9-d220c8252f71', 'ka', 'რა ევალება ლაბორანტს სასკოლო ლაბორატორიაში თანამედროვე ციფრული ლაბორატორიული აღჭურვილობისა და სენსორების სამუშაოდ მომზადებისას?', '["სენსორების პირდაპირ 220 ვოლტის ქსელში ჩართვა და მათი მუშაობის შემოწმება", "მოწყობილობებიდან ელემენტების ამოღება და მხოლოდ სადენით მუშაობა", "პროგრამული უზრუნველყოფის წაშლა, თავიდან დაინსტალირება და ტესტირების ჩაუტარებლობა", "სენსორების გამართულობის შემოწმება, ინტერფეისის ბლოკის კომპიუტერთან მიერთება, პროგრამული უზრუნველყოფისა და დაკალიბრების გამოცდა", "ყველა სენსორის გამოხდილ წყალში შენახვით დაკალიბრება"]'::jsonb, 'სენსორების გამართულობის შემოწმება, ინტერფეისის ბლოკის კომპიუტერთან მიერთება, პროგრამული უზრუნველყოფისა და დაკალიბრების გამოცდა', 'Düzgün cavab: D) სენსორების გამართულობის შემოწმება, ინტერფეისის ბლოკის კომპიუტერთან მიერთება, პრო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a29cf381-6670-413f-84f2-edaa4dab19bb', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Azərbaycan Respublikası Konstitusiyasının 42-ci maddəsinə əsasən, vətəndaşların təhsil hüququ ilə bağlı dövlətin əsas təminatı nədir?', 'multiple_choice', '["Dövlət təhsil sistemində bütün pillələrin tamamilə ödənişli əsaslarla təşkil edilməsini qanunvericiliklə tənzimləyir", "Dövlət yalnız əlaçı şagirdlərin pulsuz təhsil almasını təmin edir və digər vətəndaşlara ödənişli əsaslarla şərait yaradır", "Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir", "Dövlət yalnız dövlət qulluqçularının övladlarının pulsuz orta ixtisas təhsili almasına hüquqi zəmanət verir", "Dövlət hər bir vətəndaşın ali təhsil almasını məcburi edir və təhsil xərclərini tam şəkildə kommersiya banklarına həvalə edir"]'::jsonb, 'Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir', 'Düzgün cavab: C) Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin e', '', 31, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3e7657a1-3c41-4500-8c94-4746f55b4c31', 'a29cf381-6670-413f-84f2-edaa4dab19bb', 'ka', 'აზერბაიჯანის რესპუბლიკის კონსტიტუციის 42-ე მუხლის თანახმად, განათლების უფლების უზრუნველყოფასთან დაკავშირებით რომელი დებულებაა განმტკიცებული?', '["სახელმწიფო განათლების უფლებას მხოლოდ 18 წლამდე ასაკის მოქალაქეებზე ავრცელებს", "სახელმწიფო მხოლოდ სახელმწიფო სკოლებში ხდის განათლებას უფასოს, კერძო სკოლებში განათლება ფასიანია და კონტროლი ეკისრებათ მუნიციპალიტეტებს", "სახელმწიფო გარანტიას იძლევა თითოეული მოქალაქის უფლებაზე, მიიღოს უფასო სავალდებულო ზოგადი საშუალო განათლება, ნიჭიერი პირების მიერ განათლების გაგრძელებაზე და განათლების სისტემაზე სახელმწიფო კონტროლზე", "სახელმწიფო გარანტიას იძლევა უფასო განათლებაზე უმაღლესი განათლების ყველა საფეხურზე და სწავლის საფასური იფარება სახელმწიფო ბიუჯეტიდან", "სახელმწიფო მხოლოდ დაწყებით განათლებას მიიჩნევს სავალდებულოდ, ზოგადი საშუალო განათლება კი ნებაყოფლობითია"]'::jsonb, 'სახელმწიფო გარანტიას იძლევა თითოეული მოქალაქის უფლებაზე, მიიღოს უფასო სავალდებულო ზოგადი საშუალო განათლება, ნიჭიერი პირების მიერ განათლების გაგრძელებაზე და განათლების სისტემაზე სახელმწიფო კონტროლზე', 'Düzgün cavab: C) სახელმწიფო გარანტიას იძლევა თითოეული მოქალაქის უფლებაზე, მიიღოს უფასო სავალდებულ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('acf46d27-8e7b-4ca3-9c8d-40424bf15681', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Azərbaycan Respublikası Konstitusiyasının 25-ci maddəsinə əsasən, bərabərlik hüququnun təhsil və əmək münasibətlərində təminatı necə müəyyən olunmuşdur?', 'multiple_choice', '["Sosial mənşəyindən və yaşayış yerindən asılı olaraq təhsil müəssisələrinə qəbulda məhdudiyyətlər qoyula bilər", "İşə qəbul və təhsil prosesində yalnız rəhbərliyin subyektiv mülahizələri əsas götürülür və imtiyazlar müəyyən edilir", "Ayrı-seçkiliyə yalnız müəssisə rəhbərinin yazılı əmri və daxili nizamnamə tələbləri ilə yol verilə bilər", "Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir", "Vətəndaşların hüquq bərabərliyi yalnız dövlət qulluğunda çalışan şəxslərə şamil edilir, digər sahələrdə fərqli münasibət qanunidir"]'::jsonb, 'Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir', 'Düzgün cavab: D) Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyin', '', 32, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('afacf96e-7046-4540-8fbc-126ef81c45a0', 'acf46d27-8e7b-4ca3-9c8d-40424bf15681', 'ka', 'აზერბაიჯანის რესპუბლიკის კონსტიტუციის 25-ე მუხლის მიხედვით, რომელია თანასწორობის უფლების შინაარსის ამსახველი სწორი სამართლებრივი ნორმა?', '["სახელმწიფო გარანტიას იძლევა უფლებრივ თანასწორობაზე მხოლოდ აზერბაიჯანის მოქალაქეებისთვის, რაც არ ვრცელდება უცხოელებზე", "თანასწორობის უფლება გამოიყენება მხოლოდ სასამართლო პროცესში და არ ეხება განათლების სფეროს", "თანასწორობის უფლება გამოიყენება მხოლოდ საჯარო მოხელეებს შორის თანამდებობების განაწილებისას", "სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესის, მრწამსის, სოციალური წარმოშობის მიუხედავად", "სახელმწიფო თანასწორობას უზრუნველყოფს მხოლოდ შრომით ურთიერთობებსა და სოციალურ უზრუნველყოფაში"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესის, მრწამსის, სოციალური წარმოშობის მიუხედავად', 'Düzgün cavab: D) სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f81c620d-c887-49ea-b230-6bc4987c3c22', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Azərbaycan Respublikası Konstitusiyasının 32-ci maddəsinə əsasən, şəxsi toxunulmazlıq hüququ təhsil müəssisəsində hansı tələbi irəli sürür?', 'multiple_choice', '["Təhsil müəssisəsi rəhbərliyi işçilərin şəxsi məlumatlarını istədiyi məqsədlə kənar şəxslərə və sosial şəbəkələrə açıqlaya bilər", "İşçilərin fərdi məlumatları və tibbi arayışları kollektiv qarşısında müzakirə edilməli və elan lövhəsinə vurulmalıdır", "Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına yol verilmir", "Məktəb administrasiyası şagird və işçilərin şəxsi yazışmalarını və fərdi sirlərini əmrlə ictimaiyyətə təqdim etməlidir", "Şəxsi toxunulmazlıq hüququ yalnız rəhbər heyətə aiddir və sıravi işçilərə tətbiq edilmir"]'::jsonb, 'Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına yol verilmir', 'Düzgün cavab: C) Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılması', '', 33, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b887c5b2-2ad9-4875-9e75-6196ccb20b88', 'f81c620d-c887-49ea-b230-6bc4987c3c22', 'ka', 'აზერბაიჯანის რესპუბლიკის კონსტიტუციის 32-ე მუხლის თანახმად, რა წესია დადგენილი პირადი ხელშეუხებლობის უფლებასთან დაკავშირებით?', '["პერსონალური მონაცემების შეგროვება თავისუფლად რეგულირდება საგანმანათლებლო დაწესებულების შინაგანაწესით", "პირადი ხელშეუხებლობის უფლება ვრცელდება მხოლოდ სახელმწიფო საიდუმლოების მატარებელ პირებზე", "მოქალაქის თანხმობის გარეშე დაუშვებელია მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა, გამოყენება და გავრცელება, გარდა კანონით დადგენილი შემთხვევებისა", "პირადი ცხოვრების შესახებ ინფორმაციის გავრცელება შესაძლებელია მხოლოდ დასაქმებულის ზეპირი თანხმობით", "პირადი მონაცემები შეიძლება შეგროვდეს სასამართლო გადაწყვეტილების გარეშეც, თუ ამას საგანმანათლებლო დაწესებულება მოითხოვს"]'::jsonb, 'მოქალაქის თანხმობის გარეშე დაუშვებელია მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა, გამოყენება და გავრცელება, გარდა კანონით დადგენილი შემთხვევებისა', 'Düzgün cavab: C) მოქალაქის თანხმობის გარეშე დაუშვებელია მისი პირადი ცხოვრების შესახებ ინფორმაციის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('45256096-0ccf-4a5e-84f5-870653a2f545', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', '“Təhsil haqqında” AR Qanununun 3-cü maddəsinə əsasən, dövlət siyasətinin əsas prinsiplərindən olan ''Humanistlik'' prinsipinin mahiyyəti nədir?', 'multiple_choice', '["Təhsil müəssisələrinin maliyyə gəlirlərinin artırılmasının bütün tədris prosesindən üstün tutulması", "Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul edilməsi", "Tədris prosesində yalnız xarici ölkələrin təcrübəsinin mütləq şəkildə kopyalanması tələbi", "Təhsilalanların akademik nəticələrinin yalnız cəza mexanizmləri vasitəsilə yüksəldilməsi prinsipi", "Yalnız dövlət sifarişi əsasında kadr hazırlığının aparılması və fərdi maraqların məhdudlaşdırılması"]'::jsonb, 'Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul edilməsi', 'Düzgün cavab: B) Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və', '', 34, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('056d177e-e634-496e-b4b8-0f5441d0db06', '45256096-0ccf-4a5e-84f5-870653a2f545', 'ka', 'აზერბაიჯანის რესპუბლიკის კანონის „განათლების შესახებ“ მე-3 მუხლის თანახმად, რას გამოხატავს განათლების სფეროში სახელმწიფო პოლიტიკის ერთ-ერთი ძირითადი პრინციპი — „ჰუმანისტურობა“?', '["განათლების მხოლოდ ეროვნულ ღირებულებებზე დაფუძნებასა და საერთაშორისო ინტეგრაციის შეზღუდვას", "ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას", "საგანმანათლებლო დაწესებულებების მხოლოდ სახელმწიფოს მიერ დაფინანსებას", "სწავლის მიმღებთა მომზადებას მხოლოდ შრომის ბაზრის მოთხოვნების შესაბამისად", "განათლებაში კონკურენტული გარემოს აღმოფხვრასა და თანაბარ შეფასებას"]'::jsonb, 'ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას', 'Düzgün cavab: B) ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a092ffb7-5b8f-44c8-a030-1a9a3112b052', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', '“Təhsil haqqında” AR Qanununun 12-ci maddəsinə əsasən, Azərbaycan Respublikasında təhsilin hansı formaları müəyyən edilmişdir?', 'multiple_choice', '["Əyani, qiyabi və distant təhsil", "İbtidai, baza və orta ixtisas təhsili", "Formal, qeyri-formal və informal təhsil", "Stasionar, distant və sərbəst təhsil", "Akademik, peşəkar və ümumi təhsil"]'::jsonb, 'Formal, qeyri-formal və informal təhsil', 'Düzgün cavab: C) Formal, qeyri-formal və informal təhsil', '', 35, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3d0bef5b-1d4b-4417-b379-a04bdbaeaded', 'a092ffb7-5b8f-44c8-a030-1a9a3112b052', 'ka', 'აზერბაიჯანის რესპუბლიკის კანონის „განათლების შესახებ“ მე-12 მუხლის თანახმად, რომელია აზერბაიჯანის რესპუბლიკაში განსაზღვრული განათლების ფორმები?', '["დასწრებული, დაუსწრებელი და დისტანციური განათლება", "დაწყებითი, საშუალო და უმაღლესი განათლება", "ფორმალური, არაფორმალური და ინფორმალური განათლება", "სახელმწიფო, კერძო და მუნიციპალური განათლება", "სკოლამდელი, ზოგადი და პროფესიული განათლება"]'::jsonb, 'ფორმალური, არაფორმალური და ინფორმალური განათლება', 'Düzgün cavab: C) ფორმალური, არაფორმალური და ინფორმალური განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9b49df33-27ff-42d0-a19e-5bc247479469', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', '“Təhsil haqqında” AR Qanununa əsasən, müxtəlif səbəblərdən ümumi təhsildən kənarda qalmış şəxslərə təhsil almaq və ya təhsilin hər hansı pilləsini vaxtından əvvəl bitirmək hüququ verən təhsilalma forması hansıdır?', 'multiple_choice', '["Qiyabi təhsilalma forması", "Evdə təhsilalma forması", "Distant təhsilalma forması", "Sərbəst (eksternat) təhsilalma forması", "Fərdi təhsilalma forması"]'::jsonb, 'Sərbəst (eksternat) təhsilalma forması', 'Düzgün cavab: D) Sərbəst (eksternat) təhsilalma forması', '', 36, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f2460854-8bb8-4b30-b307-9a507897846a', '9b49df33-27ff-42d0-a19e-5bc247479469', 'ka', 'აზერბაიჯანის რესპუბლიკის კანონის „განათლების შესახებ“ თანახმად, განათლების მიღების რომელი ფორმა აძლევს განათლების მიღების უფლებას იმ პირებს, რომლებიც სხვადასხვა მიზეზით დარჩნენ ზოგადი განათლების მიღმა?', '["ინდივიდუალური განათლების მიღების ფორმა", "დისტანციური განათლების მიღების ფორმა", "შინ სწავლების ფორმა", "ექსტერნატული (თავისუფალი) განათლების მიღების ფორმა", "ინკლუზიური განათლების მიღების ფორმა"]'::jsonb, 'ექსტერნატული (თავისუფალი) განათლების მიღების ფორმა', 'Düzgün cavab: D) ექსტერნატული (თავისუფალი) განათლების მიღების ფორმა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6295ec45-43d9-418a-9315-60bd3b8f9b23', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', '“Təhsil haqqında” AR Qanununun 32-ci maddəsinə əsasən, təhsil prosesi iştirakçılarının vəzifələrinə aid olan müddəa hansıdır?', 'multiple_choice', '["Məktəbin əmlakını icarəyə vermək və əldə olunan gəliri şəxsi məqsədlər üçün istifadə etmək", "Həmkarlar ittifaqının fəaliyyətinə rəhbərlik etmək və təşkilati qərarlar qəbul etmək", "İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını mənimsəmək və daxili intizam qaydalarına riayət etmək", "Müəssisənin ştat cədvəlini və illik maliyyə xərclər smetasını təkbaşına təsdiq etmək", "Tədris planlarını nazirliyin təsdiqi olmadan müstəqil şəkildə dəyişdirmək"]'::jsonb, 'İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını mənimsəmək və daxili intizam qaydalarına riayət etmək', 'Düzgün cavab: C) İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını mən', '', 37, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8b7329d7-84a1-4f49-babb-eac32de90dcd', '6295ec45-43d9-418a-9315-60bd3b8f9b23', 'ka', 'აზერბაიჯანის რესპუბლიკის კანონის „განათლების შესახებ“ 32-ე მუხლის თანახმად, რომელი დებულება მიეკუთვნება პედაგოგთა (განათლების მიმწოდებელთა) მოვალეობებს?', '["საგანმანათლებლო პროგრამების თავისუფლად შეცვლა და სახელმძღვანელოების შერჩევა", "მოსწავლეთა დასწრებაზე კონტროლის სრულად შეწყვეტა", "კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, თანამედროვე სწავლების მეთოდებისა და ისტ-ის დაუფლება და სასწავლო პროცესში გამოყენება", "საგაკვეთილო ცხრილის დამოუკიდებლად შედგენა და დამტკიცება", "მოსწავლეთა მშობლებისგან დამატებითი სწავლის საფასურის მოთხოვნა"]'::jsonb, 'კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, თანამედროვე სწავლების მეთოდებისა და ისტ-ის დაუფლება და სასწავლო პროცესში გამოყენება', 'Düzgün cavab: C) კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილების, თანამედროვე სწავლების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('477d60b5-661d-4189-9ae5-21b302b311d0', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', '“Ümumi təhsil haqqında” AR Qanununa əsasən, ümumi təhsil pilləsinin səviyyələri hansı ardıcıllıqla düzgün göstərilmişdir?', 'multiple_choice', '["Məktəbəqədər təhsil, natamam orta təhsil və orta ixtisas təhsili", "Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)", "Ümumi ibtidai, orta məktəb, gimnaziya və lisey səviyyələri", "İbtidai təhsil, əsas təhsil, peşə liseyi və kollec səviyyəsi", "Erkən inkişaf mərhələsi, ibtidai təhsil, baza təhsili və ali təhsil"]'::jsonb, 'Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)', 'Düzgün cavab: B) Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və ta', '', 38, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1f0e2c29-8207-4776-a913-f6396674ada7', '477d60b5-661d-4189-9ae5-21b302b311d0', 'ka', 'აზერბაიჯანის რესპუბლიკის კანონის „ზოგადი განათლების შესახებ“ თანახმად, რომელ ვარიანტშია სრულად მოცემული ზოგადი განათლების საფეხურების მიხედვით დაყოფა?', '["სკოლამდელი (I–IV), საშუალო (V–X) და სრული (XI–XII)", "სკოლისთვის მომზადების ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული ზოგადი განათლება (X–XI)", "დაწყებითი (I–V), ზოგადი (VI–IX) და პროფესიული (X–XI)", "სამზადისი (0), დაწყებითი (I–IV) და საშუალო (V–XI)", "დაწყებითი (I–III), საშუალო (IV–IX) და უფროსი (X–XII)"]'::jsonb, 'სკოლისთვის მომზადების ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული ზოგადი განათლება (X–XI)', 'Düzgün cavab: B) სკოლისთვის მომზადების ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('359b8c25-6498-4042-b0e4-9393873df87c', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', '“Ümumi təhsil haqqında” AR Qanununun 21-ci maddəsinə əsasən, ümumi təhsil prosesində təhsilalanların hüquqlarına **AİD EDİLMƏYƏN** müddəa hansıdır?', 'multiple_choice', '["Təhlükəsiz və sağlam təhsil şəraiti ilə təmin olunmaq", "Təhsil müəssisəsinin kitabxana və laboratoriyasından pulsuz istifadə etmək", "Dövlət məktəblərində dərsliklərlə pulsuz təmin olunmaq", "Ləyaqətini alçaldan rəftardan müdafiə olunmaq", "Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq"]'::jsonb, 'Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq', 'Düzgün cavab: E) Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoj', '', 39, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d11e4c74-e23e-4dc8-b33d-c36eb66e9bce', '359b8c25-6498-4042-b0e4-9393873df87c', 'ka', 'აზერბაიჯანის რესპუბლიკის კანონის „ზოგადი განათლების შესახებ“ 21-ე მუხლის თანახმად, რომელი დებულება არ მიეკუთვნება ზოგადსაგანმანათლებლო პროცესში მოსწავლეთა უფლებებს?', '["სახელმწიფო სკოლებში სახელმძღვანელოებით უფასო უზრუნველყოფა", "უსაფრთხო და ჯანსაღი საგანმანათლებლო პირობებით უზრუნველყოფა", "საგანმანათლებლო დაწესებულების ბიბლიოთეკითა და ლაბორატორიით უფასო სარგებლობა", "ღირსების შემლახავი მოპყრობისგან დაცვა", "დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება"]'::jsonb, 'დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება', 'Düzgün cavab: E) დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ce4c9d76-cd98-4a93-aec2-84c5c81e0046', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Dövlət və bələdiyyə ümumi təhsil müəssisələrinin Nümunəvi Nizamnaməsinə əsasən, məktəb direktorunun vəzifəyə təyin və vəzifədən azad edilməsi necə həyata keçirilir?', 'multiple_choice', '["Məktəbin Valideyn-Müəllim Assosiasiyası tərəfindən birbaşa seçki yolu ilə", "Məktəb həmkarlar komitəsinin sədri tərəfindən sərəncamla", "Pedaqoji Şuranın gizli səsverməsi və mütləq səs çoxluğu ilə", "Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən qanunvericiliklə müəyyən edilmiş qaydada", "Yerli bələdiyyə orqanının birtərəfli qərarı və təsdiqi ilə"]'::jsonb, 'Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən qanunvericiliklə müəyyən edilmiş qaydada', 'Düzgün cavab: D) Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən qanunveric', '', 40, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0dfd1f41-1fc3-4ab0-b986-f773d4eefe14', 'ce4c9d76-cd98-4a93-aec2-84c5c81e0046', 'ka', 'სახელმწიფო და მუნიციპალური ზოგადსაგანმანათლებლო დაწესებულებების ტიპობრივი წესდების თანახმად, ვინ ახორციელებს სკოლის საქმიანობის მიმდინარე ხელმძღვანელობას?', '["პედაგოგიური საბჭოს მიერ არჩეული თავმჯდომარე", "განათლების სამინისტროს კოლეგიის მიერ არჩეული რწმუნებული", "მუნიციპალიტეტის თავმჯდომარის მიერ დანიშნული წარმომადგენელი", "დირექტორი, რომელსაც თანამდებობაზე ნიშნავს ან სამუშაოზე იღებს შესაბამისი აღმასრულებელი ხელისუფლების ორგანო (განათლების მართვის ორგანო)", "მშობელთა და მასწავლებელთა ასოციაციის თავმჯდომარე"]'::jsonb, 'დირექტორი, რომელსაც თანამდებობაზე ნიშნავს ან სამუშაოზე იღებს შესაბამისი აღმასრულებელი ხელისუფლების ორგანო (განათლების მართვის ორგანო)', 'Düzgün cavab: D) დირექტორი, რომელსაც თანამდებობაზე ნიშნავს ან სამუშაოზე იღებს შესაბამისი აღმასრულ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('907a65bf-a6f4-45e7-a837-c5c68eab62d5', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Ümumi təhsil müəssisələrində Pedaqoji Şura haqqında Əsasnaməyə əsasən, qərarların qəbul edilməsi üçün yetərsay (kvorum) necə müəyyən edilir?', 'multiple_choice', '["Yalnız fənn metodbirləşmə rəhbərlərinin iştirakı ilə mütləq yekdilliklə", "İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilir", "Üzvlərin yarısı iştirak etdikdə və valideyn komitəsinin razılığı olduqda", "Pedaqoji heyətin 90%-i iştirak etdikdə və üçdə iki səs çoxluğu ilə", "Üzvlərin dörddə bir hissəsi iştirak etdikdə və direktor təsdiq etdikdə"]'::jsonb, 'İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilir', 'Düzgün cavab: B) İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qəra', '', 41, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bc4b1fb1-5bf2-465d-a202-415f27e7d5d3', '907a65bf-a6f4-45e7-a837-c5c68eab62d5', 'ka', 'ზოგადსაგანმანათლებლო დაწესებულებებში პედაგოგიური საბჭოს შესახებ დებულების თანახმად, როგორია გადაწყვეტილებების მიღების წესი?', '["მონაწილეობენ მხოლოდ საგნობრივი კათედრების ხელმძღვანელები, გადაწყვეტილებები დირექტორის მიერ არ მტკიცდება", "სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით", "უფლებამოსილია, თუ ესწრება წევრთა ნახევარზე მეტი, გადაწყვეტილებები მიიღება ერთხმად", "უნდა ესწრებოდეს ყველა წევრი, გადაწყვეტილებები მიიღება ხმების 2/3-ის უმრავლესობით", "სხდომა ტარდება ღია კენჭისყრით, გადაწყვეტილებებს აფორმებს პედაგოგიური საბჭოს მდივანი"]'::jsonb, 'სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით', 'Düzgün cavab: B) სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e511e9b6-875b-438d-8a23-45f5471ad168', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Azərbaycan Respublikasının Əmək Məcəlləsinin 89 və 91-ci maddələrinə əsasən, iş vaxtının normal və qısaldılmış müddəti ilə bağlı hansı norma təsbit edilmişdir?', 'multiple_choice', '["Həftəlik iş vaxtı direktor tərəfindən sərbəst müəyyən olunur və məhdudiyyət qoyulmur", "Həftəlik normal iş vaxtı 48 saat, qısaldılmış iş vaxtı isə 42 saat müəyyən edilir", "Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə qısaldılmış iş vaxtı həftədə 36 saatdan artıq ola bilməz", "Bütün işçilər üçün həftəlik iş vaxtı fərq qoyulmadan eyni — 45 saatdır", "Normal iş vaxtı həftədə 35 saat, əlillər üçün isə həftədə 20 saatdır"]'::jsonb, 'Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə qısaldılmış iş vaxtı həftədə 36 saatdan artıq ola bilməz', 'Düzgün cavab: C) Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün i', '', 42, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0e05eb28-7f17-4dbe-9c26-661abd0fd24e', 'e511e9b6-875b-438d-8a23-45f5471ad168', 'ka', 'აზერბაიჯანის რესპუბლიკის შრომის კოდექსის 89-ე და 91-ე მუხლების თანახმად, რომელია სწორი ნორმა სამუშაო დროის ნორმალურ და შემცირებულ ხანგრძლივობასთან დაკავშირებით?', '["ნორმალური სამუშაო დრო შეადგენს 36 საათს, მძიმე სფეროში მომუშავეთათვის — 30 საათს", "ნორმალური სამუშაო დრო შეადგენს 45 საათს, პედაგოგიური მუშაკებისთვის — 30 საათს", "ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისა და ორსული ქალებისთვის — კვირაში 36 საათს", "ნორმალური სამუშაო დრო შეადგენს 40 საათს, 16 წლამდე ასაკის დასაქმებულთათვის — 24 საათს", "ნორმალური სამუშაო დრო შეადგენს 48 საათს, მოზარდებისთვის — 40 საათს"]'::jsonb, 'ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისა და ორსული ქალებისთვის — კვირაში 36 საათს', 'Düzgün cavab: C) ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('277c4bfb-c4d0-48e2-a204-b443b4d4e88e', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Əmək Məcəlləsinin 186-cı maddəsinə əsasən, əmək və icra intizamını pozan işçiyə işəgötürən tərəfindən tətbiq edilə bilən intizam tənbehi tədbirləri hansılardır?', 'multiple_choice', '["Şifahi töhmət, yazılı töhmət, şiddətli töhmət və işdən çıxarma", "İnzibati cərimə, ictimai işlər və müqaviləyə xitam", "Töhmət, maaşın 50% tutulması və vəzifənin aşağı salınması", "Xəbərdarlıq, töhmət, vəzifədən azad etmə və cərimə", "Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi"]'::jsonb, 'Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi', 'Düzgün cavab: E) Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutu', '', 43, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b8124d00-02c6-408d-b2f3-2f50041881f7', '277c4bfb-c4d0-48e2-a204-b443b4d4e88e', 'ka', 'შრომის კოდექსის 186-ე მუხლის თანახმად, რომელი დისციპლინური სახდელები შეიძლება დაეკისროს დასაქმებულს შრომისა და საშემსრულებლო დისციპლინის დარღვევისთვის?', '["ზეპირი საყვედური, წერილობითი საყვედური, მკაცრი საყვედური და სამსახურიდან დათხოვნა", "გაფრთხილება, საყვედური, თანამდებობიდან განთავისუფლება და ჯარიმა", "საყვედური, ხელფასის 50%-ის დაკავება და თანამდებობრივი დაქვეითება", "ადმინისტრაციული ჯარიმა, საზოგადოებრივი სამუშაო და ხელშეკრულების შეწყვეტა", "საყვედური, მკაცრი საყვედური უკანასკნელი გაფრთხილებით, ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა (თუ გათვალისწინებულია კოლექტიური ხელშეკრულებით) და შრომითი ხელშეკრულების შეწყვეტა შრომის კოდექსის 70-ე მუხლის საფუძველზე"]'::jsonb, 'საყვედური, მკაცრი საყვედური უკანასკნელი გაფრთხილებით, ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა (თუ გათვალისწინებულია კოლექტიური ხელშეკრულებით) და შრომითი ხელშეკრულების შეწყვეტა შრომის კოდექსის 70-ე მუხლის საფუძველზე', 'Düzgün cavab: E) საყვედური, მკაცრი საყვედური უკანასკნელი გაფრთხილებით, ჯარიმა ყოველთვიური ხელფასი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('794d7170-12ef-4ee5-b5cd-7ab07b140404', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'AR Əmək Məcəlləsinin 187 və 188-ci maddələrinə əsasən, intizam tənbehinin tətbiqi və qüvvədə olma müddəti qaydası necədir?', 'multiple_choice', '["İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz", "İzahat mütləqdir, tənbeh yalnız 1 ay qüvvədə olur", "İzahat tələb edilmədən tənbeh verilə bilər və 2 il qüvvədə qalır", "İzahat tələb olunmur, tənbeh məhkəmə qərarı ilə 3 il qüvvədə qalır", "İntizam tənbehi verildikdə işçidən izahat alınır və tənbeh verildiyi gündən 1 il qüvvədə qalır"]'::jsonb, 'İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz', 'Düzgün cavab: A) İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbe', '', 44, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7e627c65-6e9b-49a8-9453-213c54a77f3c', '794d7170-12ef-4ee5-b5cd-7ab07b140404', 'ka', 'შრომის კოდექსის 187-ე მუხლის თანახმად, რა მოთხოვნაა დადგენილი დისციპლინური სახდელის დადებასა და მისი მოქმედების ვადასთან დაკავშირებით?', '["დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია მისი დადების დღიდან 1 წლის განმავლობაში, ხოლო თუ 6 თვის განმავლობაში ახალი სახდელი არ დაედება, შეიძლება ვადაზე ადრე მოეხსნას", "ახსნა-განმარტება სავალდებულოა, სახდელი მოქმედებს 3 თვე და ავტომატურად იხსნება", "ახსნა-განმარტება მიიღება მხოლოდ ზეპირად და სახდელი მოქმედებს 6 თვე", "სახდელი შეიძლება დაედოს ახსნა-განმარტების მოთხოვნის გარეშე და ძალაში რჩება 2 წელი", "ახსნა-განმარტება არ მოითხოვება, სახდელი სასამართლოს გადაწყვეტილებით ძალაში რჩება 3 წელი"]'::jsonb, 'დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია მისი დადების დღიდან 1 წლის განმავლობაში, ხოლო თუ 6 თვის განმავლობაში ახალი სახდელი არ დაედება, შეიძლება ვადაზე ადრე მოეხსნას', 'Düzgün cavab: A) დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e655b909-a2b4-43aa-970a-068a8f4502b4', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Əmək Məcəlləsinin 69 və 172-ci maddələrinə əsasən, işçinin öz təşəbbüsü ilə əmək müqaviləsinə xitam verilməsi və son haqq-hesabın ödənilməsi qaydası necədir?', 'multiple_choice', '["İşçi 3 iş günü əvvəl xəbərdarlıq edir, son haqq-hesab 1 ay sonra köçürülür", "İşçi 2 həftə əvvəl şifahi xəbərdarlıq edir, kompensasiya ödənilmir", "İşçi 15 gün əvvəl ərizə verir, haqq-hesab növbəti ayın maaş günündə ödənilir", "İşçi xəbərdarlıq etmədən dərhal işi tərk edir, ödəniş rəhbərliyin qərarı ilə verilir", "İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab sonuncu iş günündən gec olmayaraq tam ödənilir"]'::jsonb, 'İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab sonuncu iş günündən gec olmayaraq tam ödənilir', 'Düzgün cavab: E) İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haq', '', 45, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('fd004e47-ffc7-48da-b928-22eb1bca2f8e', 'e655b909-a2b4-43aa-970a-068a8f4502b4', 'ka', 'შრომის კოდექსის 69-ე და 172-ე მუხლების თანახმად, როგორია დასაქმებულის საკუთარი ინიციატივით შრომითი ხელშეკრულების შეწყვეტის წესი?', '["დასაქმებულს შეუძლია წავიდეს გაფრთხილების გარეშე, საბოლოო ანგარიშსწორება ხდება 10 დღის ვადაში", "დასაქმებული აფრთხილებს ზეპირად 2 კვირით ადრე, ანგარიშსწორება ხდება 7 დღის განმავლობაში", "დასაქმებული განცხადებას წერს 15 დღით ადრე, ანგარიშსწორება ხდება მომდევნო თვის 15 რიცხვში", "დასაქმებული აფრთხილებს 3 სამუშაო დღით ადრე, ანგარიშსწორება ხდება 1 თვის ვადაში", "დასაქმებულმა დამსაქმებელი წერილობითი განცხადებით უნდა გააფრთხილოს 1 კალენდარული თვით ადრე; საბოლოო ანგარიშსწორება სრულად უნდა განხორციელდეს არაუგვიანეს ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღისა"]'::jsonb, 'დასაქმებულმა დამსაქმებელი წერილობითი განცხადებით უნდა გააფრთხილოს 1 კალენდარული თვით ადრე; საბოლოო ანგარიშსწორება სრულად უნდა განხორციელდეს არაუგვიანეს ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღისა', 'Düzgün cavab: E) დასაქმებულმა დამსაქმებელი წერილობითი განცხადებით უნდა გააფრთხილოს 1 კალენდარული', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('02bc43cc-6058-4b19-9ff6-a1033924cfea', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Kompüter şəbəkələrinin əhatə dairəsinə görə LAN və WAN şəbəkələrinin başlıca fərqi nədir?', 'multiple_choice', '["LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir", "LAN-da məlumat ötürmə sürəti çox aşağı, WAN-da isə ifrat yüksək olur", "LAN yalnız simli kabellərlə, WAN isə yalnız simsiz peyk rabitəsi ilə qurulur", "LAN yalnız internetə çıxış üçün, WAN isə lokal resursları paylaşmaq üçündür", "LAN yalnız dövlət orqanlarında, WAN isə kommersiya şirkətlərində istifadə olunur"]'::jsonb, 'LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir', 'Düzgün cavab: A) LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, W', '', 46, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2d4a8d41-408c-4a14-bb33-80401e4b2994', '02bc43cc-6058-4b19-9ff6-a1033924cfea', 'ka', 'რა არის ძირითადი განსხვავება LAN და WAN ქსელებს შორის მოცვის არეალის მიხედვით?', '["LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა, კამპუსი) განთავსებულ კომპიუტერებს, ხოლო WAN არის გლობალური განაწილებული ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს", "LAN იქმნება მხოლოდ სადენიანი, ხოლო WAN — მხოლოდ უსადენო ტექნოლოგიით", "LAN-ში სიჩქარე დაბალია, ხოლო WAN-ში — მაღალი", "LAN განკუთვნილია სახელმწიფო უწყებებისთვის, ხოლო WAN — ინდივიდუალური მომხმარებლებისთვის", "LAN გამოიყენება ინტერნეტთან წვდომისთვის, ხოლო WAN — ლოკალური რესურსების გასაზიარებლად"]'::jsonb, 'LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა, კამპუსი) განთავსებულ კომპიუტერებს, ხოლო WAN არის გლობალური განაწილებული ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს', 'Düzgün cavab: A) LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა, კამპუსი) განთა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0703a610-3bac-4406-9613-11c683dfeb38', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'İnternet şəbəkəsində domen adlarını IP ünvanlarına çevirən əsas xidmət və protokol hansıdır?', 'multiple_choice', '["DNS (Domain Name System)", "ARP (Address Resolution Protocol)", "DHCP (Dynamic Host Configuration Protocol)", "Proxy Service", "NAT (Network Address Translation)"]'::jsonb, 'DNS (Domain Name System)', 'Düzgün cavab: A) DNS (Domain Name System)', '', 47, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('18302964-f9db-4ac8-9dc2-b1b3760b69eb', '0703a610-3bac-4406-9613-11c683dfeb38', 'ka', 'რომელია ქსელის ძირითადი სერვისი, რომელიც ინტერნეტში დომენურ სახელებს IP მისამართებად გარდაქმნის?', '["DNS (Domain Name System) — დომენური სახელების განაწილებული იერარქიული სისტემა", "ARP (Address Resolution Protocol) — MAC მისამართის განსაზღვრის სისტემა", "DHCP (Dynamic Host Configuration Protocol) — დინამიკური IP განაწილების სისტემა", "Proxy Service — შუალედური ქეშირებისა და ფილტრაციის სისტემა", "NAT (Network Address Translation) — ქსელური მისამართების გარდაქმნის სისტემა"]'::jsonb, 'DNS (Domain Name System) — დომენური სახელების განაწილებული იერარქიული სისტემა', 'Düzgün cavab: A) DNS (Domain Name System) — დომენური სახელების განაწილებული იერარქიული სისტემა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d827417f-22e3-4446-8fdb-f12c7997a34d', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'İnformasiya təhlükəsizliyində ''İki faktorlu autentifikasiya'' (2FA) istifadəsinin başlıca məqsədi nədir?', 'multiple_choice', '["Kompüterin əməliyyat sistemini viruslardan tam qorumaq", "Şifrənin unudulduğu halda avtomatik bərpasını təmin etmək", "Şəbəkədə internet sürətini iki dəfə artırmaq", "Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək", "Faylların bulud yaddaşına ikiqat sürətlə yüklənməsini təmin etmək"]'::jsonb, 'Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək', 'Düzgün cavab: D) Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifi', '', 48, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2953a77d-f4c4-40eb-abef-99a88cc463fd', 'd827417f-22e3-4446-8fdb-f12c7997a34d', 'ka', 'რა არის „ორფაქტორიანი ავთენტიფიკაციის“ (2FA) მექანიზმის მთავარი უპირატესობა ინფორმაციულ უსაფრთხოებაში?', '["ოპერაციული სისტემის განახლებების ავტომატური ინსტალაცია", "ფაილების ავტომატური არქივაცია და მეხსიერების დაზოგვა", "ინტერნეტის სიჩქარის გაზრდა და დაშიფვრის პროცესის დაჩქარება", "პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დამადასტურებელი საშუალების (SMS კოდი, TOTP, ავთენტიფიკატორის აპლიკაცია ან FIDO2 გასაღები) გარეშე", "მომხმარებლის მიერ ერთდროულად რამდენიმე მოწყობილობიდან შესვლის შეზღუდვა"]'::jsonb, 'პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დამადასტურებელი საშუალების (SMS კოდი, TOTP, ავთენტიფიკატორის აპლიკაცია ან FIDO2 გასაღები) გარეშე', 'Düzgün cavab: D) პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2c9139fb-1282-4257-ae74-ecd96700de6d', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Fırıldaqçıların etibarlı təşkilat adından saxta e-poçt göndərərək istifadəçinin məxfi məlumatlarını ələ keçirməsi hansı kiberhücum növüdür?', 'multiple_choice', '["Sniffing", "Fişinq (Phishing)", "Spoofing", "Brute Force", "Ransomware"]'::jsonb, 'Fişinq (Phishing)', 'Düzgün cavab: B) Fişinq (Phishing)', '', 49, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('10f340c0-b992-4320-84cc-3eb08abc90a7', '2c9139fb-1282-4257-ae74-ecd96700de6d', 'ka', 'კიბერთავდასხმის რომელი სახეობაა, როდესაც თაღლითები სანდო ორგანიზაციის სახელით ყალბ ელფოსტას აგზავნიან პერსონალური მონაცემების მისაკუთრების მიზნით?', '["Sniffing — ქსელური ტრაფიკის ფარული მოსმენის შეტევა", "ფიშინგი (Phishing) — სოციალურ ინჟინერიაზე დაფუძნებული საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტების მეშვეობით", "Spoofing — IP ან MAC მისამართის გაყალბების შეტევა", "Ransomware — ფაილების დაშიფვრა და გამოსასყიდის მოთხოვნა (გამომძალველი პროგრამა)", "Brute Force — პაროლის შერჩევა მასიური გადარჩევის გზით"]'::jsonb, 'ფიშინგი (Phishing) — სოციალურ ინჟინერიაზე დაფუძნებული საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტების მეშვეობით', 'Düzgün cavab: B) ფიშინგი (Phishing) — სოციალურ ინჟინერიაზე დაფუძნებული საიდენტიფიკაციო მონაცემები', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('525b11cc-bdd0-4332-a5eb-7759bc5d2009', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Microsoft Word proqramında abzasın girintilərini dəqiq tənzimləmək üçün hansı alətdən istifadə olunur?', 'multiple_choice', '["Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi", "Şaquli xətkeş və səhifə nömrələmə aləti", "Naviqasiya paneli və axtarış pəncərəsi", "Sürətli müraciət paneli və stil qalereyası", "Vəziyyət zolağı və miqyas sürüşdürücüsü"]'::jsonb, 'Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi', 'Düzgün cavab: A) Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph', '', 50, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('5777ebc0-a1c5-454d-8fd4-9668096dcb0c', '525b11cc-bdd0-4332-a5eb-7759bc5d2009', 'ka', 'ინტერფეისის რომელი ელემენტი გამოიყენება Microsoft Word-ში აბზაცის კიდეების (აბზაცის შეწევის) ზუსტად დასარეგულირებლად?', '["ჰორიზონტალურ სახაზავზე (Horizontal Ruler) განთავსებული შეწევის სლაიდერები და Paragraph დიალოგური ფანჯარა", "ნავიგაციის პანელი და ძიების ველი", "სტატუსის ზოლი და მასშტაბირების სლაიდერი", "სწრაფი წვდომის პანელი და ლენტის (Ribbon) ინტერფეისი", "ვერტიკალური სახაზავი და გვერდის ველები"]'::jsonb, 'ჰორიზონტალურ სახაზავზე (Horizontal Ruler) განთავსებული შეწევის სლაიდერები და Paragraph დიალოგური ფანჯარა', 'Düzgün cavab: A) ჰორიზონტალურ სახაზავზე (Horizontal Ruler) განთავსებული შეწევის სლაიდერები და Par', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ba1b8e00-cd14-4467-98b4-345c0efc6a0f', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Microsoft Word sənədində bəzi səhifələri şaquli, bəzi səhifələri isə üfüqi (albom) etmək üçün hansı əməliyyat icra olunmalıdır?', 'multiple_choice', '["Səhifə kənar boşluqları dəyişdirilərək üfüqi effekt yaradılmalıdır", "Hər səhifə üçün ayrıca Page Break əlavə edilib oriyentasiya dəyişdirilməlidir", "Sənəd iki ayrı fayla bölünüb hər birinin oriyentasiyası ayrıca təyin edilməlidir", "Mətn qutuları istifadə edilərək səhifə fırladılmalıdır", "Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir"]'::jsonb, 'Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir', 'Düzgün cavab: E) Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin O', '', 51, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('28c44b49-bf73-4014-9365-5b33156c5694', 'ba1b8e00-cd14-4467-98b4-345c0efc6a0f', 'ka', 'რა ოპერაცია უნდა შესრულდეს Microsoft Word-ის დოკუმენტში ზოგიერთი გვერდის ვერტიკალურ (წიგნისებურ), ხოლო ზოგიერთის ჰორიზონტალურ (ალბომურ) ორიენტაციაში დასაფორმატებლად?', '["დოკუმენტი უნდა გაიყოს ორ ცალკე ფაილად და თითოეულის ორიენტაცია ცალ-ცალკე განისაზღვროს", "გვერდის ველები უნდა შეიცვალოს ჰორიზონტალური ეფექტის შესაქმნელად", "თითოეული გვერდისთვის ცალკე უნდა დაემატოს Page Break და შეიცვალოს ორიენტაცია", "ტექსტური ველების (Text Box) გამოყენებით გვერდი უნდა შემოტრიალდეს", "დოკუმენტში უნდა ჩაისვას სექციის წყვეტა (Section Break - Next Page) და ამ სექციისთვის შეიცვალოს Layout > Orientation პარამეტრი"]'::jsonb, 'დოკუმენტში უნდა ჩაისვას სექციის წყვეტა (Section Break - Next Page) და ამ სექციისთვის შეიცვალოს Layout > Orientation პარამეტრი', 'Düzgün cavab: E) დოკუმენტში უნდა ჩაისვას სექციის წყვეტა (Section Break - Next Page) და ამ სექციის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b1a61343-2a8e-4192-856d-23a85c40272a', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Microsoft Word proqramında başlıqlara əsasən avtomatik yenilənən Mündəricat yaratmaq üçün hansı taba müraciət edilir?', 'multiple_choice', '["Layout > Table of Contents", "References (İstinadlar) tabı > Table of Contents", "Review > Table of Contents", "Insert > Table of Contents", "View > Navigation Pane"]'::jsonb, 'References (İstinadlar) tabı > Table of Contents', 'Düzgün cavab: B) References (İstinadlar) tabı > Table of Contents', '', 52, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('76d81e9c-f4d6-4ac6-8d9e-f4de2fc2793b', 'b1a61343-2a8e-4192-856d-23a85c40272a', 'ka', 'რომელ ჩანართს (Tab) უნდა მივმართოთ Microsoft Word-ში სათაურებზე დაფუძნებული ავტომატურად განახლებადი სარჩევის შესაქმნელად?', '["View > Navigation Pane", "References (მიმართვები/სქოლიოები) ჩანართი > Table of Contents ჯგუფი", "Layout > Table of Contents", "Insert > Table of Contents", "Review > Table of Contents"]'::jsonb, 'References (მიმართვები/სქოლიოები) ჩანართი > Table of Contents ჯგუფი', 'Düzgün cavab: B) References (მიმართვები/სქოლიოები) ჩანართი > Table of Contents ჯგუფი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ac09692d-67b9-435c-b9e3-9a0c7b92427d', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Microsoft Excel cədvəlində `$C$2` mütləq xana ünvanı olan düstur başqa xanalara kopyalandıqda necə dəyişir?', 'multiple_choice', '["Yalnız sütun sabit qalır, sətir dəyişir", "Yalnız sətir sabit qalır, sütun dəyişir", "Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır", "Düstur xəta verir və #REF! qaytarır", "Həm sütun, həm sətir avtomatik sürüşür"]'::jsonb, 'Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', 'Düzgün cavab: C) Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', '', 53, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8a0bb9d1-2995-4acb-b457-8f1f25dee408', 'ac09692d-67b9-435c-b9e3-9a0c7b92427d', 'ka', 'როგორ შეიცვლება Microsoft Excel-ის ცხრილში ფორმულა, რომელიც შეიცავს $C$2 აბსოლუტურ მისამართს, სხვა უჯრებში კოპირებისას?', '["სვეტიც და სტრიქონიც ავტომატურად გადაადგილდება (ფარდობითი მიმართვა)", "ფორმულა დააბრუნებს შეცდომას #REF!", "ვინაიდან დოლარის $ ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი (აბსოლუტური) რჩება", "მხოლოდ სტრიქონი რჩება უცვლელი, სვეტი იცვლება", "მხოლოდ სვეტი რჩება უცვლელი, სტრიქონი იცვლება (შერეული მიმართვა)"]'::jsonb, 'ვინაიდან დოლარის $ ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი (აბსოლუტური) რჩება', 'Düzgün cavab: C) ვინაიდან დოლარის $ ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d0942f14-3ed8-42b6-9bd5-179694529885', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Microsoft Excel proqramında `A1:A10` diapazonunda yalnız qiyməti 50-dən böyük olan xanaların sayını hesablamaq üçün hansı funksiya düzgündür?', 'multiple_choice', '["=IF(A1:A10>50; COUNT(A1:A10))", "=SUMIF(A1:A10; \">50\")", "=COUNTIFS(A1:A10; \">50\")", "=COUNTIF(A1:A10; \">50\")", "=COUNTIF(A1:A10; >50)"]'::jsonb, '=COUNTIF(A1:A10; ">50")', 'Düzgün cavab: D) =COUNTIF(A1:A10; ">50")', '', 54, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b410f362-ec3c-459f-a9a0-b6c9d02bdc83', 'd0942f14-3ed8-42b6-9bd5-179694529885', 'ka', 'რომელი ფუნქციაა სწორი Microsoft Excel-ში A1:A10 დიაპაზონში მხოლოდ იმ უჯრების რაოდენობის დასათვლელად, რომელთა მნიშვნელობა 50-ზე მეტია?', '["=COUNTIFS(A1:A10;\">50\") — პირობითი დათვლა რამდენიმე კრიტერიუმით", "=SUMIF(A1:A10;\">50\") — პირობითი ჯამი", "=COUNTIF(A1:A10;>50) — ჩანაწერი ბრჭყალების გარეშე", "=COUNTIF(A1:A10;\">50\")", "=IF(A1:A10>50;COUNT(A1:A10)) — მასივის ფორმულა"]'::jsonb, '=COUNTIF(A1:A10;">50")', 'Düzgün cavab: D) =COUNTIF(A1:A10;">50")', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0e5f08e0-e063-4dc9-894d-0a81b974b011', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Microsoft Excel-də B2 xanasındakı əməkhaqqı 800-dən çox olduqda 15% mükafat, əks halda 5% hesablayan düstur hansıdır?', 'multiple_choice', '["=IF(B2>800; B2*0.15; B2*0.05)", "=IF(B2>=800; B2*0.15; B2*0.05)", "=IFS(B2>800; B2*0.15; TRUE; B2*0.05)", "=SWITCH(B2>800; TRUE; B2*0.15; FALSE; B2*0.05)", "=IF(B2>800; B2*15%; B2*5%)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: A) =IF(B2>800; B2*0.15; B2*0.05)', '', 55, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e47fab2e-3294-416e-8b46-52c5265f0a4d', '0e5f08e0-e063-4dc9-894d-0a81b974b011', 'ka', 'რომელი ფორმულა ითვლის Microsoft Excel-ში 15%-იან პრემიას, თუ B2 უჯრაში ხელფასი 800-ზე მეტია, ხოლო წინააღმდეგ შემთხვევაში — 5%-ს?', '["=IF(B2>800; B2*0.15; B2*0.05)", "=IF(B2>800; B2*15%; B2*5%) — პროცენტის განსხვავებული ფორმატი", "=IFS(B2>800; B2*0.15; TRUE; B2*0.05) — ახალი ფუნქციით", "=IF(B2>=800; B2*0.15; B2*0.05) — ზღვრის ჩათვლით", "=SWITCH(B2>800; TRUE; B2*0.15; FALSE; B2*0.05) — გადართვის ფუნქცია"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: A) =IF(B2>800; B2*0.15; B2*0.05)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5d1aa87d-b317-4255-9ce7-f84aef5be53c', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Microsoft Excel proqramında xanaya yalnız müəyyən diapazonda ədədlərin daxil edilməsinə icazə verən alət hansıdır?', 'multiple_choice', '["Group and Outline", "Conditional Formatting", "Data Consolidation", "Filter & Sort", "Data Validation (Verilənlərin yoxlanılması)"]'::jsonb, 'Data Validation (Verilənlərin yoxlanılması)', 'Düzgün cavab: E) Data Validation (Verilənlərin yoxlanılması)', '', 56, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('44f068a8-5c5b-4dc1-8b21-1f57e50d143a', '5d1aa87d-b317-4255-9ce7-f84aef5be53c', 'ka', 'რომელია ინსტრუმენტი Microsoft Excel-ში, რომელიც უჯრაში მხოლოდ განსაზღვრული დიაპაზონის რიცხვების შეყვანის საშუალებას იძლევა?', '["Data Consolidation — მონაცემთა კონსოლიდაცია", "Group — დაჯგუფებით დაცვა", "Conditional Formatting — პირობითი ფორმატირებით შეზღუდვა", "Filter — ფილტრაციით დაშვება", "Data Validation (მონაცემთა ვალიდაცია/შემოწმება) — Data ჩანართში Whole Number, List, Date კრიტერიუმებით"]'::jsonb, 'Data Validation (მონაცემთა ვალიდაცია/შემოწმება) — Data ჩანართში Whole Number, List, Date კრიტერიუმებით', 'Düzgün cavab: E) Data Validation (მონაცემთა ვალიდაცია/შემოწმება) — Data ჩანართში Whole Number, Li', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('84e6e860-15f1-42ac-950c-12a8d7f5a223', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Microsoft PowerPoint proqramında bütün slaydların vahid dizayn şablonunu dəyişmək üçün hansı rejimdən istifadə olunur?', 'multiple_choice', '["Slide Master (Slayd Ustası)", "Slide Sorter", "Reading View", "Notes Master", "Outline View"]'::jsonb, 'Slide Master (Slayd Ustası)', 'Düzgün cavab: A) Slide Master (Slayd Ustası)', '', 57, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('79982081-7e82-4e7a-a862-2fc39efec12b', '84e6e860-15f1-42ac-950c-12a8d7f5a223', 'ka', 'რომელი რეჟიმი გამოიყენება Microsoft PowerPoint-ში ყველა სლაიდის ერთიანი დიზაინის შაბლონის შესაცვლელად?', '["Slide Master (სლაიდების ნიმუში / Master) — View ჩანართში Master Views ჯგუფი", "Reading View — კითხვის რეჟიმი", "Slide Sorter — სლაიდების დამხარისხებელი რეჟიმი", "Outline View — სტრუქტურის რეჟიმი", "Notes Master — შენიშვნების ნიმუშის რეჟიმი"]'::jsonb, 'Slide Master (სლაიდების ნიმუში / Master) — View ჩანართში Master Views ჯგუფი', 'Düzgün cavab: A) Slide Master (სლაიდების ნიმუში / Master) — View ჩანართში Master Views ჯგუფი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f3b96d1d-a9da-4ee6-981a-adf82b577138', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Microsoft PowerPoint-də ''Transition'' ilə ''Animation'' arasındakı əsas fərq nədir?', 'multiple_choice', '["Transition səs effekti, Animation vizual effektdir", "Hər ikisi eyni funksiyadır, sadəcə adları fərqlidir", "Transition obyektlərə, Animation slaydlara tətbiq olunur", "Transition avtomatik, Animation əl ilə işə düşür", "Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir"]'::jsonb, 'Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir', 'Düzgün cavab: E) Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation i', '', 58, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ce4b66fc-6c5c-4712-96a0-aae72afc4c26', 'f3b96d1d-a9da-4ee6-981a-adf82b577138', 'ka', 'რა არის მთავარი განსხვავება „Transition“-სა და „Animation“-ს შორის Microsoft PowerPoint-ში?', '["ორივე ერთი და იგივე ფუნქციაა, მხოლოდ სახელწოდებებია განსხვავებული", "Transition ირთვება ავტომატურად, ხოლო Animation — ხელით", "Transition არის ხმოვანი ეფექტი, ხოლო Animation — ვიზუალური ეფექტი", "Transition გამოიყენება ობიექტებისთვის, ხოლო Animation — სლაიდებისთვის", "Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animation — უშუალოდ სლაიდზე არსებული კონკრეტული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი"]'::jsonb, 'Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animation — უშუალოდ სლაიდზე არსებული კონკრეტული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი', 'Düzgün cavab: E) Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animat', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('914b15c3-b1ff-4a7b-ae0d-7425b4942267', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Bulud saxlama xidmətlərində sənəd üzərində birgə işləyərkən əvvəlki dəyişikliklərə qayıtmaq üçün hansı funksiyadan istifadə olunur?', 'multiple_choice', '["Backup and Restore", "Version History (Versiya tarixçəsi)", "Sync History", "File Recovery", "Activity Log"]'::jsonb, 'Version History (Versiya tarixçəsi)', 'Düzgün cavab: B) Version History (Versiya tarixçəsi)', '', 59, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c4307c01-fca4-4bda-81ad-dd84e30a49ef', '914b15c3-b1ff-4a7b-ae0d-7425b4942267', 'ka', 'რომელი ფუნქცია გამოიყენება ღრუბლოვან საცავებში დოკუმენტზე ერთობლივი მუშაობისას წინა ცვლილებებზე დასაბრუნებლად?', '["Sync History — სინქრონიზაციის ისტორია", "Version History (ვერსიების ისტორია) — File > Info > Version History ან ისტორია OneDrive-სა და SharePoint-ში", "File Recovery — ფაილის აღდგენის ინსტრუმენტი", "Backup and Restore — სარეზერვო კოპირებისა და აღდგენის ინსტრუმენტი", "Activity Log — აქტივობების ჟურნალი"]'::jsonb, 'Version History (ვერსიების ისტორია) — File > Info > Version History ან ისტორია OneDrive-სა და SharePoint-ში', 'Düzgün cavab: B) Version History (ვერსიების ისტორია) — File > Info > Version History ან ისტორია O', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('87cef00b-5234-488b-98fb-5e36d6869138', 'f3da680f-d247-4f8e-a0c2-168d1830fa85', 'Süni intellekt əsaslı generativ modellərdə ''Hallüsinasiya'' riski nəyi ifadə edir?', 'multiple_choice', '["Modelin yalnız ingilis dilində cavab verib digər dilləri dəstəkləməməsini", "Modelin kompüterin resurslarını həddindən artıq yükləməsini", "Modelin istifadəçi sorğusunu başa düşmədən təsadüfi cavab verməsini", "Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları və ya mənbələri tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini", "Modelin cavab verməkdən imtina etməsini və xəta qaytarmasını"]'::jsonb, 'Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları və ya mənbələri tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini', 'Düzgün cavab: D) Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadl', '', 60, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9a685319-1ddf-4be1-be73-59656b0de974', '87cef00b-5234-488b-98fb-5e36d6869138', 'ka', 'რას გამოხატავს ხელოვნურ ინტელექტზე დაფუძნებულ გენერაციულ მოდელებში „ჰალუცინაციის“ (Hallucination) რისკი?', '["მოდელის მიერ მომხმარებლის მოთხოვნის გაუგებრად შემთხვევითი პასუხის გაცემას", "მოდელის მიერ პასუხის გაცემაზე უარის თქმასა და შეცდომის დაბრუნებას", "მოდელის მიერ კომპიუტერული რესურსების ზედმეტად გადატვირთვას", "მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ციტატებისა თუ წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით", "მოდელის მიერ მხოლოდ ინგლისურ ენაზე პასუხის გაცემას და სხვა ენების მხარდაჭერის არქონას"]'::jsonb, 'მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ციტატებისა თუ წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით', 'Düzgün cavab: D) მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციის, ციტატების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7ecc8b05-6cc9-452e-80b7-5cbc5351d1f0', '1376be74-0955-43c4-8e90-ec089c9261db', '“Psixoloji yardım haqqında” AR Qanununun 4-cü maddəsinə əsasən, psixoloji yardımın əsas prinsiplərinə **AİD EDİLMƏYƏN** qeyri-qanuni fəaliyyət hansıdır?', 'multiple_choice', '["Psixoloji yardım alan şəxsin fərdi razılığı olmadan, qanunla müəyyən edilmiş hallar istisna olmaqla, onun şəxsi sirlərinin, konfidensial məlumatlarının açıqlanması və yayılması", "İnsan və vətəndaş hüquq və azadlıqlarına tam hörmət edilməsi", "Psixoloji yardımın elmilik və peşəkar səriştəlilik meyarlarına uyğun təşkili", "Psixoloji xidmətin humanizm və peşəkar qərəzsizlik prinsiplərinə əsaslanması", "Psixoloji yardımın könüllülük və məxfilik (konfidensiallıq) əsasında göstərilməsi"]'::jsonb, 'Psixoloji yardım alan şəxsin fərdi razılığı olmadan, qanunla müəyyən edilmiş hallar istisna olmaqla, onun şəxsi sirlərinin, konfidensial məlumatlarının açıqlanması və yayılması', 'Düzgün cavab: A) Psixoloji yardım alan şəxsin fərdi razılığı olmadan, qanunla müəyyən edilmiş hal', '', 1, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a17dfe23-b373-425b-ac03-483f674d575f', '7ecc8b05-6cc9-452e-80b7-5cbc5351d1f0', 'ka', '„ფსიქოლოგიური დახმარების შესახებ“ კანონის მე-4 მუხლის თანახმად, რომელი უკანონო ქმედება არ განეკუთვნება ფსიქოლოგიური დახმარების ძირითად პრინციპებს?', '["ფსიქოლოგიური დახმარების მიმღები პირის ინდივიდუალური თანხმობის გარეშე, კანონით დადგენილი შემთხვევების გარდა, მისი პირადი საიდუმლოებებისა და კონფიდენციალური ინფორმაციის გამჟღავნება და გავრცელება", "ფსიქოლოგიური დახმარების ორგანიზება მეცნიერულობისა და პროფესიული კომპეტენტურობის კრიტერიუმების შესაბამისად", "ადამიანისა და მოქალაქის უფლებებისა და თავისუფლებების სრული პატივისცემა", "ფსიქოლოგიური დახმარების გაწევა ნებაყოფლობითობისა და კონფიდენციალურობის საფუძველზე", "ფსიქოლოგიური მომსახურების დაფუძნება ჰუმანიზმისა და პროფესიული მიუკერძოებლობის პრინციპებზე"]'::jsonb, 'ფსიქოლოგიური დახმარების მიმღები პირის ინდივიდუალური თანხმობის გარეშე, კანონით დადგენილი შემთხვევების გარდა, მისი პირადი საიდუმლოებებისა და კონფიდენციალური ინფორმაციის გამჟღავნება და გავრცელება', 'Düzgün cavab: A) ფსიქოლოგიური დახმარების მიმღები პირის ინდივიდუალური თანხმობის გარეშე, კანონით და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3c074979-38ce-4458-9006-c723c3b5cf32', '1376be74-0955-43c4-8e90-ec089c9261db', '“Psixoloji yardım haqqında” AR Qanununa əsasən, məktəb psixoloqu hansı müstəsna halda konfidensiallıq prinsipindən kənara çıxa bilər?', 'multiple_choice', '["Fənn müəllimi şagirdin xarakterik xüsusiyyətləri barədə ümumi məlumat almaq istədikdə", "Valideyn müəllimin pedaqoji fəaliyyətindən narazılıq edib psixoloqa müraciət etdikdə", "Şagirdin dərs davamiyyətində zəiflik və fənn qiymətlərində geriləmə müşahidə olunduqda", "Şagirdin və ya ətrafdakıların həyat və sağlamlığına real, bilavasitə təhlükə yarandıqda, özünəqəsd riski və ya cinayət faktı aşkar edildikdə, zəruri instansiyaları məlumatlandırmaqla", "Şagird məktəbdənkənar tədbirlərdə və ya idman yarışlarında iştirak etməkdən imtina etdikdə"]'::jsonb, 'Şagirdin və ya ətrafdakıların həyat və sağlamlığına real, bilavasitə təhlükə yarandıqda, özünəqəsd riski və ya cinayət faktı aşkar edildikdə, zəruri instansiyaları məlumatlandırmaqla', 'Düzgün cavab: D) Şagirdin və ya ətrafdakıların həyat və sağlamlığına real, bilavasitə təhlükə yar', '', 2, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c14bcb79-6e1d-4532-ab1c-00dd3ee8c979', '3c074979-38ce-4458-9006-c723c3b5cf32', 'ka', '„ფსიქოლოგიური დახმარების შესახებ“ კანონის თანახმად, რა გამონაკლის შემთხვევაში შეუძლია სკოლის ფსიქოლოგს გადაუხვიოს კონფიდენციალურობის პრინციპს?', '["როდესაც საგნის მასწავლებელს სურს მიიღოს ზოგადი ინფორმაცია მოსწავლის ხასიათის თავისებურებების შესახებ", "როდესაც მოსწავლე უარს ამბობს კლასგარეშე ღონისძიებებში ან სპორტულ შეჯიბრებებში მონაწილეობაზე", "როდესაც მშობელი გამოხატავს უკმაყოფილებას მასწავლებლის პედაგოგიური საქმიანობით და მიმართავს ფსიქოლოგს", "როდესაც იქმნება რეალური, პირდაპირი საფრთხე მოსწავლის ან გარშემომყოფთა სიცოცხლესა და ჯანმრთელობაზე, თვითდაზიანების/თვითმკვლელობის რისკის ან დანაშაულის ფაქტის გამოვლენისას, შესაბამისი ინსტანციების ინფორმირებით", "როდესაც მოსწავლის გაკვეთილებზე დასწრება სუსტდება და საგნობრივ ნიშნებში ჩამორჩენა შეიმჩნევა"]'::jsonb, 'როდესაც იქმნება რეალური, პირდაპირი საფრთხე მოსწავლის ან გარშემომყოფთა სიცოცხლესა და ჯანმრთელობაზე, თვითდაზიანების/თვითმკვლელობის რისკის ან დანაშაულის ფაქტის გამოვლენისას, შესაბამისი ინსტანციების ინფორმირებით', 'Düzgün cavab: D) როდესაც იქმნება რეალური, პირდაპირი საფრთხე მოსწავლის ან გარშემომყოფთა სიცოცხლესა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('277ecdf4-b152-4c94-a1fe-64e2dfecf77e', '1376be74-0955-43c4-8e90-ec089c9261db', 'BMT-nin “Uşaq hüquqları haqqında” Konvensiyasına görə, uşaqlara münasibətdə qərarlarda əsas rəhbər meyar nə olmalıdır?', 'multiple_choice', '["İntizam qaydalarını pozan şagirdlərə qarşı inzibati sanksiyaların sərtləşdirilməsi", "Uşağın ən yaxşı (ali) maraqlarının, təhlükəsizliyinin və hərtərəfli fiziki, əqli, mənəvi və sosial inkişafının təmin olunması", "Təhsil müəssisəsinin illik büdcə qənaəti və ştat cədvəlinin optimallaşdırılması", "Yalnız valideynlərin fərdi mülahizələri və şəxsi sosial statusu", "Təhsil müəssisəsinin regional reytinq göstəricilərinin yüksək saxlanılması"]'::jsonb, 'Uşağın ən yaxşı (ali) maraqlarının, təhlükəsizliyinin və hərtərəfli fiziki, əqli, mənəvi və sosial inkişafının təmin olunması', 'Düzgün cavab: B) Uşağın ən yaxşı (ali) maraqlarının, təhlükəsizliyinin və hərtərəfli fiziki, əqli', '', 3, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bb9c922d-fa03-45c0-a160-d518e820912b', '277ecdf4-b152-4c94-a1fe-64e2dfecf77e', 'ka', 'გაეროს „ბავშვის უფლებათა კონვენციის“ თანახმად, რა უნდა იყოს ძირითადი სახელმძღვანელო კრიტერიუმი ბავშვებთან დაკავშირებული გადაწყვეტილებების მიღებისას?', '["ადმინისტრაციული სანქციების გამკაცრება იმ მოსწავლეების მიმართ, რომლებიც არღვევენ დისციპლინურ წესებს", "ბავშვის საუკეთესო (უპირატესი) ინტერესების, უსაფრთხოებისა და მისი ყოველმხრივი ფიზიკური, გონებრივი, სულიერი და სოციალური განვითარების უზრუნველყოფა", "მხოლოდ მშობლების ინდივიდუალური შეხედულებები და პირადი სოციალური სტატუსი", "საგანმანათლებლო დაწესებულების რეგიონული სარეიტინგო მაჩვენებლების მაღალ დონეზე შენარჩუნება", "საგანმანათლებლო დაწესებულების წლიური ბიუჯეტის დაზოგვა და საშტატო განრიგის ოპტიმიზაცია"]'::jsonb, 'ბავშვის საუკეთესო (უპირატესი) ინტერესების, უსაფრთხოებისა და მისი ყოველმხრივი ფიზიკური, გონებრივი, სულიერი და სოციალური განვითარების უზრუნველყოფა', 'Düzgün cavab: B) ბავშვის საუკეთესო (უპირატესი) ინტერესების, უსაფრთხოებისა და მისი ყოველმხრივი ფიზ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('da38ab40-9577-4ea2-9e1a-2cf4c1295831', '1376be74-0955-43c4-8e90-ec089c9261db', 'Ümumi təhsil müəssisəsində çalışan psixoloqun vəzifə səlahiyyətlərinə **AİD OLMAYAN** sahə hansıdır?', 'multiple_choice', '["Şagirdlərin təhsil mühitinə psixoloji adaptasiyasına və peşə seçiminə dəstək vermək", "Şagirdlərə klinik psixiatrik diaqnoz (F-kodlu) qoymaq, tibbi-farmakoloji müalicə və dərman preparatları təyin etmək", "Təlim və davranış çətinlikləri olan şagirdlərlə psixokorreksiya və inkişafetdirici məşğələlər keçmək", "Şagirdlərin fərdi və yaş inkişaf xüsusiyyətlərinin psixodiaqnostikasını aparmaq", "Pedaqoji kollektiv və valideynlər arasında psixoloji maarifləndirmə işi təşkil etmək"]'::jsonb, 'Şagirdlərə klinik psixiatrik diaqnoz (F-kodlu) qoymaq, tibbi-farmakoloji müalicə və dərman preparatları təyin etmək', 'Düzgün cavab: B) Şagirdlərə klinik psixiatrik diaqnoz (F-kodlu) qoymaq, tibbi-farmakoloji müalicə', '', 4, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('61b9d70a-0cda-454d-918e-232a7b79f309', 'da38ab40-9577-4ea2-9e1a-2cf4c1295831', 'ka', 'რომელი სფერო არ განეკუთვნება ზოგადსაგანმანათლებლო დაწესებულებაში მომუშავე ფსიქოლოგის სამსახურებრივ უფლებამოსილებას?', '["სწავლისა და ქცევის სირთულეების მქონე მოსწავლეებთან ფსიქოკორექციული და განმავითარებელი მეცადინეობების ჩატარება", "მოსწავლეებისთვის კლინიკური ფსიქიატრიული დიაგნოზის (F-კოდით) დასმა, სამედიცინო-ფარმაკოლოგიური მკურნალობისა და მედიკამენტების დანიშვნა და რეცეპტის გამოწერა", "მოსწავლეთა ინდივიდუალური და ასაკობრივი განვითარების თავისებურებების ფსიქოდიაგნოსტიკის ჩატარება", "საგანმანათლებლო გარემოსთან მოსწავლეთა ფსიქოლოგიური ადაპტაციისა და პროფესიული ორიენტაციის მხარდაჭერა", "პედაგოგიურ კოლექტივსა და მშობლებს შორის ფსიქოლოგიური საგანმანათლებლო-საინფორმაციო მუშაობის ორგანიზება"]'::jsonb, 'მოსწავლეებისთვის კლინიკური ფსიქიატრიული დიაგნოზის (F-კოდით) დასმა, სამედიცინო-ფარმაკოლოგიური მკურნალობისა და მედიკამენტების დანიშვნა და რეცეპტის გამოწერა', 'Düzgün cavab: B) მოსწავლეებისთვის კლინიკური ფსიქიატრიული დიაგნოზის (F-კოდით) დასმა, სამედიცინო-ფა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fbc04907-1d8a-44d8-9597-9695925f79cd', '1376be74-0955-43c4-8e90-ec089c9261db', 'Jan Piajenin koqnitiv inkişaf nəzəriyyəsinə görə, ibtidai sinif yaşındakı (7–11 yaş) uşaqlar intellektual inkişafın hansı mərhələsindədir?', 'multiple_choice', '["Hissi-hərəki mərhələdə (Sensorimotor)", "Formal əməliyyatlar mərhələsində (Formal operational)", "Post-formal refleksiv mərhələdə", "Əməliyyatöncəsi təfəkkür mərhələsində (Preoperational)", "Konkret əməliyyatlar mərhələsində (məntiqi təfəkkür, tərsinə çevrilmə və qruplaşdırma bacarığı)"]'::jsonb, 'Konkret əməliyyatlar mərhələsində (məntiqi təfəkkür, tərsinə çevrilmə və qruplaşdırma bacarığı)', 'Düzgün cavab: E) Konkret əməliyyatlar mərhələsində (məntiqi təfəkkür, tərsinə çevrilmə və qruplaş', '', 5, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('975c5cbe-869f-46c5-9003-e0048e83bb0a', 'fbc04907-1d8a-44d8-9597-9695925f79cd', 'ka', 'ჟან პიაჟეს კოგნიტური განვითარების თეორიის მიხედვით, განვითარების რომელ ეტაპზე იმყოფებიან დაწყებითი კლასის ასაკის (7–11 წლის) ბავშვები?', '["სენსომოტორულ სტადიაზე (Sensorimotor) - რეფლექსები და ობიექტის მუდმივობა", "ოპერაციამდელ სტადიაზე (Preoperational) - ეგოცენტრიზმი და სიმბოლური თამაში", "პოსტფორმალურ რეფლექსურ სტადიაზე - დიალექტიკური და რელატივისტური აზროვნება", "ფორმალურ ოპერაციათა სტადიაზე (Formal operational) - აბსტრაქტული და ჰიპოთეტური აზროვნება", "კონკრეტულ ოპერაციათა სტადიაზე (Concrete operational stage) - ლოგიკური აზროვნება, შექცევადობა და კლასიფიკაციის უნარი"]'::jsonb, 'კონკრეტულ ოპერაციათა სტადიაზე (Concrete operational stage) - ლოგიკური აზროვნება, შექცევადობა და კლასიფიკაციის უნარი', 'Düzgün cavab: E) კონკრეტულ ოპერაციათა სტადიაზე (Concrete operational stage) - ლოგიკური აზროვნება,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('490025e2-5fb9-4b0d-a1ce-a5785a77ea31', '1376be74-0955-43c4-8e90-ec089c9261db', 'L.S.Vıqotskinin sosial-mədəni inkişaf nəzəriyyəsində ''Yaxın İnkişaf Zonası'' (ZPD) anlayışının mahiyyəti nədir?', 'multiple_choice', '["Uşağın sərbəst həll edə bildiyi tapşırıqlar səviyyəsi ilə yetkinin və ya daha bacarıqlı həmyaşıdın dəstəyi ilə həll edə biləcəyi potensial səviyyə arasındakı məsafə", "Ziddiyyətli biliklər arasındakı gərginliyi ifadə edən koqnitiv dissonans zonası", "Uşağın duyğu və hərəkət uyğunsuzluğunun yarandığı böhran fazası", "Müxtəlif sosial rolların kəsişdiyi şəxsiyyətlərarası inteqrasiya sərhədi", "IQ testinin ölçdüyü dəyişməz fərdi intellekt kəmiyyəti"]'::jsonb, 'Uşağın sərbəst həll edə bildiyi tapşırıqlar səviyyəsi ilə yetkinin və ya daha bacarıqlı həmyaşıdın dəstəyi ilə həll edə biləcəyi potensial səviyyə arasındakı məsafə', 'Düzgün cavab: A) Uşağın sərbəst həll edə bildiyi tapşırıqlar səviyyəsi ilə yetkinin və ya daha ba', '', 6, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('65e2e673-4bf3-4361-b360-02b8539d4b5f', '490025e2-5fb9-4b0d-a1ce-a5785a77ea31', 'ka', 'ლ. ს. ვიგოტსკის სოციალურ-კულტურული განვითარების თეორიაში რა არის „აქტუალური განვითარების უახლოესი ზონა“ (Zone of Proximal Development)?', '["მანძილი იმ ამოცანების დონეს, რომელთა დამოუკიდებლად გადაჭრა ბავშვს შეუძლია, და პოტენციურ დონეს შორის, რომლის მიღწევაც შესაძლებელია ზრდასრულის ან უფრო უნარიანი თანატოლის დახმარებით", "სენსომოტორული კრიზისის ფაზა - ბავშვის შეგრძნებებისა და მოძრაობის შეუსაბამობა", "კოგნიტური დისონანსის ზონა - დაძაბულობა ურთიერთსაწინააღმდეგო ცოდნას შორის", "პიროვნებათშორისი ინტეგრაციის ზღვარი - სოციალური როლების გადაკვეთა", "ინდივიდუალური ინტელექტის რაოდენობა - IQ ტესტით გაზომილი სტატიკური მაჩვენებელი"]'::jsonb, 'მანძილი იმ ამოცანების დონეს, რომელთა დამოუკიდებლად გადაჭრა ბავშვს შეუძლია, და პოტენციურ დონეს შორის, რომლის მიღწევაც შესაძლებელია ზრდასრულის ან უფრო უნარიანი თანატოლის დახმარებით', 'Düzgün cavab: A) მანძილი იმ ამოცანების დონეს, რომელთა დამოუკიდებლად გადაჭრა ბავშვს შეუძლია, და პო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('810d11ae-88ec-4bd9-af8e-d6b09ed5d547', '1376be74-0955-43c4-8e90-ec089c9261db', 'Erik Eriksonun psixososial inkişaf nəzəriyyəsinə əsasən, yeniyetməlik dövründə (12–18 yaş) aparıcı psixososial böhran hansıdır?', 'multiple_choice', '["Təşəbbüskarlıq və günahkarlıq hissi qarşıdurması", "Əməyə meyil və natamamlıq hissi böhranı", "İlkin inam və inamsızlıq qarşıdurması", "Şəxsiyyət identikliyi (eyniliyi) və rol qarışıqlığı böhranı", "İntimlik və təcridolunma qarşıdurması"]'::jsonb, 'Şəxsiyyət identikliyi (eyniliyi) və rol qarışıqlığı böhranı', 'Düzgün cavab: D) Şəxsiyyət identikliyi (eyniliyi) və rol qarışıqlığı böhranı', '', 7, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('40ac4640-1e6e-4855-8cf6-29e7535839df', '810d11ae-88ec-4bd9-af8e-d6b09ed5d547', 'ka', 'ერიკ ერიქსონის ფსიქოსოციალური განვითარების თეორიის თანახმად, რა არის ძირითადი კრიზისი მოზარდობის ასაკში (12–18 წელი)?', '["ინტიმურობისა და იზოლაციის კონფლიქტი - 20-40 წელი", "შრომისმოყვარეობისა და არასრულფასოვნების განცდის კრიზისი - 6-12 წელი", "ბაზისური ნდობისა და უნდობლობის კრიზისი - 0-1 წელი", "პიროვნული იდენტობისა და როლების გაურკვევლობის (დიფუზიის) კრიზისი - პასუხის ძიება კითხვაზე: „ვინ ვარ მე?“", "ინიციატივისა და დანაშაულის გრძნობის დაპირისპირება - 3-6 წელი"]'::jsonb, 'პიროვნული იდენტობისა და როლების გაურკვევლობის (დიფუზიის) კრიზისი - პასუხის ძიება კითხვაზე: „ვინ ვარ მე?“', 'Düzgün cavab: D) პიროვნული იდენტობისა და როლების გაურკვევლობის (დიფუზიის) კრიზისი - პასუხის ძიება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('982a5f3d-8b03-400d-a16c-2c876ec00b21', '1376be74-0955-43c4-8e90-ec089c9261db', 'Sinir sisteminin anadangəlmə dinamik xüsusiyyətlərinə (oyanma və ləngimənin gücü, tarazlığı və mütəhərrikliyi) əsaslanan fərdi-psixoloji xüsusiyyət necə adlanır?', 'multiple_choice', '["Xarakter", "Temperament", "Mənəvi-əxlaqi istiqamət", "Sosiallaşma dərəcəsi", "Dünyagörüşü"]'::jsonb, 'Temperament', 'Düzgün cavab: B) Temperament', '', 8, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1ef56dd6-fce6-45c9-ac8a-f5192b4d3107', '982a5f3d-8b03-400d-a16c-2c876ec00b21', 'ka', 'როგორ ეწოდება ინდივიდუალურ-ფსიქოლოგიურ თვისებას, რომელიც ნერვული სისტემის თანდაყოლილ დინამიკურ თავისებურებებს ემყარება?', '["ზნეობრივ-ეთიკური მიმართულება - სოციალურ ფასეულობათა სისტემა", "ადამიანის ტემპერამენტი - თანდაყოლილი თვისება, რომელიც განისაზღვრება აგზნებისა და შეკავების პროცესების ძალით, წონასწორობითა და მოძრაობით (მობილურობით)", "ადამიანის მსოფლმხედველობა - ფილოსოფიურ შეხედულებათა სისტემა", "პიროვნების ხასიათი - ცხოვრების განმავლობაში ჩამოყალიბებული თვისება", "სოციალიზაციის ხარისხი - საზოგადოებაში ინტეგრაციის დონე"]'::jsonb, 'ადამიანის ტემპერამენტი - თანდაყოლილი თვისება, რომელიც განისაზღვრება აგზნებისა და შეკავების პროცესების ძალით, წონასწორობითა და მოძრაობით (მობილურობით)', 'Düzgün cavab: B) ადამიანის ტემპერამენტი - თანდაყოლილი თვისება, რომელიც განისაზღვრება აგზნებისა და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4cd1b368-d6e2-4bcd-8e3d-b77a8b053a17', '1376be74-0955-43c4-8e90-ec089c9261db', 'Qıcıqlanma və ləngimə prosesləri güclü, tarazlaşmış, lakin ləng (az mütəhərrik) olan ali sinir fəaliyyəti tipinə hansı temperament uyğundur?', 'multiple_choice', '["Sanqvinik temperament tipi", "Astenik temperament tipi", "Xolerik temperament tipi", "Melanxolik temperament tipi", "Fleqmatik temperament tipi"]'::jsonb, 'Fleqmatik temperament tipi', 'Düzgün cavab: E) Fleqmatik temperament tipi', '', 9, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0850c349-b7d2-4eea-a99c-17962e828496', '4cd1b368-d6e2-4bcd-8e3d-b77a8b053a17', 'ka', 'რომელი ტემპერამენტი შეესაბამება ნერვული სისტემის ტიპს, რომელშიც აგზნებისა და შეკავების პროცესები ძლიერი, გაწონასწორებული, მაგრამ ინერტულია (ნაკლებად მობილური)?', '["სანგვინიკური ტემპერამენტის ტიპი - ძლიერი, გაწონასწორებული, მობილური", "ასთენიური ტემპერამენტის ტიპი - სუსტი, მაღალმგრძნობიარე", "მელანქოლიკური ტემპერამენტის ტიპი - სუსტი, გაუწონასწორებელი, მგრძნობიარე", "ქოლერიკული ტემპერამენტის ტიპი - ძლიერი, გაუწონასწორებელი, ფეთქებადი", "ფლეგმატიკური ტემპერამენტის ტიპი - მშვიდი, თავშეკავებული, ნელი გადართვით, სტაბილური განწყობით"]'::jsonb, 'ფლეგმატიკური ტემპერამენტის ტიპი - მშვიდი, თავშეკავებული, ნელი გადართვით, სტაბილური განწყობით', 'Düzgün cavab: E) ფლეგმატიკური ტემპერამენტის ტიპი - მშვიდი, თავშეკავებული, ნელი გადართვით, სტაბილუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e9ce9ef7-14dd-482b-9233-988b2df7d258', '1376be74-0955-43c4-8e90-ec089c9261db', 'Şagird kollektivində şəxslərarası münasibətləri, mikrotəşkilatlanmanı və liderlik statusunu aşkar etmək üçün hansı metod ən effektivdir?', 'multiple_choice', '["Raven mütərəqqi matrisləri testi", "Şulte cədvəlləri diqqət testi", "Ebbingauz yaddaş metodikası", "Sosiometriya metodikası (C.Moreno)", "Torndayk tapşırıqlar seriyası"]'::jsonb, 'Sosiometriya metodikası (C.Moreno)', 'Düzgün cavab: D) Sosiometriya metodikası (C.Moreno)', '', 10, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('47050880-f719-4c1d-9573-be0a140af3a0', 'e9ce9ef7-14dd-482b-9233-988b2df7d258', 'ka', 'მოსწავლეთა კოლექტივში პიროვნებათშორისი ურთიერთობებისა და ლიდერობის სტატუსის გამოსავლენად რომელი მეთოდია ყველაზე ეფექტური?', '["ებინგჰაუსის მეთოდიკა - მეხსიერების გაზომვა", "რავენის პროგრესული მატრიცები - არავერბალური ინტელექტი", "შულტეს ცხრილების ტესტი - ყურადღების განაწილება და გადართვა", "სოციომეტრიის მეთოდიკა (ჯ. მორენო) - არჩევანისა და უარყოფის საფუძველზე სოციომეტრიული სტატუსის, ჯგუფური შეჭიდულობისა და იზოლაციის გაზომვის მეთოდი", "თორნდაიკის ამოცანათა სერია - ინტელექტის გაზომვა"]'::jsonb, 'სოციომეტრიის მეთოდიკა (ჯ. მორენო) - არჩევანისა და უარყოფის საფუძველზე სოციომეტრიული სტატუსის, ჯგუფური შეჭიდულობისა და იზოლაციის გაზომვის მეთოდი', 'Düzgün cavab: D) სოციომეტრიის მეთოდიკა (ჯ. მორენო) - არჩევანისა და უარყოფის საფუძველზე სოციომეტრი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ad1e98a8-c3c7-4cd7-8c0a-dd555d564450', '1376be74-0955-43c4-8e90-ec089c9261db', 'Şagirdin şüuraltı daxili konfliktlərini, emosional vəziyyətini və gizli qorxularını öyrənmək üçün tətbiq edilən proyektiv metodlara hansı testlər aiddir?', 'multiple_choice', '["Eysenckin Şəxsiyyət Sorğusu Testi (EPI)", "“Mövcud olmayan heyvan”, “Ailə şəkli”, “Ağac”, “İnsan” rəsm testləri və Tematik Apperseptiv Test (TAT)", "Amthauer İntellekt Strukturu Testi", "Vekslerin Uşaq İntellekt Şkalası Testi (WISC)", "Ravenin Proqressiv Şkala Zəka Testi"]'::jsonb, '“Mövcud olmayan heyvan”, “Ailə şəkli”, “Ağac”, “İnsan” rəsm testləri və Tematik Apperseptiv Test (TAT)', 'Düzgün cavab: B) “Mövcud olmayan heyvan”, “Ailə şəkli”, “Ağac”, “İnsan” rəsm testləri və Tematik', '', 11, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('704acc8f-b027-4a25-8aec-9554def59d08', 'ad1e98a8-c3c7-4cd7-8c0a-dd555d564450', 'ka', 'რომელი ტესტი განეკუთვნება პროექციულ მეთოდს, რომელიც გამოიყენება მოსწავლის არაცნობიერი შინაგანი კონფლიქტებისა და ფარული შიშების შესასწავლად?', '["ვექსლერის ბავშვთა ინტელექტის სკალის ტესტი - IQ ტესტი", "პროექციული ტესტები: „არარსებული ცხოველი“, „ოჯახის ნახატი“, „ხე“, „ადამიანი“, აგრეთვე TAT (თემატური აპერცეპციის ტესტი) და რორშახის ტესტი", "რავენის პროგრესული სკალის ინტელექტის ტესტი - ინტელექტის ტესტი", "აიზენკის პიროვნების კითხვარი - ექსტრავერსია-ნეიროტიზმი", "ამთჰაუერის ინტელექტის სტრუქტურის ტესტი - ინტელექტის სტრუქტურა"]'::jsonb, 'პროექციული ტესტები: „არარსებული ცხოველი“, „ოჯახის ნახატი“, „ხე“, „ადამიანი“, აგრეთვე TAT (თემატური აპერცეპციის ტესტი) და რორშახის ტესტი', 'Düzgün cavab: B) პროექციული ტესტები: „არარსებული ცხოველი“, „ოჯახის ნახატი“, „ხე“, „ადამიანი“, აგრ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9dbac8a9-1060-4902-8611-f0098ce7c087', '1376be74-0955-43c4-8e90-ec089c9261db', 'Məktəbə yeni qədəm qoyan I sinif şagirdinin tədris mühitinə, yeni sosial rollara və tələblərə öyrəşməsi prosesi necə adlanır?', 'multiple_choice', '["Məktəb deqradasiyası prosesi", "Sosial akselerasiya hadisəsi", "Məktəb adaptasiyası (uyğunlaşması)", "Sensor deprivasiya vəziyyəti", "Psixoloji frustrasiya sindromu"]'::jsonb, 'Məktəb adaptasiyası (uyğunlaşması)', 'Düzgün cavab: C) Məktəb adaptasiyası (uyğunlaşması)', '', 12, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c775288d-3650-4857-b749-8b121d2480c6', '9dbac8a9-1060-4902-8611-f0098ce7c087', 'ka', 'როგორ ეწოდება პირველკლასელის სასწავლო გარემოსთან შეგუების პროცესს სკოლაში სწავლის დაწყებისას?', '["ფსიქოლოგიური ფრუსტრაციის სინდრომი - დაძაბულობა დაბრკოლების წინაშე", "სოციალური აქსელერაციის მოვლენა - დაჩქარებული განვითარება", "სასკოლო ადაპტაცია (შეგუება) - ფიზიოლოგიური, ფსიქოლოგიური და სოციალური შეგუება, პროცესი, რომელიც 2-დან 6 თვემდე გრძელდება", "სასკოლო დეგრადაციის პროცესი - რეგრესი და დაქვეითება", "სენსორული დეპრივაციის მდგომარეობა - გრძნობადი ინფორმაციის სიმწირე"]'::jsonb, 'სასკოლო ადაპტაცია (შეგუება) - ფიზიოლოგიური, ფსიქოლოგიური და სოციალური შეგუება, პროცესი, რომელიც 2-დან 6 თვემდე გრძელდება', 'Düzgün cavab: C) სასკოლო ადაპტაცია (შეგუება) - ფიზიოლოგიური, ფსიქოლოგიური და სოციალური შეგუება, პ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('75002173-7551-49ee-80c6-42ff2fee3420', '1376be74-0955-43c4-8e90-ec089c9261db', 'Məktəb mühitində bir şagirdin digərinə qarşı mütəmadi, qərəzli və güc bərabərsizliyinə əsaslanan mənəvi-fiziki təzyiqi necə adlanır?', 'multiple_choice', '["Təlim motivasiyası", "Konstruktiv rəqabət", "Bullinq (zorbalıq / mobbinq)", "Əməkdaşlıq fəaliyyəti", "Koqnitiv dissonans"]'::jsonb, 'Bullinq (zorbalıq / mobbinq)', 'Düzgün cavab: C) Bullinq (zorbalıq / mobbinq)', '', 13, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('22e1f01c-98fa-41f5-91a8-c5006c430356', '75002173-7551-49ee-80c6-42ff2fee3420', 'ka', 'როგორ ეწოდება სასკოლო გარემოში ერთი მოსწავლის მხრიდან მეორეზე სისტემატურ, განზრახ და ძალთა უთანასწორობაზე დაფუძნებულ ზეწოლას?', '["კონსტრუქციული კონკურენცია - ჯანსაღი შეჯიბრი", "სასწავლო მოტივაცია - სწავლისკენ წამახალისებელი ფაქტორი", "ბულინგი (მორალურ-ფიზიკური ძალადობა / შევიწროება / მობინგი) - განმეორებადი, მიზანმიმართული აგრესიული ქცევა", "თანამშრომლობითი საქმიანობა - ერთობლივი მუშაობა", "კოგნიტური დისონანსი - შეუსაბამო ცოდნა"]'::jsonb, 'ბულინგი (მორალურ-ფიზიკური ძალადობა / შევიწროება / მობინგი) - განმეორებადი, მიზანმიმართული აგრესიული ქცევა', 'Düzgün cavab: C) ბულინგი (მორალურ-ფიზიკური ძალადობა / შევიწროება / მობინგი) - განმეორებადი, მიზან', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e7061ef2-25ed-4b8a-b886-95f5b458e7b6', '1376be74-0955-43c4-8e90-ec089c9261db', 'Rəqəmsal platformalar, sosial şəbəkələr və messencerlər vasitəsilə şagirdə qarşı həyata keçirilən təhdid, təhqir və təqib fəaliyyəti necə adlanır?', 'multiple_choice', '["Rəqəmsal inteqrasiya", "Şəbəkə empatiyası modeli", "Kibergigiyena qaydaları", "Kiberetika prinsipləri", "Kiberbullinq (virtual zorbalıq / e-bullinq)"]'::jsonb, 'Kiberbullinq (virtual zorbalıq / e-bullinq)', 'Düzgün cavab: E) Kiberbullinq (virtual zorbalıq / e-bullinq)', '', 14, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('63213294-3bef-4cbc-8524-c71a5cd91b7c', 'e7061ef2-25ed-4b8a-b886-95f5b458e7b6', 'ka', 'როგორ ეწოდება ციფრული პლატფორმების მეშვეობით მოსწავლის მიმართ განხორციელებულ მუქარასა და შეურაცხყოფას?', '["ციფრული ინტეგრაცია - ტექნოლოგიების გაერთიანება", "კიბერჰიგიენის წესები - ციფრული უსაფრთხოება", "ქსელური ემპათიის მოდელი - ონლაინ ემპათია", "კიბერეთიკის პრინციპები - ეთიკური ქცევის წესები ინტერნეტში", "კიბერბულინგი (ვირტუალური შევიწროება / ე-ბულინგი) - ინტერნეტის, სოციალური ქსელებისა და მესენჯერების მეშვეობით ხანგრძლივი დევნა"]'::jsonb, 'კიბერბულინგი (ვირტუალური შევიწროება / ე-ბულინგი) - ინტერნეტის, სოციალური ქსელებისა და მესენჯერების მეშვეობით ხანგრძლივი დევნა', 'Düzgün cavab: E) კიბერბულინგი (ვირტუალური შევიწროება / ე-ბულინგი) - ინტერნეტის, სოციალური ქსელები', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('27e5b26d-b612-41f1-b215-0cef2acc3f5e', '1376be74-0955-43c4-8e90-ec089c9261db', 'Şagirdlərdə diqqətin davamsızlığı, impulsiv davranışlar və həddindən artıq motor hərəkətliliklə xarakterizə olunan neyroinkişaf pozuntusu hansıdır?', 'multiple_choice', '["Diqqət Çatışmazlığı və Hiperaktivlik Pozuntusu (DÇHP / ADHD)", "Nitq mərkəzinin funksional afaziya sindromu", "Hissiyyat orqanlarının sensor nevrozu", "Spesifik oxu pozuntusu (Disleksiya)", "Erkən uşaqlıq autizm spektr pozuntusu"]'::jsonb, 'Diqqət Çatışmazlığı və Hiperaktivlik Pozuntusu (DÇHP / ADHD)', 'Düzgün cavab: A) Diqqət Çatışmazlığı və Hiperaktivlik Pozuntusu (DÇHP / ADHD)', '', 15, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4f721440-2010-4fbe-9643-b01a5e485041', '27e5b26d-b612-41f1-b215-0cef2acc3f5e', 'ka', 'რომელი მდგომარეობა ხასიათდება მოსწავლეებში ყურადღების არამდგრადობით, იმპულსური ქცევითა და გადაჭარბებული მოტორული აქტივობით?', '["ყურადღების დეფიციტისა და ჰიპერაქტივობის სინდრომი (ADHD / ყდჰს) - ნეიროგანვითარების დარღვევა, ყურადღების დეფიციტის, იმპულსურობისა და ჰიპერაქტივობის ტრიადა", "ქრონიკული კითხვისა და გააზრების დისლექსია - კითხვის სირთულე", "მეტყველების ცენტრის ფუნქციური აფაზიის სინდრომი - მეტყველების დაკარგვა", "ადრეული ბავშვობის აუტისტური სპექტრის აშლილობა - სოციალური კომუნიკაციის სირთულე", "შეგრძნებათა ორგანოების სენსორული ნევროზი - მგრძნობელობის მომატება"]'::jsonb, 'ყურადღების დეფიციტისა და ჰიპერაქტივობის სინდრომი (ADHD / ყდჰს) - ნეიროგანვითარების დარღვევა, ყურადღების დეფიციტის, იმპულსურობისა და ჰიპერაქტივობის ტრიადა', 'Düzgün cavab: A) ყურადღების დეფიციტისა და ჰიპერაქტივობის სინდრომი (ADHD / ყდჰს) - ნეიროგანვითარებ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('67e86eba-4bbb-4fc6-9df1-48d8738b78ff', '1376be74-0955-43c4-8e90-ec089c9261db', 'İntellekti normal səviyyədə olan şagirdin oxuma və yazma bacarıqlarını mənimsəməsində müşahidə olunan spesifik təlim çətinlikləri hansılardır?', 'multiple_choice', '["Autizm və epilepsiya sindromu", "Disleksiya (oxu çətinliyi) və Disqrafiya (yazı pozuntusu)", "Oliqofreniya və demensiya", "Katarakta və mütləq karlıq", "Şizofreniya və kəskin psixoz"]'::jsonb, 'Disleksiya (oxu çətinliyi) və Disqrafiya (yazı pozuntusu)', 'Düzgün cavab: B) Disleksiya (oxu çətinliyi) və Disqrafiya (yazı pozuntusu)', '', 16, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('61ef8139-784e-401e-99a7-f8988cbfa596', '67e86eba-4bbb-4fc6-9df1-48d8738b78ff', 'ka', 'როგორ ეწოდება მდგომარეობას, როდესაც ნორმალური ინტელექტუალური განვითარების მიუხედავად, მოსწავლეს მუდმივი სირთულეები აქვს კითხვის უნარების ათვისებაში?', '["წერის დარღვევა დისგრაფია - წერის უნარის დარღვევა", "კითხვის დარღვევა დისლექსია - ფონოლოგიური დამუშავების სირთულე, ასო-ბგერის შესაბამისობის დარღვევა", "ანგარიშის დარღვევა დისკალკულია - მათემატიკური უნარების დარღვევა", "მოტორული დისპრაქსიის სინდრომი - მოძრაობის კოორდინაციის დარღვევა", "სენსორული მუტიზმის აშლილობა - სელექციური დუმილი"]'::jsonb, 'კითხვის დარღვევა დისლექსია - ფონოლოგიური დამუშავების სირთულე, ასო-ბგერის შესაბამისობის დარღვევა', 'Düzgün cavab: B) კითხვის დარღვევა დისლექსია - ფონოლოგიური დამუშავების სირთულე, ასო-ბგერის შესაბამ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fa7b3bfa-8b7f-432c-a51c-699df46e811a', '1376be74-0955-43c4-8e90-ec089c9261db', 'İnklüziv təhsil mühitində xüsusi təhsil ehtiyacı olan (XTEO) şagird üçün tərtib edilən Fərdi Təlim Planının (FTP) icrasında psixoloqun rolu nədir?', 'multiple_choice', '["Şagirdin qiymətlərini qeyd-şərtsiz ən yüksək balla elektron jurnala daxil etmək", "FTP-nin tərtibindən tam imtina edərək işi yalnız fənn müəlliminə həvalə etmək", "Şagirdin psixoloji xüsusiyyətlərini, idrak potensialını qiymətləndirmək, FTP-nin psixoloji komponentini hazırlamaq və adaptasiyanı dəstəkləmək", "Şagirdi ümumi dərslərdən tamamilə ayıraraq təcrid olunmuş fərdi otaqda saxlamaq", "Şagirdin valideynlərinin məktəbə gəlişini və müəllimlərlə əlaqəsini qadağan etmək"]'::jsonb, 'Şagirdin psixoloji xüsusiyyətlərini, idrak potensialını qiymətləndirmək, FTP-nin psixoloji komponentini hazırlamaq və adaptasiyanı dəstəkləmək', 'Düzgün cavab: C) Şagirdin psixoloji xüsusiyyətlərini, idrak potensialını qiymətləndirmək, FTP-nin', '', 17, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d9b75f44-d23b-4b5e-8f17-dc57aa4e15c0', 'fa7b3bfa-8b7f-432c-a51c-699df46e811a', 'ka', 'რა არის ინკლუზიური განათლების მოდელის მთავარი მიზანი?', '["სპეციალური საჭიროებების მქონე მოსწავლეთა სრული იზოლირება ზოგადსაგანმანათლებლო სკოლებიდან", "ჩაკეტილი კლასების გახსნა მხოლოდ მაღალი აკადემიური ნიჭის მქონე მოსწავლეებისთვის", "შეზღუდული შესაძლებლობისა და სპეციალური საჭიროებების მქონე ბავშვების განათლების უზრუნველყოფა ზოგადსაგანმანათლებლო გარემოში თანატოლებთან თანასწორუფლებიან საფუძველზე, დისკრიმინაციის გარეშე, დამხმარე სერვისების გამოყენებით", "ერთი და იმავე ფსიქოლოგიური სადიაგნოსტიკო ტესტების სავალდებულო გამოყენება ყველა მოსწავლისთვის", "ყველა სტანდარტული სასწავლო გეგმის სრული გაუქმება"]'::jsonb, 'შეზღუდული შესაძლებლობისა და სპეციალური საჭიროებების მქონე ბავშვების განათლების უზრუნველყოფა ზოგადსაგანმანათლებლო გარემოში თანატოლებთან თანასწორუფლებიან საფუძველზე, დისკრიმინაციის გარეშე, დამხმარე სერვისების გამოყენებით', 'Düzgün cavab: C) შეზღუდული შესაძლებლობისა და სპეციალური საჭიროებების მქონე ბავშვების განათლების უ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('538962bf-334b-4b1a-baa2-19a44dcc60ae', '1376be74-0955-43c4-8e90-ec089c9261db', 'Psixoloji məsləhət (konsultasiya) zamanı psixoloqun şagirdə münasibətdə nümayiş etdirməli olduğu əsas peşəkar yanaşma necə olmalıdır?', 'multiple_choice', '["Qeyd-şərtsiz qəbul, empatiya, aktiv dinləmə, mühakiməsiz yanaşma və peşəkar məxfilik təminatı", "Şagirdin səhvlərini dərhal tənqid edərək ona nəsihət vermək və əxlaqi dərslər keçmək", "Şagirdi cəzalandırmaq üçün məktəb rəhbərliyinə rəsmi təqdimat yazmaq", "Şagirdin yerinə qərarlar qəbul edərək ona məcburi göstərişlər vermək", "Konsultasiya zamanı səslənən şəxsi məlumatları dərhal sinif rəhbərinə bildirmək"]'::jsonb, 'Qeyd-şərtsiz qəbul, empatiya, aktiv dinləmə, mühakiməsiz yanaşma və peşəkar məxfilik təminatı', 'Düzgün cavab: A) Qeyd-şərtsiz qəbul, empatiya, aktiv dinləmə, mühakiməsiz yanaşma və peşəkar məxf', '', 18, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1927b88a-13c4-42c8-97fb-88e7a9100eb3', '538962bf-334b-4b1a-baa2-19a44dcc60ae', 'ka', 'რა არის უმნიშვნელოვანესი პრინციპი, რომელსაც ფსიქოლოგი უნდა იცავდეს ინდივიდუალური ფსიქოლოგიური კონსულტაციის პროცესში?', '["ემპათიის გამოვლენა, აქტიური მოსმენის მეთოდის გამოყენება, უპირობო დადებითი და მიუკერძოებელი მიღების გარემოს შექმნა და კონფიდენციალურობის დაცვა", "მოსწავლის ნაცვლად ყველა პირადი და სასწავლო პრობლემის ერთპიროვნულად გადაჭრა", "მოსწავლის ნათქვამის გაკრიტიკება და მისთვის დაუყოვნებლივ სავალდებულო გადაწყვეტილებების თავს მოხვევა", "კონსულტაციის დროს გაჟღერებული პირადი ინფორმაციის დაუყოვნებლივ შეტყობინება დამრიგებლისთვის", "სკოლის ხელმძღვანელობისთვის ოფიციალური წარდგინების დაწერა მოსწავლის დასჯის მიზნით"]'::jsonb, 'ემპათიის გამოვლენა, აქტიური მოსმენის მეთოდის გამოყენება, უპირობო დადებითი და მიუკერძოებელი მიღების გარემოს შექმნა და კონფიდენციალურობის დაცვა', 'Düzgün cavab: A) ემპათიის გამოვლენა, აქტიური მოსმენის მეთოდის გამოყენება, უპირობო დადებითი და მიუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('49857b1c-f9e6-4183-a718-3f9ba8cc3ded', '1376be74-0955-43c4-8e90-ec089c9261db', 'Şagird qarşısına qoyduğu məqsədə çatmaq istəyərkən gözlənilməz maneə ilə qarşılaşdıqda yaranan daxili gərginlik və məyusluq vəziyyəti necə adlanır?', 'multiple_choice', '["Sosial adaptasiya vəziyyəti", "İntellektual evrika vəziyyəti", "Emosional eyforiya vəziyyəti", "Psixoloji frustrasiya vəziyyəti", "İradi relaksasiya vəziyyəti"]'::jsonb, 'Psixoloji frustrasiya vəziyyəti', 'Düzgün cavab: D) Psixoloji frustrasiya vəziyyəti', '', 19, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('36be1fcc-6586-4b10-b2c4-e692097f96d5', '49857b1c-f9e6-4183-a718-3f9ba8cc3ded', 'ka', 'როგორ ეწოდება დაძაბულობის მდგომარეობას, რომელიც წარმოიქმნება მაშინ, როდესაც მოსწავლე დასახული მიზნის მიღწევის გზაზე მოულოდნელ დაბრკოლებას აწყდება?', '["ინტელექტუალური ევრიკის მდგომარეობა - აღმოჩენის სიხარული", "ემოციური ეიფორიის მდგომარეობა - ამაღლებული აღტაცება", "ნებელობითი რელაქსაციის მდგომარეობა - ნებაყოფლობითი მოდუნება", "ფსიქოლოგიური ფრუსტრაციის მდგომარეობა - დაბრკოლების, იმედგაცრუებისა და დაძაბულობის შედეგად წარმოქმნილი მდგომარეობა, რომელიც იწვევს აგრესიას ან რეგრესს", "სოციალური ადაპტაციის მდგომარეობა - ახალ გარემოსთან შეგუება"]'::jsonb, 'ფსიქოლოგიური ფრუსტრაციის მდგომარეობა - დაბრკოლების, იმედგაცრუებისა და დაძაბულობის შედეგად წარმოქმნილი მდგომარეობა, რომელიც იწვევს აგრესიას ან რეგრესს', 'Düzgün cavab: D) ფსიქოლოგიური ფრუსტრაციის მდგომარეობა - დაბრკოლების, იმედგაცრუებისა და დაძაბულობი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('043adecc-6dfe-4018-a136-8b280a38b69b', '1376be74-0955-43c4-8e90-ec089c9261db', 'Şəxsin öz emosiyalarını dərk etməsi, idarə etməsi, qarşı tərəfi anlaması və empatiya qurması qabiliyyəti necə adlanır?', 'multiple_choice', '["Mexaniki hafizə qabiliyyəti", "Psixomotor reaksiya sürəti", "Emosional intellekt (EQ / EI)", "Verbal linqvistik qabiliyyət", "Məkan təxəyyülü qabiliyyəti"]'::jsonb, 'Emosional intellekt (EQ / EI)', 'Düzgün cavab: C) Emosional intellekt (EQ / EI)', '', 20, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3ebd6837-5726-4ae5-9b62-9d93cd3d210d', '043adecc-6dfe-4018-a136-8b280a38b69b', 'ka', 'როგორ ეწოდება ადამიანის უნარს, გააცნობიეროს და მართოს საკუთარი და სხვების ემოციები?', '["მექანიკური მეხსიერების უნარი - მექანიკური დამახსოვრება", "ვერბალურ-ლინგვისტური უნარი - ენობრივი უნარი", "ემოციური ინტელექტი (EQ / EI) - საკუთარი და სხვების ემოციების ამოცნობის, მართვის, ემპათიისა და სოციალური უნარების მოდელი", "სივრცითი წარმოსახვის უნარი - ვიზუალურ-სივრცითი ინტელექტი", "ფსიქომოტორული რეაქციის სისწრაფე - მოძრაობის სისწრაფე"]'::jsonb, 'ემოციური ინტელექტი (EQ / EI) - საკუთარი და სხვების ემოციების ამოცნობის, მართვის, ემპათიისა და სოციალური უნარების მოდელი', 'Düzgün cavab: C) ემოციური ინტელექტი (EQ / EI) - საკუთარი და სხვების ემოციების ამოცნობის, მართვის,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('10b4d2fc-7363-49d2-b8ad-a884178e0edf', '1376be74-0955-43c4-8e90-ec089c9261db', 'İmtahan öncəsi şagirdlərdə yaranan yüksək həyəcan və narahatlığı azaltmaq üçün psixoloq hansı profilaktik işi aparmalıdır?', 'multiple_choice', '["Şagirdin imtahana buraxılmaması üçün məktəb rəhbərliyinə müraciət etmək", "Şagirdə imtahandan zəif nəticə göstərəcəyi halda cəzalanacağını xatırlatmaq", "Relaksasiya texnikaları, diafraqmal tənəffüs, vaxtın idarə edilməsi, özünəinamın artırılması və koqnitiv restrukturizasiya üzrə qrup təlimləri", "İmtahanda düşəcək sualların cavablarını əvvəlcədən təqdim etmək", "Şagirdi digər əlaçı sinif yoldaşları ilə müqayisə edərək irad bildirmək"]'::jsonb, 'Relaksasiya texnikaları, diafraqmal tənəffüs, vaxtın idarə edilməsi, özünəinamın artırılması və koqnitiv restrukturizasiya üzrə qrup təlimləri', 'Düzgün cavab: C) Relaksasiya texnikaları, diafraqmal tənəffüs, vaxtın idarə edilməsi, özünəinamın', '', 21, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6285684c-961e-4817-98ec-7ec62ecebc9e', '10b4d2fc-7363-49d2-b8ad-a884178e0edf', 'ka', 'რა სამუშაო უნდა ჩაატაროს ფსიქოლოგმა მოსწავლეებში გამოცდის წინ წარმოქმნილი მაღალი შფოთვის შესამცირებლად?', '["ხელმძღვანელობისთვის მიმართვა მოსწავლის გამოცდაზე არდაშვების მოთხოვნით", "მოსწავლისთვის შეხსენება, რომ გამოცდაზე დაბალი შედეგის ჩვენების შემთხვევაში ის დაისჯება", "პროფილაქტიკური ტრენინგები რელაქსაციის ტექნიკების, დიაფრაგმული სუნთქვის, კუნთების პროგრესული რელაქსაციის, დროის მართვის, თვითდაჯერებულობის ამაღლებისა და კოგნიტური რესტრუქტურიზაციის მიმართულებით", "გამოცდაზე მოსასვლელი ყველა კითხვის პასუხის წინასწარ მიწოდება", "მოსწავლის შედარება წარჩინებულ თანაკლასელებთან და მისთვის საყვედურის გამოცხადება"]'::jsonb, 'პროფილაქტიკური ტრენინგები რელაქსაციის ტექნიკების, დიაფრაგმული სუნთქვის, კუნთების პროგრესული რელაქსაციის, დროის მართვის, თვითდაჯერებულობის ამაღლებისა და კოგნიტური რესტრუქტურიზაციის მიმართულებით', 'Düzgün cavab: C) პროფილაქტიკური ტრენინგები რელაქსაციის ტექნიკების, დიაფრაგმული სუნთქვის, კუნთების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3086b7e5-4598-4692-a3d9-444fc070c33c', '1376be74-0955-43c4-8e90-ec089c9261db', 'Şagirdin öz real potensialı və nailiyyətləri ilə özünə verdiyi qiymət arasındakı uyğunsuzluq nə ilə xarakterizə olunur?', 'multiple_choice', '["İddia səviyyəsi və özünüqiymətləndirmənin qeyri-adekvatlığı ilə", "Sinir sisteminin dinamik balansının pozulması ilə", "İntellekt əmsalının (IQ) tam formalaşmaması ilə", "Sensor analizatorların funksional pozuntusu ilə", "Fərdin iradi keyfiyyətlərinin mütləq stabilliyi ilə"]'::jsonb, 'İddia səviyyəsi və özünüqiymətləndirmənin qeyri-adekvatlığı ilə', 'Düzgün cavab: A) İddia səviyyəsi və özünüqiymətləndirmənin qeyri-adekvatlığı ilə', '', 22, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b4254d5b-f702-4b82-a222-85ffe534d180', '3086b7e5-4598-4692-a3d9-444fc070c33c', 'ka', 'რით ხასიათდება მოსწავლის რეალურ პოტენციალსა და მის თვითშეფასებას შორის არსებული შეუსაბამობა?', '["პრეტენზიის დონისა და თვითშეფასების არაადეკვატურობით - მაღალი პრეტენზია, დაბალი თვითშეფასება ან პირიქით", "ინდივიდის ნებელობითი თვისებების აბსოლუტური სტაბილურობით", "ნერვული სისტემის დინამიკური ბალანსის დარღვევით", "ინტელექტის კოეფიციენტის (IQ) არასრული ფორმირებით", "სენსორული ანალიზატორების ფუნქციური დარღვევით"]'::jsonb, 'პრეტენზიის დონისა და თვითშეფასების არაადეკვატურობით - მაღალი პრეტენზია, დაბალი თვითშეფასება ან პირიქით', 'Düzgün cavab: A) პრეტენზიის დონისა და თვითშეფასების არაადეკვატურობით - მაღალი პრეტენზია, დაბალი თ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7e75bb69-1a9c-4d28-8843-0bbac7e5a3d3', '1376be74-0955-43c4-8e90-ec089c9261db', 'Məktəb psixoloqu psixodiaqnostik testləri seçərkən hansı əsas elmi-metodik tələblərə diqqət yetirməlidir?', 'multiple_choice', '["Testin internet sorğularından adaptasiya edilmədən birbaşa götürülməsinə", "Testin ən azı 300 sualdan ibarət mürəkkəb riyazi strukturuna", "Testin yalnız qrafik təsvirlərdən ibarət olmasına", "Testin yalnız xarici dildə tərtib olunmasına və qısa olmasına", "Testin validliyinə (ölçmə dəqiqliyi), etibarlılığına (re-test uyğunluğu), standartlaşdırılmasına və yaş normativlərinə adaptasiyasına"]'::jsonb, 'Testin validliyinə (ölçmə dəqiqliyi), etibarlılığına (re-test uyğunluğu), standartlaşdırılmasına və yaş normativlərinə adaptasiyasına', 'Düzgün cavab: E) Testin validliyinə (ölçmə dəqiqliyi), etibarlılığına (re-test uyğunluğu), standa', '', 23, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2f44b843-a425-4690-bb99-6bee7942b3e5', '7e75bb69-1a9c-4d28-8843-0bbac7e5a3d3', 'ka', 'რა ძირითად სამეცნიერო-მეთოდურ მოთხოვნებს უნდა მიაქციოს ყურადღება სკოლის ფსიქოლოგმა ფსიქოლოგიური ტესტების შერჩევისას?', '["ტესტის რთულ მათემატიკურ სტრუქტურას, რომელიც სულ მცირე 300 კითხვისგან შედგება", "ტესტის მხოლოდ უცხო ენაზე შედგენასა და მის სიმოკლეს", "ტესტის მხოლოდ გრაფიკული გამოსახულებებისგან შედგენას", "ტესტის აღებას ინტერნეტგამოკითხვებიდან ყოველგვარი ადაპტაციის გარეშე", "ტესტის ვალიდურობას (გაზომვის სიზუსტე, შინაარსობრივი, კრიტერიუმული, კონსტრუქტული), სანდოობას (ტესტ-რეტესტი, შინაგანი შეთანხმებულობა), სტანდარტიზაციას, ასაკობრივ და კულტურულ ნორმატივებთან შესაბამისობასა და ადაპტაციას"]'::jsonb, 'ტესტის ვალიდურობას (გაზომვის სიზუსტე, შინაარსობრივი, კრიტერიუმული, კონსტრუქტული), სანდოობას (ტესტ-რეტესტი, შინაგანი შეთანხმებულობა), სტანდარტიზაციას, ასაკობრივ და კულტურულ ნორმატივებთან შესაბამისობასა და ადაპტაციას', 'Düzgün cavab: E) ტესტის ვალიდურობას (გაზომვის სიზუსტე, შინაარსობრივი, კრიტერიუმული, კონსტრუქტული)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('612d9561-d3fe-4b80-bfb7-29f786c40ec6', '1376be74-0955-43c4-8e90-ec089c9261db', 'Şagird suisidal (intihar) fikirlər və ya niyyət nümayiş etdirdikdə psixoloqun təxirəsalınmaz hərəkət alqoritmi necə olmalıdır?', 'multiple_choice', '["Məsələni tam gizli saxlamaq və heç bir rəsmi qeydiyyat aparmamaq", "Şagirdi məktəb tədbirində hamının qarşısında tənqid edərək intizama dəvət etmək", "Məsələnin araşdırılmasını növbəti tədris ilinin əvvəlinə qədər təxirə salmaq", "Şagirdi dərhal bütün dərslərdən kənarlaşdıraraq təkbaşına evə göndərmək", "Təcili böhran müdaxiləsi etmək, uşağı tək qoymamaq, təhlükəsizliyi təmin etmək, valideynləri və rəhbərliyi məlumatlandıraraq ixtisaslaşmış psixiatrik-psixoloji mərkəzə yönləndirmək"]'::jsonb, 'Təcili böhran müdaxiləsi etmək, uşağı tək qoymamaq, təhlükəsizliyi təmin etmək, valideynləri və rəhbərliyi məlumatlandıraraq ixtisaslaşmış psixiatrik-psixoloji mərkəzə yönləndirmək', 'Düzgün cavab: E) Təcili böhran müdaxiləsi etmək, uşağı tək qoymamaq, təhlükəsizliyi təmin etmək,', '', 24, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('34593285-cd6a-4483-af6d-030eadc601db', '612d9561-d3fe-4b80-bfb7-29f786c40ec6', 'ka', 'როგორი უნდა იყოს ფსიქოლოგის გადაუდებელი მოქმედების ალგორითმი, როდესაც მოსწავლე სუიციდურ აზრებს ავლენს?', '["მოსწავლის დაუყოვნებლივ ჩამოშორება ყველა გაკვეთილიდან და სახლში გაშვება", "მოსწავლის საჯარო გაკრიტიკება სასკოლო ღონისძიებაზე ყველას თანდასწრებით", "საკითხის გამოკვლევის გადადება მომდევნო სასწავლო წლის დასაწყისამდე", "საკითხის გასაიდუმლოება და ყოველგვარი ოფიციალური აღრიცხვისგან თავის შეკავება", "გადაუდებელი კრიზისული ინტერვენცია, ბავშვის არასოდეს მარტო დატოვება, აქტიური მოსმენითა და ემპათიით უსაფრთხოების უზრუნველყოფა, მშობლებისა და ხელმძღვანელობის დაუყოვნებლივი ინფორმირება, გადამისამართება სპეციალიზებულ ფსიქიატრიულ-ფსიქოლოგიურ ცენტრში, სასწრაფო დახმარების გამოძახება და დოკუმენტირება"]'::jsonb, 'გადაუდებელი კრიზისული ინტერვენცია, ბავშვის არასოდეს მარტო დატოვება, აქტიური მოსმენითა და ემპათიით უსაფრთხოების უზრუნველყოფა, მშობლებისა და ხელმძღვანელობის დაუყოვნებლივი ინფორმირება, გადამისამართება სპეციალიზებულ ფსიქიატრიულ-ფსიქოლოგიურ ცენტრში, სასწრაფო დახმარების გამოძახება და დოკუმენტირება', 'Düzgün cavab: E) გადაუდებელი კრიზისული ინტერვენცია, ბავშვის არასოდეს მარტო დატოვება, აქტიური მოსმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f7439b7a-3a2b-432a-8466-434564c332dd', '1376be74-0955-43c4-8e90-ec089c9261db', 'Təlim materialının şagird tərəfindən məntiqi əlaqələr qurulmadan, yalnız mexaniki təkrarla yadda saxlanılması hansı hafizə növüdür?', 'multiple_choice', '["Qısamüddətli operativ yaddaş", "Məntiqi-mənalı yaddaş", "Mexaniki yaddaş (mexaniki əzbərləmə)", "Obrazlı eydetik hafizə", "Emosional-hissi yaddaş"]'::jsonb, 'Mexaniki yaddaş (mexaniki əzbərləmə)', 'Düzgün cavab: C) Mexaniki yaddaş (mexaniki əzbərləmə)', '', 25, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('28f481c6-5a26-4139-b5a2-2ad8d6eae428', 'f7439b7a-3a2b-432a-8466-434564c332dd', 'ka', 'მეხსიერების რომელი სახეა, როდესაც მოსწავლე სასწავლო მასალას ლოგიკური კავშირების დამყარების გარეშე, მხოლოდ მექანიკური გამეორებით იმახსოვრებს?', '["ლოგიკურ-აზრობრივი მეხსიერება - შინაარსზე დაფუძნებული დამახსოვრება", "ემოციურ-გრძნობადი მეხსიერება - ემოციებზე დაფუძნებული მეხსიერება", "არაცნობიერი მექანიკური მეხსიერება (მექანიკური დაზეპირება) - ლოგიკური მეხსიერების საპირისპირო, ხანმოკლე და არამდგრადი", "ხატოვანი ეიდეტური მეხსიერება - ნათელი ხატოვანი მეხსიერება", "მოკლევადიანი ოპერატიული მეხსიერება - მიმდინარე საქმიანობისთვის საჭირო მეხსიერება"]'::jsonb, 'არაცნობიერი მექანიკური მეხსიერება (მექანიკური დაზეპირება) - ლოგიკური მეხსიერების საპირისპირო, ხანმოკლე და არამდგრადი', 'Düzgün cavab: C) არაცნობიერი მექანიკური მეხსიერება (მექანიკური დაზეპირება) - ლოგიკური მეხსიერების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a7990b10-0e14-4cb5-8bcf-82856006cb23', '1376be74-0955-43c4-8e90-ec089c9261db', 'Şagirdin təlim fəaliyyətini kənar mükafat və ya cəza qorxusundan deyil, sırf bilik qazanmaq və dərketmə ehtiyacından icra etməsi hansı motivasiyadır?', 'multiple_choice', '["Xarici (ekstrinsik) motivasiya", "Neytral passiv motivasiya", "Situativ qrup təsiri motivasiyası", "Daxili (intrinsik) motivasiya", "İnzibati məcburetmə təzyiqi"]'::jsonb, 'Daxili (intrinsik) motivasiya', 'Düzgün cavab: D) Daxili (intrinsik) motivasiya', '', 26, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8cb703b4-aa85-40f7-abc3-7d684668e5c6', 'a7990b10-0e14-4cb5-8bcf-82856006cb23', 'ka', 'რომელი მოტივაციაა, როდესაც მოსწავლე სასწავლო საქმიანობას ცოდნის შეძენის შინაგანი სურვილით ახორციელებს?', '["გარეგანი (ექსტრინსიკული) მოტივაცია - სწავლა ნიშნის, ჯილდოსა და ქების მისაღებად", "ადმინისტრაციული იძულების ზეწოლა - სწავლა სასჯელის შიშით", "სიტუაციური ჯგუფური გავლენის მოტივაცია - სწავლა მეგობრების გავლენით", "შინაგანი (ინტრინსიკული) მოტივაცია - ინტერესით, შემეცნებითი მოთხოვნილებითა და თვითრეალიზაციით განპირობებული შინაგანი სწრაფვა", "ნეიტრალური პასიური მოტივაცია - გულგრილი დამოკიდებულება"]'::jsonb, 'შინაგანი (ინტრინსიკული) მოტივაცია - ინტერესით, შემეცნებითი მოთხოვნილებითა და თვითრეალიზაციით განპირობებული შინაგანი სწრაფვა', 'Düzgün cavab: D) შინაგანი (ინტრინსიკული) მოტივაცია - ინტერესით, შემეცნებითი მოთხოვნილებითა და თვი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1e20026d-209d-417f-ac39-efc9f63a74e2', '1376be74-0955-43c4-8e90-ec089c9261db', 'Şagirdlərdə peşəyönümü işinin təşkili zamanı məktəb psixoloqunun başlıca vəzifəsi nədən ibarətdir?', 'multiple_choice', '["Şagirdin valideynlərinin seçdiyi peşəni tərəddüdsüz təsdiqləmək", "Şagirdin maraq, qabiliyyət, temperament və dəyərlərini diaqnostika edərək, əmək bazarını nəzərə almaqla ona adekvat və perspektivli peşə seçimində məsləhətçi dəstək vermək", "Şagirdin sənədlərini ali məktəbə qəbul üçün müstəqil təqdim etmək", "Şagirdə yalnız yüksək gəlirli və dəbdə olan ixtisasları məcburi seçdirmək", "İmtahan fənlərinin sayını azaltmaq üçün rəhbərliyə təkliflər vermək"]'::jsonb, 'Şagirdin maraq, qabiliyyət, temperament və dəyərlərini diaqnostika edərək, əmək bazarını nəzərə almaqla ona adekvat və perspektivli peşə seçimində məsləhətçi dəstək vermək', 'Düzgün cavab: B) Şagirdin maraq, qabiliyyət, temperament və dəyərlərini diaqnostika edərək, əmək', '', 27, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e74427d8-9d53-469d-8636-1998003e29b0', '1e20026d-209d-417f-ac39-efc9f63a74e2', 'ka', 'რა არის ფსიქოლოგის მთავარი მიზანი მოსწავლეებთან პროფესიული ორიენტაციის სამუშაოს ორგანიზებისას?', '["მოსწავლისთვის მხოლოდ მაღალშემოსავლიანი და პოპულარული სპეციალობების სავალდებულო არჩევა", "მოსწავლის ინტერესების, მიდრეკილებების, პიროვნული თავისებურებების, ტემპერამენტისა და ღირებულებების დიაგნოსტირებით, შრომის ბაზრის გათვალისწინებით, მისთვის ჰუმანური საკონსულტაციო მხარდაჭერის გაწევა ადეკვატური, რეალური და პერსპექტიული პროფესიული მიმართულების შერჩევაში", "მოსწავლის მშობლების მიერ არჩეული პროფესიის უყოყმანო დამტკიცება", "მოსწავლის საბუთების დამოუკიდებლად წარდგენა უმაღლეს სასწავლებელში ჩასაბარებლად", "საგამოცდო საგნების რაოდენობის შემცირების შესახებ წინადადებების წარდგენა"]'::jsonb, 'მოსწავლის ინტერესების, მიდრეკილებების, პიროვნული თავისებურებების, ტემპერამენტისა და ღირებულებების დიაგნოსტირებით, შრომის ბაზრის გათვალისწინებით, მისთვის ჰუმანური საკონსულტაციო მხარდაჭერის გაწევა ადეკვატური, რეალური და პერსპექტიული პროფესიული მიმართულების შერჩევაში', 'Düzgün cavab: B) მოსწავლის ინტერესების, მიდრეკილებების, პიროვნული თავისებურებების, ტემპერამენტისა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f356e431-bc1b-44e5-bcd4-3a509578b52a', '1376be74-0955-43c4-8e90-ec089c9261db', 'Uşaq və yeniyetmələrdə aqressiv davranışlar müşahidə edildikdə psixokorreksiya işinin əsas hədəfi nə olmalıdır?', 'multiple_choice', '["Aqressiyanın səbəblərini aşkar edərək şagirdə qəzəbi tanıma, konstruktiv idarəetmə, empatiya və alternativ sosial davranış bacarıqlarını aşılamaq", "Şagirdi digər sinif yoldaşlarının kollektiv mühakiməsinə buraxmaq", "Valideynlərlə əlaqəni kəsərək məsələni yalnız məktəbdaxili cəza ilə bitirmək", "Şagirdi sinif yoldaşlarından tamamilə təcrid edərək təhsildən uzaqlaşdırmaq", "Aqressiyanı sərt fiziki cəzalar və qadağalarla dərhal yatırtmaq"]'::jsonb, 'Aqressiyanın səbəblərini aşkar edərək şagirdə qəzəbi tanıma, konstruktiv idarəetmə, empatiya və alternativ sosial davranış bacarıqlarını aşılamaq', 'Düzgün cavab: A) Aqressiyanın səbəblərini aşkar edərək şagirdə qəzəbi tanıma, konstruktiv idarəet', '', 28, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c21b36d6-bb3f-47d4-a5ce-946726b97ccb', 'f356e431-bc1b-44e5-bcd4-3a509578b52a', 'ka', 'რა უნდა იყოს ფსიქოკორექციული მუშაობის მთავარი სამიზნე ბავშვებსა და მოზარდებში აგრესიული ქცევის გამოვლენისას?', '["აგრესიის გამომწვევი მიზეზების (ოჯახი, ტრავმა, ფრუსტრაცია) გამოვლენა, მოსწავლისთვის რისხვის ამოცნობის, კონსტრუქციული მართვის, თვითგამოხატვის, ემპათიისა და სოციალური უნარების სწავლება და ალტერნატიული ქცევითი მოდელების ჩამოყალიბება", "აგრესიის დაუყოვნებლივ ჩახშობა მკაცრი ფიზიკური დასჯითა და აკრძალვებით", "მოსწავლის გადაცემა სხვა მოსწავლეთა სამართავად", "მოსწავლის სრული იზოლაცია თანაკლასელებისგან და სასწავლო პროცესიდან ჩამოშორება", "მშობლებთან კავშირის გაწყვეტა და საკითხის მხოლოდ სკოლის შიგნით დატოვება"]'::jsonb, 'აგრესიის გამომწვევი მიზეზების (ოჯახი, ტრავმა, ფრუსტრაცია) გამოვლენა, მოსწავლისთვის რისხვის ამოცნობის, კონსტრუქციული მართვის, თვითგამოხატვის, ემპათიისა და სოციალური უნარების სწავლება და ალტერნატიული ქცევითი მოდელების ჩამოყალიბება', 'Düzgün cavab: A) აგრესიის გამომწვევი მიზეზების (ოჯახი, ტრავმა, ფრუსტრაცია) გამოვლენა, მოსწავლისთვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('29063ff9-88e4-43aa-ad45-f8d56d4fe68f', '1376be74-0955-43c4-8e90-ec089c9261db', 'Məktəb psixoloqunun peşə etikası kodeksinə əsasən, fəaliyyət zamanı rəhbər tutulmalı olan fundamental prinsiplər hansılardır?', 'multiple_choice', '["Şagirdlərə fərdi konsultasiyalar üçün məktəbdə ödənişli xidmət təşkil etmək", "Yalnız yüksək akademik göstəriciləri olan şagirdlərə psixoloji yardım göstərmək", "Şəxsi maraqlarını şagirdin psixoloji rifahından hər zaman üstün tutmaq", "Məktəb rəhbərliyinin bütün subyektiv göstərişlərini müzakirəsiz icra etmək", "Peşəkar sərhədləri qorumaq, obyektivlik, konfidensiallıq, səriştəlilik, şagirdin şəxsiyyətinə hörmət və ''zərər vurmamaq'' prinsipi"]'::jsonb, 'Peşəkar sərhədləri qorumaq, obyektivlik, konfidensiallıq, səriştəlilik, şagirdin şəxsiyyətinə hörmət və ''zərər vurmamaq'' prinsipi', 'Düzgün cavab: E) Peşəkar sərhədləri qorumaq, obyektivlik, konfidensiallıq, səriştəlilik, şagirdin', '', 29, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e32e2a74-7c80-43a1-9271-4a7cc5cdaba5', '29063ff9-88e4-43aa-ad45-f8d56d4fe68f', 'ka', 'მასწავლებელთა და ფსიქოლოგთა ეთიკური ქცევის წესების თანახმად, რომელი პრინციპით უნდა იხელმძღვანელოს ფსიქოლოგმა?', '["პირადი ინტერესების დაყენება მოსწავლის ფსიქოლოგიურ კეთილდღეობაზე წინ", "სკოლაში მოსწავლეთათვის ფასიანი ინდივიდუალური კონსულტაციების ორგანიზება", "ფსიქოლოგიური დახმარების გაწევა მხოლოდ მაღალი მატერიალური შემოსავლის მქონე ოჯახების ბავშვებისთვის", "სკოლის ხელმძღვანელობის ყველა უკანონო მოთხოვნის უსიტყვო შესრულება", "პროფესიული საზღვრების დაცვა, ობიექტურობა და მიუკერძოებლობა, კონფიდენციალურობა, კომპეტენტურობა, მოსწავლის პიროვნებისადმი ღრმა პატივისცემა და „არ ავნო“-ს პრინციპი"]'::jsonb, 'პროფესიული საზღვრების დაცვა, ობიექტურობა და მიუკერძოებლობა, კონფიდენციალურობა, კომპეტენტურობა, მოსწავლის პიროვნებისადმი ღრმა პატივისცემა და „არ ავნო“-ს პრინციპი', 'Düzgün cavab: E) პროფესიული საზღვრების დაცვა, ობიექტურობა და მიუკერძოებლობა, კონფიდენციალურობა, კ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bc26c3bd-98ba-4de2-88fd-8c4f0a358e31', '1376be74-0955-43c4-8e90-ec089c9261db', 'Məktəb psixoloqunun xidməti otağının təşkilinə dair tələblərə hansı standart uyğundur?', 'multiple_choice', '["Otağın səs-küylü yeməkxana və ya idman zalının içərisində yerləşməsi", "Otaqda yalnız bir ədəd yazı masasının olması və əlavə heç bir oturacağın qoyulmaması", "Psixoloji testlərin və konfidensial sənədlərin açıq dəhliz şkaflarında saxlanılması", "Otağın sakit, səs izolyasiyalı, məxfiliyi təmin edən, rahat mebel, yumşaq işıqlandırma, relaksasiya guşəsi və diaqnostik materialların qapalı şkaflarda saxlanması ilə təchiz olunması", "Otağın təbii işıqlandırmadan və ventilyasiyadan tam məhrum zirzəmidə olması"]'::jsonb, 'Otağın sakit, səs izolyasiyalı, məxfiliyi təmin edən, rahat mebel, yumşaq işıqlandırma, relaksasiya guşəsi və diaqnostik materialların qapalı şkaflarda saxlanması ilə təchiz olunması', 'Düzgün cavab: D) Otağın sakit, səs izolyasiyalı, məxfiliyi təmin edən, rahat mebel, yumşaq işıqla', '', 30, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('49c0a80c-af84-4ae7-8d40-108b20ae465a', 'bc26c3bd-98ba-4de2-88fd-8c4f0a358e31', 'ka', 'რომელი პუნქტი შეესაბამება სკოლის ფსიქოლოგის სამუშაო კაბინეტის მოწყობისადმი წაყენებულ მოთხოვნებს?', '["ოთახში მხოლოდ ერთი საწერი მაგიდის არსებობა და დამატებითი დასაჯდომი ადგილების არქონა", "ოთახის სრული მოკლება ბუნებრივ განათებასა და ვენტილაციას", "ფსიქოლოგიური ტესტებისა და პირადი საქმეების შენახვა დერეფნის ღია კარადებში", "ოთახის აღჭურვა მშვიდ, ხმის იზოლაციის მქონე გარემოში, რომელიც უზრუნველყოფს ინდივიდუალური საუბრების კონფიდენციალურობას, კომფორტული ავეჯით, რბილი განათებით, სარელაქსაციო კუთხითა და სადიაგნოსტიკო მასალების ჩაკეტილ კარადებში შენახვით", "ოთახის განთავსება ხმაურიან სასადილოში ან სპორტულ დარბაზში"]'::jsonb, 'ოთახის აღჭურვა მშვიდ, ხმის იზოლაციის მქონე გარემოში, რომელიც უზრუნველყოფს ინდივიდუალური საუბრების კონფიდენციალურობას, კომფორტული ავეჯით, რბილი განათებით, სარელაქსაციო კუთხითა და სადიაგნოსტიკო მასალების ჩაკეტილ კარადებში შენახვით', 'Düzgün cavab: D) ოთახის აღჭურვა მშვიდ, ხმის იზოლაციის მქონე გარემოში, რომელიც უზრუნველყოფს ინდივი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e51c81af-4b9d-401e-8854-b8573a6f259b', '1376be74-0955-43c4-8e90-ec089c9261db', 'Azərbaycan Respublikası Konstitusiyasının 42-ci maddəsinə əsasən, vətəndaşların təhsil hüququ ilə bağlı dövlətin əsas təminatı nədir?', 'multiple_choice', '["Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir", "Dövlət təhsil sistemində bütün pillələrin tamamilə ödənişli əsaslarla təşkil edilməsini qanunvericiliklə tənzimləyir", "Dövlət yalnız dövlət qulluqçularının övladlarının pulsuz orta ixtisas təhsili almasına hüquqi zəmanət verir", "Dövlət yalnız əlaçı şagirdlərin pulsuz təhsil almasını təmin edir və digər vətəndaşlara ödənişli əsaslarla şərait yaradır", "Dövlət hər bir vətəndaşın ali təhsil almasını məcburi edir və təhsil xərclərini tam şəkildə kommersiya banklarına həvalə edir"]'::jsonb, 'Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir', 'Düzgün cavab: A) Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin e', '', 31, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a347e0d9-2f4e-4da2-9bba-efb95125ca9a', 'e51c81af-4b9d-401e-8854-b8573a6f259b', 'ka', 'კონსტიტუციის 42-ე მუხლის თანახმად, განათლების უფლების უზრუნველყოფასთან დაკავშირებით რომელი დებულებაა განმტკიცებული?', '["სახელმწიფო უზრუნველყოფს ყოველი მოქალაქის უფლებას უფასო სავალდებულო ზოგად საბაზო განათლებაზე, ნიჭიერი პირების მიერ სწავლის გაგრძელებასა და განათლების სისტემაზე სახელმწიფო კონტროლს", "სახელმწიფო საგანმანათლებლო დაწესებულებების დაფინანსებას მხოლოდ მუნიციპალიტეტების ადგილობრივი ბიუჯეტების ხარჯზე ახორციელებს", "სახელმწიფო მოქალაქეებისთვის სავალდებულოდ მიიჩნევს საშუალო სპეციალური განათლების მიღებას მხოლოდ დასწრებული ფორმით", "სახელმწიფო ყველა მოქალაქეს უზრუნველყოფს უფასო სრული უმაღლესი განათლების მიღების უფლებით სახელმწიფო უმაღლეს საგანმანათლებლო დაწესებულებებში", "სახელმწიფო მხოლოდ ნიჭიერ პირებს უზრუნველყოფს განათლების გაგრძელების გარანტიით, მათი მატერიალური მდგომარეობის მიუხედავად"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყოველი მოქალაქის უფლებას უფასო სავალდებულო ზოგად საბაზო განათლებაზე, ნიჭიერი პირების მიერ სწავლის გაგრძელებასა და განათლების სისტემაზე სახელმწიფო კონტროლს', 'Düzgün cavab: A) სახელმწიფო უზრუნველყოფს ყოველი მოქალაქის უფლებას უფასო სავალდებულო ზოგად საბაზო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7bc4408d-967e-437e-a083-3ed0ef3c9634', '1376be74-0955-43c4-8e90-ec089c9261db', 'Azərbaycan Respublikası Konstitusiyasının 25-ci maddəsinə əsasən, bərabərlik hüququnun təhsil və əmək münasibətlərində təminatı necə müəyyən olunmuşdur?', 'multiple_choice', '["Vətəndaşların hüquq bərabərliyi yalnız dövlət qulluğunda çalışan şəxslərə şamil edilir, digər sahələrdə fərqli münasibət qanunidir", "İşə qəbul və təhsil prosesində yalnız rəhbərliyin subyektiv mülahizələri əsas götürülür və imtiyazlar müəyyən edilir", "Ayrı-seçkiliyə yalnız müəssisə rəhbərinin yazılı əmri və daxili nizamnamə tələbləri ilə yol verilə bilər", "Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir", "Sosial mənşəyindən və yaşayış yerindən asılı olaraq təhsil müəssisələrinə qəbulda məhdudiyyətlər qoyula bilər"]'::jsonb, 'Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir', 'Düzgün cavab: D) Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyin', '', 32, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bd5494fb-ded1-406d-8517-77126f7da74b', '7bc4408d-967e-437e-a083-3ed0ef3c9634', 'ka', 'კონსტიტუციის 25-ე მუხლის მიხედვით, რომელი სწორი ნორმა ასახავს თანასწორობის უფლების შინაარსს?', '["თანასწორობის უფლება არეგულირებს მხოლოდ 18 წელს მიღწეული მოქალაქეების მონაწილეობას საარჩევნო პროცესში", "სახელმწიფო სასამართლოს წინაშე განსაკუთრებულ პრივილეგირებულ თანასწორობის უფლებას ადგენს მხოლოდ საჯარო მოხელეებისთვის", "ადამიანისა და მოქალაქის უფლებები უზრუნველყოფილია მხოლოდ მოქალაქის კერძო საკუთრების მოცულობიდან გამომდინარე", "სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესისა და სოციალური წარმოშობის მიუხედავად", "ყველას უფლებები და თავისუფლებები თანასწორად ითვლება მხოლოდ აღმასრულებელი ხელისუფლების ორგანოს თანხმობის არსებობის შემთხვევაში"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესისა და სოციალური წარმოშობის მიუხედავად', 'Düzgün cavab: D) სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას რასის,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('814021a2-9d01-43d3-a40a-f06d0065ea83', '1376be74-0955-43c4-8e90-ec089c9261db', 'Azərbaycan Respublikası Konstitusiyasının 32-ci maddəsinə əsasən, şəxsi toxunulmazlıq hüququ təhsil müəssisəsində hansı tələbi irəli sürür?', 'multiple_choice', '["Şəxsi toxunulmazlıq hüququ yalnız rəhbər heyətə aiddir və sıravi işçilərə tətbiq edilmir", "İşçilərin fərdi məlumatları və tibbi arayışları kollektiv qarşısında müzakirə edilməli və elan lövhəsinə vurulmalıdır", "Təhsil müəssisəsi rəhbərliyi işçilərin şəxsi məlumatlarını istədiyi məqsədlə kənar şəxslərə və sosial şəbəkələrə açıqlaya bilər", "Məktəb administrasiyası şagird və işçilərin şəxsi yazışmalarını və fərdi sirlərini əmrlə ictimaiyyətə təqdim etməlidir", "Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına yol verilmir"]'::jsonb, 'Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına, istifadəsinə və yayılmasına yol verilmir', 'Düzgün cavab: E) Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılması', '', 33, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('625be157-2838-47d7-97f5-9f51fce3d1f5', '814021a2-9d01-43d3-a40a-f06d0065ea83', 'ka', 'კონსტიტუციის 32-ე მუხლის თანახმად, რა წესია დადგენილი პირადი ხელშეუხებლობის უფლებასთან დაკავშირებით?', '["პერსონალური მონაცემების რეგისტრაცია საინფორმაციო სისტემებში შეიძლება განახორციელოს ნებისმიერმა უწყებამ პირის ინფორმირების გარეშე", "საგანმანათლებლო დაწესებულების ხელმძღვანელობას შეუძლია საზოგადოებას თავისუფლად წარუდგინოს ინფორმაცია თანამშრომლის პირადი ცხოვრების შესახებ", "პირის მიმოწერისა და სატელეფონო საუბრების საიდუმლოება შეიძლება შეიზღუდოს მხოლოდ შინაგანაწესით", "პირადი ხელშეუხებლობის უფლება მოქმედებს მხოლოდ სამუშაო დროს, როდესაც პირი სამუშაო ადგილზე სამსახურებრივ მოვალეობებს ასრულებს", "მოქალაქის თანხმობის გარეშე დაუშვებელია მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა და გავრცელება, გარდა კანონით პირდაპირ გათვალისწინებული შემთხვევებისა"]'::jsonb, 'მოქალაქის თანხმობის გარეშე დაუშვებელია მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა და გავრცელება, გარდა კანონით პირდაპირ გათვალისწინებული შემთხვევებისა', 'Düzgün cavab: E) მოქალაქის თანხმობის გარეშე დაუშვებელია მისი პირადი ცხოვრების შესახებ ინფორმაციის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('88e2a991-acc4-42b6-89e2-0135956248f3', '1376be74-0955-43c4-8e90-ec089c9261db', '“Təhsil haqqında” AR Qanununun 3-cü maddəsinə əsasən, dövlət siyasətinin əsas prinsiplərindən olan ''Humanistlik'' prinsipinin mahiyyəti nədir?', 'multiple_choice', '["Təhsilalanların akademik nəticələrinin yalnız cəza mexanizmləri vasitəsilə yüksəldilməsi prinsipi", "Yalnız dövlət sifarişi əsasında kadr hazırlığının aparılması və fərdi maraqların məhdudlaşdırılması", "Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul edilməsi", "Təhsil müəssisələrinin maliyyə gəlirlərinin artırılmasının bütün tədris prosesindən üstün tutulması", "Tədris prosesində yalnız xarici ölkələrin təcrübəsinin mütləq şəkildə kopyalanması tələbi"]'::jsonb, 'Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul edilməsi', 'Düzgün cavab: C) Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və', '', 34, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7bb93335-1dc7-4599-8112-86e191eee259', '88e2a991-acc4-42b6-89e2-0135956248f3', 'ka', '„განათლების შესახებ“ კანონის მე-3 მუხლის თანახმად, რას გამოხატავს პრინციპი „ჰუმანურობა“?', '["განათლების სისტემის მოქნილ ინტეგრაციას მსოფლიო საგანმანათლებლო სივრცეში", "საზოგადოების მონაწილეობას საგანმანათლებლო დაწესებულებების მართვაში", "ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას", "სასწავლო პროცესის შესაბამისობაში მოყვანას ეროვნული და საერთაშორისო სტანდარტების მოთხოვნებთან", "ყველა მოქალაქის შესაძლებლობას, უწყვეტად მიიღოს პროფესიული განათლება მთელი სიცოცხლის მანძილზე"]'::jsonb, 'ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას', 'Düzgün cavab: C) ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8b31e1cf-a0ac-440a-b4aa-645e720bf87d', '1376be74-0955-43c4-8e90-ec089c9261db', '“Təhsil haqqında” AR Qanununun 12-ci maddəsinə əsasən, Azərbaycan Respublikasında təhsilin hansı formaları müəyyən edilmişdir?', 'multiple_choice', '["İbtidai, baza və orta ixtisas təhsili", "Formal, qeyri-formal və informal təhsil", "Akademik, peşəkar və ümumi təhsil", "Stasionar, distant və sərbəst təhsil", "Əyani, qiyabi və distant təhsil"]'::jsonb, 'Formal, qeyri-formal və informal təhsil', 'Düzgün cavab: B) Formal, qeyri-formal və informal təhsil', '', 35, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d61727b0-8744-4ff5-8312-e25e92c84639', '8b31e1cf-a0ac-440a-b4aa-645e720bf87d', 'ka', '„განათლების შესახებ“ კანონის მე-12 მუხლის თანახმად, რა არის განათლების დადგენილი ფორმები?', '["სკოლამდელი, საბაზო ზოგადი, პირველადი პროფესიული და უმაღლესი განათლება", "ფორმალური, არაფორმალური და ინფორმალური განათლება", "სახელმწიფო განათლება, მუნიციპალური განათლება და კერძო განათლება", "დაწყებითი განათლება, საბაზო განათლება და სრული საშუალო განათლება", "დასწრებული, დაუსწრებელი, დისტანციური და ექსტერნატი სწავლის ფორმები"]'::jsonb, 'ფორმალური, არაფორმალური და ინფორმალური განათლება', 'Düzgün cavab: B) ფორმალური, არაფორმალური და ინფორმალური განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5211bc40-0e1e-4267-83b7-93ed142b7bfb', '1376be74-0955-43c4-8e90-ec089c9261db', '“Təhsil haqqında” AR Qanununa əsasən, müxtəlif səbəblərdən ümumi təhsildən kənarda qalmış şəxslərə təhsil almaq və ya təhsilin hər hansı pilləsini vaxtından əvvəl bitirmək hüququ verən təhsilalma forması hansıdır?', 'multiple_choice', '["Evdə təhsilalma forması", "Qiyabi təhsilalma forması", "Fərdi təhsilalma forması", "Distant təhsilalma forması", "Sərbəst (eksternat) təhsilalma forması"]'::jsonb, 'Sərbəst (eksternat) təhsilalma forması', 'Düzgün cavab: E) Sərbəst (eksternat) təhsilalma forması', '', 36, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8c99dff9-cc93-492d-b0d7-07c341e7bc35', '5211bc40-0e1e-4267-83b7-93ed142b7bfb', 'ka', 'სწავლის რომელი ფორმა აძლევს განათლების მიღების უფლებას იმ პირებს, რომლებიც სხვადასხვა მიზეზით დარჩნენ ზოგადი განათლების მიღმა?', '["შინ სწავლება", "დაუსწრებელი სწავლება", "ინფორმალური განათლება", "დისტანციური სწავლება", "დამოუკიდებელი (ექსტერნატის) სწავლის ფორმა"]'::jsonb, 'დამოუკიდებელი (ექსტერნატის) სწავლის ფორმა', 'Düzgün cavab: E) დამოუკიდებელი (ექსტერნატის) სწავლის ფორმა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8e8960c4-680a-45d5-adae-2e60d5ee15a9', '1376be74-0955-43c4-8e90-ec089c9261db', '“Təhsil haqqında” AR Qanununun 32-ci maddəsinə əsasən, təhsil prosesi iştirakçılarının vəzifələrinə aid olan müddəa hansıdır?', 'multiple_choice', '["Həmkarlar ittifaqının fəaliyyətinə rəhbərlik etmək və təşkilati qərarlar qəbul etmək", "Məktəbin əmlakını icarəyə vermək və əldə olunan gəliri şəxsi məqsədlər üçün istifadə etmək", "İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını mənimsəmək və daxili intizam qaydalarına riayət etmək", "Tədris planlarını nazirliyin təsdiqi olmadan müstəqil şəkildə dəyişdirmək", "Müəssisənin ştat cədvəlini və illik maliyyə xərclər smetasını təkbaşına təsdiq etmək"]'::jsonb, 'İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını mənimsəmək və daxili intizam qaydalarına riayət etmək', 'Düzgün cavab: C) İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri, müasir təlim metodlarını mən', '', 37, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3d83d009-0e2f-4eff-985b-b87581b89852', '8e8960c4-680a-45d5-adae-2e60d5ee15a9', 'ka', '„განათლების შესახებ“ კანონის 32-ე მუხლის თანახმად, რომელი დებულება განეკუთვნება პედაგოგთა (საგანმანათლებლო საქმიანობის განმახორციელებელთა) მოვალეობებს?', '["ახალი სასწავლო პროგრამებისა და სახელმძღვანელოების პროექტების თავისუფლად არჩევა", "პატივისა და ღირსებისადმი პატივისცემისა და უსაფრთხო სამუშაო პირობების მოთხოვნა", "კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლოგიების ათვისება და მათი გამოყენება სასწავლო პროცესში", "საგანმანათლებლო დაწესებულებაში შესაბამისი თანამდებობის დაკავება და არჩევით ორგანოებში წარმომადგენლობა", "საგანმანათლებლო დაწესებულების მართვაში წინადადებებით გამოსვლა"]'::jsonb, 'კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლოგიების ათვისება და მათი გამოყენება სასწავლო პროცესში', 'Düzgün cavab: C) კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('cefb2515-2e41-4ba9-83e1-7f90d1261d9b', '1376be74-0955-43c4-8e90-ec089c9261db', '“Ümumi təhsil haqqında” AR Qanununa əsasən, ümumi təhsil pilləsinin səviyyələri hansı ardıcıllıqla düzgün göstərilmişdir?', 'multiple_choice', '["Ümumi ibtidai, orta məktəb, gimnaziya və lisey səviyyələri", "Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)", "Məktəbəqədər təhsil, natamam orta təhsil və orta ixtisas təhsili", "Erkən inkişaf mərhələsi, ibtidai təhsil, baza təhsili və ali təhsil", "İbtidai təhsil, əsas təhsil, peşə liseyi və kollec səviyyəsi"]'::jsonb, 'Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)', 'Düzgün cavab: B) Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və ta', '', 38, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('5fa88c0c-e17d-4306-b859-14683dfb55ab', 'cefb2515-2e41-4ba9-83e1-7f90d1261d9b', 'ka', '„ზოგადი განათლების შესახებ“ კანონის თანახმად, რა არის ზოგადი განათლების საფეხურის დონეები?', '["სკოლამდელი განათლება (3–5 წელი), ზოგადი განათლება (I–XI) და ბაკალავრიატის დონე", "სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული საშუალო განათლება (X–XI)", "მხოლოდ საბაზო ზოგადი განათლება (I–IX) და სრული საშუალო განათლება (X–XI)", "დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და პროფესიული განათლების დონე", "დაწყებითი განათლება (I–IV), ძირითადი განათლება (V–VIII) და საშუალო სპეციალური განათლება (IX–XI)"]'::jsonb, 'სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული საშუალო განათლება (X–XI)', 'Düzgün cavab: B) სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('460c8853-a03a-44bd-8759-471f04c70f1d', '1376be74-0955-43c4-8e90-ec089c9261db', '“Ümumi təhsil haqqında” AR Qanununun 21-ci maddəsinə əsasən, ümumi təhsil prosesində təhsilalanların hüquqlarına **AİD EDİLMƏYƏN** müddəa hansıdır?', 'multiple_choice', '["Dövlət məktəblərində dərsliklərlə pulsuz təmin olunmaq", "Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq", "Təhlükəsiz və sağlam təhsil şəraiti ilə təmin olunmaq", "Ləyaqətini alçaldan rəftardan müdafiə olunmaq", "Təhsil müəssisəsinin kitabxana və laboratoriyasından pulsuz istifadə etmək"]'::jsonb, 'Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq', 'Düzgün cavab: B) Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoj', '', 39, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7a2fde9e-1796-48b7-9571-18618d115fdf', '460c8853-a03a-44bd-8759-471f04c70f1d', 'ka', '„ზოგადი განათლების შესახებ“ კანონის 21-ე მუხლის თანახმად, რომელი დებულება არ განეკუთვნება მოსწავლეთა უფლებებს?', '["საგანმანათლებლო დაწესებულების არსებული ინფრასტრუქტურით უფასო სარგებლობა", "დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება", "სახელმწიფო და მუნიციპალურ სკოლებში სახელმძღვანელოებით უფასოდ უზრუნველყოფა", "სიცოცხლისა და ჯანმრთელობისთვის უსაფრთხო სასწავლო პირობებით უზრუნველყოფა", "დაცვა ადამიანის ღირსების შემლახველი ძალადობის შემთხვევებისგან"]'::jsonb, 'დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება', 'Düzgün cavab: B) დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1d1d925a-f995-4df9-91e6-fa5f22b86624', '1376be74-0955-43c4-8e90-ec089c9261db', 'Dövlət və bələdiyyə ümumi təhsil müəssisələrinin Nümunəvi Nizamnaməsinə əsasən, məktəb direktorunun vəzifəyə təyin və vəzifədən azad edilməsi necə həyata keçirilir?', 'multiple_choice', '["Məktəb həmkarlar komitəsinin sədri tərəfindən sərəncamla", "Yerli bələdiyyə orqanının birtərəfli qərarı və təsdiqi ilə", "Pedaqoji Şuranın gizli səsverməsi və mütləq səs çoxluğu ilə", "Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən qanunvericiliklə müəyyən edilmiş qaydada", "Məktəbin Valideyn-Müəllim Assosiasiyası tərəfindən birbaşa seçki yolu ilə"]'::jsonb, 'Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən qanunvericiliklə müəyyən edilmiş qaydada', 'Düzgün cavab: D) Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən qanunveric', '', 40, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c92405bc-d9bb-43f8-aa72-674c327f9b10', '1d1d925a-f995-4df9-91e6-fa5f22b86624', 'ka', 'სანიმუშო წესდების თანახმად, ვინ ახორციელებს სკოლის საქმიანობის მიმდინარე ხელმძღვანელობას?', '["რაიონული აღმასრულებელი ხელისუფლების მიერ დანიშნული სპეციალური წარმომადგენელი", "საგანმანათლებლო დაწესებულების პროფკავშირული კომიტეტის ხელმძღვანელი", "სკოლის მშობელთა და მასწავლებელთა ასოციაციის გამგეობის თავმჯდომარე", "შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს (განათლების მართვის ორგანოს) მიერ თანამდებობაზე დანიშნული დირექტორი", "დაწესებულების პედაგოგიური საბჭოს არჩევითი მდივანი"]'::jsonb, 'შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს (განათლების მართვის ორგანოს) მიერ თანამდებობაზე დანიშნული დირექტორი', 'Düzgün cavab: D) შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს (განათლების მართვის ორგანოს) მიერ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f50f693b-a944-48c4-a7e8-4d6f2daf836e', '1376be74-0955-43c4-8e90-ec089c9261db', 'Ümumi təhsil müəssisələrində Pedaqoji Şura haqqında Əsasnaməyə əsasən, qərarların qəbul edilməsi üçün yetərsay (kvorum) necə müəyyən edilir?', 'multiple_choice', '["İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilir", "Üzvlərin yarısı iştirak etdikdə və valideyn komitəsinin razılığı olduqda", "Pedaqoji heyətin 90%-i iştirak etdikdə və üçdə iki səs çoxluğu ilə", "Üzvlərin dörddə bir hissəsi iştirak etdikdə və direktor təsdiq etdikdə", "Yalnız fənn metodbirləşmə rəhbərlərinin iştirakı ilə mütləq yekdilliklə"]'::jsonb, 'İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilir', 'Düzgün cavab: A) İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qəra', '', 41, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('293bde95-2b06-4826-9711-787852bff753', 'f50f693b-a944-48c4-a7e8-4d6f2daf836e', 'ka', 'პედაგოგიური საბჭოს შესახებ დებულების თანახმად, როგორია გადაწყვეტილებების მიღების წესი?', '["სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით", "გადაწყვეტილებები ძალაში შედის მხოლოდ სკოლის დირექტორის ინდივიდუალური ზეპირი თანხმობით", "სხდომაზე ხმის უფლება აქვთ მხოლოდ საგნობრივი კათედრების ხელმძღვანელებს", "პედაგოგიური საბჭოს გადაწყვეტილებებს აქვს სარეკომენდაციო ხასიათი და არ მტკიცდება ოფიციალური ბრძანებით", "გადაწყვეტილებები გამოიყენება მხოლოდ რაიონის განათლების სექტორის წერილობითი თანხმობის მიღების შემდეგ"]'::jsonb, 'სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით', 'Düzgün cavab: A) სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a1725059-28cf-420d-9808-2e3baf1387e8', '1376be74-0955-43c4-8e90-ec089c9261db', 'Azərbaycan Respublikasının Əmək Məcəlləsinin 89 və 91-ci maddələrinə əsasən, iş vaxtının normal və qısaldılmış müddəti ilə bağlı hansı norma təsbit edilmişdir?', 'multiple_choice', '["Bütün işçilər üçün həftəlik iş vaxtı fərq qoyulmadan eyni — 45 saatdır", "Həftəlik normal iş vaxtı 48 saat, qısaldılmış iş vaxtı isə 42 saat müəyyən edilir", "Normal iş vaxtı həftədə 35 saat, əlillər üçün isə həftədə 20 saatdır", "Həftəlik iş vaxtı direktor tərəfindən sərbəst müəyyən olunur və məhdudiyyət qoyulmur", "Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə qısaldılmış iş vaxtı həftədə 36 saatdan artıq ola bilməz"]'::jsonb, 'Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə qısaldılmış iş vaxtı həftədə 36 saatdan artıq ola bilməz', 'Düzgün cavab: E) Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün i', '', 42, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f0b524f6-a3e3-4308-b2a0-2e37c84534f0', 'a1725059-28cf-420d-9808-2e3baf1387e8', 'ka', 'შრომის კოდექსის 89-ე და 91-ე მუხლების თანახმად, როგორია სამუშაო დროის ნორმალური და შემოკლებული ხანგრძლივობა?', '["კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 48 საათს, ხოლო 16 წლამდე ასაკის მუშაკებისთვის - 36 საათს", "კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 45 საათს, ხოლო პედაგოგიური პერსონალისთვის - 18 საათს", "კვირეული ნორმალური სამუშაო დრო განისაზღვრება 36 საათით, ხოლო ორსული ქალებისთვის - 24 საათით", "ყველა მუშაკისთვის გამოიყენება ერთიანი კვირეული 40-საათიანი სრული სამუშაო დრო", "კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის - კვირაში 36 საათს"]'::jsonb, 'კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის - კვირაში 36 საათს', 'Düzgün cavab: E) კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a095ddbf-b828-487e-afe1-7f44689ed763', '1376be74-0955-43c4-8e90-ec089c9261db', 'Əmək Məcəlləsinin 186-cı maddəsinə əsasən, əmək və icra intizamını pozan işçiyə işəgötürən tərəfindən tətbiq edilə bilən intizam tənbehi tədbirləri hansılardır?', 'multiple_choice', '["Xəbərdarlıq, töhmət, vəzifədən azad etmə və cərimə", "Töhmət, maaşın 50% tutulması və vəzifənin aşağı salınması", "Şifahi töhmət, yazılı töhmət, şiddətli töhmət və işdən çıxarma", "İnzibati cərimə, ictimai işlər və müqaviləyə xitam", "Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi"]'::jsonb, 'Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi', 'Düzgün cavab: E) Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutu', '', 43, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c0f41924-6b2e-4b43-b08b-7d112bcf1989', 'a095ddbf-b828-487e-afe1-7f44689ed763', 'ka', 'შრომის კოდექსის 186-ე მუხლის თანახმად, როგორია დისციპლინური სახდელების სრული ჩამონათვალი?', '["ზეპირი გაფრთხილება, საზოგადოებრივი საყვედური, ჯარიმა და შვებულების გაუქმება", "მხოლოდ წერილობითი საყვედური და მუშაკისთვის საპატიო წოდებების ჩამორთმევა", "თანამდებობრივი სარგოს 50%-ით შემცირება, მორიგი შვებულების არმიცემა", "ადმინისტრაციული ჯარიმა, სავალდებულო საზოგადოებრივი სამუშაო და სხვა დაწესებულებაში იძულებითი გადაყვანა", "საყვედური, სასტიკი საყვედური ბოლო გაფრთხილებით, ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა, როდესაც ეს გათვალისწინებულია კოლექტიური ხელშეკრულებით, და შრომითი ხელშეკრულების შეწყვეტა"]'::jsonb, 'საყვედური, სასტიკი საყვედური ბოლო გაფრთხილებით, ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა, როდესაც ეს გათვალისწინებულია კოლექტიური ხელშეკრულებით, და შრომითი ხელშეკრულების შეწყვეტა', 'Düzgün cavab: E) საყვედური, სასტიკი საყვედური ბოლო გაფრთხილებით, ჯარიმა ყოველთვიური ხელფასის არაუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('166a7db8-1474-407f-84b8-c4a0a3d4b987', '1376be74-0955-43c4-8e90-ec089c9261db', 'AR Əmək Məcəlləsinin 187 və 188-ci maddələrinə əsasən, intizam tənbehinin tətbiqi və qüvvədə olma müddəti qaydası necədir?', 'multiple_choice', '["İntizam tənbehi verildikdə işçidən izahat alınır və tənbeh verildiyi gündən 1 il qüvvədə qalır", "İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz", "İzahat mütləqdir, tənbeh yalnız 1 ay qüvvədə olur", "İzahat tələb edilmədən tənbeh verilə bilər və 2 il qüvvədə qalır", "İzahat tələb olunmur, tənbeh məhkəmə qərarı ilə 3 il qüvvədə qalır"]'::jsonb, 'İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz', 'Düzgün cavab: B) İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbe', '', 44, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('72b8d529-3193-43ae-8119-e5cd539d0101', '166a7db8-1474-407f-84b8-c4a0a3d4b987', 'ka', 'შრომის კოდექსის 187-ე მუხლის თანახმად, როგორია დისციპლინური სახდელის დადების წესი?', '["ერთი დისციპლინური გადაცდომისთვის მუშაკს შეიძლება ერთდროულად დაედოს როგორც სასტიკი საყვედური, ასევე შეუწყდეს ხელშეკრულება", "დისციპლინური სახდელის დადებამდე მუშაკს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია მისი დადების დღიდან 1 წლის განმავლობაში", "დისციპლინური სახდელი ინიშნება მხოლოდ სასამართლოს გადაწყვეტილების საფუძველზე", "თუ მუშაკი უარს იტყვის წერილობითი ახსნა-განმარტების მიცემაზე, მის მიმართ არ შეიძლება გამოყენებულ იქნეს არანაირი სახდელი", "დისციპლინური სახდელი შეიძლება დაედოს გადაცდომის გამოვლენის დღიდან 6 თვის გასვლის შემდეგაც და ძალაში რჩება 2 წელი"]'::jsonb, 'დისციპლინური სახდელის დადებამდე მუშაკს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია მისი დადების დღიდან 1 წლის განმავლობაში', 'Düzgün cavab: B) დისციპლინური სახდელის დადებამდე მუშაკს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტებ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2f7dc3f5-42ea-4961-a0df-057a5f46f5a5', '1376be74-0955-43c4-8e90-ec089c9261db', 'Əmək Məcəlləsinin 69 və 172-ci maddələrinə əsasən, işçinin öz təşəbbüsü ilə əmək müqaviləsinə xitam verilməsi və son haqq-hesabın ödənilməsi qaydası necədir?', 'multiple_choice', '["İşçi 3 iş günü əvvəl xəbərdarlıq edir, son haqq-hesab 1 ay sonra köçürülür", "İşçi xəbərdarlıq etmədən dərhal işi tərk edir, ödəniş rəhbərliyin qərarı ilə verilir", "İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab sonuncu iş günündən gec olmayaraq tam ödənilir", "İşçi 15 gün əvvəl ərizə verir, haqq-hesab növbəti ayın maaş günündə ödənilir", "İşçi 2 həftə əvvəl şifahi xəbərdarlıq edir, kompensasiya ödənilmir"]'::jsonb, 'İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab sonuncu iş günündən gec olmayaraq tam ödənilir', 'Düzgün cavab: C) İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haq', '', 45, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('fdd8abb2-9473-46fa-92c0-f6938b9a46f1', '2f7dc3f5-42ea-4961-a0df-057a5f46f5a5', 'ka', 'შრომის კოდექსის 69-ე და 172-ე მუხლების თანახმად, როგორია დასაქმებულის ინიციატივით შრომითი ხელშეკრულების შეწყვეტის წესი?', '["შრომითი ხელშეკრულების შეწყვეტა შესაძლებელია მხოლოდ პროფკავშირის თანხმობით", "დასაქმებულმა შეტყობინება უნდა წარადგინოს 2 კვირით ადრე; კომპენსაცია გადაიხდება მომდევნო წელს", "დასაქმებულმა დამსაქმებელს უნდა აცნობოს წერილობითი განცხადებით 1 კალენდარული თვით ადრე; საბოლოო ანგარიშსწორება ხდება არაუგვიანეს ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღისა", "დასაქმებულს შეუძლია დატოვოს სამსახური ნებისმიერ დღეს გაფრთხილების გარეშე", "დასაქმებულმა ზეპირად უნდა გააფრთხილოს 3 დღით ადრე"]'::jsonb, 'დასაქმებულმა დამსაქმებელს უნდა აცნობოს წერილობითი განცხადებით 1 კალენდარული თვით ადრე; საბოლოო ანგარიშსწორება ხდება არაუგვიანეს ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღისა', 'Düzgün cavab: C) დასაქმებულმა დამსაქმებელს უნდა აცნობოს წერილობითი განცხადებით 1 კალენდარული თვით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('39f46716-5bcb-47ba-8b39-34bdae57c93b', '1376be74-0955-43c4-8e90-ec089c9261db', 'Kompüter şəbəkələrinin əhatə dairəsinə görə LAN və WAN şəbəkələrinin başlıca fərqi nədir?', 'multiple_choice', '["LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir", "LAN yalnız dövlət orqanlarında, WAN isə kommersiya şirkətlərində istifadə olunur", "LAN yalnız simli kabellərlə, WAN isə yalnız simsiz peyk rabitəsi ilə qurulur", "LAN yalnız internetə çıxış üçün, WAN isə lokal resursları paylaşmaq üçündür", "LAN-da məlumat ötürmə sürəti çox aşağı, WAN-da isə ifrat yüksək olur"]'::jsonb, 'LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir', 'Düzgün cavab: A) LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, W', '', 46, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('42df4cce-3c85-4865-90bd-e7c4a3fd09b2', '39f46716-5bcb-47ba-8b39-34bdae57c93b', 'ka', 'რა არის ძირითადი განსხვავება LAN და WAN ქსელებს შორის?', '["LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებულ კომპიუტერებს, ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს", "LAN გამოიყენება მხოლოდ ინტერნეტთან წვდომისთვის, ხოლო WAN უზრუნველყოფს ლოკალური ფაილებისა და პრინტერების გაზიარებას", "LAN ქსელში მონაცემები არ იშიფრება, ხოლო WAN ქსელში შიდა რესურსების გაზიარება სრულად აკრძალულია", "LAN განკუთვნილია მხოლოდ სახელმწიფო ორგანოებისთვის, ხოლო WAN - მხოლოდ ინდივიდუალური მომხმარებლებისთვის", "LAN იგება მხოლოდ ოპტიკურ-ბოჭკოვანი კაბელებით, ხოლო WAN - მხოლოდ უსადენო Bluetooth-ით"]'::jsonb, 'LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებულ კომპიუტერებს, ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს', 'Düzgün cavab: A) LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებულ კო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e691eac3-8d02-4ace-b407-a7f5b8005316', '1376be74-0955-43c4-8e90-ec089c9261db', 'İnternet şəbəkəsində domen adlarını IP ünvanlarına çevirən əsas xidmət və protokol hansıdır?', 'multiple_choice', '["DNS (Domain Name System)", "ARP (Address Resolution Protocol)", "Proxy Service", "DHCP (Dynamic Host Configuration Protocol)", "NAT (Network Address Translation)"]'::jsonb, 'DNS (Domain Name System)', 'Düzgün cavab: A) DNS (Domain Name System)', '', 47, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a6c590d9-9f66-4fc8-9e0e-4393c9e00b4d', 'e691eac3-8d02-4ace-b407-a7f5b8005316', 'ka', 'რომელია ძირითადი ქსელური სერვისი, რომელიც დომენურ სახელებს IP მისამართებად გარდაქმნის?', '["DNS (Domain Name System) - განაწილებული იერარქიული დომენური სახელების სისტემა", "FTP (File Transfer Protocol)", "SNMP (Simple Network Management Protocol)", "SMTP (Simple Mail Transfer Protocol)", "DHCP (Dynamic Host Configuration Protocol)"]'::jsonb, 'DNS (Domain Name System) - განაწილებული იერარქიული დომენური სახელების სისტემა', 'Düzgün cavab: A) DNS (Domain Name System) - განაწილებული იერარქიული დომენური სახელების სისტემა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('06d55981-f994-49e9-846d-f7574163f5c8', '1376be74-0955-43c4-8e90-ec089c9261db', 'İnformasiya təhlükəsizliyində ''İki faktorlu autentifikasiya'' (2FA) istifadəsinin başlıca məqsədi nədir?', 'multiple_choice', '["Şifrənin unudulduğu halda avtomatik bərpasını təmin etmək", "Faylların bulud yaddaşına ikiqat sürətlə yüklənməsini təmin etmək", "Kompüterin əməliyyat sistemini viruslardan tam qorumaq", "Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək", "Şəbəkədə internet sürətini iki dəfə artırmaq"]'::jsonb, 'Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək', 'Düzgün cavab: D) Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifi', '', 48, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('04e9b84f-747c-4895-8c00-c6e8c5393d6b', '06d55981-f994-49e9-846d-f7574163f5c8', 'ka', 'რა არის ორფაქტორიანი ავთენტიფიკაციის (2FA) მექანიზმის მთავარი უპირატესობა?', '["მომხმარებლისთვის ერთდროულად მხოლოდ ერთი კომპიუტერიდან შესვლის სავალდებულო ნებართვის მიცემა", "ქსელის შიგნით კომპიუტერის ინტერნეტის სიჩქარის გაორმაგება", "ოპერაციული სისტემის დრაივერების ავტომატური განახლება და ლიცენზიის ვადის გაგრძელება", "პაროლის მოპარვის/გატეხვის შემთხვევაშიც კი, ანგარიშზე შესვლის დაბლოკვა მეორე დამოუკიდებელი დამადასტურებელი საშუალების (SMS კოდი, აუტენტიფიკატორის აპლიკაცია ან უსაფრთხოების გასაღები) გარეშე", "მომხმარებლის მიერ შეყვანილი ფაილების მოცულობის ავტომატური შეკუმშვა მეხსიერების დაზოგვის მიზნით"]'::jsonb, 'პაროლის მოპარვის/გატეხვის შემთხვევაშიც კი, ანგარიშზე შესვლის დაბლოკვა მეორე დამოუკიდებელი დამადასტურებელი საშუალების (SMS კოდი, აუტენტიფიკატორის აპლიკაცია ან უსაფრთხოების გასაღები) გარეშე', 'Düzgün cavab: D) პაროლის მოპარვის/გატეხვის შემთხვევაშიც კი, ანგარიშზე შესვლის დაბლოკვა მეორე დამო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('31cc0bc6-de37-4ddb-9de6-b5b854c92d45', '1376be74-0955-43c4-8e90-ec089c9261db', 'Fırıldaqçıların etibarlı təşkilat adından saxta e-poçt göndərərək istifadəçinin məxfi məlumatlarını ələ keçirməsi hansı kiberhücum növüdür?', 'multiple_choice', '["Spoofing", "Brute Force", "Ransomware", "Sniffing", "Fişinq (Phishing)"]'::jsonb, 'Fişinq (Phishing)', 'Düzgün cavab: E) Fişinq (Phishing)', '', 49, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('20701c32-7f06-44f5-afba-adf5e4447f52', '31cc0bc6-de37-4ddb-9de6-b5b854c92d45', 'ka', 'კიბერშეტევის რომელი სახეა, როდესაც თაღლითები სანდო ორგანიზაციის სახელით ყალბი ელფოსტის გაგზავნით ითვისებენ მონაცემებს?', '["DDoS (მომსახურებაზე უარის თქმის) შეტევა", "დეფრაგმენტაციის შეტევა", "Buffer Overflow (ბუფერის გადავსება)", "SQL Injection (მონაცემთა ბაზაში ჩარევა)", "ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) - საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტის მეშვეობით"]'::jsonb, 'ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) - საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტის მეშვეობით', 'Düzgün cavab: E) ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) - საიდენტიფიკაციო მონაცემების მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('23bb30ec-9022-457e-9641-82c059fc6b73', '1376be74-0955-43c4-8e90-ec089c9261db', 'Microsoft Word proqramında abzasın girintilərini dəqiq tənzimləmək üçün hansı alətdən istifadə olunur?', 'multiple_choice', '["Vəziyyət zolağı və miqyas sürüşdürücüsü", "Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi", "Naviqasiya paneli və axtarış pəncərəsi", "Şaquli xətkeş və səhifə nömrələmə aləti", "Sürətli müraciət paneli və stil qalereyası"]'::jsonb, 'Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi', 'Düzgün cavab: B) Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph', '', 50, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7fd759fb-67e8-442d-a384-274245530bf1', '23bb30ec-9022-457e-9641-82c059fc6b73', 'ka', 'Word-ში რომელი ელემენტი გამოიყენება აბზაცის შეწევების ზუსტი ვიზუალური რეგულირებისთვის?', '["სწრაფი წვდომის პანელი (Quick Access Toolbar)", "ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული მორბენალები (First Line, Hanging, Left/Right Indent) და Paragraph დიალოგური ფანჯარა", "სტატუსის ზოლი (Status Bar)", "ნავიგაციის პანელი (Navigation Pane)", "დოკუმენტის მასშტაბირების მორბენალი (Zoom Slider)"]'::jsonb, 'ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული მორბენალები (First Line, Hanging, Left/Right Indent) და Paragraph დიალოგური ფანჯარა', 'Düzgün cavab: B) ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული მორბენალები (First Line, Hang', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('43ff4a39-1977-4185-924f-812cb093e7ef', '1376be74-0955-43c4-8e90-ec089c9261db', 'Microsoft Word sənədində bəzi səhifələri şaquli, bəzi səhifələri isə üfüqi (albom) etmək üçün hansı əməliyyat icra olunmalıdır?', 'multiple_choice', '["Sənəd iki ayrı fayla bölünüb hər birinin oriyentasiyası ayrıca təyin edilməlidir", "Hər səhifə üçün ayrıca Page Break əlavə edilib oriyentasiya dəyişdirilməlidir", "Səhifə kənar boşluqları dəyişdirilərək üfüqi effekt yaradılmalıdır", "Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir", "Mətn qutuları istifadə edilərək səhifə fırladılmalıdır"]'::jsonb, 'Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir', 'Düzgün cavab: D) Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin O', '', 51, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c2a03ad0-ae15-4b42-8c65-35b83f425541', '43ff4a39-1977-4185-924f-812cb093e7ef', 'ka', 'რა ოპერაცია უნდა შესრულდეს Word-ის დოკუმენტში ზოგიერთი გვერდის ვერტიკალურ (Portrait), ხოლო ზოგიერთის ჰორიზონტალურ (Landscape) ორიენტაციაში დასაფორმატებლად?', '["დოკუმენტის აუცილებლად შენახვა PDF ფორმატში", "ტექსტის შრიფტის ზომის შემცირება 10 pt დონემდე", "გვერდებს შორის ჩვეულებრივი გვერდის წყვეტის (Page Break) დამატება", "დოკუმენტში სექციის წყვეტის (Section Break / Next Page) დამატება და ამ სექციის გვერდის ორიენტაციის შეცვლა", "ერთიანი ცხრილის შაბლონის გამოყენება მთელი დოკუმენტისთვის"]'::jsonb, 'დოკუმენტში სექციის წყვეტის (Section Break / Next Page) დამატება და ამ სექციის გვერდის ორიენტაციის შეცვლა', 'Düzgün cavab: D) დოკუმენტში სექციის წყვეტის (Section Break / Next Page) დამატება და ამ სექციის გვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2b4cdf80-0994-4994-9988-4d8a904b1a2d', '1376be74-0955-43c4-8e90-ec089c9261db', 'Microsoft Word proqramında başlıqlara əsasən avtomatik yenilənən Mündəricat yaratmaq üçün hansı taba müraciət edilir?', 'multiple_choice', '["Insert > Table of Contents", "Review > Table of Contents", "Layout > Table of Contents", "References (İstinadlar) tabı > Table of Contents", "View > Navigation Pane"]'::jsonb, 'References (İstinadlar) tabı > Table of Contents', 'Düzgün cavab: D) References (İstinadlar) tabı > Table of Contents', '', 52, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c1240854-0d8f-44b9-9b1b-bb7da57d8b3b', '2b4cdf80-0994-4994-9988-4d8a904b1a2d', 'ka', 'რომელ ჩანართს (Tab) უნდა მივმართოთ Word-ში სათაურებზე დაფუძნებული ავტომატურად განახლებადი სარჩევის (Table of Contents) შესაქმნელად?', '["Layout (გვერდის განლაგება)", "Mailings (დაგზავნა)", "Review (რეცენზირება)", "References (ბმულები/სქოლიოები) ჩანართი > Table of Contents ჯგუფი", "Design (დიზაინი)"]'::jsonb, 'References (ბმულები/სქოლიოები) ჩანართი > Table of Contents ჯგუფი', 'Düzgün cavab: D) References (ბმულები/სქოლიოები) ჩანართი > Table of Contents ჯგუფი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('de37ca5b-b6df-4c49-90af-205f94edb83c', '1376be74-0955-43c4-8e90-ec089c9261db', 'Microsoft Excel cədvəlində `$C$2` mütləq xana ünvanı olan düstur başqa xanalara kopyalandıqda necə dəyişir?', 'multiple_choice', '["Yalnız sətir sabit qalır, sütun dəyişir", "Düstur xəta verir və #REF! qaytarır", "Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır", "Həm sütun, həm sətir avtomatik sürüşür", "Yalnız sütun sabit qalır, sətir dəyişir"]'::jsonb, 'Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', 'Düzgün cavab: C) Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', '', 53, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2fe5c460-4120-4e46-9fe1-f325ab1fc091', 'de37ca5b-b6df-4c49-90af-205f94edb83c', 'ka', 'როგორ იცვლება Excel-ის ცხრილში ფორმულა, რომელიც შეიცავს უჯრის აბსოლუტურ მისამართს $C$2, სხვა უჯრებში კოპირებისას?', '["მხოლოდ სტრიქონის ნომერი რჩება უცვლელი, ხოლო სვეტის ასო იცვლება მარჯვნივ კოპირებისას", "ფორმულა ავტომატურად აბრუნებს ნულოვან მნიშვნელობას", "ვინაიდან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური მიმართვა)", "მხოლოდ სვეტის სახელი რჩება უცვლელი, ხოლო სტრიქონის ნომერი იზრდება ქვემოთ კოპირებისას", "როგორც სვეტის (C), ასევე სტრიქონის (2) ინდექსი ავტომატურად ინაცვლებს კოპირების მიმართულების შესაბამისად"]'::jsonb, 'ვინაიდან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური მიმართვა)', 'Düzgün cavab: C) ვინაიდან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკოპირდეს ფო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3df65403-0435-4d1c-9050-11b5bae51b2c', '1376be74-0955-43c4-8e90-ec089c9261db', 'Microsoft Excel proqramında `A1:A10` diapazonunda yalnız qiyməti 50-dən böyük olan xanaların sayını hesablamaq üçün hansı funksiya düzgündür?', 'multiple_choice', '["=COUNTIF(A1:A10; >50)", "=COUNTIFS(A1:A10; \">50\")", "=IF(A1:A10>50; COUNT(A1:A10))", "=COUNTIF(A1:A10; \">50\")", "=SUMIF(A1:A10; \">50\")"]'::jsonb, '=COUNTIF(A1:A10; ">50")', 'Düzgün cavab: D) =COUNTIF(A1:A10; ">50")', '', 54, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('77f6f824-57cd-43a4-a0c9-f941521c82af', '3df65403-0435-4d1c-9050-11b5bae51b2c', 'ka', 'Excel-ში რომელი ფუნქციაა სწორი A1:A10 დიაპაზონში მხოლოდ იმ უჯრების რაოდენობის დასათვლელად, რომელთა მნიშვნელობა 50-ზე მეტია?', '["=AVERAGEIF(A1:A10; 50) - საშუალო არითმეტიკულის ფუნქცია", "=COUNTA(A1:A10; 50) - შევსებული უჯრების რაოდენობა", "=COUNT(A1:A10; >50) - სინტაქსი მცდარია", "=COUNTIF(A1:A10;\">50\") - პირობითი დათვლის ფუნქცია", "=SUM(A1:A10; \">50\") - პირობითი ჯამის ფუნქცია"]'::jsonb, '=COUNTIF(A1:A10;">50") - პირობითი დათვლის ფუნქცია', 'Düzgün cavab: D) =COUNTIF(A1:A10;">50") - პირობითი დათვლის ფუნქცია', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('093d6c53-fa55-4717-9bdf-bacb5f460b74', '1376be74-0955-43c4-8e90-ec089c9261db', 'Microsoft Excel-də B2 xanasındakı əməkhaqqı 800-dən çox olduqda 15% mükafat, əks halda 5% hesablayan düstur hansıdır?', 'multiple_choice', '["=IF(B2>800; B2*0.15; B2*0.05)", "=IF(B2>=800; B2*0.15; B2*0.05)", "=IFS(B2>800; B2*0.15; TRUE; B2*0.05)", "=IF(B2>800; B2*15%; B2*5%)", "=SWITCH(B2>800; TRUE; B2*0.15; FALSE; B2*0.05)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: A) =IF(B2>800; B2*0.15; B2*0.05)', '', 55, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c615a76d-c8ea-406c-8f04-6f607f9a2cca', '093d6c53-fa55-4717-9bdf-bacb5f460b74', 'ka', 'Excel-ში რომელი ფორმულა ითვლის 15%-იან პრემიას, როდესაც B2 უჯრაში ხელფასი 800-ზე მეტია, ხოლო წინააღმდეგ შემთხვევაში 5%-ს?', '["=IF(B2>800; B2*0.15; B2*0.05) - ლოგიკური IF ფუნქციით", "=SUMIF(B2>800; B2*15%; B2*5%) - პირობითი ჯამი", "=VLOOKUP(B2; 800; 15; 5) - ძიების ფუნქცია", "=COUNTIF(B2; 800; 15%) - დათვლის ფუნქცია", "=MAX(B2>800; 0.15; 0.05) - მაქსიმუმის ფუნქცია"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05) - ლოგიკური IF ფუნქციით', 'Düzgün cavab: A) =IF(B2>800; B2*0.15; B2*0.05) - ლოგიკური IF ფუნქციით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1a972a5e-42b3-4ef8-8dfd-d87cd56b5d76', '1376be74-0955-43c4-8e90-ec089c9261db', 'Microsoft Excel proqramında xanaya yalnız müəyyən diapazonda ədədlərin daxil edilməsinə icazə verən alət hansıdır?', 'multiple_choice', '["Conditional Formatting", "Data Validation (Verilənlərin yoxlanılması)", "Filter & Sort", "Group and Outline", "Data Consolidation"]'::jsonb, 'Data Validation (Verilənlərin yoxlanılması)', 'Düzgün cavab: B) Data Validation (Verilənlərin yoxlanılması)', '', 56, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('986012f9-a557-4333-928d-2b209bbdbff2', '1a972a5e-42b3-4ef8-8dfd-d87cd56b5d76', 'ka', 'რომელია ის ხელსაწყო Excel-ში, რომელიც უჯრაში მხოლოდ გარკვეულ დიაპაზონში რიცხვების შეყვანის საშუალებას იძლევა?', '["Flash Fill (მყისიერი შევსება) - ავტომატური შევსება", "Data Validation (მონაცემთა ვალიდაცია/შემოწმება) - Data ჩანართში Whole Number, Decimal, List, Date კრიტერიუმებით", "Remove Duplicates (დუბლიკატების წაშლა)", "Conditional Formatting (პირობითი ფორმატირება) - ვიზუალური გამოკვეთა", "Text to Columns (ტექსტის განაწილება სვეტებად)"]'::jsonb, 'Data Validation (მონაცემთა ვალიდაცია/შემოწმება) - Data ჩანართში Whole Number, Decimal, List, Date კრიტერიუმებით', 'Düzgün cavab: B) Data Validation (მონაცემთა ვალიდაცია/შემოწმება) - Data ჩანართში Whole Number, De', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('eeeb0120-fb7d-4fdf-b5d5-95c9e6d13bd1', '1376be74-0955-43c4-8e90-ec089c9261db', 'Microsoft PowerPoint proqramında bütün slaydların vahid dizayn şablonunu dəyişmək üçün hansı rejimdən istifadə olunur?', 'multiple_choice', '["Reading View", "Notes Master", "Slide Master (Slayd Ustası)", "Slide Sorter", "Outline View"]'::jsonb, 'Slide Master (Slayd Ustası)', 'Düzgün cavab: C) Slide Master (Slayd Ustası)', '', 57, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bc658622-6d56-4600-9316-a6fad8ec7084', 'eeeb0120-fb7d-4fdf-b5d5-95c9e6d13bd1', 'ka', 'PowerPoint-ში რომელი რეჟიმი გამოიყენება ყველა სლაიდის ერთიანი დიზაინის შაბლონის შესაცვლელად?', '["Presenter View (მომხსენებლის ხედი) - პრეზენტატორის ხედი", "Reading View (კითხვის რეჟიმი) - კითხვის რეჟიმი", "Slide Master (სლაიდების მასტერი / Образец слайдов) - View ჩანართში Master Views ჯგუფი", "Custom Animation (მორგებული ანიმაცია) - ანიმაციის რეჟიმი", "Slide Sorter (სლაიდების დამხარისხებელი) - დახარისხების რეჟიმი"]'::jsonb, 'Slide Master (სლაიდების მასტერი / Образец слайдов) - View ჩანართში Master Views ჯგუფი', 'Düzgün cavab: C) Slide Master (სლაიდების მასტერი / Образец слайдов) - View ჩანართში Master Views', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8405a638-1679-4c2e-a3e6-3132d58b1adc', '1376be74-0955-43c4-8e90-ec089c9261db', 'Microsoft PowerPoint-də ''Transition'' ilə ''Animation'' arasındakı əsas fərq nədir?', 'multiple_choice', '["Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir", "Hər ikisi eyni funksiyadır, sadəcə adları fərqlidir", "Transition səs effekti, Animation vizual effektdir", "Transition avtomatik, Animation əl ilə işə düşür", "Transition obyektlərə, Animation slaydlara tətbiq olunur"]'::jsonb, 'Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir', 'Düzgün cavab: A) Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation i', '', 58, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('884be7c0-f8f3-44f1-8d0b-d0fcb531eac6', '8405a638-1679-4c2e-a3e6-3132d58b1adc', 'ka', 'რა არის ძირითადი განსხვავება PowerPoint-ში „Transition“-სა და „Animation“-ს შორის?', '["Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animation არის სლაიდის შიგნით არსებული კონკრეტული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი", "ორივე ცნება ერთსა და იმავე ფუნქციას ასრულებს", "Transition ცვლის სლაიდის ფონის ფერს, ხოლო Animation არეგულირებს სლაიდის დროს", "Transition მუშაობს მხოლოდ კომპიუტერის გამორთვისას, ხოლო Animation აქტიურდება ბეჭდვის დროს", "Transition გამოიყენება მხოლოდ ტექსტებზე, ხოლო Animation აჩვენებს მხოლოდ ვიდეოფაილებს"]'::jsonb, 'Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animation არის სლაიდის შიგნით არსებული კონკრეტული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი', 'Düzgün cavab: A) Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animat', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('642317f4-3241-4356-af8e-be3620330dc0', '1376be74-0955-43c4-8e90-ec089c9261db', 'Bulud saxlama xidmətlərində sənəd üzərində birgə işləyərkən əvvəlki dəyişikliklərə qayıtmaq üçün hansı funksiyadan istifadə olunur?', 'multiple_choice', '["File Recovery", "Backup and Restore", "Track Changes (Dəyişiklikləri izləmə)", "Sync History", "Version History (Versiya tarixçəsi)"]'::jsonb, 'Version History (Versiya tarixçəsi)', 'Düzgün cavab: E) Version History (Versiya tarixçəsi)', '', 59, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8d4aabb6-02ca-417a-aafa-e692c4d7dbe3', '642317f4-3241-4356-af8e-be3620330dc0', 'ka', 'ღრუბლოვან საცავ სერვისებში რომელი ფუნქცია გამოიყენება დოკუმენტის წინა ვერსიებზე დასაბრუნებლად?', '["Defragmentation (დეფრაგმენტაცია) - ოპტიმიზაციას უკეთებს დისკს", "Task Manager (ამოცანათა მენეჯერი) - მართავს პროცესებს", "Version History - დოკუმენტის წინა ვარიანტების დათვალიერება", "Disk Cleanup (დისკის გასუფთავება) - შლის დროებით ფაილებს", "Version History (ვერსიების ისტორია / История версий) - File > Info > Version History ან ისტორია OneDrive/SharePoint-ში"]'::jsonb, 'Version History (ვერსიების ისტორია / История версий) - File > Info > Version History ან ისტორია OneDrive/SharePoint-ში', 'Düzgün cavab: E) Version History (ვერსიების ისტორია / История версий) - File > Info > Version His', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('32c49903-484b-4353-963f-66a3644a32a9', '1376be74-0955-43c4-8e90-ec089c9261db', 'Süni intellekt əsaslı generativ modellərdə ''Hallüsinasiya'' riski nəyi ifadə edir?', 'multiple_choice', '["Modelin yalnız ingilis dilində cavab verib digər dilləri dəstəkləməməsini", "Modelin cavab verməkdən imtina etməsini və xəta qaytarmasını", "Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları və ya mənbələri tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini", "Modelin kompüterin resurslarını həddindən artıq yükləməsini", "Modelin istifadəçi sorğusunu başa düşmədən təsadüfi cavab verməsini"]'::jsonb, 'Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları və ya mənbələri tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini', 'Düzgün cavab: C) Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadl', '', 60, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1febaaf2-5dee-4dfc-a314-03d40b4f6192', '32c49903-484b-4353-963f-66a3644a32a9', 'ka', 'რას გამოხატავს ხელოვნურ ინტელექტში „ჰალუცინაციის“ (Hallucination) რისკი?', '["ხელოვნური ინტელექტის მიერ კომპიუტერის აპარატურული ნაწილების მწყობრიდან გამოყვანას", "მოდელის მუშაობას მხოლოდ უცხო ენებზე და მშობლიური ენის მხარდაჭერის არქონას", "მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და ციტატების/ბმულების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით", "ხელოვნური ინტელექტის მიერ მომხმარებლის ყველა პაროლის ავტომატურ წაშლას", "მოდელის მიერ ინტერნეტქსელის გადატვირთვას და კომპიუტერის გაყინვას"]'::jsonb, 'მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და ციტატების/ბმულების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით', 'Düzgün cavab: C) მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და ციტატე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('96c69af3-3b0a-494f-a184-0331b44234df', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Ümumi təhsil müəssisəsində Təsərrüfat işləri üzrə direktor müavininin əsas vəzifə və səlahiyyətləri hansı sahəni əhatə edir?', 'multiple_choice', '["Pedaqoji Şuranın qərarlarının layihəsini hazırlamaq və dərsdənkənar tədbirlərə rəhbərlik etmək", "Tədris-pedaqoji prosesin akademik planlaşdırılması və fənn müəllimlərinin attestasiyasının təşkili", "Maddi-texniki bazanın, mühəndis sistemlərinin (istilik, su, elektrik, havalandırma) idarəsi, əməyin mühafizəsi, yanğın və buraxılış rejimi təhlükəsizliyi, anbar və xidmətedici heyətə rəhbərlik", "Dərsliklərin məktəbə gətirilməsi və kitabxana fondunun fərdi uçotunun aparılmasına nəzarət", "Fənn kurikulumlarının dövlət standartlarına uyğunluğunun və dərslərin keyfiyyətinin yoxlanılması"]'::jsonb, 'Maddi-texniki bazanın, mühəndis sistemlərinin (istilik, su, elektrik, havalandırma) idarəsi, əməyin mühafizəsi, yanğın və buraxılış rejimi təhlükəsizliyi, anbar və xidmətedici heyətə rəhbərlik', 'Düzgün cavab: C) Maddi-texniki bazanın, mühəndis sistemlərinin (istilik, su, elektrik, havalandır', '', 1, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('06b912c7-b7f9-4ef9-a40c-692e715b250f', '96c69af3-3b0a-494f-a184-0331b44234df', 'ka', 'რომელ სფეროს მოიცავს ზოგადსაგანმანათლებლო დაწესებულებაში სამეურნეო დარგში დირექტორის მოადგილის ძირითადი მოვალეობები და უფლებამოსილებები?', '["სასწავლო-პედაგოგიური პროცესის აკადემიური დაგეგმვა და საგნის მასწავლებელთა ატესტაციის ორგანიზება", "პედაგოგიური საბჭოს გადაწყვეტილებათა პროექტების მომზადება და კლასგარეშე ღონისძიებების ხელმძღვანელობა", "მატერიალურ-ტექნიკური ბაზის, საინჟინრო სისტემების (გათბობა, წყალმომარაგება, ელექტროენერგია, ვენტილაცია) მართვა, შრომის დაცვა, სახანძრო და საშვთა რეჟიმის უსაფრთხოება, საწყობისა და მომსახურე პერსონალის ხელმძღვანელობა", "სახელმძღვანელოების სკოლაში მიტანა და საბიბლიოთეკო ფონდის ინდივიდუალური აღრიცხვის წარმოებაზე კონტროლი", "საგნობრივი კურიკულუმების სახელმწიფო სტანდარტებთან შესაბამისობისა და გაკვეთილების ხარისხის შემოწმება"]'::jsonb, 'მატერიალურ-ტექნიკური ბაზის, საინჟინრო სისტემების (გათბობა, წყალმომარაგება, ელექტროენერგია, ვენტილაცია) მართვა, შრომის დაცვა, სახანძრო და საშვთა რეჟიმის უსაფრთხოება, საწყობისა და მომსახურე პერსონალის ხელმძღვანელობა', 'Düzgün cavab: C) მატერიალურ-ტექნიკური ბაზის, საინჟინრო სისტემების (გათბობა, წყალმომარაგება, ელექტ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('21ebe180-317f-47a9-a0c1-fe1642cf6fac', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəbin illik büdcə xərclərinin planlaşdırılması çərçivəsində təsərrüfat işləri üzrə direktor müavini hansı strateji sənədin hazırlanmasında birbaşa iştirak edir?', 'multiple_choice', '["Müəssisənin Təsərrüfat və İnventar Tələbatı Smetasının, cari və əsaslı təmir ehtiyacları planının, satınalma planının və resurs qənaət proqramının", "Kitabxana fondunun dövri nəşrlər və bədii ədəbiyyat üzrə illik abunə siyahısının tərtibində", "Şagirdlərin buraxılış və monitorinq imtahanlarının keçirilməsi qrafikinin tərtibində", "Fənn metodbirləşmələrinin illik tədris-təqvim planının və açıq dərs qrafiklərinin hazırlanmasında", "Müəllimlərin fərdi elmi-pedaqoji portfoliolarının və ixtisasartırma cədvəlinin hazırlanmasında"]'::jsonb, 'Müəssisənin Təsərrüfat və İnventar Tələbatı Smetasının, cari və əsaslı təmir ehtiyacları planının, satınalma planının və resurs qənaət proqramının', 'Düzgün cavab: A) Müəssisənin Təsərrüfat və İnventar Tələbatı Smetasının, cari və əsaslı təmir eht', '', 2, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('5410dad5-13d1-484e-9e6d-b8fe9cb4b7d1', '21ebe180-317f-47a9-a0c1-fe1642cf6fac', 'ka', 'სკოლის წლიური საბიუჯეტო ხარჯების დაგეგმვის ფარგლებში, რომელი სტრატეგიული დოკუმენტის მომზადებაში იღებს უშუალო მონაწილეობას სამეურნეო დარგში დირექტორის მოადგილე?', '["დაწესებულების სამეურნეო და ინვენტარის მოთხოვნილებათა ხარჯთაღრიცხვის, მიმდინარე და კაპიტალური რემონტის საჭიროებათა გეგმის, შესყიდვების გეგმისა და რესურსების დაზოგვის პროგრამის", "მასწავლებელთა ინდივიდუალური სამეცნიერო-პედაგოგიური პორტფოლიოებისა და კვალიფიკაციის ამაღლების გრაფიკის მომზადებაში", "საბიბლიოთეკო ფონდის პერიოდული გამოცემებისა და მხატვრული ლიტერატურის წლიური გამოწერის სიის შედგენაში", "მოსწავლეთა გამოსაშვები და მონიტორინგის გამოცდების ჩატარების გრაფიკის შედგენაში", "საგნობრივი კათედრების წლიური სასწავლო-კალენდარული გეგმისა და ღია გაკვეთილების გრაფიკის მომზადებაში"]'::jsonb, 'დაწესებულების სამეურნეო და ინვენტარის მოთხოვნილებათა ხარჯთაღრიცხვის, მიმდინარე და კაპიტალური რემონტის საჭიროებათა გეგმის, შესყიდვების გეგმისა და რესურსების დაზოგვის პროგრამის', 'Düzgün cavab: A) დაწესებულების სამეურნეო და ინვენტარის მოთხოვნილებათა ხარჯთაღრიცხვის, მიმდინარე დ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('62a55ccd-0d23-48fd-8549-2154ecc3807f', '0d80fe94-6f97-4552-86f3-825d1ba268e0', '“Dövlət satınalmaları haqqında” AR Qanununa əsasən, məktəb üçün təsərrüfat mallarının alınması hansı prinsiplərlə həyata keçirilməlidir?', 'multiple_choice', '["Malların yalnız xarici bazarlardan xarici valyuta ilə birbaşa sifariş edilməsi", "Ən baha qiymət təklif edən təşkilatla ilkin sənədsiz müqavilə bağlanması", "Şəffaflıq, rəqabətlilik, aşkarlıq, qənaətcillik, səmərəlilik və dövlət elektron satınalma portalı (etender.gov.az) vasitəsilə icrası, hesabatlılıq", "Malların yalnız yerli icra hakimiyyətinin şifahi razılığı ilə nağd hesablaşma yolu ilə alınması", "Satınalma prosesinin qapalı aparılması və yalnız birbaşa sifarişlərlə icrası"]'::jsonb, 'Şəffaflıq, rəqabətlilik, aşkarlıq, qənaətcillik, səmərəlilik və dövlət elektron satınalma portalı (etender.gov.az) vasitəsilə icrası, hesabatlılıq', 'Düzgün cavab: C) Şəffaflıq, rəqabətlilik, aşkarlıq, qənaətcillik, səmərəlilik və dövlət elektron', '', 3, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8849ed7a-321f-4a06-869f-8614fdfd14b9', '62a55ccd-0d23-48fd-8549-2154ecc3807f', 'ka', '„სახელმწიფო შესყიდვების შესახებ“ კანონის თანახმად, რა პრინციპებით უნდა განხორციელდეს სკოლისთვის სამეურნეო საქონლის შესყიდვა?', '["ყველაზე მაღალი ფასის შემთავაზებელ ორგანიზაციასთან ხელშეკრულების დადება წინასწარი დოკუმენტაციის გარეშე", "საქონლის უშუალო შეკვეთა მხოლოდ საგარეო ბაზრებიდან უცხოურ ვალუტაში", "გამჭვირვალობა, კონკურენტულობა, საჯაროობა, ეკონომიურობა, ეფექტიანობა, სახელმწიფო ელექტრონული შესყიდვების პორტალის მეშვეობით განხორციელება და ანგარიშვალდებულება", "შესყიდვების პროცესის დახურულად წარმართვა და მხოლოდ პირდაპირი შეკვეთებით შესრულება", "საქონლის შესყიდვა მხოლოდ ადგილობრივი აღმასრულებელი ხელისუფლების ზეპირი თანხმობით ნაღდი ანგარიშსწორებით"]'::jsonb, 'გამჭვირვალობა, კონკურენტულობა, საჯაროობა, ეკონომიურობა, ეფექტიანობა, სახელმწიფო ელექტრონული შესყიდვების პორტალის მეშვეობით განხორციელება და ანგარიშვალდებულება', 'Düzgün cavab: C) გამჭვირვალობა, კონკურენტულობა, საჯაროობა, ეკონომიურობა, ეფექტიანობა, სახელმწიფო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f4face83-7b3e-4b89-8b03-62ea648b1611', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təhsil müəssisəsində Əməyin Mühafizəsi və Təhlükəsizlik Texnikası sisteminin idarə olunmasında direktor müavininin cavabdehliyi nədir?', 'multiple_choice', '["Əməyin mühafizəsi tələblərini yalnız formal qeydiyyat kimi saxlayaraq icrasına nəzarət etməmək", "Əmək xəsarətləri barədə məlumatı yalnız növbəti təqvim ilində qeyd etmək", "Təhlükəsiz iş şəraitinin yaradılması, vaxtında ilkin və dövri təlimatlandırma, fərdi mühafizə vasitələri ilə təminat və qəza risklərinin qarşısının alınması, jurnalların aparılması", "İşçilərə texniki təhlükəsizlik qaydalarının izah olunmasını məhdudlaşdıraraq sərbəst buraxmaq", "Təhlükəsizlik tədbirlərinin təşkilini yalnız təhsilalanların ictimai təşəbbüslərinə həvalə etmək"]'::jsonb, 'Təhlükəsiz iş şəraitinin yaradılması, vaxtında ilkin və dövri təlimatlandırma, fərdi mühafizə vasitələri ilə təminat və qəza risklərinin qarşısının alınması, jurnalların aparılması', 'Düzgün cavab: C) Təhlükəsiz iş şəraitinin yaradılması, vaxtında ilkin və dövri təlimatlandırma, f', '', 4, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('63dc5f49-864e-42fc-bb21-157797dcc6f2', 'f4face83-7b3e-4b89-8b03-62ea648b1611', 'ka', 'რა პასუხისმგებლობა ეკისრება დირექტორის მოადგილეს საგანმანათლებლო დაწესებულებაში შრომის დაცვისა და უსაფრთხოების ტექნიკის სისტემის მართვაში?', '["უსაფრთხოების ღონისძიებების ორგანიზების დაკისრება მხოლოდ მოსწავლეთა საზოგადოებრივ ინიციატივებზე", "შრომის დაცვის მოთხოვნების მხოლოდ ფორმალურ რეგისტრაციად შენარჩუნება მათი შესრულების კონტროლის გარეშე", "უსაფრთხო სამუშაო პირობების შექმნა, პირველადი და პერიოდული ინსტრუქტაჟის დროული ჩატარება, ინდივიდუალური დაცვის საშუალებებით უზრუნველყოფა, ავარიული რისკების თავიდან აცილება და ჟურნალების წარმოება", "თანამშრომლებისთვის ტექნიკური უსაფრთხოების წესების განმარტების შეზღუდვა და თვითდინებაზე მიშვება", "შრომითი ტრავმების შესახებ ინფორმაციის დაფიქსირება მხოლოდ მომდევნო კალენდარულ წელს"]'::jsonb, 'უსაფრთხო სამუშაო პირობების შექმნა, პირველადი და პერიოდული ინსტრუქტაჟის დროული ჩატარება, ინდივიდუალური დაცვის საშუალებებით უზრუნველყოფა, ავარიული რისკების თავიდან აცილება და ჟურნალების წარმოება', 'Düzgün cavab: C) უსაფრთხო სამუშაო პირობების შექმნა, პირველადი და პერიოდული ინსტრუქტაჟის დროული ჩა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ffad37c6-862d-4cbf-84b5-fc54dec6bee9', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb binasının əsaslı və ya cari təmiri zamanı podratçı təşkilatın gördüyü işlərin qəbulu hansı qaydada aparılır?', 'multiple_choice', '["Layihə-smeta sənədlərinə, tikinti norma və qaydalarına (SNiP) və müqavilə şərtlərinə uyğunluq yoxlanılaraq, qüsurlar aktı tərtib edilərək Rəsmi Təhvil-Təslim Aktı (Forma 2) imzalanmaqla", "Təmirin keyfiyyətini yoxlamadan ayrılmış vəsaitin podratçıya dərhal ödənilməsi ilə", "Təmir işlərinin başa çatması barədə akt tərtib edilmədən birbaşa istismara başlamaqla", "Yalnız təhsilalanların və valideynlərin anonim rəy sorğularının nəticələri əsasında", "Podratçı rəhbərliyinə yalnız şifahi təşəkkür bildirməklə sənədsiz təhvil almaqla"]'::jsonb, 'Layihə-smeta sənədlərinə, tikinti norma və qaydalarına (SNiP) və müqavilə şərtlərinə uyğunluq yoxlanılaraq, qüsurlar aktı tərtib edilərək Rəsmi Təhvil-Təslim Aktı (Forma 2) imzalanmaqla', 'Düzgün cavab: A) Layihə-smeta sənədlərinə, tikinti norma və qaydalarına (SNiP) və müqavilə şərtlə', '', 5, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f1aded22-5e4e-4cd9-818d-36215407d3df', 'ffad37c6-862d-4cbf-84b5-fc54dec6bee9', 'ka', 'სკოლის შენობის კაპიტალური ან მიმდინარე რემონტის დროს რა წესით ხდება კონტრაქტორი (მენარდე) ორგანიზაციის მიერ შესრულებული სამუშაოების მიღება?', '["საპროექტო-სახარჯთაღრიცხვო დოკუმენტაციასთან, სამშენებლო ნორმებსა და წესებთან და ხელშეკრულების პირობებთან შესაბამისობის შემოწმებით, ხარვეზების აქტის შედგენითა და ოფიციალური მიღება-ჩაბარების აქტის ხელმოწერით", "სარემონტო სამუშაოების დასრულების შესახებ აქტის შედგენის გარეშე შენობის პირდაპირი ექსპლუატაციაში გაშვებით", "მხოლოდ მოსწავლეთა და მშობელთა ანონიმური გამოკითხვის შედეგების საფუძველზე", "რემონტის ხარისხის შემოწმების გარეშე გამოყოფილი თანხის კონტრაქტორისთვის დაუყოვნებლივ გადახდით", "კონტრაქტორის ხელმძღვანელობისთვის მხოლოდ ზეპირი მადლობის გამოცხადებით, დოკუმენტაციის გარეშე მიღებით"]'::jsonb, 'საპროექტო-სახარჯთაღრიცხვო დოკუმენტაციასთან, სამშენებლო ნორმებსა და წესებთან და ხელშეკრულების პირობებთან შესაბამისობის შემოწმებით, ხარვეზების აქტის შედგენითა და ოფიციალური მიღება-ჩაბარების აქტის ხელმოწერით', 'Düzgün cavab: A) საპროექტო-სახარჯთაღრიცხვო დოკუმენტაციასთან, სამშენებლო ნორმებსა და წესებთან და ხ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e9e6cdd0-9665-42a0-b5c6-36df6484e831', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb təsərrüfatında olan bütün əsas vəsaitlərin illik dövlət inventarizasiyası üzrə komissiyada direktor müavininin rolu nədir?', 'multiple_choice', '["İnventarizasiya komissiyasının fəaliyyətindən kənarda qalaraq hesabatları imzalamamaq", "Faktiki artıq aşkar olunmuş əmlakı heç bir uçota almadan müəssisədən çıxarmaq", "İnventar uçotunu yalnız şifahi məlumatlar əsasında dövriyyədən çıxarmaqla yekunlaşdırmaq", "İnventarizasiya komissiyasına rəhbərlik etmək və ya üzv kimi faktiki sayımın dəqiqliyinə, uçot sənədləri ilə uyğunluğuna, artıq və əskiklərin aktlaşdırılmasına nəzarət etmək", "İnventarizasiya prosesini ləğv edərək əvvəlki illərin rəqəmlərini təsdiqləmək"]'::jsonb, 'İnventarizasiya komissiyasına rəhbərlik etmək və ya üzv kimi faktiki sayımın dəqiqliyinə, uçot sənədləri ilə uyğunluğuna, artıq və əskiklərin aktlaşdırılmasına nəzarət etmək', 'Düzgün cavab: D) İnventarizasiya komissiyasına rəhbərlik etmək və ya üzv kimi faktiki sayımın dəq', '', 6, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('71e8a018-a8b3-40c2-b734-b3804438b783', 'e9e6cdd0-9665-42a0-b5c6-36df6484e831', 'ka', 'რა როლი ეკისრება დირექტორის მოადგილეს სკოლის მეურნეობაში არსებული ყველა ძირითადი საშუალების წლიური სახელმწიფო ინვენტარიზაციის კომისიაში?', '["ინვენტარიზაციის პროცესის გაუქმება და წინა წლების მონაცემების დამტკიცება", "ინვენტარიზაციის კომისიის საქმიანობისგან თავის არიდება და ანგარიშებზე ხელის არმოწერა", "ფაქტობრივად აღმოჩენილი ზედმეტი ქონების ყოველგვარი აღრიცხვის გარეშე დაწესებულებიდან გატანა", "ინვენტარიზაციის კომისიის ხელმძღვანელობა ან წევრის სახით ფაქტობრივი დათვლის სიზუსტეზე, სააღრიცხვო დოკუმენტებთან შესაბამისობაზე, ზედმეტობისა და დანაკლისის გაფორმებაზე კონტროლი", "ინვენტარის აღრიცხვის დასრულება მხოლოდ ზეპირი მონაცემების საფუძველზე ბრუნვიდან ამოღებით"]'::jsonb, 'ინვენტარიზაციის კომისიის ხელმძღვანელობა ან წევრის სახით ფაქტობრივი დათვლის სიზუსტეზე, სააღრიცხვო დოკუმენტებთან შესაბამისობაზე, ზედმეტობისა და დანაკლისის გაფორმებაზე კონტროლი', 'Düzgün cavab: D) ინვენტარიზაციის კომისიის ხელმძღვანელობა ან წევრის სახით ფაქტობრივი დათვლის სიზუს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b7129392-3f3a-4ff1-91b0-6c1f0d65ac47', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Ümumi təhsil müəssisəsində Fövqəladə Hallar və Mülki Müdafiə planının hazırlanmasında direktor müavininin vəzifəsi hansıdır?', 'multiple_choice', '["Mülki müdafiə avadanlıqlarını və fərdi mühafizə vasitələrini sənədsiz ləğv etmək", "Məktəbin fövqəladə hallar və mülki müdafiə planını hazırlamaq, MM qruplarını və təxliyə dəstələrini formalaşdırmaq, təxliyə məşqlərini, təlimatlandırmanı təşkil etmək və təhlükəsizliyi təmin etmək", "Təxliyə planlarını yalnız arxiv qovluğunda saxlayaraq divarlara vurmamaq", "Şagird və kollektivi fövqəladə hal təhlükələri barədə məlumatsız saxlamaqla panikanın qarşısını almaq", "Fövqəladə hallar zamanı məktəbin bütün çıxış qapılarını bağlayaraq binanı tərk etmək"]'::jsonb, 'Məktəbin fövqəladə hallar və mülki müdafiə planını hazırlamaq, MM qruplarını və təxliyə dəstələrini formalaşdırmaq, təxliyə məşqlərini, təlimatlandırmanı təşkil etmək və təhlükəsizliyi təmin etmək', 'Düzgün cavab: B) Məktəbin fövqəladə hallar və mülki müdafiə planını hazırlamaq, MM qruplarını və', '', 7, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c25f74e7-1c7a-4e18-881d-843873a428b5', 'b7129392-3f3a-4ff1-91b0-6c1f0d65ac47', 'ka', 'რა ევალება დირექტორის მოადგილეს ზოგადსაგანმანათლებლო დაწესებულებაში საგანგებო სიტუაციებისა და სამოქალაქო თავდაცვის გეგმის მომზადებისას?', '["სამოქალაქო თავდაცვის აღჭურვილობისა და ინდივიდუალური დაცვის საშუალებების უდოკუმენტოდ ჩამოწერა/ლიკვიდაცია", "სკოლის საგანგებო სიტუაციებისა და სამოქალაქო თავდაცვის გეგმის შემუშავება, სამოქალაქო თავდაცვის ჯგუფებისა და საევაკუაციო რაზმების ფორმირება, საევაკუაციო წვრთნებისა და ინსტრუქტაჟების ორგანიზება და უსაფრთხოების უზრუნველყოფა", "მოსწავლეებისა და კოლექტივის არაინფორმირებულად დატოვება საგანგებო სიტუაციების საფრთხეების შესახებ პანიკის თავიდან ასაცილებლად", "საგანგებო სიტუაციების დროს სკოლის ყველა გასასვლელი კარის ჩაკეტვა და შენობის დატოვება", "საევაკუაციო გეგმების შენახვა მხოლოდ საარქივო საქაღალდეში და კედლებზე არგანთავსება"]'::jsonb, 'სკოლის საგანგებო სიტუაციებისა და სამოქალაქო თავდაცვის გეგმის შემუშავება, სამოქალაქო თავდაცვის ჯგუფებისა და საევაკუაციო რაზმების ფორმირება, საევაკუაციო წვრთნებისა და ინსტრუქტაჟების ორგანიზება და უსაფრთხოების უზრუნველყოფა', 'Düzgün cavab: B) სკოლის საგანგებო სიტუაციებისა და სამოქალაქო თავდაცვის გეგმის შემუშავება, სამოქალ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('11ba3002-4610-4513-873d-8fe29baa3978', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təhsil müəssisəsinin mühəndis-kommunikasiya şəbəkələrinin texniki təhlükəsizliyinə nəzarət necə qurulmalıdır?', 'multiple_choice', '["Avadanlıqların zavod texniki pasportlarını və istismar təlimatlarını ləğv edərək sərbəst istismar etmək", "Dövlət texniki nəzarət tələblərinə uyğun profilaktik baxışları, hidravlik sınaqları, elektrik izolyasiya ölçmələrini vaxtında keçirmək, təlimatlı heyətlə qəza risklərini minimuma endirmək", "Mühəndis qurğularının idarə olunmasını heç bir ixtisası və sertifikatı olmayan şəxslərə həvalə etmək", "Təzyiq altında işləyən avadanlıqların manometrlərini və qoruyucu klapanlarını çıxararaq birbaşa rejimdə işlətmək", "Texniki sistemləri yalnız qəza baş verdikdən sonra yoxlamaq və profilaktik baxışlardan imtina etmək"]'::jsonb, 'Dövlət texniki nəzarət tələblərinə uyğun profilaktik baxışları, hidravlik sınaqları, elektrik izolyasiya ölçmələrini vaxtında keçirmək, təlimatlı heyətlə qəza risklərini minimuma endirmək', 'Düzgün cavab: B) Dövlət texniki nəzarət tələblərinə uyğun profilaktik baxışları, hidravlik sınaql', '', 8, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d4c7a370-d606-4c51-9063-ca40f7bbe9d3', '11ba3002-4610-4513-873d-8fe29baa3978', 'ka', 'როგორ უნდა იყოს ორგანიზებული საგანმანათლებლო დაწესებულების საინჟინრო-საკომუნიკაციო ქსელების ტექნიკურ უსაფრთხოებაზე კონტროლი?', '["საინჟინრო დანადგარების მართვის დავალება იმ პირებისთვის, რომლებსაც არ გააჩნიათ შესაბამისი კვალიფიკაცია და სერტიფიკატი", "სახელმწიფო ტექნიკური ზედამხედველობის მოთხოვნათა შესაბამისად პროფილაქტიკური დათვალიერების, ჰიდრავლიკური გამოცდების, ელექტროიზოლაციის გაზომვების დროული ჩატარება და ინსტრუქტირებული პერსონალის მეშვეობით ავარიული რისკების მინიმუმამდე დაყვანა", "წნევის ქვეშ მომუშავე მოწყობილობებიდან მანომეტრებისა და დამცავი სარქველების მოხსნა და პირდაპირ რეჟიმში ამუშავება", "ტექნიკური სისტემების შემოწმება მხოლოდ ავარიის მომხდარის შემდეგ და პროფილაქტიკურ დათვალიერებაზე უარის თქმა", "მოწყობილობათა ქარხნული ტექნიკური პასპორტებისა და საექსპლუატაციო ინსტრუქციების გაუქმება და თვითნებური ექსპლუატაცია"]'::jsonb, 'სახელმწიფო ტექნიკური ზედამხედველობის მოთხოვნათა შესაბამისად პროფილაქტიკური დათვალიერების, ჰიდრავლიკური გამოცდების, ელექტროიზოლაციის გაზომვების დროული ჩატარება და ინსტრუქტირებული პერსონალის მეშვეობით ავარიული რისკების მინიმუმამდე დაყვანა', 'Düzgün cavab: B) სახელმწიფო ტექნიკური ზედამხედველობის მოთხოვნათა შესაბამისად პროფილაქტიკური დათვა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('06bf9eb6-8ed6-405a-9281-b424525992d4', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təsərrüfat işləri üzrə direktor müavini xidmətedici heyətin idarə olunmasında hansı funksiyanı icra edir?', 'multiple_choice', '["Ştat vahidləri üzrə vəzifə bölgüsünü aparmaq, iş qrafiklərini və növbətçilik cədvəllərini təsdiq etmək, əmək və icra intizamına, davamiyyət tabelinə gündəlik nəzarət etmək", "Xidmətedici işçilərin fərdi tarif dərəcələrini və aylıq əməkhaqlarını təkbaşına müəyyən etmək", "İşçilərin əmək qanunvericiliyi ilə müəyyən edilmiş istirahət hüquqlarını tamamilə məhdudlaşdırmaq", "İş vaxtının və davamiyyətin uçotu tabelinin aparılmasını lazımsız hesab edərək dayandırmaq", "Xidmətedici texniki heyəti tədris otaqlarında fənn dərslərini əvəz etməyə cəlb etmək"]'::jsonb, 'Ştat vahidləri üzrə vəzifə bölgüsünü aparmaq, iş qrafiklərini və növbətçilik cədvəllərini təsdiq etmək, əmək və icra intizamına, davamiyyət tabelinə gündəlik nəzarət etmək', 'Düzgün cavab: A) Ştat vahidləri üzrə vəzifə bölgüsünü aparmaq, iş qrafiklərini və növbətçilik cəd', '', 9, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d1e0efb2-67db-4185-af16-869e038066e7', '06bf9eb6-8ed6-405a-9281-b424525992d4', 'ka', 'რა ფუნქციას ასრულებს სამეურნეო დარგში დირექტორის მოადგილე მომსახურე პერსონალის მართვაში?', '["საშტატო ერთეულების მიხედვით მოვალეობათა განაწილება, სამუშაო და მორიგეობის გრაფიკების დამტკიცება, შრომისა და საშემსრულებლო დისციპლინაზე, ასევე სამუშაო დროის აღრიცხვის ტაბელზე ყოველდღიური კონტროლი", "მუშაკთა შრომის კანონმდებლობით განსაზღვრული დასვენების უფლების სრული შეზღუდვა", "სამუშაო დროისა და გამოცხადების აღრიცხვის ტაბელის წარმოების უსარგებლოდ მიჩნევა და შეწყვეტა", "მომსახურე პერსონალის ინდივიდუალური სატარიფო თანრიგებისა და ყოველთვიური ხელფასების ერთპიროვნულად განსაზღვრა", "ტექნიკური მომსახურე პერსონალის ჩართვა საკლასო ოთახებში საგნობრივი გაკვეთილების ჩასანაცვლებლად"]'::jsonb, 'საშტატო ერთეულების მიხედვით მოვალეობათა განაწილება, სამუშაო და მორიგეობის გრაფიკების დამტკიცება, შრომისა და საშემსრულებლო დისციპლინაზე, ასევე სამუშაო დროის აღრიცხვის ტაბელზე ყოველდღიური კონტროლი', 'Düzgün cavab: A) საშტატო ერთეულების მიხედვით მოვალეობათა განაწილება, სამუშაო და მორიგეობის გრაფიკ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7528c398-41c8-47b5-a068-d1b83163effa', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təhsil müəssisəsinin sanitar-gigiyenik vəziyyətinin SanPiN normalarına uyğunluğunun təmin edilməsində direktor müavini hansı nəzarət mexanizmini tətbiq edir?', 'multiple_choice', '["Təmizlik işlərinin aparılması məsuliyyətini tam şəkildə fənn müəllimlərinin üzərinə yönəltmək", "Otaqların, dəhlizlərin, sanitar qovşaqların, yeməkxananın gündəlik dezinfeksiya və nəm təmizliyinə, havalandırma, işıqlandırma və temperatur rejiminə daimi nəzarət etmək və jurnallaşdırmaq", "Tədris korpusunun və həyətyanı sahənin sanitar təmizlənməsini yalnız tədris rübündə bir dəfə yoxlamaq", "Müəssisədə dezinfeksiya və təmizlik maddələrinin istifadəsini maliyyə qənaəti məqsədilə tam dayandırmaq", "Sanitar qovşaqların fəaliyyətini tamamilə bağlayaraq şagirdlərin istifadəsini məhdudlaşdırmaq"]'::jsonb, 'Otaqların, dəhlizlərin, sanitar qovşaqların, yeməkxananın gündəlik dezinfeksiya və nəm təmizliyinə, havalandırma, işıqlandırma və temperatur rejiminə daimi nəzarət etmək və jurnallaşdırmaq', 'Düzgün cavab: B) Otaqların, dəhlizlərin, sanitar qovşaqların, yeməkxananın gündəlik dezinfeksiya', '', 10, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('64814fa0-4b09-4e49-a39c-ed6022da6795', '7528c398-41c8-47b5-a068-d1b83163effa', 'ka', 'რა კონტროლის მექანიზმს იყენებს დირექტორის მოადგილე საგანმანათლებლო დაწესებულების სანიტარიულ-ჰიგიენური მდგომარეობის სანიტარიულ ნორმებთან (სანპინ) შესაბამისობის უზრუნველსაყოფად?', '["დასუფთავების სამუშაოების ჩატარების პასუხისმგებლობის სრულად საგნის მასწავლებლებზე დაკისრება", "ოთახების, დერეფნების, სანიტარიული კვანძების, სასადილოს ყოველდღიურ დეზინფექციასა და სველ წმენდაზე, ვენტილაციაზე, განათებასა და ტემპერატურულ რეჟიმზე მუდმივი კონტროლი და ჟურნალში აღრიცხვა", "სასწავლო კორპუსისა და მიმდებარე ტერიტორიის სანიტარიული დასუფთავების შემოწმება მხოლოდ სასწავლო მეოთხედში ერთხელ", "დაწესებულებაში სადეზინფექციო და საწმენდი საშუალებების გამოყენების სრული შეწყვეტა ფინანსების დაზოგვის მიზნით", "სანიტარიული კვანძების მუშაობის სრული ჩაკეტვა და მოსწავლეთა მიერ მათი გამოყენების შეზღუდვა"]'::jsonb, 'ოთახების, დერეფნების, სანიტარიული კვანძების, სასადილოს ყოველდღიურ დეზინფექციასა და სველ წმენდაზე, ვენტილაციაზე, განათებასა და ტემპერატურულ რეჟიმზე მუდმივი კონტროლი და ჟურნალში აღრიცხვა', 'Düzgün cavab: B) ოთახების, დერეფნების, სანიტარიული კვანძების, სასადილოს ყოველდღიურ დეზინფექციასა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7e293849-b066-46dc-bd0d-e758a0099cba', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb binasında enerji effektivliyinin artırılması və resurslara qənaət üçün direktor müavini hansı tədbirləri görür?', 'multiple_choice', '["Resurs sərfiyyatının (qaz, işıq, su) daimi monitorinqini aparmaq, sayğaclara nəzarət, LED işıqlandırma və termostatlı radiatorlar, istilik tənzimləyiciləri, vaxtında təmir və israfçılığın önlənməsi", "Kommunal sayğacların dövlət plomblarını açaraq kənar qeyri-qanuni xətlər quraşdırmaq", "Qış fəslində pəncərələri açıq qoyaraq istilik radiatorlarının fəaliyyətini zəiflətmək", "Müəssisənin bütün istilik və su xətlərini qənaət məqsədilə tədris saatlarında tam kəsmək", "Kommunal sayğacların göstəricilərini saxtalaşdıraraq faktiki hesabatlardan kənarda saxlamaq"]'::jsonb, 'Resurs sərfiyyatının (qaz, işıq, su) daimi monitorinqini aparmaq, sayğaclara nəzarət, LED işıqlandırma və termostatlı radiatorlar, istilik tənzimləyiciləri, vaxtında təmir və israfçılığın önlənməsi', 'Düzgün cavab: A) Resurs sərfiyyatının (qaz, işıq, su) daimi monitorinqini aparmaq, sayğaclara nəz', '', 11, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d6092aa3-08a9-400e-95b4-790bcf2472fa', '7e293849-b066-46dc-bd0d-e758a0099cba', 'ka', 'რა ზომებს იღებს დირექტორის მოადგილე სკოლის შენობაში ენერგოეფექტიანობის გაზრდისა და რესურსების დაზოგვის მიზნით?', '["რესურსების (გაზი, ელექტროენერგია, წყალი) მოხმარების მუდმივი მონიტორინგი, მრიცხველების კონტროლი, LED განათება, თერმოსტატიანი რადიატორები და თბორეგულატორები, დროული შეკეთება და გაფლანგვის აღკვეთა", "კომუნალური მრიცხველების ჩვენებების გაყალბება და მათი ფაქტობრივი ანგარიშგების მიღმა დატოვება", "ზამთრის პერიოდში ფანჯრების ღიად დატოვება და გათბობის რადიატორების მუშაობის შესუსტება", "კომუნალური მრიცხველების სახელმწიფო ლუქების მოხსნა და უკანონო გარე ხაზების დამონტაჟება", "დაწესებულების გათბობისა და წყლის ყველა ხაზის სრული გათიშვა სასწავლო საათებში ეკონომიის მიზნით"]'::jsonb, 'რესურსების (გაზი, ელექტროენერგია, წყალი) მოხმარების მუდმივი მონიტორინგი, მრიცხველების კონტროლი, LED განათება, თერმოსტატიანი რადიატორები და თბორეგულატორები, დროული შეკეთება და გაფლანგვის აღკვეთა', 'Düzgün cavab: A) რესურსების (გაზი, ელექტროენერგია, წყალი) მოხმარების მუდმივი მონიტორინგი, მრიცხვე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('56e4577c-46d5-4bd8-bdff-9c7905a7c309', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb anbar təsərrüfatının fəaliyyətinin yoxlanılması zamanı direktor müavini hansı qaydalara riayət olunmasını tələb edir?', 'multiple_choice', '["Malların anbara sənədsiz qəbul edilməsinə və tələbat olmadan sərbəst paylanmasına", "Malların xarab olmasına, fiziki aşınmasına və qeyri-qanuni istifadəsinə nəzarət edilməməsinə", "Anbarda saxlanılan mebel və texniki avadanlıqların müəssisədən kənarda icarəyə verilməsinə", "Anbar otaqlarının qapılarının və pəncərələrinin gün boyu açıq və nəzarətsiz saxlanılmasına", "Bütün daxilolma və xaricetmələrin ciddi ilkin uçot sənədləri (qaimə, akt, elektron faktura) ilə aparılmasına, saxlanma şəraitinə, səliqə-sahmana və yanğın təhlükəsizliyinə riayət olunmasına"]'::jsonb, 'Bütün daxilolma və xaricetmələrin ciddi ilkin uçot sənədləri (qaimə, akt, elektron faktura) ilə aparılmasına, saxlanma şəraitinə, səliqə-sahmana və yanğın təhlükəsizliyinə riayət olunmasına', 'Düzgün cavab: E) Bütün daxilolma və xaricetmələrin ciddi ilkin uçot sənədləri (qaimə, akt, elektr', '', 12, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8978d4ee-1a8f-4ce7-b67d-befb5e682442', '56e4577c-46d5-4bd8-bdff-9c7905a7c309', 'ka', 'სკოლის სასაწყობო მეურნეობის შემოწმებისას, რომელი წესების დაცვას მოითხოვს დირექტორის მოადგილე?', '["საწყობის ოთახების კარ-ფანჯრების მთელი დღის განმავლობაში ღიად და უმეთვალყურეოდ დატოვებას", "საქონლის გაფუჭებაზე, ფიზიკურ ცვეთასა და უკანონო გამოყენებაზე კონტროლის არარსებობას", "საწყობში შენახული ავეჯისა და ტექნიკური აღჭურვილობის დაწესებულების გარეთ იჯარით გაცემას", "საქონლის საწყობში უდოკუმენტოდ მიღებასა და მოთხოვნის გარეშე თავისუფალ დარიგებას", "ყველა შემოსავლისა და გასავლის მკაცრი პირველადი სააღრიცხვო დოკუმენტაციით (სასაქონლო ზედნადები, აქტი) წარმოებას, შენახვის პირობების, სისუფთავე-წესრიგისა და სახანძრო უსაფრთხოების წესების დაცვას"]'::jsonb, 'ყველა შემოსავლისა და გასავლის მკაცრი პირველადი სააღრიცხვო დოკუმენტაციით (სასაქონლო ზედნადები, აქტი) წარმოებას, შენახვის პირობების, სისუფთავე-წესრიგისა და სახანძრო უსაფრთხოების წესების დაცვას', 'Düzgün cavab: E) ყველა შემოსავლისა და გასავლის მკაცრი პირველადი სააღრიცხვო დოკუმენტაციით (სასაქონ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6605e6f4-4947-45ac-b718-8085ef275101', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təhsil müəssisəsində baş vermiş bədbəxt hadisələrin araşdırılması və aktlaşdırılması qaydası necədir?', 'multiple_choice', '["Araşdırma işlərinə yalnız hadisə baş verdikdən bir il sonra məhkəmə qərarı ilə başlamaq", "Baş vermiş hadisəyə görə bütün hüquqi məsuliyyəti zərərçəkən işçinin üzərinə yönəltmək", "Hadisə faktını gizlədərək rəsmi orqanlara və rəhbərliyə heç bir məlumat təqdim etməmək", "Hadisə baş verən ərazini dərhal təmizləyərək sübutları və texniki izləri kənarlaşdırmaq", "Xüsusi komissiya yaratmaq, hadisə yerini qorumaq, şahidləri dindirmək, hadisəni araşdıraraq ''İstehsalatda bədbəxt hadisə haqqında Akt (İz-1 forması)'' tərtib etmək və profilaktik tədbirlər görmək"]'::jsonb, 'Xüsusi komissiya yaratmaq, hadisə yerini qorumaq, şahidləri dindirmək, hadisəni araşdıraraq ''İstehsalatda bədbəxt hadisə haqqında Akt (İz-1 forması)'' tərtib etmək və profilaktik tədbirlər görmək', 'Düzgün cavab: E) Xüsusi komissiya yaratmaq, hadisə yerini qorumaq, şahidləri dindirmək, hadisəni', '', 13, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('00ceba3a-bd38-4c9c-bb95-e884440217e8', '6605e6f4-4947-45ac-b718-8085ef275101', 'ka', 'როგორია საგანმანათლებლო დაწესებულებაში მომხდარი უბედური შემთხვევების მოკვლევისა და აქტით გაფორმების წესი?', '["მოკვლევის დაწყება მხოლოდ შემთხვევის მომხდარიდან ერთი წლის შემდეგ სასამართლოს გადაწყვეტილებით", "შემთხვევის ფაქტის დამალვა და ოფიციალური ორგანოებისა და ხელმძღვანელობისთვის ინფორმაციის მიუწოდებლობა", "შემთხვევის ადგილის დაუყოვნებლივ დასუფთავება და მტკიცებულებებისა და ტექნიკური კვალის წაშლა", "მომხდარ შემთხვევაზე მთელი სამართლებრივი პასუხისმგებლობის დაზარალებულ თანამშრომელზე დაკისრება", "სპეციალური კომისიის შექმნა, შემთხვევის ადგილის დაცვა, მოწმეების გამოკითხვა, შემთხვევის გამოკვლევა, ''საწარმოო უბედური შემთხვევის შესახებ აქტის'' შედგენა და პროფილაქტიკური ზომების მიღება"]'::jsonb, 'სპეციალური კომისიის შექმნა, შემთხვევის ადგილის დაცვა, მოწმეების გამოკითხვა, შემთხვევის გამოკვლევა, ''საწარმოო უბედური შემთხვევის შესახებ აქტის'' შედგენა და პროფილაქტიკური ზომების მიღება', 'Düzgün cavab: E) სპეციალური კომისიის შექმნა, შემთხვევის ადგილის დაცვა, მოწმეების გამოკითხვა, შემთ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c8152d43-055d-408d-9fc9-542981ce1b8c', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəbin maddi-texniki təminatına dair hesabatların Regional Təhsil İdarəsinə təqdim edilməsi prosesində direktor müavininin vəzifəsi nədir?', 'multiple_choice', '["Hesabat sənədlərini heç bir rəsmi imza və möhür olmadan elektron poçtla adsız göndərmək", "Hesabatlara bilərəkdən reallığı əks etdirməyən yalan və şişirdilmiş göstəricilər daxil etmək", "Təsərrüfat fəaliyyətinə dair statistik və maliyyə hesabatlarını tərtib etməkdən imtina etmək", "Real təsərrüfat vəziyyətini, xərclənmiş və tələb olunan vəsaitləri, inventar hərəkətini, təmir işlərini əks etdirən dəqiq, sənədləşdirilmiş hesabatları vaxtında təqdim etmək", "Maddi-texniki vəziyyət haqqında məlumatları yalnız şifahi telefon danışığı ilə çatdırmaq"]'::jsonb, 'Real təsərrüfat vəziyyətini, xərclənmiş və tələb olunan vəsaitləri, inventar hərəkətini, təmir işlərini əks etdirən dəqiq, sənədləşdirilmiş hesabatları vaxtında təqdim etmək', 'Düzgün cavab: D) Real təsərrüfat vəziyyətini, xərclənmiş və tələb olunan vəsaitləri, inventar hər', '', 14, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('24e5349a-3c58-4f3e-a243-dae1ff1fc208', 'c8152d43-055d-408d-9fc9-542981ce1b8c', 'ka', 'რა ევალება დირექტორის მოადგილეს რეგიონული განათლების სამმართველოსთვის სკოლის მატერიალურ-ტექნიკური უზრუნველყოფის შესახებ ანგარიშების წარდგენის პროცესში?', '["მატერიალურ-ტექნიკური მდგომარეობის შესახებ ინფორმაციის გადაცემა მხოლოდ ზეპირი სატელეფონო საუბრით", "ანგარიშებში შეგნებულად ისეთი ცრუ და გაზვიადებული მონაცემების შეტანა, რომლებიც არ ასახავს რეალობას", "საანგარიშგებო დოკუმენტების ოფიციალური ხელმოწერისა და ბეჭდის გარეშე ელექტრონული ფოსტით ანონიმურად გაგზავნა", "ზუსტი, დოკუმენტირებული ანგარიშების დროული წარდგენა, რომლებიც ასახავს რეალურ სამეურნეო მდგომარეობას, დახარჯულ და საჭირო სახსრებს, ინვენტარის მოძრაობასა და სარემონტო სამუშაოებს", "სამეურნეო საქმიანობის შესახებ სტატისტიკური და ფინანსური ანგარიშების შედგენაზე უარის თქმა"]'::jsonb, 'ზუსტი, დოკუმენტირებული ანგარიშების დროული წარდგენა, რომლებიც ასახავს რეალურ სამეურნეო მდგომარეობას, დახარჯულ და საჭირო სახსრებს, ინვენტარის მოძრაობასა და სარემონტო სამუშაოებს', 'Düzgün cavab: D) ზუსტი, დოკუმენტირებული ანგარიშების დროული წარდგენა, რომლებიც ასახავს რეალურ სამე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5fed78e6-ab7b-4be4-a0bc-82ffe160a584', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təhsil müəssisəsində yanğın təhlükəsizliyi qaydalarının icrasına baxış keçirilərkən direktor müavini hansı sənədləri təqdim etməlidir?', 'multiple_choice', '["Məktəb yeməkxanasının həftəlik ərzaq tədarükü menyusunu", "Yanğın təhlükəsizliyi təlimatlarını, təxliyə planlarını və sxemlərini, odsöndürənlərin texniki pasportlarını, elektrik izolyasiya müqaviməti sınaq protokollarını, təlimatlandırma jurnallarını", "Təhsilalanların şəxsi işlərini və valideyn iclası protokollarını", "Kitabxana fondunun illik dövriyyə və fərdi oxucu formulyarlarını", "Müəllimlərin fənn proqramlarını və yarımillik qiymətləndirmə jurnallarını"]'::jsonb, 'Yanğın təhlükəsizliyi təlimatlarını, təxliyə planlarını və sxemlərini, odsöndürənlərin texniki pasportlarını, elektrik izolyasiya müqaviməti sınaq protokollarını, təlimatlandırma jurnallarını', 'Düzgün cavab: B) Yanğın təhlükəsizliyi təlimatlarını, təxliyə planlarını və sxemlərini, odsöndürə', '', 15, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8cfff6ab-5e03-41a3-b9c4-f7dc40435f6c', '5fed78e6-ab7b-4be4-a0bc-82ffe160a584', 'ka', 'რა დოკუმენტები უნდა წარადგინოს დირექტორის მოადგილემ საგანმანათლებლო დაწესებულებაში სახანძრო უსაფრთხოების წესების შესრულების შემოწმებისას?', '["მოსწავლეთა პირადი საქმეები და მშობელთა კრების ოქმები", "სახანძრო უსაფრთხოების ინსტრუქციები, საევაკუაციო გეგმები და სქემები, ცეცხლსაქრობების ტექნიკური პასპორტები, ელექტროიზოლაციის წინაღობის გამოცდის ოქმები, ინსტრუქტაჟის ჟურნალები", "სკოლის სასადილოს საკვები პროდუქტების მომარაგების ყოველკვირეული მენიუ", "საბიბლიოთეკო ფონდის წლიური ბრუნვისა და ინდივიდუალური მკითხველის ბარათები", "მასწავლებელთა საგნობრივი პროგრამები და ნახევარწლიური შეფასების ჟურნალები"]'::jsonb, 'სახანძრო უსაფრთხოების ინსტრუქციები, საევაკუაციო გეგმები და სქემები, ცეცხლსაქრობების ტექნიკური პასპორტები, ელექტროიზოლაციის წინაღობის გამოცდის ოქმები, ინსტრუქტაჟის ჟურნალები', 'Düzgün cavab: B) სახანძრო უსაფრთხოების ინსტრუქციები, საევაკუაციო გეგმები და სქემები, ცეცხლსაქრობე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9708086f-db1c-4a92-8c97-8a1eff72db62', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb binasının ərazisində yaşıllaşdırma işlərinin təşkilində direktor müavini hansı fəaliyyəti icra edir?', 'multiple_choice', '["Mövcud ağac və yaşıllıqlara aqrotexniki qulluq göstərilməsini, suvarılmasını, mövsümi budama, gübrələmə və abadlaşdırma işlərini, təhlükəsiz ərazini təşkil etmək", "Məktəb həyətini kommersiya məqsədli pullu avtomobil dayanacağına çevirmək", "Məktəb həyətindəki çoxillik ağacların qanunsuz kəsilməsinə şərait yaratmaq", "Məktəb bağbanının fəaliyyətini ləğv edərək ərazini baxımsız saxlamaq", "Yaşıllıq sahələrini tikinti tullantılarının saxlanması poliqonu kimi istifadə etmək"]'::jsonb, 'Mövcud ağac və yaşıllıqlara aqrotexniki qulluq göstərilməsini, suvarılmasını, mövsümi budama, gübrələmə və abadlaşdırma işlərini, təhlükəsiz ərazini təşkil etmək', 'Düzgün cavab: A) Mövcud ağac və yaşıllıqlara aqrotexniki qulluq göstərilməsini, suvarılmasını, mö', '', 16, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('35caf594-85d1-43e4-a9f3-ed0fa3902754', '9708086f-db1c-4a92-8c97-8a1eff72db62', 'ka', 'რა საქმიანობას ახორციელებს დირექტორის მოადგილე სკოლის ტერიტორიაზე გამწვანების სამუშაოების ორგანიზებისას?', '["არსებულ ხეებსა და ნარგავებზე აგროტექნიკური მოვლის, მორწყვის, სეზონური გასხვლის, განაყოფიერებისა და კეთილმოწყობის სამუშაოების, ასევე უსაფრთხო გარემოს ორგანიზება", "მწვანე ნარგავების ტერიტორიის გამოყენება სამშენებლო ნარჩენების შესანახ პოლიგონად", "სკოლის ეზოში არსებული მრავალწლიანი ხეების უკანონო ჭრისთვის ხელის შეწყობა", "სკოლის ეზოს გადაქცევა კომერციული მიზნით ფასიან ავტოსადგომად", "სკოლის მებაღის საქმიანობის გაუქმება და ტერიტორიის მიტოვებულ მდგომარეობაში დატოვება"]'::jsonb, 'არსებულ ხეებსა და ნარგავებზე აგროტექნიკური მოვლის, მორწყვის, სეზონური გასხვლის, განაყოფიერებისა და კეთილმოწყობის სამუშაოების, ასევე უსაფრთხო გარემოს ორგანიზება', 'Düzgün cavab: A) არსებულ ხეებსა და ნარგავებზე აგროტექნიკური მოვლის, მორწყვის, სეზონური გასხვლის,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0b5ac765-b8bd-4791-918b-8737cf5574f8', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb təsərrüfatı işçilərinin peşəkar inkişafı üçün direktor müavini hansı işləri görməlidir?', 'multiple_choice', '["İşçilərin peşəkar sertifikatlaşdırma kurslarına qatılmasına mane olmaq", "Dövri təhlükəsizlik və əməyin mühafizəsi üzrə təlimatlandırma, texniki istismar qaydaları, ixtisasartırma və maarifləndirmə seminarları, təlimləri təşkil etmək", "Əməyin mühafizəsi təlimatlarını işçilərdən gizli saxlayaraq xidməti istifadəyə verməmək", "Texniki heyət üçün təhlükəsizlik təlimlərinin keçirilməsini tamamilə ləğv etmək", "İşçilərin idarə olunmasını yalnız intizam cəzaları və əməkhaqqı kəsintiləri ilə aparmaq"]'::jsonb, 'Dövri təhlükəsizlik və əməyin mühafizəsi üzrə təlimatlandırma, texniki istismar qaydaları, ixtisasartırma və maarifləndirmə seminarları, təlimləri təşkil etmək', 'Düzgün cavab: B) Dövri təhlükəsizlik və əməyin mühafizəsi üzrə təlimatlandırma, texniki istismar', '', 17, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2e8d73fc-4c79-40c6-872f-8fe42671611a', '0b5ac765-b8bd-4791-918b-8737cf5574f8', 'ka', 'რა სამუშაოები უნდა განახორციელოს დირექტორის მოადგილემ სკოლის სამეურნეო პერსონალის პროფესიული განვითარებისთვის?', '["თანამშრომლებისთვის პროფესიული სერტიფიცირების კურსებზე მონაწილეობაში ხელის შეშლა", "უსაფრთხოებასა და შრომის დაცვაში პერიოდული ინსტრუქტაჟის, ტექნიკური ექსპლუატაციის წესების, კვალიფიკაციის ამაღლებისა და საგანმანათლებლო სემინარების, ტრენინგების ორგანიზება", "შრომის დაცვის ინსტრუქციების თანამშრომლებისგან საიდუმლოდ შენახვა და სამსახურებრივი გამოყენებისთვის არმიცემა", "ტექნიკური პერსონალისთვის უსაფრთხოების ტრენინგების ჩატარების სრული გაუქმება", "თანამშრომელთა მართვა მხოლოდ დისციპლინური სახდელებითა და ხელფასის დაკავებით"]'::jsonb, 'უსაფრთხოებასა და შრომის დაცვაში პერიოდული ინსტრუქტაჟის, ტექნიკური ექსპლუატაციის წესების, კვალიფიკაციის ამაღლებისა და საგანმანათლებლო სემინარების, ტრენინგების ორგანიზება', 'Düzgün cavab: B) უსაფრთხოებასა და შრომის დაცვაში პერიოდული ინსტრუქტაჟის, ტექნიკური ექსპლუატაციის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d3b14ec5-8523-48a6-9d1c-f7b528639f0f', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb binasının fiziki mühafizəsinin və buraxılış rejiminin təmin olunmasında direktor müavininin nəzarət funksiyası nədir?', 'multiple_choice', '["Kənar şəxslərin məktəb binasına sərbəst və qeydiyyatsız daxil olmasına şərait yaratmaq", "Təhlükəsizlik kameralarını elektrik şəbəkəsindən ayıraraq arxiv çəkilişlərini dayandırmaq", "Dərs saatlarında şagirdlərin nəzarətsiz şəkildə məktəb ərazisini tərk etməsinə göz yummaq", "Məktəbin bütün giriş qapılarını və pəncərə konstruksiyalarını gün boyu açıq qoymaq", "Mühafizəçilərin və gözətçilərin işinə, növbətçilik qrafikinə nəzarət etmək, turniket, domofon və videomüşahidə kameralarının işləkliyini təmin etmək, kənar şəxslərin girişini qeydiyyatla əngəlləmək"]'::jsonb, 'Mühafizəçilərin və gözətçilərin işinə, növbətçilik qrafikinə nəzarət etmək, turniket, domofon və videomüşahidə kameralarının işləkliyini təmin etmək, kənar şəxslərin girişini qeydiyyatla əngəlləmək', 'Düzgün cavab: E) Mühafizəçilərin və gözətçilərin işinə, növbətçilik qrafikinə nəzarət etmək, turn', '', 18, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b8733ca4-e73b-4bbd-801a-c5c90826c32b', 'd3b14ec5-8523-48a6-9d1c-f7b528639f0f', 'ka', 'რა საკონტროლო ფუნქცია ეკისრება დირექტორის მოადგილეს სკოლის შენობის ფიზიკური დაცვისა და გამშვები (საშვთა) რეჟიმის უზრუნველყოფაში?', '["გაკვეთილების დროს მოსწავლეთა მიერ სკოლის ტერიტორიის უმეთვალყურეოდ დატოვებაზე თვალის დახუჭვა", "უსაფრთხოების კამერების ელექტროქსელიდან გათიშვა და არქივის ჩაწერის შეწყვეტა", "გარეშე პირთათვის სკოლის შენობაში თავისუფლად და რეგისტრაციის გარეშე შესვლის ხელშეწყობა", "სკოლის ყველა შემოსასვლელი კარისა და ფანჯრის კონსტრუქციის მთელი დღის განმავლობაში ღიად დატოვება", "დაცვის თანამშრომლებისა და დარაჯების მუშაობაზე, მორიგეობის გრაფიკზე კონტროლი, ტურნიკეტების, დომოფონისა და ვიდეომეთვალყურეობის კამერების გამართულობის უზრუნველყოფა, უცხო პირთა შესვლის რეგისტრაციით აღკვეთა"]'::jsonb, 'დაცვის თანამშრომლებისა და დარაჯების მუშაობაზე, მორიგეობის გრაფიკზე კონტროლი, ტურნიკეტების, დომოფონისა და ვიდეომეთვალყურეობის კამერების გამართულობის უზრუნველყოფა, უცხო პირთა შესვლის რეგისტრაციით აღკვეთა', 'Düzgün cavab: E) დაცვის თანამშრომლებისა და დარაჯების მუშაობაზე, მორიგეობის გრაფიკზე კონტროლი, ტურ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c3e792ea-607a-429c-a8b1-ceee5279c2e4', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təsərrüfat işləri üzrə direktor müavininin tabeliyində olan işçilərlə münasibətdə etik idarəetmə prinsipi hansıdır?', 'multiple_choice', '["Kollektiv daxilində işçiləri qanunvericiliyin tələblərini pozmağa məcbur etmək", "İşçiləri kollektiv qarşısında təhqir edərək kobud inzibati təzyiq metodlarından istifadə etmək", "Şəxsi maraqları naminə tabelikdə olan heyətə qanunsuz təsərrüfat tapşırıqları vermək", "İşçilərdən vəzifə öhdəliklərinin icrası müqabilində qeyri-qanuni maddi tələblər irəli sürmək", "Ədalətli, obyektiv, tələbkar və qayğıkeş olmaq, əmək hüquqlarına hörmət etmək, şəffaflıq və sağlam mənəvi-psixoloji mühit yaratmaq, ayrı-seçkiliyə yol verməmək"]'::jsonb, 'Ədalətli, obyektiv, tələbkar və qayğıkeş olmaq, əmək hüquqlarına hörmət etmək, şəffaflıq və sağlam mənəvi-psixoloji mühit yaratmaq, ayrı-seçkiliyə yol verməmək', 'Düzgün cavab: E) Ədalətli, obyektiv, tələbkar və qayğıkeş olmaq, əmək hüquqlarına hörmət etmək, ş', '', 19, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4fdf6e07-e62c-444e-8e6d-e639d181e02d', 'c3e792ea-607a-429c-a8b1-ceee5279c2e4', 'ka', 'როგორია ეთიკური მართვის პრინციპი სამეურნეო დარგში დირექტორის მოადგილის დაქვემდებარებაში მყოფ თანამშრომლებთან ურთიერთობაში?', '["თანამშრომელთა შეურაცხყოფა კოლექტივის წინაშე და უხეში ადმინისტრაციული ზეწოლის მეთოდების გამოყენება", "კოლექტივის შიგნით თანამშრომელთა იძულება კანონმდებლობის მოთხოვნების დასარღვევად", "თანამშრომლებისთვის სამსახურებრივი მოვალეობების შესრულების სანაცვლოდ უკანონო მატერიალური მოთხოვნების წაყენება", "პირადი ინტერესების სასარგებლოდ დაქვემდებარებული პერსონალისთვის უკანონო სამეურნეო დავალებების მიცემა", "სამართლიანობა, ობიექტურობა, მომთხოვნელობა და მზრუნველობა, შრომითი უფლებების პატივისცემა, გამჭვირვალობა და ჯანსაღი მორალურ-ფსიქოლოგიური გარემოს შექმნა, დისკრიმინაციის დაუშვებლობა"]'::jsonb, 'სამართლიანობა, ობიექტურობა, მომთხოვნელობა და მზრუნველობა, შრომითი უფლებების პატივისცემა, გამჭვირვალობა და ჯანსაღი მორალურ-ფსიქოლოგიური გარემოს შექმნა, დისკრიმინაციის დაუშვებლობა', 'Düzgün cavab: E) სამართლიანობა, ობიექტურობა, მომთხოვნელობა და მზრუნველობა, შრომითი უფლებების პატი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1ba12cc9-d51a-4bd2-9bd6-3145c7d8a1f6', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb qazanxanasında istilik mövsümündə qəfil qəza baş verdikdə direktor müavininin təcili fəaliyyət planı necə olmalıdır?', 'multiple_choice', '["Qazanxananın qapılarını bağlayaraq heç bir tədbir görmədən ərazini tərk etmək", "Hadisə barədə heç kimə məlumat vermədən tədris gününün başa çatmasını gözləmək", "Təhsilalanları və fənn müəllimlərini qəzanı aradan qaldırmaq üçün qazanxanaya göndərmək", "Dərhal qəza-xilasetmə və qaz xidməti briqadasını cəlb etmək, rəhbərliyi və aidiyyəti xidmətləri məlumatlandırmaq, şagirdlərin təhlükəsizliyini təmin edərək donmanın, partlayışın qarşısını almaq üçün tədbirlər görmək", "Qaz təchizatı xəttini daha da açaraq təzyiqi normadan artıq qaldırmağa çalışmaq"]'::jsonb, 'Dərhal qəza-xilasetmə və qaz xidməti briqadasını cəlb etmək, rəhbərliyi və aidiyyəti xidmətləri məlumatlandırmaq, şagirdlərin təhlükəsizliyini təmin edərək donmanın, partlayışın qarşısını almaq üçün tədbirlər görmək', 'Düzgün cavab: D) Dərhal qəza-xilasetmə və qaz xidməti briqadasını cəlb etmək, rəhbərliyi və aidiy', '', 20, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('093d643a-63ea-4fa4-afa0-2534f4c131dc', '1ba12cc9-d51a-4bd2-9bd6-3145c7d8a1f6', 'ka', 'როგორი უნდა იყოს დირექტორის მოადგილის გადაუდებელი სამოქმედო გეგმა სკოლის საქვაბეში გათბობის სეზონზე მოულოდნელი ავარიის დროს?', '["შემთხვევის შესახებ არავისთვის შეტყობინება და სასწავლო დღის დასრულებამდე ლოდინი", "საქვაბის კარების ჩაკეტვა და ყოველგვარი ზომების მიღების გარეშე ტერიტორიის დატოვება", "მოსწავლეებისა და საგნის მასწავლებლების გაგზავნა საქვაბეში ავარიის აღმოსაფხვრელად", "დაუყოვნებლივ ავარიულ-სამაშველო და გაზის სამსახურის ბრიგადის გამოძახება, ხელმძღვანელობისა და შესაბამისი სამსახურების ინფორმირება, მოსწავლეთა უსაფრთხოების უზრუნველყოფა და გაყინვისა თუ აფეთქების თავიდან ასაცილებლად ზომების მიღება", "გაზმომარაგების ხაზის კიდევ უფრო მეტად გახსნა და წნევის ნორმაზე მეტად გაზრდის მცდელობა"]'::jsonb, 'დაუყოვნებლივ ავარიულ-სამაშველო და გაზის სამსახურის ბრიგადის გამოძახება, ხელმძღვანელობისა და შესაბამისი სამსახურების ინფორმირება, მოსწავლეთა უსაფრთხოების უზრუნველყოფა და გაყინვისა თუ აფეთქების თავიდან ასაცილებლად ზომების მიღება', 'Düzgün cavab: D) დაუყოვნებლივ ავარიულ-სამაშველო და გაზის სამსახურის ბრიგადის გამოძახება, ხელმძღვა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8a293cbf-69ac-489a-81a2-0f74b8f9afc8', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəbin fasadının, hasarlarının və daxili divarlarının estetik görünüşünün qorunmasında direktor müavini nəyə nəzarət edir?', 'multiple_choice', '["Məktəb binasının fasadına qanunsuz kommersiya reklamlarının və afişaların vurulmasına", "Hasarların və divarların uçması təhlükəsi yarandıqda heç bir təmir tədbiri görməməyə", "Binanın rənginin hər tədris rübündə fərqli çalarlarla yenidən boyanmasının tələb edilməsinə", "Tədris korpusunun daxili arakəsmələrinin razılaşdırılmadan sökülməsinə", "Divarlarda təhlükəli çatlar, rütubət və qopmalar yarandıqda vaxtında cari təmir tədbirlərinin görülməsinə, fasadın, hasarların möhkəmliyinə və ərazinin təmizliyinə"]'::jsonb, 'Divarlarda təhlükəli çatlar, rütubət və qopmalar yarandıqda vaxtında cari təmir tədbirlərinin görülməsinə, fasadın, hasarların möhkəmliyinə və ərazinin təmizliyinə', 'Düzgün cavab: E) Divarlarda təhlükəli çatlar, rütubət və qopmalar yarandıqda vaxtında cari təmir', '', 21, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6655f97e-3181-4729-92ea-309eba677f59', '8a293cbf-69ac-489a-81a2-0f74b8f9afc8', 'ka', 'რას აკონტროლებს დირექტორის მოადგილე სკოლის ფასადის, ღობეებისა და შიდა კედლების ესთეტიკური იერსახის შენარჩუნებისას?', '["სკოლის შენობის ფასადზე უკანონო კომერციული რეკლამებისა და აფიშების განთავსებას", "სასწავლო კორპუსის შიდა ტიხრების შეუთანხმებლად დემონტაჟს", "ღობეებისა და კედლების ჩამოქცევის საფრთხის შექმნისას არავითარი სარემონტო ზომების არმიღებას", "შენობის ფერის ყოველ სასწავლო მეოთხედში სხვადასხვა ტონალობით ხელახლა შეღებვის მოთხოვნას", "კედლებზე საშიში ბზარების, ნესტისა და ბათქაშის ჩამოცვენის გაჩენისას დროული მიმდინარე რემონტის ჩატარებას, ფასადისა და ღობეების სიმტკიცესა და ტერიტორიის სისუფთავეს"]'::jsonb, 'კედლებზე საშიში ბზარების, ნესტისა და ბათქაშის ჩამოცვენის გაჩენისას დროული მიმდინარე რემონტის ჩატარებას, ფასადისა და ღობეების სიმტკიცესა და ტერიტორიის სისუფთავეს', 'Düzgün cavab: E) კედლებზე საშიში ბზარების, ნესტისა და ბათქაშის ჩამოცვენის გაჩენისას დროული მიმდინ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0b1aa186-faf3-4757-b3f8-f15079a35fca', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təhsil müəssisəsində xidməti avtomobil olduqda onların istismarına nəzarət necə aparılır?', 'multiple_choice', '["Texnikanın təmirsiz, əyləc sistemi nasaz və qəzalı vəziyyətdə xəttə buraxılması ilə", "Yanacaq-sürtkü materiallarının qanunsuz xərclənməsinə və silinməsinə şərait yaradılması ilə", "Sürücünün dövri tibbi müayinəsinin ləğv edilməsi və sənədsiz istismara buraxılması ilə", "Texnikanın heç bir texniki pasport və yol sənədi olmadan sərbəst istifadə edilməsi ilə", "Yol vərəqələrinin düzgün tərtibatı, gündəlik yürüşün qeydiyyatı, yanacaq-sürtkü materiallarının normativlər üzrə sərfiyyatı, texniki baxışın və sığortanın vaxtında keçirilməsi ilə"]'::jsonb, 'Yol vərəqələrinin düzgün tərtibatı, gündəlik yürüşün qeydiyyatı, yanacaq-sürtkü materiallarının normativlər üzrə sərfiyyatı, texniki baxışın və sığortanın vaxtında keçirilməsi ilə', 'Düzgün cavab: E) Yol vərəqələrinin düzgün tərtibatı, gündəlik yürüşün qeydiyyatı, yanacaq-sürtkü', '', 22, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7fbdfc4d-fc2e-4c04-90ef-1fb20098db05', '0b1aa186-faf3-4757-b3f8-f15079a35fca', 'ka', 'როგორ ხორციელდება კონტროლი საგანმანათლებლო დაწესებულების ბალანსზე სამსახურებრივი ავტომობილის არსებობის შემთხვევაში მის ექსპლუატაციაზე?', '["მძღოლის პერიოდული სამედიცინო შემოწმების გაუქმებით და უდოკუმენტოდ ექსპლუატაციაში გაშვებით", "საწვავ-საცხები მასალების უკანონო ხარჯვისა და ჩამოწერისთვის ხელის შეწყობით", "ტექნიკის ყოველგვარი ტექნიკური პასპორტისა და საგზური ფურცლის გარეშე თავისუფალი გამოყენებით", "ტექნიკის შეუკეთებელ, სამუხრუჭე სისტემის გაუმართავ და ავარიულ მდგომარეობაში ხაზზე გაშვებით", "საგზური ფურცლების სწორი შედგენით, ყოველდღიური გარბენის აღრიცხვით, საწვავ-საცხები მასალების ნორმატივების მიხედვით ხარჯვით, ტექნიკური დათვალიერებისა და დაზღვევის დროული გავლით"]'::jsonb, 'საგზური ფურცლების სწორი შედგენით, ყოველდღიური გარბენის აღრიცხვით, საწვავ-საცხები მასალების ნორმატივების მიხედვით ხარჯვით, ტექნიკური დათვალიერებისა და დაზღვევის დროული გავლით', 'Düzgün cavab: E) საგზური ფურცლების სწორი შედგენით, ყოველდღიური გარბენის აღრიცხვით, საწვავ-საცხები', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3f5f5c76-7962-4b44-bda6-3402c5187f53', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb təsərrüfatında tətbiq olunan ''Giriş nəzarəti və maddi qiymətlilərin hərəkəti'' qaydasına hansı tələb daxildir?', 'multiple_choice', '["Gözətçi və mühafizə heyətinə əmlakın çıxarılmasına nəzarət etməyi qadağan etmək", "Maddi qiymətlilərin məktəbə girişi və çıxışı üzrə heç bir rəsmi qeydiyyat aparmamaq", "Əmlakın, avadanlığın müəssisədən çıxarılmasının yalnız direktorun və ya direktor müavininin rəsmi icazə vərəqəsi (material buraxılış qaiməsi) əsasında icrası və jurnalda qeydiyyatı", "Müəssisənin avadanlıqlarını kənar təşkilatlara və şəxslərə sənədsiz paylamaq", "Məktəb inventarlarının qapıdan heç bir sənəd olmadan sərbəst çıxarılmasına icazə vermək"]'::jsonb, 'Əmlakın, avadanlığın müəssisədən çıxarılmasının yalnız direktorun və ya direktor müavininin rəsmi icazə vərəqəsi (material buraxılış qaiməsi) əsasında icrası və jurnalda qeydiyyatı', 'Düzgün cavab: C) Əmlakın, avadanlığın müəssisədən çıxarılmasının yalnız direktorun və ya direktor', '', 23, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0102803a-c484-4042-b57d-c866a9258e83', '3f5f5c76-7962-4b44-bda6-3402c5187f53', 'ka', 'რა მოთხოვნა შედის სკოლის მეურნეობაში მოქმედ ''შესვლის კონტროლისა და მატერიალურ ფასეულობათა მოძრაობის'' წესში?', '["სკოლის ინვენტარის კარიდან ყოველგვარი დოკუმენტის გარეშე თავისუფლად გატანის ნებართვის მიცემა", "დაწესებულების აღჭურვილობის გარეშე ორგანიზაციებსა და პირებზე უდოკუმენტოდ განაწილება", "ქონებისა და აღჭურვილობის დაწესებულებიდან გატანის განხორციელება მხოლოდ დირექტორის ან დირექტორის მოადგილის ოფიციალური ნებართვის (მატერიალური საშვის/ზედნადების) საფუძველზე და ჟურნალში რეგისტრაცია", "დარაჯებისა და დაცვის პერსონალისთვის ქონების გატანაზე კონტროლის აკრძალვა", "მატერიალურ ფასეულობათა სკოლაში შეტანა-გატანაზე არავითარი ოფიციალური აღრიცხვის არწარმოება"]'::jsonb, 'ქონებისა და აღჭურვილობის დაწესებულებიდან გატანის განხორციელება მხოლოდ დირექტორის ან დირექტორის მოადგილის ოფიციალური ნებართვის (მატერიალური საშვის/ზედნადების) საფუძველზე და ჟურნალში რეგისტრაცია', 'Düzgün cavab: C) ქონებისა და აღჭურვილობის დაწესებულებიდან გატანის განხორციელება მხოლოდ დირექტორის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('50b4cfe7-8b6b-4bd2-b41f-16744d3535f5', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təhsil müəssisəsində sanitar qovşaqların və kanalizasiya xətlərinin fasiləsiz işləməsi üçün hansı tədbir görülməlidir?', 'multiple_choice', '["Kanalizasiya xətlərinin baxış quyularını açıq və qapaqsız vəziyyətdə saxlamaq", "Kanalizasiya borularının tam tutulmasına və axıntı yaranmasına qədər tədbir görməmək", "Profilaktik yuma, təmizləmə, dezinfeksiya işləri aparmaq, axıtma mexanizmlərinin, kranların, sifonların sazlığını gündəlik yoxlamaq və qəzaların qarşısını almaq", "Sanitar qovşaqlarda xüsusi yuyucu və dezinfeksiyaedici vasitələrdən istifadəni qadağan etmək", "Sanitar qovşaqlarda su təchizatı xətlərini qənaət məqsədilə gün boyu bağlı saxlamaq"]'::jsonb, 'Profilaktik yuma, təmizləmə, dezinfeksiya işləri aparmaq, axıtma mexanizmlərinin, kranların, sifonların sazlığını gündəlik yoxlamaq və qəzaların qarşısını almaq', 'Düzgün cavab: C) Profilaktik yuma, təmizləmə, dezinfeksiya işləri aparmaq, axıtma mexanizmlərinin', '', 24, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2d45da6b-7d89-49ef-b830-b107427943bc', '50b4cfe7-8b6b-4bd2-b41f-16744d3535f5', 'ka', 'რა ზომები უნდა იქნეს მიღებული საგანმანათლებლო დაწესებულებაში სანიტარიული კვანძებისა და საკანალიზაციო ქსელების უწყვეტი მუშაობისთვის?', '["სანიტარიულ კვანძებში წყალმომარაგების ხაზების მთელი დღის განმავლობაში დაკეტვა ეკონომიის მიზნით", "ზომების არმიღება საკანალიზაციო მილების სრულ გაჭედვამდე და გაჟონვის წარმოქმნამდე", "პროფილაქტიკური რეცხვის, დასუფთავებისა და დეზინფექციის სამუშაოების ჩატარება, ჩარეცხვის მექანიზმების, ონკანებისა და სიფონების გამართულობის ყოველდღიური შემოწმება და ავარიების თავიდან აცილება", "სანიტარიულ კვანძებში სპეციალური სარეცხი და სადეზინფექციო საშუალებების გამოყენების აკრძალვა", "საკანალიზაციო ქსელების საკონტროლო ჭების ღია და თავსახურის გარეშე მდგომარეობაში დატოვება"]'::jsonb, 'პროფილაქტიკური რეცხვის, დასუფთავებისა და დეზინფექციის სამუშაოების ჩატარება, ჩარეცხვის მექანიზმების, ონკანებისა და სიფონების გამართულობის ყოველდღიური შემოწმება და ავარიების თავიდან აცილება', 'Düzgün cavab: C) პროფილაქტიკური რეცხვის, დასუფთავებისა და დეზინფექციის სამუშაოების ჩატარება, ჩარე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ee260566-ae9f-4818-ba9d-d53bb59ed7ae', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb laboratoriyalarında olan xüsusi təhlükəli kimyəvi maddələrin saxlanmasına təsərrüfat nəzarəti necə olmalıdır?', 'multiple_choice', '["Laboratoriya otaqlarında yanğın və texniki təhlükəsizlik təlimatlarını ləğv etmək", "Qaz balonlarını birbaşa istilik batareyalarının və elektrik qızdırıcılarının yanında yerləşdirmək", "Kimyəvi maddələri adi sinif otaqlarında açıq rəflərdə nəzarətsiz saxlamaq", "Qanunvericiliklə müəyyən edilmiş xüsusi saxlanma rejiminə, dəmir şkaflara, işarələnməyə, uçota və yanğın-texniki təhlükəsizlik normalarına ciddi riayət etməklə, cavabdeh şəxs təyin etməklə", "Təhlükəli kimyəvi reaktivləri adi məişət tullantıları qutusuna tökərək kənarlaşdırmaq"]'::jsonb, 'Qanunvericiliklə müəyyən edilmiş xüsusi saxlanma rejiminə, dəmir şkaflara, işarələnməyə, uçota və yanğın-texniki təhlükəsizlik normalarına ciddi riayət etməklə, cavabdeh şəxs təyin etməklə', 'Düzgün cavab: D) Qanunvericiliklə müəyyən edilmiş xüsusi saxlanma rejiminə, dəmir şkaflara, işarə', '', 25, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('36ab8aaa-ce1f-4cd5-8e49-eb7af21aeed7', 'ee260566-ae9f-4818-ba9d-d53bb59ed7ae', 'ka', 'როგორი უნდა იყოს სამეურნეო კონტროლი სკოლის ლაბორატორიებში არსებული განსაკუთრებით საშიში ქიმიური ნივთიერებების შენახვაზე?', '["ქიმიური ნივთიერებების შენახვა ჩვეულებრივ საკლასო ოთახებში ღია თაროებზე უმეთვალყურეოდ", "ლაბორატორიულ ოთახებში სახანძრო და ტექნიკური უსაფრთხოების ინსტრუქციების გაუქმება", "საშიში ქიმიური რეაქტივების ჩვეულებრივ საყოფაცხოვრებო ნარჩენების ურნაში ჩაყრა და გადაგდება", "კანონმდებლობით დადგენილი სპეციალური შენახვის რეჟიმის, რკინის კარადების, მარკირების, აღრიცხვისა და სახანძრო-ტექნიკური უსაფრთხოების ნორმების მკაცრი დაცვა და პასუხისმგებელი პირის დანიშვნა", "გაზის ბალონების განთავსება უშუალოდ გათბობის ბატარეებთან და ელექტროგამათბობლებთან ახლოს"]'::jsonb, 'კანონმდებლობით დადგენილი სპეციალური შენახვის რეჟიმის, რკინის კარადების, მარკირების, აღრიცხვისა და სახანძრო-ტექნიკური უსაფრთხოების ნორმების მკაცრი დაცვა და პასუხისმგებელი პირის დანიშვნა', 'Düzgün cavab: D) კანონმდებლობით დადგენილი სპეციალური შენახვის რეჟიმის, რკინის კარადების, მარკირებ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('57ca2256-f2a8-41d4-a706-20112242305b', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təhsil müəssisəsində qış fəslində daxili otaqlarda sanitar normalara görə minimal tələb olunan hava temperaturu nə qədərdir?', 'multiple_choice', '["Dərs otaqlarında 10–12°C, idman zalında 8–10°C", "Dərs otaqlarında 5–10°C, idman zalında 3–5°C", "Dərs otaqlarında 18–21°C (optimal 18–24°C), idman zalında 15–17°C, emalatxanalarda 16–18°C, dəhlizlərdə 16°C-dən aşağı olmamaqla", "Havanın daxili temperaturuna sanitar normalarla heç bir tələb qoyulmur", "Dərs otaqlarında 30–35°C, idman zalında 28–30°C"]'::jsonb, 'Dərs otaqlarında 18–21°C (optimal 18–24°C), idman zalında 15–17°C, emalatxanalarda 16–18°C, dəhlizlərdə 16°C-dən aşağı olmamaqla', 'Düzgün cavab: C) Dərs otaqlarında 18–21°C (optimal 18–24°C), idman zalında 15–17°C, emalatxanalar', '', 26, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7bd016b6-5879-49a6-a205-e908f05cbfe2', '57ca2256-f2a8-41d4-a706-20112242305b', 'ka', 'სანიტარიული ნორმების მიხედვით, რა არის მინიმალური მოთხოვნილი ჰაერის ტემპერატურა საგანმანათლებლო დაწესებულების შიდა ოთახებში ზამთრის პერიოდში?', '["საკლასო ოთახებში 30–35°C, სპორტდარბაზში 28–30°C - ცხელი რეჟიმი", "ჰაერის შიდა ტემპერატურაზე სანიტარიული ნორმებით არავითარი მოთხოვნა არ წესდება - თავისუფალი", "საკლასო ოთახებში 18–21°C (ოპტიმალური 18-24°C), სპორტდარბაზში 15–17°C, სახელოსნოებში 16-18°C, დერეფნებში არანაკლებ 16°C", "საკლასო ოთახებში 10–12°C, სპორტდარბაზში 8–10°C - ცივი რეჟიმი", "საკლასო ოთახებში 5–10°C, სპორტდარბაზში 3–5°C - ეკონომიური რეჟიმი"]'::jsonb, 'საკლასო ოთახებში 18–21°C (ოპტიმალური 18-24°C), სპორტდარბაზში 15–17°C, სახელოსნოებში 16-18°C, დერეფნებში არანაკლებ 16°C', 'Düzgün cavab: C) საკლასო ოთახებში 18–21°C (ოპტიმალური 18-24°C), სპორტდარბაზში 15–17°C, სახელოსნოე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f8e848c9-7a9f-47f1-a073-91b76ad6f708', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəb rəhbərliyi tərəfindən təsərrüfat işləri üzrə direktor müavininin fəaliyyətinin qiymətləndirilməsində hansı əsas meyar götürülür?', 'multiple_choice', '["Fənn dərsliklərinin və metodiki vəsaitlərin müəllif heyətinin müəyyənləşdirilməsi", "Maddi-texniki bazanın sazlığı və möhkəmliyi, təhlükəsiz, gigiyenik və estetik mühitin yaradılması, əmlakın qorunması, inventarizasiyanın düzgünlüyü və resurslardan səmərəli istifadə", "Pedaqoji heyətin gündəlik sinif jurnallarını və tədris planlarını doldurma səviyyəsi", "Şagirdlərin fənn olimpiadalarında və bilik yarışlarında qazandığı medalların sayı", "Təhsil müəssisəsinin mədəni-kütləvi tədbirlərində musiqi tərtibatının təşkili"]'::jsonb, 'Maddi-texniki bazanın sazlığı və möhkəmliyi, təhlükəsiz, gigiyenik və estetik mühitin yaradılması, əmlakın qorunması, inventarizasiyanın düzgünlüyü və resurslardan səmərəli istifadə', 'Düzgün cavab: B) Maddi-texniki bazanın sazlığı və möhkəmliyi, təhlükəsiz, gigiyenik və estetik mü', '', 27, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('dfecfdb9-d4d9-4fd1-b440-e79ac55f5c06', 'f8e848c9-7a9f-47f1-a073-91b76ad6f708', 'ka', 'რა ძირითადი კრიტერიუმი გამოიყენება სკოლის ხელმძღვანელობის მიერ სამეურნეო დარგში დირექტორის მოადგილის საქმიანობის შეფასებისას?', '["საგნობრივ ოლიმპიადებსა და ცოდნის კონკურსებში მოსწავლეთა მიერ მოპოვებული მედლების რაოდენობა", "მატერიალურ-ტექნიკური ბაზის გამართულობა და სიმტკიცე, უსაფრთხო, ჰიგიენური და ესთეტიკური გარემოს შექმნა, ქონების დაცვა, ინვენტარიზაციის სისწორე და რესურსების რაციონალური გამოყენება", "სასკოლო სახელმძღვანელოებისა და მეთოდიკური დამხმარე საშუალებების ავტორთა კოლექტივის განსაზღვრა", "საგანმანათლებლო დაწესებულების კულტურულ-მასობრივ ღონისძიებებზე მუსიკალური გაფორმების ორგანიზება", "პედაგოგიური პერსონალის მიერ ყოველდღიური საკლასო ჟურნალებისა და სასწავლო გეგმების შევსების დონე"]'::jsonb, 'მატერიალურ-ტექნიკური ბაზის გამართულობა და სიმტკიცე, უსაფრთხო, ჰიგიენური და ესთეტიკური გარემოს შექმნა, ქონების დაცვა, ინვენტარიზაციის სისწორე და რესურსების რაციონალური გამოყენება', 'Düzgün cavab: B) მატერიალურ-ტექნიკური ბაზის გამართულობა და სიმტკიცე, უსაფრთხო, ჰიგიენური და ესთეტ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('83ca10ca-6b15-4ac8-8a62-47320a788715', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təsərrüfat işləri üzrə direktor müavini məktəb direktorunun və təhsili idarəetmə orqanlarının hansı göstərişlərini icra etməyə borcludur?', 'multiple_choice', '["Yalnız şəxsi maraqlarına və fərdi mülahizələrinə uyğun gələn inzibati qərarları", "Yalnız məhkəmə orqanlarının xüsusi icra qərarı ilə verilən inzibati tapşırıqları", "Qanunvericiliyin tələblərinə zidd olan və sənədsiz, şifahi göstərişləri", "Qanunvericiliyə, müəssisənin Nizamnaməsinə, daxili intizam qaydalarına və vəzifə təlimatına uyğun olan bütün rəsmi qanuni tapşırıq və sərəncamları", "Müəssisə rəhbərliyinin heç bir rəsmi sərəncamını və xidməti tapşırığını icra etməmək hüququ vardır"]'::jsonb, 'Qanunvericiliyə, müəssisənin Nizamnaməsinə, daxili intizam qaydalarına və vəzifə təlimatına uyğun olan bütün rəsmi qanuni tapşırıq və sərəncamları', 'Düzgün cavab: D) Qanunvericiliyə, müəssisənin Nizamnaməsinə, daxili intizam qaydalarına və vəzifə', '', 28, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('13773260-8404-4307-8d94-fa97d5d27e18', '83ca10ca-6b15-4ac8-8a62-47320a788715', 'ka', 'სკოლის დირექტორისა და განათლების მმართველი ორგანოების რომელი მითითებების შესრულება ევალება სამეურნეო დარგში დირექტორის მოადგილეს?', '["მხოლოდ სასამართლო ორგანოების სპეციალური სააღსრულებო გადაწყვეტილებით გაცემული ადმინისტრაციული დავალებების", "მხოლოდ იმ ადმინისტრაციული გადაწყვეტილებების, რომლებიც მის პირად ინტერესებსა და შეხედულებებს ემთხვევა", "უფლება აქვს არ შეასრულოს დაწესებულების ხელმძღვანელობის არცერთი ოფიციალური განკარგულება და სამსახურებრივი დავალება", "კანონმდებლობასთან, დაწესებულების წესდებასთან, შინაგანაწესსა და თანამდებობრივ ინსტრუქციასთან შესაბამისობაში მყოფი ყველა ოფიციალური კანონიერი დავალებისა და განკარგულების", "კანონმდებლობის მოთხოვნებთან შეუსაბამო, უდოკუმენტო და ზეპირი მითითებების"]'::jsonb, 'კანონმდებლობასთან, დაწესებულების წესდებასთან, შინაგანაწესსა და თანამდებობრივ ინსტრუქციასთან შესაბამისობაში მყოფი ყველა ოფიციალური კანონიერი დავალებისა და განკარგულების', 'Düzgün cavab: D) კანონმდებლობასთან, დაწესებულების წესდებასთან, შინაგანაწესსა და თანამდებობრივ ინს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('536fd98e-0161-4317-830c-16c5104d9521', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Məktəbdə fəaliyyət göstərən tibb məntəqəsinin maddi-texniki və kommunal təminatında direktor müavininin vəzifəsi hansıdır?', 'multiple_choice', '["Şagirdlərə klinik diaqnozlar qoyaraq onları xüsusi müalicə müəssisələrinə göndərmək", "Tibb otağını təsərrüfat avadanlıqlarının saxlanması üçün anbar sahəsinə çevirmək", "Tibb bacısının əvəzinə xəstələnən şagirdlərə fərdi farmakoloji dərmanlar təyin etmək", "Otağın daimi işıq, istilik, isti-soyuq su təchizatı, havalandırma, zəruri tibbi mebel, kušetka, soyuducu və ilk yardım avadanlığı ilə təminatını, təmizliyini təşkil etmək", "Tibb məntəqəsinin fəaliyyətini dayandıraraq otağı tədris kabineti kimi istifadəyə vermək"]'::jsonb, 'Otağın daimi işıq, istilik, isti-soyuq su təchizatı, havalandırma, zəruri tibbi mebel, kušetka, soyuducu və ilk yardım avadanlığı ilə təminatını, təmizliyini təşkil etmək', 'Düzgün cavab: D) Otağın daimi işıq, istilik, isti-soyuq su təchizatı, havalandırma, zəruri tibbi', '', 29, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('318c6698-1e58-4c0c-94d9-58f2cf4d08de', '536fd98e-0161-4317-830c-16c5104d9521', 'ka', 'რა ევალება დირექტორის მოადგილეს სკოლაში მოქმედი სამედიცინო პუნქტის მატერიალურ-ტექნიკურ და კომუნალურ უზრუნველყოფაში?', '["სამედიცინო პუნქტის მუშაობის შეწყვეტა და ოთახის სასწავლო კაბინეტად გამოყენება", "ექთნის ნაცვლად ავადმყოფი მოსწავლეებისთვის ინდივიდუალური ფარმაკოლოგიური მედიკამენტების დანიშვნა", "სამედიცინო ოთახის გადაქცევა სამეურნეო ინვენტარის შესანახ სასაწყობო ფართობად", "ოთახის მუდმივი განათებით, გათბობით, ცხელი და ცივი წყლით, ვენტილაციით, აუცილებელი სამედიცინო ავეჯით, ტახტით (კუშეტკა), მაცივრითა და პირველადი დახმარების აღჭურვილობით უზრუნველყოფა და სისუფთავის ორგანიზება", "მოსწავლეებისთვის კლინიკური დიაგნოზების დასმა და მათი სპეციალურ სამკურნალო დაწესებულებებში გაგზავნა"]'::jsonb, 'ოთახის მუდმივი განათებით, გათბობით, ცხელი და ცივი წყლით, ვენტილაციით, აუცილებელი სამედიცინო ავეჯით, ტახტით (კუშეტკა), მაცივრითა და პირველადი დახმარების აღჭურვილობით უზრუნველყოფა და სისუფთავის ორგანიზება', 'Düzgün cavab: D) ოთახის მუდმივი განათებით, გათბობით, ცხელი და ცივი წყლით, ვენტილაციით, აუცილებელი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5fcddc35-8fcf-4620-b530-c4a965d79fb8', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Təsərrüfat işləri üzrə direktor müavini ilə təsərrüfat müdiri arasındakı tabelilik və səlahiyyət bölgüsü necə tənzimlənir?', 'multiple_choice', '["Direktor müavini strateji planlaşdırma, sifariş, smeta və nəzarəti həyata keçirir; təsərrüfat müdiri ona tabe olaraq gündəlik icranı, anbar uçotunu və texniki heyətin işini təmin edir", "Hər iki vəzifə eyni vaxtda mütləq şəkildə vahid bir şəxs tərəfindən icra olunur", "Hər iki vəzifəli şəxs tamamilə müstəqildir və xidməti fəaliyyətdə bir-biri ilə əlaqə saxlamır", "Təsərrüfat müdiri direktor müavininə rəhbərlik edərək onun xidməti fəaliyyətini qiymətləndirir", "Direktor müavini yalnız xadimələrə rəhbərlik edir, digər təsərrüfat heyətinə qarışmır"]'::jsonb, 'Direktor müavini strateji planlaşdırma, sifariş, smeta və nəzarəti həyata keçirir; təsərrüfat müdiri ona tabe olaraq gündəlik icranı, anbar uçotunu və texniki heyətin işini təmin edir', 'Düzgün cavab: A) Direktor müavini strateji planlaşdırma, sifariş, smeta və nəzarəti həyata keçiri', '', 30, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bf6abed1-6fc4-4d64-8d30-ff4583f27ab8', '5fcddc35-8fcf-4620-b530-c4a965d79fb8', 'ka', 'როგორ რეგულირდება დაქვემდებარებისა და უფლებამოსილებათა განაწილება სამეურნეო დარგში დირექტორის მოადგილესა და სამეურნეო ნაწილის გამგეს (ზავხოზს) შორის?', '["დირექტორის მოადგილე ახორციელებს სტრატეგიულ დაგეგმვას, შეკვეთებს, ხარჯთაღრიცხვასა და კონტროლს; სამეურნეო ნაწილის გამგე ექვემდებარება მას და უზრუნველყოფს ყოველდღიურ შესრულებას, სასაწყობო აღრიცხვასა და ტექნიკური პერსონალის მუშაობას", "სამეურნეო ნაწილის გამგე ხელმძღვანელობს დირექტორის მოადგილეს და აფასებს მის სამსახურებრივ საქმიანობას", "ორივე თანამდებობის პირი სრულიად დამოუკიდებელია და სამსახურებრივ საქმიანობაში ერთმანეთთან შეხება არ აქვთ", "დირექტორის მოადგილე ხელმძღვანელობს მხოლოდ დამლაგებლებს და არ ერევა სხვა სამეურნეო პერსონალის საქმიანობაში", "ორივე თანამდებობა ერთდროულად აუცილებლად ერთი პირის მიერ სრულდება"]'::jsonb, 'დირექტორის მოადგილე ახორციელებს სტრატეგიულ დაგეგმვას, შეკვეთებს, ხარჯთაღრიცხვასა და კონტროლს; სამეურნეო ნაწილის გამგე ექვემდებარება მას და უზრუნველყოფს ყოველდღიურ შესრულებას, სასაწყობო აღრიცხვასა და ტექნიკური პერსონალის მუშაობას', 'Düzgün cavab: A) დირექტორის მოადგილე ახორციელებს სტრატეგიულ დაგეგმვას, შეკვეთებს, ხარჯთაღრიცხვასა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6bc25f74-e32c-4a3d-ad78-44c6fd26b9d1', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Azərbaycan Respublikası Konstitusiyasının 42-ci maddəsinə əsasən, vətəndaşların təhsil hüququ ilə bağlı dövlətin əsas təminatı nədir?', 'multiple_choice', '["Dövlət hər bir vətəndaşın ali təhsil almasını məcburi edir və təhsil xərclərini tam şəkildə kommersiya banklarına həvalə edir", "Dövlət yalnız əlaçı şagirdlərin pulsuz təhsil almasını təmin edir və digər vətəndaşlara ödənişli əsaslarla şərait yaradır", "Dövlət yalnız dövlət qulluqçularının övladlarının pulsuz orta ixtisas təhsili almasına hüquqi zəmanət verir", "Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir", "Dövlət təhsil sistemində bütün pillələrin tamamilə ödənişli əsaslarla təşkil edilməsini qanunvericiliklə tənzimləyir"]'::jsonb, 'Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir', 'Düzgün cavab: D) Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin e', '', 31, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f184b25e-742c-4608-84c2-7acf92f9f529', '6bc25f74-e32c-4a3d-ad78-44c6fd26b9d1', 'ka', 'კონსტიტუციის 42-ე მუხლის თანახმად, განათლების უფლების უზრუნველყოფასთან დაკავშირებით რომელი დებულებაა განმტკიცებული?', '["სახელმწიფო საგანმანათლებლო დაწესებულებების დაფინანსებას ახორციელებს მხოლოდ მუნიციპალიტეტების ადგილობრივი ბიუჯეტების ხარჯზე", "სახელმწიფო ყველა მოქალაქეს უზრუნველყოფს სახელმწიფო უმაღლეს საგანმანათლებლო დაწესებულებებში უფასო სრული უმაღლესი განათლების მიღების უფლებით", "სახელმწიფო მხოლოდ ნიჭიერი პირებისთვის უზრუნველყოფს განათლების გაგრძელებას მათი მატერიალური მდგომარეობის მიუხედავად", "სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო ზოგად საბაზო განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და სახელმწიფო კონტროლს განათლების სისტემაზე", "სახელმწიფო მოქალაქეებისთვის სავალდებულოდ მიიჩნევს საშუალო პროფესიული განათლების მიღებას მხოლოდ დასწრებული ფორმით"]'::jsonb, 'სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო ზოგად საბაზო განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და სახელმწიფო კონტროლს განათლების სისტემაზე', 'Düzgün cavab: D) სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო ზოგად საბაზ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e7d39a8b-4d92-47a5-a66c-2660c090a553', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Azərbaycan Respublikası Konstitusiyasının 25-ci maddəsinə əsasən, bərabərlik hüququnun təhsil və əmək münasibətlərində təminatı necə müəyyən olunmuşdur?', 'multiple_choice', '["Vətəndaşların hüquq bərabərliyi yalnız dövlət qulluğunda çalışan şəxslərə şamil edilir, digər sahələrdə fərqli münasibət qanunidir", "Sosial mənşəyindən və yaşayış yerindən asılı olaraq təhsil müəssisələrinə qəbulda məhdudiyyətlər qoyula bilər", "Ayrı-seçkiliyə yalnız müəssisə rəhbərinin yazılı əmri və daxili nizamnamə tələbləri ilə yol verilə bilər", "İşə qəbul və təhsil prosesində yalnız rəhbərliyin subyektiv mülahizələri əsas götürülür və imtiyazlar müəyyən edilir", "Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir"]'::jsonb, 'Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir', 'Düzgün cavab: E) Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyin', '', 32, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('eb7787c6-7c4e-4dc0-b22c-6c9dcd80bb77', 'e7d39a8b-4d92-47a5-a66c-2660c090a553', 'ka', 'კონსტიტუციის 25-ე მუხლის თანახმად, რომელია თანასწორობის უფლების შინაარსის ამსახველი სწორი ნორმა?', '["თითოეული ადამიანის უფლებები და თავისუფლებები თანასწორად ითვლება მხოლოდ აღმასრულებელი ხელისუფლების ორგანოს თანხმობის არსებობისას", "სახელმწიფო მხოლოდ საჯარო მოხელეებისთვის ადგენს სასამართლოს წინაშე სპეციალურ პრივილეგირებულ თანასწორობის უფლებას", "ადამიანისა და მოქალაქის უფლებები უზრუნველყოფილია მხოლოდ მოქალაქის კერძო საკუთრების მოცულობის მიხედვით", "თანასწორობის უფლება არეგულირებს მხოლოდ 18 წელს მიღწეულ მოქალაქეთა მონაწილეობას საარჩევნო პროცესში", "სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესისა და სოციალური წარმოშობის მიუხედავად"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესისა და სოციალური წარმოშობის მიუხედავად', 'Düzgün cavab: E) სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f8d886a5-8d1f-43a8-8f79-c11561f7bcea', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Azərbaycan Respublikası Konstitusiyasının 32-ci maddəsinə əsasən, şəxsi toxunulmazlıq hüququ təhsil müəssisəsində hansı tələbi irəli sürür?', 'multiple_choice', '["Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir", "Şəxsin yazışma və telefon danışıqlarının sirri yalnız daxili intizam qaydaları ilə məhdudlaşdırıla bilər", "Fərdi məlumatların informasiya sistemlərində qeydiyyatı şəxsin xəbəri olmadan istənilən qurum tərəfindən aparıla bilər", "İşçilərin fərdi məlumatları və tibbi arayışları kollektiv qarşısında müzakirə edilməli və elan lövhəsinə vurulmalıdır", "Təhsil müəssisəsi rəhbərliyi işçilərin şəxsi məlumatlarını istədiyi məqsədlə kənar şəxslərə və sosial şəbəkələrə açıqlaya bilər"]'::jsonb, 'Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir', 'Düzgün cavab: A) Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılması', '', 33, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ef941d9d-dec3-489d-812d-33f3be80ed21', 'f8d886a5-8d1f-43a8-8f79-c11561f7bcea', 'ka', 'კონსტიტუციის 32-ე მუხლის თანახმად, რა წესია დადგენილი პირადი ხელშეუხებლობის უფლებასთან დაკავშირებით?', '["მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა და გავრცელება დაუშვებელია, გარდა კანონით პირდაპირ გათვალისწინებული შემთხვევებისა", "საგანმანათლებლო დაწესებულების ხელმძღვანელობას შეუძლია თანამშრომლის პირადი ცხოვრების შესახებ ინფორმაცია თავისუფლად წარუდგინოს საზოგადოებას", "პირის მიმოწერისა და სატელეფონო საუბრების საიდუმლოება შეიძლება შეიზღუდოს მხოლოდ შინაგანაწესით", "პირადი ხელშეუხებლობის უფლება მოქმედებს მხოლოდ იმ სამუშაო დროის განმავლობაში, როდესაც პირი სამუშაო ადგილზე ასრულებს სამსახურებრივ მოვალეობებს", "პერსონალური მონაცემების საინფორმაციო სისტემებში რეგისტრაცია შეიძლება განხორციელდეს ნებისმიერი უწყების მიერ პირის ინფორმირების გარეშე"]'::jsonb, 'მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა და გავრცელება დაუშვებელია, გარდა კანონით პირდაპირ გათვალისწინებული შემთხვევებისა', 'Düzgün cavab: A) მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('36fd2ab2-4647-43e7-a9e4-022afc494048', '0d80fe94-6f97-4552-86f3-825d1ba268e0', '“Təhsil haqqında” AR Qanununun 3-cü maddəsinə əsasən, dövlət siyasətinin əsas prinsiplərindən olan ''Humanistlik'' nəyi ifadə edir?', 'multiple_choice', '["Bütün vətəndaşların fasiləsiz olaraq ömür boyu peşəkar təhsil almaq imkanını", "Təhsil sisteminin dünya təhsil məkanına çevik inteqrasiya olunmasını", "Təhsil müəssisələrinin idarə edilməsində ictimaiyyətin iştirakını", "Təhsil prosesinin milli və beynəlxalq standartların tələblərinə uyğunlaşdırılmasını", "Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını"]'::jsonb, 'Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını', 'Düzgün cavab: E) Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və', '', 34, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1a2ef4a0-3409-4a20-892c-0f272667eace', '36fd2ab2-4647-43e7-a9e4-022afc494048', 'ka', '„განათლების შესახებ“ კანონის მე-3 მუხლის თანახმად, რას გამოხატავს „ჰუმანურობის“ პრინციპი?', '["ყველა მოქალაქის შესაძლებლობას უწყვეტად, მთელი სიცოცხლის მანძილზე მიიღოს პროფესიული განათლება", "საგანმანათლებლო დაწესებულებების მართვაში საზოგადოების მონაწილეობას", "განათლების სისტემის მოქნილ ინტეგრაციას მსოფლიო საგანმანათლებლო სივრცეში", "სასწავლო პროცესის ეროვნული და საერთაშორისო სტანდარტების მოთხოვნებთან შესაბამისობას", "ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას"]'::jsonb, 'ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას', 'Düzgün cavab: E) ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('787b05f0-6e8d-416f-a204-08eeeea92853', '0d80fe94-6f97-4552-86f3-825d1ba268e0', '“Təhsil haqqında” AR Qanununun 12-ci maddəsinə əsasən, təsbit edilmiş təhsil formaları hansılardır?', 'multiple_choice', '["Dövlət təhsili, bələdiyyə təhsili və xüsusi təhsil", "Əyani, qiyabi, distant və sərbəst təhsilalma", "Formal, qeyri-formal və informal təhsil", "Məktəbəqədər, ümumi orta, ilk peşə və ali təhsil", "İbtidai təhsil, əsas təhsil və tam orta təhsil"]'::jsonb, 'Formal, qeyri-formal və informal təhsil', 'Düzgün cavab: C) Formal, qeyri-formal və informal təhsil', '', 35, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('54a90fc3-df7b-42bc-9318-b5f54203122b', '787b05f0-6e8d-416f-a204-08eeeea92853', 'ka', '„განათლების შესახებ“ კანონის მე-12 მუხლის თანახმად, რომელია განსაზღვრული განათლების ფორმები?', '["დაწყებითი განათლება, საბაზო განათლება და სრული საშუალო განათლება", "სკოლამდელი, ზოგადი საშუალო, პირველადი პროფესიული და უმაღლესი განათლება", "ფორმალური, არაფორმალური და ინფორმალური განათლება", "დასწრებული, დაუსწრებელი, დისტანციური და თავისუფალი (ექსტერნატი) განათლება", "სახელმწიფო განათლება, მუნიციპალური განათლება და სპეციალური განათლება"]'::jsonb, 'ფორმალური, არაფორმალური და ინფორმალური განათლება', 'Düzgün cavab: C) ფორმალური, არაფორმალური და ინფორმალური განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9f530cd4-1cf0-474e-8fa4-d8c129a6aed0', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Müxtəlif səbəblərdən ümumi təhsildən kənarda qalmış şəxslərə təhsil almaq və ya təhsilin hər hansı pilləsini vaxtından əvvəl bitirmək hüququ verən təhsilalma forması hansıdır?', 'multiple_choice', '["Sərbəst (eksternat) təhsilalma forması", "Qiyabi təhsilalma", "Distant (məsafədən) təhsilalma", "Evdə təhsilalma", "İnformal təhsil"]'::jsonb, 'Sərbəst (eksternat) təhsilalma forması', 'Düzgün cavab: A) Sərbəst (eksternat) təhsilalma forması', '', 36, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('52078074-231c-45c5-a5c1-d71f8ccb2f79', '9f530cd4-1cf0-474e-8fa4-d8c129a6aed0', 'ka', 'რომელი ფორმა აძლევს განათლების მიღების უფლებას იმ პირებს, რომლებიც სხვადასხვა მიზეზით დარჩნენ ზოგადი განათლების მიღმა?', '["ექსტერნატის (თავისუფალი) სწავლების ფორმა", "ინფორმალური განათლება", "დისტანციური სწავლება", "დაუსწრებელი სწავლება", "შინ სწავლება"]'::jsonb, 'ექსტერნატის (თავისუფალი) სწავლების ფორმა', 'Düzgün cavab: A) ექსტერნატის (თავისუფალი) სწავლების ფორმა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5cd3a1ad-6533-4450-8e31-d3d909dfadff', '0d80fe94-6f97-4552-86f3-825d1ba268e0', '“Təhsil haqqında” AR Qanununun 32-ci maddəsinə əsasən, təhsilverənlərin vəzifələrinə aid olan müddəa hansıdır?', 'multiple_choice', '["Yeni tədris proqramlarını və dərslik layihələrini sərbəst şəkildə seçmək", "İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri və müasir texnologiyaları mənimsəyərək tədris prosesində tətbiq etmək", "Şərəf və ləyaqətinə hörmətlə yanaşılmasını və təhlükəsiz iş şəraitini tələb etmək", "Təhsil müəssisəsinin idarə olunmasında təkliflərlə çıxış etmək", "Təhsil müəssisəsində müvafiq vəzifə tutmaq və seçkili orqanlarda təmsil olunmaq"]'::jsonb, 'İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri və müasir texnologiyaları mənimsəyərək tədris prosesində tətbiq etmək', 'Düzgün cavab: B) İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri və müasir texnologiyaları mən', '', 37, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('69fea604-fced-4ee5-b16b-a207076ba953', '5cd3a1ad-6533-4450-8e31-d3d909dfadff', 'ka', '„განათლების შესახებ“ კანონის 32-ე მუხლის თანახმად, რომელი დებულება განეკუთვნება მასწავლებელთა (პედაგოგთა) მოვალეობებს?', '["საგანმანათლებლო დაწესებულებაში შესაბამისი თანამდებობის დაკავება და არჩევით ორგანოებში წარმოდგენა", "კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლოგიების ათვისება და სასწავლო პროცესში დანერგვა", "პატივისა და ღირსების პატივისცემისა და უსაფრთხო სამუშაო პირობების მოთხოვნა", "საგანმანათლებლო დაწესებულების მართვაში წინადადებებით გამოსვლა", "ახალი სასწავლო პროგრამებისა და სახელმძღვანელოების პროექტების თავისუფლად არჩევა"]'::jsonb, 'კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლოგიების ათვისება და სასწავლო პროცესში დანერგვა', 'Düzgün cavab: B) კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('031b064b-b927-499c-8662-343954683ea6', '0d80fe94-6f97-4552-86f3-825d1ba268e0', '“Ümumi təhsil haqqında” AR Qanununa əsasən, ümumi təhsil pilləsinin səviyyələri hansı ardıcıllıqla düzgün göstərilmişdir?', 'multiple_choice', '["Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)", "Məktəbəqədər təhsil (3–5 yaş), ümumi təhsil (I–XI) və bakalavriat səviyyəsi", "İbtidai təhsil (I–IV), əsas təhsil (V–VIII) və orta ixtisas təhsili (IX–XI)", "Yalnız ümumi orta təhsil (I–IX) və tam orta təhsil (X–XI)", "İbtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və peşə təhsili səviyyəsi"]'::jsonb, 'Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)', 'Düzgün cavab: A) Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və ta', '', 38, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a99dbb80-0042-4963-8c74-0579e014b480', '031b064b-b927-499c-8662-343954683ea6', 'ka', '„ზოგადი განათლების შესახებ“ კანონის თანახმად, რომელია ზოგადი განათლების საფეხურები?', '["სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), ზოგადი საბაზო განათლება (V–IX) და სრული საშუალო განათლება (X–XI)", "დაწყებითი განათლება (I–IV), საბაზო განათლება (V–IX) და პროფესიული განათლების საფეხური", "სკოლამდელი განათლება (3–5 წელი), ზოგადი განათლება (I–XI) და ბაკალავრიატის საფეხური", "დაწყებითი განათლება (I–IV), ძირითადი განათლება (V–VIII) და საშუალო სპეციალური განათლება (IX–XI)", "მხოლოდ ზოგადი საბაზო განათლება (I–IX) და სრული საშუალო განათლება (X–XI)"]'::jsonb, 'სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), ზოგადი საბაზო განათლება (V–IX) და სრული საშუალო განათლება (X–XI)', 'Düzgün cavab: A) სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), ზოგადი საბაზო განათლება (V–IX', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7e7fdc0b-e819-47c6-a1a2-ac468ef2dc1c', '0d80fe94-6f97-4552-86f3-825d1ba268e0', '“Ümumi təhsil haqqında” AR Qanununun 21-ci maddəsinə əsasən, təhsilalanların hüquqlarına **AİD EDİLMƏYƏN** müddəa hansıdır?', 'multiple_choice', '["İnsan ləyaqətini alçaldan zorakılıq hallarından müdafiə olunmaq", "Həyat və sağlamlıq üçün təhlükəsiz təhsil şəraiti ilə təmin olunmaq", "Dövlət və bələdiyyə məktəblərində dərsliklərlə pulsuz təmin olunmaq", "Təhsil müəssisəsinin mövcud infrastrukturundan ödənişsiz istifadə etmək", "Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq"]'::jsonb, 'Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq', 'Düzgün cavab: E) Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoj', '', 39, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('66793557-2194-4fee-a3b3-72e01d2cb6b6', '7e7fdc0b-e819-47c6-a1a2-ac468ef2dc1c', 'ka', '„ზოგადი განათლების შესახებ“ კანონის 21-ე მუხლის თანახმად, რომელი დებულება არ განეკუთვნება მოსწავლეთა უფლებებს?', '["საგანმანათლებლო დაწესებულების არსებული ინფრასტრუქტურით უფასოდ სარგებლობა", "სიცოცხლისა და ჯანმრთელობისთვის უსაფრთხო საგანმანათლებლო პირობებით უზრუნველყოფა", "ადამიანის ღირსების შემლახავი ძალადობის შემთხვევებისგან დაცვა", "სახელმწიფო და მუნიციპალურ სკოლებში სახელმძღვანელოებით უფასოდ უზრუნველყოფა", "დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება"]'::jsonb, 'დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება', 'Düzgün cavab: E) დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b2f46db5-3cdb-4a3d-9717-31587672e121', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Dövlət və bələdiyyə ümumi təhsil müəssisələrinin Nümunəvi Nizamnaməsinə əsasən, məktəbin fəaliyyətinə cari rəhbərliyi kim həyata keçirir?', 'multiple_choice', '["Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən vəzifəyə təyin olunan direktor", "Müəssisənin Pedaqoji Şurasının seçkili katibi", "Rayon İcra Hakimiyyətinin təyin etdiyi xüsusi nümayəndə", "Məktəbin Valideyn-Müəllim Assosiasiyasının idarə heyətinin sədri", "Təhsil müəssisəsinin Həmkarlar İttifaqı Komitəsinin rəhbəri"]'::jsonb, 'Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən vəzifəyə təyin olunan direktor', 'Düzgün cavab: A) Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən vəzifəyə t', '', 40, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3383a34b-d074-48c3-9521-dbf14bf840de', 'b2f46db5-3cdb-4a3d-9717-31587672e121', 'ka', 'სანიმუშო წესდების თანახმად, ვინ ახორციელებს სკოლის საქმიანობის მიმდინარე ხელმძღვანელობას?', '["შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექტორი", "რაიონის აღმასრულებელი ხელისუფლების მიერ დანიშნული სპეციალური წარმომადგენელი", "სკოლის მშობელთა და მასწავლებელთა ასოციაციის გამგეობის თავმჯდომარე", "დაწესებულების პედაგოგიური საბჭოს არჩეული მდივანი", "საგანმანათლებლო დაწესებულების პროფკავშირული კომიტეტის ხელმძღვანელი"]'::jsonb, 'შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექტორი', 'Düzgün cavab: A) შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0681360b-dedd-4088-b14d-27a5df7cf6b4', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Ümumi təhsil müəssisələrində Pedaqoji Şura haqqında Əsasnaməyə əsasən, qərarların qəbul edilməsi qaydası necədir?', 'multiple_choice', '["Qərarlar yalnız məktəb direktorunun fərdi şifahi razılığı ilə qüvvəyə minir", "Qərarlar yalnız rayon təhsil sektorunun yazılı razılığı alındıqdan sonra tətbiq edilir", "Pedaqoji Şuranın qərarları tövsiyə xarakteri daşıyır və rəsmi əmrlə təsdiqlənmir", "İclasda yalnız metodbirləşmə rəhbərləri səsvermə hüququna malikdir", "İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilərək direktorun əmri ilə rəsmiləşdirilir"]'::jsonb, 'İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilərək direktorun əmri ilə rəsmiləşdirilir', 'Düzgün cavab: E) İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qəra', '', 41, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3d35ee73-dff8-4903-988f-e8e3e6eec689', '0681360b-dedd-4088-b14d-27a5df7cf6b4', 'ka', 'პედაგოგიური საბჭოს შესახებ დებულების თანახმად, როგორია გადაწყვეტილებების მიღების წესი?', '["გადაწყვეტილებები ძალაში შედის მხოლოდ სკოლის დირექტორის ინდივიდუალური ზეპირი თანხმობით", "გადაწყვეტილებები გამოიყენება მხოლოდ რაიონული განათლების სექტორის წერილობითი თანხმობის მიღების შემდეგ", "სხდომაზე ხმის მიცემის უფლება აქვთ მხოლოდ საგნობრივი კათედრების ხელმძღვანელებს", "პედაგოგიური საბჭოს გადაწყვეტილებებს აქვს სარეკომენდაციო ხასიათი და არ მტკიცდება ოფიციალური ბრძანებით", "სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით"]'::jsonb, 'სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით', 'Düzgün cavab: E) სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('99465e54-d042-4167-bd8c-31869e4bdf9f', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Azərbaycan Respublikasının Əmək Məcəlləsinin 89 və 91-ci maddələrinə əsasən, iş vaxtının normal və qısaldılmış müddəti necədir?', 'multiple_choice', '["Bütün işçilər üçün vahid həftəlik 40 saatlıq tam iş vaxtı tətbiq olunur", "Həftəlik normal iş vaxtı 36 saat, hamilə qadınlar üçün 24 saat müəyyən edilir", "Həftəlik normal iş vaxtı 48 saat, 16 yaşınadək işçilər üçün 36 saatdan çox ola bilməz", "Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz", "Həftəlik normal iş vaxtı 45 saat, pedaqoji heyət üçün 18 saatdan çox ola bilməz"]'::jsonb, 'Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz', 'Düzgün cavab: D) Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün i', '', 42, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('fbed11c0-cce5-4594-af4c-d0011e54e0ce', '99465e54-d042-4167-bd8c-31869e4bdf9f', 'ka', 'შრომის კოდექსის 89-ე და 91-ე მუხლების თანახმად, როგორია სამუშაო დროის ნორმალური და შემოკლებული ხანგრძლივობა?', '["კვირეული ნორმალური სამუშაო დროა 36 საათი, ხოლო ორსული ქალებისთვის განისაზღვრება 24 საათი", "კვირეული ნორმალური სამუშაო დროა 45 საათი, პედაგოგიური პერსონალისთვის კი არ შეიძლება აღემატებოდეს 18 საათს", "ყველა მუშაკისთვის გამოიყენება ერთიანი კვირეული 40-საათიანი სრული სამუშაო დრო", "კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის - კვირაში 36 საათს", "კვირეული ნორმალური სამუშაო დროა 48 საათი, 16 წლამდე ასაკის მუშაკებისთვის კი არ უნდა აღემატებოდეს 36 საათს"]'::jsonb, 'კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის - კვირაში 36 საათს', 'Düzgün cavab: D) კვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0f91c08d-d763-477b-b59d-39c05f1df1d7', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Əmək Məcəlləsinin 186-cı maddəsinə əsasən, əmək və icra intizamını pozan işçiyə işəgötürən tərəfindən tətbiq edilə bilən intizam tənbehlərinin tam siyahısı hansıdır?', 'multiple_choice', '["Şifahi xəbərdarlıq, ictimai töhmət, cərimə və məzuniyyətin ləğv edilməsi", "Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi", "İnzibati cərimə, məcburi ictimai işlər və başqa müəssisəyə məcburi keçirilmə", "Yalnız yazılı töhmət və işçinin fəxri adlardan məhrum edilməsi", "Vəzifə maaşının 50% azaldılması, növbəti məzuniyyətin verilməməsi"]'::jsonb, 'Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi', 'Düzgün cavab: B) Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutu', '', 43, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a25f95dd-dc3d-4e8e-9708-9ef9747deb4c', '0f91c08d-d763-477b-b59d-39c05f1df1d7', 'ka', 'შრომის კოდექსის 186-ე მუხლის თანახმად, რომელია დისციპლინური სახდელების სრული ჩამონათვალი?', '["ზეპირი გაფრთხილება, საზოგადოებრივი საყვედური, ჯარიმა და შვებულების გაუქმება", "საყვედური, მკაცრი საყვედური ბოლო გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალისწინებულ შემთხვევაში ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა და შრომითი ხელშეკრულების შეწყვეტა", "თანამდებობრივი სარგოს 50%-ით შემცირება, მორიგი შვებულების არმიცემა", "ადმინისტრაციული ჯარიმა, სავალდებულო საზოგადოებრივი სამუშაო და სხვა დაწესებულებაში იძულებითი გადაყვანა", "მხოლოდ წერილობითი საყვედური და თანამშრომლისთვის საპატიო წოდებების ჩამორთმევა"]'::jsonb, 'საყვედური, მკაცრი საყვედური ბოლო გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალისწინებულ შემთხვევაში ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა და შრომითი ხელშეკრულების შეწყვეტა', 'Düzgün cavab: B) საყვედური, მკაცრი საყვედური ბოლო გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c1ca7b8e-409a-4823-8100-94b81e56d3d7', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'AR Əmək Məcəlləsinin 187 və 188-ci maddələrinə əsasən, intizam tənbehinin verilməsi və qüvvədə olma müddəti qaydası necədir?', 'multiple_choice', '["İşçi yazılı izahat verməkdən imtina etdikdə ona heç bir tənbeh tətbiq edilə bilməz", "İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz", "İntizam tənbehi verildikdə işçidən izahat alınır və tənbeh verildiyi gündən 1 il qüvvədə qalır", "İntizam tənbehi yalnız məhkəmə qərarı əsasında verilir", "İntizam tənbehi xətanın aşkar edildiyi gündən 6 ay keçdikdən sonra da verilə bilər və 2 il qüvvədə qalır"]'::jsonb, 'İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz', 'Düzgün cavab: B) İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbe', '', 44, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('03a65922-46dd-444f-8e0c-bc3d38681918', 'c1ca7b8e-409a-4823-8100-94b81e56d3d7', 'ka', 'შრომის კოდექსის 187-ე მუხლის თანახმად, როგორია დისციპლინური სახდელის დადების წესი?', '["დისციპლინური სახდელი გამოიყენება მხოლოდ სასამართლოს გადაწყვეტილების საფუძველზე", "დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი მოქმედებს მისი გამოტანის დღიდან 1 წლის განმავლობაში", "თუ დასაქმებული უარს იტყვის წერილობითი ახსნა-განმარტების მიცემაზე, მის მიმართ ვერანაირი სახდელი ვერ იქნება გამოყენებული", "ერთი დისციპლინური გადაცდომისთვის დასაქმებულს ერთდროულად შეიძლება დაედოს როგორც მკაცრი საყვედური, ისე შეუწყდეს ხელშეკრულება", "დისციპლინური სახდელი შეიძლება დაედოს გადაცდომის გამოვლენის დღიდან 6 თვის გასვლის შემდეგაც და ძალაში რჩება 2 წელი"]'::jsonb, 'დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი მოქმედებს მისი გამოტანის დღიდან 1 წლის განმავლობაში', 'Düzgün cavab: B) დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('185e51b9-9f65-45f9-92e5-143e11e48ee9', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Əmək Məcəlləsinin 69 və 172-ci maddələrinə əsasən, işçinin öz təşəbbüsü ilə əmək müqaviləsinə xitam verilməsi və son haqq-hesabın ödənilməsi qaydası necədir?', 'multiple_choice', '["İşçi istədiyi gün xəbərdarlıq etmədən işi tərk edə bilər", "Əmək müqaviləsinə xitam verilməsi yalnız həmkarlar ittifaqının razılığı ilə mümkündür", "İşçi 3 gün əvvəl şifahi xəbərdarlıq etməlidir", "İşçi 2 həftə əvvəl bildiriş verməlidir; kompensasiya növbəti ildə ödənilir", "İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab müqaviləyə xitam verildiyi sonuncu iş günündən gec olmayaraq ödənilir"]'::jsonb, 'İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab müqaviləyə xitam verildiyi sonuncu iş günündən gec olmayaraq ödənilir', 'Düzgün cavab: E) İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haq', '', 45, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ed5309c1-52fa-4241-99c8-fa897391344f', '185e51b9-9f65-45f9-92e5-143e11e48ee9', 'ka', 'შრომის კოდექსის 69-ე და 172-ე მუხლების თანახმად, როგორია დასაქმებულის საკუთარი ინიციატივით შრომითი ხელშეკრულების შეწყვეტის წესი?', '["დასაქმებულმა 3 დღით ადრე უნდა გააფრთხილოს ზეპირად", "დასაქმებულმა 2 კვირით ადრე უნდა წარადგინოს შეტყობინება; კომპენსაცია გაიცემა მომდევნო წელს", "შრომითი ხელშეკრულების შეწყვეტა შესაძლებელია მხოლოდ პროფკავშირის თანხმობით", "დასაქმებულს შეუძლია ნებისმიერ დღეს გაფრთხილების გარეშე დატოვოს სამუშაო", "დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი; საბოლოო ანგარიშსწორება ხდება ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღეს არაუგვიანეს"]'::jsonb, 'დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი; საბოლოო ანგარიშსწორება ხდება ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღეს არაუგვიანეს', 'Düzgün cavab: E) დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('837abffe-d476-4474-aee2-28733ea605e9', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Kompüter şəbəkələrinin əhatə dairəsinə görə LAN və WAN şəbəkələrinin başlıca fərqi nədir?', 'multiple_choice', '["LAN şəbəkəsində məlumatlar şifrələnmir, WAN şəbəkəsində isə daxili resurs paylaşımı tam qadağandır", "LAN yalnız dövlət orqanları üçün, WAN isə yalnız fərdi istifadəçilər üçün nəzərdə tutulan şəbəkədir", "LAN yalnız internetə çıxış üçün istifadə olunur, WAN isə lokal fayl və printer mübadiləsini təmin edir", "LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir", "LAN yalnız optik lifli kabellərlə, WAN isə yalnız simsiz Bluetooth ilə qurulur"]'::jsonb, 'LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir', 'Düzgün cavab: D) LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, W', '', 46, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6258f320-a154-4c57-9fe7-8abb51bcb14c', '837abffe-d476-4474-aee2-28733ea605e9', 'ka', 'რა არის ძირითადი განსხვავება LAN და WAN ქსელებს შორის?', '["LAN იგება მხოლოდ ოპტიკურ-ბოჭკოვანი კაბელებით, ხოლო WAN მხოლოდ უსადენო Bluetooth-ით", "LAN განკუთვნილია მხოლოდ სახელმწიფო ორგანოებისთვის, ხოლო WAN მხოლოდ კერძო მომხმარებლებისთვის", "LAN გამოიყენება მხოლოდ ინტერნეტში გასასვლელად, ხოლო WAN უზრუნველყოფს ლოკალურ ფაილთა და პრინტერთა გაზიარებას", "LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებულ კომპიუტერებს, ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს", "LAN ქსელში მონაცემები არ იშიფრება, ხოლო WAN ქსელში შიდა რესურსების გაზიარება სრულიად აკრძალულია"]'::jsonb, 'LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებულ კომპიუტერებს, ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ არეალებს, ქვეყნებსა და კონტინენტებს', 'Düzgün cavab: D) LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებულ კო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('75a54f48-0ede-4999-9651-027cfad41587', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'İnternet şəbəkəsində domen adlarını IP ünvanlarına çevirən əsas xidmət və protokol hansıdır?', 'multiple_choice', '["DHCP (Dynamic Host Configuration Protocol)", "SNMP (Simple Network Management Protocol)", "FTP (File Transfer Protocol)", "DNS (Domain Name System)", "SMTP (Simple Mail Transfer Protocol)"]'::jsonb, 'DNS (Domain Name System)', 'Düzgün cavab: D) DNS (Domain Name System)', '', 47, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1bd119bf-3118-4873-ae77-6ac08de1ac50', '75a54f48-0ede-4999-9651-027cfad41587', 'ka', 'რომელია ძირითადი ქსელური სერვისი, რომელიც დომენურ სახელებს IP მისამართებად გარდაქმნის?', '["SMTP (Simple Mail Transfer Protocol)", "SNMP (Simple Network Management Protocol)", "FTP (File Transfer Protocol)", "DNS (Domain Name System) - დომენური სახელების განაწილებული იერარქიული სისტემა", "DHCP (Dynamic Host Configuration Protocol)"]'::jsonb, 'DNS (Domain Name System) - დომენური სახელების განაწილებული იერარქიული სისტემა', 'Düzgün cavab: D) DNS (Domain Name System) - დომენური სახელების განაწილებული იერარქიული სისტემა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('637d5970-b2c2-428c-9614-8883909e1dc4', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'İnformasiya təhlükəsizliyində ''İki faktorlu autentifikasiya'' (2FA) istifadəsinin başlıca məqsədi nədir?', 'multiple_choice', '["Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək", "İstifadəçiyə eyni vaxtda yalnız bir kompüterdən daxil olmağa məcburi icazə verməsi", "İstifadəçinin daxil etdiyi faylların həcmini avtomatik sıxaraq yaddaşa qənaət etməsi", "Şəbəkə daxilində kompüterin internet sürətini ikiqat artırması", "Əməliyyat sisteminin drayverlərini avtomatik yeniləyərək lisenziya müddətini uzatması"]'::jsonb, 'Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək', 'Düzgün cavab: A) Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifi', '', 48, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ebc1f6c1-66ac-4b8f-9497-a0e6d7f01b36', '637d5970-b2c2-428c-9614-8883909e1dc4', 'ka', 'რა არის ორფაქტორიანი ავთენტიფიკაციის (2FA) მექანიზმის ძირითადი უპირატესობა?', '["პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების (SMS კოდი, ავთენტიფიკატორის აპლიკაცია ან უსაფრთხოების გასაღები) გარეშე", "მომხმარებლის მიერ შეყვანილი ფაილების მოცულობის ავტომატური შეკუმშვა მეხსიერების დაზოგვის მიზნით", "ქსელის შიგნით კომპიუტერის ინტერნეტის სიჩქარის გაორმაგება", "ოპერაციული სისტემის დრაივერების ავტომატური განახლება და ლიცენზიის ვადის გახანგრძლივება", "მომხმარებლისთვის ერთდროულად მხოლოდ ერთი კომპიუტერიდან შესვლის იძულებითი ნებართვა"]'::jsonb, 'პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების (SMS კოდი, ავთენტიფიკატორის აპლიკაცია ან უსაფრთხოების გასაღები) გარეშე', 'Düzgün cavab: A) პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('af061d2f-9617-4ed8-8231-2c90a2604531', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Fırıldaqçıların etibarlı təşkilat adından saxta e-poçt göndərərək istifadəçinin məxfi məlumatlarını ələ keçirməsi hansı kiberhücum növüdür?', 'multiple_choice', '["DDoS (Xidmətdən imtina) hücumu", "Buffer Overflow (Buferin daşması)", "Defragmentasiya hücumu", "Fişinq (Phishing)", "SQL Injection (Məlumat bazasına müdaxilə)"]'::jsonb, 'Fişinq (Phishing)', 'Düzgün cavab: D) Fişinq (Phishing)', '', 49, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('eeef3791-c1f1-435c-98b4-915713e364d4', 'af061d2f-9617-4ed8-8231-2c90a2604531', 'ka', 'კიბერშეტევის რომელ სახეობას მიეკუთვნება შემთხვევა, როდესაც თაღლითები სანდო ორგანიზაციის სახელით აგზავნიან ყალბ ელფოსტას და ითვისებენ მონაცემებს?', '["დეფრაგმენტაციის შეტევა", "Buffer Overflow (ბუფერის გადავსება)", "DDoS (მომსახურებაზე უარის თქმის შეტევა)", "ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) - საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტის მეშვეობით", "SQL Injection (მონაცემთა ბაზაში შეღწევა)"]'::jsonb, 'ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) - საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტის მეშვეობით', 'Düzgün cavab: D) ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) - საიდენტიფიკაციო მონაცემების მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6880e3b8-d07f-494f-8a70-82fcb24fdfdd', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Microsoft Word proqramında abzasın girintilərini dəqiq vizual tənzimləmək üçün hansı elementdən istifadə olunur?', 'multiple_choice', '["Vəziyyət zolağı (Status Bar)", "Sənədin miqyas sürüşdürücüsü (Zoom Slider)", "Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi", "Sürətli müraciət paneli (Quick Access Toolbar)", "Naviqasiya paneli (Navigation Pane)"]'::jsonb, 'Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi', 'Düzgün cavab: C) Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph', '', 50, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('262528bf-3eaf-49f3-b61a-4c63f15c0bb3', '6880e3b8-d07f-494f-8a70-82fcb24fdfdd', 'ka', 'Word-ში რომელი ელემენტი გამოიყენება აბზაცის შეწევების ზუსტი ვიზუალური რეგულირებისთვის?', '["ნავიგაციის პანელი (Navigation Pane)", "სტატუსის ზოლი (Status Bar)", "ჰორიზონტალურ სახაზავზე (Horizontal Ruler) განთავსებული მცოცავები (First Line, Hanging, Left/Right) და Paragraph დიალოგური ფანჯარა", "სწრაფი წვდომის პანელი (Quick Access Toolbar)", "დოკუმენტის მასშტაბის მცოცავი (Zoom Slider)"]'::jsonb, 'ჰორიზონტალურ სახაზავზე (Horizontal Ruler) განთავსებული მცოცავები (First Line, Hanging, Left/Right) და Paragraph დიალოგური ფანჯარა', 'Düzgün cavab: C) ჰორიზონტალურ სახაზავზე (Horizontal Ruler) განთავსებული მცოცავები (First Line, Ha', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c856c26a-d662-4b5a-ae0d-d27ee3d72710', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Microsoft Word sənədində bəzi səhifələri şaquli, bəzi səhifələri isə üfüqi (albom) etmək üçün hansı əməliyyat icra olunmalıdır?', 'multiple_choice', '["Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir", "Səhifələrin arasına adi səhifə kəsilməsi (Page Break) əlavə edilməlidir", "Sənəd mütləq PDF formatında yadda saxlanılmalıdır", "Mətnin şrift ölçüsü 10 pt səviyyəsinə endirilməlidir", "Bütün sənəd üçün vahid cədvəl şablonu tətbiq olunmalıdır"]'::jsonb, 'Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir', 'Düzgün cavab: A) Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin O', '', 51, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('69501817-cd14-4aad-ac55-8fee54ec9d6a', 'c856c26a-d662-4b5a-ae0d-d27ee3d72710', 'ka', 'რა ოპერაცია უნდა შესრულდეს Word-ის დოკუმენტში ზოგიერთი გვერდის ვერტიკალური (წიგნისებრი), ხოლო ზოგიერთის ჰორიზონტალური (ალბომური) ორიენტაციით დასაფორმატებლად?', '["დოკუმენტში სექციის წყვეტის (Section Break / Next Page) ჩამატება და ამ სექციის ორიენტაციის შეცვლა", "ტექსტის შრიფტის ზომის 10 pt დონემდე შემცირება", "გვერდებს შორის ჩვეულებრივი გვერდის წყვეტის (Page Break) დამატება", "დოკუმენტის აუცილებლად PDF ფორმატში შენახვა", "მთელი დოკუმენტისთვის ცხრილის ერთიანი შაბლონის გამოყენება"]'::jsonb, 'დოკუმენტში სექციის წყვეტის (Section Break / Next Page) ჩამატება და ამ სექციის ორიენტაციის შეცვლა', 'Düzgün cavab: A) დოკუმენტში სექციის წყვეტის (Section Break / Next Page) ჩამატება და ამ სექციის ორ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('394597a3-6f9e-4dd9-9626-1e5e43163c5b', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Microsoft Word proqramında başlıqlara əsasən avtomatik yenilənən Mündəricat yaratmaq üçün hansı taba müraciət edilir?', 'multiple_choice', '["Design (Dizayn)", "Mailings (Göndərişlər)", "Layout (Səhifə düzəni)", "Review (İcmal)", "References (İstinadlar) tabı > Table of Contents qrupu"]'::jsonb, 'References (İstinadlar) tabı > Table of Contents qrupu', 'Düzgün cavab: E) References (İstinadlar) tabı > Table of Contents qrupu', '', 52, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2884b338-dbc6-4ae3-b016-af23ee533223', '394597a3-6f9e-4dd9-9626-1e5e43163c5b', 'ka', 'რომელ ჩანართს (Tab) უნდა მივმართოთ Word-ში სათაურების საფუძველზე ავტომატურად განახლებადი სარჩევის შესაქმნელად?', '["Design (დიზაინი)", "Review (განხილვა / რეცენზირება)", "Mailings (გზავნილები)", "Layout (გვერდის განლაგება)", "References (მითითებები / სქოლიო) ჩანართი > Table of Contents ჯგუფი"]'::jsonb, 'References (მითითებები / სქოლიო) ჩანართი > Table of Contents ჯგუფი', 'Düzgün cavab: E) References (მითითებები / სქოლიო) ჩანართი > Table of Contents ჯგუფი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c91245c1-b1d0-4328-aff0-910a13545971', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Microsoft Excel cədvəlində `$C$2` mütləq xana ünvanı olan düstur başqa xanalara kopyalandıqda necə dəyişir?', 'multiple_choice', '["Düstur avtomatik olaraq sıfır qiyməti qaytarır", "Yalnız sütun adı sabit qalır, sətir nömrəsi isə aşağı kopyalandıqca artır", "Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır", "Yalnız sətir nömrəsi sabit qalır, sütun hərfi isə sağa kopyalandıqca dəyişir", "Həm sütun (C), həm də sətir (2) indeksi kopyalanan istiqamətə uyğun avtomatik sürüşür"]'::jsonb, 'Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', 'Düzgün cavab: C) Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', '', 53, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('da6f5ec5-3f6a-439d-80c0-cd4c3b0c93df', 'c91245c1-b1d0-4328-aff0-910a13545971', 'ka', 'როგორ შეიცვლება Excel-ის ცხრილში ფორმულა, რომელიც შეიცავს უჯრის აბსოლუტურ მისამართს $C$2, როდესაც ის სხვა უჯრებში კოპირდება?', '["მხოლოდ სვეტის სახელი დარჩება უცვლელი, ხოლო სტრიქონის ნომერი ქვემოთ კოპირებისას გაიზრდება", "როგორც სვეტის (C), ისე სტრიქონის (2) ინდექსი ავტომატურად გადაადგილდება კოპირების მიმართულების შესაბამისად", "ვინაიდან დოლარის ნიშანი $ ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკომპლექტდეს/დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური მიმართვა)", "მხოლოდ სტრიქონის ნომერი დარჩება უცვლელი, ხოლო სვეტის ასო შეიცვლება მარჯვნივ კოპირებისას", "ფორმულა ავტომატურად დააბრუნებს ნულოვან მნიშვნელობას"]'::jsonb, 'ვინაიდან დოლარის ნიშანი $ ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკომპლექტდეს/დაკოპირდეს ფორმულა, უჯრის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური მიმართვა)', 'Düzgün cavab: C) ვინაიდან დოლარის ნიშანი $ ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკომპლექტდეს/დ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('90abbca5-c53d-452a-9e64-9504c0074ba6', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Microsoft Excel proqramında `A1:A10` diapazonunda yalnız qiyməti 50-dən böyük olan xanaların sayını hesablamaq üçün hansı funksiya düzgündür?', 'multiple_choice', '["=SUM(A1:A10; \">50\")", "=COUNTIF(A1:A10; \">50\")", "=COUNT(A1:A10; >50)", "=AVERAGEIF(A1:A10; 50)", "=COUNTA(A1:A10; 50)"]'::jsonb, '=COUNTIF(A1:A10; ">50")', 'Düzgün cavab: B) =COUNTIF(A1:A10; ">50")', '', 54, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4a8ff6ce-dba8-4cd1-a8d9-01eb61ad3acb', '90abbca5-c53d-452a-9e64-9504c0074ba6', 'ka', 'Excel-ში A1:A10 დიაპაზონში მხოლოდ იმ უჯრების რაოდენობის დასათვლელად, რომელთა მნიშვნელობა 50-ზე მეტია, რომელი ფუნქციაა სწორი?', '["=SUM(A1:A10; \">50\") - პირობითი ჯამის ფუნქცია", "=COUNTIF(A1:A10;\">50\") - პირობითი დათვლის ფუნქცია", "=COUNT(A1:A10; >50) - სინტაქსური შეცდომაა", "=COUNTA(A1:A10; 50) - შევსებული უჯრების რაოდენობა", "=AVERAGEIF(A1:A10; 50) - საშუალო მნიშვნელობის ფუნქცია"]'::jsonb, '=COUNTIF(A1:A10;">50") - პირობითი დათვლის ფუნქცია', 'Düzgün cavab: B) =COUNTIF(A1:A10;">50") - პირობითი დათვლის ფუნქცია', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('00ac9f57-aa28-4acc-bc31-20b496da3e53', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Microsoft Excel-də B2 xanasındakı əməkhaqqı 800-dən çox olduqda 15% mükafat, əks halda 5% hesablayan düstur hansıdır?', 'multiple_choice', '["=VLOOKUP(B2; 800; 15; 5)", "=SUMIF(B2>800; B2*15%; B2*5%)", "=MAX(B2>800; 0.15; 0.05)", "=IF(B2>800; B2*0.15; B2*0.05)", "=COUNTIF(B2; 800; 15%)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: D) =IF(B2>800; B2*0.15; B2*0.05)', '', 55, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6309d768-ef27-4b1b-8d1d-f7a65290685c', '00ac9f57-aa28-4acc-bc31-20b496da3e53', 'ka', 'რომელია ის ფორმულა Excel-ში, რომელიც ითვლის 15%-იან პრემიას, როდესაც B2 უჯრაში ხელფასი 800-ზე მეტია?', '["=MAX(B2>800; 0.15; 0.05) - მაქსიმუმის ფუნქცია", "=VLOOKUP(B2; 800; 15; 5) - ძიების ფუნქცია", "=SUMIF(B2>800; B2*15%; B2*5%) - პირობითი ჯამი", "=IF(B2>800; B2*0.15; B2*0.05) - ლოგიკური IF ფუნქციით", "=COUNTIF(B2; 800; 15%) - დათვლის ფუნქცია"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05) - ლოგიკური IF ფუნქციით', 'Düzgün cavab: D) =IF(B2>800; B2*0.15; B2*0.05) - ლოგიკური IF ფუნქციით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('89b798d6-44c8-4843-a483-a2a05cbf71b9', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Microsoft Excel proqramında xanaya yalnız müəyyən diapazonda ədədlərin daxil edilməsinə icazə verən alət hansıdır?', 'multiple_choice', '["Text to Columns (Mətnin sütunlara bölünməsi)", "Data Validation (Verilənlərin yoxlanılması)", "Flash Fill (Sürətli doldurma)", "Conditional Formatting (Şərti formatlaşdırma)", "Remove Duplicates (Təkrarların silinməsi)"]'::jsonb, 'Data Validation (Verilənlərin yoxlanılması)', 'Düzgün cavab: B) Data Validation (Verilənlərin yoxlanılması)', '', 56, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e3cae973-cbdb-4512-a13b-d826ac02f5ba', '89b798d6-44c8-4843-a483-a2a05cbf71b9', 'ka', 'Excel-ში რომელი ინსტრუმენტი იძლევა საშუალებას, უჯრაში დაშვებულ იქნეს რიცხვების შეყვანა მხოლოდ განსაზღვრულ დიაპაზონში?', '["Remove Duplicates (დუბლიკატების წაშლა)", "Data Validation (მონაცემთა შემოწმება/ვალიდაცია) - Data ჩანართში Whole Number, Decimal, List, Date კრიტერიუმებით", "Flash Fill (მყისიერი შევსება) - ავტომატური შევსება", "Text to Columns (ტექსტის სვეტებად დაყოფა)", "Conditional Formatting (პირობითი ფორმატირება) - ვიზუალური გამოკვეთა"]'::jsonb, 'Data Validation (მონაცემთა შემოწმება/ვალიდაცია) - Data ჩანართში Whole Number, Decimal, List, Date კრიტერიუმებით', 'Düzgün cavab: B) Data Validation (მონაცემთა შემოწმება/ვალიდაცია) - Data ჩანართში Whole Number, De', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('00c9bba5-fd7b-49ea-b88a-28251595b14e', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Microsoft PowerPoint proqramında bütün slaydların vahid dizayn şablonunu dəyişmək üçün hansı rejimdən istifadə olunur?', 'multiple_choice', '["Slide Sorter (Slayd çeşidləyicisi)", "Reading View (Oxu rejimi)", "Slide Master (Slayd Ustası)", "Custom Animation (Fərdi animasiya)", "Presenter View (Aparıcı görünüşü)"]'::jsonb, 'Slide Master (Slayd Ustası)', 'Düzgün cavab: C) Slide Master (Slayd Ustası)', '', 57, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('19f44cf7-5a5c-4b00-a636-8e34d2a12fcf', '00c9bba5-fd7b-49ea-b88a-28251595b14e', 'ka', 'PowerPoint-ში რომელი რეჟიმი გამოიყენება ყველა სლაიდის ერთიანი დიზაინის შაბლონის შესაცვლელად?', '["Slide Sorter (სლაიდების დამხარისხებელი) - დახარისხების რეჟიმი", "Reading View (კითხვის რეჟიმი)", "Slide Master (სლაიდების ნიმუში / Образец слайдов) - View ჩანართში Master Views ჯგუფი", "Custom Animation (მორგებული ანიმაცია) - ანიმაციის რეჟიმი", "Presenter View (მომხსენებლის ხედი) - პრეზენტატორის რეჟიმი"]'::jsonb, 'Slide Master (სლაიდების ნიმუში / Образец слайдов) - View ჩანართში Master Views ჯგუფი', 'Düzgün cavab: C) Slide Master (სლაიდების ნიმუში / Образец слайдов) - View ჩანართში Master Views ჯ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4bf17949-38a9-454f-80aa-b5d83df0ffdf', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Microsoft PowerPoint-də ''Transition'' ilə ''Animation'' arasındakı əsas fərq nədir?', 'multiple_choice', '["Hər iki anlayış eyni funksiyanı icra edir", "Transition yalnız kompüter sönərkən işləyir, Animation çap zamanı aktivləşir", "Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir", "Transition yalnız mətnlərə tətbiq olunur, Animation yalnız video faylları nümayiş etdirir", "Transition slaydın arxa fon rəngini dəyişir, Animation slaydın vaxtını tənzimləyir"]'::jsonb, 'Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir', 'Düzgün cavab: C) Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation i', '', 58, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('353e815b-92a2-4d53-99c2-75b4eb978fd6', '4bf17949-38a9-454f-80aa-b5d83df0ffdf', 'ka', 'რა არის ძირითადი განსხვავება PowerPoint-ში ''Transition''-სა და ''Animation''-ს შორის?', '["Transition გამოიყენება მხოლოდ ტექსტებისთვის, Animation კი მხოლოდ ვიდეოფაილებს უჩვენებს", "Transition ცვლის სლაიდის ფონის ფერს, Animation კი არეგულირებს სლაიდის დროს", "Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორე სლაიდზე გადასვლისას, ხოლო Animation არის უშუალოდ სლაიდის შიგნით არსებული კონკრეტული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი", "Transition მუშაობს მხოლოდ კომპიუტერის გამორთვისას, Animation კი აქტიურდება ბეჭდვის დროს", "ორივე ცნება ერთსა და იმავე ფუნქციას ასრულებს"]'::jsonb, 'Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორე სლაიდზე გადასვლისას, ხოლო Animation არის უშუალოდ სლაიდის შიგნით არსებული კონკრეტული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი', 'Düzgün cavab: C) Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორე სლაიდზე გადასვლისას, ხოლო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8b10daa7-4427-439d-a212-82dfe58859bf', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Bulud saxlama xidmətlərində sənəd üzərində birgə işləyərkən əvvəlki versiyalara qayıtmaq üçün hansı funksiyadan istifadə olunur?', 'multiple_choice', '["Task Manager (Tapşırıqlar meneceri)", "Version History (Versiya tarixçəsi)", "Disk Cleanup (Diskin təmizlənməsi)", "Defragmentation (Defragmentasiya)", "Registry Editor (Reyestr redaktoru)"]'::jsonb, 'Version History (Versiya tarixçəsi)', 'Düzgün cavab: B) Version History (Versiya tarixçəsi)', '', 59, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('acbcb911-c582-4842-9d4b-5eda5e7830f8', '8b10daa7-4427-439d-a212-82dfe58859bf', 'ka', 'ღრუბლოვანი შენახვის სერვისებში დოკუმენტის წინა ვერსიებზე დასაბრუნებლად რომელი ფუნქცია გამოიყენება?', '["Task Manager (დავალებათა მენეჯერი) - მართავს პროცესებს", "Version History (ვერსიების ისტორია) - File > Info > Version History ან ისტორია OneDrive/SharePoint-ში", "Defragmentation (დეფრაგმენტაცია) - ახდენს დისკის ოპტიმიზაციას", "Disk Cleanup (დისკის გასუფთავება) - შლის დროებით ფაილებს", "Registry Editor (რეესტრის რედაქტორი) - ასწორებს რეესტრს"]'::jsonb, 'Version History (ვერსიების ისტორია) - File > Info > Version History ან ისტორია OneDrive/SharePoint-ში', 'Düzgün cavab: B) Version History (ვერსიების ისტორია) - File > Info > Version History ან ისტორია O', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9a2eb10c-a4c6-4904-b7af-d21c257c8e16', '0d80fe94-6f97-4552-86f3-825d1ba268e0', 'Süni intellekt əsaslı generativ modellərdə ''Hallüsinasiya'' riski nəyi ifadə edir?', 'multiple_choice', '["Süni intellektin bütün istifadəçi parollarını avtomatik silməsini", "Modelin internet şəbəkəsini həddindən artıq yükləyərək kompüteri dondurmasını", "Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini", "Süni intellektin kompüterin aparat hissələrini sıradan çıxarmasını", "Modelin yalnız xarici dillərdə işləyərək Azərbaycan dilini dəstəkləməməsini"]'::jsonb, 'Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini', 'Düzgün cavab: C) Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadl', '', 60, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('289e2e90-fb0e-4d3b-9dfe-614d696268ff', '9a2eb10c-a4c6-4904-b7af-d21c257c8e16', 'ka', 'რას გამოხატავს ხელოვნურ ინტელექტში „ჰალუცინაციის“ (Hallucination) რისკი?', '["მოდელის მუშაობას მხოლოდ უცხო ენებზე და მის მიერ ქართული ენის მხარდაჭერის არარსებობას", "ხელოვნური ინტელექტის მიერ კომპიუტერის აპარატურული ნაწილების მწყობრიდან გამოყვანას", "მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და წყაროების სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით გენერირებას", "ხელოვნური ინტელექტის მიერ ყველა მომხმარებლის პაროლის ავტომატურ წაშლას", "მოდელის მიერ ინტერნეტქსელის გადატვირთვასა და კომპიუტერის გაყინვას"]'::jsonb, 'მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და წყაროების სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით გენერირებას', 'Düzgün cavab: C) მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და წყაროე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d37b44bb-7e1f-43b7-8955-022ed157e6ef', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Ümumi təhsil müəssisəsində Təsərrüfat müdirinin əsas xidməti vəzifə öhdəliyi hansıdır?', 'multiple_choice', '["Fənn laboratoriyalarında praktiki məşğələlərin icra vəziyyətinə rəhbərlik etmək", "Məktəb binasının, kommunal şəbəkələrin (istilik, su, elektrik), həyətin, mebel və inventarların sazlığını təmin etmək, anbar uçotunu aparmaq və təsərrüfat heyətinin işini təşkil etmək", "Təhsilalanların akademik nailiyyətlərini və summativ qiymətləndirmə nəticələrini təhlil etmək", "Məktəbin kargüzarlıq sənəd dövriyyəsini və rəsmi dövlət statistik hesabatlarını formalaşdırmaq", "Müəssisənin tədris-metodiki işlərini tənzimləmək, dərs cədvəlini və hesabatları təsdiqləmək"]'::jsonb, 'Məktəb binasının, kommunal şəbəkələrin (istilik, su, elektrik), həyətin, mebel və inventarların sazlığını təmin etmək, anbar uçotunu aparmaq və təsərrüfat heyətinin işini təşkil etmək', 'Düzgün cavab: B) Məktəb binasının, kommunal şəbəkələrin (istilik, su, elektrik), həyətin, mebel v', '', 1, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a3a9b233-8cab-4d82-bd2b-22383f01b47f', 'd37b44bb-7e1f-43b7-8955-022ed157e6ef', 'ka', 'ზოგადსაგანმანათლებლო დაწესებულებაში რა წარმოადგენს სამეურნეო ნაწილის გამგის ძირითად სამსახურებრივ მოვალეობას?', '["მოსწავლეთა აკადემიური მიღწევებისა და შემაჯამებელი შეფასების შედეგების ანალიზი", "სკოლის შენობის, კომუნალური ქსელების (გათბობა, წყალი, ელექტროენერგია), ეზოს, ავეჯისა და ინვენტარის გამართულობის უზრუნველყოფა, სასაწყობო აღრიცხვის წარმოება და სამეურნეო პერსონალის მუშაობის ორგანიზება", "საგნობრივ ლაბორატორიებში პრაქტიკული მეცადინეობების ჩატარების ხელმძღვანელობა", "სკოლის საქმისწარმოების დოკუმენტბრუნვისა და ოფიციალური სახელმწიფო სტატისტიკური ანგარიშგების ფორმირება", "დაწესებულების სასწავლო-მეთოდური მუშაობის რეგულირება, გაკვეთილების ცხრილისა და ანგარიშების დამტკიცება"]'::jsonb, 'სკოლის შენობის, კომუნალური ქსელების (გათბობა, წყალი, ელექტროენერგია), ეზოს, ავეჯისა და ინვენტარის გამართულობის უზრუნველყოფა, სასაწყობო აღრიცხვის წარმოება და სამეურნეო პერსონალის მუშაობის ორგანიზება', 'Düzgün cavab: B) სკოლის შენობის, კომუნალური ქსელების (გათბობა, წყალი, ელექტროენერგია), ეზოს, ავეჯ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6e06b416-880e-4f8f-87d9-f7076fbf6f72', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb təsərrüfatında olan bütün əsas vəsaitlərin rəsmi uçotu və maddi məsuliyyəti necə müəyyən edilir?', 'multiple_choice', '["Əsas vəsaitlərin uçotu yalnız yerli bələdiyyə orqanının balans arayışı ilə aparılır", "Təsərrüfat malları müəssisə rəhbərinin fərdi sərəncamı ilə hər rüb yenidən nömrələnmədən silinir", "Əmlak yalnız tədris ilinin əvvəlində sinif rəhbərləri arasında şifahi razılaşma ilə bölüşdürülür", "Maddi-məsul şəxslə tam fərdi maddi məsuliyyət müqaviləsi bağlanır, əmlak inventar kitabında, cəmi uçot kitabında qeydiyyata alınır və balansda əks olunur", "Həmkarlar İttifaqı Komitəsinin qərarı ilə əmlak kollektivin ümumi istifadəsinə verilir"]'::jsonb, 'Maddi-məsul şəxslə tam fərdi maddi məsuliyyət müqaviləsi bağlanır, əmlak inventar kitabında, cəmi uçot kitabında qeydiyyata alınır və balansda əks olunur', 'Düzgün cavab: D) Maddi-məsul şəxslə tam fərdi maddi məsuliyyət müqaviləsi bağlanır, əmlak inventa', '', 2, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8df34490-7476-44d2-b43b-2a490bee1a5f', '6e06b416-880e-4f8f-87d9-f7076fbf6f72', 'ka', 'როგორ განისაზღვრება სკოლის მეურნეობაში არსებული ყველა ძირითადი საშუალების ოფიციალური აღრიცხვა და მატერიალური პასუხისმგებლობა?', '["ძირითადი საშუალებების აღრიცხვა ხორციელდება მხოლოდ ადგილობრივი თვითმმართველობის ორგანოს საბალანსო ცნობით", "სამეურნეო საქონელი დაწესებულების ხელმძღვანელის ინდივიდუალური განკარგულებით ყოველ კვარტალში ჩამოიწერება ხელახალი დანომრვის გარეშე", "ქონება მხოლოდ სასწავლო წლის დასაწყისში ნაწილდება კლასის დამრიგებლებს შორის ზეპირი შეთანხმებით", "მატერიალურად პასუხისმგებელ პირთან იდება სრული ინდივიდუალური მატერიალური პასუხისმგებლობის ხელშეკრულება, ქონება რეგისტრირდება საინვენტარო წიგნში, საერთო სააღრიცხვო წიგნში და აისახება ბალანსზე", "პროფკავშირის კომიტეტის გადაწყვეტილებით ქონება გადაეცემა კოლექტივს საერთო სარგებლობაში"]'::jsonb, 'მატერიალურად პასუხისმგებელ პირთან იდება სრული ინდივიდუალური მატერიალური პასუხისმგებლობის ხელშეკრულება, ქონება რეგისტრირდება საინვენტარო წიგნში, საერთო სააღრიცხვო წიგნში და აისახება ბალანსზე', 'Düzgün cavab: D) მატერიალურად პასუხისმგებელ პირთან იდება სრული ინდივიდუალური მატერიალური პასუხისმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0682caa5-a582-4c95-8375-4333d115c7f6', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təhsil müəssisəsində illik inventarizasiya zamanı hansı əsas vəzifə icra olunur?', 'multiple_choice', '["Fənn müəllimlərinin dərs yükünün normativlərə uyğun bölüşdürülməsini təsdiq etmək", "Müəssisənin illik tədris planlarının və dərnək proqramlarının icra vəziyyətini yoxlamaq", "Pedaqoji kollektivin fərdi əməkhaqqı dərəcələrini və tarif dərəcələrinin uyğunluğunu dəqiqləşdirmək", "Şagirdlərin dərsdənkənar mütaliə səviyyəsinin statistik göstəricilərini toplamaq", "Faktiki mövcud olan bütün bina, qurğu, inventar, avadanlıq və materialların sayılması, texniki vəziyyətinin, artıq və əskiklərin müəyyən edilərək sənədləşdirilməsi"]'::jsonb, 'Faktiki mövcud olan bütün bina, qurğu, inventar, avadanlıq və materialların sayılması, texniki vəziyyətinin, artıq və əskiklərin müəyyən edilərək sənədləşdirilməsi', 'Düzgün cavab: E) Faktiki mövcud olan bütün bina, qurğu, inventar, avadanlıq və materialların sayı', '', 3, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('427c5358-789b-480a-ba1b-d532bc79aa50', '0682caa5-a582-4c95-8375-4333d115c7f6', 'ka', 'რა ძირითადი ამოცანა სრულდება საგანმანათლებლო დაწესებულებაში წლიური ინვენტარიზაციის დროს?', '["პედაგოგიური კოლექტივის ინდივიდუალური ხელფასის კატეგორიებისა და სატარიფო განაკვეთების შესაბამისობის დაზუსტება", "დაწესებულების წლიური სასწავლო გეგმებისა და წრეების პროგრამების შესრულების მდგომარეობის შემოწმება", "სკოლის საბიბლიოთეკო ფონდის პერიოდული პრესისა და მხატვრული ლიტერატურის მარაგის გადაფასება", "მოსწავლეთა მიერ სასკოლო სახელმძღვანელოებითა და ლაბორატორიული უსაფრთხოების წესების დაცვის შეფასება", "ფაქტობრივად არსებული ძირითადი საშუალებების, ინვენტარისა და მატერიალური მარაგების შედარება საბუღალტრო აღრიცხვასა და საინვენტარო წიგნებთან, ზედმეტობის ან დანაკლისის, დანაკარგების გამოვლენა და აქტის შედგენა"]'::jsonb, 'ფაქტობრივად არსებული ძირითადი საშუალებების, ინვენტარისა და მატერიალური მარაგების შედარება საბუღალტრო აღრიცხვასა და საინვენტარო წიგნებთან, ზედმეტობის ან დანაკლისის, დანაკარგების გამოვლენა და აქტის შედგენა', 'Düzgün cavab: E) ფაქტობრივად არსებული ძირითადი საშუალებების, ინვენტარისა და მატერიალური მარაგების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4ebc8aeb-39bf-456f-ac37-83200bfac62e', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'İstismara yararsız, fiziki köhnəlmiş və ya tam sıradan çıxmış məktəb inventarlarının silinməsi (ləğvi) hansı qaydada aparılır?', 'multiple_choice', '["Köhnəlmiş mebellərin dərhal kənar şəxslərə pulsuz paylanması yolu ilə", "Direktorun əmri ilə yaradılmış xüsusi ləğvetmə komissiyası tərəfindən qüsur aktı tərtib edilir, yuxarı idarəetmə orqanının razılığı ilə silinmə aktı rəsmiləşdirilir", "Əmlakın silinməsi yalnız şagird valideynlərinin şifahi razılığı əsasında aparılır", "İnventarların silinməsi yalnız yerli icra hakimiyyətinin şifahi göstərişi ilə icra olunur", "Təsərrüfat müdirinin heç bir akt tərtib etmədən inventarları zibilxanaya atması ilə"]'::jsonb, 'Direktorun əmri ilə yaradılmış xüsusi ləğvetmə komissiyası tərəfindən qüsur aktı tərtib edilir, yuxarı idarəetmə orqanının razılığı ilə silinmə aktı rəsmiləşdirilir', 'Düzgün cavab: B) Direktorun əmri ilə yaradılmış xüsusi ləğvetmə komissiyası tərəfindən qüsur aktı', '', 4, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('17ec8436-b16d-4805-befe-eed1e79b9620', '4ebc8aeb-39bf-456f-ac37-83200bfac62e', 'ka', 'სკოლის შენობაში გათბობის სეზონისთვის მომზადების ფარგლებში რა საინჟინრო-ტექნიკური ღონისძიებები უნდა განახორციელოს სამეურნეო ნაწილის გამგემ?', '["გათბობის რადიატორების მარეგულირებელი ვენტილების დემონტაჟი და საწყობში სათადარიგო ნაწილებად შენახვა", "საქვაბის მოწყობილობების, მილსადენებისა და რადიატორების წნევით (ჰიდრავლიკური გამოცდა) შემოწმება, გარეცხვა, გამართვა, ვენტილების შემოწმება და სისტემის გამართულობისა და იზოლაციის უზრუნველყოფა", "ფანჯრებისა და კარების ყველა კონსტრუქციის მოხსნა შიდა ოთახებში მუდმივი ვენტილაციის შესაქმნელად", "გათბობის უზრუნველყოფა მხოლოდ საკლასო ოთახებში ღია სპირალის ტიპის ელექტროქურების დამონტაჟებით", "გათბობის სისტემის წყლისა და გაზის ხაზების დაკეტვა მთელი ზამთრის განმავლობაში და ინდივიდუალური გამათბობლების გამოყენება"]'::jsonb, 'საქვაბის მოწყობილობების, მილსადენებისა და რადიატორების წნევით (ჰიდრავლიკური გამოცდა) შემოწმება, გარეცხვა, გამართვა, ვენტილების შემოწმება და სისტემის გამართულობისა და იზოლაციის უზრუნველყოფა', 'Düzgün cavab: B) საქვაბის მოწყობილობების, მილსადენებისა და რადიატორების წნევით (ჰიდრავლიკური გამო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a6817f83-48a3-4e59-b692-c5381c3b49b1', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb binasında yanğın təhlükəsizliyinin təmin olunması üzrə təsərrüfat müdirinin cavabdeh olduğu sahəyə hansı **AİD DEYİLDİR?**', 'multiple_choice', '["Təsərrüfat və xidmətedici heyət üçün yanğın təhlükəsizliyi üzrə ilkin təlimatlandırmanın keçirilməsi", "Fənn müəllimlərinin dərs jurnallarında yanğın təhlükəsizliyi qaydalarının illik akademik qiymətləndirməsini aparmaq", "Təxliyə yollarının, qəza çıxışlarının və pilləkən qəfəslərinin daimi sərbəst və açıq olmasının təmini", "Yanğın xəbərdarlıq sistemlərinin və yanğın kranlarının sazlığının yoxlanılması", "İlkin odsöndürmə vasitələrinin (odsöndürənlər, qum yeşikləri, yanğın şlanqları) saz vəziyyətdə saxlanması"]'::jsonb, 'Fənn müəllimlərinin dərs jurnallarında yanğın təhlükəsizliyi qaydalarının illik akademik qiymətləndirməsini aparmaq', 'Düzgün cavab: B) Fənn müəllimlərinin dərs jurnallarında yanğın təhlükəsizliyi qaydalarının illik', '', 5, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('31ce8e38-ae48-43f2-9275-aa6120002ae3', 'a6817f83-48a3-4e59-b692-c5381c3b49b1', 'ka', 'სკოლის შენობაში ხანძარსაწინააღმდეგო უსაფრთხოების უზრუნველყოფის კუთხით, რომელი არ განეკუთვნება სამეურნეო ნაწილის გამგის პასუხისმგებლობის სფეროს?', '["სათადარიგო საევაკუაციო გასასვლელი კარებისა და დერეფნების თავისუფალ, შეუფერხებელ მდგომარეობაში შენარჩუნება", "სათადარიგო საევაკუაციო კიბეებისა და გასასვლელი გზების ძველი მერხებით, გატეხილი ავეჯითა და სამშენებლო მასალებით ჩახერგვა და დაკეტვა (აკრძალულია)", "პირველადი ხანძარსაწინააღმდეგო საშუალებების გამართულ მდგომარეობაში შენარჩუნება და დროული ხელახალი დატენვა", "ხანძარსაწინააღმდეგო ავტომატური სიგნალიზაციისა და სახანძრო ონკანების სისტემების მუშა მდგომარეობაში შენარჩუნება", "შენობის სართულებზე ევაკუაციის გეგმების თვალსაჩინო ადგილებში განთავსების უზრუნველყოფა"]'::jsonb, 'სათადარიგო საევაკუაციო კიბეებისა და გასასვლელი გზების ძველი მერხებით, გატეხილი ავეჯითა და სამშენებლო მასალებით ჩახერგვა და დაკეტვა (აკრძალულია)', 'Düzgün cavab: B) სათადარიგო საევაკუაციო კიბეებისა და გასასვლელი გზების ძველი მერხებით, გატეხილი ა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('cc6ac92e-e4f6-44cb-97f4-0ec1b307760b', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'İlkin odsöndürmə vasitəsi olan karbon qazlı və tozlu odsöndürənlərin texniki sazlığına nəzarət necə həyata keçirilir?', 'multiple_choice', '["Manometrin təzyiq göstəricisi yoxlanılır (yaşıl zonada olmalı), plombun bütövlüyü, yararlılıq müddəti və pasport məlumatları xüsusi jurnalda qeydiyyata alınır", "Odsöndürənlər hər ay boşaldılaraq yenidən su ilə doldurulur", "Təzyiq göstəricisi yoxlanılmadan odsöndürənlər açıq günəş altında saxlanılır", "Odsöndürən balonların manometri çıxarılaraq birbaşa təzyiq altında saxlanılır", "Odsöndürənlərin sazlığı yalnız yanğın baş verdikdən sonra sınaqdan keçirilir"]'::jsonb, 'Manometrin təzyiq göstəricisi yoxlanılır (yaşıl zonada olmalı), plombun bütövlüyü, yararlılıq müddəti və pasport məlumatları xüsusi jurnalda qeydiyyata alınır', 'Düzgün cavab: A) Manometrin təzyiq göstəricisi yoxlanılır (yaşıl zonada olmalı), plombun bütövlüy', '', 6, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0f8371a8-ac3f-4aa7-bc5d-bebd54988ae6', 'cc6ac92e-e4f6-44cb-97f4-0ec1b307760b', 'ka', 'სკოლის საქვაბეში გაზზე მომუშავე ქვაბების ექსპლუატაციის დროს რომელი მოთხოვნა ითვლება დარღვევად?', '["საქვაბის ოპერატორების დაშვება ქვაბის მართვაზე სპეციალური უსაფრთხოების ინსტრუქტაჟის, ატესტაციისა და მოწმობის გარეშე, სამედიცინო შემოწმების გავლის გარეშე", "საქვაბის შესასვლელ კარზე გარეშე პირთა შესვლის ამკრძალავი აბრის განთავსება", "საქვაბის შიგნით ბუნებრივი და ხელოვნური ვენტილაციის არხების მუდმივად ღია მდგომარეობაში შენარჩუნება", "წნევის მანომეტრებისა და დამცავი სარქველების რეგულარული მეტროლოგიური შემოწმება", "გაზის გაჟონვის მაუწყებელი გაზანალიზატორ-დეტექტორებისა და ავარიული სარქველების გამართულ მდგომარეობაში შენარჩუნება"]'::jsonb, 'საქვაბის ოპერატორების დაშვება ქვაბის მართვაზე სპეციალური უსაფრთხოების ინსტრუქტაჟის, ატესტაციისა და მოწმობის გარეშე, სამედიცინო შემოწმების გავლის გარეშე', 'Düzgün cavab: A) საქვაბის ოპერატორების დაშვება ქვაბის მართვაზე სპეციალური უსაფრთხოების ინსტრუქტაჟ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0ec19df5-05b8-4d2f-bee8-9c32fb1f45a1', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəbin istilik qazanxanasının qış mövsümünə hazırlanmasında təsərrüfat müdirinin əsas vəzifəsi nədir?', 'multiple_choice', '["Qazanxananın bütün texniki təlimatlarını ləğv edərək otağı təsərrüfat anbarına çevirmək", "Qazanxana sistemini yoxlamadan yalnız ilk şaxtalı gündə qaz təchizatını açmaq", "İstilik sisteminin suyunu boşaldaraq sistemi bütün qış boyu quru saxlamaq", "İstilik radiatorlarını sökərək tədris korpusunu elektrik qızdırıcıları ilə qızdırmaq", "Qazanların, nasosların, istilik radiatorlarının hidravlik yoxlanışı, boruların təmizlənməsi, qaz və təhlükəsizlik avtomatikasının sazlanmasını təmin etmək"]'::jsonb, 'Qazanların, nasosların, istilik radiatorlarının hidravlik yoxlanışı, boruların təmizlənməsi, qaz və təhlükəsizlik avtomatikasının sazlanmasını təmin etmək', 'Düzgün cavab: E) Qazanların, nasosların, istilik radiatorlarının hidravlik yoxlanışı, boruların t', '', 7, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f82007ce-4d05-4a49-b191-44e2ab270103', '0ec19df5-05b8-4d2f-bee8-9c32fb1f45a1', 'ka', 'რა დოკუმენტით ფორმდება სკოლის საწყობში შემოსული სამეურნეო საქონლის მიღება და აღრიცხვა?', '["სკოლის სამეურნეო მუშაკების ყოველთვიური სამუშაო დროის აღრიცხვის ტაბელისა და პატაკების საფუძველზე", "სასწავლო ნივთებზე კლასის დამრიგებელთა ზეპირი შეკვეთა-შეტყობინებების საფუძველზე", "დაწესებულების პედაგოგიური საბჭოს კვარტალური სხდომის ოქმისა და მეთოდური დასკვნის საფუძველზე", "მშობელთა და მასწავლებელთა ასოციაციის მიერ შედგენილი საზოგადოებრივი კონტროლის აქტის საფუძველზე", "მომწოდებლის ელექტრონული სასაქონლო ზედნადების, მიღება-ჩაბარების აქტის, საწყობის შემოსავლის ორდერისა და საინვენტარო წიგნში რეგისტრაციის საფუძველზე"]'::jsonb, 'მომწოდებლის ელექტრონული სასაქონლო ზედნადების, მიღება-ჩაბარების აქტის, საწყობის შემოსავლის ორდერისა და საინვენტარო წიგნში რეგისტრაციის საფუძველზე', 'Düzgün cavab: E) მომწოდებლის ელექტრონული სასაქონლო ზედნადების, მიღება-ჩაბარების აქტის, საწყობის შ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('326640a7-c369-4c7a-9349-3b8976c180fb', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təhsil müəssisəsinin elektrik təsərrüfatının təhlükəsiz istismarı zamanı hansı əsas qaydaya riayət olunmalıdır?', 'multiple_choice', '["Elektrik lövhələri qapalı və kilidli saxlanmalı, qoruyucu vasitələrlə təchiz edilməli, kabel izolyasiyaları saz olmalı, xəsarət təhlükəsi aradan qaldırılmalıdır", "Standart qoruyucular sıradan çıxdıqda onların yerinə kustar məftil (juçok) quraşdırmaq", "Elektrik naqillərini açıq vəziyyətdə döşəmə üzərində nəzarətsiz saxlamaq", "Elektrik lövhələrinin qapılarını açıq qoyaraq təhsilalanların sərbəst baxışına şərait yaratmaq", "Elektrik cihazlarının təmirini fənn müəllimlərinə və ya şagirdlərə həvalə etmək"]'::jsonb, 'Elektrik lövhələri qapalı və kilidli saxlanmalı, qoruyucu vasitələrlə təchiz edilməli, kabel izolyasiyaları saz olmalı, xəsarət təhlükəsi aradan qaldırılmalıdır', 'Düzgün cavab: A) Elektrik lövhələri qapalı və kilidli saxlanmalı, qoruyucu vasitələrlə təchiz edi', '', 8, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e826ab09-f954-43d7-a4f2-6411bb7937db', '326640a7-c369-4c7a-9349-3b8976c180fb', 'ka', 'როგორია ფიზიკური ცვეთის შედეგად სრულად მწყობრიდან გამოსული ინვენტარის ჩამოწერის წესი?', '["ხელმძღვანელობის ბრძანებით შექმნილი სალიკვიდაციო კომისიის (სამეურნეო ნაწილის გამგე, მოადგილე, ბუღალტერი) ოფიციალურად დამტკიცებული ჩამოწერის აქტის, დეფექტური აქტისა და ნარჩენი ღირებულების გაანგარიშების საფუძველზე", "მშობლების ზეპირი თანხმობით ავეჯის სხვა პირებზე გადაცემა აუქციონის გარეშე", "მხოლოდ საგნის მასწავლებლების მიერ ლაბორატორიულ აღჭურვილობაზე გაცემული ინდივიდუალური ცნობების საფუძველზე", "სამეურნეო ნაწილის გამგის ინდივიდუალური გადაწყვეტილებით ქონების სკოლის ტერიტორიიდან გატანა და მოცილება", "საინვენტარო წიგნში სარეგისტრაციო ნომრის წაშლა და ქონების ხელახალი დანომრვის გარეშე გამოყენება"]'::jsonb, 'ხელმძღვანელობის ბრძანებით შექმნილი სალიკვიდაციო კომისიის (სამეურნეო ნაწილის გამგე, მოადგილე, ბუღალტერი) ოფიციალურად დამტკიცებული ჩამოწერის აქტის, დეფექტური აქტისა და ნარჩენი ღირებულების გაანგარიშების საფუძველზე', 'Düzgün cavab: A) ხელმძღვანელობის ბრძანებით შექმნილი სალიკვიდაციო კომისიის (სამეურნეო ნაწილის გამგ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d9abfc10-0b1f-4414-8f6d-5006d7b73326', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Sanitar-gigiyena və SanPiN normalarına əsasən, məktəb binasının dərs otaqlarında optimal hava temperaturu hansı həddə olmalıdır?', 'multiple_choice', '["Dərs otaqlarında temperatur rejiminin saxlanması məcburi sayılmır", "Dərs otaqlarında 10–12°C, idman zalında 8–10°C", "Dərs otaqlarında və laboratoriyalarda 18–21°C (optimal 18–24°C), idman zalında isə 15–17°C", "Bütün otaqlarda temperatur həddi fərq qoyulmadan 5–10°C olmalıdır", "Dərs otaqlarında 28–32°C, idman zalında 25–27°C"]'::jsonb, 'Dərs otaqlarında və laboratoriyalarda 18–21°C (optimal 18–24°C), idman zalında isə 15–17°C', 'Düzgün cavab: C) Dərs otaqlarında və laboratoriyalarda 18–21°C (optimal 18–24°C), idman zalında i', '', 9, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ab9e2514-4f81-4cd2-8644-8b7d67bd880b', 'd9abfc10-0b1f-4414-8f6d-5006d7b73326', 'ka', 'სკოლის შენობის სანიტარიულ-ჰიგიენური მდგომარეობის უზრუნველყოფისას რა ფორმით ახორციელებს სამეურნეო ნაწილის გამგე მომსახურე პერსონალის ხელმძღვანელობას?', '["დამლაგებლების სამუშაო გრაფიკის აღრიცხვის გარეშე ოთახების დასუფთავების მხოლოდ მოსწავლეებზე დაკისრება", "დასუფთავების სამუშაოების მხოლოდ სასწავლო წლის ბოლოს შაბათობის ფორმით ორგანიზებით შემოფარგვლა", "სამუშაოს ყოველდღიური განაწილება, უბნებად დაყოფა, საწმენდი და სადეზინფექციო საშუალებებით უზრუნველყოფა, ხარისხის ყოველდღიური კონტროლი და ჰიგიენის ჟურნალის წარმოება", "დამლაგებლების სამსახურებრივი უფლებამოსილებების შეცვლა და მათი ჩართვა პედაგოგიური დოკუმენტების საქმისწარმოების აღრიცხვაში", "სასწავლო ოთახების სანიტარიული დასუფთავების პროცესის მიტოვება მხოლოდ მშობელთა კომიტეტის კონტროლზე"]'::jsonb, 'სამუშაოს ყოველდღიური განაწილება, უბნებად დაყოფა, საწმენდი და სადეზინფექციო საშუალებებით უზრუნველყოფა, ხარისხის ყოველდღიური კონტროლი და ჰიგიენის ჟურნალის წარმოება', 'Düzgün cavab: C) სამუშაოს ყოველდღიური განაწილება, უბნებად დაყოფა, საწმენდი და სადეზინფექციო საშუა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3af9b0f9-8ecf-4b53-9ac4-486a340a732e', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təhsil müəssisəsində su təchizatı və kanalizasiya sisteminin saz saxlanması üçün təsərrüfat müdiri nə etməlidir?', 'multiple_choice', '["Bütün su kranlarını bağlayaraq məktəbdə su istifadəsini tamamilə qadağan etmək", "İçməli su çənlərinin təmizlənməsini və yuyulmasını qeyri-müəyyən müddətə təxirə salmaq", "Kanalizasiya quyularının qapaqlarını açıq saxlayaraq hava axını yaratmaq", "Kanalizasiya borularında sızma olduqda təmir etmədən üzərinə qum örtmək", "Su kranlarının, axıtma baklarının, boru və ventillərin sızmalarını vaxtında aşkar edib aradan qaldırmaq, su ehtiyat anbarlarını dövri təmizləmək və dezinfeksiya etmək"]'::jsonb, 'Su kranlarının, axıtma baklarının, boru və ventillərin sızmalarını vaxtında aşkar edib aradan qaldırmaq, su ehtiyat anbarlarını dövri təmizləmək və dezinfeksiya etmək', 'Düzgün cavab: E) Su kranlarının, axıtma baklarının, boru və ventillərin sızmalarını vaxtında aşka', '', 10, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('84052d9a-1c74-40d2-9d27-536fb77d4c23', '3af9b0f9-8ecf-4b53-9ac4-486a340a732e', 'ka', 'საგანმანათლებლო დაწესებულების წყალმომარაგებისა და საკანალიზაციო სისტემაში ავარიის მოხდენისას რა უნდა იყოს სამეურნეო ნაწილის გამგის პირველი ნაბიჯი?', '["მოსწავლეების მიყვანა წყლის გაჟონვის ადგილას და მათთვის დასუფთავებისა და შეკეთების სამუშაოების დავალება", "შემთხვევის შესახებ არანაირი ზომების მიუღებლობა და სასწავლო დღისა და გაკვეთილების დასრულების ლოდინი", "ავარიის ადგილზე მაღალი ძაბვის ელექტროგამათბობელი მოწყობილობების მიერთება ტერიტორიის გასაშრობად", "მთელი შენობის სავენტილაციო ფანჯრების დახურვა და ოთახების კარების ჩაკეტვა", "შესაბამისი ავარიული ონკანის (ურდულის) გადაკეტვა წყალმომარაგების დაუყოვნებლივ შესაწყვეტად, ელექტროუსაფრთხოების უზრუნველყოფა, ტექნიკური პერსონალის მობილიზება და ავარიის აღმოფხვრა"]'::jsonb, 'შესაბამისი ავარიული ონკანის (ურდულის) გადაკეტვა წყალმომარაგების დაუყოვნებლივ შესაწყვეტად, ელექტროუსაფრთხოების უზრუნველყოფა, ტექნიკური პერსონალის მობილიზება და ავარიის აღმოფხვრა', 'Düzgün cavab: E) შესაბამისი ავარიული ონკანის (ურდულის) გადაკეტვა წყალმომარაგების დაუყოვნებლივ შეს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('99f6397d-a1e5-4685-bf72-59663734cd84', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb anbarına daxil olan maddi qiymətlilərin (təsərrüfat malları, mebel, inventar) qəbulu hansı sənədlər əsasında həyata keçirilir?', 'multiple_choice', '["Maddi qiymətlilər yalnız təqvim ilinin sonunda bir ümumi aktla qəbul edilir", "Yalnız şagird valideynlərinin vatsap bildirişi əsasında", "Yalnız tədarükçü şirkətin sürücüsü ilə şifahi razılaşma əsasında", "Təhvil-təslim qaiməsi, elektron qaimə-faktura və ya daxili qaimə əsasında faktiki sayılaraq və yoxlanılaraq qəbul orderi tərtib olunur", "Heç bir sənəd olmadan, mallar birbaşa anbara boşaldılaraq qeydiyyatsız saxlanılır"]'::jsonb, 'Təhvil-təslim qaiməsi, elektron qaimə-faktura və ya daxili qaimə əsasında faktiki sayılaraq və yoxlanılaraq qəbul orderi tərtib olunur', 'Düzgün cavab: D) Təhvil-təslim qaiməsi, elektron qaimə-faktura və ya daxili qaimə əsasında faktik', '', 11, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('57c803c6-78d8-4c55-875a-d55f3b05ee22', '99f6397d-a1e5-4685-bf72-59663734cd84', 'ka', 'სკოლის ელექტრომეურნეობის ექსპლუატაციისას უსაფრთხოების რომელ წესს უნდა იცავდეს სამეურნეო ნაწილის გამგე?', '["დაზიანებული და გადახურებული ელექტროსადენების შეუკეთებლად, ქაღალდის ლენტის გადაკვრით ექსპლუატაცია", "ელექტროგამანაწილებელი ფარების კარების მუდმივად ღია დატოვება და დამცველების არასტანდარტული მავთულებით შეცვლა", "უსაფრთხოების დამიწების კონტურის გამორთვა როზეტებიდან და მოწყობილობების პირდაპირ ფაზაზე მიერთება", "ელექტროგამანაწილებელი ფარების დაკეტილ და დაბლოკილ მდგომარეობაში შენარჩუნება, დამცველების (ავტომატების) გამართულობა, დამიწების არსებობა და შეკეთების წარმოება მხოლოდ კვალიფიციური ელექტრიკოსების მიერ", "ელექტროქსელში წარმოქმნილი გაუმართაობების აღმოფხვრის დავალება მორიგე მოსწავლეებისთვის"]'::jsonb, 'ელექტროგამანაწილებელი ფარების დაკეტილ და დაბლოკილ მდგომარეობაში შენარჩუნება, დამცველების (ავტომატების) გამართულობა, დამიწების არსებობა და შეკეთების წარმოება მხოლოდ კვალიფიციური ელექტრიკოსების მიერ', 'Düzgün cavab: D) ელექტროგამანაწილებელი ფარების დაკეტილ და დაბლოკილ მდგომარეობაში შენარჩუნება, დამ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1afec3cc-00e6-425c-92c0-7bc18686fcde', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təsərrüfat müdiri tabeliyində olan xidmətedici heyətin (xadimə, fəhlə, gözətçi, bağban) gündəlik fəaliyyətinə və iş vaxtına hansı sənədlə nəzarət edir?', 'multiple_choice', '["Müəllimlərin açıq dərs protokolları ilə", "Kitabxana fondunun dövriyyə statistikası ilə", "İş vaxtının uçotu tabelində (tabel cədvəlində) gündəlik davamiyyətin və növbətçiliyin qeydiyyatı ilə", "Sinif jurnallarının rüblük qiymətləndirmə səhifələri ilə", "Fənn dərslərinin elektron tədris cədvəli ilə"]'::jsonb, 'İş vaxtının uçotu tabelində (tabel cədvəlində) gündəlik davamiyyətin və növbətçiliyin qeydiyyatı ilə', 'Düzgün cavab: C) İş vaxtının uçotu tabelində (tabel cədvəlində) gündəlik davamiyyətin və növbətçi', '', 12, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ae4eb04d-07c1-44e5-9725-6b325600a7d9', '1afec3cc-00e6-425c-92c0-7bc18686fcde', 'ka', 'შრომის კანონმდებლობის შესაბამისად, რომელ დოკუმენტში წარმოებს მომსახურე პერსონალის სამუშაო დროის აღრიცხვა?', '["საბიბლიოთეკო ფონდის ბრუნვისა და საინვენტარო აღრიცხვის საქაღალდეში", "დაწესებულების წლიური ფინანსური ხარჯებისა და სამეურნეო ხარჯთაღრიცხვის ცხრილში", "სამუშაო დროის აღრიცხვის ტაბელში — ოფიციალურ დოკუმენტში, სადაც ფიქსირდება ყოველდღიური დასწრება, შვებულებები და საავადმყოფო ფურცლები", "სკოლის პედაგოგიური საბჭოს წლიური გადაწყვეტილებების რეესტრში", "საგნობრივი კაბინეტების პასპორტიზაციისა და რეგისტრაციის ბარათში"]'::jsonb, 'სამუშაო დროის აღრიცხვის ტაბელში — ოფიციალურ დოკუმენტში, სადაც ფიქსირდება ყოველდღიური დასწრება, შვებულებები და საავადმყოფო ფურცლები', 'Düzgün cavab: C) სამუშაო დროის აღრიცხვის ტაბელში — ოფიციალურ დოკუმენტში, სადაც ფიქსირდება ყოველდღ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('626efd6f-bef3-4cd5-8f9f-cb2fd5b54e95', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb həyətinin, idman meydançalarının və keçid yollarının təmizlənməsi və abadlığı necə təşkil edilməlidir?', 'multiple_choice', '["İdman meydançasının texniki baxışı yalnız tədris ilinin sonunda aparılmalıdır", "Qışda yaranan buzlaşma sahələri təmizlənmədən təbii əriməyə buraxılmalıdır", "Həyətin təmizlənməsi yalnız ildə iki dəfə ümumxalq iməciliyi zamanı icra edilməlidir", "Gündəlik süpürülməli, zibil və tullantılar kənarlaşdırılmalı, qışda qar və buzdan təmizlənərək qum-duz qarışığı səpilməli, təhlükəsizlik təmin olunmalıdır", "Tullantılar həyətin küncündə yığılaraq açıq havada yandırılmalıdır"]'::jsonb, 'Gündəlik süpürülməli, zibil və tullantılar kənarlaşdırılmalı, qışda qar və buzdan təmizlənərək qum-duz qarışığı səpilməli, təhlükəsizlik təmin olunmalıdır', 'Düzgün cavab: D) Gündəlik süpürülməli, zibil və tullantılar kənarlaşdırılmalı, qışda qar və buzda', '', 13, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('71abe48f-8f30-498c-8146-af3821dfc273', '626efd6f-bef3-4cd5-8f9f-cb2fd5b54e95', 'ka', 'სამეურნეო საწყობში ქიმიური საწმენდი და სადეზინფექციო ნივთიერებების შენახვისას რომელი მოთხოვნაა სავალდებულო?', '["ნივთიერებების ერთმანეთზე დაწყობა ღია სასკოლო ეზოში პირდაპირი მზის სხივების ქვეშ", "ქიმიური ნივთიერებების ჭურჭელზე გამაფრთხილებელი ეტიკეტების წაშლა და მათი უსახელოდ შენახვა", "საკვებ პროდუქტებთან და სასმელი წყლის მარაგთან ერთ თაროზე არეულად შენახვა", "სპეციალურ დახურულ, ბავშვებისთვის მიუწვდომელ, კარგად ვენტილირებად, ხანძარუსაფრთხო, მარკირებულ და ჩაკეტილ კარადაში ან საწყობში, საკვები პროდუქტებისა და სახელმძღვანელოებისგან განცალკევებით შენახვა", "სასწავლო კორპუსის დერეფნებსა და კიბის ქვეშ ღია თაროებზე განთავსება"]'::jsonb, 'სპეციალურ დახურულ, ბავშვებისთვის მიუწვდომელ, კარგად ვენტილირებად, ხანძარუსაფრთხო, მარკირებულ და ჩაკეტილ კარადაში ან საწყობში, საკვები პროდუქტებისა და სახელმძღვანელოებისგან განცალკევებით შენახვა', 'Düzgün cavab: D) სპეციალურ დახურულ, ბავშვებისთვის მიუწვდომელ, კარგად ვენტილირებად, ხანძარუსაფრთხო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9db8848a-074d-4160-9941-1859c64b3070', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təhsil müəssisəsində dərs otaqlarının və dəhlizlərin gündəlik nəm təmizlənməsi və dezinfeksiyası hansı qrafiklə aparılmalıdır?', 'multiple_choice', '["Dərslərdən sonra və növbələr arasında döşəmələr nəm üsulla silinməli, pəncərə altlıqları, qapı tutacaqları dezinfeksiyaedici vasitələrlə təmizlənməlidir", "Dərs otaqlarında heç vaxt su və dezinfeksiyaedici vasitə istifadə edilməməlidir", "Nəm təmizləmə yalnız həftədə bir dəfə dərslər zamanı aparılmalıdır", "Təmizlik işləri yalnız yay tətili dövründə bir dəfə icra olunmalıdır", "Otaqların nəm təmizlənməsi şagirdlərin şəxsi vəzifəsi hesab edilir"]'::jsonb, 'Dərslərdən sonra və növbələr arasında döşəmələr nəm üsulla silinməli, pəncərə altlıqları, qapı tutacaqları dezinfeksiyaedici vasitələrlə təmizlənməlidir', 'Düzgün cavab: A) Dərslərdən sonra və növbələr arasında döşəmələr nəm üsulla silinməli, pəncərə al', '', 14, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('550700d0-6836-419d-8f8c-3d736bc35579', '9db8848a-074d-4160-9941-1859c64b3070', 'ka', 'რა არის ზამთრისა და წვიმების სეზონის წინ სკოლის შენობის სახურავის, ღარებისა და წყალსაწრეტი მილების შემოწმების ძირითადი მიზანი?', '["სახურავიდან წვიმისა და თოვლის წყლის ეფექტური ჩადინების უზრუნველყოფა, წყლის გაჟონვის, კედლების სინესტისგან დაზიანებისა და ზამთარში ყინულის ლოლოების წარმოქმნის თავიდან აცილება", "შენობის ფასადის გარეგანი იერსახის ხელოვნური შეცვლა და ფერთა გამის განახლება", "სახურავის საფარზე დამატებითი ტექნიკური სასაწყობო ოთახების მოწყობა და იქ ინვენტარის განთავსება", "წვიმისა და თოვლის წყლის პირდაპირ შიდა სასწავლო ოთახებში ჩადინება და მათი დაუყოვნებლივი დასუფთავების უზრუნველყოფა", "სახურავის ტექნიკური დათვალიერების ჩატარება მხოლოდ ზამთრის სეზონის სრულად დასრულების შემდეგ მომდევნო სასწავლო წელს"]'::jsonb, 'სახურავიდან წვიმისა და თოვლის წყლის ეფექტური ჩადინების უზრუნველყოფა, წყლის გაჟონვის, კედლების სინესტისგან დაზიანებისა და ზამთარში ყინულის ლოლოების წარმოქმნის თავიდან აცილება', 'Düzgün cavab: A) სახურავიდან წვიმისა და თოვლის წყლის ეფექტური ჩადინების უზრუნველყოფა, წყლის გაჟონ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('cb3136bf-1152-41c6-9c80-a7da078d41ef', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb mebelinin (parta, stul, yazı lövhəsi) sazlığına və istismarına təsərrüfat nəzarəti zamanı hansı tələb əsas götürülür?', 'multiple_choice', '["Qırıq və mismarı çıxmış stulların təmir edilmədən istifadəsinə icazə verilməsi", "Mebel təmirinin şagirdlərin texnologiya dərslərində icra olunmasına məcbur edilməsi", "Bütün siniflərdə eyni ölçülü partaların şagirdlərin boyundan asılı olmayaraq qoyulması", "Partaların rənglənməsinin yalnız dərslər gedən saatlarda aparılması", "Parta və stulların şagirdlərin boy və yaş qruplarına (SanPiN üzrə 1–6 nömrə) uyğunlaşdırılması, kəsici-batıcı qüsurların olmaması və lövhələrin möhkəm bərkidilməsi"]'::jsonb, 'Parta və stulların şagirdlərin boy və yaş qruplarına (SanPiN üzrə 1–6 nömrə) uyğunlaşdırılması, kəsici-batıcı qüsurların olmaması və lövhələrin möhkəm bərkidilməsi', 'Düzgün cavab: E) Parta və stulların şagirdlərin boy və yaş qruplarına (SanPiN üzrə 1–6 nömrə) uyğ', '', 15, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3b80abb3-f91d-46ca-b9ea-340960d27213', 'cb3136bf-1152-41c6-9c80-a7da078d41ef', 'ka', 'სკოლის ეზოსა და სპორტული მოედნების კეთილმოწყობისა და უსაფრთხოდ შენარჩუნების კუთხით, რა შედის სამეურნეო ნაწილის გამგის მოვალეობაში?', '["სპორტული კონსტრუქციების ტექნიკური გამართულობის შემოწმება მხოლოდ უბედური შემთხვევის მოხდენის შემდეგ", "დასვენების დროს მოსწავლეთა სკოლის ეზოსა და მოედანზე გასვლის სრული შეზღუდვა", "ტერიტორიის კეთილმოწყობისა და გამწვანების სამუშაოების მიტოვება მხოლოდ მოსწავლეთა ინდივიდუალურ ინიციატივაზე", "ეზოს ტერიტორიაზე საყოფაცხოვრებო და სამეურნეო ნარჩენების ღიად შეგროვებისთვის პირობების შექმნა", "ნაგვის ურნებისა და კონტეინერების განთავსება, სპორტული დანადგარების მყარი დამაგრება, საფარის გამართულობა და ტერიტორიის ყოველდღიური სისუფთავისა და განათების უზრუნველყოფა"]'::jsonb, 'ნაგვის ურნებისა და კონტეინერების განთავსება, სპორტული დანადგარების მყარი დამაგრება, საფარის გამართულობა და ტერიტორიის ყოველდღიური სისუფთავისა და განათების უზრუნველყოფა', 'Düzgün cavab: E) ნაგვის ურნებისა და კონტეინერების განთავსება, სპორტული დანადგარების მყარი დამაგრე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('92e07d88-db16-415e-9c7f-22ba7633d2f1', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Sanitar qovşaqların (tualetlərin) təmizliyi və gigiyenik təminatı hansı qaydada həyata keçirilir?', 'multiple_choice', '["Hər tənəffüsdən sonra yoxlanılmalı, gündəlik dezinfeksiya edilməli, fasiləsiz su, sabun, tualet kağızı və zibil qabları ilə təmin olunmalıdır", "Tualetlərdə sabun və yuyucu vasitələrin saxlanılması qadağandır", "Sanitar qovşaqların qapıları gün ərzində kilidli saxlanılaraq istifadəyə verilməməlidir", "Sanitar qovşaqlar həftədə yalnız bir dəfə dezinfeksiya olunmalıdır", "Sanitar qovşaqların təmizlənməsi xadimələrin vəzifə öhdəliyinə daxil deyildir"]'::jsonb, 'Hər tənəffüsdən sonra yoxlanılmalı, gündəlik dezinfeksiya edilməli, fasiləsiz su, sabun, tualet kağızı və zibil qabları ilə təmin olunmalıdır', 'Düzgün cavab: A) Hər tənəffüsdən sonra yoxlanılmalı, gündəlik dezinfeksiya edilməli, fasiləsiz su', '', 16, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e701de81-0faa-4571-9063-3979b571e9d7', '92e07d88-db16-415e-9c7f-22ba7633d2f1', 'ka', 'სასკოლო ავეჯის (მერხი, სკამი) შეკეთებისა და კლასებში განაწილების პროცესში რა არის ძირითადი ერგონომიკული მოთხოვნა?', '["მერხებისა და სკამების მისადაგება მოსწავლეთა სიმაღლესთან და ასაკობრივ ჯგუფებთან (სანიტარიული ნორმებით დანომრვა — № 1-6), მხედველობის თავისებურებებთან და ზედაპირების სიგლუვე და უსაფრთხოება", "ავეჯის საკლასო ოთახებში ისე მჭიდროდ განლაგება, რომ სრულად ჩაიხერგოს ფანჯრის სინათლე", "ყველა საკლასო ოთახში განურჩევლად ერთი და იმავე ზომის ყველაზე დიდი ავეჯის კომპლექტების დამონტაჟება", "მერხებისა და სკამების ყოველ სასწავლო კვარტალში სხვადასხვა ფერად ხელახალი შეღებვის ორგანიზება", "მერხებზე ლითონის დამამაგრებელი კუთხეების მიმაგრება მოსწავლეთა მოძრაობის სივრცის შეზღუდვით"]'::jsonb, 'მერხებისა და სკამების მისადაგება მოსწავლეთა სიმაღლესთან და ასაკობრივ ჯგუფებთან (სანიტარიული ნორმებით დანომრვა — № 1-6), მხედველობის თავისებურებებთან და ზედაპირების სიგლუვე და უსაფრთხოება', 'Düzgün cavab: A) მერხებისა და სკამების მისადაგება მოსწავლეთა სიმაღლესთან და ასაკობრივ ჯგუფებთან (', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d5efef2f-b5d7-41a5-983d-b076eb7f3c64', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb yeməkxanasının və ya bufetinin təsərrüfat təminatında təsərrüfat müdirinin cavabdehliyi nədir?', 'multiple_choice', '["İsti və soyuq su təchizatı, kanalizasiya, havalandırma, texnoloji və soyuducu avadanlıqların sazlığı, gigiyenik şərait və zibilin vaxtında kənarlaşdırılması", "Yeməkxanada qida bişirilməsi işinə birbaşa aşpaz kimi rəhbərlik etmək", "Qida məhsullarının keyfiyyət sertifikatlarının laboratoriya analizinin aparılması", "Gündəlik qida rasionunun və kulinariya reseptlərinin tərtib edilməsi", "Şagirdlərin bufetdə qidalanma növbəsinin akademik cədvəlinin tərtibi"]'::jsonb, 'İsti və soyuq su təchizatı, kanalizasiya, havalandırma, texnoloji və soyuducu avadanlıqların sazlığı, gigiyenik şərait və zibilin vaxtında kənarlaşdırılması', 'Düzgün cavab: A) İsti və soyuq su təchizatı, kanalizasiya, havalandırma, texnoloji və soyuducu av', '', 17, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3e183fbe-3719-4258-a865-e15bf4a77626', 'd5efef2f-b5d7-41a5-983d-b076eb7f3c64', 'ka', 'როგორ ორგანიზდება საგანმანათლებლო დაწესებულებაში დეზინფექციის, დეზინსექციისა და დერატიზაციის სამუშაოები?', '["ხელშეკრულების საფუძველზე ლიცენზირებულ სპეციალიზებულ მომსახურების ორგანიზაციებთან, გაკვეთილების დასრულების შემდეგ, მოსწავლეთა არყოფნისას, უსაფრთხოების ზომების დაცვით შესრულება", "ქიმიური დამუშავების ჩატარება მხოლოდ სკოლის სასადილოში და საკლასო ოთახების უყურადღებოდ დატოვება", "დაწესებულებაში ამგვარი სანიტარიული ღონისძიებების ჩატარების სრული აკრძალვა სანიტარიული წესებით", "სამუშაოების ჩატარება დამლაგებლების მიერ სასწავლო პროცესის დროს საგნობრივი გაკვეთილების პარალელურად", "მავნებლებთან ბრძოლის განხორციელება მხოლოდ სამეურნეო ნაწილის გამგის ინდივიდუალური ქიმიური ნარევებით"]'::jsonb, 'ხელშეკრულების საფუძველზე ლიცენზირებულ სპეციალიზებულ მომსახურების ორგანიზაციებთან, გაკვეთილების დასრულების შემდეგ, მოსწავლეთა არყოფნისას, უსაფრთხოების ზომების დაცვით შესრულება', 'Düzgün cavab: A) ხელშეკრულების საფუძველზე ლიცენზირებულ სპეციალიზებულ მომსახურების ორგანიზაციებთან', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('039fff29-9759-40f3-a7df-33895c0ad7ec', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb binasında pəncərələrin təmizlənməsi və şüşələrin silinməsi zamanı hansı əsas təhlükəsizlik qaydası tətbiq olunur?', 'multiple_choice', '["Şüşələrin silinməsini yalnız güclü küləkli və yağışlı havada həyata keçirmək", "Şüşələrin xaricdən silinməsini təhsilalanların köməyi ilə təşkil etmək", "Hündür mərtəbələrdə xaricdən şüşə silinərkən pəncərə taxtasına və ya kənara çıxmaq qəti qadağandır; xüsusi teleskopik fırçalardan və ya təhlükəsizlik kəmərindən istifadə edilməlidir", "Şüşə təmizləmə zamanı qoruyucu vasitələrdən istifadəni qadağan etmək", "Pəncərə kənarına çıxaraq heç bir sığorta olmadan şüşələri silməyə icazə vermək"]'::jsonb, 'Hündür mərtəbələrdə xaricdən şüşə silinərkən pəncərə taxtasına və ya kənara çıxmaq qəti qadağandır; xüsusi teleskopik fırçalardan və ya təhlükəsizlik kəmərindən istifadə edilməlidir', 'Düzgün cavab: C) Hündür mərtəbələrdə xaricdən şüşə silinərkən pəncərə taxtasına və ya kənara çıxm', '', 18, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2478cb8f-9cad-4825-aa77-ce2b7a8b6f46', '039fff29-9759-40f3-a7df-33895c0ad7ec', 'ka', 'სად აღრიცხავს სამეურნეო ნაწილის გამგე მომსახურე პერსონალის შრომის უსაფრთხოების ინსტრუქტაჟს?', '["დაწესებულების წლიური ფინანსური ხარჯებისა და სამეურნეო ხარჯთაღრიცხვის საქაღალდეში", "მოსწავლეთა კლასის მიხედვით ინდივიდუალური აკადემიური დასწრების ჟურნალში", "დასაქმებულთა უსაფრთხოების ტექნიკისა და შრომის დაცვის ინსტრუქტაჟის ჟურნალში, როგორც პირველადი, პერიოდული და რიგგარეშე ინსტრუქტაჟი, ხელმოწერით", "საბიბლიოთეკო ფონდის ინვენტარისა და ბრუნვის სააღრიცხვო წიგნში", "სკოლის ხელმძღვანელის ყოველდღიური ადმინისტრაციული განკარგულებების რვეულში"]'::jsonb, 'დასაქმებულთა უსაფრთხოების ტექნიკისა და შრომის დაცვის ინსტრუქტაჟის ჟურნალში, როგორც პირველადი, პერიოდული და რიგგარეშე ინსტრუქტაჟი, ხელმოწერით', 'Düzgün cavab: C) დასაქმებულთა უსაფრთხოების ტექნიკისა და შრომის დაცვის ინსტრუქტაჟის ჟურნალში, როგო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0441bb1e-bedf-4a4d-bfb1-606599102ff5', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəbdə elektrik cərəyanı vurması və ya qısaqapanma təhlükəsi yarandıqda təsərrüfat müdirinin ilk addımı nə olmalıdır?', 'multiple_choice', '["Hadisə yerini təcrid etmədən şagirdlərin sərbəst baxışına şərait yaratmaq", "Elektrik lövhəsinin üzərinə dərhal su tökərək qığılcımı söndürməyə çalışmaq", "Gərginlik altında olan naqili çılpaq əllə tutaraq kənara çəkmək", "Dərhal əsas paylayıcı lövhədən ümumi elektrik açarını (avtomatı) söndürərək dövrəni enerjisizləşdirmək və təhlükəsizlik tədbirləri görmək", "Elektrik sistemini söndürmədən yalnız növbəti gün mütəxəssis çağırmaq"]'::jsonb, 'Dərhal əsas paylayıcı lövhədən ümumi elektrik açarını (avtomatı) söndürərək dövrəni enerjisizləşdirmək və təhlükəsizlik tədbirləri görmək', 'Düzgün cavab: D) Dərhal əsas paylayıcı lövhədən ümumi elektrik açarını (avtomatı) söndürərək dövr', '', 19, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c5cac717-0720-41fe-9e9a-a1ffe9c74673', '0441bb1e-bedf-4a4d-bfb1-606599102ff5', 'ka', 'ზამთრის პერიოდში სკოლის შესასვლელი კიბეების მოყინვისას რა ზომა უნდა მიიღოს სამეურნეო ნაწილის გამგემ?', '["მოსწავლეებისა და მასწავლებლების წახალისება მოყინულ ზედაპირზე თავისუფლად გადასაადგილებლად", "საფეხმავლო გადასასვლელი მონაკვეთების დატოვება ყოველგვარი გაწმენდის გარეშე ბუნებრივი გადნობისთვის", "კიბეებზე ცივი წყლის დასხმა ყინულის ფენის კიდევ უფრო გამაგრების მიზნით", "კიბეებისა და საფეხმავლო ბილიკების თოვლისა და ყინულისგან გაწმენდა, მოცურების საწინააღმდეგო ქვიშა-მარილის ნარევის მოყრა, რეზინის ხალიჩების დაგება და უსაფრთხოების უზრუნველყოფა", "სკოლის ყველა შესასვლელი კარის ჩაკეტვა და გაკვეთილების განუსაზღვრელი ვადით გადადების მოთხოვნა"]'::jsonb, 'კიბეებისა და საფეხმავლო ბილიკების თოვლისა და ყინულისგან გაწმენდა, მოცურების საწინააღმდეგო ქვიშა-მარილის ნარევის მოყრა, რეზინის ხალიჩების დაგება და უსაფრთხოების უზრუნველყოფა', 'Düzgün cavab: D) კიბეებისა და საფეხმავლო ბილიკების თოვლისა და ყინულისგან გაწმენდა, მოცურების საწი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e9be5be2-0a52-4b65-9608-40022b148155', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəbin texniki təmir fəhlələrinin təhlükəsiz iş alətləri ilə təminatına hansı tələblər qoyulur?', 'multiple_choice', '["Kustar üsulla düzəldilmiş təhlükəli nərdivanlardan hündürlükdə istifadə edilməsi", "İşçilərə fərdi mühafizə vasitələri (eynək, əlcək) verilməsinin qadağan olunması", "Alətlər (çəkic, kəlbətin, vintaçan, nərdivan) saz olmalı, çat və qüsur olmamalı, elektrik alətlərinin kabelləri izolyasiyalı və torpaqlanmış olmalıdır", "Elektrik alətlərinin çılpaq naqillərlə birbaşa elektrik yuvasına qoşulması", "Sapı çatlamış və boşalmış çəkiclərdən istifadəyə icazə verilməsi"]'::jsonb, 'Alətlər (çəkic, kəlbətin, vintaçan, nərdivan) saz olmalı, çat və qüsur olmamalı, elektrik alətlərinin kabelləri izolyasiyalı və torpaqlanmış olmalıdır', 'Düzgün cavab: C) Alətlər (çəkic, kəlbətin, vintaçan, nərdivan) saz olmalı, çat və qüsur olmamalı,', '', 20, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('88da74d8-c060-49d7-ad77-f315f2d8fa4e', 'e9be5be2-0a52-4b65-9608-40022b148155', 'ka', 'სკოლის ბუფეტისა და სასადილოს სანიტარიული მდგომარეობის სამეურნეო მხარდაჭერა რა მიმართულებით უნდა განხორციელდეს?', '["სასადილოს სანიტარიული მოთხოვნების მიუხედავად, ელექტროენერგიისა და წყალმომარაგების ხაზების გათიშვა ეკონომიის მიზნით", "სასადილოს აღჭურვილობის კაპიტალური შეკეთების ჩატარება სასწავლო დროს მოსწავლეთა ყოფნის საათებში", "სასადილოს უწყვეტი ცხელი და ცივი წყლით მომარაგების, ვენტილაციის, კანალიზაციის, განათების, აღჭურვილობის გამართულობისა და ნარჩენების დროული გატანის უზრუნველყოფა", "საკვები ნარჩენების სასადილოს შიგნით ღია ჭურჭელში რამდენიმე დღით შენახვის დაშვება", "სამეურნეო სამსახურის მიერ სასადილოს ჰიგიენის კონტროლის კანონმდებლობით აკრძალვა"]'::jsonb, 'სასადილოს უწყვეტი ცხელი და ცივი წყლით მომარაგების, ვენტილაციის, კანალიზაციის, განათების, აღჭურვილობის გამართულობისა და ნარჩენების დროული გატანის უზრუნველყოფა', 'Düzgün cavab: C) სასადილოს უწყვეტი ცხელი და ცივი წყლით მომარაგების, ვენტილაციის, კანალიზაციის, გა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2d638827-280b-4a02-8915-185472170dc4', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təsərrüfat xərclərinin optimallaşdırılması üçün elektrik enerjisi və su sərfiyyatına nəzarət necə aparılır?', 'multiple_choice', '["Kommunal sayğacların daxili mexanizminə müdaxilə edərək göstəriciləri süni şəkildə azaltmaq", "Enerji və su sərfiyyatı üzrə aylıq hesabatların aparılmasını tamamilə ləğv etmək", "Sayğac göstəricilərinin gündəlik və aylıq qeydiyyatı, qənaətcil LED sistemlərinin tətbiqi, avtomatik sensorların quraşdırılması və sızmaların, nasazlıqların vaxtında aradan qaldırılması", "Bütün daxili işıqlandırma lampalarını sökərək tədris otaqlarını tam qaranlıq rejimə keçirmək", "Müəssisədə su təchizatını tam dayandıraraq sanitar qovşaqların fəaliyyətini məhdudlaşdırmaq"]'::jsonb, 'Sayğac göstəricilərinin gündəlik və aylıq qeydiyyatı, qənaətcil LED sistemlərinin tətbiqi, avtomatik sensorların quraşdırılması və sızmaların, nasazlıqların vaxtında aradan qaldırılması', 'Düzgün cavab: C) Sayğac göstəricilərinin gündəlik və aylıq qeydiyyatı, qənaətcil LED sistemlərini', '', 21, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('06b3585a-4558-448f-85ee-713704d0e969', '2d638827-280b-4a02-8915-185472170dc4', 'ka', 'სამეურნეო ხარჯების ოპტიმიზაციისთვის როგორ ხორციელდება ელექტროენერგიისა და წყლის მოხმარების კონტროლი?', '["ენერგიისა და წყლის ხარჯვის ყოველთვიური ანგარიშგების წარმოების სრული გაუქმება", "კომუნალური მრიცხველების შიდა მექანიზმში ჩარევა მაჩვენებლების ხელოვნურად შესამცირებლად", "მრიცხველის ჩვენებების ყოველდღიური და ყოველთვიური აღრიცხვა, ეკონომიური LED სისტემების დანერგვა, ავტომატური სენსორების დამონტაჟება და გაჟონვებისა და გაუმართაობების დროული აღმოფხვრა", "ყველა შიდა განათების ნათურის მოხსნა და სასწავლო ოთახების სრულ სიბნელის რეჟიმზე გადაყვანა", "დაწესებულებაში წყალმომარაგების სრული შეწყვეტა და სანიტარიული კვანძების ფუნქციონირების შეზღუდვა"]'::jsonb, 'მრიცხველის ჩვენებების ყოველდღიური და ყოველთვიური აღრიცხვა, ეკონომიური LED სისტემების დანერგვა, ავტომატური სენსორების დამონტაჟება და გაჟონვებისა და გაუმართაობების დროული აღმოფხვრა', 'Düzgün cavab: C) მრიცხველის ჩვენებების ყოველდღიური და ყოველთვიური აღრიცხვა, ეკონომიური LED სისტემ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9197c667-1630-4ba5-859b-6acbc63976b7', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təhsil müəssisəsində gecə gözətçilərinin fəaliyyətinin təşkilində təsərrüfat müdirinin əsas nəzarət funksiyası nədir?', 'multiple_choice', '["Gözətçilərə tədris fənləri üzrə illik tematik planlaşdırmanın hazırlanmasını tapşırmaq", "Gözətçilərin faktiki işə gəlmə və getmə vaxtlarını heç bir rəsmi sənəddə qeydiyyata almamaq", "Məktəb binasının bütün xarici qapılarını və pəncərələrini gecə vaxtı açıq saxlamaq", "Gözətçiləri növbətçilik saatlarında məktəb ərazisini tərk edərək kənar işlərə getməyə yönəltmək", "Növbə qrafikinə, faktiki işə gəlmə-getmə vaxtlarına riayəti, qapı-pəncərələrin bağlılığını, açarların təhvil-təslimini, jurnalların aparılmasını və ərazi mühafizəsini yoxlamaq"]'::jsonb, 'Növbə qrafikinə, faktiki işə gəlmə-getmə vaxtlarına riayəti, qapı-pəncərələrin bağlılığını, açarların təhvil-təslimini, jurnalların aparılmasını və ərazi mühafizəsini yoxlamaq', 'Düzgün cavab: E) Növbə qrafikinə, faktiki işə gəlmə-getmə vaxtlarına riayəti, qapı-pəncərələrin b', '', 22, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7deac76e-5808-4b24-9d31-59252324c05a', '9197c667-1630-4ba5-859b-6acbc63976b7', 'ka', 'საგანმანათლებლო დაწესებულებაში ღამის დარაჯების საქმიანობის ორგანიზებისას რა წარმოადგენს სამეურნეო ნაწილის გამგის ძირითად საკონტროლო ფუნქციას?', '["დარაჯების სამუშაოზე ფაქტობრივი მოსვლისა და წასვლის დროის არცერთ ოფიციალურ დოკუმენტში არდაფიქსირება", "დარაჯებისთვის სასწავლო საგნების მიხედვით წლიური თემატური გეგმების მომზადების დავალება", "დარაჯების წახალისება მორიგეობის საათებში სკოლის ტერიტორიის დატოვებისა და გარეშე საქმეებზე წასვლისკენ", "სკოლის შენობის ყველა გარე კარი და ფანჯარა ღამით ღია მდგომარეობაში დატოვება", "მორიგეობის გრაფიკის, სამუშაოზე ფაქტობრივი გამოცხადება-წასვლის დროის დაცვის, კარ-ფანჯრების ჩაკეტვის, გასაღებების მიღება-ჩაბარების, ჟურნალების წარმოებისა და ტერიტორიის დაცვის, ვიდეომეთვალყურეობის შემოწმება"]'::jsonb, 'მორიგეობის გრაფიკის, სამუშაოზე ფაქტობრივი გამოცხადება-წასვლის დროის დაცვის, კარ-ფანჯრების ჩაკეტვის, გასაღებების მიღება-ჩაბარების, ჟურნალების წარმოებისა და ტერიტორიის დაცვის, ვიდეომეთვალყურეობის შემოწმება', 'Düzgün cavab: E) მორიგეობის გრაფიკის, სამუშაოზე ფაქტობრივი გამოცხადება-წასვლის დროის დაცვის, კარ-', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2ef4d5ee-000e-49f4-bc13-76dbb34eb93b', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb anbarında malların saxlanması zamanı ''Rəfləmə və qruplaşdırma'' qaydasına hansı tələb uyğundur?', 'multiple_choice', '["Ən ağır inşaat materiallarını ən yuxarı yüngül konstruksiyalı taxta rəflərə yığmaq", "Malların növünə, çəkisinə, həcminə və təyinatına görə rəflərdə, stellajlarda, döşəmədən (15 sm) və divardan (30 sm) aralı, keçidləri saxlamaqla səliqəli yerləşdirilməsi", "Anbar otağının təbii və süni havalandırma sistemlərini daimi bağlı saxlamaq", "Tezalışan kimyəvi maddələri kağız və parça qutuların içərisində qarışıq saxlamaq", "Bütün daxil olan malları qruplaşdırmadan anbarın giriş qapısının önünə tökmək"]'::jsonb, 'Malların növünə, çəkisinə, həcminə və təyinatına görə rəflərdə, stellajlarda, döşəmədən (15 sm) və divardan (30 sm) aralı, keçidləri saxlamaqla səliqəli yerləşdirilməsi', 'Düzgün cavab: B) Malların növünə, çəkisinə, həcminə və təyinatına görə rəflərdə, stellajlarda, dö', '', 23, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('64c75f92-60ab-4c15-95a3-87f68dbb576d', '2ef4d5ee-000e-49f4-bc13-76dbb34eb93b', 'ka', 'სკოლის საწყობში საქონლის შენახვისას რომელი მოთხოვნა შეესაბამება წესს „თაროებზე განლაგება და დაჯგუფება“?', '["ყველაზე მძიმე სამშენებლო მასალების ყველაზე ზედა მსუბუქი კონსტრუქციის ხის თაროებზე დაწყობა", "საქონლის ტიპის, წონის, მოცულობისა და დანიშნულების მიხედვით თაროებზე, სტელაჟებზე, იატაკიდან (15 სმ) და კედლიდან (30 სმ) დაშორებით, გასასვლელების შენარჩუნებით აკურატულად განლაგება", "ადვილაალებადი ქიმიური ნივთიერებების ქაღალდისა და ქსოვილის ყუთებში არეულად შენახვა", "ყველა შემოსული საქონლის დაუჯგუფებლად საწყობის შესასვლელი კარის წინ დაყრა", "საწყობი ოთახის ბუნებრივი და ხელოვნური სავენტილაციო სისტემების მუდმივად დაკეტილ მდგომარეობაში შენარჩუნება"]'::jsonb, 'საქონლის ტიპის, წონის, მოცულობისა და დანიშნულების მიხედვით თაროებზე, სტელაჟებზე, იატაკიდან (15 სმ) და კედლიდან (30 სმ) დაშორებით, გასასვლელების შენარჩუნებით აკურატულად განლაგება', 'Düzgün cavab: B) საქონლის ტიპის, წონის, მოცულობისა და დანიშნულების მიხედვით თაროებზე, სტელაჟებზე,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('cec8a4cf-05af-4f17-820e-39238ecd83f8', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb binasının daxili pəncərə və qapılarının şüşələnməsi zamanı təhlükəsizlik üzrə hansı tələb qoyulur?', 'multiple_choice', '["Qırıq şüşələrin yerinə karton və ya polietilen örtüklər vuraraq mövsümü başa vurmaq", "Şüşələnmə və quraşdırma işlərini ibtidai sinif şagirdlərinin köməyi ilə həyata keçirmək", "Çatlamış və qırıq şüşələri dəyişmədən üzərinə adi şəffaf lent yapışdırıb saxlamaq", "Bütün pəncərə çərçivələrini qalın taxta lövhələrlə örtərək təbii işığı tam bağlamaq", "Şüşələrin bütöv, çatısız, möhkəm bərkidilmiş olmasını təmin etmək və qırıq şüşələri dərhal, təhlükəsizlik qaydalarına riayət etməklə yenisi ilə əvəzləmək"]'::jsonb, 'Şüşələrin bütöv, çatısız, möhkəm bərkidilmiş olmasını təmin etmək və qırıq şüşələri dərhal, təhlükəsizlik qaydalarına riayət etməklə yenisi ilə əvəzləmək', 'Düzgün cavab: E) Şüşələrin bütöv, çatısız, möhkəm bərkidilmiş olmasını təmin etmək və qırıq şüşəl', '', 24, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('6ea9ef69-b83f-424e-89c6-bb0ed7107ade', 'cec8a4cf-05af-4f17-820e-39238ecd83f8', 'ka', 'სკოლის შენობის შიდა ფანჯრებისა და კარების შემინვისას უსაფრთხოების რა მოთხოვნა წესდება?', '["შემინვისა და მონტაჟის სამუშაოების ჩატარება დაწყებითი კლასების მოსწავლეთა დახმარებით", "გატეხილი მინების ნაცვლად მუყაოს ან პოლიეთილენის საფარის აკვრით სეზონის დასრულება", "დაბზარული და გატეხილი მინების შეუცვლელად დატოვება და მათზე ჩვეულებრივი გამჭვირვალე წებოვანი ლენტის გადაკვრა", "ფანჯრის ყველა ჩარჩოს სქელი ხის ფიცრებით დაფარვა და ბუნებრივი სინათლის სრული ჩახერგვა", "მინების მთლიანობის, უბზარობის, მყარი დამაგრების (შტაპიკებით) უზრუნველყოფა და გატეხილი მინების დაუყოვნებლივ, უსაფრთხოების წესების დაცვით ახლით შეცვლა"]'::jsonb, 'მინების მთლიანობის, უბზარობის, მყარი დამაგრების (შტაპიკებით) უზრუნველყოფა და გატეხილი მინების დაუყოვნებლივ, უსაფრთხოების წესების დაცვით ახლით შეცვლა', 'Düzgün cavab: E) მინების მთლიანობის, უბზარობის, მყარი დამაგრების (შტაპიკებით) უზრუნველყოფა და გატ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d68072e4-29ac-4aa4-bd04-c0209164b06f', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təsərrüfat işlərinin aparılması üçün fəhlələrə fərdi mühafizə vasitələrinin verilməsi hansı əsasla həyata keçirilir?', 'multiple_choice', '["Fərdi mühafizə vasitələri (işçi forması, əlcək, xüsusi ayaqqabı, qoruyucu eynək, kaska) dövlət standartlarına və normalarına uyğun olaraq müəssisə tərəfindən pulsuz təmin edilməlidir", "Bütün xüsusi geyim və qoruyucu vasitələr işçinin öz şəxsi əməkhaqqı hesabına alınmalıdır", "Fəhlələr təhlükəli təmir işlərini heç bir qoruyucu vasitə olmadan icra etməyə borcludurlar", "Təhsil müəssisələrində xüsusi qoruyucu vasitələrin istifadəsi təhlükəsizlik qaydaları ilə qadağandır", "Mühafizə vasitələrinin alınması yalnız valideyn komitəsinin könüllü ianələri hesabına olmalıdır"]'::jsonb, 'Fərdi mühafizə vasitələri (işçi forması, əlcək, xüsusi ayaqqabı, qoruyucu eynək, kaska) dövlət standartlarına və normalarına uyğun olaraq müəssisə tərəfindən pulsuz təmin edilməlidir', 'Düzgün cavab: A) Fərdi mühafizə vasitələri (işçi forması, əlcək, xüsusi ayaqqabı, qoruyucu eynək,', '', 25, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('da5987dd-e530-4e44-9f02-b2cbc68bcca8', 'd68072e4-29ac-4aa4-bd04-c0209164b06f', 'ka', 'სამეურნეო სამუშაოების ჩასატარებლად მუშაკებისთვის ინდივიდუალური დაცვის საშუალებების მიწოდება ვისი მოვალეობაა?', '["ინდივიდუალური დაცვის საშუალებები (სამუშაო ფორმა, ხელთათმანები, სპეციალური ფეხსაცმელი, დამცავი სათვალე, ჩაფხუტი) სახელმწიფო სტანდარტებისა და ნორმების შესაბამისად უფასოდ უნდა უზრუნველყოს დაწესებულებამ", "საგანმანათლებლო დაწესებულებებში სპეციალური დამცავი საშუალებების გამოყენება აკრძალულია უსაფრთხოების წესებით", "მუშები ვალდებულნი არიან სახიფათო სარემონტო სამუშაოები შეასრულონ ყოველგვარი დამცავი საშუალებების გარეშე", "ყველა სპეცტანსაცმელი და დამცავი საშუალება შეძენილი უნდა იქნეს მუშაკის პირადი ხელფასის ხარჯზე", "დამცავი საშუალებების შეძენა უნდა განხორციელდეს მხოლოდ მშობელთა კომიტეტის ნებაყოფლობითი შემოწირულობების ხარჯზე"]'::jsonb, 'ინდივიდუალური დაცვის საშუალებები (სამუშაო ფორმა, ხელთათმანები, სპეციალური ფეხსაცმელი, დამცავი სათვალე, ჩაფხუტი) სახელმწიფო სტანდარტებისა და ნორმების შესაბამისად უფასოდ უნდა უზრუნველყოს დაწესებულებამ', 'Düzgün cavab: A) ინდივიდუალური დაცვის საშუალებები (სამუშაო ფორმა, ხელთათმანები, სპეციალური ფეხსაც', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('85c8ff8e-1f80-45a8-843f-5677b159fe18', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəb binasının fasadının və yağış novlarının təmizlənməsi zamanı hündürlükdə işləyən işçilər üçün hansı təhlükəsizlik qaydası məcburidir?', 'multiple_choice', '["İşçini yüksəklikdə təkbaşına buraxaraq aşağıda heç bir köməkçi və ya nəzarətçi təyin etməmək", "Hündürlükdə işləyən işçiyə əvvəlcədən təhlükəsizlik texnikası üzrə xüsusi təlimat keçməmək", "Təmizləmə və təmir işlərini yalnız güclü küləkli, qasırğalı və ya buzlaşma olan hava şəraitində aparmaq", "Qoruyucu kəmərdən, dəbilqədən (kaskadan), etibarlı nərdivan, iskele və ya avtoqaldırıcıdan istifadə etmək, təlimatlandırmaq və aşağıda nəzarətçi və hasarlama qoymaq", "Hündürlükdə işləri heç bir fərdi qoruyucu kəmər və dayaq vasitəsi olmadan sərbəst icra etmək"]'::jsonb, 'Qoruyucu kəmərdən, dəbilqədən (kaskadan), etibarlı nərdivan, iskele və ya avtoqaldırıcıdan istifadə etmək, təlimatlandırmaq və aşağıda nəzarətçi və hasarlama qoymaq', 'Düzgün cavab: D) Qoruyucu kəmərdən, dəbilqədən (kaskadan), etibarlı nərdivan, iskele və ya avtoqa', '', 26, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('fa5ed8e2-5d3f-48e1-9ef9-59ad6673cd68', '85c8ff8e-1f80-45a8-843f-5677b159fe18', 'ka', 'სკოლის შენობის ფასადისა და წვიმის წყალსაწრეტების გაწმენდისას სიმაღლეზე მომუშავე მუშაკებისთვის უსაფრთხოების რომელი წესია სავალდებულო?', '["გაწმენდისა და შეკეთების სამუშაოების ჩატარება მხოლოდ ძლიერი ქარის, ქარიშხლის ან მოყინვის ამინდში", "მუშაკის სიმაღლეზე მარტო დატოვება და ქვევით არცერთი დამხმარის ან მეთვალყურის არდანიშვნა", "სიმაღლეზე სამუშაოების თავისუფლად შესრულება ყოველგვარი ინდივიდუალური დამცავი ქამრისა და საყრდენი საშუალების გარეშე", "დამცავი ქამრის, ჩაფხუტის, საიმედო კიბის, ხარაჩოს ან ავტოამწის გამოყენება, ინსტრუქტაჟის ჩატარება და ქვევით მეთვალყურის დაყენება და შემოღობვა", "სიმაღლეზე მომუშავე მუშაკისთვის წინასწარ უსაფრთხოების ტექნიკის სპეციალური ინსტრუქტაჟის არჩატარება"]'::jsonb, 'დამცავი ქამრის, ჩაფხუტის, საიმედო კიბის, ხარაჩოს ან ავტოამწის გამოყენება, ინსტრუქტაჟის ჩატარება და ქვევით მეთვალყურის დაყენება და შემოღობვა', 'Düzgün cavab: D) დამცავი ქამრის, ჩაფხუტის, საიმედო კიბის, ხარაჩოს ან ავტოამწის გამოყენება, ინსტრუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d291b9e7-99dd-4b17-86bd-f1982a8f9513', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Müəssisənin illik cari təmir işlərinin planlaşdırılmasında təsərrüfat müdiri hansı ilkin sənədi hazırlayır?', 'multiple_choice', '["Şagirdlərin həftəlik dərs cədvəli və imtahan sessiyası planı", "Təmir tələb olunan sahələrin Qüsur Aktı (Defekt cədvəli) və tələbat smetası, material siyahısı və iş həcmi cədvəli", "Məktəb rəhbərinin illik fəaliyyət hesabatı və fərdi xasiyyətnaməsi", "Pedaqoji kollektivin illik məzuniyyət qrafiki və əvəzetmə cədvəli", "Kitabxana fondunun illik oxucu qeydiyyatı və abunə reyestri"]'::jsonb, 'Təmir tələb olunan sahələrin Qüsur Aktı (Defekt cədvəli) və tələbat smetası, material siyahısı və iş həcmi cədvəli', 'Düzgün cavab: B) Təmir tələb olunan sahələrin Qüsur Aktı (Defekt cədvəli) və tələbat smetası, mat', '', 27, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('77038338-75ee-41a6-9ea9-3d6a76097b86', 'd291b9e7-99dd-4b17-86bd-f1982a8f9513', 'ka', 'დაწესებულების წლიური მიმდინარე სარემონტო სამუშაოების დაგეგმვისას რა პირველად დოკუმენტს ამზადებს სამეურნეო ნაწილის გამგე?', '["სკოლის ხელმძღვანელის წლიურ ანგარიშსა და ინდივიდუალურ დახასიათებას", "შესაკეთებელი უბნების დეფექტურ აქტს (დეფექტურ უწყისს), მოთხოვნის ხარჯთაღრიცხვას, მასალების ჩამონათვალსა და სამუშაოთა მოცულობის უწყისს", "პედაგოგიური კოლექტივის წლიურ შვებულებათა გრაფიკსა და შეცვლის ცხრილს", "მოსწავლეთა ყოველკვირეულ გაკვეთილების ცხრილსა და საგამოცდო სესიის გეგმას", "საბიბლიოთეკო ფონდის წლიურ მკითხველთა რეგისტრაციასა და გამოწერის რეესტრს"]'::jsonb, 'შესაკეთებელი უბნების დეფექტურ აქტს (დეფექტურ უწყისს), მოთხოვნის ხარჯთაღრიცხვას, მასალების ჩამონათვალსა და სამუშაოთა მოცულობის უწყისს', 'Düzgün cavab: B) შესაკეთებელი უბნების დეფექტურ აქტს (დეფექტურ უწყისს), მოთხოვნის ხარჯთაღრიცხვას,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e32f050e-5f03-4776-958f-22c93db7fc36', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Məktəbdə tullantıların toplanması və daşınması qaydası necə təşkil edilməlidir?', 'multiple_choice', '["Tullantıların daşınmasını tədris ili boyunca dayandıraraq yalnız yay tətilində icra etmək", "Tullantıları məktəb binasının daxili dəhlizlərində və pilləkən qəfəslərində açıq şəkildə toplamaq", "Zibil qutularını bilavasitə məktəbin əsas giriş qapısının və yeməkxana pəncərəsinin önünə qoymaq", "Tullantıları qapaqlı konteynerlərdə, xüsusi ayrılmış meydançada, binadan 15–20 metr aralı, sərt örtüklü yerdə yerləşdirmək və vaxtında, müqavilə əsasında daşınmasını təmin etmək", "Bütün məişət tullantılarını məktəbin həyətyanı sahəsində açıq tonqallarda yandırmaq"]'::jsonb, 'Tullantıları qapaqlı konteynerlərdə, xüsusi ayrılmış meydançada, binadan 15–20 metr aralı, sərt örtüklü yerdə yerləşdirmək və vaxtında, müqavilə əsasında daşınmasını təmin etmək', 'Düzgün cavab: D) Tullantıları qapaqlı konteynerlərdə, xüsusi ayrılmış meydançada, binadan 15–20 m', '', 28, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4c41a3ec-3114-4d1e-83b7-292326504827', 'e32f050e-5f03-4776-958f-22c93db7fc36', 'ka', 'როგორ უნდა იყოს ორგანიზებული სკოლაში ნარჩენების შეგროვებისა და გატანის წესი?', '["ნაგვის ურნების განთავსება უშუალოდ სკოლის მთავარი შესასვლელი კარის და სასადილოს ფანჯრის წინ", "ნარჩენების ღიად შეგროვება სკოლის შენობის შიდა დერეფნებსა და კიბის უჯრედებში", "ყველა საყოფაცხოვრებო ნარჩენის დაწვა სკოლის ეზოს ტერიტორიაზე ღია კოცონებზე", "ნარჩენების განთავსება თავსახურიან კონტეინერებში, სპეციალურად გამოყოფილ, მყარსაფარიან მოედანზე შენობიდან 15-20 მეტრის დაშორებით და მათი დროული გატანა ხელშეკრულების საფუძველზე", "ნარჩენების გატანის შეჩერება მთელი სასწავლო წლის განმავლობაში და მხოლოდ ზაფხულის არდადეგებზე გატანა"]'::jsonb, 'ნარჩენების განთავსება თავსახურიან კონტეინერებში, სპეციალურად გამოყოფილ, მყარსაფარიან მოედანზე შენობიდან 15-20 მეტრის დაშორებით და მათი დროული გატანა ხელშეკრულების საფუძველზე', 'Düzgün cavab: D) ნარჩენების განთავსება თავსახურიან კონტეინერებში, სპეციალურად გამოყოფილ, მყარსაფა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('cab781f6-0445-4a92-9277-4fef20d82438', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təsərrüfat müdirinin iş yerində və xidməti fəaliyyətində etik davranış standartlarına hansı addım uyğundur?', 'multiple_choice', '["Təmir üçün ayrılmış inşaat və rəngsazlıq materiallarının kənar şəxslərə qanunsuz satışını təşkil etmək", "Məktəb təsərrüfatına aid əsas vəsaitləri və alətləri şəxsi məqsədlər üçün evdə istifadə etmək", "Dövlət əmlakına qayğı ilə yanaşmaq, dürüst, şəffaf və məsuliyyətli olmaq, kollektivlə peşəkar əməkdaşlıq etmək, israfçılığa yol verməmək", "Xidmətedici heyətə və təhsilalanlara qarşı kobud, alçaldıcı və qeyri-etik rəftar nümayiş etdirmək", "Rəhbərliyin qanunvericiliyə uyğun xidməti tapşırıqlarını icra etməkdən əsassız imtina etmək"]'::jsonb, 'Dövlət əmlakına qayğı ilə yanaşmaq, dürüst, şəffaf və məsuliyyətli olmaq, kollektivlə peşəkar əməkdaşlıq etmək, israfçılığa yol verməmək', 'Düzgün cavab: C) Dövlət əmlakına qayğı ilə yanaşmaq, dürüst, şəffaf və məsuliyyətli olmaq, kollek', '', 29, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('237ac560-92d5-484a-b667-e0529e49fba5', 'cab781f6-0445-4a92-9277-4fef20d82438', 'ka', 'სამუშაო ადგილზე და სამსახურებრივ საქმიანობაში ეთიკური ქცევის სტანდარტებს რომელი ქმედება შეესაბამება?', '["მომსახურე პერსონალისა და მოსწავლეების მიმართ უხეში, დამამცირებელი და არაეთიკური მოპყრობის გამოვლენა", "სკოლის მეურნეობის ძირითადი საშუალებებისა და ხელსაწყოების პირადი მიზნებისთვის სახლში გამოყენება", "სახელმწიფო ქონებისადმი გაფრთხილება, პატიოსნება, გამჭვირვალობა და პასუხისმგებლობა, კოლექტივთან პროფესიული თანამშრომლობა, მფლანგველობის დაუშვებლობა", "ხელმძღვანელობის კანონშესაბამისი სამსახურებრივი დავალებების შესრულებაზე დაუსაბუთებელი უარის თქმა", "რემონტისთვის გამოყოფილი სამშენებლო და სამღებრო მასალების გარეშე პირებზე უკანონო გაყიდვის ორგანიზება"]'::jsonb, 'სახელმწიფო ქონებისადმი გაფრთხილება, პატიოსნება, გამჭვირვალობა და პასუხისმგებლობა, კოლექტივთან პროფესიული თანამშრომლობა, მფლანგველობის დაუშვებლობა', 'Düzgün cavab: C) სახელმწიფო ქონებისადმი გაფრთხილება, პატიოსნება, გამჭვირვალობა და პასუხისმგებლობა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b988db65-6acf-4dd1-bf6e-6866a96dcd37', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Təhsil müəssisəsində baş vermiş bədbəxt hadisə və ya qəza zamanı təsərrüfat müdiri dərhal hansı addımı atmalıdır?', 'multiple_choice', '["Zədələnmiş avadanlıqları müayinə etmədən dərhal sənədsiz şəkildə kənarlaşdırmaq", "Təxirəsalınmaz təhlükəsizlik tədbirləri görmək, hadisə yerini mühafizə etmək, ilk yardım göstərmək, təcili yardım çağırmaq və rəhbərliyə təcili məlumat vermək, akt tərtib etmək", "Qəza baş verən sahəni təcrid etmədən təhsilalanların sərbəst hərəkətinə icazə vermək", "Yalnız növbəti təqvim ayında müvafiq təmir-bərpa komissiyasının yaradılmasını təklif etmək", "Hadisə barədə heç bir rəsmi qeydiyyat aparmayaraq nəticələri gizlətməyə çalışmaq"]'::jsonb, 'Təxirəsalınmaz təhlükəsizlik tədbirləri görmək, hadisə yerini mühafizə etmək, ilk yardım göstərmək, təcili yardım çağırmaq və rəhbərliyə təcili məlumat vermək, akt tərtib etmək', 'Düzgün cavab: B) Təxirəsalınmaz təhlükəsizlik tədbirləri görmək, hadisə yerini mühafizə etmək, il', '', 30, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7f818f9d-6e36-4f81-80c6-70c8624d4c9e', 'b988db65-6acf-4dd1-bf6e-6866a96dcd37', 'ka', 'საგანმანათლებლო დაწესებულებაში მომხდარი უბედური შემთხვევის ან ავარიის დროს რა ნაბიჯი უნდა გადადგას სამეურნეო ნაწილის გამგემ დაუყოვნებლივ?', '["ავარიის ადგილის იზოლირების გარეშე მოსწავლეთა თავისუფალი გადაადგილების დაშვება", "გადაუდებელი უსაფრთხოების ზომების მიღება, შემთხვევის ადგილის დაცვა, პირველადი დახმარების აღმოჩენა, სასწრაფო დახმარების გამოძახება, ხელმძღვანელობისთვის სასწრაფო შეტყობინება და აქტის შედგენა", "შემთხვევის შესახებ ყოველგვარი ოფიციალური აღრიცხვის გარეშე შედეგების დამალვის მცდელობა", "მხოლოდ მომდევნო კალენდარულ თვეში შესაბამისი სარემონტო-აღდგენითი კომისიის შექმნის შეთავაზება", "დაზიანებული მოწყობილობების შემოწმების გარეშე დაუყოვნებლივ, უდოკუმენტოდ მოცილება"]'::jsonb, 'გადაუდებელი უსაფრთხოების ზომების მიღება, შემთხვევის ადგილის დაცვა, პირველადი დახმარების აღმოჩენა, სასწრაფო დახმარების გამოძახება, ხელმძღვანელობისთვის სასწრაფო შეტყობინება და აქტის შედგენა', 'Düzgün cavab: B) გადაუდებელი უსაფრთხოების ზომების მიღება, შემთხვევის ადგილის დაცვა, პირველადი დახ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bb1309bb-994e-4806-b281-f3e9dbff38e8', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Azərbaycan Respublikası Konstitusiyasının 42-ci maddəsinə əsasən, vətəndaşların təhsil hüququ ilə bağlı dövlətin əsas təminatı nədir?', 'multiple_choice', '["Dövlət hər bir vətəndaşın ali təhsil almasını məcburi edir və təhsil xərclərini tam şəkildə kommersiya banklarına həvalə edir", "Dövlət yalnız əlaçı şagirdlərin pulsuz təhsil almasını təmin edir və digər vətəndaşlara ödənişli əsaslarla şərait yaradır", "Dövlət təhsil sistemində bütün pillələrin tamamilə ödənişli əsaslarla təşkil edilməsini qanunvericiliklə tənzimləyir", "Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir", "Dövlət yalnız dövlət qulluqçularının övladlarının pulsuz orta ixtisas təhsili almasına hüquqi zəmanət verir"]'::jsonb, 'Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir', 'Düzgün cavab: D) Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin e', '', 31, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ea91919d-d02c-424f-a916-00a324ee72cc', 'bb1309bb-994e-4806-b281-f3e9dbff38e8', 'ka', 'კონსტიტუციის 42-ე მუხლის თანახმად, განათლების უფლების უზრუნველყოფასთან დაკავშირებით რომელი დებულებაა განმტკიცებული?', '["სახელმწიფო მხოლოდ ნიჭიერი პირების მიერ განათლების გაგრძელების გარანტიას იძლევა მათი მატერიალური მდგომარეობის მიუხედავად", "სახელმწიფო ყველა მოქალაქეს უზრუნველყოფს სახელმწიფო უმაღლეს სასწავლებლებში უფასო სრული უმაღლესი განათლების მიღების უფლებით", "სახელმწიფო სავალდებულოდ მიიჩნევს მოქალაქეთა მიერ საშუალო პროფესიული განათლების მიღებას მხოლოდ დასწრებული ფორმით", "სახელმწიფო უზრუნველყოფს ყოველი მოქალაქის უფლებას უფასო სავალდებულო საბაზო განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და განათლების სისტემაზე სახელმწიფო კონტროლს", "სახელმწიფო საგანმანათლებლო დაწესებულებების დაფინანსებას ახორციელებს მხოლოდ მუნიციპალიტეტების ადგილობრივი ბიუჯეტების ხარჯზე"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყოველი მოქალაქის უფლებას უფასო სავალდებულო საბაზო განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და განათლების სისტემაზე სახელმწიფო კონტროლს', 'Düzgün cavab: D) სახელმწიფო უზრუნველყოფს ყოველი მოქალაქის უფლებას უფასო სავალდებულო საბაზო განათლ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('13a3fbf7-cc7a-4e88-a261-a62eaefdbe47', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Azərbaycan Respublikası Konstitusiyasının 25-ci maddəsinə əsasən, bərabərlik hüququnun təhsil və əmək münasibətlərində təminatı necə müəyyən olunmuşdur?', 'multiple_choice', '["İşə qəbul və təhsil prosesində yalnız rəhbərliyin subyektiv mülahizələri əsas götürülür və imtiyazlar müəyyən edilir", "Sosial mənşəyindən və yaşayış yerindən asılı olaraq təhsil müəssisələrinə qəbulda məhdudiyyətlər qoyula bilər", "Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir", "Vətəndaşların hüquq bərabərliyi yalnız dövlət qulluğunda çalışan şəxslərə şamil edilir, digər sahələrdə fərqli münasibət qanunidir", "Ayrı-seçkiliyə yalnız müəssisə rəhbərinin yazılı əmri və daxili nizamnamə tələbləri ilə yol verilə bilər"]'::jsonb, 'Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir', 'Düzgün cavab: C) Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyin', '', 32, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('080e2a4b-c85a-4c4b-bf2b-9b31e4c914be', '13a3fbf7-cc7a-4e88-a261-a62eaefdbe47', 'ka', 'კონსტიტუციის 25-ე მუხლის თანახმად, რომელია სწორი ნორმა, რომელიც ასახავს თანასწორობის უფლების შინაარსს?', '["ადამიანისა და მოქალაქის უფლებები უზრუნველყოფილია მხოლოდ მოქალაქის კერძო საკუთრების მოცულობიდან გამომდინარე", "თანასწორობის უფლება არეგულირებს მხოლოდ 18 წელს მიღწეულ მოქალაქეთა მონაწილეობას საარჩევნო პროცესში", "სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესისა და სოციალური წარმოშობის მიუხედავად", "სახელმწიფო მხოლოდ საჯარო მოხელეებისთვის ადგენს სასამართლოს წინაშე სპეციალურ პრივილეგირებულ თანასწორობის უფლებას", "თითოეულის უფლებები და თავისუფლებები თანასწორად ითვლება მხოლოდ აღმასრულებელი ხელისუფლების ორგანოს თანხმობის შემთხვევაში"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესისა და სოციალური წარმოშობის მიუხედავად', 'Düzgün cavab: C) სახელმწიფო უზრუნველყოფს ყველას უფლებებისა და თავისუფლებების თანასწორობას რასის,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fbd4ea76-d3e8-484a-859a-8f2375352fb6', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Azərbaycan Respublikası Konstitusiyasının 32-ci maddəsinə əsasən, şəxsi toxunulmazlıq hüququ təhsil müəssisəsində hansı tələbi irəli sürür?', 'multiple_choice', '["İşçilərin fərdi məlumatları və tibbi arayışları kollektiv qarşısında müzakirə edilməli və elan lövhəsinə vurulmalıdır", "Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir", "Təhsil müəssisəsi rəhbərliyi işçilərin şəxsi məlumatlarını istədiyi məqsədlə kənar şəxslərə və sosial şəbəkələrə açıqlaya bilər", "Şəxsin yazışma və telefon danışıqlarının sirri yalnız daxili intizam qaydaları ilə məhdudlaşdırıla bilər", "Fərdi məlumatların informasiya sistemlərində qeydiyyatı şəxsin xəbəri olmadan istənilən qurum tərəfindən aparıla bilər"]'::jsonb, 'Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir', 'Düzgün cavab: B) Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılması', '', 33, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ef12871b-52f3-4d80-811a-862d6a66fd86', 'fbd4ea76-d3e8-484a-859a-8f2375352fb6', 'ka', 'კონსტიტუციის 32-ე მუხლის თანახმად, რა წესია დადგენილი პირადი ხელშეუხებლობის უფლებასთან დაკავშირებით?', '["პერსონალური მონაცემების რეგისტრაცია საინფორმაციო სისტემებში პირის შეუტყობინებლად ნებისმიერ უწყებას შეუძლია განახორციელოს", "მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა და გავრცელება დაუშვებელია, გარდა კანონით დადგენილი შემთხვევებისა", "საგანმანათლებლო დაწესებულების ხელმძღვანელობას შეუძლია საზოგადოებას თავისუფლად წარუდგინოს ინფორმაცია დასაქმებულის პირადი ცხოვრების შესახებ", "პირადი ხელშეუხებლობის უფლება ძალაშია მხოლოდ იმ სამუშაო დროის განმავლობაში, როდესაც პირი სამუშაო ადგილზე ასრულებს სამსახურებრივ მოვალეობებს", "პირის მიმოწერისა და სატელეფონო საუბრების საიდუმლოება შეიძლება შეიზღუდოს მხოლოდ შინაგანაწესით"]'::jsonb, 'მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა და გავრცელება დაუშვებელია, გარდა კანონით დადგენილი შემთხვევებისა', 'Düzgün cavab: B) მოქალაქის თანხმობის გარეშე მისი პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('006e9c8b-945c-4f63-bd0c-b17567f9ca1c', 'cc5a9152-038e-4e28-a998-92078ee3e505', '“Təhsil haqqında” AR Qanununun 3-cü maddəsinə əsasən, dövlət siyasətinin əsas prinsiplərindən olan ''Humanistlik'' nəyi ifadə edir?', 'multiple_choice', '["Təhsil prosesinin milli və beynəlxalq standartların tələblərinə uyğunlaşdırılmasını", "Təhsil sisteminin dünya təhsil məkanına çevik inteqrasiya olunmasını", "Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını", "Təhsil müəssisələrinin idarə edilməsində ictimaiyyətin iştirakını", "Bütün vətəndaşların fasiləsiz olaraq ömür boyu peşəkar təhsil almaq imkanını"]'::jsonb, 'Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını', 'Düzgün cavab: C) Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və', '', 34, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('481272cf-c7c5-4462-8051-f5b126612949', '006e9c8b-945c-4f63-bd0c-b17567f9ca1c', 'ka', '„განათლების შესახებ“ კანონის მე-3 მუხლის თანახმად, რას გამოხატავს „ჰუმანურობა“?', '["სასწავლო პროცესის მისადაგებას ეროვნული და საერთაშორისო სტანდარტების მოთხოვნებთან", "ყველა მოქალაქის შესაძლებლობას უწყვეტად, მთელი სიცოცხლის მანძილზე მიიღოს პროფესიული განათლება", "ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას", "საზოგადოების მონაწილეობას საგანმანათლებლო დაწესებულებების მართვაში", "განათლების სისტემის მოქნილ ინტეგრაციას მსოფლიო საგანმანათლებლო სივრცეში"]'::jsonb, 'ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების პრიორიტეტად აღიარებას', 'Düzgün cavab: C) ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('48ede316-d61d-494c-8e26-ac629aa2402f', 'cc5a9152-038e-4e28-a998-92078ee3e505', '“Təhsil haqqında” AR Qanununun 12-ci maddəsinə əsasən, təsbit edilmiş təhsil formaları hansılardır?', 'multiple_choice', '["İbtidai təhsil, əsas təhsil və tam orta təhsil", "Əyani, qiyabi, distant və sərbəst təhsilalma", "Dövlət təhsili, bələdiyyə təhsili və xüsusi təhsil", "Məktəbəqədər, ümumi orta, ilk peşə və ali təhsil", "Formal, qeyri-formal və informal təhsil"]'::jsonb, 'Formal, qeyri-formal və informal təhsil', 'Düzgün cavab: E) Formal, qeyri-formal və informal təhsil', '', 35, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('28477fb2-a204-49bb-b776-62844bb55de5', '48ede316-d61d-494c-8e26-ac629aa2402f', 'ka', '„განათლების შესახებ“ კანონის მე-12 მუხლის თანახმად, რომელია განსაზღვრული განათლების ფორმები?', '["სახელმწიფო განათლება, მუნიციპალური განათლება და სპეციალური განათლება", "სკოლამდელი, საბაზო, პირველადი პროფესიული და უმაღლესი განათლება", "დაწყებითი განათლება, საბაზო განათლება და სრული ზოგადი განათლება", "დასწრებული, დაუსწრებელი, დისტანციური და ექსტერნატი განათლების მიღების ფორმა", "ფორმალური, არაფორმალური და ინფორმალური განათლება"]'::jsonb, 'ფორმალური, არაფორმალური და ინფორმალური განათლება', 'Düzgün cavab: E) ფორმალური, არაფორმალური და ინფორმალური განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('803d397c-a67a-45a2-a0ea-e3351b3c87ab', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Müxtəlif səbəblərdən ümumi təhsildən kənarda qalmış şəxslərə təhsil almaq və ya təhsilin hər hansı pilləsini vaxtından əvvəl bitirmək hüququ verən təhsilalma forması hansıdır?', 'multiple_choice', '["Qiyabi təhsilalma", "İnformal təhsil", "Distant (məsafədən) təhsilalma", "Evdə təhsilalma", "Sərbəst (eksternat) təhsilalma forması"]'::jsonb, 'Sərbəst (eksternat) təhsilalma forması', 'Düzgün cavab: E) Sərbəst (eksternat) təhsilalma forması', '', 36, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9a55e76f-351d-4653-9f47-56f01fdb2a46', '803d397c-a67a-45a2-a0ea-e3351b3c87ab', 'ka', 'რომელი ფორმა ანიჭებს განათლების მიღების უფლებას პირებს, რომლებიც სხვადასხვა მიზეზის გამო დარჩნენ ზოგადი განათლების მიღმა?', '["დაუსწრებელი სწავლება", "ინფორმალური განათლება", "დისტანციური სწავლება", "შინ სწავლება", "ექსტერნატის (თავისუფალი) სწავლების ფორმა"]'::jsonb, 'ექსტერნატის (თავისუფალი) სწავლების ფორმა', 'Düzgün cavab: E) ექსტერნატის (თავისუფალი) სწავლების ფორმა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('00794cbf-2c81-4cb7-8cf3-919e133f4e61', 'cc5a9152-038e-4e28-a998-92078ee3e505', '“Təhsil haqqında” AR Qanununun 32-ci maddəsinə əsasən, təhsilverənlərin vəzifələrinə aid olan müddəa hansıdır?', 'multiple_choice', '["İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri və müasir texnologiyaları mənimsəyərək tədris prosesində tətbiq etmək", "Təhsil müəssisəsinin idarə olunmasında təkliflərlə çıxış etmək", "Şərəf və ləyaqətinə hörmətlə yanaşılmasını və təhlükəsiz iş şəraitini tələb etmək", "Təhsil müəssisəsində müvafiq vəzifə tutmaq və seçkili orqanlarda təmsil olunmaq", "Yeni tədris proqramlarını və dərslik layihələrini sərbəst şəkildə seçmək"]'::jsonb, 'İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri və müasir texnologiyaları mənimsəyərək tədris prosesində tətbiq etmək', 'Düzgün cavab: A) İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri və müasir texnologiyaları mən', '', 37, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('40eef2e1-bdf5-40fe-afdb-388b1d18c77a', '00794cbf-2c81-4cb7-8cf3-919e133f4e61', 'ka', '„განათლების შესახებ“ კანონის 32-ე მუხლის თანახმად, რომელი დებულება განეკუთვნება პედაგოგთა (განმანათლებელთა) მოვალეობებს?', '["კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლოგიების ათვისება და სასწავლო პროცესში გამოყენება", "პატივისა და ღირსებისადმი პატივისცემისა და უსაფრთხო სამუშაო პირობების მოთხოვნა", "საგანმანათლებლო დაწესებულებაში შესაბამისი თანამდებობის დაკავება და არჩევით ორგანოებში წარმოდგენა", "ახალი სასწავლო პროგრამებისა და სახელმძღვანელოების პროექტების თავისუფლად არჩევა", "საგანმანათლებლო დაწესებულების მართვაში წინადადებებით გამოსვლა"]'::jsonb, 'კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლოგიების ათვისება და სასწავლო პროცესში გამოყენება', 'Düzgün cavab: A) კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('31a5743f-c0e2-40b4-8b22-37c83d853a70', 'cc5a9152-038e-4e28-a998-92078ee3e505', '“Ümumi təhsil haqqında” AR Qanununa əsasən, ümumi təhsil pilləsinin səviyyələri hansı ardıcıllıqla düzgün göstərilmişdir?', 'multiple_choice', '["İbtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və peşə təhsili səviyyəsi", "İbtidai təhsil (I–IV), əsas təhsil (V–VIII) və orta ixtisas təhsili (IX–XI)", "Məktəbəqədər təhsil (3–5 yaş), ümumi təhsil (I–XI) və bakalavriat səviyyəsi", "Yalnız ümumi orta təhsil (I–IX) və tam orta təhsil (X–XI)", "Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)"]'::jsonb, 'Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)', 'Düzgün cavab: E) Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və ta', '', 38, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cb155f40-5e78-4b94-b6a3-5350c6fea901', '31a5743f-c0e2-40b4-8b22-37c83d853a70', 'ka', '„ზოგადი განათლების შესახებ“ კანონის თანახმად, რომელია ზოგადი განათლების საფეხურის დონეები (საფეხურები)?', '["მხოლოდ საბაზო განათლება (I–IX) და სრული საშუალო განათლება (X–XI)", "დაწყებითი განათლება (I–IV), საბაზო განათლება (V–VIII) და საშუალო სპეციალური განათლება (IX–XI)", "დაწყებითი განათლება (I–IV), საბაზო განათლება (V–IX) და პროფესიული განათლების საფეხური", "სკოლამდელი განათლება (3–5 წელი), ზოგადი განათლება (I–XI) და ბაკალავრიატის საფეხური", "სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო განათლება (V–IX) და სრული საშუალო განათლება (X–XI)"]'::jsonb, 'სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო განათლება (V–IX) და სრული საშუალო განათლება (X–XI)', 'Düzgün cavab: E) სასკოლო მზაობის ეტაპი, დაწყებითი განათლება (I–IV), საბაზო განათლება (V–IX) და სრ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('addd3d04-7b33-4f51-b644-046195ba20d3', 'cc5a9152-038e-4e28-a998-92078ee3e505', '“Ümumi təhsil haqqında” AR Qanununun 21-ci maddəsinə əsasən, təhsilalanların hüquqlarına **AİD EDİLMƏYƏN** müddəa hansıdır?', 'multiple_choice', '["Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq", "İnsan ləyaqətini alçaldan zorakılıq hallarından müdafiə olunmaq", "Təhsil müəssisəsinin mövcud infrastrukturundan ödənişsiz istifadə etmək", "Həyat və sağlamlıq üçün təhlükəsiz təhsil şəraiti ilə təmin olunmaq", "Dövlət və bələdiyyə məktəblərində dərsliklərlə pulsuz təmin olunmaq"]'::jsonb, 'Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq', 'Düzgün cavab: A) Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoj', '', 39, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8d6d0f6e-01f4-497d-9fc0-a3f8136e4d90', 'addd3d04-7b33-4f51-b644-046195ba20d3', 'ka', '„ზოგადი განათლების შესახებ“ კანონის 21-ე მუხლის თანახმად, რომელი დებულება არ მიეკუთვნება მოსწავლეთა უფლებებს?', '["დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება", "სახელმწიფო და მუნიციპალურ სკოლებში სახელმძღვანელოებით უფასო უზრუნველყოფა", "სიცოცხლისა და ჯანმრთელობისთვის უსაფრთხო საგანმანათლებლო გარემოთი უზრუნველყოფა", "საგანმანათლებლო დაწესებულების არსებული ინფრასტრუქტურით უფასო სარგებლობა", "ადამიანის ღირსების შემლახველი ძალადობის შემთხვევებისგან დაცვა"]'::jsonb, 'დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება', 'Düzgün cavab: A) დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('052a9c25-4344-454c-93d8-effcb0e85dd4', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Dövlət və bələdiyyə ümumi təhsil müəssisələrinin Nümunəvi Nizamnaməsinə əsasən, məktəbin fəaliyyətinə cari rəhbərliyi kim həyata keçirir?', 'multiple_choice', '["Təhsil müəssisəsinin Həmkarlar İttifaqı Komitəsinin rəhbəri", "Rayon İcra Hakimiyyətinin təyin etdiyi xüsusi nümayəndə", "Müəssisənin Pedaqoji Şurasının seçkili katibi", "Məktəbin Valideyn-Müəllim Assosiasiyasının idarə heyətinin sədri", "Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən vəzifəyə təyin olunan direktor"]'::jsonb, 'Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən vəzifəyə təyin olunan direktor', 'Düzgün cavab: E) Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən vəzifəyə t', '', 40, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('47dfe3a4-a7f0-4846-93f3-32dfeaa95394', '052a9c25-4344-454c-93d8-effcb0e85dd4', 'ka', 'სანიმუშო წესდების თანახმად, ვინ ახორციელებს სკოლის საქმიანობის მიმდინარე ხელმძღვანელობას?', '["დაწესებულების პედაგოგიური საბჭოს არჩეული მდივანი", "რაიონული აღმასრულებელი ხელისუფლების მიერ დანიშნული სპეციალური წარმომადგენელი", "სკოლის მშობელთა და მასწავლებელთა ასოციაციის გამგეობის თავმჯდომარე", "საგანმანათლებლო დაწესებულების პროფკავშირის კომიტეტის ხელმძღვანელი", "შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექტორი"]'::jsonb, 'შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექტორი', 'Düzgün cavab: E) შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e9a65921-c271-466f-8a1a-d3667f3581a6', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Ümumi təhsil müəssisələrində Pedaqoji Şura haqqında Əsasnaməyə əsasən, qərarların qəbul edilməsi qaydası necədir?', 'multiple_choice', '["Qərarlar yalnız məktəb direktorunun fərdi şifahi razılığı ilə qüvvəyə minir", "İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilərək direktorun əmri ilə rəsmiləşdirilir", "Qərarlar yalnız rayon təhsil sektorunun yazılı razılığı alındıqdan sonra tətbiq edilir", "İclasda yalnız metodbirləşmə rəhbərləri səsvermə hüququna malikdir", "Pedaqoji Şuranın qərarları tövsiyə xarakteri daşıyır və rəsmi əmrlə təsdiqlənmir"]'::jsonb, 'İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilərək direktorun əmri ilə rəsmiləşdirilir', 'Düzgün cavab: B) İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qəra', '', 41, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('eb3bf701-363b-41be-9c5c-2c0703d87382', 'e9a65921-c271-466f-8a1a-d3667f3581a6', 'ka', 'პედაგოგიური საბჭოს შესახებ დებულების თანახმად, როგორია გადაწყვეტილებების მიღების წესი?', '["პედაგოგიური საბჭოს გადაწყვეტილებებს აქვს სარეკომენდაციო ხასიათი და არ მტკიცდება ოფიციალური ბრძანებით", "სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით", "გადაწყვეტილებები გამოიყენება მხოლოდ რაიონული საგანმანათლებლო სექტორის წერილობითი თანხმობის მიღების შემდეგ", "გადაწყვეტილებები ძალაში შედის მხოლოდ სკოლის დირექტორის ინდივიდუალური ზეპირი თანხმობით", "სხდომაზე კენჭისყრის უფლება აქვთ მხოლოდ საგნობრივი კათედრების (მეთოდგაერთიანებების) ხელმძღვანელებს"]'::jsonb, 'სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით', 'Düzgün cavab: B) სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('bbaf9276-e157-402b-a340-bd87275a231a', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Azərbaycan Respublikasının Əmək Məcəlləsinin 89 və 91-ci maddələrinə əsasən, iş vaxtının normal və qısaldılmış müddəti necədir?', 'multiple_choice', '["Həftəlik normal iş vaxtı 36 saat, hamilə qadınlar üçün 24 saat müəyyən edilir", "Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz", "Bütün işçilər üçün vahid həftəlik 40 saatlıq tam iş vaxtı tətbiq olunur", "Həftəlik normal iş vaxtı 45 saat, pedaqoji heyət üçün 18 saatdan çox ola bilməz", "Həftəlik normal iş vaxtı 48 saat, 16 yaşınadək işçilər üçün 36 saatdan çox ola bilməz"]'::jsonb, 'Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz', 'Düzgün cavab: B) Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün i', '', 42, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e5de2cec-02e0-405c-a654-72b5a6527f95', 'bbaf9276-e157-402b-a340-bd87275a231a', 'ka', 'შრომის კოდექსის 89-ე და 91-ე მუხლების თანახმად, როგორია სამუშაო დროის ნორმალური და შემოკლებული ხანგრძლივობა?', '["ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 48 საათს, ხოლო 16 წლამდე ასაკის მუშაკებისთვის — 36 საათს", "ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის — კვირაში 36 საათს", "ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 45 საათს, ხოლო პედაგოგიური პერსონალისთვის — 18 საათს", "ყოველკვირეული ნორმალური სამუშაო დრო განისაზღვრება 36 საათით, ხოლო ორსული ქალებისთვის — 24 საათით", "ყველა მუშაკისთვის გამოიყენება ერთიანი ყოველკვირეული 40-საათიანი სრული სამუშაო დრო"]'::jsonb, 'ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შეზღუდული შესაძლებლობის მქონე პირებისთვის — კვირაში 36 საათს', 'Düzgün cavab: B) ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c065db35-8dcf-406b-b47d-5af689b453a1', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Əmək Məcəlləsinin 186-cı maddəsinə əsasən, əmək və icra intizamını pozan işçiyə işəgötürən tərəfindən tətbiq edilə bilən intizam tənbehlərinin tam siyahısı hansıdır?', 'multiple_choice', '["Vəzifə maaşının 50% azaldılması, növbəti məzuniyyətin verilməməsi", "Şifahi xəbərdarlıq, ictimai töhmət, cərimə və məzuniyyətin ləğv edilməsi", "Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi", "Yalnız yazılı töhmət və işçinin fəxri adlardan məhrum edilməsi", "İnzibati cərimə, məcburi ictimai işlər və başqa müəssisəyə məcburi keçirilmə"]'::jsonb, 'Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi', 'Düzgün cavab: C) Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutu', '', 43, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('980ce150-cc93-4bbd-8eff-47a3695159a9', 'c065db35-8dcf-406b-b47d-5af689b453a1', 'ka', 'შრომის კოდექსის 186-ე მუხლის თანახმად, რომელია დისციპლინური სახდელების სრული ჩამონათვალი?', '["მხოლოდ წერილობითი საყვედური და დასაქმებულისთვის საპატიო წოდებების ჩამორთმევა", "ზეპირი გაფრთხილება, საზოგადოებრივი საყვედური, ჯარიმა და შვებულების გაუქმება", "საყვედური, მკაცრი საყვედური უკანასკნელი გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალისწინებულ შემთხვევაში ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა და შრომითი ხელშეკრულების შეწყვეტა", "ადმინისტრაციული ჯარიმა, სავალდებულო საზოგადოებრივი სამუშაოები და სხვა დაწესებულებაში იძულებითი გადაყვანა", "თანამდებობრივი სარგოს 50%-ით შემცირება, მორიგი შვებულების მიუცემლობა"]'::jsonb, 'საყვედური, მკაცრი საყვედური უკანასკნელი გაფრთხილებით, კოლექტიური ხელშეკრულებით გათვალისწინებულ შემთხვევაში ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა და შრომითი ხელშეკრულების შეწყვეტა', 'Düzgün cavab: C) საყვედური, მკაცრი საყვედური უკანასკნელი გაფრთხილებით, კოლექტიური ხელშეკრულებით გ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('36a8afbf-e50d-453a-a2f2-03181ceb22bb', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'AR Əmək Məcəlləsinin 187 və 188-ci maddələrinə əsasən, intizam tənbehinin verilməsi və qüvvədə olma müddəti qaydası necədir?', 'multiple_choice', '["İntizam tənbehi yalnız məhkəmə qərarı əsasında verilir", "İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz", "İşçi yazılı izahat verməkdən imtina etdikdə ona heç bir tənbeh tətbiq edilə bilməz", "İntizam tənbehi verildikdə işçidən izahat alınır və tənbeh verildiyi gündən 1 il qüvvədə qalır", "İntizam tənbehi xətanın aşkar edildiyi gündən 6 ay keçdikdən sonra da verilə bilər və 2 il qüvvədə qalır"]'::jsonb, 'İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz', 'Düzgün cavab: B) İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbe', '', 44, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('cb058c25-12e0-491c-8ffb-622e9af45b36', '36a8afbf-e50d-453a-a2f2-03181ceb22bb', 'ka', 'შრომის კოდექსის 187-ე მუხლის თანახმად, როგორია დისციპლინური სახდელის დადების წესი?', '["თუ დასაქმებული უარს აცხადებს წერილობითი ახსნა-განმარტების მიცემაზე, მას ვერანაირი სახდელი ვერ დაედება", "დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია დადების დღიდან 1 წლის განმავლობაში", "დისციპლინური სახდელი შეიძლება დაედოს გადაცდომის გამოვლენის დღიდან 6 თვის გასვლის შემდეგაც და ძალაში რჩება 2 წელი", "ერთი დისციპლინური გადაცდომისთვის დასაქმებულს შეიძლება ერთდროულად დაედოს როგორც მკაცრი საყვედური, ასევე შეუწყდეს ხელშეკრულება", "დისციპლინური სახდელი გამოიყენება მხოლოდ სასამართლოს გადაწყვეტილების საფუძველზე"]'::jsonb, 'დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია დადების დღიდან 1 წლის განმავლობაში', 'Düzgün cavab: B) დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3e58e71f-fccf-48b4-a653-5c71424989b6', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Əmək Məcəlləsinin 69 və 172-ci maddələrinə əsasən, işçinin öz təşəbbüsü ilə əmək müqaviləsinə xitam verilməsi və son haqq-hesabın ödənilməsi qaydası necədir?', 'multiple_choice', '["Əmək müqaviləsinə xitam verilməsi yalnız həmkarlar ittifaqının razılığı ilə mümkündür", "İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab müqaviləyə xitam verildiyi sonuncu iş günündən gec olmayaraq ödənilir", "İşçi 3 gün əvvəl şifahi xəbərdarlıq etməlidir", "İşçi 2 həftə əvvəl bildiriş verməlidir; kompensasiya növbəti ildə ödənilir", "İşçi istədiyi gün xəbərdarlıq etmədən işi tərk edə bilər"]'::jsonb, 'İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab müqaviləyə xitam verildiyi sonuncu iş günündən gec olmayaraq ödənilir', 'Düzgün cavab: B) İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haq', '', 45, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7e98fbb7-132d-4dfc-94fc-f50b708b6339', '3e58e71f-fccf-48b4-a653-5c71424989b6', 'ka', 'შრომის კოდექსის 69-ე და 172-ე მუხლების თანახმად, როგორია დასაქმებულის ინიციატივით შრომითი ხელშეკრულების შეწყვეტის წესი?', '["დასაქმებულმა შეტყობინება უნდა წარადგინოს 2 კვირით ადრე; კომპენსაცია გაიცემა მომდევნო წელს", "დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი; საბოლოო ანგარიშსწორება ხდება ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღეს არაუგვიანეს", "დასაქმებულმა 3 დღით ადრე უნდა გააფრთხილოს ზეპირად", "შრომითი ხელშეკრულების შეწყვეტა შესაძლებელია მხოლოდ პროფკავშირის თანხმობით", "დასაქმებულს შეუძლია სამუშაო დატოვოს ნებისმიერ დღეს გაფრთხილების გარეშე"]'::jsonb, 'დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი; საბოლოო ანგარიშსწორება ხდება ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღეს არაუგვიანეს', 'Düzgün cavab: B) დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f64e3499-ac3d-4ee2-bdce-40e5246ef4ed', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Kompüter şəbəkələrinin əhatə dairəsinə görə LAN və WAN şəbəkələrinin başlıca fərqi nədir?', 'multiple_choice', '["LAN şəbəkəsində məlumatlar şifrələnmir, WAN şəbəkəsində isə daxili resurs paylaşımı tam qadağandır", "LAN yalnız optik lifli kabellərlə, WAN isə yalnız simsiz Bluetooth ilə qurulur", "LAN yalnız internetə çıxış üçün istifadə olunur, WAN isə lokal fayl və printer mübadiləsini təmin edir", "LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir", "LAN yalnız dövlət orqanları üçün, WAN isə yalnız fərdi istifadəçilər üçün nəzərdə tutulan şəbəkədir"]'::jsonb, 'LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir', 'Düzgün cavab: D) LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, W', '', 46, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e315e55b-9d96-4512-b545-eea7c189bf88', 'f64e3499-ac3d-4ee2-bdce-40e5246ef4ed', 'ka', 'რა არის ძირითადი განსხვავება LAN და WAN ქსელებს შორის?', '["LAN გამოიყენება მხოლოდ ინტერნეტთან წვდომისთვის, ხოლო WAN უზრუნველყოფს ლოკალური ფაილებისა და პრინტერების გაზიარებას", "LAN იგება მხოლოდ ოპტიკურ-ბოჭკოვანი კაბელებით, ხოლო WAN მხოლოდ უსადენო Bluetooth-ით", "LAN ქსელში მონაცემები არ იშიფრება, ხოლო WAN ქსელში შიდა რესურსების გაზიარება სრულიად აკრძალულია", "LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებულ კომპიუტერებს, ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ სივრცეებს, ქვეყნებსა და კონტინენტებს", "LAN განკუთვნილია მხოლოდ სახელმწიფო ორგანოებისთვის, ხოლო WAN — მხოლოდ ინდივიდუალური მომხმარებლებისთვის"]'::jsonb, 'LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებულ კომპიუტერებს, ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ სივრცეებს, ქვეყნებსა და კონტინენტებს', 'Düzgün cavab: D) LAN აერთიანებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა) განთავსებულ კო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('dffe0e61-79d3-4dda-b75c-13c62c1d8500', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'İnternet şəbəkəsində domen adlarını IP ünvanlarına çevirən əsas xidmət və protokol hansıdır?', 'multiple_choice', '["SNMP (Simple Network Management Protocol)", "FTP (File Transfer Protocol)", "SMTP (Simple Mail Transfer Protocol)", "DHCP (Dynamic Host Configuration Protocol)", "DNS (Domain Name System)"]'::jsonb, 'DNS (Domain Name System)', 'Düzgün cavab: E) DNS (Domain Name System)', '', 47, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b3ae00d0-7499-4243-b264-3c99758ba710', 'dffe0e61-79d3-4dda-b75c-13c62c1d8500', 'ka', 'რომელი ძირითადი ქსელური სერვისი გარდაქმნის დომენურ სახელებს IP მისამართებად?', '["DHCP (Dynamic Host Configuration Protocol)", "SNMP (Simple Network Management Protocol)", "FTP (File Transfer Protocol)", "SMTP (Simple Mail Transfer Protocol)", "DNS (Domain Name System) — განაწილებული იერარქიული დომენური სახელების სისტემა"]'::jsonb, 'DNS (Domain Name System) — განაწილებული იერარქიული დომენური სახელების სისტემა', 'Düzgün cavab: E) DNS (Domain Name System) — განაწილებული იერარქიული დომენური სახელების სისტემა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('6554eb52-a11a-4a03-adcc-6ececa249d89', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'İnformasiya təhlükəsizliyində ''İki faktorlu autentifikasiya'' (2FA) istifadəsinin başlıca məqsədi nədir?', 'multiple_choice', '["Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək", "Əməliyyat sisteminin drayverlərini avtomatik yeniləyərək lisenziya müddətini uzatması", "İstifadəçinin daxil etdiyi faylların həcmini avtomatik sıxaraq yaddaşa qənaət etməsi", "İstifadəçiyə eyni vaxtda yalnız bir kompüterdən daxil olmağa məcburi icazə verməsi", "Şəbəkə daxilində kompüterin internet sürətini ikiqat artırması"]'::jsonb, 'Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək', 'Düzgün cavab: A) Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifi', '', 48, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bc491730-5d81-4898-b3ce-8099e3f66591', '6554eb52-a11a-4a03-adcc-6ececa249d89', 'ka', 'რა არის ორფაქტორიანი აუთენტიფიკაციის (2FA) მექანიზმის ძირითადი უპირატესობა?', '["პაროლის ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე შესვლის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების (SMS კოდი, აუთენტიფიკატორის აპლიკაცია ან უსაფრთხოების გასაღები) გარეშე", "მომხმარებლისთვის ერთდროულად მხოლოდ ერთი კომპიუტერიდან შესვლის სავალდებულო ნებართვა", "ქსელის შიგნით კომპიუტერის ინტერნეტის სიჩქარის გაორმაგება", "ოპერაციული სისტემის დრაივერების ავტომატური განახლება და ლიცენზიის ვადის გაგრძელება", "მომხმარებლის მიერ შეყვანილი ფაილების მოცულობის ავტომატური შეკუმშვა და მეხსიერების დაზოგვა"]'::jsonb, 'პაროლის ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე შესვლის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების (SMS კოდი, აუთენტიფიკატორის აპლიკაცია ან უსაფრთხოების გასაღები) გარეშე', 'Düzgün cavab: A) პაროლის ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე შესვლის დაბლოკვა მეორე დამოუკი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('526245d2-4c1b-44a2-9055-a5631a69042b', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Fırıldaqçıların etibarlı təşkilat adından saxta e-poçt göndərərək istifadəçinin məxfi məlumatlarını ələ keçirməsi hansı kiberhücum növüdür?', 'multiple_choice', '["Defragmentasiya hücumu", "DDoS (Xidmətdən imtina) hücumu", "Fişinq (Phishing)", "SQL Injection (Məlumat bazasına müdaxilə)", "Buffer Overflow (Buferin daşması)"]'::jsonb, 'Fişinq (Phishing)', 'Düzgün cavab: C) Fişinq (Phishing)', '', 49, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('12200b1f-60ef-437b-a7ad-1ee548ea4b97', '526245d2-4c1b-44a2-9055-a5631a69042b', 'ka', 'კიბერთავდასხმის რომელი სახეობაა, როდესაც თაღლითები სანდო ორგანიზაციის სახელით აგზავნიან ყალბ ელფოსტას მონაცემების მითვისების მიზნით?', '["დეფრაგმენტაციის შეტევა", "SQL ინიექცია (მონაცემთა ბაზაში შეღწევა)", "ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) — საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტის მეშვეობით", "ბუფერის გადავსება (Buffer Overflow)", "DDoS (სერვისის უარყოფის) შეტევა"]'::jsonb, 'ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) — საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტის მეშვეობით', 'Düzgün cavab: C) ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) — საიდენტიფიკაციო მონაცემების მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1631ec4f-49af-45cd-a908-8ae6f4c25362', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Microsoft Word proqramında abzasın girintilərini dəqiq vizual tənzimləmək üçün hansı elementdən istifadə olunur?', 'multiple_choice', '["Naviqasiya paneli (Navigation Pane)", "Vəziyyət zolağı (Status Bar)", "Sənədin miqyas sürüşdürücüsü (Zoom Slider)", "Sürətli müraciət paneli (Quick Access Toolbar)", "Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi"]'::jsonb, 'Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi', 'Düzgün cavab: E) Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph', '', 50, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f50b6791-6a71-446a-a767-bc5959f7ed6c', '1631ec4f-49af-45cd-a908-8ae6f4c25362', 'ka', 'Word-ში აბზაცის შეწევების ზუსტი ვიზუალური რეგულირებისთვის რომელი ელემენტი გამოიყენება?', '["სტატუსის ზოლი (Status Bar)", "სწრაფი წვდომის პანელი (Quick Access Toolbar)", "ნავიგაციის პანელი (Navigation Pane)", "დოკუმენტის მასშტაბირების სლაიდერი (Zoom Slider)", "ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული მორბენალები (First Line, Hanging, Left/Right) და დიალოგური ფანჯარა Paragraph"]'::jsonb, 'ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული მორბენალები (First Line, Hanging, Left/Right) და დიალოგური ფანჯარა Paragraph', 'Düzgün cavab: E) ჰორიზონტალურ სახაზავზე (Horizontal Ruler) არსებული მორბენალები (First Line, Hang', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2f0b7c50-fe3f-4a4a-87e3-2ab537ed385c', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Microsoft Word sənədində bəzi səhifələri şaquli, bəzi səhifələri isə üfüqi (albom) etmək üçün hansı əməliyyat icra olunmalıdır?', 'multiple_choice', '["Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir", "Bütün sənəd üçün vahid cədvəl şablonu tətbiq olunmalıdır", "Sənəd mütləq PDF formatında yadda saxlanılmalıdır", "Mətnin şrift ölçüsü 10 pt səviyyəsinə endirilməlidir", "Səhifələrin arasına adi səhifə kəsilməsi (Page Break) əlavə edilməlidir"]'::jsonb, 'Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir', 'Düzgün cavab: A) Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin O', '', 51, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('94e408c4-c0d5-4878-8b06-f82e19f6fcaa', '2f0b7c50-fe3f-4a4a-87e3-2ab537ed385c', 'ka', 'Word-ის დოკუმენტში ზოგიერთი გვერდის ვერტიკალური, ხოლო ზოგიერთის ჰორიზონტალური ორიენტაციით დასაფორმატებლად რა მოქმედება უნდა შესრულდეს?', '["დოკუმენტში უნდა ჩაისვას სექციის წყვეტა (Section Break / სექცია მომდევნო გვერდიდან) და შეიცვალოს ამ სექციის ორიენტაცია", "დოკუმენტი აუცილებლად უნდა შეინახოს PDF ფორმატში", "ტექსტის შრიფტის ზომა უნდა შემცირდეს 10 pt დონემდე", "მთელი დოკუმენტისთვის უნდა იქნეს გამოყენებული ცხრილის ერთიანი შაბლონი", "გვერდებს შორის უნდა დაემატოს გვერდის ჩვეულებრივი წყვეტა (Page Break)"]'::jsonb, 'დოკუმენტში უნდა ჩაისვას სექციის წყვეტა (Section Break / სექცია მომდევნო გვერდიდან) და შეიცვალოს ამ სექციის ორიენტაცია', 'Düzgün cavab: A) დოკუმენტში უნდა ჩაისვას სექციის წყვეტა (Section Break / სექცია მომდევნო გვერდიდა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('68ac035d-cfb5-4eec-ba29-575e3361bcff', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Microsoft Word proqramında başlıqlara əsasən avtomatik yenilənən Mündəricat yaratmaq üçün hansı taba müraciət edilir?', 'multiple_choice', '["Design (Dizayn)", "Layout (Səhifə düzəni)", "References (İstinadlar) tabı > Table of Contents qrupu", "Review (İcmal)", "Mailings (Göndərişlər)"]'::jsonb, 'References (İstinadlar) tabı > Table of Contents qrupu', 'Düzgün cavab: C) References (İstinadlar) tabı > Table of Contents qrupu', '', 52, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('5d81690b-91c0-49c7-bcf8-9b694aa680eb', '68ac035d-cfb5-4eec-ba29-575e3361bcff', 'ka', 'Word-ში სათაურების საფუძველზე ავტომატურად განახლებადი სარჩევის შესაქმნელად რომელ ჩანართს მიმართავენ?', '["Mailings (გაგზავნა / დაგზავნა)", "Layout (გვერდის განლაგება)", "References (სქოლიოები/ბმულები) ჩანართი > ჯგუფი Table of Contents", "Design (დიზაინი)", "Review (რეცენზირება)"]'::jsonb, 'References (სქოლიოები/ბმულები) ჩანართი > ჯგუფი Table of Contents', 'Düzgün cavab: C) References (სქოლიოები/ბმულები) ჩანართი > ჯგუფი Table of Contents', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d2c611a8-6bf9-45fe-8d43-5f22107b4a61', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Microsoft Excel cədvəlində `$C$2` mütləq xana ünvanı olan düstur başqa xanalara kopyalandıqda necə dəyişir?', 'multiple_choice', '["Həm sütun (C), həm də sətir (2) indeksi kopyalanan istiqamətə uyğun avtomatik sürüşür", "Yalnız sütun adı sabit qalır, sətir nömrəsi isə aşağı kopyalandıqca artır", "Yalnız sətir nömrəsi sabit qalır, sütun hərfi isə sağa kopyalandıqca dəyişir", "Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır", "Düstur avtomatik olaraq sıfır qiyməti qaytarır"]'::jsonb, 'Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', 'Düzgün cavab: D) Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', '', 53, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c13941a0-b5b8-4d19-8b7e-9a0368630b9b', 'd2c611a8-6bf9-45fe-8d43-5f22107b4a61', 'ka', 'Excel-ის ცხრილში ფორმულის სხვა უჯრედებში კოპირებისას, რომელშიც გამოყენებულია აბსოლუტური მისამართი $C$2, როგორ შეიცვლება იგი?', '["ფორმულა ავტომატურად აბრუნებს ნულოვან მნიშვნელობას", "მხოლოდ სვეტის სახელი რჩება უცვლელი, ხოლო სტრიქონის ნომერი იზრდება ქვემოთ კოპირებისას", "მხოლოდ სტრიქონის ნომერი რჩება უცვლელი, ხოლო სვეტის ასო იცვლება მარჯვნივ კოპირებისას", "რადგან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკომპირდეს ფორმულა, უჯრედის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური ბმული)", "როგორც სვეტის (C), ასევე სტრიქონის (2) ინდექსი ავტომატურად ინაცვლებს კოპირების მიმართულების შესაბამისად"]'::jsonb, 'რადგან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკომპირდეს ფორმულა, უჯრედის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური ბმული)', 'Düzgün cavab: D) რადგან დოლარის ($) ნიშანი ორივე ინდექსის წინ დგას, სადაც არ უნდა დაკომპირდეს ფორ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5a61b61d-a305-489b-8f1a-ffadbeee8817', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Microsoft Excel proqramında `A1:A10` diapazonunda yalnız qiyməti 50-dən böyük olan xanaların sayını hesablamaq üçün hansı funksiya düzgündür?', 'multiple_choice', '["=COUNT(A1:A10; >50)", "=COUNTIF(A1:A10; \">50\")", "=COUNTA(A1:A10; 50)", "=SUM(A1:A10; \">50\")", "=AVERAGEIF(A1:A10; 50)"]'::jsonb, '=COUNTIF(A1:A10; ">50")', 'Düzgün cavab: B) =COUNTIF(A1:A10; ">50")', '', 54, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('66f7c152-88ef-4363-9fdd-52926e258e4d', '5a61b61d-a305-489b-8f1a-ffadbeee8817', 'ka', 'Excel-ში A1:A10 დიაპაზონში მხოლოდ იმ უჯრედების რაოდენობის დასათვლელად, რომელთა მნიშვნელობა 50-ზე მეტია, რომელი ფუნქციაა სწორი?', '["=COUNT(A1:A10; >50) — სინტაქსი მცდარია", "=COUNTIF(A1:A10;\">50\") — პირობითი დათვლის ფუნქცია", "=COUNTA(A1:A10; 50) — შევსებული უჯრედების რაოდენობა", "=SUM(A1:A10; \">50\") — პირობითი ჯამის ფუნქცია", "=AVERAGEIF(A1:A10; 50) — საშუალო არითმეტიკულის ფუნქცია"]'::jsonb, '=COUNTIF(A1:A10;">50") — პირობითი დათვლის ფუნქცია', 'Düzgün cavab: B) =COUNTIF(A1:A10;">50") — პირობითი დათვლის ფუნქცია', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('dfa0db5c-ce98-4e79-8463-dabdb1a50e59', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Microsoft Excel-də B2 xanasındakı əməkhaqqı 800-dən çox olduqda 15% mükafat, əks halda 5% hesablayan düstur hansıdır?', 'multiple_choice', '["=VLOOKUP(B2; 800; 15; 5)", "=MAX(B2>800; 0.15; 0.05)", "=SUMIF(B2>800; B2*15%; B2*5%)", "=IF(B2>800; B2*0.15; B2*0.05)", "=COUNTIF(B2; 800; 15%)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: D) =IF(B2>800; B2*0.15; B2*0.05)', '', 55, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('46835d62-cb5c-4ce2-8ce8-bb2dafc0c1f9', 'dfa0db5c-ce98-4e79-8463-dabdb1a50e59', 'ka', 'Excel-ში რომელი ფორმულა ითვლის 15%-იან პრემიას, როდესაც B2 უჯრედში არსებული ხელფასი 800-ზე მეტია?', '["=SUMIF(B2>800; B2*15%; B2*5%) — პირობითი ჯამი", "=COUNTIF(B2; 800; 15%) — დათვლის ფუნქცია", "=VLOOKUP(B2; 800; 15; 5) — ძიების ფუნქცია", "=IF(B2>800; B2*0.15; B2*0.05) — ლოგიკური IF ფუნქციით", "=MAX(B2>800; 0.15; 0.05) — მაქსიმუმის ფუნქცია"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05) — ლოგიკური IF ფუნქციით', 'Düzgün cavab: D) =IF(B2>800; B2*0.15; B2*0.05) — ლოგიკური IF ფუნქციით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ac3e68f6-122f-487c-bce8-ee0cbb38bfcc', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Microsoft Excel proqramında xanaya yalnız müəyyən diapazonda ədədlərin daxil edilməsinə icazə verən alət hansıdır?', 'multiple_choice', '["Remove Duplicates (Təkrarların silinməsi)", "Conditional Formatting (Şərti formatlaşdırma)", "Text to Columns (Mətnin sütunlara bölünməsi)", "Data Validation (Verilənlərin yoxlanılması)", "Flash Fill (Sürətli doldurma)"]'::jsonb, 'Data Validation (Verilənlərin yoxlanılması)', 'Düzgün cavab: D) Data Validation (Verilənlərin yoxlanılması)', '', 56, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7350fb12-d10f-489f-9231-cf17cddfe387', 'ac3e68f6-122f-487c-bce8-ee0cbb38bfcc', 'ka', 'Excel-ში რომელი ხელსაწყო იძლევა უჯრედში მხოლოდ გარკვეულ დიაპაზონში რიცხვების შეყვანის ნებართვას?', '["Flash Fill (მყისიერი შევსება) — ავტომატური შევსება", "Text to Columns (ტექსტის სვეტებად დაყოფა)", "Remove Duplicates (დუბლიკატების წაშლა)", "Data Validation (მონაცემთა ვალიდაცია) — ჩანართში Data კრიტერიუმებით Whole Number, Decimal, List, Date", "Conditional Formatting (პირობითი ფორმატირება) — ვიზუალური გამოკვეთა"]'::jsonb, 'Data Validation (მონაცემთა ვალიდაცია) — ჩანართში Data კრიტერიუმებით Whole Number, Decimal, List, Date', 'Düzgün cavab: D) Data Validation (მონაცემთა ვალიდაცია) — ჩანართში Data კრიტერიუმებით Whole Number', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('8e0c851d-df4f-4309-94e8-023ffa032ed9', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Microsoft PowerPoint proqramında bütün slaydların vahid dizayn şablonunu dəyişmək üçün hansı rejimdən istifadə olunur?', 'multiple_choice', '["Slide Master (Slayd Ustası)", "Presenter View (Aparıcı görünüşü)", "Custom Animation (Fərdi animasiya)", "Reading View (Oxu rejimi)", "Slide Sorter (Slayd çeşidləyicisi)"]'::jsonb, 'Slide Master (Slayd Ustası)', 'Düzgün cavab: A) Slide Master (Slayd Ustası)', '', 57, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('13a6a70b-38a7-4a9d-9b44-cb9c67b94e5d', '8e0c851d-df4f-4309-94e8-023ffa032ed9', 'ka', 'PowerPoint-ში ყველა სლაიდის ერთიანი დიზაინის შაბლონის შესაცვლელად რომელი რეჟიმი გამოიყენება?', '["Slide Master (სლაიდების მასტერი / Образец слайдов) — View ჩანართის Master Views ჯგუფი", "Custom Animation (მორგებული ანიმაცია) — ანიმაციის რეჟიმი", "Reading View (კითხვის რეჟიმი) — კითხვის რეჟიმი", "Slide Sorter (სლაიდების დამხარისხებელი) — დახარისხების რეჟიმი", "Presenter View (მომხსენებლის ხედი) — მომხსენებლის ხედი"]'::jsonb, 'Slide Master (სლაიდების მასტერი / Образец слайдов) — View ჩანართის Master Views ჯგუფი', 'Düzgün cavab: A) Slide Master (სლაიდების მასტერი / Образец слайдов) — View ჩანართის Master Views', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a5f0dfa2-ea45-491c-9d8a-3f3f6aae3f06', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Microsoft PowerPoint-də ''Transition'' ilə ''Animation'' arasındakı əsas fərq nədir?', 'multiple_choice', '["Transition slaydın arxa fon rəngini dəyişir, Animation slaydın vaxtını tənzimləyir", "Transition yalnız mətnlərə tətbiq olunur, Animation yalnız video faylları nümayiş etdirir", "Hər iki anlayış eyni funksiyanı icra edir", "Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir", "Transition yalnız kompüter sönərkən işləyir, Animation çap zamanı aktivləşir"]'::jsonb, 'Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir', 'Düzgün cavab: D) Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation i', '', 58, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4a0cc52b-6461-44a7-bce5-98650026960b', 'a5f0dfa2-ea45-491c-9d8a-3f3f6aae3f06', 'ka', 'PowerPoint-ში რა არის ძირითადი განსხვავება ''Transition''-სა და ''Animation''-ს შორის?', '["ორივე ცნება ერთსა და იმავე ფუნქციას ასრულებს", "Transition მუშაობს მხოლოდ კომპიუტერის გამორთვისას, ხოლო Animation აქტიურდება ბეჭდვის დროს", "Transition ცვლის სლაიდის ფონის ფერს, ხოლო Animation არეგულირებს სლაიდის დროს", "Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animation არის უშუალოდ სლაიდის შიგნით არსებული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი", "Transition გამოიყენება მხოლოდ ტექსტებზე, ხოლო Animation აჩვენებს მხოლოდ ვიდეოფაილებს"]'::jsonb, 'Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animation არის უშუალოდ სლაიდის შიგნით არსებული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი', 'Düzgün cavab: D) Transition არის ვიზუალური ეფექტი ერთი სლაიდიდან მეორეზე გადასვლისას, ხოლო Animat', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7e7e0751-deae-4c4b-9cdb-07ba491960ed', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Bulud saxlama xidmətlərində sənəd üzərində birgə işləyərkən əvvəlki versiyalara qayıtmaq üçün hansı funksiyadan istifadə olunur?', 'multiple_choice', '["Registry Editor (Reyestr redaktoru)", "Disk Cleanup (Diskin təmizlənməsi)", "Version History (Versiya tarixçəsi)", "Task Manager (Tapşırıqlar meneceri)", "Defragmentation (Defragmentasiya)"]'::jsonb, 'Version History (Versiya tarixçəsi)', 'Düzgün cavab: C) Version History (Versiya tarixçəsi)', '', 59, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('51252dc9-51c6-46ea-a221-e62db3392ec1', '7e7e0751-deae-4c4b-9cdb-07ba491960ed', 'ka', 'ღრუბლოვან საცავებში დოკუმენტის წინა ვერსიებზე დასაბრუნებლად რომელი ფუნქცია გამოიყენება?', '["Disk Cleanup (დისკის გასუფთავება) — შლის დროებით ფაილებს", "Task Manager (ამოცანების მმართველი) — მართავს პროცესებს", "Version History (ვერსიების ისტორია / История версий) — File > Info > Version History ან ისტორია OneDrive/SharePoint-ში", "Defragmentation (დეფრაგმენტაცია) — დისკის ოპტიმიზაცია", "Registry Editor (რეესტრის რედაქტორი) — რეესტრის რედაქტირება"]'::jsonb, 'Version History (ვერსიების ისტორია / История версий) — File > Info > Version History ან ისტორია OneDrive/SharePoint-ში', 'Düzgün cavab: C) Version History (ვერსიების ისტორია / История версий) — File > Info > Version His', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('91d64ede-8475-4d9c-ab87-58fa6da67c7a', 'cc5a9152-038e-4e28-a998-92078ee3e505', 'Süni intellekt əsaslı generativ modellərdə ''Hallüsinasiya'' riski nəyi ifadə edir?', 'multiple_choice', '["Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini", "Süni intellektin kompüterin aparat hissələrini sıradan çıxarmasını", "Modelin internet şəbəkəsini həddindən artıq yükləyərək kompüteri dondurmasını", "Süni intellektin bütün istifadəçi parollarını avtomatik silməsini", "Modelin yalnız xarici dillərdə işləyərək Azərbaycan dilini dəstəkləməməsini"]'::jsonb, 'Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini', 'Düzgün cavab: A) Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadl', '', 60, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4ff231ec-00e1-4fb0-a351-20239c8e21a9', '91d64ede-8475-4d9c-ab87-58fa6da67c7a', 'ka', 'ხელოვნურ ინტელექტში რას გამოხატავს „ჰალუცინაციის“ (Hallucination) რისკი?', '["მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და ბმულების სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით გენერირებას", "ხელოვნური ინტელექტის მიერ მომხმარებლის ყველა პაროლის ავტომატურ წაშლას", "მოდელის მიერ ინტერნეტქსელის გადატვირთვას და კომპიუტერის გაყინვას", "ხელოვნური ინტელექტის მიერ კომპიუტერის აპარატურული ნაწილების მწყობრიდან გამოყვანას", "მოდელის მუშაობას მხოლოდ უცხო ენებზე და აზერბაიჯანული ენის მხარდაჭერის არქონას"]'::jsonb, 'მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და ბმულების სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით გენერირებას', 'Düzgün cavab: A) მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და ბმულებ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('cc25a938-62f5-467b-af99-e8781547c81b', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Ümumi təhsil müəssisəsində Uşaq Birliyi Təşkilatı Rəhbərinin (UBTR) əsas xidməti vəzifəsi hansıdır?', 'multiple_choice', '["Şagirdlərin dərsdənkənar asudə vaxtının səmərəli təşkili, vətənpərvərlik və milli-mənəvi tərbiyəsi, liderlik və sosial bacarıqlarının inkişafı və uşaq-gənclər təşkilatlarının fəaliyyətini pedaqoji cəhətdən əlaqələndirmək", "Məktəb binasının mühəndis-texniki təhlükəsizliyinə və təsərrüfat anbarının idarə edilməsinə rəhbərlik etmək", "Məktəbin illik büdcə xərclərini tərtib etmək və ştat vahidlərinin maliyyələşdirilməsini icra etmək", "Fənn müəllimlərinin dərs cədvəlinin metodiki planlaşdırılmasını və dərslik təminatını həyata keçirmək", "Təhsilalanların fənlər üzrə rüblük və illik akademik qiymətləndirməsini aparmaq və təsdiq etmək"]'::jsonb, 'Şagirdlərin dərsdənkənar asudə vaxtının səmərəli təşkili, vətənpərvərlik və milli-mənəvi tərbiyəsi, liderlik və sosial bacarıqlarının inkişafı və uşaq-gənclər təşkilatlarının fəaliyyətini pedaqoji cəhətdən əlaqələndirmək', 'Düzgün cavab: A) Şagirdlərin dərsdənkənar asudə vaxtının səmərəli təşkili, vətənpərvərlik və mill', '', 1, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4425f979-ff33-4783-a48e-a452a860d1cb', 'cc25a938-62f5-467b-af99-e8781547c81b', 'ka', 'რა არის ბავშვთა გაერთიანების ორგანიზაციის ხელმძღვანელის (ბგოხ) ძირითადი სამსახურებრივი მოვალეობა ზოგადსაგანმანათლებლო დაწესებულებაში?', '["მოსწავლეთა კლასგარეშე თავისუფალი დროის ნაყოფიერი ორგანიზება, პატრიოტული და ეროვნულ-ზნეობრივი აღზრდა, ლიდერული და სოციალური უნარების განვითარება და ბავშვთა და ახალგაზრდულ ორგანიზაციათა საქმიანობის პედაგოგიური კოორდინაცია", "მოსწავლეთა საგნობრივი კვარტალური და წლიური აკადემიური შეფასების წარმოება და დამტკიცება", "საგნის მასწავლებელთა გაკვეთილების ცხრილის მეთოდიკური დაგეგმვა და სახელმძღვანელოებით უზრუნველყოფა", "სკოლის წლიური საბიუჯეტო ხარჯების შედგენა და საშტატო ერთეულების დაფინანსების განხორციელება", "სკოლის შენობის საინჟინრო-ტექნიკურ უსაფრთხოებასა და სამეურნეო საწყობის მართვაზე ხელმძღვანელობა"]'::jsonb, 'მოსწავლეთა კლასგარეშე თავისუფალი დროის ნაყოფიერი ორგანიზება, პატრიოტული და ეროვნულ-ზნეობრივი აღზრდა, ლიდერული და სოციალური უნარების განვითარება და ბავშვთა და ახალგაზრდულ ორგანიზაციათა საქმიანობის პედაგოგიური კოორდინაცია', 'Düzgün cavab: A) მოსწავლეთა კლასგარეშე თავისუფალი დროის ნაყოფიერი ორგანიზება, პატრიოტული და ეროვნ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9bfd49c2-ce76-4c9f-a002-1fa38c5b99a2', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəbdə fəaliyyət göstərən şagird özünüidarəetmə orqanının formalaşdırılmasında UBTR-in başlıca rolu nədir?', 'multiple_choice', '["Şagird özünüidarəetmə orqanının (Məktəb Şagird Parlamenti / Şurası) seçkilərini demokratik prinsiplərlə təşkil etmək, şagirdlərin təşəbbüskarlığını, seçki mədəniyyətini və demokratik qərarvermə prosesini metodiki istiqamətləndirmək", "Şagird təşkilatının iclaslarında ictimai fəallığı deyil, yalnız formal sənədləşməni icra etmək", "Bütün qərarları şagirdlərin əvəzinə təkbaşına qəbul edərək iclaslara qatılmağı məhdudlaşdırmaq", "Şagird özünüidarəetmə orqanının seçkilərini yalnız müəllimlərin fərdi mülahizələrinə əsasən təşkil etmək", "Şura üzvlüyünə yalnız akademik dərslərdə nizam-intizamı pozan şagirdləri məcburi cəlb etmək"]'::jsonb, 'Şagird özünüidarəetmə orqanının (Məktəb Şagird Parlamenti / Şurası) seçkilərini demokratik prinsiplərlə təşkil etmək, şagirdlərin təşəbbüskarlığını, seçki mədəniyyətini və demokratik qərarvermə prosesini metodiki istiqamətləndirmək', 'Düzgün cavab: A) Şagird özünüidarəetmə orqanının (Məktəb Şagird Parlamenti / Şurası) seçkilərini', '', 2, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('26e1f0fe-7f0c-4431-b875-75f0799381d7', '9bfd49c2-ce76-4c9f-a002-1fa38c5b99a2', 'ka', 'რა არის ბგოხ-ის მთავარი როლი სკოლაში მოქმედი მოსწავლეთა თვითმმართველობის ორგანოს ფორმირებაში?', '["მოსწავლეთა თვითმმართველობის ორგანოს (სკოლის მოსწავლეთა პარლამენტი / საბჭო) არჩევნების დემოკრატიული პრინციპებით ორგანიზება, მოსწავლეთა ინიციატივის, საარჩევნო კულტურისა და გადაწყვეტილების მიღების დემოკრატიული პროცესის მეთოდიკური წარმართვა", "მოსწავლეთა ორგანიზაციის სხდომებზე არა საზოგადოებრივი აქტიურობის, არამედ მხოლოდ ფორმალური დოკუმენტაციის წარმოება", "მოსწავლეების ნაცვლად ყველა გადაწყვეტილების ერთპიროვნულად მიღება და სხდომებზე დასწრების შეზღუდვა", "მოსწავლეთა თვითმმართველობის ორგანოს არჩევნების ორგანიზება მხოლოდ მასწავლებელთა პირადი შეხედულებების საფუძველზე", "საბჭოს წევრებად მხოლოდ იმ მოსწავლეთა იძულებითი ჩართვა, რომლებიც აკადემიურ გაკვეთილებზე დისციპლინას არღვევენ"]'::jsonb, 'მოსწავლეთა თვითმმართველობის ორგანოს (სკოლის მოსწავლეთა პარლამენტი / საბჭო) არჩევნების დემოკრატიული პრინციპებით ორგანიზება, მოსწავლეთა ინიციატივის, საარჩევნო კულტურისა და გადაწყვეტილების მიღების დემოკრატიული პროცესის მეთოდიკური წარმართვა', 'Düzgün cavab: A) მოსწავლეთა თვითმმართველობის ორგანოს (სკოლის მოსწავლეთა პარლამენტი / საბჭო) არჩევ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('1fccc012-fb79-480f-bfa4-ba5cf71ab8d3', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'BMT-nin “Uşaq hüquqları haqqında” Konvensiyasına əsasən, uşaqların ictimai birliklərdə iştirakı hansı prinsiplə tənzimlənir?', 'multiple_choice', '["Yaşayış yeri üzrə bələdiyyə orqanlarının məcburi göndərişi və yazılı təyinatı əsasında", "Yalnız yüksək akademik nailiyyəti olan şagirdlərin qeyd-şərtsiz təşkilata daxil edilməsi ilə", "Məktəb rəhbərliyinin birtərəfli inzibati qərarı və direktiv göstərişi əsasında", "Uşaqların sərbəst toplaşmaq, ictimai birliklər yaratmaq və dinc yığıncaqlarda könüllü, sərbəst iştirak etmək hüququ dövlət tərəfindən tanınır və təmin edilir", "Uşaqların ictimai birliklərdə iştirakının yetkinlik yaşına çatana qədər qadağan olunması ilə"]'::jsonb, 'Uşaqların sərbəst toplaşmaq, ictimai birliklər yaratmaq və dinc yığıncaqlarda könüllü, sərbəst iştirak etmək hüququ dövlət tərəfindən tanınır və təmin edilir', 'Düzgün cavab: D) Uşaqların sərbəst toplaşmaq, ictimai birliklər yaratmaq və dinc yığıncaqlarda kö', '', 3, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4a90a4b6-2e7a-4d77-a1c5-ec5a196cb764', '1fccc012-fb79-480f-bfa4-ba5cf71ab8d3', 'ka', 'გაეროს „ბავშვის უფლებათა კონვენციის“ თანახმად, რა პრინციპით რეგულირდება ბავშვთა მონაწილეობა საზოგადოებრივ გაერთიანებებში?', '["საცხოვრებელი ადგილის მიხედვით მუნიციპალური ორგანოების სავალდებულო მიმართვისა და წერილობითი დანიშნულების საფუძველზე", "სკოლის ხელმძღვანელობის ცალმხრივი ადმინისტრაციული გადაწყვეტილებისა და დირექტიული მითითების საფუძველზე", "მხოლოდ ოჯახის სოციალურ-ეკონომიკური შემოსავლის დონისა და სპეციალური შუამდგომლობის საფუძველზე", "ნებაყოფლობითობის, თანასწორობის, დისკრიმინაციის დაუშვებლობისა და ბავშვის საკუთარი აზრის თავისუფლად გამოხატვის, შეკრებისა და გაერთიანების თავისუფლების უფლების საფუძველზე", "მხოლოდ იმ პირობით, თუ მოსწავლეს აქვს მაღალი აკადემიური მოსწრების მაჩვენებლები სასკოლო საგნებში"]'::jsonb, 'ნებაყოფლობითობის, თანასწორობის, დისკრიმინაციის დაუშვებლობისა და ბავშვის საკუთარი აზრის თავისუფლად გამოხატვის, შეკრებისა და გაერთიანების თავისუფლების უფლების საფუძველზე', 'Düzgün cavab: D) ნებაყოფლობითობის, თანასწორობის, დისკრიმინაციის დაუშვებლობისა და ბავშვის საკუთარი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4d456cfe-e8ab-4d1f-8c60-5e3ed35bd0a8', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Şagirdlərdə hərbi-vətənpərvərlik, dövlət rəmzlərinə hörmət və milli qürur hissinin aşılanmasında UBTR hansı tədbirləri təşkil edir?', 'multiple_choice', '["Vətənpərvərlik tərbiyəsinin yalnız yuxarı sinif şagirdləri üçün məcburi imtahan fənni kimi tədrisi", "Təhsilalanların dərsdənkənar tədbirlərdə iştirakına tam qadağa qoyulması", "Şagirdlərin yalnız tədris proqramı xaricində olan kommersiya tədbirlərinə cəlb edilməsi", "Dövlət atributlarının (Bayraq, Himn, Gerb) təbliği, tarixi zəfər günləri, şəhidlərin xatirəsinə həsr olunmuş tədbirlər, hərbi-idman oyunları (''Cəsurlar'', ''Şahinlər'') və muzey dərsləri", "Dövlət atributlarının məktəb tədbirlərində istifadəsinin məhdudlaşdırılması"]'::jsonb, 'Dövlət atributlarının (Bayraq, Himn, Gerb) təbliği, tarixi zəfər günləri, şəhidlərin xatirəsinə həsr olunmuş tədbirlər, hərbi-idman oyunları (''Cəsurlar'', ''Şahinlər'') və muzey dərsləri', 'Düzgün cavab: D) Dövlət atributlarının (Bayraq, Himn, Gerb) təbliği, tarixi zəfər günləri, şəhidl', '', 4, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ea08cd89-d118-41b9-a0f2-cd08778954f1', '4d456cfe-e8ab-4d1f-8c60-5e3ed35bd0a8', 'ka', 'მოსწავლეებში ეროვნულ-ზნეობრივი ღირებულებებისა და პატრიოტული აღზრდის ჩასანერგად ღონისძიებათა რა კომპლექსი უნდა მოაწყოს ბგოხ-მა?', '["მოსწავლეთა სრული გათავისუფლება აკადემიური გაკვეთილებისგან და მხოლოდ სპორტულ შეჯიბრებებზე მათი მიმართვა", "გაკვეთილების დროს მოსწავლეების ჩართვა სკოლის ეზოში სარემონტო და სამეურნეო სამუშაოებში", "საგნობრივი ოლიმპიადების კითხვების მომზადება და მოსწავლეებს შორის საცდელი გამოცდების ჩატარება", "სახელმწიფო სიმბოლოების პოპულარიზაცია, ისტორიული გამარჯვებების (გამარჯვების დღე) აღნიშვნა, გმირთა ხსოვნის პატივგება, ომის ვეტერანებთან შეხვედრები, მუზეუმებსა და ისტორიულ ადგილებში, მემორიალურ კომპლექსებში ექსკურსიების ორგანიზება", "მხოლოდ უცხოურ ენებზე გამართულ მუსიკალურ ფესტივალებზე მოსწავლეთა იძულებითი მონაწილეობის ორგანიზება"]'::jsonb, 'სახელმწიფო სიმბოლოების პოპულარიზაცია, ისტორიული გამარჯვებების (გამარჯვების დღე) აღნიშვნა, გმირთა ხსოვნის პატივგება, ომის ვეტერანებთან შეხვედრები, მუზეუმებსა და ისტორიულ ადგილებში, მემორიალურ კომპლექსებში ექსკურსიების ორგანიზება', 'Düzgün cavab: D) სახელმწიფო სიმბოლოების პოპულარიზაცია, ისტორიული გამარჯვებების (გამარჯვების დღე)', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d29d0d5a-6b6e-4ecb-87a2-308e33829a68', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəbdə könüllülük hərəkatının və sosial layihələrin təşkilində UBTR-in başlıca vəzifəsi nədən ibarətdir?', 'multiple_choice', '["Şagirdlərin ekoloji aksiyalara (''Təbiəti qoruyaq'', ağacəkmə), xeyriyyə yarmarkalarına, tənha və qocalara qayğı aksiyalarına, sosial məsuliyyət və vətəndaşlıq təşəbbüslərinə cəlb edilməsi", "Könüllülük fəaliyyətini yalnız dərslərdən yayınmaq üçün bir vasitə kimi təbliğ etmək", "Şagirdlərin sosial layihələrdə iştirakını valideyn komitəsinin rəsmi qərarı ilə qadağan etmək", "Şagirdlərdən məcburi maliyyə vəsaiti toplayaraq kənar kommersiya layihələrinə yönəltmək", "Könüllülük hərəkatını yalnız inzibati cəzalar tətbiq edilən şagirdlər üçün məcburi etmək"]'::jsonb, 'Şagirdlərin ekoloji aksiyalara (''Təbiəti qoruyaq'', ağacəkmə), xeyriyyə yarmarkalarına, tənha və qocalara qayğı aksiyalarına, sosial məsuliyyət və vətəndaşlıq təşəbbüslərinə cəlb edilməsi', 'Düzgün cavab: A) Şagirdlərin ekoloji aksiyalara (''Təbiəti qoruyaq'', ağacəkmə), xeyriyyə yarmarkal', '', 5, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('35d2ec89-fae4-4d99-a81c-d95850ee8a03', 'd29d0d5a-6b6e-4ecb-87a2-308e33829a68', 'ka', 'საგანმანათლებლო დაწესებულებაში სახელმწიფო სიმბოლოების პოპულარიზაციისა და დაცვის წესების თანახმად, რომელი მოსაზრებაა სწორი?', '["სახელმწიფო ჰიმნის გაჟღერებისას ყოველი მოქალაქე უნდა წამოდგეს, მარჯვენა ხელი გულზე დაიდოს და გამოხატოს პატივისცემა; სიმბოლოებისადმი უპატივცემულობა კანონით გათვალისწინებულ პასუხისმგებლობას იწვევს", "სახელმწიფო დროშა უნდა აღიმართოს მხოლოდ სასწავლო წლის პირველ დღეს, სხვა დღეებში კი დაშვებული უნდა იყოს", "სახელმწიფო სიმბოლოების პროპაგანდა დასაშვებია მხოლოდ უმაღლეს საგანმანათლებლო დაწესებულებებში სპეციალური ნებართვით", "ნებადართულია სკოლის შენობაზე ფერგახუნებული და დაზიანებული სახელმწიფო დროშის გამოფენა", "სახელმწიფო გერბი შეიძლება გამოფენილი იყოს მხოლოდ სკოლის სამეურნეო საწყობის შიდა კარზე"]'::jsonb, 'სახელმწიფო ჰიმნის გაჟღერებისას ყოველი მოქალაქე უნდა წამოდგეს, მარჯვენა ხელი გულზე დაიდოს და გამოხატოს პატივისცემა; სიმბოლოებისადმი უპატივცემულობა კანონით გათვალისწინებულ პასუხისმგებლობას იწვევს', 'Düzgün cavab: A) სახელმწიფო ჰიმნის გაჟღერებისას ყოველი მოქალაქე უნდა წამოდგეს, მარჯვენა ხელი გულზ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e6099955-d564-40ab-bc4b-e8498d3ce67a', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'UBTR-in illik iş planının strukturu və təsdiq olunma qaydası necə tənzimlənir?', 'multiple_choice', '["Plan yalnız tədris ilinin sonunda hesabat xarakterli tərtib olunur", "Tədris ilinin əvvəlində məktəbin illik fəaliyyət planına, dövlət proqramlarına və təqvim planına uyğun tərtib edilir və məktəb direktoru tərəfindən təsdiqlənir", "Plan Pedaqoji Şuranın qərarı olmadan yalnız valideynlər tərəfindən təsdiqlənir", "İş planı yalnız rayon icra hakimiyyətinin humanitar şöbəsi tərəfindən birbaşa hazırlanır", "İş planı tərtib edilmir, bütün tədbirlər yalnız situativ şəkildə həyata keçirilir"]'::jsonb, 'Tədris ilinin əvvəlində məktəbin illik fəaliyyət planına, dövlət proqramlarına və təqvim planına uyğun tərtib edilir və məktəb direktoru tərəfindən təsdiqlənir', 'Düzgün cavab: B) Tədris ilinin əvvəlində məktəbin illik fəaliyyət planına, dövlət proqramlarına v', '', 6, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('fb660ae7-8f1d-4058-85b3-991d2c246b6f', 'e6099955-d564-40ab-bc4b-e8498d3ce67a', 'ka', 'მოსწავლეებში მავნე ჩვევების პროფილაქტიკისთვის რა მიმართულებით უნდა წარიმართოს ბგოხ-ის საგანმანათლებლო-საგანმანათლებლო მუშაობა?', '["მხოლოდ მავნე ნივთიერებების ქიმიური ფორმულების თეორიულად დაზეპირება", "მრგვალი მაგიდების ორგანიზება თემაზე „ჯანსაღი ცხოვრების წესი“, შეხვედრები ფსიქოლოგებთან, სამედიცინო სპეციალისტებთან და სამართალდამცავ ორგანოებთან, ინტერაქტიული ტრენინგების, ფლეშმობებისა და აქციების ჩატარება", "საკითხის საჯარო განხილვისგან დამალვა და არანაირი პროფილაქტიკური ღონისძიების არჩატარება", "მოსწავლეების დაშინება დისციპლინური გადაცდომებისთვის დასჯით და მათი სასწავლო პროცესიდან სრული ჩამოშორება", "მოსწავლეებთან ინდივიდუალური საუბრების შეწყვეტა და საკითხის მხოლოდ შინაგანაწესში დაფიქსირება"]'::jsonb, 'მრგვალი მაგიდების ორგანიზება თემაზე „ჯანსაღი ცხოვრების წესი“, შეხვედრები ფსიქოლოგებთან, სამედიცინო სპეციალისტებთან და სამართალდამცავ ორგანოებთან, ინტერაქტიული ტრენინგების, ფლეშმობებისა და აქციების ჩატარება', 'Düzgün cavab: B) მრგვალი მაგიდების ორგანიზება თემაზე „ჯანსაღი ცხოვრების წესი“, შეხვედრები ფსიქოლო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a4d02f7a-ab59-4663-8a89-d39adf2d213f', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'İbtidai sinif şagirdləri ilə iş zamanı UBTR hansı yaş və psixoloji xüsusiyyətləri əsas götürməlidir?', 'multiple_choice', '["İbtidai siniflərdə yalnız mürəkkəb elmi konfransların və debatların keçirilməsi", "Şagirdlərin fərdi maraqlarını nəzərə almadan yalnız formal çıxışların tələb olunması", "Təlim və asudə vaxt tədbirlərinin oyun texnologiyaları, nağıl terapiyası, vizual və hərəkətli metodlarla, uşaqların tez yorulmasını nəzərə alaraq təşkili", "Şagirdlərə ağır hərbi-taktiki təlimlərin məcburi tətbiq edilməsi", "İbtidai sinif şagirdlərinin dərsdənkənar tədbirlərdə iştirakının tam qadağan edilməsi"]'::jsonb, 'Təlim və asudə vaxt tədbirlərinin oyun texnologiyaları, nağıl terapiyası, vizual və hərəkətli metodlarla, uşaqların tez yorulmasını nəzərə alaraq təşkili', 'Düzgün cavab: C) Təlim və asudə vaxt tədbirlərinin oyun texnologiyaları, nağıl terapiyası, vizual', '', 7, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('14d8cb0e-26f7-4232-85a3-f04e4b0baf74', 'a4d02f7a-ab59-4663-8a89-d39adf2d213f', 'ka', 'სკოლაში „ეკოლოგიური აღზრდის“ საქმიანობის ფარგლებში რომელი პრაქტიკული პროექტის განხორციელებაა შესაძლებელი?', '["ბუნებრივი წყლის რესურსების რაციონალური გამოყენების თემაზე ტრენინგების ამოღება პროგრამიდან", "სკოლის ეზოში არსებული ყველა მწვანე ზოლის გაუქმება და მათი ასფალტის საფარით ჩანაცვლება", "ნარჩენების სორტირება, ქაღალდისა და პლასტმასის ნარჩენების შეგროვება გადამუშავებისთვის, აქციები „მწვანე ქსელი“, „დავიცვათ ბუნება“, „ხეების დარგვა“ და ეკოლოგიური მონიტორინგის პროექტები", "მოსწავლეთა სასწავლო ექსკურსიების აკრძალვა ბუნების წიაღში და ზოოპარკებში", "მხოლოდ ოთახის მცენარეების ლაბორატორიულ პირობებში განოყიერების თეორიული შემოწმებები"]'::jsonb, 'ნარჩენების სორტირება, ქაღალდისა და პლასტმასის ნარჩენების შეგროვება გადამუშავებისთვის, აქციები „მწვანე ქსელი“, „დავიცვათ ბუნება“, „ხეების დარგვა“ და ეკოლოგიური მონიტორინგის პროექტები', 'Düzgün cavab: C) ნარჩენების სორტირება, ქაღალდისა და პლასტმასის ნარჩენების შეგროვება გადამუშავების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c7566120-967f-462b-96be-986625221d64', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Yeniyetməlik dövründə (V–IX siniflər) şagirdlərlə dərsdənkənar tərbiyəvi işin aparılmasında UBTR hansı istiqamətə üstünlük verməlidir?', 'multiple_choice', '["Şəxsiyyətin özünüreallaşdırması, intellektual oyunlar (''Nə? Harada? Nə zaman?'', Breyn-rinq), debat klubları, liderlik məktəbləri və sosial layihələrdə müstəqil təşəbbüslər", "Şagirdlərin bütün sərbəst təşəbbüslərini sərt inzibati cəzalarla məhdudlaşdırmaq", "Yeniyetmələri yalnız fiziki təsərrüfat işlərinə cəlb edərək intellektual oyunlardan uzaqlaşdırmaq", "Dərsdənkənar fəaliyyəti yalnız passiv tamaşaçı formatında təşkil etmək", "Şagirdlər arasında ünsiyyət və komanda oyunlarının keçirilməsini qadağan etmək"]'::jsonb, 'Şəxsiyyətin özünüreallaşdırması, intellektual oyunlar (''Nə? Harada? Nə zaman?'', Breyn-rinq), debat klubları, liderlik məktəbləri və sosial layihələrdə müstəqil təşəbbüslər', 'Düzgün cavab: A) Şəxsiyyətin özünüreallaşdırması, intellektual oyunlar (''Nə? Harada? Nə zaman?'',', '', 8, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8000b147-a7c2-4818-bbd8-b620f66bf301', 'c7566120-967f-462b-96be-986625221d64', 'ka', 'სკოლაში მოსწავლეებს შორის ბულინგის შემთხვევების გამოვლენისას როგორ უნდა წარიმართოს ბგოხ-ის საქმიანობა?', '["შემთხვევის დაუყოვნებლივი მოკვლევა, სკოლის ფსიქოლოგთან და მშობლებთან თანამშრომლობით ტრენინგების „მეგობრობა და ემპათია“, „ერთად ბულინგის წინააღმდეგ“ ჩატარება, მხარეებთან საკორექციო მუშაობის წარმოება და უსაფრთხო გარემოს შექმნა", "შემთხვევის დამალვა მშობლებისგან და უსაფრთხოების წესების განუხილველობა", "მოძალადე მოსწავლის დამცირება კოლექტივის წინაშე და მისი გაკვეთილებიდან იზოლირება", "ძალადობის მსხვერპლი მოსწავლის დადანაშაულება და საკითხის დახურვა", "ძალადობის მსხვერპლი მოსწავლის დაუყოვნებლივი გადაყვანა სხვა საგანმანათლებლო დაწესებულებაში"]'::jsonb, 'შემთხვევის დაუყოვნებლივი მოკვლევა, სკოლის ფსიქოლოგთან და მშობლებთან თანამშრომლობით ტრენინგების „მეგობრობა და ემპათია“, „ერთად ბულინგის წინააღმდეგ“ ჩატარება, მხარეებთან საკორექციო მუშაობის წარმოება და უსაფრთხო გარემოს შექმნა', 'Düzgün cavab: A) შემთხვევის დაუყოვნებლივი მოკვლევა, სკოლის ფსიქოლოგთან და მშობლებთან თანამშრომლობ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('58bcb794-3ceb-4b7a-b162-7292117d95ef', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəbdə intellektual klubların və bilik yarışlarının təşkilində UBTR-in vəzifəsi nədir?', 'multiple_choice', '["Yalnız əlaçı şagirdlərin yarışa qatılmasına icazə verib digərlərini kənarlaşdırmaq", "Yarışların nəticələrini elan etmədən qalibləri gizli saxlamaq", "Yarış suallarını əvvəlcədən sevimli komandaya təqdim edərək qələbəsini təmin etmək", "Yarışların əsasnaməsini, suallar bazasını hazırlamaq, münsiflər heyətini formalaşdırmaq, şəffaf və ədalətli mühitdə komandaların yarışını və mükafatlandırılmasını təmin etmək", "İntellektual oyunları ödənişli kommersiya tədbirinə çevirmək"]'::jsonb, 'Yarışların əsasnaməsini, suallar bazasını hazırlamaq, münsiflər heyətini formalaşdırmaq, şəffaf və ədalətli mühitdə komandaların yarışını və mükafatlandırılmasını təmin etmək', 'Düzgün cavab: D) Yarışların əsasnaməsini, suallar bazasını hazırlamaq, münsiflər heyətini formala', '', 9, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0b01946f-5353-4e3a-86ab-971f6d490608', '58bcb794-3ceb-4b7a-b162-7292117d95ef', 'ka', 'რომელ ორგანოსთან თანხმდება და როგორ მტკიცდება ბავშვთა გაერთიანების ორგანიზაციის წლიური და ყოველთვიური სამოქმედო გეგმა?', '["დამოუკიდებლად მტკიცდება სკოლის დირექტორის მოადგილის მიერ სამეურნეო დარგში", "ზეპირი წესით თანხმდება მხოლოდ კლასის მშობელთა კომიტეტის ხელმძღვანელთან", "მტკიცდება მხოლოდ ადგილობრივი მუნიციპალური ორგანოს საზოგადოებრივი საბჭოს მიერ", "თანხმდება დირექტორის მოადგილესთან აღმზრდელობით დარგში, ინტეგრირდება სკოლის წლიურ სამოქმედო გეგმაში და მტკიცდება სკოლის დირექტორის მიერ", "სამოქმედო გეგმის შედგენისა და ოფიციალური დამტკიცების საჭიროება არ არსებობს"]'::jsonb, 'თანხმდება დირექტორის მოადგილესთან აღმზრდელობით დარგში, ინტეგრირდება სკოლის წლიურ სამოქმედო გეგმაში და მტკიცდება სკოლის დირექტორის მიერ', 'Düzgün cavab: D) თანხმდება დირექტორის მოადგილესთან აღმზრდელობით დარგში, ინტეგრირდება სკოლის წლიურ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b8ef12de-3e33-492d-abf3-da75553c3adb', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəb tədbirlərinin və bayram proqramlarının ssenarilərinin hazırlanmasında UBTR nəyi nəzərə almalıdır?', 'multiple_choice', '["Mövzunun ideya-bədii məzmununu, dövlətçilik prinsiplərini, şagirdlərin yaş və istedad imkanlarını, təhlükəsizlik qaydalarını və tədbirin vaxt reqlamentini", "Tədbir müddətini 5 saatdan artıq uzadaraq şagirdlərin fiziki tükənməsinə səbəb olmaq", "Ssenaridə yalnız xarici dillərdə olan musiqi və mətnlərdən istifadə etmək", "Milli-mənəvi dəyərlərə zidd olan qeyri-etik səhnəciklərin nümayişinə şərait yaratmaq", "Tədbirin hazırlanmasına şagirdləri deyil, yalnız məktəb rəhbərliyini cəlb etmək"]'::jsonb, 'Mövzunun ideya-bədii məzmununu, dövlətçilik prinsiplərini, şagirdlərin yaş və istedad imkanlarını, təhlükəsizlik qaydalarını və tədbirin vaxt reqlamentini', 'Düzgün cavab: A) Mövzunun ideya-bədii məzmununu, dövlətçilik prinsiplərini, şagirdlərin yaş və is', '', 10, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('579a2b4f-8bb7-41db-b7ce-ea6fe0d6db55', 'b8ef12de-3e33-492d-abf3-da75553c3adb', 'ka', 'მოსწავლეთა თავისუფალი დროის ნაყოფიერად ორგანიზებისთვის კლასგარეშე საქმიანობის რომელ ფორმებს უნდა იყენებდეს ბგოხ?', '["ინტელექტუალური თამაშების („რა? სად? როდის?“, „ხამსა“, „ბრეინ-რინგი“), სადებატო კლუბების, მხატვრული კითხვის, მუსიკალური წრეების, ხატვის კონკურსებისა და სპორტული შეჯიბრებების ორგანიზება", "მოსწავლეთა სრული იზოლირება სკოლისგარეშე საზოგადოებრივ ღონისძიებებში მონაწილეობისგან", "მოსწავლეთა გადამისამართება მხოლოდ ფასიანი მოსამზადებელი ცენტრების წრეებში", "მოსწავლეებისთვის გაკვეთილების დროს მხოლოდ კომერციული ფილმების ჩვენების მოწყობა", "მოსწავლეთა მიერ სასკოლო ბიბლიოთეკითა და სამკითხველო დარბაზით სარგებლობის შეზღუდვა"]'::jsonb, 'ინტელექტუალური თამაშების („რა? სად? როდის?“, „ხამსა“, „ბრეინ-რინგი“), სადებატო კლუბების, მხატვრული კითხვის, მუსიკალური წრეების, ხატვის კონკურსებისა და სპორტული შეჯიბრებების ორგანიზება', 'Düzgün cavab: A) ინტელექტუალური თამაშების („რა? სად? როდის?“, „ხამსა“, „ბრეინ-რინგი“), სადებატო კ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('271fe14d-e61c-4ac3-87d2-d2dd548c26b4', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Şagirdlərin asudə vaxtlarında ekoloji tərbiyəsinin və təbiətə qayğının formalaşdırılmasında UBTR hansı layihələri həyata keçirir?', 'multiple_choice', '["Məktəb həyətindəki yaşıllıqların məhv edilməsi aksiyalarını təşkil etmək", "“Yaşıl şəbəkə” ekoloji klubları, tullantıların çeşidlənməsi, kağız və plastik qabların toplanması aksiyaları, quş yuvalarının hazırlanması və təbiət qoynuna ekskursiyalar", "Tullantıların məktəb ərazisində açıq tonqallarda yandırılmasını təbliğ etmək", "Şagirdlərin təbiət qoruqlarına və milli parklara səfərlərini qadağan etmək", "Ekoloji mövzuların dərsdənkənar fəaliyyət proqramından tam çıxarılması"]'::jsonb, '“Yaşıl şəbəkə” ekoloji klubları, tullantıların çeşidlənməsi, kağız və plastik qabların toplanması aksiyaları, quş yuvalarının hazırlanması və təbiət qoynuna ekskursiyalar', 'Düzgün cavab: B) “Yaşıl şəbəkə” ekoloji klubları, tullantıların çeşidlənməsi, kağız və plastik qa', '', 11, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0567d406-260e-46ec-8b6f-fed906971f3d', '271fe14d-e61c-4ac3-87d2-d2dd548c26b4', 'ka', '„ბავშვთა უფლებების თვის“ ფარგლებში რომელი საგანმანათლებლო-საგანმანათლებლო აქტივობა შედის ბგოხ-ის მიერ ორგანიზებულ ღონისძიებებში?', '["მხოლოდ მოსწავლეთა საგნობრივი რვეულებისა და საშინაო დავალებების შესრულების შემოწმება", "ინტერაქტიული მრგვალი მაგიდების, დებატების, ნახატებისა და ესეების კონკურსების, იურისტებთან და ფსიქოლოგებთან შეხვედრების, ფლეშმობების ჩატარება მოსწავლეებისთვის მათი უფლებებისა და მოვალეობების ასახსნელად", "მოსწავლეებისთვის იმ საჯარიმო სანქციების ახსნა, რომლებიც გამოიყენება შინაგანაწესის დარღვევისას", "საგანმანათლებლო ღონისძიებების ორგანიზება მხოლოდ სასწავლო წლის ბოლო კვირაში", "სასკოლო ფორმის გაუქმება და თავისუფალი ჩაცმულობის დღეების გამოცხადება"]'::jsonb, 'ინტერაქტიული მრგვალი მაგიდების, დებატების, ნახატებისა და ესეების კონკურსების, იურისტებთან და ფსიქოლოგებთან შეხვედრების, ფლეშმობების ჩატარება მოსწავლეებისთვის მათი უფლებებისა და მოვალეობების ასახსნელად', 'Düzgün cavab: B) ინტერაქტიული მრგვალი მაგიდების, დებატების, ნახატებისა და ესეების კონკურსების, იუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d5edd099-466c-4011-952b-f858b8877524', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'İnklüziv təhsil mühitində xüsusi qayğıya ehtiyacı olan şagirdlərin məktəbin ictimai həyatına inteqrasiyasında UBTR hansı rolu oynayır?', 'multiple_choice', '["Digər şagirdlərə onlarla ünsiyyət qurmağı qadağan etmək", "Onların tədbirlərdə, dərnəklərdə və yaradıcılıq sərgilərində fəal iştirakını təmin edərək bərabərhüquqlu, empatik və dəstəkləyici sosial mühit formalaşdırmaq", "Xüsusi qayğıya ehtiyacı olan şagirdləri kütləvi tədbirlərdən kənarda saxlamaq", "İnklüziv şagirdlərin yaradıcılıq işlərini sərgilərə buraxmamaq", "Onların məktəb ictimai həyatında iştirakını yalnız formal hesabatlarda göstərmək"]'::jsonb, 'Onların tədbirlərdə, dərnəklərdə və yaradıcılıq sərgilərində fəal iştirakını təmin edərək bərabərhüquqlu, empatik və dəstəkləyici sosial mühit formalaşdırmaq', 'Düzgün cavab: B) Onların tədbirlərdə, dərnəklərdə və yaradıcılıq sərgilərində fəal iştirakını təm', '', 12, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2dc23e85-5efc-42f0-bc01-b82da6ed426b', 'd5edd099-466c-4011-952b-f858b8877524', 'ka', 'ინკლუზიური განათლების მქონე მოსწავლეების საზოგადოებრივ ღონისძიებებში ინტეგრაციისას როგორი მიდგომა უნდა გამოავლინოს ბგოხ-მა?', '["მათი დასმა მხოლოდ მაყურებლის სახით სააქტო დარბაზის უკანა რიგებში", "მათი ინდივიდუალური შესაძლებლობების, ინტერესებისა და უნარების შესაბამისი როლების მინიჭებით ღონისძიებებში აქტიური, თანასწორუფლებიანი ჩართვა, ინკლუზიური და ემპათიური გარემოს გაძლიერება", "სხვა მოსწავლეებისთვის ამ ბავშვებთან ერთობლივ პროექტებში მუშაობის აკრძალვა", "მათი მონაწილეობის დაკავშირება მშობლების მხრიდან სპეციალურ ფინანსურ უზრუნველყოფასთან", "ამ მოსწავლეთა გარიყვა კოლექტიური ღონისძიებებიდან და სადღესასწაულო ზეიმებიდან"]'::jsonb, 'მათი ინდივიდუალური შესაძლებლობების, ინტერესებისა და უნარების შესაბამისი როლების მინიჭებით ღონისძიებებში აქტიური, თანასწორუფლებიანი ჩართვა, ინკლუზიური და ემპათიური გარემოს გაძლიერება', 'Düzgün cavab: B) მათი ინდივიდუალური შესაძლებლობების, ინტერესებისა და უნარების შესაბამისი როლების', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fb7676c4-363f-4d8e-9307-af46353e8a39', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəbdə bullinq (həmyaşıd zorakılığı) hallarının qarşısının alınmasında UBTR hansı profilaktik fəaliyyəti icra edir?', 'multiple_choice', '["Bullinq qurbanı olan şagirdi hamının qarşısında tənqid edərək intizama dəvət etmək", "Zorakılıq faktlarını gizlədərək rəhbərliyə məlumat verməmək", "Təcavüzkar davranış göstərən şagirdi dərhal təhsildən uzaqlaşdırmaq", "Bullinq mövzusunu məktəbdə müzakirə olunması qadağan edilən məsələ elan etmək", "Məktəb psixoloqu və sinif rəhbərləri ilə birlikdə tolerantlıq, empatiya, dostluq mövzularında interaktiv təlimlər, sosial çarxların nümayişi və birgə komanda tədbirləri keçirmək"]'::jsonb, 'Məktəb psixoloqu və sinif rəhbərləri ilə birlikdə tolerantlıq, empatiya, dostluq mövzularında interaktiv təlimlər, sosial çarxların nümayişi və birgə komanda tədbirləri keçirmək', 'Düzgün cavab: E) Məktəb psixoloqu və sinif rəhbərləri ilə birlikdə tolerantlıq, empatiya, dostluq', '', 13, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('fd4510f6-f125-46b6-8d18-36abfb8efbff', 'fb7676c4-363f-4d8e-9307-af46353e8a39', 'ka', 'რა არის დებატების ფორმატის ძირითადი წესი, რომელიც მოსწავლეებში ლიდერული და ორატორული უნარების განსავითარებლად ეწყობა?', '["მსაჯების ოფიციალურ გადაწყვეტილებებზე პროტესტის გამოხატვა და გუნდთან ერთად დარბაზის დატოვება", "ფაქტებისა და წყაროების მითითების გარეშე ოპონენტი მხარის შესახებ უსაფუძვლო მოსაზრებების გამოთქმა", "გამარჯვებულად მხოლოდ იმ გუნდის გამოცხადება, რომელიც ემოციურად და მაღალ ტონალობაში გამოდის", "მოპირდაპირე მხარის სპიკერებზე პირადი მოტივით ზეწოლა და მათი გამოსვლის შეწყვეტინება", "თემის ირგვლივ დასაბუთებულ არგუმენტებზე, ფაქტებზე, ლოგიკაზე, ეთიკურ კომუნიკაციაზე, ურთიერთპატივისცემასა და რეგლამენტის წესებზე დაყრდნობით პოზიციის კულტურულად დაცვა"]'::jsonb, 'თემის ირგვლივ დასაბუთებულ არგუმენტებზე, ფაქტებზე, ლოგიკაზე, ეთიკურ კომუნიკაციაზე, ურთიერთპატივისცემასა და რეგლამენტის წესებზე დაყრდნობით პოზიციის კულტურულად დაცვა', 'Düzgün cavab: E) თემის ირგვლივ დასაბუთებულ არგუმენტებზე, ფაქტებზე, ლოგიკაზე, ეთიკურ კომუნიკაციაზე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('52aa2d4c-aad3-416d-aea0-ff63a6ad97ff', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəbdənkənar ekskursiyaların və muzey dərslərinin təşkilində UBTR hansı əsas təhlükəsizlik qaydasına riayət etməlidir?', 'multiple_choice', '["Şagirdləri təhlükəsizlik qaydaları barədə təlimatlandırmadan yola çıxarmaq", "Valideynlərin yazılı razılığını almağı lazımsız hesab etmək", "Ekskursiyanı direktorun xəbəri və rəsmi əmri olmadan təşkil etmək", "Nəqliyyat vasitəsinin texniki sazlığını və sürücünün sənədlərini yoxlamamaq", "Marşrutun əvvəlcədən razılaşdırılması, direktorun rəsmi əmri, təlimatlandırma, valideynlərin yazılı razılığı, müşayiətedici pedaqoji heyətin və tibbi yardım çantasının təmini"]'::jsonb, 'Marşrutun əvvəlcədən razılaşdırılması, direktorun rəsmi əmri, təlimatlandırma, valideynlərin yazılı razılığı, müşayiətedici pedaqoji heyətin və tibbi yardım çantasının təmini', 'Düzgün cavab: E) Marşrutun əvvəlcədən razılaşdırılması, direktorun rəsmi əmri, təlimatlandırma, v', '', 14, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a2654372-b9d6-4a0a-b832-7a5a109ade78', '52aa2d4c-aad3-416d-aea0-ff63a6ad97ff', 'ka', 'სკოლაში „მოხალისეობრივი მოძრაობის“ განვითარებისას რა საქმიანობისკენ შეუძლია ბგოხ-ს მოსწავლეთა მიმართვა?', '["ძირითადი გაკვეთილების გაცდენა და სკოლისგარეშე დაწესებულებებში მუშაობა", "მოსწავლეებს შორის ფულის შეგროვების კამპანიების ჩატარება", "კომერციული კომპანიების სარეკლამო ბუკლეტების დარიგების პროექტებში ჩართვა", "სასკოლო ფასიანი ღონისძიებების ორგანიზებაში მომსახურე პერსონალის სახით მონაწილეობა", "მარტოხელა ხანდაზმულებზე, ომის ვეტერანებსა და დაღუპულ გმირთა ოჯახებზე ზრუნვა, ეკოლოგიურ დასუფთავებაში, გამწვანებასა და საქველმოქმედო აქციებში, სოციალურ პროექტებში უსასყიდლო მონაწილეობა"]'::jsonb, 'მარტოხელა ხანდაზმულებზე, ომის ვეტერანებსა და დაღუპულ გმირთა ოჯახებზე ზრუნვა, ეკოლოგიურ დასუფთავებაში, გამწვანებასა და საქველმოქმედო აქციებში, სოციალურ პროექტებში უსასყიდლო მონაწილეობა', 'Düzgün cavab: E) მარტოხელა ხანდაზმულებზე, ომის ვეტერანებსა და დაღუპულ გმირთა ოჯახებზე ზრუნვა, ეკო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ca8b5b34-c447-44e7-ba45-6b87da290444', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Şagirdlərin liderlik keyfiyyətlərinin inkişaf etdirilməsi üçün təşkil olunan ''Debat'' klublarında hansı bacarıqlar formalaşdırılır?', 'multiple_choice', '["Yalnız əvvəlcədən əzbərlənmiş mətni heç bir arqument olmadan təkrarlamaq", "Qarşı tərəfi təhqir edərək şəxsi zəmində mübahisə yaratmaq bacarığı", "Tənqidi təfəkkür, arqumentlərlə çıxış etmə, natiqlik mədəniyyəti, qarşı tərəfi dinləmə və tolerantlıq, komandada əsaslandırılmış qərarlar qəbul etmək", "Digər komandanın fikirlərini qərəzli şəkildə inkar edərək səs-küy salmaq", "Debat zamanı reqlament qaydalarını qəsdən pozaraq çıxışı uzatmaq"]'::jsonb, 'Tənqidi təfəkkür, arqumentlərlə çıxış etmə, natiqlik mədəniyyəti, qarşı tərəfi dinləmə və tolerantlıq, komandada əsaslandırılmış qərarlar qəbul etmək', 'Düzgün cavab: C) Tənqidi təfəkkür, arqumentlərlə çıxış etmə, natiqlik mədəniyyəti, qarşı tərəfi d', '', 15, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('13542846-f730-4687-ad62-aeb0547a0c88', 'ca8b5b34-c447-44e7-ba45-6b87da290444', 'ka', 'ვინ არის პასუხისმგებელი მოსწავლეთა უსაფრთხოებაზე კლასგარეშე ღონისძიებებისა და ექსკურსიების დროს?', '["სკოლის სასადილოს საზოგადოებრივი კვების მუშაკები და ტექნიკური პერსონალი", "ღონისძიებაში მონაწილე თითოეული არასრულწლოვანი მოსწავლე ინდივიდუალურად", "ღონისძიებასა და ექსკურსიაზე პასუხისმგებელი, ბრძანებით დანიშნული პირები (ბგოხ, კლასის ხელმძღვანელი, დირექტორის მოადგილე აღმზრდელობით დარგში და თანმხლები პედაგოგები) და სკოლის ხელმძღვანელობა", "მხოლოდ დაქირავებული ტრანსპორტის მძღოლი, რომელიც ახორციელებს გადაყვანას", "იმ მუზეუმის ან პარკის გიდი-მეგზური, სადაც ექსკურსია ტარდება"]'::jsonb, 'ღონისძიებასა და ექსკურსიაზე პასუხისმგებელი, ბრძანებით დანიშნული პირები (ბგოხ, კლასის ხელმძღვანელი, დირექტორის მოადგილე აღმზრდელობით დარგში და თანმხლები პედაგოგები) და სკოლის ხელმძღვანელობა', 'Düzgün cavab: C) ღონისძიებასა და ექსკურსიაზე პასუხისმგებელი, ბრძანებით დანიშნული პირები (ბგოხ, კლ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('5a6e5d7f-174d-4cf5-8550-0ceb598d5384', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Şagirdlərin internet və sosial şəbəkələrdən təhlükəsiz istifadəsi üzrə UBTR-in maarifləndirmə işinə hansı tövsiyə **AİD DEYİLDİR?**', 'multiple_choice', '["Kiberbullinq halları ilə qarşılaşdıqda dərhal valideynə və ya müəllimə məlumat vermək", "Məxfi məlumatların və güclü parolların qorunması qaydalarına riayət etmək", "Sosial şəbəkələrdə etik və mədəni ünsiyyət qaydalarını rəhbər tutmaq", "Şübhəli keçidlərə və naməlum göndəricilərdən gələn fayllara klikləməmək", "Şəxsi məlumatları, ev ünvanını və parolları sosial şəbəkələrdə açıq şəkildə paylaşmaq və tanımadığı şəxslərlə görüş təyin etmək"]'::jsonb, 'Şəxsi məlumatları, ev ünvanını və parolları sosial şəbəkələrdə açıq şəkildə paylaşmaq və tanımadığı şəxslərlə görüş təyin etmək', 'Düzgün cavab: E) Şəxsi məlumatları, ev ünvanını və parolları sosial şəbəkələrdə açıq şəkildə payl', '', 16, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a8f02dc4-78c3-476b-9418-1bd1e3883e39', '5a6e5d7f-174d-4cf5-8550-0ceb598d5384', 'ka', 'რომელი რეკომენდაცია არ განეკუთვნება ბგოხ-ის საგანმანათლებლო მუშაობას ინტერნეტითა და სოციალური ქსელებით მოსწავლეთა უსაფრთხო სარგებლობის შესახებ?', '["პირადი და ოჯახური ინფორმაციის, სახლის მისამართის უცნობ პირებთან არგაზიარება", "კიბერბულინგის შემთხვევებთან შეჯახებისას მშობლის ან მასწავლებლის დაუყოვნებლივი ინფორმირება", "რთული პაროლების გამოყენება და საეჭვო ბმულებზე გადასვლისგან თავის შეკავება", "სოციალურ ქსელებში შეურაცხმყოფელი და მავნე პოსტებისგან კატეგორიულად თავის შეკავება", "უცნობი პირების მიერ გამოგზავნილი ყველა ფაილის, საეჭვო ბმულისა და პროგრამის დაუყოვნებლივ ჩამოტვირთვა და ინსტალაცია, პირადი მონაცემების გაზიარება (აკრძალული ქცევა)"]'::jsonb, 'უცნობი პირების მიერ გამოგზავნილი ყველა ფაილის, საეჭვო ბმულისა და პროგრამის დაუყოვნებლივ ჩამოტვირთვა და ინსტალაცია, პირადი მონაცემების გაზიარება (აკრძალული ქცევა)', 'Düzgün cavab: E) უცნობი პირების მიერ გამოგზავნილი ყველა ფაილის, საეჭვო ბმულისა და პროგრამის დაუყო', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('61872f95-24bc-42d8-b162-e50a46853253', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəb radio qovşağının və ya daxili informasiya bülleteninin fəaliyyətində UBTR hansı məzmunun işıqlandırılmasına rəhbərlik edir?', 'multiple_choice', '["Kənar kommersiya şirkətlərinin pullu reklam elanlarının səsləndirilməsi", "Dərs saatlarında musiqili yayım açaraq tədris prosesinə mane olmaq", "Pedaqoji işçilərin şəxsi həyatına dair şayiələrin tirajlanması", "Şagirdlərin şəxsi sirlərinin və ailə məlumatlarının ictimaiyyətə yayılması", "Məktəbin ictimai həyatı, şagird uğurları, tarixi günlər, maraqlı elmi məlumatlar, təhsil xəbərləri və musiqi-mədəni maarifləndirici anonslar"]'::jsonb, 'Məktəbin ictimai həyatı, şagird uğurları, tarixi günlər, maraqlı elmi məlumatlar, təhsil xəbərləri və musiqi-mədəni maarifləndirici anonslar', 'Düzgün cavab: E) Məktəbin ictimai həyatı, şagird uğurları, tarixi günlər, maraqlı elmi məlumatlar', '', 17, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b345b3d2-0d67-446d-9f6d-9440ed416e0e', '61872f95-24bc-42d8-b162-e50a46853253', 'ka', 'რა არის სკოლაში წრეების „ნორჩი მაშველი“ ან „საგზაო მოძრაობის ნორჩი ინსპექტორები“ შექმნის ძირითადი აღმზრდელობითი მიზანი?', '["მოსწავლეებისთვის სატრანსპორტო საშუალებების სამართავად მართვის მოწმობების გაცემა", "მოსწავლეთა ჩაბმა ქუჩებში საპატრულო სამსახურის თანამშრომლების ნაცვლად მორიგეობაში", "პრივილეგიის შექმნა მოსწავლეთა სასკოლო ატესტატში საგნობრივი ქულების ასამაღლებლად", "სკოლის მოძველებული ინვენტარისა და ავეჯის შეკეთება მოსწავლეთა დახმარებით", "საგანგებო სიტუაციებში, ხანძრისა და საგზაო-სატრანსპორტო შემთხვევების დროს უსაფრთხო ქცევის წესების, პირველადი სამედიცინო დახმარების უნარებისა და მოქალაქეობრივი პასუხისმგებლობის ჩანერგვა მოსწავლეებში"]'::jsonb, 'საგანგებო სიტუაციებში, ხანძრისა და საგზაო-სატრანსპორტო შემთხვევების დროს უსაფრთხო ქცევის წესების, პირველადი სამედიცინო დახმარების უნარებისა და მოქალაქეობრივი პასუხისმგებლობის ჩანერგვა მოსწავლეებში', 'Düzgün cavab: E) საგანგებო სიტუაციებში, ხანძრისა და საგზაო-სატრანსპორტო შემთხვევების დროს უსაფრთხ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3ad77261-2fe9-4519-969c-da2ff5aa1278', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Şagirdlərin sağlam həyat tərzinə istiqamətləndirilməsində və zərərli vərdişlərlə mübarizədə UBTR hansı maarifləndirmə işini aparır?', 'multiple_choice', '["Sağlam həyat tərzi mövzusunda tədbirlərin keçirilməsini ləğv etmək", "Təhsilalanları idman və bədən tərbiyəsi məşğələlərindən yayındırmaq", "“Zərərli vərdişlərə YOX deyək!”, narkomaniya, tütün və alkoqolun fəsadları barədə həkimlərlə görüşlər, idman estafetləri, fləşmoblar və maarifləndirici sərgilər", "Zərərli maddələrin qəbulunun fərdi seçim olduğunu təbliğ etmək", "Yalnız cəza tədbirləri tətbiq edərək maarifləndirmə işindən imtina etmək"]'::jsonb, '“Zərərli vərdişlərə YOX deyək!”, narkomaniya, tütün və alkoqolun fəsadları barədə həkimlərlə görüşlər, idman estafetləri, fləşmoblar və maarifləndirici sərgilər', 'Düzgün cavab: C) “Zərərli vərdişlərə YOX deyək!”, narkomaniya, tütün və alkoqolun fəsadları barəd', '', 18, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('531750c1-5671-4186-b72d-714aa7b7feac', '3ad77261-2fe9-4519-969c-da2ff5aa1278', 'ka', 'პედაგოგიური ურთიერთობის რომელ პრინციპს უნდა იცავდეს ბგოხ მოსწავლეებთან ინდივიდუალური საუბრების წარმართვისას?', '["მოსწავლეთა გაკიცხვა თანატოლების წინაშე და მათში შიშის გრძნობის ჩამოყალიბება", "თანამშრომლობის დამყარება მხოლოდ იმ მოსწავლეებთან, რომელთაც სკოლის ხელმძღვანელობასთან ახლო კავშირი აქვთ", "პიროვნების პატივისცემა, გულწრფელობა, ემპათია, ობიექტურობა, კონფიდენციალურობა და ურთიერთნდობა, თანამშრომლობითი გარემოს შექმნა", "მოსწავლეთა მართვა დისციპლინის დარღვევისას ფიზიკური დასჯის მეთოდების გამოყენებით", "მოსწავლის პირადი ხასიათის საიდუმლოებების გამხელა სხდომებზე მთელი სასკოლო კოლექტივის წინაშე"]'::jsonb, 'პიროვნების პატივისცემა, გულწრფელობა, ემპათია, ობიექტურობა, კონფიდენციალურობა და ურთიერთნდობა, თანამშრომლობითი გარემოს შექმნა', 'Düzgün cavab: C) პიროვნების პატივისცემა, გულწრფელობა, ემპათია, ობიექტურობა, კონფიდენციალურობა და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('59cf3005-1266-45cc-8a9c-94dcd996b6e4', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'UBTR-in tərbiyə işləri üzrə direktor müavini (təşkilatçı) ilə xidməti əlaqəsi və tabeliyi necə tənzimlənir?', 'multiple_choice', '["UBTR yalnız təsərrüfat müdirinə tabe olaraq təsərrüfat tapşırıqlarını icra edir", "Hər iki vəzifə eyni vaxtda mütləq şəkildə fənn müəllimi tərəfindən icra olunmalıdır", "UBTR bilavasitə direktor müavininin (təşkilatçı) rəhbərliyi altında işləyir, onunla birgə tədbirlər planını əlaqələndirir və məktəb direktoruna hesabat verir", "UBTR direktor müavininə tabe deyil və məktəbdə tamamilə müstəqil fəaliyyət göstərir", "Direktor müavini UBTR-in fəaliyyətinə heç bir nəzarət edə bilməz"]'::jsonb, 'UBTR bilavasitə direktor müavininin (təşkilatçı) rəhbərliyi altında işləyir, onunla birgə tədbirlər planını əlaqələndirir və məktəb direktoruna hesabat verir', 'Düzgün cavab: C) UBTR bilavasitə direktor müavininin (təşkilatçı) rəhbərliyi altında işləyir, onu', '', 19, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d77b7fdf-42e1-401e-93bd-22c8e3b17a86', '59cf3005-1266-45cc-8a9c-94dcd996b6e4', 'ka', 'რომელ საქაღალდეში უნდა გროვდებოდეს სკოლაში ჩატარებული საერთო-სასკოლო ღონისძიებების სცენარები და მასალები?', '["მხოლოდ ღონისძიების მონაწილე მოსწავლეთა პირად მეხსიერების ბარათებზე", "ბიბლიოთეკის სახელმძღვანელოების ფონდისა და ლიტერატურის აღრიცხვის კარტოთეკაში", "ბავშვთა გაერთიანების ორგანიზაციის წლიური ღონისძიებების პორტფოლიოში, სამუშაო საქაღალდეში, საანგარიშო ალბომსა და ელექტრონულ არქივში", "სამეურნეო საწყობის ინვენტარის აღრიცხვის საქაღალდეებში", "სკოლის საერთო ელექტროფარისა და ამომრთველების კარადაში"]'::jsonb, 'ბავშვთა გაერთიანების ორგანიზაციის წლიური ღონისძიებების პორტფოლიოში, სამუშაო საქაღალდეში, საანგარიშო ალბომსა და ელექტრონულ არქივში', 'Düzgün cavab: C) ბავშვთა გაერთიანების ორგანიზაციის წლიური ღონისძიებების პორტფოლიოში, სამუშაო საქა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('14fe134c-26e4-4994-a17d-479d70a6bf36', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəbdə bədii-estetik tərbiyənin inkişafı üçün UBTR hansı dərnək və təşəbbüsləri irəli sürə bilər?', 'multiple_choice', '["Şagirdlərin köhnə dərslik və jurnalları cırıb məhv etməsi aksiyalarını", "Yalnız bina daxilində santexnika və təmir-bərpa işlərini icra etmək", "Şagirdləri bədii və klassik ədəbiyyat mütaliəsindən tam çəkindirmək", "Sinif otaqlarının pəncərələrini örtərək dərsləri qaranlıq şəraitdə keçirmək", "Məktəb teatr dərnəyi, xor kollektivi, rəqs ansamblı, rəsm sərgiləri, bədii qiraət müsabiqələri və əl işləri yarmarkaları təşkil etmək"]'::jsonb, 'Məktəb teatr dərnəyi, xor kollektivi, rəqs ansamblı, rəsm sərgiləri, bədii qiraət müsabiqələri və əl işləri yarmarkaları təşkil etmək', 'Düzgün cavab: E) Məktəb teatr dərnəyi, xor kollektivi, rəqs ansamblı, rəsm sərgiləri, bədii qiraə', '', 20, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('4077bcad-fd9c-4e9b-bd4d-6e696d780110', '14fe134c-26e4-4994-a17d-479d70a6bf36', 'ka', 'მოსწავლეებში ესთეტიკური გემოვნებისა და შემოქმედებითი უნარების განსავითარებლად საქმიანობის რომელი სახეობა შეუძლია მოაწყოს ბგოხ-მა?', '["საკლასო ოთახების ფანჯრების დაბნელება და გაკვეთილების ბნელ პირობებში ჩატარება", "აქციები, სადაც მოსწავლეები ძველ სახელმძღვანელოებსა და ჟურნალებს ხევენ და ანადგურებენ", "მოსწავლეთა სრული ჩამოშორება მხატვრული და კლასიკური ლიტერატურის კითხვისგან", "მხოლოდ შენობის შიდა სანტექნიკური და სარემონტო-აღდგენითი სამუშაოების შესრულება", "სასკოლო თეატრალური წრის, გუნდის, ცეკვის ანსამბლის, ნახატების გამოფენების, მხატვრული კითხვის კონკურსებისა და ხელნაკეთი ნივთების ბაზრობების ორგანიზება"]'::jsonb, 'სასკოლო თეატრალური წრის, გუნდის, ცეკვის ანსამბლის, ნახატების გამოფენების, მხატვრული კითხვის კონკურსებისა და ხელნაკეთი ნივთების ბაზრობების ორგანიზება', 'Düzgün cavab: E) სასკოლო თეატრალური წრის, გუნდის, ცეკვის ანსამბლის, ნახატების გამოფენების, მხატვრ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('3a338617-18c1-4143-ac9e-4fed5dcccd8f', '033a9bc7-c2a4-4b06-85d2-7d715a095041', '''Təhsilverənlərin etik davranış Qaydaları''na əsasən, UBTR-in şagirdlərə münasibətdə davranışı necə olmalıdır?', 'multiple_choice', '["Şagirdlərdən şəxsi məişət ehtiyacları üçün təmənna və hədiyyə tələb etmək", "Şagirdlər arasında dini, milli və sosial zəmində fərqlər qoyaraq ayrı-seçkilik etmək", "Şagirdlərin şərəf və ləyaqətinə hörmətlə yanaşmaq, humanist olmaq, ayrı-seçkiliyə yol verməmək, şəffaf və nümunəvi olmaq, etik prinsipləri qorumaq", "Şagirdləri dərslərdən ayıraraq fərdi təsərrüfat işlərinə cəlb etmək", "Şagirdlərlə ünsiyyət zamanı sərt, qeyri-etik və təhqiramiz ifadələrdən istifadə etmək"]'::jsonb, 'Şagirdlərin şərəf və ləyaqətinə hörmətlə yanaşmaq, humanist olmaq, ayrı-seçkiliyə yol verməmək, şəffaf və nümunəvi olmaq, etik prinsipləri qorumaq', 'Düzgün cavab: C) Şagirdlərin şərəf və ləyaqətinə hörmətlə yanaşmaq, humanist olmaq, ayrı-seçkiliy', '', 21, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c53cd44d-b243-4b47-b8d3-9bb63463203e', '3a338617-18c1-4143-ac9e-4fed5dcccd8f', 'ka', '„პედაგოგთა ეთიკური ქცევის წესების“ თანახმად, როგორი უნდა იყოს ბგოხ-ის ქცევა მოსწავლეებთან მიმართებაში?', '["მოსწავლეებისგან პირადი საყოფაცხოვრებო საჭიროებებისთვის ანგარებისა და საჩუქრების მოთხოვნა", "მოსწავლეთა გაკვეთილებიდან მოწყვეტა და პირადი სამეურნეო სამუშაოებისთვის გამოყენება", "მოსწავლეთა პატივისა და ღირსების პატივისცემა, ჰუმანურობა, დისკრიმინაციის დაუშვებლობა, გამჭვირვალობა, სამაგალითო ქცევა და ეთიკური პრინციპების დაცვა", "მოსწავლეებს შორის რელიგიურ, ეროვნულ და სოციალურ ნიადაგზე განსხვავებების შექმნა და დისკრიმინაცია", "მოსწავლეებთან ურთიერთობისას უხეში, არაეთიკური და შეურაცხმყოფელი გამონათქვამების გამოყენება"]'::jsonb, 'მოსწავლეთა პატივისა და ღირსების პატივისცემა, ჰუმანურობა, დისკრიმინაციის დაუშვებლობა, გამჭვირვალობა, სამაგალითო ქცევა და ეთიკური პრინციპების დაცვა', 'Düzgün cavab: C) მოსწავლეთა პატივისა და ღირსების პატივისცემა, ჰუმანურობა, დისკრიმინაციის დაუშვებლ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c1ae9781-6ad3-4e62-8c30-71862bc0d87a', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəb Şagird Parlamenti seçkilərinin təşkilində UBTR hansı demokratik prinsipi təmin etməlidir?', 'multiple_choice', '["Yalnız yüksək sosial statuslu ailələrin uşaqlarının namizədliyini irəli sürmək", "Bütün namizədlər üçün bərabər təşviqat şəraitini, könüllülük, bərabərlik, gizli, şəffaf və ədalətli səsvermə prosesini və nəticələrin açıq hesablanmasını", "Seçki bülletenlərinin səslər hesablanmadan dərhal məhv edilməsini", "Seçki qalibinin səsvermə olmadan məktəb rəhbərliyi tərəfindən əvvəlcədən təyin edilməsini", "İbtidai və orta sinif şagirdlərinin səsvermə hüququndan tam məhrum olunmasını"]'::jsonb, 'Bütün namizədlər üçün bərabər təşviqat şəraitini, könüllülük, bərabərlik, gizli, şəffaf və ədalətli səsvermə prosesini və nəticələrin açıq hesablanmasını', 'Düzgün cavab: B) Bütün namizədlər üçün bərabər təşviqat şəraitini, könüllülük, bərabərlik, gizli,', '', 22, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8014d828-5510-4ea9-b35a-02b2d75ac994', 'c1ae9781-6ad3-4e62-8c30-71862bc0d87a', 'ka', 'სკოლის მოსწავლეთა პარლამენტის არჩევნების ორგანიზებისას რომელი დემოკრატიული პრინციპი უნდა უზრუნველყოს ბგოხ-მა?', '["საარჩევნო ბიულეტენების დაუყოვნებლივი განადგურება ხმების დათვლის გარეშე", "თანაბარი სააგიტაციო პირობები ყველა კანდიდატისთვის, ნებაყოფლობითობა, თანასწორობა, ფარული, გამჭვირვალე და სამართლიანი კენჭისყრის პროცესი და შედეგების ღია დათვლა", "არჩევნებში გამარჯვებულის წინასწარ დანიშვნა სკოლის ხელმძღვანელობის მიერ კენჭისყრის გარეშე", "დაწყებითი და საბაზო კლასების მოსწავლეთა სრული ჩამორთმევა ხმის მიცემის უფლებისგან", "კანდიდატებად მხოლოდ მაღალი სოციალური სტატუსის მქონე ოჯახების შვილების წამოყენება"]'::jsonb, 'თანაბარი სააგიტაციო პირობები ყველა კანდიდატისთვის, ნებაყოფლობითობა, თანასწორობა, ფარული, გამჭვირვალე და სამართლიანი კენჭისყრის პროცესი და შედეგების ღია დათვლა', 'Düzgün cavab: B) თანაბარი სააგიტაციო პირობები ყველა კანდიდატისთვის, ნებაყოფლობითობა, თანასწორობა,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('489e3cbb-055c-4c6c-a394-2f9170d34047', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Şagirdlərin dərsdənkənar fəaliyyətə cəlb olunması zamanı onların tədris dərslərindən yayınması barədə qayda nəyi tələb edir?', 'multiple_choice', '["Tədbirdə iştirak edən şagirdlərə bütün fənlərdən imtahansız avtomatik əla qiymət yazılmalıdır", "Dərsdənkənar tədbirlər illik akademik tədris proqramını tamamilə əvəz etməlidir", "Şagirdlər müəllimin icazəsi olmadan istənilən saatda dərsləri tərk edə bilərlər", "Tədbirlər və dərnəklər şagirdlərin tədris dərslərinə, akademik nailiyyətinə mane olmamalı, dərsdənkənar vaxtlarda, tənəffüslərdə və ya dərsdən sonra təşkil edilməlidir", "Şagirdlərin əsas tədris dərslərində iştirakı tədbir günlərində tamamilə ləğv olunmalıdır"]'::jsonb, 'Tədbirlər və dərnəklər şagirdlərin tədris dərslərinə, akademik nailiyyətinə mane olmamalı, dərsdənkənar vaxtlarda, tənəffüslərdə və ya dərsdən sonra təşkil edilməlidir', 'Düzgün cavab: D) Tədbirlər və dərnəklər şagirdlərin tədris dərslərinə, akademik nailiyyətinə mane', '', 23, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('0bdbd0d0-f966-49bc-b466-e4373497d6a6', '489e3cbb-055c-4c6c-a394-2f9170d34047', 'ka', 'მოსწავლეთა კლასგარეშე საქმიანობაში ჩართვისას რას მოითხოვს წესი გაკვეთილების გაცდენასთან დაკავშირებით?', '["ღონისძიებაში მონაწილე მოსწავლეებს ყველა საგანში გამოცდის გარეშე ავტომატურად უნდა დაეწეროთ ფრიადი შეფასება", "ღონისძიების დღეებში მოსწავლეთა მონაწილეობა ძირითად სასწავლო გაკვეთილებში სრულად უნდა გაუქმდეს", "კლასგარეშე ღონისძიებებმა სრულად უნდა ჩაანაცვლოს წლიური აკადემიური სასწავლო პროგრამა", "ღონისძიებები და წრეები ხელს არ უნდა უშლიდეს მოსწავლეთა სასწავლო გაკვეთილებსა და აკადემიურ მოსწრებას; ისინი უნდა მოეწყოს გაკვეთილების შემდგომ თავისუფალ დროს, შესვენებებზე ან გაკვეთილების დასრულების შემდეგ", "მოსწავლეებს შეუძლიათ მასწავლებლის ნებართვის გარეშე ნებისმიერ დროს დატოვონ გაკვეთილები"]'::jsonb, 'ღონისძიებები და წრეები ხელს არ უნდა უშლიდეს მოსწავლეთა სასწავლო გაკვეთილებსა და აკადემიურ მოსწრებას; ისინი უნდა მოეწყოს გაკვეთილების შემდგომ თავისუფალ დროს, შესვენებებზე ან გაკვეთილების დასრულების შემდეგ', 'Düzgün cavab: D) ღონისძიებები და წრეები ხელს არ უნდა უშლიდეს მოსწავლეთა სასწავლო გაკვეთილებსა და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('88553ab3-66f1-4d3f-ab4c-bb5e45f386bd', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Ümumtəhsil məktəblərində ''Kiçik Akademiya''ların yaradılmasında UBTR-in vəzifəsi nədir?', 'multiple_choice', '["Elmə və tədqiqata marağı olan, istedadlı şagirdləri aşkar edib, onların elmi-tədqiqat layihələrinə, müsabiqələrə və olimpiadalara, konfranslara təşkilati və metodiki dəstək vermək", "Məktəbin fənn laboratoriyalarını və təcrübə otaqlarını şagirdlərin üzünə bağlamaq", "Şagirdlərin humanitar və təbiət fənlərini öyrənməsinə qadağa qoymaq", "Şagirdlərə məktəbdaxili elmi dərəcələr və saxta sertifikatlar paylamaq", "Yalnız xarici elmi jurnallara məcburi ödənişli abunə kampaniyalarını təşkil etmək"]'::jsonb, 'Elmə və tədqiqata marağı olan, istedadlı şagirdləri aşkar edib, onların elmi-tədqiqat layihələrinə, müsabiqələrə və olimpiadalara, konfranslara təşkilati və metodiki dəstək vermək', 'Düzgün cavab: A) Elmə və tədqiqata marağı olan, istedadlı şagirdləri aşkar edib, onların elmi-təd', '', 24, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('96b229e9-753d-453c-9c5b-cefb0ce66026', '88553ab3-66f1-4d3f-ab4c-bb5e45f386bd', 'ka', 'რა არის ბგოხ-ის მოვალეობა ზოგადსაგანმანათლებლო სკოლებში „მცირე აკადემიების“ შექმნისას?', '["მეცნიერებითა და კვლევით დაინტერესებული, ნიჭიერი მოსწავლეების გამოვლენა და მათი სამეცნიერო-კვლევითი პროექტების, კონკურსების, ოლიმპიადებისა და კონფერენციების საორგანიზაციო და მეთოდიკური მხარდაჭერა", "მოსწავლეებისთვის შიდასასკოლო სამეცნიერო ხარისხებისა და ყალბი სერტიფიკატების დარიგება", "სკოლის საგნობრივი ლაბორატორიებისა და საცდელი ოთახების დაკეტვა მოსწავლეებისთვის", "მოსწავლეებისთვის ჰუმანიტარული და საბუნებისმეტყველო საგნების შესწავლის აკრძალვა", "მხოლოდ უცხოურ სამეცნიერო ჟურნალებზე სავალდებულო ფასიანი გამოწერის კამპანიების ორგანიზება"]'::jsonb, 'მეცნიერებითა და კვლევით დაინტერესებული, ნიჭიერი მოსწავლეების გამოვლენა და მათი სამეცნიერო-კვლევითი პროექტების, კონკურსების, ოლიმპიადებისა და კონფერენციების საორგანიზაციო და მეთოდიკური მხარდაჭერა', 'Düzgün cavab: A) მეცნიერებითა და კვლევით დაინტერესებული, ნიჭიერი მოსწავლეების გამოვლენა და მათი ს', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e844c979-f32a-4c79-9374-d464ca59b6f1', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəb divar qəzetlərinin və şagird guşələrinin tərtibatında UBTR hansı tələbə nəzarət etməlidir?', 'multiple_choice', '["Mətnlərin heç bir orfoqrafik və qrammatik yoxlama aparılmadan dərc olunmasına", "Məzmunun tərbiyəvi, maarifləndirici, informativ, dövlətçilik və milli-mənəvi dəyərlərə uyğun olmasına, estetik tərtibata və şagird əməyini, yaradıcılığını əks etdirməsinə", "Qəzet səhifələrində kənar kommersiya məhsullarının ödənişli reklamlarının verilməsinə", "Divar qəzetinin şagirdlərin daxil ola bilmədiyi qapalı otaqlarda yerləşdirilməsinə", "Qəzetdə yalnız rəhbər heyətin fərdi fotoşəkillərinin və qərarlarının yer almasına"]'::jsonb, 'Məzmunun tərbiyəvi, maarifləndirici, informativ, dövlətçilik və milli-mənəvi dəyərlərə uyğun olmasına, estetik tərtibata və şagird əməyini, yaradıcılığını əks etdirməsinə', 'Düzgün cavab: B) Məzmunun tərbiyəvi, maarifləndirici, informativ, dövlətçilik və milli-mənəvi dəy', '', 25, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('938ee2ee-a110-4eeb-84d7-9d2ed2e27bad', 'e844c979-f32a-4c79-9374-d464ca59b6f1', 'ka', 'სასკოლო კედლის გაზეთებისა და მოსწავლეთა კუთხეების გაფორმებისას რომელ მოთხოვნას უნდა აკონტროლებდეს ბგოხ?', '["გაზეთში მხოლოდ ხელმძღვანელი პირების პირადი ფოტოსურათებისა და გადაწყვეტილებების განთავსებას", "შინაარსის შესაბამისობას აღმზრდელობით, საგანმანათლებლო, საინფორმაციო, სახელმწიფოებრივ და ეროვნულ-ზნეობრივ ღირებულებებთან, ესთეტიკურ გაფორმებას და მოსწავლეთა შრომისა და შემოქმედების ასახვას", "კედლის გაზეთის განთავსებას დახურულ ოთახებში, სადაც მოსწავლეები ვერ შედიან", "გაზეთის გვერდებზე გარე კომერციული პროდუქციის ფასიანი რეკლამის განთავსებას", "ტექსტების გამოქვეყნებას ყოველგვარი ორთოგრაფიული და გრამატიკული შემოწმების გარეშე"]'::jsonb, 'შინაარსის შესაბამისობას აღმზრდელობით, საგანმანათლებლო, საინფორმაციო, სახელმწიფოებრივ და ეროვნულ-ზნეობრივ ღირებულებებთან, ესთეტიკურ გაფორმებას და მოსწავლეთა შრომისა და შემოქმედების ასახვას', 'Düzgün cavab: B) შინაარსის შესაბამისობას აღმზრდელობით, საგანმანათლებლო, საინფორმაციო, სახელმწიფოე', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9adeed07-8c28-44db-a227-0f694c61f809', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Məktəb tədbirində elektrik və səs avadanlıqlarından istifadə zamanı hansı qayda pozuntu sayılır?', 'multiple_choice', '["Tədbir zalında odsöndürən balonların işlək vəziyyətdə hazır saxlanılması", "Avadanlıqların standart torpaqlanmış rozetkalara qaydalara uyğun qoşulması", "Bütün elektrik naqillərinin izolyasiya örtüyünün tədbirdən əvvəl yoxlanılması", "Tədbir bitdikdən sonra səs gücləndirici aparatların şəbəkədən dərhal ayrılması", "Səhnə keçidlərində açıq və zədəli, izolyasiyası pozulmuş elektrik kabellərinin şagirdlərin ayaqları altına, keçid yollarına səpələnməsi, qoruyucu olmadan saxlanılması"]'::jsonb, 'Səhnə keçidlərində açıq və zədəli, izolyasiyası pozulmuş elektrik kabellərinin şagirdlərin ayaqları altına, keçid yollarına səpələnməsi, qoruyucu olmadan saxlanılması', 'Düzgün cavab: E) Səhnə keçidlərində açıq və zədəli, izolyasiyası pozulmuş elektrik kabellərinin ş', '', 26, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('64e35280-ddd4-43f8-9176-e829a7feb5eb', '9adeed07-8c28-44db-a227-0f694c61f809', 'ka', 'სასკოლო ღონისძიებაზე ელექტრო- და ხმის აპარატურის გამოყენებისას რომელი ქმედება ითვლება წესების დარღვევად?', '["ღონისძიების დაწყებამდე ყველა ელექტროსადენის იზოლაციის შემოწმება", "ღონისძიების დასრულების შემდეგ ხმის გამაძლიერებელი აპარატურის ქსელიდან დაუყოვნებლივ გამორთვა", "აპარატურის წესების შესაბამისად ჩართვა სტანდარტულ დამიწებულ როზეტებში", "ღონისძიების დარბაზში ცეცხლსაქრობების მუშა მდგომარეობაში მზადყოფნა", "სცენის გასასვლელებში ღია, დაზიანებული და იზოლაციადარღვეული ელექტროკაბელების მოსწავლეთა ფეხქვეშ, გასასვლელ გზებზე გაშლა დამცავი საფარის გარეშე"]'::jsonb, 'სცენის გასასვლელებში ღია, დაზიანებული და იზოლაციადარღვეული ელექტროკაბელების მოსწავლეთა ფეხქვეშ, გასასვლელ გზებზე გაშლა დამცავი საფარის გარეშე', 'Düzgün cavab: E) სცენის გასასვლელებში ღია, დაზიანებული და იზოლაციადარღვეული ელექტროკაბელების მოსწ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('b13d1226-5ce2-4e57-80d2-2392b7381f44', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Şagirdlərin asudə vaxtlarında idman və hərəkətli oyunlara cəlb olunmasında UBTR-in əsas məqsədi nədir?', 'multiple_choice', '["Şagirdlərə yalnız peşəkar kommersiya klubları ilə pullu idman müqavilələri bağlatdırmaq", "İdman yarışlarında məğlub olan siniflərin təhsil göstəricilərini aşağı salmaq", "Fiziki hazırlığı zəif olan şagirdləri bütün idman dərnəklərindən birdəfəlik kənarlaşdırmaq", "Şagirdlərin fiziki sağlamlığını, çevikliyini, komandada işləmək, liderlik və kollektiv həmrəylik, fair-play hisslərini möhkəmləndirmək və sağlam həyat tərzini təbliğ etmək", "Şagirdləri tədris dərslərindən ayıraraq gün boyu yalnız stadionda saxlamaq"]'::jsonb, 'Şagirdlərin fiziki sağlamlığını, çevikliyini, komandada işləmək, liderlik və kollektiv həmrəylik, fair-play hisslərini möhkəmləndirmək və sağlam həyat tərzini təbliğ etmək', 'Düzgün cavab: D) Şagirdlərin fiziki sağlamlığını, çevikliyini, komandada işləmək, liderlik və kol', '', 27, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f5670a8a-fe07-4143-8a5f-19b0fc5f8dbd', 'b13d1226-5ce2-4e57-80d2-2392b7381f44', 'ka', 'რა არის ბგოხ-ის მთავარი მიზანი მოსწავლეთა ჩართვისას თავისუფალ დროს სპორტულ და მოძრავ თამაშებში?', '["მოსწავლეთათვის მხოლოდ პროფესიულ კომერციულ კლუბებთან ფასიანი სპორტული კონტრაქტების გაფორმება", "სპორტულ შეჯიბრებებში დამარცხებული კლასების სასწავლო მაჩვენებლების დაქვეითება", "სუსტი ფიზიკური მომზადების მქონე მოსწავლეების სამუდამოდ ჩამოშორება ყველა სპორტული წრიდან", "მოსწავლეთა ფიზიკური ჯანმრთელობისა და მოქნილობის განმტკიცება, გუნდური მუშაობის, ლიდერობის, კოლექტიური სოლიდარობისა და სამართლიანი თამაშის (fair-play) გრძნობების გამყარება და ჯანსაღი ცხოვრების წესის პროპაგანდა", "მოსწავლეთა გაკვეთილებიდან მოწყვეტა და მთელი დღის განმავლობაში მხოლოდ სტადიონზე დატოვება"]'::jsonb, 'მოსწავლეთა ფიზიკური ჯანმრთელობისა და მოქნილობის განმტკიცება, გუნდური მუშაობის, ლიდერობის, კოლექტიური სოლიდარობისა და სამართლიანი თამაშის (fair-play) გრძნობების გამყარება და ჯანსაღი ცხოვრების წესის პროპაგანდა', 'Düzgün cavab: D) მოსწავლეთა ფიზიკური ჯანმრთელობისა და მოქნილობის განმტკიცება, გუნდური მუშაობის, ლ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f2f2c8cb-a9c7-4dd4-b91d-a24b85f565fc', '033a9bc7-c2a4-4b06-85d2-7d715a095041', '''Zəfər Günü'' və ''Dövlət Bayrağı Günü'' münasibətilə məktəbdə keçirilən tədbirlərdə UBTR hansı təşkilati işi görməlidir?', 'multiple_choice', '["Şagirdlərin bayram tədbirlərində iştirakını məcburi imtahan balı ilə şərtləndirmək", "Tədbiri məktəb binasından kənarda kommersiya zalında ödənişli təşkil etmək", "Tədbirin bədii-musiqili ssenarisini, videoçarxını hazırlamaq, şagirdlərin çıxışlarını, şeir və mahnılarını təşkil etmək, qaziləri, şəhid ailələrini dəvət etmək və sərgi təşkil etmək", "Yalnız fənn müəllimlərinin çıxışları ilə kifayətlənib şagirdləri prosesə cəlb etməmək", "Tədbir keçirmədən yalnız şagirdlərin davamiyyət jurnalına qeydiyyat aparmaq"]'::jsonb, 'Tədbirin bədii-musiqili ssenarisini, videoçarxını hazırlamaq, şagirdlərin çıxışlarını, şeir və mahnılarını təşkil etmək, qaziləri, şəhid ailələrini dəvət etmək və sərgi təşkil etmək', 'Düzgün cavab: C) Tədbirin bədii-musiqili ssenarisini, videoçarxını hazırlamaq, şagirdlərin çıxışl', '', 28, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('025f018c-f3fd-437d-b355-ea2f7cae64b3', 'f2f2c8cb-a9c7-4dd4-b91d-a24b85f565fc', 'ka', 'რა საორგანიზაციო სამუშაო უნდა შეასრულოს ბგოხ-მა სკოლაში „გამარჯვების დღისა“ და „სახელმწიფო დროშის დღისადმი“ მიძღვნილ ღონისძიებებზე?', '["ღონისძიების ჩატარების გარეშე მხოლოდ მოსწავლეთა დასწრების ჟურნალში აღრიცხვის წარმოება", "ღონისძიების ფასიან საფუძველზე ორგანიზება სკოლის შენობის გარეთ არსებულ კომერციულ დარბაზში", "ღონისძიების მხატვრულ-მუსიკალური სცენარისა და ვიდეორგოლის მომზადება, მოსწავლეთა გამოსვლების, ლექსებისა და სიმღერების ორგანიზება, ომის ვეტერანებისა და დაღუპულ გმირთა ოჯახების მოწვევა და გამოფენის მოწყობა", "მოსწავლეთა მონაწილეობის დაკავშირება სავალდებულო საგამოცდო ქულასთან", "მხოლოდ საგნის მასწავლებელთა გამოსვლებით შემოფარგვლა და მოსწავლეთა პროცესში არჩართვა"]'::jsonb, 'ღონისძიების მხატვრულ-მუსიკალური სცენარისა და ვიდეორგოლის მომზადება, მოსწავლეთა გამოსვლების, ლექსებისა და სიმღერების ორგანიზება, ომის ვეტერანებისა და დაღუპულ გმირთა ოჯახების მოწვევა და გამოფენის მოწყობა', 'Düzgün cavab: C) ღონისძიების მხატვრულ-მუსიკალური სცენარისა და ვიდეორგოლის მომზადება, მოსწავლეთა გ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('d5b6b8c6-d104-474a-9c4b-ba4229519f9f', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Uşaq təşkilatının rəhbəri kimi UBTR məktəb valideyn komitələri ilə münasibətləri necə tənzimləməlidir?', 'multiple_choice', '["Valideynlərdən hər tədbir üçün məcburi nağd pul vəsaiti toplamaq", "Şagirdlərin dərsdənkənar uğurları barədə valideynlərə məlumat verməkdən imtina etmək", "Valideyn komitəsinin fəaliyyətini yalnız inzibati cəzaların tətbiqinə yönəltmək", "Valideynlərlə səmərəli əməkdaşlıq edərək, şagirdlərin asudə vaxtının, tərbiyəvi tədbirlərin və sosial layihələrin təşkilinə onların könüllü dəstəyini, təcrübəsini cəlb etmək", "Valideynlərin məktəbin ictimai və tərbiyəvi həyatında iştirakına tam qadağa qoymaq"]'::jsonb, 'Valideynlərlə səmərəli əməkdaşlıq edərək, şagirdlərin asudə vaxtının, tərbiyəvi tədbirlərin və sosial layihələrin təşkilinə onların könüllü dəstəyini, təcrübəsini cəlb etmək', 'Düzgün cavab: D) Valideynlərlə səmərəli əməkdaşlıq edərək, şagirdlərin asudə vaxtının, tərbiyəvi', '', 29, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('810f29a8-0a6c-4b56-847a-18ba2d7ff1dd', 'd5b6b8c6-d104-474a-9c4b-ba4229519f9f', 'ka', 'როგორ უნდა დაარეგულიროს ბგოხ-მა ურთიერთობა სასკოლო მშობელთა კომიტეტებთან, როგორც ბავშვთა ორგანიზაციის ხელმძღვანელმა?', '["მშობლებისთვის ინფორმაციის მიწოდებაზე უარის თქმა მოსწავლეთა კლასგარეშე წარმატებების შესახებ", "მშობელთა კომიტეტის საქმიანობის მიმართვა მხოლოდ ადმინისტრაციული სასჯელების გამოყენებისკენ", "მშობლებისგან ყოველი ღონისძიებისთვის ნაღდი ფულადი სახსრების სავალდებულო შეგროვება", "მშობლებთან ნაყოფიერი თანამშრომლობით, მოსწავლეთა თავისუფალი დროის, აღმზრდელობითი ღონისძიებებისა და სოციალური პროექტების ორგანიზებაში მათი ნებაყოფლობითი მხარდაჭერისა და გამოცდილების ჩართვა", "მშობლებისთვის სკოლის საზოგადოებრივ და აღმზრდელობით ცხოვრებაში მონაწილეობის სრული აკრძალვა"]'::jsonb, 'მშობლებთან ნაყოფიერი თანამშრომლობით, მოსწავლეთა თავისუფალი დროის, აღმზრდელობითი ღონისძიებებისა და სოციალური პროექტების ორგანიზებაში მათი ნებაყოფლობითი მხარდაჭერისა და გამოცდილების ჩართვა', 'Düzgün cavab: D) მშობლებთან ნაყოფიერი თანამშრომლობით, მოსწავლეთა თავისუფალი დროის, აღმზრდელობითი', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('874f0954-1649-4062-a9ca-a95d5df596d5', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Şagirdlərin yaradıcılıq və fəallığını stimullaşdırmaq üçün UBTR hansı təltifat metodundan istifadə edə bilər?', 'multiple_choice', '["Həvəsləndirmə tədbirlərindən tam imtina edərək yalnız cəza mexanizmini tətbiq etmək", "Fəal şagirdləri Uşaq Təşkilatının Fəxri Fərmanı, Təşəkkürnaməsi, diplomu və xatirə hədiyyələri ilə, məktəb saytında işıqlandırmaqla mükafatlandırmaq", "Şagirdləri digər sinif yoldaşları qarşısında tənqid edərək rəqabət yaratmaq", "Fəal şagirdlərə fənn müəllimlərindən xahiş edərək saxta imtahan balları yazdırmaq", "Yalnız qalib gələn şagirdlərə pul mükafatı paylayaraq digərlərini cəzalandırmaq"]'::jsonb, 'Fəal şagirdləri Uşaq Təşkilatının Fəxri Fərmanı, Təşəkkürnaməsi, diplomu və xatirə hədiyyələri ilə, məktəb saytında işıqlandırmaqla mükafatlandırmaq', 'Düzgün cavab: B) Fəal şagirdləri Uşaq Təşkilatının Fəxri Fərmanı, Təşəkkürnaməsi, diplomu və xati', '', 30, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('1967e5f6-1a96-4242-bcde-7f4456c74795', '874f0954-1649-4062-a9ca-a95d5df596d5', 'ka', 'მოსწავლეთა შემოქმედებითობისა და აქტიურობის სტიმულირებისთვის წახალისების რა მეთოდი შეუძლია გამოიყენოს ბგოხ-მა?', '["მოსწავლეთა გაკრიტიკება თანაკლასელების წინაშე კონკურენციის შესაქმნელად", "აქტიური მოსწავლეების დაჯილდოება ბავშვთა ორგანიზაციის საპატიო სიგელით, მადლობის წერილით, დიპლომითა და სამახსოვრო საჩუქრებით, მათი წარმატების გაშუქება სკოლის ვებგვერდზე", "აქტიური მოსწავლეებისთვის საგნის მასწავლებლებთან თხოვნით ყალბი საგამოცდო ქულების დაწერა", "წახალისების ღონისძიებებზე სრული უარის თქმა და მხოლოდ დასჯის მექანიზმის გამოყენება", "ფულადი ჯილდოს დარიგება მხოლოდ გამარჯვებულ მოსწავლეებზე და სხვების დასჯა"]'::jsonb, 'აქტიური მოსწავლეების დაჯილდოება ბავშვთა ორგანიზაციის საპატიო სიგელით, მადლობის წერილით, დიპლომითა და სამახსოვრო საჩუქრებით, მათი წარმატების გაშუქება სკოლის ვებგვერდზე', 'Düzgün cavab: B) აქტიური მოსწავლეების დაჯილდოება ბავშვთა ორგანიზაციის საპატიო სიგელით, მადლობის წ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c27565b5-3b37-48de-9bef-ace74e8241e7', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Azərbaycan Respublikası Konstitusiyasının 42-ci maddəsinə əsasən, vətəndaşların təhsil hüququ ilə bağlı dövlətin əsas təminatı nədir?', 'multiple_choice', '["Dövlət təhsil sistemində bütün pillələrin tamamilə ödənişli əsaslarla təşkil edilməsini qanunvericiliklə tənzimləyir", "Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir", "Dövlət hər bir vətəndaşın ali təhsil almasını məcburi edir və təhsil xərclərini tam şəkildə kommersiya banklarına həvalə edir", "Dövlət yalnız dövlət qulluqçularının övladlarının pulsuz orta ixtisas təhsili almasına hüquqi zəmanət verir", "Dövlət yalnız əlaçı şagirdlərin pulsuz təhsil almasını təmin edir və digər vətəndaşlara ödənişli əsaslarla şərait yaradır"]'::jsonb, 'Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin edir və istedadlı şəxslərin maddi vəziyyətindən asılı olmayaraq təhsilini davam etdirməsinə zəmanət verir', 'Düzgün cavab: B) Dövlət hər bir vətəndaşın pulsuz icbari ümumi orta təhsil almaq hüququnu təmin e', '', 31, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('559b3eee-523e-4926-ba00-79c64ba05fc2', 'c27565b5-3b37-48de-9bef-ace74e8241e7', 'ka', 'კონსტიტუციის 42-ე მუხლის თანახმად, განათლების უფლების უზრუნველყოფასთან დაკავშირებით რომელი დებულებაა განმტკიცებული?', '["სახელმწიფო საგანმანათლებლო დაწესებულებების დაფინანსებას ახორციელებს მხოლოდ მუნიციპალიტეტების ადგილობრივი ბიუჯეტების ხარჯზე", "სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო საბაზო ზოგად განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და სახელმწიფო კონტროლს განათლების სისტემაზე", "სახელმწიფო ყველა მოქალაქეს უზრუნველყოფს უფასო სრული უმაღლესი განათლების მიღების უფლებით სახელმწიფო უმაღლეს საგანმანათლებლო დაწესებულებებში", "სახელმწიფო სავალდებულოდ მიიჩნევს მოქალაქეების მიერ საშუალო პროფესიული განათლების მიღებას მხოლოდ დასწრებული ფორმით", "სახელმწიფო უზრუნველყოფს მხოლოდ ნიჭიერი პირების მიერ განათლების გაგრძელებას მათი მატერიალური მდგომარეობის მიუხედავად"]'::jsonb, 'სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო საბაზო ზოგად განათლებაზე, ნიჭიერი პირების მიერ განათლების გაგრძელებასა და სახელმწიფო კონტროლს განათლების სისტემაზე', 'Düzgün cavab: B) სახელმწიფო უზრუნველყოფს თითოეული მოქალაქის უფლებას უფასო სავალდებულო საბაზო ზოგა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('842f4d21-d226-4a70-b5b1-91376a54e785', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Azərbaycan Respublikası Konstitusiyasının 25-ci maddəsinə əsasən, bərabərlik hüququnun təhsil və əmək münasibətlərində təminatı necə müəyyən olunmuşdur?', 'multiple_choice', '["Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir", "Sosial mənşəyindən və yaşayış yerindən asılı olaraq təhsil müəssisələrinə qəbulda məhdudiyyətlər qoyula bilər", "İşə qəbul və təhsil prosesində yalnız rəhbərliyin subyektiv mülahizələri əsas götürülür və imtiyazlar müəyyən edilir", "Ayrı-seçkiliyə yalnız müəssisə rəhbərinin yazılı əmri və daxili nizamnamə tələbləri ilə yol verilə bilər", "Vətəndaşların hüquq bərabərliyi yalnız dövlət qulluğunda çalışan şəxslərə şamil edilir, digər sahələrdə fərqli münasibət qanunidir"]'::jsonb, 'Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyindən və əmlak vəziyyətindən asılı olmayaraq hər kəsin hüquq və azadlıqlarının bərabərliyinə təminat verir', 'Düzgün cavab: A) Dövlət irqindən, etnik mənsubiyyətindən, dinindən, dilindən, cinsindən, mənşəyin', '', 32, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('be68d29a-e3d3-4966-af36-c50a0534802f', '842f4d21-d226-4a70-b5b1-91376a54e785', 'ka', 'კონსტიტუციის 25-ე მუხლის თანახმად, რომელია სწორი ნორმა, რომელიც ასახავს თანასწორობის უფლების შინაარსს?', '["სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესისა და სოციალური წარმომავლობის მიუხედავად", "სახელმწიფო სასამართლოს წინაშე განსაკუთრებულ პრივილეგიურ თანასწორობის უფლებას ადგენს მხოლოდ საჯარო მოხელეებისთვის", "თანასწორობის უფლება არეგულირებს მხოლოდ 18 წელს მიღწეულ მოქალაქეთა მონაწილეობას საარჩევნო პროცესში", "ადამიანისა და მოქალაქის უფლებები უზრუნველყოფილია მხოლოდ მოქალაქის კერძო საკუთრების მოცულობიდან გამომდინარე", "ყველას უფლებები და თავისუფლებები თანასწორად ითვლება მხოლოდ აღმასრულებელი ხელისუფლების ორგანოს თანხმობის შემთხვევაში"]'::jsonb, 'სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნიკური კუთვნილების, რელიგიის, ენის, სქესისა და სოციალური წარმომავლობის მიუხედავად', 'Düzgün cavab: A) სახელმწიფო უზრუნველყოფს ყველას უფლებათა და თავისუფლებათა თანასწორობას რასის, ეთნ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('ee5e1832-2418-4291-8e57-900158c61fdc', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Azərbaycan Respublikası Konstitusiyasının 32-ci maddəsinə əsasən, şəxsi toxunulmazlıq hüququ təhsil müəssisəsində hansı tələbi irəli sürür?', 'multiple_choice', '["Şəxsin yazışma və telefon danışıqlarının sirri yalnız daxili intizam qaydaları ilə məhdudlaşdırıla bilər", "Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir", "Təhsil müəssisəsi rəhbərliyi işçilərin şəxsi məlumatlarını istədiyi məqsədlə kənar şəxslərə və sosial şəbəkələrə açıqlaya bilər", "İşçilərin fərdi məlumatları və tibbi arayışları kollektiv qarşısında müzakirə edilməli və elan lövhəsinə vurulmalıdır", "Fərdi məlumatların informasiya sistemlərində qeydiyyatı şəxsin xəbəri olmadan istənilən qurum tərəfindən aparıla bilər"]'::jsonb, 'Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılmasına, saxlanılmasına və yayılmasına qanunla müəyyən edilmiş hallar istisna olmaqla yol verilmir', 'Düzgün cavab: B) Vətəndaşın razılığı olmadan onun şəxsi həyatı haqqında məlumatların toplanılması', '', 33, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3c92e7fa-a12b-47f7-a92e-2c1e6676149d', 'ee5e1832-2418-4291-8e57-900158c61fdc', 'ka', 'კონსტიტუციის 32-ე მუხლის თანახმად, რა წესია დადგენილი პირადი ხელშეუხებლობის უფლებასთან დაკავშირებით?', '["საგანმანათლებლო დაწესებულების ხელმძღვანელობას შეუძლია თავისუფლად გაასაჯაროოს ინფორმაცია თანამშრომლის პირადი ცხოვრების შესახებ", "დაუშვებელია მოქალაქის პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა და გავრცელება მისი თანხმობის გარეშე, გარდა კანონით გათვალისწინებული შემთხვევებისა", "პირის მიმოწერისა და სატელეფონო საუბრების საიდუმლოება შეიძლება შეიზღუდოს მხოლოდ შინაგანაწესით", "საინფორმაციო სისტემებში პერსონალური მონაცემების აღრიცხვა შეიძლება განახორციელოს ნებისმიერმა უწყებამ პირის თანხმობის გარეშე", "პირადი ხელშეუხებლობის უფლება მოქმედებს მხოლოდ სამუშაო დროის განმავლობაში, როდესაც პირი ასრულებს სამსახურებრივ მოვალეობებს სამუშაო ადგილზე"]'::jsonb, 'დაუშვებელია მოქალაქის პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა და გავრცელება მისი თანხმობის გარეშე, გარდა კანონით გათვალისწინებული შემთხვევებისა', 'Düzgün cavab: B) დაუშვებელია მოქალაქის პირადი ცხოვრების შესახებ ინფორმაციის შეგროვება, შენახვა და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('24a14cc3-42a1-4d2a-a120-be8701aaed00', '033a9bc7-c2a4-4b06-85d2-7d715a095041', '“Təhsil haqqında” AR Qanununun 3-cü maddəsinə əsasən, dövlət siyasətinin əsas prinsiplərindən olan ''Humanistlik'' nəyi ifadə edir?', 'multiple_choice', '["Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını", "Bütün vətəndaşların fasiləsiz olaraq ömür boyu peşəkar təhsil almaq imkanını", "Təhsil prosesinin milli və beynəlxalq standartların tələblərinə uyğunlaşdırılmasını", "Təhsil sisteminin dünya təhsil məkanına çevik inteqrasiya olunmasını", "Təhsil müəssisələrinin idarə edilməsində ictimaiyyətin iştirakını"]'::jsonb, 'Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və azadlıqlarının, sağlamlığın və təhlükəsizliyin prioritet kimi qəbul olunmasını', 'Düzgün cavab: A) Milli və ümumbəşəri dəyərlərin, şəxsiyyətin azad inkişafının, insan hüquqları və', '', 34, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d6d7c867-0954-44d5-9529-1846b3e66bfe', '24a14cc3-42a1-4d2a-a120-be8701aaed00', 'ka', '„განათლების შესახებ“ კანონის მე-3 მუხლის თანახმად, რას გამოხატავს „ჰუმანიზმი“?', '["ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების აღიარებას პრიორიტეტად", "სასწავლო პროცესის შესაბამისობაში მოყვანას ეროვნული და საერთაშორისო სტანდარტების მოთხოვნებთან", "განათლების სისტემის მოქნილ ინტეგრაციას მსოფლიო საგანმანათლებლო სივრცეში", "ყველა მოქალაქის შესაძლებლობას უწყვეტად, მთელი სიცოცხლის მანძილზე მიიღოს პროფესიული განათლება", "საზოგადოების მონაწილეობას საგანმანათლებლო დაწესებულებების მართვაში"]'::jsonb, 'ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ადამიანის უფლებებისა და თავისუფლებების, ჯანმრთელობისა და უსაფრთხოების აღიარებას პრიორიტეტად', 'Düzgün cavab: A) ეროვნული და ზოგადსაკაცობრიო ღირებულებების, პიროვნების თავისუფალი განვითარების, ა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a5e649f5-1c12-4cdf-9f1e-b79ade699240', '033a9bc7-c2a4-4b06-85d2-7d715a095041', '“Təhsil haqqında” AR Qanununun 12-ci maddəsinə əsasən, təsbit edilmiş təhsil formaları hansılardır?', 'multiple_choice', '["Əyani, qiyabi, distant və sərbəst təhsilalma", "Məktəbəqədər, ümumi orta, ilk peşə və ali təhsil", "İbtidai təhsil, əsas təhsil və tam orta təhsil", "Dövlət təhsili, bələdiyyə təhsili və xüsusi təhsil", "Formal, qeyri-formal və informal təhsil"]'::jsonb, 'Formal, qeyri-formal və informal təhsil', 'Düzgün cavab: E) Formal, qeyri-formal və informal təhsil', '', 35, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('d7ebb926-bfed-4225-8588-ccbb9f32caab', 'a5e649f5-1c12-4cdf-9f1e-b79ade699240', 'ka', '„განათლების შესახებ“ კანონის მე-12 მუხლის თანახმად, განათლების რა ფორმებია განსაზღვრული?', '["დასწრებული, დაუსწრებელი, დისტანციური და თავისუფალი (ექსტერნატი) განათლების მიღება", "დაწყებითი განათლება, საბაზო განათლება და სრული საშუალო განათლება", "სკოლამდელი, საბაზო ზოგადი, პირველადი პროფესიული და უმაღლესი განათლება", "სახელმწიფო განათლება, მუნიციპალური განათლება და სპეციალური განათლება", "ფორმალური, არაფორმალური და ინფორმალური განათლება"]'::jsonb, 'ფორმალური, არაფორმალური და ინფორმალური განათლება', 'Düzgün cavab: E) ფორმალური, არაფორმალური და ინფორმალური განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('db323c49-f4c4-474e-b4aa-557b0b107444', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Müxtəlif səbəblərdən ümumi təhsildən kənarda qalmış şəxslərə təhsil almaq və ya təhsilin hər hansı pilləsini vaxtından əvvəl bitirmək hüququ verən təhsilalma forması hansıdır?', 'multiple_choice', '["Evdə təhsilalma", "Qiyabi təhsilalma", "Sərbəst (eksternat) təhsilalma forması", "İnformal təhsil", "Distant (məsafədən) təhsilalma"]'::jsonb, 'Sərbəst (eksternat) təhsilalma forması', 'Düzgün cavab: C) Sərbəst (eksternat) təhsilalma forması', '', 36, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7c1c39e6-ed1b-4900-96ad-c94c8718c5f8', 'db323c49-f4c4-474e-b4aa-557b0b107444', 'ka', 'განათლების მიღების რომელი ფორმა აძლევს განათლების მიღების უფლებას იმ პირებს, რომლებიც სხვადასხვა მიზეზით დარჩნენ ზოგადი განათლების მიღმა?', '["დისტანციური განათლება", "შინ სწავლება", "თავისუფალი (ექსტერნატის) ფორმით განათლების მიღება", "ინფორმალური განათლება", "დაუსწრებელი სწავლება"]'::jsonb, 'თავისუფალი (ექსტერნატის) ფორმით განათლების მიღება', 'Düzgün cavab: C) თავისუფალი (ექსტერნატის) ფორმით განათლების მიღება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a801c8e5-03aa-4bfb-9822-2bfb7e14d643', '033a9bc7-c2a4-4b06-85d2-7d715a095041', '“Təhsil haqqında” AR Qanununun 32-ci maddəsinə əsasən, təhsilverənlərin vəzifələrinə aid olan müddəa hansıdır?', 'multiple_choice', '["Təhsil müəssisəsinin idarə olunmasında təkliflərlə çıxış etmək", "Yeni tədris proqramlarını və dərslik layihələrini sərbəst şəkildə seçmək", "İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri və müasir texnologiyaları mənimsəyərək tədris prosesində tətbiq etmək", "Təhsil müəssisəsində müvafiq vəzifə tutmaq və seçkili orqanlarda təmsil olunmaq", "Şərəf və ləyaqətinə hörmətlə yanaşılmasını və təhlükəsiz iş şəraitini tələb etmək"]'::jsonb, 'İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri və müasir texnologiyaları mənimsəyərək tədris prosesində tətbiq etmək', 'Düzgün cavab: C) İxtisasını artırmaq, qabaqcıl pedaqoji təcrübələri və müasir texnologiyaları mən', '', 37, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('760bfec4-f353-4a8a-94f5-5e93febc4e03', 'a801c8e5-03aa-4bfb-9822-2bfb7e14d643', 'ka', '„განათლების შესახებ“ კანონის 32-ე მუხლის თანახმად, რომელი დებულება განეკუთვნება პედაგოგთა მოვალეობებს?', '["ახალი სასწავლო პროგრამებისა და სახელმძღვანელოების პროექტების თავისუფლად არჩევა", "საგანმანათლებლო დაწესებულებაში შესაბამისი თანამდებობის დაკავება და არჩევით ორგანოებში წარმომადგენლობა", "კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლოგიების ათვისება და სასწავლო პროცესში დანერგვა", "საგანმანათლებლო დაწესებულების მართვაში წინადადებებით გამოსვლა", "პატივისა და ღირსების პატივისცემის და უსაფრთხო სამუშაო პირობების მოთხოვნა"]'::jsonb, 'კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლოგიების ათვისება და სასწავლო პროცესში დანერგვა', 'Düzgün cavab: C) კვალიფიკაციის ამაღლება, მოწინავე პედაგოგიური გამოცდილებისა და თანამედროვე ტექნოლ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('4ff197c1-aac5-4eb8-b232-e7c84f36a996', '033a9bc7-c2a4-4b06-85d2-7d715a095041', '“Ümumi təhsil haqqında” AR Qanununa əsasən, ümumi təhsil pilləsinin səviyyələri hansı ardıcıllıqla düzgün göstərilmişdir?', 'multiple_choice', '["Yalnız ümumi orta təhsil (I–IX) və tam orta təhsil (X–XI)", "Məktəbəqədər təhsil (3–5 yaş), ümumi təhsil (I–XI) və bakalavriat səviyyəsi", "İbtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və peşə təhsili səviyyəsi", "Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)", "İbtidai təhsil (I–IV), əsas təhsil (V–VIII) və orta ixtisas təhsili (IX–XI)"]'::jsonb, 'Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və tam orta təhsil (X–XI)', 'Düzgün cavab: D) Məktəbəhazırlıq mərhələsi, ibtidai təhsil (I–IV), ümumi orta təhsil (V–IX) və ta', '', 38, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('ae49e475-2b2e-4a05-bf03-674b438584d9', '4ff197c1-aac5-4eb8-b232-e7c84f36a996', 'ka', '„ზოგადი განათლების შესახებ“ კანონის თანახმად, რა საფეხურებს მოიცავს ზოგადი განათლების საფეხური?', '["მხოლოდ საბაზო ზოგადი განათლება (I–IX) და სრული საშუალო განათლება (X–XI)", "სკოლამდელი განათლება (3–5 წელი), ზოგადი განათლება (I–XI) და ბაკალავრიატის საფეხური", "დაწყებითი განათლება (I–IV), ძირითადი განათლება (V–VIII) და საშუალო სპეციალური განათლება (IX–XI)", "სკოლისთვის მომზადების ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული საშუალო განათლება (X–XI)", "დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და პროფესიული განათლების საფეხური"]'::jsonb, 'სკოლისთვის მომზადების ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება (V–IX) და სრული საშუალო განათლება (X–XI)', 'Düzgün cavab: D) სკოლისთვის მომზადების ეტაპი, დაწყებითი განათლება (I–IV), საბაზო ზოგადი განათლება', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('28671f3e-27c5-4e48-be4b-c6cd41fad992', '033a9bc7-c2a4-4b06-85d2-7d715a095041', '“Ümumi təhsil haqqında” AR Qanununun 21-ci maddəsinə əsasən, təhsilalanların hüquqlarına **AİD EDİLMƏYƏN** müddəa hansıdır?', 'multiple_choice', '["Həyat və sağlamlıq üçün təhlükəsiz təhsil şəraiti ilə təmin olunmaq", "Təhsil müəssisəsinin mövcud infrastrukturundan ödənişsiz istifadə etmək", "Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq", "Dövlət və bələdiyyə məktəblərində dərsliklərlə pulsuz təmin olunmaq", "İnsan ləyaqətini alçaldan zorakılıq hallarından müdafiə olunmaq"]'::jsonb, 'Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoji işçilərin fəaliyyətini dayandırmaq', 'Düzgün cavab: C) Müəssisənin daxili intizam qaydalarını birtərəfli şəkildə dəyişdirmək və pedaqoj', '', 39, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b278b14c-7449-4f3c-957b-e42586e746e2', '28671f3e-27c5-4e48-be4b-c6cd41fad992', 'ka', '„ზოგადი განათლების შესახებ“ კანონის 21-ე მუხლის თანახმად, რომელი დებულება არ განეკუთვნება მოსწავლეთა უფლებებს?', '["სახელმწიფო და მუნიციპალურ სკოლებში უფასო სახელმძღვანელოებით უზრუნველყოფა", "სიცოცხლისა და ჯანმრთელობისთვის უსაფრთხო სასწავლო პირობებით უზრუნველყოფა", "დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება", "ადამიანის ღირსების შემლახავი ძალადობის შემთხვევებისგან დაცვა", "საგანმანათლებლო დაწესებულების არსებული ინფრასტრუქტურით უფასოდ სარგებლობა"]'::jsonb, 'დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის შეჩერება', 'Düzgün cavab: C) დაწესებულების შინაგანაწესის ცალმხრივად შეცვლა და პედაგოგიურ მუშაკთა საქმიანობის', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('e43ac27d-de84-456d-8708-5744e0407cb5', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Dövlət və bələdiyyə ümumi təhsil müəssisələrinin Nümunəvi Nizamnaməsinə əsasən, məktəbin fəaliyyətinə cari rəhbərliyi kim həyata keçirir?', 'multiple_choice', '["Təhsil müəssisəsinin Həmkarlar İttifaqı Komitəsinin rəhbəri", "Rayon İcra Hakimiyyətinin təyin etdiyi xüsusi nümayəndə", "Məktəbin Valideyn-Müəllim Assosiasiyasının idarə heyətinin sədri", "Müəssisənin Pedaqoji Şurasının seçkili katibi", "Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən vəzifəyə təyin olunan direktor"]'::jsonb, 'Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən vəzifəyə təyin olunan direktor', 'Düzgün cavab: E) Müvafiq icra hakimiyyəti orqanı (təhsili idarəetmə orqanı) tərəfindən vəzifəyə t', '', 40, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9e32f96d-eb26-46c0-a358-1540b1e63248', 'e43ac27d-de84-456d-8708-5744e0407cb5', 'ka', 'სანიმუშო წესდების თანახმად, ვინ ახორციელებს სკოლის საქმიანობის მიმდინარე ხელმძღვანელობას?', '["რაიონული აღმასრულებელი ხელისუფლების მიერ დანიშნული სპეციალური წარმომადგენელი", "სკოლის მშობელთა და მასწავლებელთა ასოციაციის გამგეობის თავმჯდომარე", "დაწესებულების პედაგოგიური საბჭოს არჩეული მდივანი", "საგანმანათლებლო დაწესებულების პროფკავშირის კომიტეტის ხელმძღვანელი", "შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექტორი"]'::jsonb, 'შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექტორი', 'Düzgün cavab: E) შესაბამისი აღმასრულებელი ხელისუფლების ორგანოს მიერ თანამდებობაზე დანიშნული დირექ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0388358d-328f-4752-a49b-63970e3af6f9', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Ümumi təhsil müəssisələrində Pedaqoji Şura haqqında Əsasnaməyə əsasən, qərarların qəbul edilməsi qaydası necədir?', 'multiple_choice', '["İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilərək direktorun əmri ilə rəsmiləşdirilir", "Pedaqoji Şuranın qərarları tövsiyə xarakteri daşıyır və rəsmi əmrlə təsdiqlənmir", "İclasda yalnız metodbirləşmə rəhbərləri səsvermə hüququna malikdir", "Qərarlar yalnız rayon təhsil sektorunun yazılı razılığı alındıqdan sonra tətbiq edilir", "Qərarlar yalnız məktəb direktorunun fərdi şifahi razılığı ilə qüvvəyə minir"]'::jsonb, 'İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qərarlar sadə səs çoxluğu ilə qəbul edilərək direktorun əmri ilə rəsmiləşdirilir', 'Düzgün cavab: A) İclas üzvlərinin ən azı üçdə iki hissəsi iştirak etdikdə səlahiyyətlidir və qəra', '', 41, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9caba53e-cbf5-4ac0-bf03-65765ae35035', '0388358d-328f-4752-a49b-63970e3af6f9', 'ka', '„პედაგოგიური საბჭოს შესახებ დებულების“ თანახმად, როგორია გადაწყვეტილებების მიღების წესი?', '["სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით", "გადაწყვეტილებები ძალაში შედის მხოლოდ სკოლის დირექტორის პირადი ზეპირი თანხმობით", "სხდომაზე ხმის მიცემის უფლება აქვთ მხოლოდ მეთოდგაერთიანებების ხელმძღვანელებს", "გადაწყვეტილებები გამოიყენება მხოლოდ რაიონული საგანმანათლებლო სექტორის წერილობითი თანხმობის მიღების შემდეგ", "პედაგოგიური საბჭოს გადაწყვეტილებებს აქვს სარეკომენდაციო ხასიათი და არ მტკიცდება ოფიციალური ბრძანებით"]'::jsonb, 'სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვეტილებები მიიღება ხმათა უბრალო უმრავლესობით და ფორმდება დირექტორის ბრძანებით', 'Düzgün cavab: A) სხდომა უფლებამოსილია, თუ მას ესწრება წევრთა არანაკლებ ორი მესამედი, ხოლო გადაწყვ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('762f7ae0-65e1-4d59-ad59-065d22ed90d7', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Azərbaycan Respublikasının Əmək Məcəlləsinin 89 və 91-ci maddələrinə əsasən, iş vaxtının normal və qısaldılmış müddəti necədir?', 'multiple_choice', '["Həftəlik normal iş vaxtı 45 saat, pedaqoji heyət üçün 18 saatdan çox ola bilməz", "Bütün işçilər üçün vahid həftəlik 40 saatlıq tam iş vaxtı tətbiq olunur", "Həftəlik normal iş vaxtı 36 saat, hamilə qadınlar üçün 24 saat müəyyən edilir", "Həftəlik normal iş vaxtı 48 saat, 16 yaşınadək işçilər üçün 36 saatdan çox ola bilməz", "Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz"]'::jsonb, 'Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün isə həftədə 36 saatdan artıq ola bilməz', 'Düzgün cavab: E) Həftəlik normal iş vaxtı 40 saatdan, I və II dərəcə əlilliyi olan şəxslər üçün i', '', 42, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('79a54b52-08bf-4c8c-aaef-15fd3bc29bb6', '762f7ae0-65e1-4d59-ad59-065d22ed90d7', 'ka', 'შრომის კოდექსის 89-ე და 91-ე მუხლების თანახმად, როგორია სამუშაო დროის ნორმალური და შემოკლებული ხანგრძლივობა?', '["ყოველკვირეული ნორმალური სამუშაო დრო განისაზღვრება 36 საათით, ხოლო ორსული ქალებისთვის – 24 საათით", "ყველა მუშაკისთვის გამოიყენება ერთიანი ყოველკვირეული 40-საათიანი სრული სამუშაო დრო", "ყოველკვირეული ნორმალური სამუშაო დროა 48 საათი, ხოლო 16 წლამდე ასაკის მუშაკებისთვის – არაუმეტეს 36 საათისა", "ყოველკვირეული ნორმალური სამუშაო დროა 45 საათი, ხოლო პედაგოგიური პერსონალისთვის – არაუმეტეს 18 საათისა", "ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შშმ პირებისთვის – კვირაში 36 საათს"]'::jsonb, 'ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და II ჯგუფის შშმ პირებისთვის – კვირაში 36 საათს', 'Düzgün cavab: E) ყოველკვირეული ნორმალური სამუშაო დრო არ შეიძლება აღემატებოდეს 40 საათს, ხოლო I და', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('2991edee-1629-4dde-b249-b9bda94363b2', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Əmək Məcəlləsinin 186-cı maddəsinə əsasən, əmək və icra intizamını pozan işçiyə işəgötürən tərəfindən tətbiq edilə bilən intizam tənbehlərinin tam siyahısı hansıdır?', 'multiple_choice', '["Şifahi xəbərdarlıq, ictimai töhmət, cərimə və məzuniyyətin ləğv edilməsi", "Vəzifə maaşının 50% azaldılması, növbəti məzuniyyətin verilməməsi", "Yalnız yazılı töhmət və işçinin fəxri adlardan məhrum edilməsi", "İnzibati cərimə, məcburi ictimai işlər və başqa müəssisəyə məcburi keçirilmə", "Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi"]'::jsonb, 'Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutulduqda aylıq əməkhaqqının 1/4-dən çox olmamaqla cərimə və ƏM-nin 70-ci maddəsi ilə müqavilənin ləğvi', 'Düzgün cavab: E) Töhmət, sonuncu xəbərdarlıqla şiddətli töhmət, kollektiv müqavilədə nəzərdə tutu', '', 43, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b25572e1-0aa3-4597-9dff-deec02cbed96', '2991edee-1629-4dde-b249-b9bda94363b2', 'ka', 'შრომის კოდექსის 186-ე მუხლის თანახმად, რომელია დისციპლინური სახდელების სრული ჩამონათვალი?', '["ზეპირი გაფრთხილება, საზოგადოებრივი საყვედური, ჯარიმა და შვებულების გაუქმება", "მხოლოდ წერილობითი საყვედური და დასაქმებულისთვის საპატიო წოდებების ჩამორთმევა", "ადმინისტრაციული ჯარიმა, სავალდებულო საზოგადოებრივი სამუშაო და სხვა საწარმოში იძულებითი გადაყვანა", "თანამდებობრივი სარგოს 50%-ით შემცირება, მორიგი შვებულების მიუცემლობა", "საყვედური, მკაცრი საყვედური ბოლო გაფრთხილებით, ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა (თუ გათვალისწინებულია კოლექტიური ხელშეკრულებით) და შრომითი ხელშეკრულების შეწყვეტა"]'::jsonb, 'საყვედური, მკაცრი საყვედური ბოლო გაფრთხილებით, ჯარიმა ყოველთვიური ხელფასის არაუმეტეს 1/4-ისა (თუ გათვალისწინებულია კოლექტიური ხელშეკრულებით) და შრომითი ხელშეკრულების შეწყვეტა', 'Düzgün cavab: E) საყვედური, მკაცრი საყვედური ბოლო გაფრთხილებით, ჯარიმა ყოველთვიური ხელფასის არაუმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('299e2d78-2a7d-4853-8011-642229e05969', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'AR Əmək Məcəlləsinin 187 və 188-ci maddələrinə əsasən, intizam tənbehinin verilməsi və qüvvədə olma müddəti qaydası necədir?', 'multiple_choice', '["İntizam tənbehi xətanın aşkar edildiyi gündən 6 ay keçdikdən sonra da verilə bilər və 2 il qüvvədə qalır", "İntizam tənbehi yalnız məhkəmə qərarı əsasında verilir", "İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz", "İntizam tənbehi verildikdə işçidən izahat alınır və tənbeh verildiyi gündən 1 il qüvvədə qalır", "İşçi yazılı izahat verməkdən imtina etdikdə ona heç bir tənbeh tətbiq edilə bilməz"]'::jsonb, 'İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbeh verildiyi gündən 6 aydan artıq qüvvədə ola bilməz', 'Düzgün cavab: C) İntizam tənbehi verilməzdən əvvəl işçidən yazılı izahat tələb edilməlidir; tənbe', '', 44, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('a3df1002-6c84-44de-96af-1980eccdbfd8', '299e2d78-2a7d-4853-8011-642229e05969', 'ka', 'შრომის კოდექსის 187-ე მუხლის თანახმად, როგორია დისციპლინური სახდელის დადების წესი?', '["დისციპლინური სახდელი შეიძლება დაედოს გადაცდომის გამოვლენის დღიდან 6 თვის გასვლის შემდეგაც და მოქმედებს 2 წლის განმავლობაში", "დისციპლინური სახდელი ედება მხოლოდ სასამართლოს გადაწყვეტილების საფუძველზე", "დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია მისი დადების დღიდან 1 წლის განმავლობაში", "ერთი დისციპლინური გადაცდომისთვის დასაქმებულს შეიძლება ერთდროულად დაედოს მკაცრი საყვედურიც და შეუწყდეს ხელშეკრულებაც", "თუ დასაქმებული უარს ამბობს წერილობითი ახსნა-განმარტების მიცემაზე, მის მიმართ არ შეიძლება გამოყენებულ იქნეს რაიმე სახდელი"]'::jsonb, 'დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმარტება; სახდელი ძალაშია მისი დადების დღიდან 1 წლის განმავლობაში', 'Düzgün cavab: C) დისციპლინური სახდელის დადებამდე დასაქმებულს უნდა მოეთხოვოს წერილობითი ახსნა-განმ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a4d76908-2102-4518-aace-58961268b258', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Əmək Məcəlləsinin 69 və 172-ci maddələrinə əsasən, işçinin öz təşəbbüsü ilə əmək müqaviləsinə xitam verilməsi və son haqq-hesabın ödənilməsi qaydası necədir?', 'multiple_choice', '["Əmək müqaviləsinə xitam verilməsi yalnız həmkarlar ittifaqının razılığı ilə mümkündür", "İşçi 2 həftə əvvəl bildiriş verməlidir; kompensasiya növbəti ildə ödənilir", "İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab müqaviləyə xitam verildiyi sonuncu iş günündən gec olmayaraq ödənilir", "İşçi 3 gün əvvəl şifahi xəbərdarlıq etməlidir", "İşçi istədiyi gün xəbərdarlıq etmədən işi tərk edə bilər"]'::jsonb, 'İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haqq-hesab müqaviləyə xitam verildiyi sonuncu iş günündən gec olmayaraq ödənilir', 'Düzgün cavab: C) İşçi 1 təqvim ayı əvvəl işəgötürəni yazılı ərizə ilə xəbərdar etməlidir; son haq', '', 45, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('f4022179-6421-4c60-86fe-f89c3d97b61f', 'a4d76908-2102-4518-aace-58961268b258', 'ka', 'შრომის კოდექსის 69-ე და 172-ე მუხლების თანახმად, როგორია დასაქმებულის საკუთარი ინიციატივით შრომითი ხელშეკრულების შეწყვეტის წესი?', '["დასაქმებულს შეუძლია ნებისმიერ დღეს გაფრთხილების გარეშე მიატოვოს სამუშაო", "დასაქმებულმა 3 დღით ადრე ზეპირად უნდა გააფრთხილოს დამსაქმებელი", "დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი; საბოლოო ანგარიშსწორება ხდება ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღეს არაუგვიანეს", "დასაქმებულმა 2 კვირით ადრე უნდა წარადგინოს შეტყობინება; კომპენსაცია გაიცემა მომდევნო წელს", "შრომითი ხელშეკრულების შეწყვეტა შესაძლებელია მხოლოდ პროფკავშირის თანხმობით"]'::jsonb, 'დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამსაქმებელი; საბოლოო ანგარიშსწორება ხდება ხელშეკრულების შეწყვეტის ბოლო სამუშაო დღეს არაუგვიანეს', 'Düzgün cavab: C) დასაქმებულმა 1 კალენდარული თვით ადრე წერილობითი განცხადებით უნდა გააფრთხილოს დამ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f22f76e8-0931-4d31-8e3a-fc758a36710b', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Kompüter şəbəkələrinin əhatə dairəsinə görə LAN və WAN şəbəkələrinin başlıca fərqi nədir?', 'multiple_choice', '["LAN yalnız optik lifli kabellərlə, WAN isə yalnız simsiz Bluetooth ilə qurulur", "LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir", "LAN yalnız internetə çıxış üçün istifadə olunur, WAN isə lokal fayl və printer mübadiləsini təmin edir", "LAN şəbəkəsində məlumatlar şifrələnmir, WAN şəbəkəsində isə daxili resurs paylaşımı tam qadağandır", "LAN yalnız dövlət orqanları üçün, WAN isə yalnız fərdi istifadəçilər üçün nəzərdə tutulan şəbəkədir"]'::jsonb, 'LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, WAN isə böyük coğrafi əraziləri, ölkələri və qitələri birləşdirən qlobal şəbəkədir', 'Düzgün cavab: B) LAN məhdud coğrafi ərazidə (otaq, bina, məktəb, kampus) yerləşən kompüterləri, W', '', 46, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('bb6a2b8a-ee0e-49e7-af00-0e0464ecec33', 'f22f76e8-0931-4d31-8e3a-fc758a36710b', 'ka', 'რა არის ძირითადი განსხვავება LAN და WAN ქსელებს შორის?', '["LAN იგება მხოლოდ ოპტიკურ-ბოჭკოვანი კაბელებით, ხოლო WAN – მხოლოდ უსადენო Bluetooth-ით", "LAN აერთიანებს კომპიუტერებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა), ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ ტერიტორიებს, ქვეყნებსა და კონტინენტებს", "LAN განკუთვნილია მხოლოდ სახელმწიფო ორგანოებისთვის, ხოლო WAN – მხოლოდ ინდივიდუალური მომხმარებლებისთვის", "LAN გამოიყენება მხოლოდ ინტერნეტში გასასვლელად, ხოლო WAN უზრუნველყოფს ლოკალურ ფაილთა და პრინტერების გაზიარებას", "LAN ქსელში მონაცემები არ იშიფრება, ხოლო WAN ქსელში შიდა რესურსების გაზიარება სრულიად აკრძალულია"]'::jsonb, 'LAN აერთიანებს კომპიუტერებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა), ხოლო WAN არის გლობალური ქსელი, რომელიც აერთიანებს დიდ გეოგრაფიულ ტერიტორიებს, ქვეყნებსა და კონტინენტებს', 'Düzgün cavab: B) LAN აერთიანებს კომპიუტერებს შეზღუდულ გეოგრაფიულ არეალში (ოთახი, შენობა, სკოლა),', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('82642051-35c8-452b-b1cc-8ffe808757a6', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'İnternet şəbəkəsində domen adlarını IP ünvanlarına çevirən əsas xidmət və protokol hansıdır?', 'multiple_choice', '["SMTP (Simple Mail Transfer Protocol)", "FTP (File Transfer Protocol)", "DNS (Domain Name System)", "DHCP (Dynamic Host Configuration Protocol)", "SNMP (Simple Network Management Protocol)"]'::jsonb, 'DNS (Domain Name System)', 'Düzgün cavab: C) DNS (Domain Name System)', '', 47, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c1f6c5f8-dedc-4761-9085-6370783825bb', '82642051-35c8-452b-b1cc-8ffe808757a6', 'ka', 'რომელია ქსელური ძირითადი სერვისი, რომელიც დომენურ სახელებს IP მისამართებად გარდაქმნის?', '["FTP (File Transfer Protocol - ფაილთა გადაცემის ოქმი)", "SMTP (Simple Mail Transfer Protocol - ელფოსტის გადაცემის მარტივი ოქმი)", "DNS (Domain Name System) - განაწილებული იერარქიული დომენური სახელების სისტემა", "DHCP (Dynamic Host Configuration Protocol - ჰოსტის დინამიკური კონფიგურაციის ოქმი)", "SNMP (Simple Network Management Protocol - ქსელის მართვის მარტივი ოქმი)"]'::jsonb, 'DNS (Domain Name System) - განაწილებული იერარქიული დომენური სახელების სისტემა', 'Düzgün cavab: C) DNS (Domain Name System) - განაწილებული იერარქიული დომენური სახელების სისტემა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c57ba5fb-c23c-4d7e-b78a-112367228176', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'İnformasiya təhlükəsizliyində ''İki faktorlu autentifikasiya'' (2FA) istifadəsinin başlıca məqsədi nədir?', 'multiple_choice', '["Şəbəkə daxilində kompüterin internet sürətini ikiqat artırması", "Əməliyyat sisteminin drayverlərini avtomatik yeniləyərək lisenziya müddətini uzatması", "İstifadəçiyə eyni vaxtda yalnız bir kompüterdən daxil olmağa məcburi icazə verməsi", "İstifadəçinin daxil etdiyi faylların həcmini avtomatik sıxaraq yaddaşa qənaət etməsi", "Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək"]'::jsonb, 'Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifikator tətbiqi və s.) olmadan hesaba daxil olmağı əngəlləmək', 'Düzgün cavab: E) Şifrə ələ keçirildikdə belə, ikinci müstəqil təsdiq vasitəsi (SMS kod, autentifi', '', 48, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('7fcdeabb-5383-4513-a4a3-e018eae35d34', 'c57ba5fb-c23c-4d7e-b78a-112367228176', 'ka', 'რა არის ორფაქტორიანი აუთენტიფიკაციის (2FA) მექანიზმის მთავარი უპირატესობა?', '["მომხმარებლის მიერ შეყვანილი ფაილების მოცულობის ავტომატური შეკუმშვა მეხსიერების დაზოგვის მიზნით", "ქსელის შიგნით კომპიუტერის ინტერნეტის სიჩქარის გაორმაგება", "ოპერაციული სისტემის დრაივერების ავტომატური განახლება და სალიცენზიო ვადის გახანგრძლივება", "მომხმარებლისთვის ერთდროულად მხოლოდ ერთი კომპიუტერიდან შესვლის სავალდებულო დაშვება", "პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების (SMS კოდი, ავთენტიფიკატორის აპლიკაცია ან უსაფრთხოების გასაღები) გარეშე"]'::jsonb, 'პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მეორე დამოუკიდებელი დადასტურების საშუალების (SMS კოდი, ავთენტიფიკატორის აპლიკაცია ან უსაფრთხოების გასაღები) გარეშე', 'Düzgün cavab: E) პაროლის გატეხვის ან ხელში ჩაგდების შემთხვევაშიც კი, ანგარიშზე წვდომის დაბლოკვა მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('fe3aaae5-3cfa-4e7e-98b3-9a1d0a234b11', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Fırıldaqçıların etibarlı təşkilat adından saxta e-poçt göndərərək istifadəçinin məxfi məlumatlarını ələ keçirməsi hansı kiberhücum növüdür?', 'multiple_choice', '["Buffer Overflow (Buferin daşması)", "Defragmentasiya hücumu", "DDoS (Xidmətdən imtina) hücumu", "SQL Injection (Məlumat bazasına müdaxilə)", "Fişinq (Phishing)"]'::jsonb, 'Fişinq (Phishing)', 'Düzgün cavab: E) Fişinq (Phishing)', '', 49, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('37e75c4b-e7ee-47aa-80b2-be636fd6af2f', 'fe3aaae5-3cfa-4e7e-98b3-9a1d0a234b11', 'ka', 'კიბერშეტევის რომელ სახეობას მიეკუთვნება თაღლითების მიერ სანდო ორგანიზაციის სახელით ყალბი ელფოსტის გაგზავნა მონაცემების მითვისების მიზნით?', '["დეფრაგმენტაციის შეტევა", "Buffer Overflow (ბუფერის გადავსება)", "SQL Injection (მონაცემთა ბაზაში შეღწევა/ჩასმა)", "DDoS (მომსახურებაზე უარის თქმის) შეტევა", "ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) - საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტების მეშვეობით"]'::jsonb, 'ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) - საიდენტიფიკაციო მონაცემების მოპარვა ყალბი ელფოსტისა და ვებსაიტების მეშვეობით', 'Düzgün cavab: E) ფიშინგი (Phishing / სოციალური ინჟინერიის შეტევა) - საიდენტიფიკაციო მონაცემების მ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('16b53867-62d9-497c-a170-63a2c1a734ea', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Microsoft Word proqramında abzasın girintilərini dəqiq vizual tənzimləmək üçün hansı elementdən istifadə olunur?', 'multiple_choice', '["Naviqasiya paneli (Navigation Pane)", "Sənədin miqyas sürüşdürücüsü (Zoom Slider)", "Sürətli müraciət paneli (Quick Access Toolbar)", "Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi", "Vəziyyət zolağı (Status Bar)"]'::jsonb, 'Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph dialoq pəncərəsi', 'Düzgün cavab: D) Üfüqi Xətkeş (Horizontal Ruler) üzərindəki girinti sürüşdürücüləri və Paragraph', '', 50, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('b7e8fa29-9c32-4739-8548-1836997701c0', '16b53867-62d9-497c-a170-63a2c1a734ea', 'ka', 'MS Word-ში აბზაცის შეწევის (ინდენტაციის) ზუსტი ვიზუალური რეგულირებისთვის რომელი ელემენტი გამოიყენება?', '["სწრაფი წვდომის პანელი (Quick Access Toolbar)", "სტატუსის ზოლი (Status Bar)", "დოკუმენტის მასშტაბის მორბენალი (Zoom Slider)", "ჰორიზონტალურ სახაზავზე (Horizontal Ruler) განთავსებული მორბენალები (First Line, Hanging, Left/Right) და დიალოგური ფანჯარა Paragraph", "ნავიგაციის პანელი (Navigation Pane)"]'::jsonb, 'ჰორიზონტალურ სახაზავზე (Horizontal Ruler) განთავსებული მორბენალები (First Line, Hanging, Left/Right) და დიალოგური ფანჯარა Paragraph', 'Düzgün cavab: D) ჰორიზონტალურ სახაზავზე (Horizontal Ruler) განთავსებული მორბენალები (First Line,', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('f175b882-9e27-4db8-93a8-68c3b9a62a32', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Microsoft Word sənədində bəzi səhifələri şaquli, bəzi səhifələri isə üfüqi (albom) etmək üçün hansı əməliyyat icra olunmalıdır?', 'multiple_choice', '["Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir", "Sənəd mütləq PDF formatında yadda saxlanılmalıdır", "Mətnin şrift ölçüsü 10 pt səviyyəsinə endirilməlidir", "Bütün sənəd üçün vahid cədvəl şablonu tətbiq olunmalıdır", "Səhifələrin arasına adi səhifə kəsilməsi (Page Break) əlavə edilməlidir"]'::jsonb, 'Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin Orientation parametri dəyişdirilməlidir', 'Düzgün cavab: A) Sənədə Bölmə Kəsilməsi (Section Break – Next Page) əlavə edilib həmin bölmənin O', '', 51, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('e5b76734-1599-4bd2-aa97-c662eafd4301', 'f175b882-9e27-4db8-93a8-68c3b9a62a32', 'ka', 'რა ოპერაცია უნდა შესრულდეს MS Word-ის დოკუმენტში ზოგიერთი გვერდის ვერტიკალურ (Portrait), ხოლო ზოგიერთის ჰორიზონტალურ (Landscape) ორიენტაციაში დასაფორმატებლად?', '["დოკუმენტში სექციის გაწყვეტის (Section Break / Next Page) დამატება და ამ კონკრეტული სექციის ორიენტაციის შეცვლა", "მთელი დოკუმენტისთვის ცხრილის ერთიანი შაბლონის გამოყენება", "დოკუმენტის აუცილებლად PDF ფორმატში შენახვა", "ტექსტის შრიფტის ზომის 10 pt-მდე შემცირება", "გვერდებს შორის ჩვეულებრივი გვერდის გაწყვეტის (Page Break) ჩამატება"]'::jsonb, 'დოკუმენტში სექციის გაწყვეტის (Section Break / Next Page) დამატება და ამ კონკრეტული სექციის ორიენტაციის შეცვლა', 'Düzgün cavab: A) დოკუმენტში სექციის გაწყვეტის (Section Break / Next Page) დამატება და ამ კონკრეტუ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('0411e2a9-30b8-4db9-8080-1c0d53a5e50c', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Microsoft Word proqramında başlıqlara əsasən avtomatik yenilənən Mündəricat yaratmaq üçün hansı taba müraciət edilir?', 'multiple_choice', '["Layout (Səhifə düzəni)", "References (İstinadlar) tabı > Table of Contents qrupu", "Review (İcmal)", "Mailings (Göndərişlər)", "Design (Dizayn)"]'::jsonb, 'References (İstinadlar) tabı > Table of Contents qrupu', 'Düzgün cavab: B) References (İstinadlar) tabı > Table of Contents qrupu', '', 52, true, false, true, 1.0, 'exact', true, false, NOW());
