INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('c2db74bc-8876-4232-88bc-bd483eea4bb3', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Microsoft Excel cədvəlində `$C$2` mütləq xana ünvanı olan düstur başqa xanalara kopyalandıqda necə dəyişir?', 'multiple_choice', '["Düstur avtomatik olaraq sıfır qiyməti qaytarır", "Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır", "Yalnız sətir nömrəsi sabit qalır, sütun hərfi isə sağa kopyalandıqca dəyişir", "Həm sütun (C), həm də sətir (2) indeksi kopyalanan istiqamətə uyğun avtomatik sürüşür", "Yalnız sütun adı sabit qalır, sətir nömrəsi isə aşağı kopyalandıqca artır"]'::jsonb, 'Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', 'Düzgün cavab: B) Həm sütun, həm də sətir tamamilə dəyişməz (sabit) qalır', '', 53, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('9d6cd3bc-35d2-489f-be9b-5cc527cafd50', 'c2db74bc-8876-4232-88bc-bd483eea4bb3', 'ka', 'როგორ შეიცვლება Excel-ის ცხრილში აბსოლუტური უჯრის მისამართის შემცველი ფორმულა $C$2 სხვა უჯრებში კოპირებისას?', '["მხოლოდ სვეტის სახელი რჩება უცვლელი, ხოლო სტრიქონის ნომერი იზრდება ქვემოთ კოპირებისას", "რადგან დოლარის ნიშანი ($) ორივე ინდექსის წინ დგას, ფორმულა სადაც არ უნდა დაკომპლექტდეს/გადაკოპირდეს, უჯრის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური ბმული)", "მხოლოდ სტრიქონის ნომერი რჩება უცვლელი, ხოლო სვეტის ასო იცვლება მარჯვნივ კოპირებისას", "როგორც სვეტის (C), ისე სტრიქონის (2) ინდექსი ავტომატურად იცვლება კოპირების მიმართულების მიხედვით", "ფორმულა ავტომატურად აბრუნებს ნულოვან მნიშვნელობას"]'::jsonb, 'რადგან დოლარის ნიშანი ($) ორივე ინდექსის წინ დგას, ფორმულა სადაც არ უნდა დაკომპლექტდეს/გადაკოპირდეს, უჯრის მისამართი სრულიად უცვლელი რჩება (აბსოლუტური ბმული)', 'Düzgün cavab: B) რადგან დოლარის ნიშანი ($) ორივე ინდექსის წინ დგას, ფორმულა სადაც არ უნდა დაკომპლ', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('9d65a0b7-36d6-4588-9f7a-df7800a204b2', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Microsoft Excel proqramında `A1:A10` diapazonunda yalnız qiyməti 50-dən böyük olan xanaların sayını hesablamaq üçün hansı funksiya düzgündür?', 'multiple_choice', '["=SUM(A1:A10; \">50\")", "=COUNTA(A1:A10; 50)", "=AVERAGEIF(A1:A10; 50)", "=COUNTIF(A1:A10; \">50\")", "=COUNT(A1:A10; >50)"]'::jsonb, '=COUNTIF(A1:A10; ">50")', 'Düzgün cavab: D) =COUNTIF(A1:A10; ">50")', '', 54, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('86def9c6-d3bb-490a-96e8-25d9911ad071', '9d65a0b7-36d6-4588-9f7a-df7800a204b2', 'ka', 'Excel-ში A1:A10 დიაპაზონში მხოლოდ იმ უჯრების რაოდენობის დასათვლელად, რომელთა მნიშვნელობა 50-ზე მეტია, რომელი ფუნქციაა სწორი?', '["=COUNT(A1:A10; >50) - სინტაქსური შეცდომაა", "=SUM(A1:A10; \">50\") - პირობითი ჯამის ფუნქციაა", "=COUNTA(A1:A10; 50) - შევსებული უჯრების რაოდენობაა", "=COUNTIF(A1:A10;\">50\") - პირობითი დათვლის ფუნქციაა", "=AVERAGEIF(A1:A10; 50) - საშუალო არითმეტიკულის ფუნქციაა"]'::jsonb, '=COUNTIF(A1:A10;">50") - პირობითი დათვლის ფუნქციაა', 'Düzgün cavab: D) =COUNTIF(A1:A10;">50") - პირობითი დათვლის ფუნქციაა', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('7886a7fc-f364-4a0f-952d-bb118e2c9752', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Microsoft Excel-də B2 xanasındakı əməkhaqqı 800-dən çox olduqda 15% mükafat, əks halda 5% hesablayan düstur hansıdır?', 'multiple_choice', '["=IF(B2>800; B2*0.15; B2*0.05)", "=COUNTIF(B2; 800; 15%)", "=MAX(B2>800; 0.15; 0.05)", "=SUMIF(B2>800; B2*15%; B2*5%)", "=VLOOKUP(B2; 800; 15; 5)"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05)', 'Düzgün cavab: A) =IF(B2>800; B2*0.15; B2*0.05)', '', 55, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('2e842fd5-0696-4fff-b68e-a3a080e777a5', '7886a7fc-f364-4a0f-952d-bb118e2c9752', 'ka', 'Excel-ში რომელი ფორმულა ითვლის 15%-იან პრემიას, თუ B2 უჯრაში ხელფასი 800-ზე მეტია (სხვა შემთხვევაში 5%-ს)?', '["=IF(B2>800; B2*0.15; B2*0.05) - ლოგიკური IF ფუნქციით", "=COUNTIF(B2; 800; 15%) - დათვლის ფუნქცია", "=VLOOKUP(B2; 800; 15; 5) - ძებნის ფუნქცია", "=SUMIF(B2>800; B2*15%; B2*5%) - პირობითი ჯამი", "=MAX(B2>800; 0.15; 0.05) - მაქსიმუმის ფუნქცია"]'::jsonb, '=IF(B2>800; B2*0.15; B2*0.05) - ლოგიკური IF ფუნქციით', 'Düzgün cavab: A) =IF(B2>800; B2*0.15; B2*0.05) - ლოგიკური IF ფუნქციით', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('02e7fca8-90b6-45f0-a07a-9e534d9d40a4', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Microsoft Excel proqramında xanaya yalnız müəyyən diapazonda ədədlərin daxil edilməsinə icazə verən alət hansıdır?', 'multiple_choice', '["Data Validation (Verilənlərin yoxlanılması)", "Conditional Formatting (Şərti formatlaşdırma)", "Remove Duplicates (Təkrarların silinməsi)", "Flash Fill (Sürətli doldurma)", "Text to Columns (Mətnin sütunlara bölünməsi)"]'::jsonb, 'Data Validation (Verilənlərin yoxlanılması)', 'Düzgün cavab: A) Data Validation (Verilənlərin yoxlanılması)', '', 56, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('078da413-8dc7-48f0-8729-fab088e65a34', '02e7fca8-90b6-45f0-a07a-9e534d9d40a4', 'ka', 'რომელი ხელსაწყო იძლევა Excel-ში უჯრაში მხოლოდ განსაზღვრული დიაპაზონის რიცხვების შეყვანის ნებართვას?', '["Data Validation (მონაცემთა ვალიდაცია/შემოწმება) - ჩანართ Data-ში Whole Number, Decimal, List, Date კრიტერიუმებით", "Flash Fill (მყისიერი შევსება) - ავტომატური შევსება", "Conditional Formatting (პირობითი ფორმატირება) - ვიზუალური გამოკვეთა", "Remove Duplicates (დუბლიკატების წაშლა)", "Text to Columns (ტექსტის სვეტებად დაყოფა)"]'::jsonb, 'Data Validation (მონაცემთა ვალიდაცია/შემოწმება) - ჩანართ Data-ში Whole Number, Decimal, List, Date კრიტერიუმებით', 'Düzgün cavab: A) Data Validation (მონაცემთა ვალიდაცია/შემოწმება) - ჩანართ Data-ში Whole Number, D', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('afb72fb8-ca47-4875-90e3-ca407e4a740f', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Microsoft PowerPoint proqramında bütün slaydların vahid dizayn şablonunu dəyişmək üçün hansı rejimdən istifadə olunur?', 'multiple_choice', '["Custom Animation (Fərdi animasiya)", "Reading View (Oxu rejimi)", "Presenter View (Aparıcı görünüşü)", "Slide Master (Slayd Ustası)", "Slide Sorter (Slayd çeşidləyicisi)"]'::jsonb, 'Slide Master (Slayd Ustası)', 'Düzgün cavab: D) Slide Master (Slayd Ustası)', '', 57, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('519619a4-4aeb-4a2c-9943-c5deee75e67f', 'afb72fb8-ca47-4875-90e3-ca407e4a740f', 'ka', 'რომელი რეჟიმი გამოიყენება PowerPoint-ში ყველა სლაიდის ერთიანი დიზაინის შაბლონის შესაცვლელად?', '["Reading View (კითხვის რეჟიმი)", "Presenter View (მომხსენებლის ხედი)", "Custom Animation (მორგებული ანიმაცია)", "Slide Master (სლაიდების ნიმუში / Образец слайдов) - ჩანართ View-ში ჯგუფი Master Views", "Slide Sorter (სლაიდების დამხარისხებელი)"]'::jsonb, 'Slide Master (სლაიდების ნიმუში / Образец слайдов) - ჩანართ View-ში ჯგუფი Master Views', 'Düzgün cavab: D) Slide Master (სლაიდების ნიმუში / Образец слайдов) - ჩანართ View-ში ჯგუფი Master', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('24f8ecd7-0dcb-4435-88a0-f24660548a80', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Microsoft PowerPoint-də ''Transition'' ilə ''Animation'' arasındakı əsas fərq nədir?', 'multiple_choice', '["Transition yalnız mətnlərə tətbiq olunur, Animation yalnız video faylları nümayiş etdirir", "Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir", "Transition slaydın arxa fon rəngini dəyişir, Animation slaydın vaxtını tənzimləyir", "Transition yalnız kompüter sönərkən işləyir, Animation çap zamanı aktivləşir", "Hər iki anlayış eyni funksiyanı icra edir"]'::jsonb, 'Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation isə slaydın daxilindəki konkret obyektlərin (mətn, şəkil) hərəkət effektidir', 'Düzgün cavab: B) Transition bir slayddan digər slayda keçərkən yaranan vizual effekt, Animation i', '', 58, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('3572eb5d-fc89-4b8d-a429-40ee50c37dad', '24f8ecd7-0dcb-4435-88a0-f24660548a80', 'ka', 'რა არის ძირითადი განსხვავება PowerPoint-ში „Transition“-სა და „Animation“-ს შორის?', '["Transition ცვლის სლაიდის ფონის ფერს, ხოლო Animation არეგულირებს სლაიდის დროს", "Transition არის ერთი სლაიდიდან მეორეზე გადასვლის ვიზუალური ეფექტი, ხოლო Animation არის სლაიდის შიგნით არსებული კონკრეტული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი", "Transition მუშაობს მხოლოდ კომპიუტერის გამორთვისას, ხოლო Animation აქტიურდება ბეჭდვის დროს", "ორივე ცნება ზუსტად ერთსა და იმავე ფუნქციას ასრულებს", "Transition გამოიყენება მხოლოდ ტექსტებზე, ხოლო Animation აჩვენებს მხოლოდ ვიდეოფაილებს"]'::jsonb, 'Transition არის ერთი სლაიდიდან მეორეზე გადასვლის ვიზუალური ეფექტი, ხოლო Animation არის სლაიდის შიგნით არსებული კონკრეტული ობიექტების (ტექსტი, სურათი) მოძრაობის ეფექტი', 'Düzgün cavab: B) Transition არის ერთი სლაიდიდან მეორეზე გადასვლის ვიზუალური ეფექტი, ხოლო Animatio', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('a55744e1-48d0-421c-9cae-cc5396023760', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Bulud saxlama xidmətlərində sənəd üzərində birgə işləyərkən əvvəlki versiyalara qayıtmaq üçün hansı funksiyadan istifadə olunur?', 'multiple_choice', '["Defragmentation (Defragmentasiya)", "Disk Cleanup (Diskin təmizlənməsi)", "Registry Editor (Reyestr redaktoru)", "Version History (Versiya tarixçəsi)", "Task Manager (Tapşırıqlar meneceri)"]'::jsonb, 'Version History (Versiya tarixçəsi)', 'Düzgün cavab: D) Version History (Versiya tarixçəsi)', '', 59, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('c4ec1f35-2d5e-4bc2-8185-f3f22602807c', 'a55744e1-48d0-421c-9cae-cc5396023760', 'ka', 'რომელი ფუნქცია გამოიყენება ღრუბლოვან საცავებში დოკუმენტის წინა ვერსიებზე დასაბრუნებლად?', '["Defragmentation (დეფრაგმენტაცია) - ახდენს დისკის ოპტიმიზაციას", "Registry Editor (რეესტრის რედაქტორი) - არედაქტირებს რეესტრს", "Disk Cleanup (დისკის გასუფთავება) - შლის დროებით ფაილებს", "Version History (ვერსიების ისტორია / История версий) - File > Info > Version History ან ისტორია OneDrive/SharePoint-ში", "Task Manager (ამოცანათა მენეჯერი) - მართავს პროცესებს"]'::jsonb, 'Version History (ვერსიების ისტორია / История версий) - File > Info > Version History ან ისტორია OneDrive/SharePoint-ში', 'Düzgün cavab: D) Version History (ვერსიების ისტორია / История версий) - File > Info > Version His', NOW(), NOW());
INSERT INTO questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, topic, order_index, is_required, shuffle_options, is_graded, weight, answer_match_type, answer_trim_spaces, answer_case_sensitive, created_at) VALUES ('53951068-90cd-414b-87b6-72de74347c69', '033a9bc7-c2a4-4b06-85d2-7d715a095041', 'Süni intellekt əsaslı generativ modellərdə ''Hallüsinasiya'' riski nəyi ifadə edir?', 'multiple_choice', '["Süni intellektin kompüterin aparat hissələrini sıradan çıxarmasını", "Modelin internet şəbəkəsini həddindən artıq yükləyərək kompüteri dondurmasını", "Modelin yalnız xarici dillərdə işləyərək Azərbaycan dilini dəstəkləməməsini", "Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini", "Süni intellektin bütün istifadəçi parollarını avtomatik silməsini"]'::jsonb, 'Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadları tamamilə inandırıcı və qrammatik düzgün tərzdə generasiya etməsini', 'Düzgün cavab: D) Modelin faktiki olaraq yalan, uydurma və ya mövcud olmayan məlumatları, istinadl', '', 60, true, false, true, 1.0, 'exact', true, false, NOW());
INSERT INTO question_translations (id, question_id, language_code, question_text, options, correct_answer, explanation, created_at, updated_at) VALUES ('8677a588-c8d3-4a48-831a-be4677bd4e8f', '53951068-90cd-414b-87b6-72de74347c69', 'ka', 'რას გამოხატავს „ჰალუცინაციის“ რისკი ხელოვნურ ინტელექტში?', '["მოდელის მიერ ინტერნეტ-ქსელის გადატვირთვას და კომპიუტერის გაყინვას", "ხელოვნური ინტელექტის მიერ მომხმარებლის ყველა პაროლის ავტომატურ წაშლას", "ხელოვნური ინტელექტის მიერ კომპიუტერის აპარატურული ნაწილების მწყობრიდან გამოყვანას", "მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით", "მოდელის მუშაობას მხოლოდ უცხო ენებზე და აზერბაიჯანული ენის მხარდაჭერის არქონას"]'::jsonb, 'მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და წყაროების გენერირებას სრულიად დამაჯერებელი და გრამატიკულად გამართული ფორმით', 'Düzgün cavab: D) მოდელის მიერ ფაქტობრივად მცდარი, გამოგონილი ან არარსებული ინფორმაციისა და წყაროე', NOW(), NOW());
